@dataclass(frozen=True)
class DispatchAttempt:
    """Durable identity assigned to one external child-spawn attempt."""

    intent_id: str
    started_at: float
    harness: str
    agent_type: str = ""
    model: str | None = None
    #: The harness identifier the plan requested, carried so a dispatch record
    #: can name both the request and the route it resolved to.
    requested_harness: str | None = None
    #: Authorized reason a retry may use the current role policy instead.
    route_reconciliation_source: str | None = None
    attempt: int = 0
    controller_epoch: str | None = None
    #: The per-slice dispatch attempt counter under the current controller epoch.
    #:
    #: It is minted with the intent and persisted on the slice in the same write,
    #: so the intent events, the checkpoint, and every later reconstruction report
    #: one generation for one dispatch. A spawn observation that carries a
    #: generation is adopted only when it names this one, which is what refuses a
    #: confirmation that belongs to an earlier attempt of the same intent.
    dispatch_generation: int = 0
    #: The consumed ledger position when this intent was recorded.
    #:
    #: A refusal for this attempt can only be at or after this position, so
    #: correlating one reads forward from here instead of replaying the ledger
    #: from zero. It is persisted with the slice, so a restart still knows the
    #: floor its intent was issued at.
    ledger_floor: int = 0

    def routed(
        self,
        *,
        harness: str,
        agent_type: str,
        model: str | None,
        requested_harness: str | None = None,
        route_reconciliation_source: str | None = None,
    ) -> DispatchAttempt:
        """Return this attempt with the selected harness route attached.

        The policy path resolves the harness after the intent is minted. The
        route is the only thing that changes: the intent identity, its ledger
        floor, and the controller epoch and dispatch generation the correlation
        reads are carried by ``replace``, so selecting a harness can never
        record an attempt with incomplete provenance.

        ``requested_harness`` is written only when the attempt carries no
        request yet, so re-routing an attempt never erases what the plan asked
        for.
        """
        return replace(
            self,
            harness=harness,
            agent_type=agent_type,
            model=model,
            requested_harness=self.requested_harness or requested_harness,
            route_reconciliation_source=(
                self.route_reconciliation_source or route_reconciliation_source
            ),
        )

    @classmethod
    def requested(cls, route: HarnessRoute) -> DispatchAttempt:
        """Build an identity-free route carrier for a validated plan request.

        Only :func:`_resolve_direct_request` uses this, and only for a run with
        no policy bound, where there is no intent identity to attach to yet. The
        intent that eventually persists carries the same fields, so this is a
        staging value rather than a second source of dispatch provenance.
        """
        return cls("", 0.0, route.harness, agent_type=route.agent_type, model=route.model)

    @classmethod
    def recorded_for(cls, slice_state: SliceState, controller_epoch: str | None) -> DispatchAttempt:
        """Rebuild the attempt one slice's dispatch provenance records.

        This is the only way an attempt is reconstructed from persisted state,
        and it reads every field from the slice's own dispatch boundary, so a
        new field cannot be dropped by a second hand-written construction. The
        controller epoch is the current run's epoch, which is the epoch the
        correlation admits; the generation and ledger floor are the ones the
        persisted intent was recorded with. The slice persists the qualified
        harness the policy resolved and the protocol agent type separately, so
        each dimension reads its own value and a request can never be mistaken
        for the route that ran.

        A slice that records no intent has no attempt to rebuild, and
        reconstruction fails closed rather than inventing one.
        """
        if slice_state.dispatch_intent_id is None or slice_state.dispatch_started_at is None:
            raise TLLoopError(f"slice {slice_state.id!r} records no dispatch intent to reconstruct")
        return cls(
            intent_id=slice_state.dispatch_intent_id,
            started_at=slice_state.dispatch_started_at,
            harness=slice_state.resolved_harness or slice_state.agent_type or "",
            agent_type=slice_state.agent_type or "",
            model=slice_state.model,
            requested_harness=slice_state.requested_harness,
            route_reconciliation_source=(
                "proven_preexecution_retry"
                if slice_state.dispatch_uses_current_role_configuration
                else None
            ),
            attempt=max(1, slice_state.attempts),
            controller_epoch=controller_epoch,
            dispatch_generation=slice_state.dispatch_generation,
            ledger_floor=slice_state.dispatch_ledger_floor,
        )


@dataclass(frozen=True)
class DispatchCorrelation:
    """Classify a spawn observation without inferring ownership from history."""

    classification: str
    slice_id: str | None = None
    reason: str | None = None


DISPATCH_CORRELATED = "correlated"
DISPATCH_HISTORICAL_AUDIT = "historical_audit"
DISPATCH_INTEGRITY_CONFLICT = "integrity_conflict"
#: A spawn row was confirmed under a controller epoch that is not the current
#: one, so it belongs to a predecessor generation and can never confirm a
#: dispatch this run owns. This is the one refusal reason that is historical
#: evidence rather than an integrity conflict.
DISPATCH_EPOCH_MISMATCH = "controller_epoch_mismatch"
#: The spawn row names an intent this run already recorded a confirmation for.
#: One dispatch writes two such rows -- the child registration carries
#: ``child_agent`` and the dispatch record carries ``slug``/``task_summary`` --
#: and the controller may observe either, or both, for the same intent. The
#: second one carries no new fact, so it is acknowledged without an FSM
#: transition instead of being quarantined as an integrity conflict.
DISPATCH_ALREADY_CONFIRMED = "already_confirmed"
#: The boundary a slice records once it has taken a spawn confirmation. Paired
#: with a recorded authoritative sequence this is the durable proof that a
#: duplicate confirmation is a duplicate and not a first confirmation.
DISPATCH_CONFIRMED_BOUNDARY = "agent.spawned"
#: Boundaries at which an ordered child controller's dispatch is durably
#: reconciled rather than in flight. ``sub_tl_started`` is recorded when the
#: controller takes the child's spawn confirmation; ``sub_tl_recovered`` is
#: recorded when an approved recovery mints a replacement invocation for a child
#: whose previous controller had already exited. Both name a dispatch of record,
#: so either is a state the controller can still act on and re-dispatch from.
#: Recovery must not leave a child at a boundary the next continuation proof
#: rejects: a child that fails again after an approved recovery has to stay
#: provable, or the run is permanently unrecoverable on a false diagnosis.
SUB_TL_DISPATCH_STARTED_BOUNDARY = "sub_tl_started"
SUB_TL_DISPATCH_RECOVERED_BOUNDARY = "sub_tl_recovered"
RECONCILED_SUB_TL_DISPATCH_BOUNDARIES: frozenset[str] = frozenset(
    {SUB_TL_DISPATCH_STARTED_BOUNDARY, SUB_TL_DISPATCH_RECOVERED_BOUNDARY}
)
#: Correlation markers that name a permanently retained audit row. A refused
#: publication and a refused spawn confirmation from a predecessor controller
#: epoch are the same class of evidence: they prove what an earlier generation
#: did, so they are written to the audit log and never to the pending queue.
PUBLICATION_HISTORY_AUDIT = "publication_history_audit"
SPAWN_HISTORY_AUDIT = "spawn_history_audit"
AUDIT_CORRELATIONS = frozenset({PUBLICATION_HISTORY_AUDIT, SPAWN_HISTORY_AUDIT})


@dataclass
class EventDiagnostics:
    """Counters explaining what the controller did with projected events."""

    controller_started_at: float = field(default_factory=time.time)
    task_started_at: dict[str, float] = field(default_factory=dict)
    received: int = 0
    acknowledged: int = 0
    filtered: int = 0
    correlated: int = 0
    rejected: int = 0
    duplicate_confirmations: int = 0
    last_event_seq: int | None = None
    last_authoritative_event_seq: int | None = None
    last_observed_progress_at: float | None = None
    reader_finding_keys: set[tuple[str, str, str, int]] = field(default_factory=set)
    reader_findings: list[str] = field(default_factory=list)
    unresolved_event_keys: set[tuple[int, str]] = field(default_factory=set)
    unresolved_events: list[str] = field(default_factory=list)

    def record_reader_findings(self, findings: Sequence[LedgerFinding]) -> None:
        for finding in findings:
            key = (
                finding.kind.value,
                finding.event_type,
                str(finding.segment),
                finding.line_number,
            )
            if key in self.reader_finding_keys:
                continue
            self.reader_finding_keys.add(key)
            self.reader_findings.append(finding.message)
            if finding.kind is FindingKind.RUN_ID_MISMATCH:
                self.received += 1

    def record_unresolved_event(self, event: EventEnvelope, resolution: IdentityResolution) -> None:
        """Record a valid observation retained until ownership is proven."""
        key = (event.run_seq or 0, event.event_type)
        if key in self.unresolved_event_keys:
            return
        self.unresolved_event_keys.add(key)
        details = (
            f"{event.event_type} seq={event.run_seq} reason={resolution.reason} "
            f"candidates={list(resolution.candidates)}"
        )
        self.unresolved_events.append(details)
        self.rejected += 1

    def record_task_blocked_owner_issue(
        self,
        event: EventEnvelope,
        reason_code: str,
        candidates: Sequence[str],
        *,
        reporter_scope_path: Sequence[str] = (),
        candidate_paths: Sequence[Sequence[str]] = (),
        conflicting_aliases: Sequence[str] = (),
        missing_proof: Sequence[str] = (),
    ) -> None:
        """Retain the stable reason for an unresolved blocked-event owner."""
        key = (event.run_seq or 0, event.event_type)
        if key in self.unresolved_event_keys:
            return
        self.unresolved_event_keys.add(key)
        blocked = event.task_blocked
        self.unresolved_events.append(
            f"{event.event_type} seq={event.run_seq} reason={reason_code} "
            f"reporter={event.agent_id!r} subject={blocked.slice_id if blocked else None!r} "
            f"reporter_scope={list(reporter_scope_path)} candidates={list(candidates)} "
            f"candidate_scopes={[list(path) for path in candidate_paths]} "
            f"conflicting_aliases={list(conflicting_aliases)} "
            f"missing_proof={list(missing_proof)}"
        )
        self.rejected += 1

    def snapshot(self) -> Mapping[str, object]:
        return {
            "controller_started_at": self.controller_started_at,
            "elapsed_seconds": max(0.0, time.time() - self.controller_started_at),
            "task_started_at": dict(self.task_started_at),
            "received": self.received,
            "acknowledged": self.acknowledged,
            "filtered": self.filtered,
            "correlated": self.correlated,
            "rejected": self.rejected,
            "duplicate_confirmations": self.duplicate_confirmations,
            "last_event_seq": self.last_event_seq,
            "last_authoritative_event_seq": self.last_authoritative_event_seq,
            "last_observed_progress_at": self.last_observed_progress_at,
            "reader_findings": list(self.reader_findings),
            "unresolved_events": list(self.unresolved_events),
        }


