@dataclass(frozen=True)
class WorkPlan:
    """Direct children the TL may dispatch for one bounded run."""

    workers: tuple[WorkerTask, ...] = ()
    leaves: tuple[LeafTask, ...] = ()
    sub_tls: tuple[SubTLTask, ...] = ()

    def __post_init__(self) -> None:
        names = (
            [task.name for task in self.workers]
            + [task.name for task in self.leaves]
            + [task.name for task in self.sub_tls]
        )
        if len(names) != len(set(names)):
            raise ValueError("worker and leaf names must be unique")
        leaf_names = {task.name for task in self.leaves}
        validate_leaf_dependencies(
            {task.name: task.depends_on for task in self.leaves if task.depends_on},
            leaf_names=leaf_names,
            # A worker never merges and a sub-TL carries its own staged order, so
            # an edge naming either is a rejected plan rather than a lost edge.
            other_names=set(names) - leaf_names,
        )
        _validate_chainlink_issue_bindings(self)

    @classmethod
    def from_mapping(cls, value: Mapping[str, object], *, path: str = "plan") -> WorkPlan:
        """Parse the small, closed plan shape used by the TL entry point."""
        unknown = sorted(set(value) - {"workers", "leaves", "sub_tls"})
        if unknown:
            raise ValueError(f"work plan contains unknown keys: {', '.join(unknown)}")
        parsed = cls(
            workers=_workers(value.get("workers", ())),
            leaves=_leaves(value.get("leaves", ()), path=f"{path}.leaves"),
            sub_tls=_sub_tls(value.get("sub_tls", ()), path=f"{path}.sub_tls"),
        )
        return normalize_work_plan(parsed, path=path)

    @property
    def ordered_stages(self) -> tuple[OrderedStage, ...]:
        """Group direct sub-TLs by positive sibling order, lowest first."""
        grouped: dict[int, list[str]] = {}
        for task in self.sub_tls:
            grouped.setdefault(task.order, []).append(task.name)
        return tuple(
            OrderedStage(order, tuple(sorted(grouped[order]))) for order in sorted(grouped)
        )


@dataclass(frozen=True)
class SubTLTask:
    """One recursive child TL executed with an isolated nested run-state."""

    name: str
    plan: WorkPlan | Mapping[str, object]
    source: EventQueue | None = None
    effects: EffectClient | ReadOnlyEffectClient | None = None
    worktree: str | Path | None = None
    agent_id: str | None = None
    order: int = 1
    integration: IntegrationContract = field(default_factory=IntegrationContract)
    order_explicit: bool = True
    task_timeout_seconds: float | None = None
    task_timeout_declared: bool = False
    chainlink_issue_id: int | None = None

    def __post_init__(self) -> None:
        _require_text(self.name, "sub-TL name")
        if not isinstance(self.plan, (WorkPlan, Mapping)):
            raise TypeError("sub-TL plan must be a WorkPlan or object")
        _optional_text(self.agent_id, "sub-TL agent_id")
        if self.worktree is not None:
            _require_text(str(self.worktree), "sub-TL worktree")
        if type(self.order) is not int or self.order <= 0:
            raise ValueError("sub-TL order must be a positive integer")
        if not isinstance(self.integration, IntegrationContract):
            raise TypeError("sub-TL integration must be an IntegrationContract")
        if self.integration.aggregate_review_owner is ReviewOwner.AGGREGATE:
            raise ValueError(
                "root aggregate review phases are unsupported; reviews belong to leaf PRs"
            )
        if not isinstance(self.order_explicit, bool):
            raise TypeError("sub-TL order_explicit must be a boolean")
        _validate_task_timeout(self.task_timeout_seconds, "sub-TL task_timeout_seconds")
        _validate_chainlink_issue_id(self.chainlink_issue_id, "sub-TL chainlink_issue_id")


@dataclass(frozen=True)
class TLLoopConfig:
    """Safety ceilings and effect mode for one TL invocation."""

    active: bool = True
    max_workers: int = 8
    max_leaves: int = 8
    max_parallel_slices: int | None = None
    max_events: int = 256
    test_harness: bool = False
    cancel_event: threading.Event | None = None
    poll_interval: float = 0.1
    keep_alive_on_waiting: bool = True
    task_timeout_seconds: float | None = 3600.0
    task_timeout_source: str = "built_in"
    max_base_revalidations: int = 3
    dispatch_retry_limit: int = DEFAULT_RETRY_LIMIT
    dispatch_retry_base_delay_seconds: float = DEFAULT_RETRY_BASE_DELAY_SECONDS
    dispatch_retry_max_delay_seconds: float = DEFAULT_RETRY_MAX_DELAY_SECONDS
    wall_clock: Callable[[], float] | None = None
    work_clock: Callable[[], float] | None = None
    heartbeat: HeartbeatConfig | None = None
    goals: GoalState | None = None
    merge_strategy: str | None = None
    working_dir: str | None = None
    repository_identity: RepositoryIdentity | None = None
    source: EventQueue | None = None
    effects: EffectClient | ReadOnlyEffectClient | None = None
    root_dir: str | Path = DEFAULT_ROOT
    project_root: str | Path | None = None
    run_id: str = "tl-run"
    session_mode: str | None = None
    ledger_run_id: str | None = None
    policy: HarnessPolicy | None = None
    learned_policy: LearnedPolicy | None = None
    capabilities: CapabilityMap | None = None
    catalog: ModelCatalog | None = None
    requested_model: str | None = None
    role: str = "worker"
    review_policy_path: str | Path | None = None
    review_clock: Callable[[], datetime] | None = None
    enable_reviewer_spawn: bool = False
    dispatch_names: Mapping[str, str] = field(default_factory=dict)
    ordered_recovery_child: str | None = None
    ordered_recovery: bool = False
    review_model_choice: object | None = None
    tl_model_choice: RlmModelChoice | None = None
    branch: str = "main"
    worktree: str | Path | None = None
    agent_id: str | None = None
    parent_branch: str | None = None
    parent_run_id: str | None = None
    parent_agent_id: str | None = None
    parent_generation_id: str | None = None
    depth: int = 0
    max_depth: int = 3
    plan_revision: int = 1
    declared_manifest: PlanManifest | None = None

    def __post_init__(self) -> None:
        if self.project_root is not None:
            object.__setattr__(self, "project_root", Path(self.project_root))
        for name in (
            "max_workers",
            "max_leaves",
            "max_events",
            "max_base_revalidations",
            "dispatch_retry_limit",
        ):
            value = getattr(self, name)
            if type(value) is not int or value < 0:
                raise ValueError(f"{name} must be a non-negative integer")
        for name in (
            "dispatch_retry_base_delay_seconds",
            "dispatch_retry_max_delay_seconds",
        ):
            value = getattr(self, name)
            if isinstance(value, bool) or not isinstance(value, (int, float)) or value < 0:
                raise ValueError(f"{name} must be a non-negative number")
        if self.dispatch_retry_max_delay_seconds < self.dispatch_retry_base_delay_seconds:
            raise ValueError("dispatch_retry_max_delay_seconds must be at least the base delay")
        if self.wall_clock is not None and not callable(self.wall_clock):
            raise TypeError("wall_clock must be a zero-argument callable or null")
        if self.work_clock is not None and not callable(self.work_clock):
            raise TypeError("work_clock must be a zero-argument callable or null")
        if self.max_parallel_slices is not None and (
            type(self.max_parallel_slices) is not int or self.max_parallel_slices < 0
        ):
            raise ValueError("max_parallel_slices must be null or non-negative")
        if self.max_events == 0:
            raise ValueError("max_events must be positive")
        if type(self.test_harness) is not bool:
            raise ValueError("test_harness must be a boolean")
        if not isinstance(self.dispatch_names, Mapping):
            raise TypeError("dispatch_names must be a mapping")
        for slice_id, runtime_name in self.dispatch_names.items():
            _require_text(slice_id, "dispatch_names slice id")
            _require_text(runtime_name, "dispatch_names runtime name")
        if type(self.ordered_recovery) is not bool:
            raise ValueError("ordered_recovery must be a boolean")
        if self.poll_interval < 0:
            raise ValueError("poll_interval must be non-negative")
        if self.heartbeat is not None and self.project_root is None:
            raise ValueError("project_root is required when heartbeat reconciliation is enabled")
        if type(self.keep_alive_on_waiting) is not bool:
            raise ValueError("keep_alive_on_waiting must be a boolean")
        _validate_task_timeout(self.task_timeout_seconds, "task_timeout_seconds")
        _require_text(self.task_timeout_source, "task_timeout_source")
        if type(self.enable_reviewer_spawn) is not bool:
            raise ValueError("enable_reviewer_spawn must be a boolean")
        _optional_text(self.merge_strategy, "merge_strategy")
        _optional_text(self.working_dir, "working_dir")
        if self.repository_identity is not None and not isinstance(
            self.repository_identity, RepositoryIdentity
        ):
            raise TypeError("repository_identity must be a RepositoryIdentity or null")
        _require_text(self.run_id, "run_id")
        if self.session_mode is not None and self.session_mode not in {
            "start",
            "continue",
            "recreate",
        }:
            raise ValueError("session_mode must be start, continue, recreate, or null")
        _optional_text(self.ledger_run_id, "ledger_run_id")
        _require_text(self.role, "role")
        for name in ("depth", "max_depth"):
            value = getattr(self, name)
            if type(value) is not int or value < 0:
                raise ValueError(f"{name} must be a non-negative integer")
        if type(self.plan_revision) is not int or self.plan_revision < 1:
            raise ValueError("plan_revision must be a positive integer")
        _require_text(self.branch, "branch")
        _optional_text(self.agent_id, "agent_id")
        _optional_text(self.ordered_recovery_child, "ordered_recovery_child")
        _optional_text(self.parent_branch, "parent_branch")
        _optional_text(self.parent_run_id, "parent_run_id")
        _optional_text(self.parent_agent_id, "parent_agent_id")
        _optional_text(self.parent_generation_id, "parent_generation_id")
        if self.worktree is not None:
            _require_text(str(self.worktree), "worktree")
        _optional_text(self.requested_model, "requested_model")
        if self.requested_model is not None and self.catalog is None:
            raise ValueError("requested_model requires a model catalog")


@dataclass(frozen=True)
class EffectIntent:
    """An effect requested by the loop, whether executed or shadowed."""

    operation: str
    target: str
    arguments: Mapping[str, object]
    executed: bool

    def __post_init__(self) -> None:
        object.__setattr__(self, "arguments", MappingProxyType(dict(self.arguments)))


@dataclass(frozen=True)
class LoopTransition:
    """One durable event-to-phase transition."""

    event_seq: int
    event_type: str
    before: TLPhase
    after: TLPhase


@dataclass(frozen=True)
class TLRunResult:
    """The durable result and audit trail of one bounded invocation."""

    final_state: RunState
    effects: tuple[EffectIntent, ...]
    transitions: tuple[LoopTransition, ...]
    consumed_events: tuple[int, ...]
    heartbeat_events: tuple[SyntheticHeartbeatEvent, ...] = ()
    diagnostics: Mapping[str, object] = field(default_factory=dict)
    journal_entries: tuple[Mapping[str, object], ...] = ()

    @property
    def cursor(self) -> int:
        """Return the exact durable ledger cursor reached by this invocation."""
        return self.final_state.events.last_consumed_offset

    @property
    def reducer_version(self) -> int:
        """Return the reducer contract used to produce this checkpoint."""
        return self.final_state.reducer_version

    @property
    def recursive_position(self) -> object | None:
        """Return the complete recursive FSM position, if this is recursive."""
        return self.final_state.recursive_fsm


def tl_run(
    root_spec: WorkPlan | Mapping[str, object],
    cfg: TLLoopConfig,
    budgets: BudgetLedger | Mapping[str, object],
) -> TLRunResult:
    """Run one selector-integrated wave through the shared active/shadow body."""
    if not isinstance(cfg, TLLoopConfig):
        raise TypeError("cfg must be a TLLoopConfig")
    try:
        plan, run_id, source, effects = _root_inputs(root_spec, cfg)
    except ChainlinkIssueBindingError as error:
        if cfg.active:
            gate_recorded = _record_chainlink_binding_gate(root_spec, cfg, error)
            if not gate_recorded:
                raise TLLoopError(
                    f"{error}; no durable gate was created because repository identity "
                    "is unavailable"
                ) from error
        raise TLLoopError(
            f"{error}; resolve gate {CHAINLINK_BINDING_RECONCILIATION_GATE_NAME!r} "
            "by correcting the explicit slice binding"
        ) from error
    policy = cfg.policy or load_policy()
    capabilities = cfg.capabilities or load_capability()
    selected = replace(cfg, policy=policy, capabilities=capabilities)
    return run_tl_loop(
        run_id,
        plan,
        source,
        effects,
        config=selected,
        root_dir=selected.root_dir,
        budgets=budgets,
        initial_slices=_initial_slices(plan, selected) if plan is not None else None,
    )


def run_tl_loop(
    run_id: str,
    plan: WorkPlan | Mapping[str, object] | None,
    source: EventQueue,
    effects: EffectClient | ReadOnlyEffectClient,
    *,
    config: TLLoopConfig | None = None,
    root_dir: str | Path = DEFAULT_ROOT,
    decoder: TLEventDecoder | None = None,
    budgets: BudgetLedger | Mapping[str, object] | None = None,
    initial_slices: Mapping[str, Mapping[str, object]] | None = None,
) -> TLRunResult:
    """Dispatch direct children and run one bounded active/shadow event loop."""
    selected = config or TLLoopConfig()
    _validate_mode(selected, effects)
    if plan is not None and isinstance(plan, Mapping):
        try:
            plan = WorkPlan.from_mapping(plan)
        except ChainlinkIssueBindingError as error:
            if selected.active:
                gate_recorded = _record_chainlink_binding_gate(
                    {"run_id": run_id, "plan": plan}, selected, error
                )
                if not gate_recorded:
                    raise TLLoopError(
                        f"{error}; no durable gate was created because repository identity "
                        "is unavailable"
                    ) from error
            raise TLLoopError(
                f"{error}; resolve gate {CHAINLINK_BINDING_RECONCILIATION_GATE_NAME!r} "
                "by correcting the explicit slice binding"
            ) from error
    store = RunStore(run_id, Path(root_dir))
    identity_effects: list[EffectIntent] = []
    checkpoint_error: CorruptCheckpoint | None = None
    existing_state: RunState | None = None
    if store.path.exists():
        try:
            existing_state = store.load()
        except CorruptCheckpoint as error:
            checkpoint_error = error
    if existing_state is not None:
        _verify_supplied_plan_before_identity_recovery(
            run_id,
            plan,
            existing_state,
            selected,
            Path(root_dir),
        )
    identity_required = _repository_identity_required(existing_state, selected)
    if checkpoint_error is not None and not identity_required:
        raise TLLoopError(f"run checkpoint is corrupt: {checkpoint_error}") from checkpoint_error
    if identity_required:
        inherited_identity = (
            selected.repository_identity
            if selected.parent_run_id is not None
            or (existing_state is None and selected.repository_identity is not None)
            or (not selected.active and selected.repository_identity is not None)
            else None
        )
        if inherited_identity is not None:
            resolution, failure_code = inherited_identity, None
        else:
            resolution, failure_code = _resolve_repository_identity_detail(
                selected, effects, identity_effects
            )
        if resolution is None:
            if checkpoint_error is not None:
                raise TLLoopError(
                    f"repository_identity_{failure_code}: existing run checkpoint is unavailable"
                ) from checkpoint_error
            if existing_state is None:
                raise TLLoopError(
                    f"repository_identity_{failure_code}: no runnable run was created"
                )
            return _park_repository_identity_failure(
                store,
                failure_code or "unavailable",
                identity_effects,
                existing_state,
            )
        if selected.repository_identity is not None and selected.repository_identity != resolution:
            raise TLLoopError(
                "repository_identity_conflict: configured identity differs from the selected remote"
            )
        selected = replace(selected, repository_identity=resolution)
        if checkpoint_error is not None:
            try:
                store.migrate_repository_identity(resolution)
            except RepositoryIdentityMigrationError as error:
                raise TLLoopError(
                    f"repository_identity_{error.code}: existing checkpoint cannot be resumed"
                ) from error
            raise TLLoopError("repository_identity_malformed: checkpoint validation failed")
        if existing_state is not None:
            evidence_children = (
                _repository_identity_sub_tl_names(existing_state, store)
                if existing_state.repository_identity is None
                else ()
            )
            try:
                existing_state = store.migrate_repository_identity(
                    resolution,
                    corroborating_sub_tls=evidence_children,
                )
            except RepositoryIdentityMigrationError as error:
                if error.code == "conflicting":
                    raise TLLoopError(
                        "repository_identity_conflict: checkpoint and selected remote differ"
                    ) from error
                return _park_repository_identity_failure(
                    store,
                    error.code,
                    identity_effects,
                    existing_state,
                )
            if any(gate.name == REPOSITORY_IDENTITY_GATE_NAME for gate in existing_state.gates):
                existing_state = store.clear_gate(REPOSITORY_IDENTITY_GATE_NAME)
    if existing_state is not None:
        # Before anything reads the gates, so a parked run resumed from a
        # pre-#1119 checkpoint resolves the same per-slice name this code opens.
        existing_state = _migrate_legacy_dispatch_gates(store, existing_state)
    continued_failed_root_reason = _continued_failed_root_reason(existing_state, selected)
    if existing_state is not None and _is_terminal_phase(_phase_from_state(existing_state)):
        if plan is not None:
            persisted_manifest = existing_state.plan_manifest
            if persisted_manifest is None:
                raise TLLoopError(
                    "terminal checkpoint has no immutable plan manifest; "
                    "cannot verify the supplied plan before returning terminal state"
                )
            supplied_plan = plan if isinstance(plan, WorkPlan) else WorkPlan.from_mapping(plan)
            candidate = _candidate_manifest(supplied_plan, run_id, selected)
            candidate = retain_scope_revisions(candidate, persisted_manifest)
            if candidate.digest != persisted_manifest.digest:
                raise TLLoopError(
                    "terminal checkpoint plan digest "
                    f"{persisted_manifest.digest} differs from supplied plan digest "
                    f"{candidate.digest}; archive the completed run before starting a new plan"
                )
        if continued_failed_root_reason is None:
            terminal_recovery_reopened = False
            if (
                selected.session_mode == "continue"
                and isinstance(existing_state.recursive_fsm, RecursiveTLFailed)
                and existing_state.plan_manifest is not None
            ):
                recovery_plan = (
                    plan
                    if isinstance(plan, WorkPlan)
                    else WorkPlan.from_mapping(plan)
                    if plan is not None
                    else _work_plan_from_manifest(existing_state.plan_manifest)
                )
                decision = _ordered_terminal_recovery_decision(
                    existing_state,
                    recovery_plan,
                    selected,
                    store,
                )
                if decision is not None:
                    if not decision.recoverable:
                        state = _hold_ordered_recovery_gate(store, decision)
                        return TLRunResult(
                            state,
                            (),
                            (),
                            (),
                            (),
                            {
                                "reducer_version": state.reducer_version,
                                "cursor": state.events.last_consumed_offset,
                                "ordered_recovery": decision.reason,
                                "recovery_gate": decision.gate_name,
                                "recovery_gate_status": (
                                    decision.gate_status.value
                                    if decision.gate_status is not None
                                    else GateStatus.PENDING.value
                                ),
                            },
                            (),
                        )
                    try:
                        existing_state = _reopen_ordered_scope(
                            existing_state,
                            recovery_plan,
                            store,
                            decision.task_name,
                            authorized=decision.authorized,
                        )
                    except OrderedCompletionEvidenceError as error:
                        return _terminal_ordered_completion_hold_result(
                            existing_state,
                            error,
                            selected,
                            effects,
                            store,
                            identity_effects,
                        )
                    selected = replace(
                        selected,
                        ordered_recovery_child=decision.task_name,
                        branch=existing_state.owner_branch or selected.branch,
                        worktree=existing_state.owner_worktree or selected.worktree,
                    )
                    terminal_recovery_reopened = True
            if selected.ordered_recovery and isinstance(
                existing_state.recursive_fsm, RecursiveTLFailed
            ):
                recovery_plan = (
                    plan
                    if isinstance(plan, WorkPlan)
                    else WorkPlan.from_mapping(plan)
                    if plan is not None
                    else _work_plan_from_manifest(existing_state.plan_manifest)
                )
                dispatch_failed = any(
                    item.status is SliceStatus.DISPATCH_FAILED
                    for item in existing_state.slices.values()
                )
                rejection = (
                    _proven_preexecution_dispatch_rejection(existing_state, store)
                    if dispatch_failed
                    else None
                )
                if dispatch_failed and rejection is None:
                    # The parent may restart a child controller only after its
                    # proof. Recheck the leaf-owned evidence here as well so a
                    # changed checkpoint cannot turn a prior authorization into
                    # a fresh dispatch.
                    terminal_recovery_reopened = False
                else:
                    try:
                        existing_state = _reopen_ordered_scope(
                            existing_state,
                            recovery_plan,
                            store,
                            None,
                            retry_dispatch_slice=(rejection.slice_id if rejection else None),
                        )
                    except OrderedCompletionEvidenceError as error:
                        return _terminal_ordered_completion_hold_result(
                            existing_state,
                            error,
                            selected,
                            effects,
                            store,
                            identity_effects,
                        )
                    terminal_recovery_reopened = True
            # Fall through to the live loop when a recovery reopened this terminal
            # checkpoint so the recovered child is actually relaunched in this
            # invocation instead of requiring a second controller call.
            if not terminal_recovery_reopened:
                if existing_state.reducer_version != REDUCER_VERSION:
                    raise TLLoopError(
                        f"checkpoint reducer_version {existing_state.reducer_version} is incompatible "
                        f"with reducer {REDUCER_VERSION}"
                    )
                terminal_ledger_id = selected.ledger_run_id or existing_state.ledger_run_id
                terminal_log: list[EffectIntent] = (
                    EffectJournal(run_id, store.run_dir / "action-journal.json")
                    if terminal_ledger_id is not None
                    else []
                )
                return TLRunResult(
                    existing_state,
                    (),
                    (),
                    (),
                    (),
                    {
                        "reducer_version": existing_state.reducer_version,
                        "cursor": existing_state.events.last_consumed_offset,
                    },
                    _journal_entries(terminal_log),
                )
    manifest: PlanManifest
    if existing_state is not None and existing_state.plan_manifest is not None:
        persisted_manifest = existing_state.plan_manifest
        if _manifest_is_legacy(persisted_manifest):
            if plan is None:
                raise TLLoopError(
                    "continuation cannot reconstruct a legacy checkpoint; "
                    "supply an explicit external WorkPlan"
                )
            supplied_plan = plan if isinstance(plan, WorkPlan) else WorkPlan.from_mapping(plan)
            candidate = _candidate_manifest(supplied_plan, run_id, selected)
            reconciliation = None
            if selected.active:
                journal_path = store.run_dir / "action-journal.json"
                migration_journal: list[EffectIntent] = (
                    EffectJournal(run_id, journal_path)
                    if selected.ledger_run_id is not None or journal_path.exists()
                    else []
                )
                reconciliation = reconcile_legacy_manifest(
                    persisted_manifest,
                    candidate,
                    existing_state,
                    migration_journal,
                    child_checkpoint_root=store.run_dir,
                )
                if not reconciliation.proven:
                    store.set_gate(reconciliation.gate_name())
                    raise TLLoopError(
                        "continuation cannot replace the legacy manifest: "
                        f"{reconciliation.disposition.value}: {reconciliation.reason}"
                    )
            proofs = (
                {proof.slice_id: proof for proof in reconciliation.proofs} if reconciliation else {}
            )
            rebound: dict[str, SliceState] = {}
            for slice_id, slice_state in existing_state.slices.items():
                proof = proofs.get(slice_id)
                rebound[slice_id] = replace(
                    slice_state,
                    branch=(proof.branch if proof else None) or slice_state.branch,
                    worktree=(proof.worktree if proof else None) or slice_state.worktree,
                    legacy_manifest_migration=proof.to_document() if proof else None,
                )
            generated = _initial_slices(supplied_plan, selected, root_dir, run_id)
            initial_slices = {
                **rebound,
                **{
                    name: value
                    for name, value in generated.items()
                    if name not in existing_state.slices
                },
            }
            try:
                existing_state = store.set_plan_manifest(
                    candidate,
                    slices=initial_slices,
                )
            except ManifestError as error:
                if "chainlink_issue_id" in str(error):
                    store.set_gate(CHAINLINK_BINDING_RECONCILIATION_GATE_NAME)
                    raise TLLoopError(
                        f"legacy plan manifest replacement rejected: {error}; resolve gate "
                        f"{CHAINLINK_BINDING_RECONCILIATION_GATE_NAME!r}"
                    ) from error
                raise TLLoopError(f"legacy plan manifest replacement rejected: {error}") from error
            existing_state = _clear_resolved_migration_gate(
                store,
                existing_state,
                reconciliation,
            )
            work_plan = _work_plan_from_manifest(candidate)
            manifest = candidate
            initial_slices = None
        elif plan is None:
            work_plan = _work_plan_from_manifest(persisted_manifest)
            manifest = persisted_manifest
            initial_slices = None
        else:
            supplied_plan = plan if isinstance(plan, WorkPlan) else WorkPlan.from_mapping(plan)
            candidate = _candidate_manifest(supplied_plan, run_id, selected)
            candidate = retain_scope_revisions(candidate, persisted_manifest)
            if candidate.digest == persisted_manifest.digest:
                work_plan = _work_plan_from_manifest(persisted_manifest)
                manifest = persisted_manifest
                initial_slices = None
            else:
                raise TLLoopError(
                    "external plan differs from the persisted manifest; use "
                    "`exomonad plan revise --dry-run` and apply the audited revision. "
                    "If revision analysis reports unversioned drift, inspect "
                    "`exomonad plan reconcile --dry-run` and apply only with its "
                    "current evidence fingerprint."
                )
    else:
        if plan is None:
            if existing_state is None:
                raise TLLoopError("a new run requires an external WorkPlan")
            raise TLLoopError(
                "continuation cannot reconstruct a legacy checkpoint without an immutable plan manifest"
            )
        work_plan = plan if isinstance(plan, WorkPlan) else WorkPlan.from_mapping(plan)
        manifest = _candidate_manifest(work_plan, run_id, selected)
        if initial_slices is None:
            initial_slices = _initial_slices(work_plan, selected, root_dir, run_id)
        initial_slices = _bind_initial_slices(initial_slices, manifest)

    if len(work_plan.workers) > selected.max_workers:
        raise LoopLimitExceeded("work plan exceeds max_workers")
    if len(work_plan.leaves) > selected.max_leaves:
        raise LoopLimitExceeded("work plan exceeds max_leaves")
    epoch_enabled = selected.active and selected.review_clock is None

    if existing_state is None:
        root_state: dict[str, object] = {}
        if (
            work_plan.sub_tls
            or selected.parent_branch is not None
            or selected.worktree is not None
            or selected.depth > 0
        ):
            root_state = {
                "owner_branch": selected.branch,
                "owner_worktree": _effective_worktree(selected, Path(root_dir), run_id),
                "parent_branch": selected.parent_branch,
                "parent_run_id": selected.parent_run_id,
                "parent_agent_id": selected.parent_agent_id,
                "depth": selected.depth,
            }
        if selected.goals is not None:
            root_state["goals"] = _encode_goals(selected.goals)
        if initial_slices is not None:
            root_state["slices"] = copy.deepcopy(dict(initial_slices))
        root_state["plan_manifest"] = manifest.to_document()
        root_state["fsm"] = _canonical_planning_from_manifest(manifest, initial_slices or {})
        if budgets is not None:
            root_state["budgets"] = _budget_root(budgets)
        if selected.ledger_run_id is not None:
            root_state["ledger_run_id"] = selected.ledger_run_id
        if selected.repository_identity is not None:
            root_state["repository_identity"] = selected.repository_identity.to_document()
        if selected.session_mode is not None:
            root_state["session_mode"] = selected.session_mode
        if epoch_enabled:
            root_state["controller_epoch"] = _controller_epoch(
                store.root_dir, run_id, selected.parent_generation_id
            )
        create(run_id, root_state, root_dir=store.root_dir)
    state = store.load()
    if plan is not None and any(
        gate.name == CHAINLINK_BINDING_RECONCILIATION_GATE_NAME for gate in state.gates
    ):
        store.clear_gate(CHAINLINK_BINDING_RECONCILIATION_GATE_NAME)
        state = store.load()
    if state.reducer_version != REDUCER_VERSION:
        raise TLLoopError(
            f"checkpoint reducer_version {state.reducer_version} is incompatible "
            f"with reducer {REDUCER_VERSION}"
        )
    if selected.repository_identity is not None:
        if (
            state.repository_identity is not None
            and state.repository_identity != selected.repository_identity
        ):
            raise TLLoopError("continuation repository identity differs from the checkpoint")
        if state.repository_identity is None:
            state = store.set_repository_identity(selected.repository_identity)
    if state.plan_manifest is None:
        node_ids_by_name = {node.name: node.node_id for node in manifest.nodes}
        protected = {
            node_ids_by_name[next_node]
            for next_node, slice_state in state.slices.items()
            if slice_state.status not in {SliceStatus.PENDING, SliceStatus.READY}
            and next_node in node_ids_by_name
        }
        if protected and selected.active:
            state = store.set_gate(
                "plan-manifest-migration: existing active run has no immutable manifest"
            )
            raise TLLoopError("continuation cannot infer a plan manifest for an active legacy run")
        state = store.set_plan_manifest(
            manifest,
            slices=initial_slices if existing_state is None else None,
        )
    if state.session_mode is None and selected.session_mode is not None:
        state = store.set_session_mode(selected.session_mode)
    if epoch_enabled:
        current_controller_epoch = _controller_epoch(
            store.root_dir, run_id, selected.parent_generation_id
        )
        if state.controller_epoch is None or (
            selected.session_mode == "continue"
            and state.controller_epoch != current_controller_epoch
        ):
            state = store.set_controller_epoch(current_controller_epoch)
    if (
        state.ledger_run_id
        and selected.ledger_run_id
        and (state.ledger_run_id != selected.ledger_run_id)
    ):
        raise TLLoopError(
            f"checkpoint ledger_run_id {state.ledger_run_id!r} does not match "
            f"active swarm {selected.ledger_run_id!r}"
        )
    effective_ledger_run_id = selected.ledger_run_id or state.ledger_run_id
    if effective_ledger_run_id is not None:
        selected = replace(selected, ledger_run_id=effective_ledger_run_id)
    state = _ensure_canonical_scope(state, manifest, store)
    state = _release_canonical_scope(state, store)
    effects_log: list[EffectIntent] = (
        EffectJournal(run_id, store.run_dir / "action-journal.json")
        if selected.ledger_run_id is not None or (store.run_dir / "action-journal.json").exists()
        else []
    )
    effects_log.extend(identity_effects)
    state = _reconcile_legacy_parked_lanes(state, store, effects_log)
    state = _initialize_ordered_runtime(work_plan, state, store)
    if continued_failed_root_reason is not None:
        previous_phase = _phase_from_state(state)
        try:
            state = _reopen_ordered_scope(state, work_plan, store, None)
        except OrderedCompletionEvidenceError as error:
            state = _hold_ordered_completion_evidence(
                state, error, selected, effects, store, effects_log
            )
            return TLRunResult(
                state,
                tuple(effects_log),
                (),
                (),
                (),
                {"ordered_completion_recovery": str(error)},
                _journal_entries(effects_log),
            )
        _emit_phase_change(
            run_id,
            previous_phase,
            _phase_from_state(state),
            selected,
            effects,
            effects_log,
        )
    try:
        return _run_loop(
            run_id,
            work_plan,
            source,
            effects,
            selected,
            store,
            state,
            effects_log,
            decoder or TLEventDecoder(),
            True,
            continued_failed_root_reason,
        )
    except ToolUnavailableError as error:
        return _recover_tool_unavailable(store, effects, effects_log, error)
    except DurableWriteError as error:
        return _recover_durable_write_failure(store, effects, effects_log, error)


def _clear_resolved_migration_gate(
    store: RunStore,
    state: RunState,
    reconciliation: LegacyManifestReconciliation | None,
) -> RunState:
    """Clear only the gate whose exact proof has just been resolved."""
    if reconciliation is None:
        return state
    gate_name = reconciliation.gate_name()
    if not any(gate.name == gate_name for gate in state.gates):
        return state
    return store.clear_gate(gate_name)


def _failure_phase(state: RunState, reason: str) -> PhaseValue:
    """Build a failure value in the active FSM domain.

    A run that is already failed stays failed, keeping the reason it failed
    with. The scope reducer has no ``FailureRecorded`` arm out of a terminal
    phase, and a second slice's dispatch park is the same run-level hold as the
    first rather than a second failure: the run holds behind its open gates
    until the operator answers them, so the parked slice and its gate are the
    only new durable facts.
    """
    phase = state.recursive_fsm
    if phase is not None:
        if isinstance(phase, RecursiveTLFailed):
            return TLFailed(phase.reason)
        return scope_transition(phase, ScopeFailureRecorded(reason))
    return TLFailed(reason)


def _recover_durable_write_failure(
    store: RunStore,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    error: DurableWriteError,
) -> TLRunResult:
    """Park the affected slice when lifecycle journaling cannot be trusted."""
    if not isinstance(effects, EffectClient):
        store.record_exit_reason("durable write failed in shadow mode", error=error)
        raise error
    state = store.load()
    slice_state = state.slices.get(error.target or "")
    if slice_state is None:
        slice_state = next(
            (
                candidate
                for candidate in state.slices.values()
                if candidate.status
                not in {
                    SliceStatus.MERGED,
                    SliceStatus.FAILED,
                    SliceStatus.PARKED,
                    SliceStatus.BLOCKED,
                }
            ),
            None,
        )
    if slice_state is None:
        store.record_exit_reason("durable write failed without an active slice", error=error)
        raise error
    park(
        slice_state,
        ParkCause.DURABLE_WRITE_FAILED,
        store=store,
        issue_creator=effects,
        audit={"reason": str(error)},
    )
    state = store.load()
    if state.fsm.phase not in {TLPhase.TLDone, TLPhase.TLFailed}:
        state = store.checkpoint(
            _failure_phase(state, f"durable write failed for {slice_state.id!r}"),
            state.slices,
            state.budgets,
            state.events.last_consumed_offset,
        )
    return TLRunResult(
        state,
        tuple(effects_log),
        (),
        (),
        journal_entries=_journal_entries(effects_log),
    )


def _recover_tool_unavailable(
    store: RunStore,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    error: ToolUnavailableError,
) -> TLRunResult:
    """Park deployment skew instead of terminating the controller."""
    if not isinstance(effects, EffectClient):
        store.record_exit_reason("tool unavailable in shadow mode", error=error)
        raise error
    state = store.load()
    slice_state = state.slices.get(error.target or "")
    if slice_state is None:
        slice_state = next(
            (
                candidate
                for candidate in state.slices.values()
                if candidate.status
                not in {
                    SliceStatus.MERGED,
                    SliceStatus.FAILED,
                    SliceStatus.PARKED,
                    SliceStatus.BLOCKED,
                }
            ),
            None,
        )
    if slice_state is None:
        store.record_exit_reason("tool unavailable without an active slice", error=error)
        raise error
    payload = {
        "slice_id": slice_state.id,
        "tool_name": error.tool_name,
        "role": error.role,
        "wasm_path": error.wasm_path,
        "wasm_mtime": error.wasm_mtime,
        "remediation": error.remediation,
        "message": str(error),
        "error_kind": "tool_unavailable",
    }
    emit_controller_event(effects, "tl.tool_unavailable", payload)
    park(
        slice_state,
        ParkCause.TOOL_UNAVAILABLE,
        store=store,
        issue_creator=effects,
        audit=payload,
    )
    state = store.load()
    if state.fsm.phase not in {TLPhase.TLDone, TLPhase.TLFailed}:
        state = store.checkpoint(
            _failure_phase(state, f"tool unavailable for {slice_state.id!r}"),
            state.slices,
            state.budgets,
            state.events.last_consumed_offset,
        )
    return TLRunResult(
        state,
        tuple(effects_log),
        (),
        (),
        journal_entries=_journal_entries(effects_log),
    )


def _initialize_ordered_runtime(plan: WorkPlan, state: RunState, store: RunStore) -> RunState:
    """Create ordered restart metadata once, without resetting progress."""
    if not plan.sub_tls:
        return state
    stages = tuple(OrderedStageState(stage.order, stage.sub_tls) for stage in plan.ordered_stages)
    if state.ordered_stages:
        if state.ordered_stages != stages:
            raise TLLoopError("persisted ordered stages do not match the normalized plan")
        return state
    integration = IntegrationRuntimeState(
        sub_tl_states={task.name: IntegrationLifecycle.RUNNING for task in plan.sub_tls}
    )
    return store.set_ordered_state(1, stages, integration)


def _canonical_planning_from_manifest(
    manifest: PlanManifest,
    slices: Mapping[str, object],
) -> RecursiveTLPlanning:
    """Build the one canonical planning value from immutable declarations."""
    records = {
        node.node_id: _canonical_child_record(
            node, slices.get(node.name), manifest.manifest_revision
        )
        for node in manifest.nodes
    }
    parallel = tuple(
        records[node.node_id] for node in manifest.nodes if node.kind in {"worker", "leaf"}
    )
    ordered = tuple(
        (order, tuple(records[node_id] for node_id in node_ids))
        for order, node_ids in manifest.ordered_stages
    )
    return RecursiveTLPlanning(
        ordered_children=ordered,
        scope_path=(manifest.scope_id,),
        plan_digest=manifest.digest or "",
        parallel_children=parallel,
    )


def _canonical_child_record(
    node: object,
    slice_value: object,
    manifest_revision: int,
) -> ChildRecord:
    """Bind one runtime child record to its immutable manifest identity."""
    kind = ChildKind(node.kind)
    action = _runtime_field(slice_value, "action")
    intent_id = _runtime_field(action, "intent_id")
    invocation_id = _runtime_field(slice_value, "dispatch_invocation_id")
    evidence = {
        "manifest_node_id": node.node_id,
        "manifest_revision": str(manifest_revision),
    }
    integration = getattr(node, "integration_contract", {})
    aggregate_required = integration.get("aggregate_pr_required", True)
    if (
        kind is ChildKind.SUB_TL
        and aggregate_required is False
        and _runtime_field(slice_value, "status") is SliceStatus.MERGED
    ):
        evidence["aggregate_pr_required"] = "false"
    return ChildRecord(
        child_id=node.name,
        kind=kind,
        dispatch_intent_id=intent_id if isinstance(intent_id, str) else None,
        invocation_id=invocation_id if isinstance(invocation_id, str) else None,
        evidence=evidence,
        manifest_node_id=node.node_id,
        manifest_revision=manifest_revision,
    )


def _runtime_field(value: object, field_name: str) -> object:
    """Read a field from either a decoded state value or an input mapping."""
    if isinstance(value, Mapping):
        return value.get(field_name)
    return getattr(value, field_name, None)


def _ensure_canonical_scope(
    state: RunState,
    manifest: PlanManifest,
    store: RunStore,
) -> RunState:
    """Upgrade only unambiguous legacy planning checkpoints."""
    if state.recursive_fsm is not None:
        return state
    if state.fsm.phase is TLPhase.TLPlanning:
        planning = _canonical_planning_from_manifest(manifest, state.slices)
        return store.checkpoint(
            planning,
            state.slices,
            state.budgets,
            state.events.last_consumed_offset,
            plan_manifest=manifest,
        )
    if state.fsm.phase is TLPhase.TLDone:
        return store.checkpoint(
            RecursiveTLDone(
                scope_path=(manifest.scope_id,),
                plan_digest=manifest.digest or "",
                finalization_evidence={"legacy_terminal": "true"},
            ),
            state.slices,
            state.budgets,
            state.events.last_consumed_offset,
        )
    if state.fsm.phase is TLPhase.TLFailed:
        return store.checkpoint(
            RecursiveTLFailed("legacy failure checkpoint"),
            state.slices,
            state.budgets,
            state.events.last_consumed_offset,
        )
    if state.fsm.phase in {TLPhase.TLWaiting, TLPhase.TLMerging} and not manifest.ordered_stages:
        planning = _canonical_planning_from_manifest(manifest, state.slices)
        active_ids = tuple(state.fsm.waiting)
        declared_ids = tuple(record.child_id for record in planning.parallel_children)
        if set(active_ids) == set(declared_ids) and len(active_ids) == len(declared_ids):
            running = scope_transition(
                planning,
                ScopeStageReleased(
                    order=0,
                    child_ids=declared_ids,
                    scope_path=planning.scope_path,
                ),
            )
            return store.checkpoint(
                running,
                state.slices,
                state.budgets,
                state.events.last_consumed_offset,
            )
    store.set_gate(
        "recursive-fsm-migration: legacy active phase cannot be upgraded without dispatch evidence"
    )
    raise TLLoopError(
        f"legacy active phase {state.fsm.phase.value!r} cannot be resumed safely; "
        "dispatch evidence is ambiguous"
    )


def _release_canonical_scope(state: RunState, store: RunStore) -> RunState:
    """Release the first canonical block exactly once at startup."""
    phase = state.recursive_fsm
    if not isinstance(phase, RecursiveTLPlanning):
        return state
    if phase.ordered_children:
        order, records = phase.ordered_children[0]
    else:
        order, records = 0, phase.parallel_children
    event = ScopeStageReleased(
        order=order,
        child_ids=tuple(record.child_id for record in records),
        scope_path=phase.scope_path,
    )
    try:
        next_phase = scope_transition(phase, event)
    except Exception as error:
        raise TLLoopError(f"canonical scope release failed: {error}") from error
    return store.checkpoint(
        next_phase,
        state.slices,
        state.budgets,
        state.events.last_consumed_offset,
    )


def _is_terminal_phase(phase: object) -> bool:
    """Recognize terminal values from both the canonical and legacy views."""
    return isinstance(
        phase,
        (
            TLDone,
            TLFailed,
            RecursiveTLDone,
            RecursiveTLPRFiled,
            RecursiveTLFailed,
            RecursiveTLParked,
        ),
    )


@dataclass(frozen=True)
class OrderedRecoveryDecision:
    """Proof result for one terminal ordered-child continuation."""

    task_name: str | None
    gate_name: str
    reason: str
    recoverable: bool
    #: The recorded answer for ``gate_name``, or ``None`` when the gate has
    #: never been opened. Only an ``APPROVED`` answer authorizes a recovery the
    #: checkpoint evidence alone cannot prove; ``PENDING`` and ``REJECTED`` both
    #: leave the run gated, and neither is ever re-armed to pending.
    gate_status: GateStatus | None = None
    #: Whether an approved gate, rather than the checkpoint evidence, authorizes
    #: the reopen. An authorized reopen mints a fresh child invocation instead of
    #: reusing the recorded one, because the prior delivery target is gone.
    authorized: bool = False
    #: Whether an approved gate may release *this* failure. True only when the
    #: sole unproven fact is how the child's exit reason is classified, because
    #: every ownership, publication, and effect-reconciliation proof already
    #: holds. An operator may overrule a judgement about a message; no operator
    #: answer can manufacture an ownership binding or un-run an effect that may
    #: already have landed, so the other failures stay gated however they are
    #: answered.
    operator_overridable: bool = False


def _ordered_recovery_gate_name(task_name: str | None) -> str:
    """Build the stable operator gate for an ordered continuation proof."""
    return f"{ORDERED_RECOVERY_GATE_PREFIX}{task_name or 'ambiguous'}"


def _continued_failed_root_reason(state: RunState | None, config: TLLoopConfig) -> str | None:
    """Return the saved root failure only as input to a fresh continue replay."""
    if (
        state is None
        or config.session_mode != "continue"
        or state.plan_manifest is None
        or state.plan_manifest.role != "root"
    ):
        return None
    phase = _phase_from_state(state)
    if isinstance(phase, (TLFailed, RecursiveTLFailed)):
        return phase.reason
    return None


def _ordered_terminal_recovery_decision(
    state: RunState,
    plan: WorkPlan,
    config: TLLoopConfig,
    store: RunStore,
) -> OrderedRecoveryDecision | None:
    """Classify a failed ordered child, then apply the operator's answer.

    The checkpoint proof decides first. An incomplete proof leaves the run gated,
    and the recorded answer for that named gate decides what happens next: an
    approved gate authorizes the reopen when — and only when — the sole unproven
    fact is how the child's exit reason is classified. Ownership, publication,
    merge, and effect-reconciliation proofs are never released by an answer,
    because approving a question is not evidence that a sibling does not exist,
    that an effect did not already land, or that the recorded branch is this
    child's. A pending or rejected answer leaves the run gated. An answer is
    never overwritten and a rejected gate is never re-armed to pending, so a
    repeat `--continue` cannot undo a decision.
    """
    proof = _ordered_recovery_proof(state, plan, config, store)
    if proof is None:
        return None
    gate_status = next(
        (gate.status for gate in state.gates if gate.name == proof.gate_name),
        None,
    )
    if proof.recoverable:
        if gate_status is GateStatus.REJECTED:
            return replace(
                proof,
                recoverable=False,
                reason=f"ordered recovery gate {proof.gate_name!r} was rejected",
                gate_status=gate_status,
            )
        return replace(proof, gate_status=gate_status)
    if gate_status is not GateStatus.APPROVED:
        return replace(proof, gate_status=gate_status)
    if not proof.operator_overridable or proof.task_name is None:
        # An answer to a question about ownership or effects is not a proof of
        # them. Re-decomposing or escalating is the only way past these.
        return replace(proof, gate_status=gate_status)
    return replace(
        proof,
        recoverable=True,
        authorized=True,
        gate_status=gate_status,
        reason=(
            f"operator approved gate {proof.gate_name} for child {proof.task_name!r}: "
            f"{proof.reason}"
        ),
    )


def _ordered_recovery_proof(
    state: RunState,
    plan: WorkPlan,
    config: TLLoopConfig,
    store: RunStore,
) -> OrderedRecoveryDecision | None:
    """Classify a failed ordered child without guessing ownership or effects."""
    failed_phase = state.recursive_fsm
    if not plan.sub_tls or not isinstance(failed_phase, RecursiveTLFailed):
        return None
    tasks_by_name = {task.name: task for task in plan.sub_tls}
    stage = next(
        (stage for stage in plan.ordered_stages if stage.order == state.current_order),
        None,
    )
    if stage is None:
        return OrderedRecoveryDecision(
            None,
            _ordered_recovery_gate_name(None),
            f"ordered recovery cannot identify current order {state.current_order}",
            False,
        )
    failed = [
        task_name
        for task_name in stage.sub_tls
        if state.slices.get(task_name) is not None
        and state.slices[task_name].status is SliceStatus.FAILED
    ]
    if len(failed) != 1:
        return OrderedRecoveryDecision(
            failed[0] if len(failed) == 1 else None,
            _ordered_recovery_gate_name(failed[0] if len(failed) == 1 else None),
            "ordered recovery requires exactly one failed child in the current stage",
            False,
        )
    task_name = failed[0]
    task = tasks_by_name.get(task_name)
    if task is None:
        return OrderedRecoveryDecision(
            task_name,
            _ordered_recovery_gate_name(task_name),
            f"ordered recovery plan is missing failed child {task_name!r}",
            False,
        )
    if any(
        state.slices.get(sibling) is not None
        and state.slices[sibling].status in {SliceStatus.FAILED, SliceStatus.PARKED}
        for sibling in stage.sub_tls
        if sibling != task_name
    ):
        return OrderedRecoveryDecision(
            task_name,
            _ordered_recovery_gate_name(task_name),
            "ordered recovery found another failed or parked sibling",
            False,
        )
    child_store = RunStore(task.name, store.run_dir)
    if not child_store.path.exists():
        return OrderedRecoveryDecision(
            task_name,
            _ordered_recovery_gate_name(task_name),
            "failed child checkpoint is missing",
            False,
        )
    try:
        child_state = child_store.load()
    except (OSError, ValueError) as error:
        return OrderedRecoveryDecision(
            task_name,
            _ordered_recovery_gate_name(task_name),
            f"failed child checkpoint cannot be verified: {error}",
            False,
        )
    proof = _ordered_child_recovery_reason(state, task, child_state, config, store)
    if proof.reason is not None:
        return OrderedRecoveryDecision(
            task_name,
            _ordered_recovery_gate_name(task_name),
            proof.reason,
            False,
            operator_overridable=proof.operator_overridable,
        )
    return OrderedRecoveryDecision(
        task_name,
        _ordered_recovery_gate_name(task_name),
        "durable child startup or transport failure is retryable",
        True,
    )


def _hold_ordered_recovery_gate(
    store: RunStore,
    decision: OrderedRecoveryDecision,
) -> RunState:
    """Keep an unresolved or rejected ordered recovery gated, answering nothing.

    A gate that an operator already answered is the durable record of a
    decision, so it is left exactly as it is: re-arming a rejected gate to
    pending would silently re-ask a question that was already declined, and
    re-arming an approved one would discard the authorization this decision
    just consumed. Only an unrecorded name opens one pending gate.
    """
    if decision.gate_status is not None:
        return store.load()
    return store.set_gate(decision.gate_name, GateStatus.PENDING)


class _ChildRecoveryProof(NamedTuple):
    """Why one failed ordered child is not provably retryable.

    ``reason`` is ``None`` when the checkpoint proves the child retryable, and
    otherwise the fail-closed reason. ``operator_overridable`` is true only when
    the sole unproven fact is the classification of the child's exit reason: at
    that point every ownership, publication, and effect-reconciliation proof has
    already held. It is the one failure an operator answer can release, because
    an operator can judge a message but cannot prove an ownership binding or
    un-run an effect.
    """

    reason: str | None
    operator_overridable: bool


def _ordered_child_recovery_reason(
    parent_state: RunState,
    task: SubTLTask,
    child_state: RunState,
    config: TLLoopConfig,
    store: RunStore,
) -> _ChildRecoveryProof:
    """Return a fail-closed reason when child continuation proof is incomplete."""
    child_store = RunStore(task.name, store.run_dir)
    parent_slice = parent_state.slices.get(task.name)
    if parent_slice is None:
        return _hard_failure(f"parent checkpoint is missing child slice {task.name!r}")
    parent_branch = parent_state.owner_branch or config.branch
    recovery_config = replace(config, branch=parent_branch)
    branch = derive_child_branch(parent_branch, _child_controller_name(task))
    worktree = str(_sub_tl_worktree(recovery_config, store.root_dir, store.run_id, task))
    if parent_slice.branch != branch or parent_slice.worktree != worktree:
        return _hard_failure("parent child branch or worktree does not match the declared owner")
    # Either reconciled boundary proves the child's dispatch of record: the
    # original spawn confirmation, or the replacement invocation an approved
    # recovery minted. Anything else means the dispatch is unresolved or failed,
    # which no operator answer can release.
    if (
        not parent_slice.dispatch_intent_id
        or parent_slice.dispatch_authoritative_event_seq is None
        or parent_slice.dispatch_last_boundary not in RECONCILED_SUB_TL_DISPATCH_BOUNDARIES
    ):
        return _hard_failure("accepted ordered-child dispatch intent is not durably reconciled")
    expected_controller = _child_controller_name(task)
    if parent_slice.dispatch_agent_id != expected_controller:
        return _hard_failure(
            "accepted ordered-child dispatch identity "
            f"{parent_slice.dispatch_agent_id!r} does not match the declared controller "
            f"{expected_controller!r}"
        )
    if parent_slice.pr_number is not None or parent_slice.publication is not None:
        return _hard_failure(
            "parent child has publication evidence requiring integration reconciliation"
        )
    if child_state.run_id != task.name:
        return _hard_failure("child checkpoint run identity does not match the declared child")
    if not isinstance(child_state.recursive_fsm, RecursiveTLFailed):
        return _hard_failure("child checkpoint is not an authoritative recursive failure")
    if child_state.owner_branch != branch or child_state.owner_worktree != worktree:
        return _hard_failure("child checkpoint owner branch or worktree conflicts with the parent")
    if (
        child_state.parent_run_id != parent_state.run_id
        or child_state.parent_branch != parent_branch
    ):
        return _hard_failure(
            "child checkpoint parent ownership does not match the current controller"
        )
    if child_state.plan_manifest is None or parent_state.plan_manifest is None:
        return _hard_failure("matching child plan manifest is missing")
    node = next(
        (
            candidate
            for candidate in parent_state.plan_manifest.nodes
            if candidate.name == task.name
        ),
        None,
    )
    expected_child = (
        parent_state.plan_manifest.child_manifests.get(node.node_id) if node is not None else None
    )
    if expected_child is None or child_state.plan_manifest.digest != expected_child.digest:
        return _hard_failure("child checkpoint plan manifest does not match the parent declaration")
    integration = child_state.integration
    if integration.lifecycle in {
        IntegrationLifecycle.MERGED,
        IntegrationLifecycle.INTEGRATION_VALIDATED,
        IntegrationLifecycle.MERGING,
    }:
        return _hard_failure("child integration has completed or in-flight merge evidence")
    blocked_proof: _BlockedLeafResumeProof | None = None
    if any(item.status is SliceStatus.BLOCKED for item in child_state.slices.values()):
        child_config = _ordered_child_config(config, task, branch, worktree, parent_branch)
        blocked_proof, blocked_reason = _blocked_leaf_resume_proof(
            task.plan, child_state, child_config, child_store
        )
        if blocked_proof is None:
            return _hard_failure(
                blocked_reason or "child has a blocked slice without a unique approved resume proof"
            )
    diagnostic = child_store.exit_diagnostics()
    rejection = _proven_preexecution_dispatch_rejection(child_state, child_store)
    if isinstance(diagnostic, Mapping):
        binding_error = _ordered_exit_diagnostic_binding_error(diagnostic, child_state)
        if binding_error is not None:
            return _hard_failure(binding_error)
    elif rejection is None and blocked_proof is None:
        return _hard_failure(
            "durable child exit diagnostic is missing and checkpoint/journal do not prove "
            "a pre-execution dispatch refusal"
        )
    exit_reason = diagnostic.get("reason") if isinstance(diagnostic, Mapping) else None
    if (
        rejection is None
        and blocked_proof is None
        and (not isinstance(exit_reason, str) or not exit_reason)
    ):
        return _hard_failure("durable child exit diagnostic has no failure reason")
    if (
        rejection is None
        and blocked_proof is None
        and not _retryable_ordered_exit_reason(cast(str, exit_reason))
    ):
        # Every ownership, publication, and effect proof above already holds, so
        # the only thing left unproven is how this message is classified. That
        # judgement is exactly what an operator is being asked to make.
        return _ChildRecoveryProof(
            f"child exit is not a retryable startup, transport, or process failure: {exit_reason}",
            True,
        )
    for slice_state in child_state.slices.values():
        if slice_state.status in {
            SliceStatus.FAILED,
            SliceStatus.PARKED,
            SliceStatus.BLOCKED,
        } and not (
            blocked_proof is not None
            and slice_state.id == blocked_proof.leaf.name
            and slice_state.status is SliceStatus.BLOCKED
        ):
            return _hard_failure(f"child slice {slice_state.id!r} has an unsafe terminal status")
        if slice_state.status is SliceStatus.MERGED:
            return _hard_failure(f"child slice {slice_state.id!r} already completed")
        if slice_state.action is not None and slice_state.action.phase in {
            ActionPhase.INTENDED,
            ActionPhase.IN_FLIGHT,
            ActionPhase.UNKNOWN,
        }:
            return _hard_failure(
                f"child slice {slice_state.id!r} has an unresolved action boundary"
            )
        if slice_state.status in {
            SliceStatus.SPAWNED,
            SliceStatus.DISPATCH_UNCONFIRMED,
            SliceStatus.IN_REVIEW,
            SliceStatus.REPAIRING,
        } and (
            not slice_state.dispatch_intent_id
            or not slice_state.dispatch_agent_id
            or slice_state.dispatch_authoritative_event_seq is None
        ):
            return _hard_failure(f"child slice {slice_state.id!r} lacks accepted dispatch evidence")
    journal_path = child_store.run_dir / "action-journal.json"
    try:
        pending = EffectJournal(task.name, journal_path).pending_entries()
    except ActionJournalError as error:
        return _hard_failure(f"child action journal cannot be verified: {error}")
    if pending and not _pending_blocked_resume_is_proven(pending, blocked_proof):
        return _hard_failure("child action journal contains an unreconciled effect")
    return _ChildRecoveryProof(None, False)


def _ordered_child_config(
    config: TLLoopConfig,
    task: SubTLTask,
    branch: str,
    worktree: str,
    parent_branch: str,
) -> TLLoopConfig:
    return replace(
        config,
        run_id=task.name,
        branch=branch,
        worktree=worktree,
        parent_run_id=config.run_id,
        parent_branch=parent_branch,
        parent_agent_id=_child_controller_name(task),
        depth=config.depth + 1,
        ordered_recovery=True,
    )


def _pending_blocked_resume_is_proven(
    pending: Sequence[Mapping[str, object]],
    proof: _BlockedLeafResumeProof | None,
) -> bool:
    if proof is None or len(pending) != 1:
        return False
    entry = pending[0]
    arguments = entry.get("arguments")
    return (
        entry.get("operation") == "resume_blocked_leaf"
        and entry.get("target") == proof.leaf.name
        and isinstance(arguments, Mapping)
        and arguments.get("dispatch_intent_id") == proof.intent_id
        and arguments.get("expected_invocation_id") == proof.owner.prior_invocation_id
    )


class _PreExecutionDispatchRejection(NamedTuple):
    """One scoped spawn refusal proven to have happened before worker creation."""

    slice_id: str
    intent_id: str
    gate_name: str
    response_format: str


def _proven_preexecution_dispatch_rejection(
    child_state: RunState,
    child_store: RunStore,
) -> _PreExecutionDispatchRejection | None:
    """Recognize only a correlated dirty-worktree refusal with no launched leaf."""
    failed = [
        item
        for item in child_state.slices.values()
        if item.status is SliceStatus.DISPATCH_FAILED
        and item.park_cause is ParkCause.DISPATCH_FAILED
    ]
    if len(failed) != 1:
        return None
    slice_state = failed[0]
    if not _dispatch_rejection_has_no_active_sibling(child_state, slice_state.id):
        return None
    if not _dispatch_rejection_checkpoint_is_preexecution(slice_state):
        return None
    entry = _rejected_spawn_journal_entry(
        child_store, slice_state.id, slice_state.dispatch_intent_id
    )
    response_format = (
        _journal_result_dirty_preflight_format(entry, slice_state) if entry is not None else None
    )
    if response_format is None:
        return None
    gate_name = _dispatch_failure_gate_name(slice_state.id, slice_state.dispatch_error_code)
    gate = next((item for item in child_state.gates if item.name == gate_name), None)
    if gate is not None and gate.status is GateStatus.REJECTED:
        return None
    return _PreExecutionDispatchRejection(
        slice_state.id,
        cast(str, slice_state.dispatch_intent_id),
        gate_name,
        response_format,
    )


def _dispatch_rejection_has_no_active_sibling(state: RunState, failed_id: str) -> bool:
    active = {
        SliceStatus.SPAWNED,
        SliceStatus.DISPATCHING,
        SliceStatus.DISPATCH_UNCONFIRMED,
        SliceStatus.DISPATCH_RETRY_SCHEDULED,
        SliceStatus.IN_REVIEW,
        SliceStatus.REPAIRING,
    }
    return all(
        item.id == failed_id or (item.status not in active and item.action is None)
        for item in state.slices.values()
    )


def _dispatch_rejection_checkpoint_is_preexecution(slice_state: SliceState) -> bool:
    return (
        slice_state.attempts > 0
        and slice_state.action is None
        and slice_state.dispatch_last_boundary == "spawn_request_failed"
        and slice_state.dispatch_error_code
        in {"agent_error", "agent.spawn_precondition.dirty_worktree"}
        and bool(slice_state.dispatch_intent_id)
        and slice_state.dispatch_started_at is not None
        and slice_state.dispatch_agent_id is None
        and slice_state.dispatch_invocation_id is None
        and slice_state.dispatch_authoritative_event_seq is None
        and slice_state.pr_number is None
        and slice_state.publication is None
    )


def _rejected_spawn_journal_entry(
    store: RunStore,
    slice_id: str,
    intent_id: str | None,
) -> Mapping[str, object] | None:
    if not intent_id:
        return None
    try:
        entries = EffectJournal(store.run_id, store.run_dir / "action-journal.json").entries_for(
            "spawn_leaf", slice_id
        )
    except ActionJournalError:
        return None
    matching = [
        entry
        for entry in entries
        if entry.get("status") == "rejected"
        and isinstance(entry.get("arguments"), Mapping)
        and entry["arguments"].get("name") == slice_id
        and entry["arguments"].get("intent_id") == intent_id
    ]
    return matching[0] if len(matching) == 1 else None


def _journal_result_dirty_preflight_format(
    entry: Mapping[str, object],
    slice_state: SliceState,
) -> str | None:
    result = entry.get("result")
    if not isinstance(result, Mapping) or result.get("success") is not False:
        return None
    error = result.get("error")
    if not isinstance(error, str) or error != slice_state.dispatch_error:
        return None
    code = slice_state.dispatch_error_code
    kind = result.get("error_kind")
    if code == "agent.spawn_precondition.dirty_worktree":
        return "structured_dirty_precondition" if kind == code else None
    if code != "agent_error":
        return None
    if kind == "agent_error" and _wrapped_legacy_dirty_preflight(error):
        return "wrapped_legacy_agent_error"
    if (
        kind is None
        and {"success", "result", "error", "error_kind", "error_context"}.issubset(result)
        and result.get("result") is None
        and result.get("error_context") is None
        and _raw_legacy_dirty_preflight(error)
    ):
        return "raw_legacy_null_error_kind"
    return None


def _raw_legacy_dirty_preflight(error: str) -> bool:
    """Match the historical service envelope without accepting arbitrary prose."""
    prefix = "BLOCKED: cannot spawn agent into a dirty TL worktree. "
    if not error.startswith(prefix):
        return False
    lines = error[len(prefix) :].splitlines()
    if not lines:
        return False
    count_prefix = "file(s) have uncommitted changes:"
    count_text, separator, first_path = lines[0].partition(count_prefix)
    if not separator or not count_text.endswith(" "):
        return False
    try:
        expected_paths = int(count_text.strip())
    except ValueError:
        return False
    if expected_paths <= 0 or first_path.strip():
        return False
    recovery = (
        "Commit the scaffold (per scaffold-fork-converge) or run `discard_worker_output` "
        "if throwaway, then retry. Workers spawn in-place and would inherit this state; "
        "dev-leaves fork from your branch HEAD and would not see your uncommitted work."
    )
    try:
        recovery_index = lines.index(recovery)
    except ValueError:
        return False
    paths = lines[1:recovery_index]
    return (
        len(paths) == expected_paths
        and all(path.startswith("  ") and path[2:].strip() for path in paths)
        and lines[recovery_index + 1 :] == []
    )


def _wrapped_legacy_dirty_preflight(error: str) -> bool:
    """Match the historical TL preflight wrapper and its structured file report."""
    headers = (
        "TL preflight failed; spawning is blocked until the worktree is clean. ",
        (
            "TL preflight failed; spawning is blocked until the worktree is clean or the user "
            "acknowledges with EXOMONAD_TL_PREFLIGHT_ACK=1.\n"
        ),
    )
    body = next((error[len(header) :] for header in headers if error.startswith(header)), None)
    if body is None:
        return False
    if body.startswith("BLOCKED: cannot spawn agent into a dirty TL worktree. "):
        return _raw_legacy_dirty_preflight(body)
    lines = body.splitlines()
    return (
        len(lines) >= 3
        and lines[0] == "worktree check failed: uncommitted or untracked files are present"
        and _wrapped_dirty_path_rows(lines[1:-1])
        and _wrapped_runtime_exclusions_footer(lines[-1])
    )


def _wrapped_dirty_path_rows(rows: list[str]) -> bool:
    overflow = [index for index, row in enumerate(rows) if row.startswith("  - ... and ")]
    if overflow and (overflow != [10] or len(rows) != 11):
        return False
    if not overflow and not 1 <= len(rows) <= 10:
        return False
    for row in rows[:10]:
        if not row.startswith("  - ") or not row[4:].strip():
            return False
    return not overflow or _wrapped_overflow_row_is_valid(rows[10])


def _wrapped_overflow_row_is_valid(row: str) -> bool:
    prefix = "  - ... and "
    suffix = " more"
    if not row.startswith(prefix) or not row.endswith(suffix):
        return False
    count = row[len(prefix) : -len(suffix)]
    return bool(count) and count.isascii() and count.isdigit() and count[0] != "0"


def _wrapped_runtime_exclusions_footer(line: str) -> bool:
    prefix = "TL preflight runtime exclusions (built-in plus configured): "
    if not line.startswith(prefix):
        return False
    paths = line[len(prefix) :].split(", ")
    return bool(paths) and all(_wrapped_runtime_path_is_valid(path) for path in paths)


def _wrapped_runtime_path_is_valid(path: str) -> bool:
    if not path or not path.endswith("/") or path.startswith("/"):
        return False
    return all(part not in {"", ".."} for part in path[:-1].split("/"))


def _hard_failure(reason: str) -> _ChildRecoveryProof:
    """One fail-closed reason no operator answer may release."""
    return _ChildRecoveryProof(reason, False)


def _ordered_exit_diagnostic_binding_error(
    diagnostic: Mapping[str, object] | None,
    child_state: RunState,
) -> str | None:
    """Fail closed when a diagnostic marker predates or contradicts the checkpoint.

    ``controller-exit.json`` is written as a diagnostic side file, so it is not
    itself authoritative. Recovery may only trust it when it was recorded
    against the exact child checkpoint being considered: a stale marker from an
    older transient failure must never reopen a newer nonretryable failure.
    """
    if not isinstance(diagnostic, Mapping):
        return "durable child exit diagnostic is missing"
    bound_revision = diagnostic.get("checkpoint_revision")
    if type(bound_revision) is not int or bound_revision != child_state.revision:
        return "durable child exit diagnostic is not bound to the current child checkpoint revision"
    if not isinstance(child_state.recursive_fsm, RecursiveTLFailed):
        return "child checkpoint is not an authoritative recursive failure"
    bound_reason = diagnostic.get("checkpoint_failure_reason")
    if not isinstance(bound_reason, str) or bound_reason != child_state.recursive_fsm.reason:
        return "durable child exit diagnostic does not match the child checkpoint failure reason"
    scope_bindings = {
        "scope_run_id": child_state.run_id,
        "scope_parent_run_id": child_state.parent_run_id,
        "scope_branch": child_state.owner_branch,
        "controller_epoch": child_state.controller_epoch,
        "plan_manifest_digest": (
            child_state.plan_manifest.digest if child_state.plan_manifest is not None else None
        ),
    }
    for field_name, expected in scope_bindings.items():
        if field_name in diagnostic and diagnostic.get(field_name) != expected:
            return f"durable child exit diagnostic conflicts with checkpoint {field_name}"
    failure_bindings = diagnostic.get("dispatch_failures")
    if failure_bindings is not None:
        expected_failures = _dispatch_failure_diagnostic_bindings(child_state)
        if failure_bindings != expected_failures:
            return "durable child exit diagnostic conflicts with the current dispatch attempt"
    outcome = diagnostic.get("outcome")
    if outcome is not None and outcome not in {
        "controller_exit",
        "exception",
        "process_exit",
        "cancelled",
        "normal_return",
        "supervisor_observed_failure",
    }:
        return "durable child exit diagnostic has an unknown outcome classification"
    return None


def _dispatch_failure_diagnostic_bindings(state: RunState) -> list[dict[str, object]]:
    """Rebuild the minimal dispatch identity embedded in a diagnostic sidecar."""
    return [
        {
            "slice_id": item.id,
            "dispatch_intent_id": item.dispatch_intent_id,
            "dispatch_agent_id": item.dispatch_agent_id,
            "dispatch_invocation_id": item.dispatch_invocation_id,
            "dispatch_authoritative_event_seq": item.dispatch_authoritative_event_seq,
            "dispatch_generation": item.dispatch_generation,
            "attempt": item.attempts,
            "dispatch_error_code": item.dispatch_error_code,
            "dispatch_last_boundary": item.dispatch_last_boundary,
        }
        for item in state.slices.values()
        if item.status is SliceStatus.DISPATCH_FAILED
    ]


def _retryable_ordered_exit_reason(reason: str) -> bool:
    """Recognize only transient controller-boundary failures for retry."""
    lowered = reason.lower()
    if any(
        marker in lowered
        for marker in (
            "identity conflict",
            "conflicts with existing ownership",
            "ownership conflict",
            "already exists",
            "already-owned",
            "without matching durable identity",
            "identity or workspace",
            "http 400",
            "http 401",
            "http 403",
            "http 404",
            "http 409",
            "status 409",
            " 409",
            "plan manifest",
            "depth ceiling",
            "cancelled explicitly",
            "publication ownership",
            "merge",
            "review",
        )
    ):
        return False
    return any(
        marker in lowered
        for marker in (
            "controller exited before authoritative resolution",
            "controller exited",
            "transport",
            "server returned http 429",
            "server returned http 500",
            "server returned http 502",
            "server returned http 503",
            "server returned http 504",
            "server socket",
            "server timeout",
            "connection",
            "timed out",
            "broken pipe",
            "eof",
            "missing request extension",
        )
    )


def _ordered_child_invocation_is_gone(store: RunStore, task_name: str) -> bool:
    """Whether the recorded child controller invocation provably no longer exists.

    A child controller that exited before authoritative resolution persisted its
    own recursive failure checkpoint and an exit diagnostic bound to that exact
    checkpoint revision. That diagnostic is the only durable proof available
    that the prior invocation — and therefore its delivery target — is gone,
    so it is what authorizes minting a replacement instead of reusing the
    recorded identity.
    """
    child_store = RunStore(task_name, store.run_dir)
    if not child_store.path.exists():
        return False
    try:
        child_state = child_store.load()
    except (OSError, ValueError):
        return False
    if (
        _ordered_exit_diagnostic_binding_error(
            child_store.exit_diagnostics(),
            child_state,
        )
        is not None
    ):
        return False
    return isinstance(child_state.recursive_fsm, RecursiveTLFailed)


def _mint_ordered_child_invocation(
    target: SliceState,
    state: RunState,
    store: RunStore,
    target_name: str,
    agent_id: str,
) -> SliceState:
    """Replace one ordered child's exited invocation with a fresh, valid identity.

    An approved recovery of a child whose controller already exited must not
    deliver to the pane that exited: the relaunch reuses the same agent name,
    branch, worktree, and dispatch intent, so without a new invocation the
    server would resolve the dead one. The replacement is deterministic in the
    child's own exit diagnostic, which is what makes a repeated `--continue`
    idempotent instead of minting a second identity per attempt.

    The relaunched slice stays at a reconciled dispatch boundary, so a child that
    fails again after this recovery is still provable. A boundary outside
    ``RECONCILED_SUB_TL_DISPATCH_BOUNDARIES`` would be read as an unresolved
    dispatch by the next continuation proof, which would make a second failure of
    the same child permanently unrecoverable and would report it as a dispatch
    reconciliation fault rather than the exit that actually caused it.

    Publication ownership is untouched: the child's recorded PR, head, and
    publication binding survive, so nothing here can hand the child's work to
    another owner or re-publish it.
    """
    diagnostic = RunStore(target_name, store.run_dir).exit_diagnostics()
    revision = diagnostic.get("checkpoint_revision") if isinstance(diagnostic, Mapping) else None
    seed = f"{state.run_id}:{target_name}:ordered-recovery:{revision}"
    intent_id = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:32]
    if target.dispatch_intent_id == intent_id:
        # This exact exit already authorized this exact invocation. Re-minting
        # would let a repeated `--continue` walk the dispatch generation forward
        # without any new child ever running.
        return target
    generation = target.dispatch_generation + 1
    # The authoritative boundary moves forward to the position this recovery was
    # decided at, and never backward: a stale-boundary marker would let a
    # confirmation from the previous invocation satisfy this one.
    authoritative_seq = max(
        target.dispatch_authoritative_event_seq or 0,
        state.events.last_consumed_offset,
    )
    return replace(
        target,
        dispatch_intent_id=intent_id,
        dispatch_invocation_id=intent_id,
        dispatch_generation=generation,
        dispatch_authoritative_event_seq=authoritative_seq,
        dispatch_last_boundary=SUB_TL_DISPATCH_RECOVERED_BOUNDARY,
        dispatch_error=None,
        dispatch_error_code=None,
        recovery=_ordered_child_recovery_state(
            state,
            target_name,
            intent_id,
            agent_id,
            generation,
        ),
    )


def _ordered_child_recovery_state(
    state: RunState,
    target_name: str,
    intent_id: str,
    agent_id: str,
    generation: int,
) -> RecoveryState:
    """Record the approved recovery that produced one fresh child invocation."""
    return begin_recovery(
        cause="ordered_child_pane_exited",
        owner_run_id=state.run_id,
        slice_attempt=1,
        owner_agent_id=agent_id,
        invocation_generation=generation,
        evidence={
            "invocation_id": intent_id,
            "slice_id": target_name,
            "authorization_source": "human",
            "reopened_from": "ordered_child_recovery",
        },
        next_action="resume_same_owner",
    )


def _reopen_ordered_scope(
    state: RunState,
    plan: WorkPlan,
    store: RunStore,
    target_name: str | None,
    *,
    authorized: bool = False,
    expected_revision: int | None = None,
    retry_dispatch_slice: str | None = None,
) -> RunState:
    """Reopen one proven ordered scope while retaining all durable identities.

    ``authorized`` marks an operator-approved recovery, where the prior child
    controller invocation is provably gone. That child is relaunched with a
    fresh invocation identity and dispatch generation so guidance lands on a live
    delivery target instead of the exited pane, while its branch, worktree,
    publication ownership, and dispatch intent are all preserved: the child is
    reopened, never duplicated.
    """
    if state.plan_manifest is None:
        raise TLLoopError("ordered recovery checkpoint has no plan manifest")
    planning = _canonical_planning_from_manifest(state.plan_manifest, state.slices)
    tasks_by_name = {task.name: task for task in plan.sub_tls}
    records = [*planning.parallel_children]
    records.extend(record for _, group in planning.ordered_children for record in group)
    completed: dict[str, ChildRecord] = {}
    parallel_pending: list[ChildRecord] = []
    pending_by_order: dict[int, tuple[ChildRecord, ...]] = {}
    post_merge: dict[str, PostMergeState] = {}
    for record in records:
        current = state.slices.get(record.child_id)
        if current is None:
            raise TLLoopError(f"ordered recovery slice {record.child_id!r} is missing")
        task = tasks_by_name.get(record.child_id)
        complete = (
            _ordered_child_complete(task, current)
            if task is not None
            else _ordered_slice_complete(current)
        )
        if complete:
            completed[record.child_id] = record
            if record.kind is ChildKind.SUB_TL:
                post_merge[record.child_id] = _ordered_sub_tl_completion_state(
                    state,
                    record,
                    task,
                    current,
                    store,
                )
            elif record.kind is ChildKind.WORKER:
                post_merge[record.child_id] = _ordered_worker_completion_state(record, current)
            else:
                post_merge[record.child_id] = _ordered_leaf_completion_state(record, current)
        elif record.kind is ChildKind.SUB_TL and current.status is SliceStatus.MERGED:
            raise OrderedCompletionEvidenceError(
                record.child_id,
                "merged declaration lacks its required completion proof; "
                "recovery will not reopen the completed producer",
            )
        elif record.kind is ChildKind.SUB_TL:
            for order, group in planning.ordered_children:
                if record in group:
                    pending_by_order.setdefault(order, ())
                    pending_by_order[order] = (*pending_by_order[order], record)
                    break
        else:
            parallel_pending.append(record)
    if parallel_pending:
        current_order = 0
    elif pending_by_order:
        current_order = min(pending_by_order)
    else:
        complete = RecursiveTLAllMerged(
            scope_path=planning.scope_path,
            plan_digest=planning.plan_digest,
            completed_children=post_merge,
        )
        return store.checkpoint(
            complete,
            state.slices,
            state.budgets,
            state.events.last_consumed_offset,
            current_order=max(1, state.current_order),
            ordered_stages=state.ordered_stages,
            integration=state.integration,
            expected_revision=expected_revision,
        )
    slices = dict(state.slices)
    clear_gates: set[str] = set()
    rejection_format: str | None = None
    if target_name is not None:
        target = slices[target_name]
        reopened = replace(
            slice_transition(target, SliceStatusChanged(SliceStatus.SPAWNED)),
            park_cause=None,
            dispatch_error=None,
        )
        if authorized and _ordered_child_invocation_is_gone(store, target_name):
            task = tasks_by_name.get(target_name)
            reopened = _mint_ordered_child_invocation(
                reopened,
                state,
                store,
                target_name,
                _child_controller_name(task) if task is not None else target_name,
            )
        slices[target_name] = reopened
        recovery_gate = _ordered_recovery_gate_name(target_name)
        if any(
            gate.name == recovery_gate and gate.status is GateStatus.PENDING for gate in state.gates
        ):
            clear_gates.add(recovery_gate)
        for order, records_at_order in pending_by_order.items():
            pending_by_order[order] = tuple(
                replace(
                    record,
                    dispatch_intent_id=reopened.dispatch_intent_id,
                    invocation_id=reopened.dispatch_invocation_id,
                )
                if record.child_id == target_name
                else record
                for record in records_at_order
            )
    dispatch_intents = {
        record.child_id: record.dispatch_intent_id
        for record in records
        if record.dispatch_intent_id is not None
    }
    if target_name is not None:
        target_intent = slices[target_name].dispatch_intent_id
        if target_intent is None:
            dispatch_intents.pop(target_name, None)
        else:
            dispatch_intents[target_name] = target_intent
    if retry_dispatch_slice is not None:
        rejected = slices.get(retry_dispatch_slice)
        if rejected is None or rejected.status is not SliceStatus.DISPATCH_FAILED:
            raise TLLoopError(
                f"ordered retry slice {retry_dispatch_slice!r} is not a failed dispatch"
            )
        rejection = _proven_preexecution_dispatch_rejection(state, store)
        if rejection is None or rejection.slice_id != retry_dispatch_slice:
            raise TLLoopError(
                f"ordered retry slice {retry_dispatch_slice!r} no longer has proven "
                "pre-execution refusal evidence"
            )
        rejection_format = rejection.response_format
        slices[retry_dispatch_slice] = replace(
            slice_transition(rejected, SliceStatusChanged(SliceStatus.PENDING)),
            park_cause=None,
            dispatch_last_boundary="preexecution_retry_authorized",
            dispatch_uses_current_role_configuration=True,
        )
        if any(
            gate.name == rejection.gate_name and gate.status is GateStatus.PENDING
            for gate in state.gates
        ):
            clear_gates.add(rejection.gate_name)
        dispatch_intents.pop(retry_dispatch_slice, None)
    running = RecursiveTLRunning(
        current_order=current_order,
        pending_by_order=pending_by_order,
        scope_path=planning.scope_path,
        plan_digest=planning.plan_digest,
        parallel_pending=tuple(parallel_pending),
        completed_children=completed,
        post_merge=post_merge,
        dispatch_intents=dispatch_intents,
        lane_bindings={
            record.child_id: record.lane_id for record in records if record.lane_id is not None
        },
        evidence={
            "ordered_recovery_child": target_name or "scope",
            **(
                {"preexecution_dispatch_refusal_format": rejection_format}
                if rejection_format is not None
                else {}
            ),
        },
    )
    sub_tl_states = dict(state.integration.sub_tl_states)
    if target_name is not None:
        sub_tl_states[target_name] = IntegrationLifecycle.RUNNING
    integration = replace(
        state.integration,
        sub_tl_states=sub_tl_states,
        sub_tl_recovery={
            name: summary
            for name, summary in state.integration.sub_tl_recovery.items()
            if name != target_name or target_name is None
        },
    )
    return store.checkpoint(
        running,
        slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=max(1, current_order),
        ordered_stages=state.ordered_stages,
        integration=integration,
        expected_revision=expected_revision,
        clear_gates=tuple(sorted(clear_gates)),
    )


def _ordered_sub_tl_completion_state(
    state: RunState,
    record: ChildRecord,
    task: SubTLTask | None,
    current: SliceState,
    store: RunStore,
) -> PostMergeState:
    """Retain verified completion evidence for one declared ordered subTL."""
    if task is None or task.name != record.child_id:
        raise OrderedCompletionEvidenceError(record.child_id, "no matching accepted declaration")
    node = next((node for node in state.plan_manifest.nodes if node.name == task.name), None)
    if node is None or record.manifest_node_id != node.node_id:
        raise OrderedCompletionEvidenceError(
            task.name, "manifest binding is missing or conflicting"
        )
    declared_required = node.integration_contract.get("aggregate_pr_required", True)
    if declared_required is not task.integration.aggregate_pr_required:
        raise OrderedCompletionEvidenceError(
            task.name, "aggregate requirement conflicts with its manifest"
        )
    receipt = current.post_merge
    if receipt is None and not declared_required and current.pr_number is None:
        return PostMergeState(
            PostMergePhase.NOT_REQUIRED,
            {"child_id": task.name, "aggregate_pr_required": "false"},
        )
    if receipt is None:
        raise OrderedCompletionEvidenceError(task.name, "complete without its post-merge receipt")
    try:
        validated = PostMergeState(receipt.phase, dict(receipt.evidence))
    except (TypeError, ValueError) as error:
        raise OrderedCompletionEvidenceError(
            task.name, f"invalid post-merge evidence: {error}"
        ) from error
    if validated.phase is PostMergePhase.NOT_REQUIRED and not declared_required:
        if current.pr_number is not None:
            raise OrderedCompletionEvidenceError(
                task.name, "has a PR but no required post-merge proof"
            )
        return PostMergeState(
            PostMergePhase.NOT_REQUIRED,
            {**receipt.evidence, "child_id": task.name, "aggregate_pr_required": "false"},
        )
    if validated.phase is not PostMergePhase.COMPLETE:
        raise OrderedCompletionEvidenceError(
            task.name,
            f"requires COMPLETE post-merge evidence; found {validated.phase.value}",
        )
    reason = _ordered_sub_tl_complete_receipt_error(state, task, current, store)
    if reason is not None:
        raise OrderedCompletionEvidenceError(task.name, f"completion proof is unresolved: {reason}")
    return receipt


def _ordered_worker_completion_state(
    record: ChildRecord,
    current: SliceState,
) -> PostMergeState:
    """Retain worker result evidence or project its already-completed result."""
    receipt = current.post_merge
    if (
        receipt is not None
        and receipt.phase is PostMergePhase.NOT_REQUIRED
        and receipt.evidence.get("worker_result")
    ):
        return receipt
    return PostMergeState(
        PostMergePhase.NOT_REQUIRED,
        {"worker_result": f"recovered:{record.child_id}"},
    )


def _ordered_leaf_completion_state(
    record: ChildRecord,
    current: SliceState,
) -> PostMergeState:
    """Validate and retain a durable completion receipt for one accepted leaf."""
    receipt = current.post_merge
    if receipt is None:
        raise OrderedCompletionEvidenceError(record.child_id, "completed leaf receipt is missing")
    try:
        PostMergeState(receipt.phase, dict(receipt.evidence))
    except (TypeError, ValueError) as error:
        raise OrderedCompletionEvidenceError(
            record.child_id, f"completed leaf receipt is invalid: {error}"
        ) from error
    if receipt.phase is PostMergePhase.NOT_REQUIRED:
        leaf_result = receipt.evidence.get("leaf_result")
        if not isinstance(leaf_result, str) or not leaf_result.strip():
            raise OrderedCompletionEvidenceError(
                record.child_id, "NOT_REQUIRED completed leaf receipt is missing leaf_result"
            )
    if receipt.evidence.get("child_id") not in (None, record.child_id):
        raise OrderedCompletionEvidenceError(
            record.child_id, "completed leaf receipt child_id conflicts with its declaration"
        )
    if receipt.phase not in {PostMergePhase.COMPLETE, PostMergePhase.NOT_REQUIRED}:
        raise OrderedCompletionEvidenceError(
            record.child_id,
            f"completed leaf receipt has unsupported phase {receipt.phase.value}",
        )
    return receipt


def _ordered_sub_tl_complete_receipt_error(
    state: RunState,
    task: SubTLTask,
    current: SliceState,
    store: RunStore,
) -> str | None:
    """Match a retained COMPLETE receipt to its accepted aggregate and journal."""
    receipt = current.post_merge
    publication = current.publication
    candidate = state.integration.candidates.get(task.name)
    reconciliation = current.reconciliation
    if receipt is None or publication is None or candidate is None:
        return "aggregate publication or candidate identity is missing"
    if state.repository_identity is None or not isinstance(reconciliation, Mapping):
        return "repository identity or merge reconciliation is missing"
    evidence = receipt.evidence
    base_sha = candidate.aggregate_original_base_sha
    repository_match = _completed_repository_evidence_match_kind(evidence.get("repository"), state)
    conflicts = _ordered_sub_tl_completion_coordinate_conflicts(
        task, current, evidence, publication, candidate, reconciliation, base_sha, repository_match
    )
    if conflicts:
        return "receipt coordinates conflict with the accepted declaration: " + ", ".join(conflicts)
    if candidate.lifecycle is not IntegrationLifecycle.MERGED:
        return "aggregate candidate is not authoritatively merged"
    missing: list[str] = []
    _validate_completed_issue_closure(current, evidence, missing, store)
    if evidence.get("issue_close_outcome") == "not_applicable":
        changelog_error = _unlinked_changelog_outcome_error(
            evidence.get("changelog_outcome", ""),
            evidence.get("changelog_commit_sha", ""),
            evidence.get("observed_remote_head", ""),
        )
        if changelog_error is not None:
            missing.append(changelog_error)
    else:
        _validate_completed_push_receipt(current, evidence, missing)
    if missing:
        return "post-merge completion evidence conflicts: " + ", ".join(sorted(set(missing)))
    journal = EffectJournal(store.run_id, store.run_dir / "action-journal.json")
    return _aggregate_completion_sync_error(state, current, current.pr_number, candidate, journal)


def _ordered_sub_tl_completion_coordinate_conflicts(
    task: SubTLTask,
    current: SliceState,
    evidence: Mapping[str, str],
    publication: PublicationBinding,
    candidate: IntegrationCandidateState,
    reconciliation: Mapping[str, object],
    base_sha: str | None,
    repository_match: str | None,
) -> tuple[str, ...]:
    """Name each accepted aggregate coordinate that conflicts with its receipt."""
    checks = (
        ("child_id", evidence.get("child_id") == task.name),
        ("repository", repository_match is not None),
        ("parent_branch", evidence.get("parent_branch") == current.base_ref),
        ("publication_base_branch", publication.base_branch == current.base_ref),
        ("publication_head_branch", publication.head_branch == current.branch),
        ("publication_pr_number", publication.pr_number == current.pr_number),
        ("slice_pr_number", type(current.pr_number) is int),
        ("receipt_pr_number", evidence.get("pr_number") == str(current.pr_number)),
        ("candidate_pr_number", candidate.aggregate_pr_number == current.pr_number),
        ("publication_head_sha", evidence.get("head_sha") == publication.head_sha),
        ("candidate_head_sha", candidate.aggregate_head_sha == publication.head_sha),
        ("candidate_owner_run_id", candidate.integration_owner_run_id == task.name),
        ("candidate_owner_branch", candidate.integration_owner_branch == current.branch),
        ("aggregate_base_sha", bool(base_sha)),
        ("merge_base_sha", reconciliation.get("merge_base_sha") == base_sha),
        ("merge_head_sha", reconciliation.get("merge_head_sha") == publication.head_sha),
        (
            "merge_journal_id",
            reconciliation.get("merge_journal_id") == evidence.get("merge_journal_id"),
        ),
    )
    return tuple(name for name, matches in checks if not matches)


def _checkpoint_scope_phase(
    phase: PhaseValue,
    state: RunState,
    store: RunStore,
) -> RunState:
    """Persist one canonical scope transition with exactly one version step."""
    return store.checkpoint(
        phase,
        state.slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=state.integration,
        state_version=state.state_version + 1,
    )


def _maybe_finalize_root_scope(
    state: RunState,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Fast-forward the root branch before durably completing finalization."""
    phase = state.recursive_fsm
    manifest = state.plan_manifest
    if manifest is None or manifest.role != "root":
        return state
    if _scope_has_pending_post_merge(state):
        return state
    if not isinstance(phase, (RecursiveTLAllMerged, RecursiveTLFinalizing)):
        return state
    evidence = {
        "root_branch": state.owner_branch or manifest.owned_branch,
        "local_checkout": state.owner_worktree or manifest.owned_branch,
    }
    if isinstance(phase, RecursiveTLAllMerged):
        finalizing = scope_transition(phase, ScopeFinalizationRequested(ScopeRole.ROOT))
        finalizing = replace(finalizing, evidence=evidence)
        state = _checkpoint_scope_phase(finalizing, state, store)
    else:
        finalizing = phase
        if not finalizing.evidence:
            finalizing = replace(finalizing, evidence=evidence)
            state = _checkpoint_scope_phase(finalizing, state, store)
    if not config.active:
        completed = scope_transition(
            finalizing,
            ScopeFinalizationComplete(ScopeRole.ROOT, evidence),
        )
        return _checkpoint_scope_phase(completed, state, store)

    branch = evidence["root_branch"]
    if not isinstance(branch, str) or not branch:
        return store.set_gate("tl-root-finalization", GateStatus.PENDING)
    result = _post_merge_effect(
        "root_branch_finalize",
        state.run_id,
        {"branch": branch, "working_dir": _relative_process_working_dir(config)},
        effects,
        effects_log,
        "root_branch_finalize",
        active=True,
        retryable_failure=False,
    )
    payload = _merge_result_payload(result)
    if payload is None:
        return store.set_gate("tl-root-finalization", GateStatus.PENDING)
    if (
        payload.get("branch") != branch
        or payload.get("fast_forward") is not True
        or not isinstance(payload.get("local_head_sha"), str)
        or not isinstance(payload.get("remote_head_sha"), str)
        or payload["local_head_sha"] != payload["remote_head_sha"]
        or not isinstance(payload.get("ancestry_proof"), str)
        or not payload["ancestry_proof"]
    ):
        return store.set_gate("tl-root-finalization", GateStatus.PENDING)
    completion_evidence = {
        **evidence,
        "local_head_sha": payload["local_head_sha"],
        "remote_head_sha": payload["remote_head_sha"],
        "ancestry_proof": payload["ancestry_proof"],
        "fast_forward": "true",
    }
    completed = scope_transition(
        finalizing,
        ScopeFinalizationComplete(ScopeRole.ROOT, completion_evidence),
    )
    return _checkpoint_scope_phase(completed, state, store)


def _non_root_finalization_evidence(
    state: RunState,
    manifest: PlanManifest,
) -> Mapping[str, str] | None:
    """Recover a parent-targeted aggregate candidate from durable runtime data."""
    integration = state.integration
    aggregate_pr = integration.aggregate_pr_number
    head_sha = integration.aggregate_head_sha or integration.head_sha
    base_sha = integration.aggregate_original_base_sha or state.parent_branch
    parent_branch = state.parent_branch or manifest.parent_integration_target
    handoff = integration.integration_owner_id
    if not all((aggregate_pr, head_sha, base_sha, parent_branch, handoff)):
        return None
    return {
        "aggregate_pr": str(aggregate_pr),
        "head_sha": str(head_sha),
        "base_sha": str(base_sha),
        "parent_branch": str(parent_branch),
        "handoff": str(handoff),
    }


def _maybe_finalize_non_root_scope(state: RunState, store: RunStore) -> RunState:
    """Persist and complete a non-root aggregate publication handoff."""
    phase = state.recursive_fsm
    manifest = state.plan_manifest
    if manifest is None or manifest.role != "non_root":
        return state
    if _scope_has_pending_post_merge(state):
        return state
    if isinstance(phase, RecursiveTLAllMerged):
        evidence = _non_root_finalization_evidence(state, manifest)
        if evidence is None:
            return state
        finalizing = scope_transition(phase, ScopeFinalizationRequested(ScopeRole.NON_ROOT))
        finalizing = replace(finalizing, evidence=evidence)
        state = _checkpoint_scope_phase(finalizing, state, store)
    elif isinstance(phase, RecursiveTLFinalizing):
        finalizing = phase
        if not finalizing.evidence:
            evidence = _non_root_finalization_evidence(state, manifest)
            if evidence is None:
                return state
            finalizing = replace(finalizing, evidence=evidence)
            state = _checkpoint_scope_phase(finalizing, state, store)
    else:
        return state
    completed = scope_transition(
        finalizing,
        ScopeFinalizationComplete(ScopeRole.NON_ROOT, finalizing.evidence),
    )
    return _checkpoint_scope_phase(completed, state, store)


def _maybe_finalize_scope(
    state: RunState,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Select the role-specific finalization reducer for one scope."""
    manifest = state.plan_manifest
    if manifest is None:
        return state
    if state.recursive_fsm is None and state.fsm.phase is TLPhase.TLAllMerged:
        return store.checkpoint(
            TLDone(),
            state.slices,
            state.budgets,
            state.events.last_consumed_offset,
            current_order=state.current_order,
            ordered_stages=state.ordered_stages,
            integration=state.integration,
        )
    if manifest.role == "root":
        return _maybe_finalize_root_scope(state, store, config, effects, effects_log)
    return _maybe_finalize_non_root_scope(state, store)


def _recovery_boundary_payload(
    state: RunState,
    config: TLLoopConfig,
    *,
    reason: str,
    cursor: int,
    pending_quarantine: int,
    boundary_run_seq: int | None = None,
) -> dict[str, object]:
    """Describe one recovery/live boundary as auditable evidence."""
    return {
        "run_id": state.run_id,
        "scope_id": state.plan_manifest.scope_id if state.plan_manifest is not None else None,
        "depth": config.depth,
        "reason": reason,
        "cursor": cursor,
        "boundary_run_seq": boundary_run_seq,
        "pending_quarantine": pending_quarantine,
        "transition_version": 1,
    }


def _record_recovery_boundary(
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    *,
    reason: str,
    cursor: int,
    pending_quarantine: int,
    boundary_run_seq: int | None = None,
) -> None:
    """Record why the controller has (or has not) reached live operation."""
    _record_controller_event(
        "controller",
        "tl.recovery_boundary",
        _recovery_boundary_payload(
            state,
            config,
            reason=reason,
            cursor=cursor,
            pending_quarantine=pending_quarantine,
            boundary_run_seq=boundary_run_seq,
        ),
        config,
        effects,
        effects_log,
    )


def _capture_startup_history(
    source: EventQueue,
    state: RunState,
    store: RunStore,
) -> _StartupHistory:
    """Capture one finite source prefix and combine it with retained quarantine."""
    cursor = state.events.last_consumed_offset
    boundary = cursor
    source_events: tuple[EventEnvelope, ...] = ()
    capture = getattr(source, "capture_snapshot", None)
    if callable(capture):
        try:
            snapshot = capture(cursor)
        except (OSError, ValueError) as error:
            return _StartupHistory(
                (), cursor, f"ledger_snapshot_unavailable: {type(error).__name__}"
            )
        boundary_value = getattr(snapshot, "boundary_run_seq", None)
        sequence_status = getattr(snapshot, "sequence_status", None)
        if type(boundary_value) is not int or boundary_value < cursor:
            return _StartupHistory((), cursor, "ledger_snapshot_malformed_boundary")
        boundary = boundary_value
        if not isinstance(sequence_status, SequenceStatus):
            return _StartupHistory((), boundary, "ledger_snapshot_malformed_sequence_status")
        if sequence_status is SequenceStatus.PARTIAL:
            return _StartupHistory((), boundary, "ledger_sequence_gap_or_duplicate")
        if getattr(snapshot, "active_tail", None) is not None:
            return _StartupHistory((), boundary, "ledger_snapshot_has_incomplete_tail")
        findings = getattr(snapshot, "findings", ())
        if not isinstance(findings, (tuple, list)) or not all(
            isinstance(finding, LedgerFinding) for finding in findings
        ):
            return _StartupHistory((), boundary, "ledger_snapshot_malformed_findings")
        if any(
            getattr(finding, "kind", None) is FindingKind.MISSING_RUN_SEQ for finding in findings
        ):
            return _StartupHistory((), boundary, "ledger_snapshot_missing_run_seq")
        raw_events = getattr(snapshot, "events", None)
        if not isinstance(raw_events, (tuple, list)) or not all(
            isinstance(event, EventEnvelope) for event in raw_events
        ):
            return _StartupHistory((), boundary, "ledger_snapshot_malformed_events")
        source_events = tuple(raw_events)
        source_sequences = [event.run_seq for event in source_events]
        if any(sequence is None for sequence in source_sequences):
            return _StartupHistory((), boundary, "ledger_event_missing_run_seq")
        typed_sequences = [cast(int, sequence) for sequence in source_sequences]
        if typed_sequences != sorted(typed_sequences):
            return _StartupHistory((), boundary, "ledger_snapshot_out_of_order")
        if any(sequence > boundary for sequence in typed_sequences):
            return _StartupHistory((), boundary, "ledger_event_exceeds_snapshot_boundary")
        if len(set(typed_sequences)) != len(typed_sequences):
            return _StartupHistory((), boundary, "ledger_snapshot_duplicate_run_seq")
    else:
        return _StartupHistory(
            (), cursor, "ledger_snapshot_unavailable: event source has no snapshot"
        )

    by_sequence: dict[int, _StartupEvent] = {}
    for event in source_events:
        sequence = event.run_seq
        if sequence is None:
            return _StartupHistory((), boundary, "ledger_event_missing_run_seq")
        if sequence <= cursor:
            continue
        existing = by_sequence.get(sequence)
        if existing is not None:
            if existing.event != event:
                return _StartupHistory((), boundary, f"conflicting_duplicate_run_seq:{sequence}")
            continue
        by_sequence[sequence] = _StartupEvent(event, False, True)

    for document in _replayable_quarantine_documents(store):
        try:
            event = project(document)
        except EnvelopeError:
            return _StartupHistory((), boundary, "quarantined_event_malformed")
        sequence = event.run_seq
        if sequence is None:
            return _StartupHistory((), boundary, "quarantined_event_missing_run_seq")
        boundary = max(boundary, sequence)
        existing = by_sequence.get(sequence)
        if existing is not None:
            if existing.event != event:
                return _StartupHistory((), boundary, f"conflicting_quarantine_run_seq:{sequence}")
            by_sequence[sequence] = _StartupEvent(existing.event, True, existing.source_backed)
            continue
        by_sequence[sequence] = _StartupEvent(event, True)
    return _StartupHistory(
        tuple(by_sequence[sequence] for sequence in sorted(by_sequence)),
        boundary,
    )


def _blocking_quarantine_reason(
    state: RunState,
    store: RunStore,
    expected: set[str],
    ledger_run_id: str,
) -> str | None:
    """Keep plan-relevant unresolved evidence from being skipped at startup."""
    for document in _replayable_quarantine_documents(store):
        try:
            event = project(document)
        except EnvelopeError:
            return "quarantined_event_malformed"
        if event.run_id not in {None, ledger_run_id}:
            continue
        if event.kind is EventKind.AGENT_TASK_BLOCKED:
            if _resolve_task_blocked_owner(event, state, store).owner is None:
                return f"quarantined_blocker_unresolved:{event.run_seq}"
            continue
        if not _event_belongs_to_plan(event, expected, state):
            continue
        if not resolve_event_slice(event, state, allowed_ids=expected).resolved:
            return f"quarantined_identity_unresolved:{event.event_type}:{event.run_seq}"
    return None


def _recovery_hold_result(
    state: RunState,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    reason: str,
    boundary_run_seq: int,
) -> TLRunResult:
    """Persist a bounded startup hold without dispatching lifecycle work."""
    previous = next(
        (gate for gate in state.gates if gate.name == RECOVERY_CONSISTENCY_GATE_NAME),
        None,
    )
    state = store.set_gate(RECOVERY_CONSISTENCY_GATE_NAME, GateStatus.PENDING)
    if previous is None or previous.status is not GateStatus.PENDING:
        _record_controller_event(
            "controller",
            "tl.gate_opened",
            {"gate_name": RECOVERY_CONSISTENCY_GATE_NAME, "run_id": state.run_id},
            config,
            effects,
            effects_log,
        )
    _record_recovery_boundary(
        state,
        config,
        effects,
        effects_log,
        reason=f"consistency_hold: {reason}",
        cursor=state.events.last_consumed_offset,
        pending_quarantine=len(_replayable_quarantine_documents(store)),
        boundary_run_seq=boundary_run_seq,
    )
    return TLRunResult(
        state,
        tuple(effects_log),
        (),
        (),
        diagnostics={"recovery_consistency": reason},
        journal_entries=_journal_entries(effects_log),
    )


def _complete_startup_recovery(
    plan: WorkPlan,
    state: RunState,
    source: EventQueue,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    boundary_run_seq: int,
    continued_failed_root_reason: str | None = None,
) -> tuple[RunState, str | None, bool]:
    """Reconcile durable effects, validate projection, then enable scheduling."""
    state, inconsistency = _prepare_startup_recovery(
        plan, state, source, config, effects, store, effects_log, boundary_run_seq
    )
    if inconsistency is not None:
        return state, inconsistency, False
    state = _reconcile_continued_root_failure(
        plan,
        state,
        config,
        effects,
        store,
        effects_log,
        continued_failed_root_reason,
    )
    if continued_failed_root_reason is not None and _is_terminal_phase(_phase_from_state(state)):
        return state, None, True
    config = _continued_ordered_recovery_config(state, config)
    state = _activate_startup_work(
        plan,
        state,
        source,
        config,
        effects,
        store,
        effects_log,
        boundary_run_seq,
    )
    return state, None, False


def _reconcile_continued_root_failure(
    plan: WorkPlan,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    previous_failure_reason: str | None,
) -> RunState:
    """Re-derive a prior failed root only after startup evidence is reconciled."""
    if previous_failure_reason is None:
        return state
    phase = _phase_from_state(state)
    if _is_terminal_phase(phase):
        return state
    if not plan.sub_tls:
        return state
    stage = next(
        (stage for stage in plan.ordered_stages if stage.order == state.current_order),
        None,
    )
    if stage is None:
        return state
    failed = [
        name
        for name in stage.sub_tls
        if state.slices.get(name) is not None and state.slices[name].status is SliceStatus.FAILED
    ]
    if not failed:
        return _clear_superseded_ambiguous_recovery_gate(
            state,
            stage.sub_tls,
            previous_failure_reason,
            config,
            effects,
            store,
            effects_log,
        )
    proof_state = replace(
        state,
        recursive_fsm=RecursiveTLFailed(
            previous_failure_reason,
            scope_path=getattr(phase, "scope_path", ("root",)),
        ),
    )
    decision = _ordered_terminal_recovery_decision(proof_state, plan, config, store)
    if decision is None:
        return state
    if not decision.recoverable:
        state = _hold_ordered_recovery_gate(store, decision)
        return _persist_rederived_root_failure(
            state,
            decision.reason,
            config,
            effects,
            store,
            effects_log,
        )
    try:
        return _reopen_ordered_scope(
            state,
            plan,
            store,
            decision.task_name,
            authorized=decision.authorized,
        )
    except OrderedCompletionEvidenceError as error:
        return _hold_ordered_completion_evidence(state, error, config, effects, store, effects_log)


def _hold_ordered_completion_evidence(
    state: RunState,
    error: OrderedCompletionEvidenceError,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Persist one scoped hold when a completed declaration lacks valid proof."""
    gate_name = f"tl-ordered-completion-evidence-{error.child_id}"
    if not any(gate.name == gate_name for gate in state.gates):
        state = store.set_gate(gate_name, GateStatus.PENDING)
    return _persist_rederived_root_failure(
        state,
        str(error),
        config,
        effects,
        store,
        effects_log,
    )


def _terminal_ordered_completion_hold_result(
    state: RunState,
    error: OrderedCompletionEvidenceError,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    identity_effects: Sequence[EffectIntent],
) -> TLRunResult:
    """Turn terminal-reopen proof failures into a durable scoped hold result."""
    journal_path = store.run_dir / "action-journal.json"
    effects_log: list[EffectIntent] = (
        EffectJournal(store.run_id, journal_path)
        if config.ledger_run_id is not None or journal_path.exists()
        else []
    )
    effects_log.extend(identity_effects)
    held = _hold_ordered_completion_evidence(state, error, config, effects, store, effects_log)
    return TLRunResult(
        held,
        tuple(effects_log),
        (),
        (),
        (),
        {
            "reducer_version": held.reducer_version,
            "cursor": held.events.last_consumed_offset,
            "ordered_completion_recovery": str(error),
        },
        _journal_entries(effects_log),
    )


def _clear_superseded_ambiguous_recovery_gate(
    state: RunState,
    stage_members: Sequence[str],
    previous_failure_reason: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Retire only the old zero-failed-child diagnostic after replay proves it stale."""
    gate = next(
        (
            gate
            for gate in state.gates
            if gate.name == _ordered_recovery_gate_name(None) and gate.status is GateStatus.PENDING
        ),
        None,
    )
    if gate is None:
        return state
    if any(
        state.slices.get(member) is not None and state.slices[member].status is SliceStatus.FAILED
        for member in stage_members
    ):
        return state
    state = store.clear_gate(gate.name)
    previous_failure_sha256 = hashlib.sha256(previous_failure_reason.encode("utf-8")).hexdigest()
    recovery_reason = (
        "ordered_recovery_gate_superseded:"
        f"gate={gate.name};"
        "reason_code=no_failed_child_after_replay;"
        f"previous_failure_sha256={previous_failure_sha256};"
        f"stage_members={','.join(stage_members)}"
    )
    _record_controller_event(
        "controller",
        "tl.recovery_boundary",
        {
            "scope_id": (state.plan_manifest.scope_id if state.plan_manifest is not None else None),
            "depth": config.depth,
            "reason": recovery_reason,
            "cursor": state.events.last_consumed_offset,
            "boundary_run_seq": None,
            "pending_quarantine": 0,
            "transition_version": 1,
        },
        config,
        effects,
        effects_log,
    )
    return state


def _persist_rederived_root_failure(
    state: RunState,
    reason: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Persist the failure found by this replay instead of reviving the old verdict."""
    before_phase = _phase_from_state(state)
    failed = RecursiveTLFailed(
        reason,
        scope_path=getattr(before_phase, "scope_path", ("root",)),
    )
    state = store.checkpoint(
        failed,
        state.slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=state.integration,
    )
    _emit_phase_change(
        state.run_id,
        before_phase,
        _phase_from_state(state),
        config,
        effects,
        effects_log,
    )
    return state


def _continued_ordered_recovery_config(
    state: RunState,
    config: TLLoopConfig,
) -> TLLoopConfig:
    """Restore the producer-retry route selected by post-replay proof."""
    phase = state.recursive_fsm
    if not isinstance(phase, RecursiveTLRunning):
        return config
    target = phase.evidence.get("ordered_recovery_child")
    if not target or target == "scope":
        return config
    return replace(
        config,
        ordered_recovery_child=target,
        branch=state.owner_branch or config.branch,
        worktree=state.owner_worktree or config.worktree,
    )


def _terminal_recovery_diagnostics(
    state: RunState,
    diagnostics: Mapping[str, object],
) -> dict[str, object]:
    """Expose the fresh replay's terminal decision and any still-pending gate."""
    result = dict(diagnostics)
    phase = _phase_from_state(state)
    if not isinstance(phase, (TLFailed, RecursiveTLFailed)):
        return result
    result["ordered_recovery"] = phase.reason
    gate = next(
        (gate for gate in state.gates if gate.name.startswith(ORDERED_RECOVERY_GATE_PREFIX)),
        None,
    )
    if gate is not None:
        result["recovery_gate"] = gate.name
        result["recovery_gate_status"] = gate.status.value
    return result


def _prepare_startup_recovery(
    plan: WorkPlan,
    state: RunState,
    source: EventQueue,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    boundary_run_seq: int,
) -> tuple[RunState, str | None]:
    """Reconcile retained evidence and validate projection before live effects."""
    state = store.load()
    state = _reconcile_action_journal(
        state,
        store,
        effects_log,
        effects=effects,
        project_root=config.project_root,
        ledger_run_id=config.ledger_run_id,
    )
    state = _reconcile_confirmed_repair_actions(state, store, effects_log)
    state = _reconcile_dispatches(state, config, effects, store, effects_log)
    state = _reconcile_nonterminal_slices(plan, state, config, effects, store, effects_log)
    inconsistency = _recovery_inconsistency(plan, state)
    if inconsistency is not None:
        return state, inconsistency
    if any(
        gate.name == RECOVERY_CONSISTENCY_GATE_NAME and gate.status is GateStatus.PENDING
        for gate in state.gates
    ):
        state = store.clear_gate(RECOVERY_CONSISTENCY_GATE_NAME)
        _record_recovery_boundary(
            state,
            config,
            effects,
            effects_log,
            reason="consistency_restored",
            cursor=state.events.last_consumed_offset,
            pending_quarantine=len(_replayable_quarantine_documents(store)),
            boundary_run_seq=boundary_run_seq,
        )
    return state, None


def _activate_startup_work(
    plan: WorkPlan,
    state: RunState,
    source: EventQueue,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    boundary_run_seq: int,
) -> RunState:
    """Enable lifecycle scheduling only after finite history is reconciled."""
    _record_recovery_boundary(
        state,
        config,
        effects,
        effects_log,
        reason="historical_catch_up_complete",
        cursor=state.events.last_consumed_offset,
        pending_quarantine=len(_replayable_quarantine_documents(store)),
        boundary_run_seq=boundary_run_seq,
    )
    if config.ordered_recovery:
        state = _resume_approved_blocked_leaf(plan, state, config, effects, store, effects_log)
    state = _dispatch_children(plan, state, config, effects, effects_log, store)
    state = _run_sub_tls(plan, state, config, source, effects, store, effects_log)
    return state


class _BlockedLeafResumeProof(NamedTuple):
    """Accepted leaf, old host owner, and immutable refusal evidence."""

    leaf: LeafTask
    current: SliceState
    owner: BlockedLeafOwner
    gate_name: str
    rejected_spawn: Mapping[str, object]
    intent_id: str
    action_arguments: Mapping[str, object] | None


def _blocked_leaf_resume_proof(
    plan: WorkPlan,
    state: RunState,
    config: TLLoopConfig,
    store: RunStore,
) -> tuple[_BlockedLeafResumeProof | None, str | None]:
    """Bind one approved human-gated leaf to its old owner and rejected spawn."""
    blocked = [
        leaf
        for leaf in plan.leaves
        if (current := state.slices.get(leaf.name)) is not None
        and current.status is SliceStatus.BLOCKED
        and current.recovery is not None
        and current.recovery.phase is RecoveryPhase.HUMAN_GATE
    ]
    if not blocked:
        return None, None
    if len(blocked) != 1:
        return None, "multiple human-gated leaves prevent a unique blocked-owner resume"
    leaf = blocked[0]
    current = state.slices[leaf.name]
    recovery = current.recovery
    if recovery is None or recovery.owner_run_id != state.run_id:
        return None, "blocked leaf recovery is not owned by this scope"
    evidence = recovery.evidence
    boundary_failures = [
        label
        for label, invalid in (
            ("recovery cause", recovery.cause != "human_decision_required"),
            ("recovery slice", evidence.get("slice_id") != leaf.name),
            ("recovery outcome", evidence.get("outcome") != "blocked"),
            ("human decision", evidence.get("needs_human") is not True),
            ("park cause", current.park_cause is not ParkCause.HUMAN_DECISION_REQUIRED),
            ("dispatch boundary", current.dispatch_last_boundary != "spawn_request_failed"),
            (
                "preflight error code",
                current.dispatch_error_code
                not in {"agent_error", "agent.spawn_precondition.dirty_worktree"},
            ),
            ("dispatch intent", not current.dispatch_intent_id),
            ("dispatch timestamp", current.dispatch_started_at is None),
            ("dispatch agent", current.dispatch_agent_id is not None),
            ("dispatch invocation", current.dispatch_invocation_id is not None),
            ("authoritative event", current.dispatch_authoritative_event_seq is not None),
            ("PR binding", current.pr_number is not None),
            ("publication", current.publication is not None),
            ("active action", current.action is not None),
        )
        if invalid
    ]
    if boundary_failures:
        return None, (
            "blocked leaf checkpoint lacks a proven pre-execution human recovery boundary: "
            + ", ".join(boundary_failures)
        )
    if leaf.chainlink_issue_id is not None and current.chainlink_issue_id not in {
        None,
        leaf.chainlink_issue_id,
    }:
        return None, "blocked leaf issue binding conflicts with the accepted declaration"
    if state.plan_manifest is None:
        return None, "blocked leaf has no accepted plan manifest"
    declared_node = next(
        (node for node in state.plan_manifest.nodes if node.name == leaf.name),
        None,
    )
    if (
        declared_node is None
        or declared_node.node_id != current.manifest_node_id
        or declared_node.task != leaf.task
        or declared_node.chainlink_issue_id != leaf.chainlink_issue_id
    ):
        return None, "blocked leaf declaration does not match its accepted manifest binding"
    expected_slice = _initial_slices(plan, config, store.root_dir, state.run_id).get(leaf.name)
    if (
        expected_slice is None
        or current.branch != expected_slice.get("branch")
        or current.worktree != expected_slice.get("worktree")
        or current.base_ref != config.branch
    ):
        return None, "blocked leaf branch or worktree differs from the accepted scope coordinates"
    gate_name = _dispatch_failure_gate_name(leaf.name, current.dispatch_error_code)
    gate = next((item for item in state.gates if item.name == gate_name), None)
    if gate is None or gate.status is not GateStatus.APPROVED:
        return None, f"required leaf recovery gate {gate_name!r} is not approved"
    rejected = _rejected_spawn_journal_entry(store, leaf.name, current.dispatch_intent_id)
    if rejected is None:
        return None, "matching rejected spawn journal evidence is missing or ambiguous"
    arguments = rejected.get("arguments")
    if (
        not isinstance(arguments, Mapping)
        or arguments.get("name") != leaf.name
        or arguments.get("task") != leaf.task
        or _journal_result_dirty_preflight_format(rejected, current) is None
    ):
        return None, "rejected spawn journal does not prove this leaf's pre-execution refusal"

    try:
        proof = _resolve_blocked_leaf_owner(state, config, store, leaf, current)
    except BlockedLeafOwnerError as error:
        return None, str(error)
    checkpoint_worktree = Path(current.worktree) if current.worktree is not None else None
    if checkpoint_worktree is not None and not checkpoint_worktree.is_absolute():
        checkpoint_worktree = Path(config.project_root or store.root_dir) / checkpoint_worktree
    lineage_conflicts = [
        label
        for label, invalid in (
            ("owner branch", proof.owner.branch != current.branch),
            (
                (f"owner worktree checkpoint={checkpoint_worktree} owner={proof.owner.worktree}"),
                checkpoint_worktree is None
                or proof.owner.worktree != checkpoint_worktree.resolve(),
            ),
            ("parent branch", proof.owner.parent_branch != current.base_ref),
            (
                "evidence owner",
                evidence.get("owner_agent_id") not in {None, proof.owner.agent_name},
            ),
            (
                "evidence invocation",
                evidence.get("invocation_id") not in {None, proof.owner.prior_invocation_id},
            ),
            (
                "evidence generation",
                evidence.get("generation") not in {None, 0, proof.owner.generation},
            ),
            ("recovery owner", recovery.owner_agent_id not in {None, proof.owner.agent_name}),
            (
                "recovery generation",
                recovery.invocation_generation not in {0, proof.owner.generation},
            ),
        )
        if invalid
    ]
    if lineage_conflicts:
        return None, (
            "blocked leaf owner evidence conflicts with accepted identity: "
            + ", ".join(lineage_conflicts)
        )
    return proof, None


def _resolve_blocked_leaf_owner(
    state: RunState,
    config: TLLoopConfig,
    store: RunStore,
    leaf: LeafTask,
    current: SliceState,
) -> _BlockedLeafResumeProof:
    if config.project_root is None:
        raise BlockedLeafOwnerError("blocked leaf owner lookup requires the project root")
    child_store = store
    entries = EffectJournal(state.run_id, child_store.run_dir / "action-journal.json").entries_for(
        "resume_blocked_leaf", leaf.name
    )
    if len(entries) > 1:
        raise BlockedLeafOwnerError("multiple blocked-leaf resume actions require reconciliation")
    if entries:
        entry = entries[0]
        args = entry.get("arguments")
        if not isinstance(args, Mapping):
            raise BlockedLeafOwnerError("blocked-leaf resume journal arguments are malformed")
        expected = {
            "chainlink_issue_id": args.get("chainlink_issue_id"),
            "expected_invocation_id": args.get("expected_invocation_id"),
            "expected_branch": args.get("expected_branch"),
            "expected_worktree_fingerprint": args.get("expected_worktree_fingerprint"),
            "task": leaf.task,
            "human_approved": True,
        }
        if any(args.get(key) != value for key, value in expected.items()):
            raise BlockedLeafOwnerError(
                "blocked-leaf resume journal conflicts with this declaration"
            )
        if entry.get("status") == "rejected":
            raise BlockedLeafOwnerError("the exact blocked-leaf resume request was rejected")
        if (
            not isinstance(args.get("owner_agent_name"), str)
            or type(args.get("prior_generation")) is not int
            or not isinstance(args.get("expected_worktree"), str)
            or not isinstance(args.get("expected_worktree_recorded"), str)
            or not isinstance(args.get("dispatch_intent_id"), str)
            or type(args.get("chainlink_issue_id")) is not int
            or not isinstance(args.get("expected_invocation_id"), str)
            or not isinstance(args.get("expected_branch"), str)
            or not isinstance(args.get("expected_worktree_fingerprint"), str)
        ):
            raise BlockedLeafOwnerError("blocked-leaf resume journal lacks owner lineage")
        owner, _successor = resolve_owner_for_resume_retry(
            config.project_root,
            slice_id=leaf.name,
            issue_id=int(args["chainlink_issue_id"]),
            expected_parent_branch=config.branch,
            expected_agent_name=str(args["owner_agent_name"]),
            prior_invocation_id=str(args["expected_invocation_id"]),
            prior_generation=int(args["prior_generation"]),
            expected_branch=str(args["expected_branch"]),
            expected_worktree=str(args["expected_worktree"]),
            expected_worktree_recorded=str(args["expected_worktree_recorded"]),
            expected_worktree_fingerprint=str(args["expected_worktree_fingerprint"]),
            dispatch_intent_id=str(args["dispatch_intent_id"]),
        )
        issue_id = int(args["chainlink_issue_id"])
        if leaf.chainlink_issue_id is not None and issue_id != leaf.chainlink_issue_id:
            raise BlockedLeafOwnerError(
                "journaled issue differs from the accepted leaf declaration"
            )
        if blocked_resume_intent_id(owner) != args["dispatch_intent_id"]:
            raise BlockedLeafOwnerError("journaled resume idempotency identity is inconsistent")
        return _BlockedLeafResumeProof(
            leaf,
            current,
            owner,
            _dispatch_failure_gate_name(leaf.name, current.dispatch_error_code),
            _rejected_spawn_journal_entry(child_store, leaf.name, current.dispatch_intent_id) or {},
            str(args["dispatch_intent_id"]),
            args,
        )

    owner = resolve_dormant_owner_for_slice(
        config.project_root,
        slice_id=leaf.name,
        expected_issue_id=leaf.chainlink_issue_id,
        expected_parent_branch=config.branch,
    )
    if current.chainlink_issue_id is not None and current.chainlink_issue_id != owner.issue_id:
        raise BlockedLeafOwnerError("owner issue differs from the blocked leaf checkpoint")
    return _BlockedLeafResumeProof(
        leaf,
        current,
        owner,
        _dispatch_failure_gate_name(leaf.name, current.dispatch_error_code),
        _rejected_spawn_journal_entry(child_store, leaf.name, current.dispatch_intent_id) or {},
        blocked_resume_intent_id(owner),
        None,
    )


def _resume_approved_blocked_leaf(
    plan: WorkPlan,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Resume one exactly proved, operator-approved leaf through its owner."""
    proof, reason = _blocked_leaf_resume_proof(plan, state, config, store)
    if proof is None:
        if reason is not None:
            return _hold_blocked_leaf_resume(state, config, effects, store, effects_log, reason)
        return state
    if not config.active or not isinstance(effects, EffectClient):
        return state
    try:
        arguments = _blocked_leaf_resume_action_arguments(proof, state)
        intent = EffectIntent("resume_blocked_leaf", proof.leaf.name, arguments, True)
        journal = effects_log if isinstance(effects_log, EffectJournal) else None
        if journal is None:
            raise ActionJournalError("blocked-leaf resume requires a durable action journal")
        existing = journal.existing(intent)
        status = existing.get("status") if existing is not None else None
        if status == "confirmed" or status == "rejected":
            result = journal.replay(existing)
        else:
            journal.append(intent)
            attempt = _blocked_leaf_dispatch_attempt(arguments, proof.current)
            dispatch_intended = _record_controller_event(
                proof.leaf.name,
                "tl.dispatch_intended",
                _dispatch_payload(proof.leaf.name, attempt, "dispatch_intended"),
                config,
                effects,
                effects_log,
            )
            spawn_requested = _record_controller_event(
                proof.leaf.name,
                "tl.spawn_requested",
                _dispatch_payload(proof.leaf.name, attempt, "spawn_requested"),
                config,
                effects,
                effects_log,
            )
            if not (
                dispatch_intended is not None
                and dispatch_intended.success is True
                and spawn_requested is not None
                and spawn_requested.success is True
            ):
                journal.mark_not_dispatched(intent)
                return _hold_blocked_leaf_resume(
                    state,
                    config,
                    effects,
                    store,
                    effects_log,
                    "controller dispatch intent could not be recorded before owner resume",
                )
            try:
                result = effects.resume_blocked_leaf(
                    chainlink_issue_id=proof.owner.issue_id,
                    expected_invocation_id=proof.owner.prior_invocation_id,
                    expected_branch=proof.owner.branch,
                    expected_worktree_fingerprint=proof.owner.worktree_fingerprint,
                    task=proof.leaf.task,
                    human_approved=True,
                )
            except Exception as error:  # noqa: BLE001 - journal and safely retry exact owner intent
                journal.mark_unknown(intent, error)
                return _hold_blocked_leaf_resume(
                    state,
                    config,
                    effects,
                    store,
                    effects_log,
                    f"blocked-leaf resume outcome is unknown: {type(error).__name__}",
                )
            journal.mark_result(intent, result)
        if result.success is not True:
            return _hold_blocked_leaf_resume(
                state,
                config,
                effects,
                store,
                effects_log,
                "configured blocked-leaf resume was rejected; inspect the exact owner evidence",
            )
        successor = _validated_blocked_resume_result(proof, result)
        if successor is None:
            return _hold_blocked_leaf_resume(
                state,
                config,
                effects,
                store,
                effects_log,
                "blocked-leaf resume response does not match the persisted owner successor",
            )
        invocation_id, runtime, model, effort = successor
        attempt = _blocked_leaf_dispatch_attempt(arguments, proof.current).routed(
            harness=f"{runtime}/{model}" if model else runtime,
            agent_type=runtime,
            model=model,
            requested_harness=proof.current.requested_harness,
            route_reconciliation_source="proven_preexecution_retry",
        )
        accepted = _record_controller_event(
            proof.leaf.name,
            "tl.spawn_request_accepted",
            _dispatch_payload(proof.leaf.name, attempt, "spawn_request_accepted"),
            config,
            effects,
            effects_log,
        )
        if accepted is None or accepted.success is not True:
            return _hold_blocked_leaf_resume(
                state,
                config,
                effects,
                store,
                effects_log,
                "controller could not durably record the confirmed owner response",
            )
        state = _checkpoint_blocked_leaf_successor(
            proof, state, store, attempt, invocation_id, runtime, model, effort
        )
        return _reconcile_dispatches(state, config, effects, store, effects_log)
    except (
        BlockedLeafOwnerError,
        ActionJournalError,
        KeyError,
        TypeError,
        ValueError,
        OSError,
    ) as error:
        return _hold_blocked_leaf_resume(state, config, effects, store, effects_log, str(error))


def _blocked_leaf_resume_action_arguments(
    proof: _BlockedLeafResumeProof,
    state: RunState,
) -> Mapping[str, object]:
    if proof.action_arguments is not None:
        return proof.action_arguments
    return {
        "chainlink_issue_id": proof.owner.issue_id,
        "expected_invocation_id": proof.owner.prior_invocation_id,
        "expected_branch": proof.owner.branch,
        "expected_worktree_fingerprint": proof.owner.worktree_fingerprint,
        "task": proof.leaf.task,
        "human_approved": True,
        "owner_agent_name": proof.owner.agent_name,
        "prior_generation": proof.owner.generation,
        "expected_worktree": str(proof.owner.worktree),
        "expected_worktree_recorded": proof.owner.worktree_recorded,
        "dispatch_intent_id": proof.intent_id,
        "dispatch_attempt": proof.current.attempts + 1,
        "dispatch_started_at": time.time(),
        "dispatch_generation": proof.owner.generation + 1,
        "dispatch_ledger_floor": state.events.last_consumed_offset,
        "controller_epoch": state.controller_epoch,
        "route_reconciliation_source": "proven_preexecution_retry",
        "requested_harness": proof.current.requested_harness,
    }


def _blocked_leaf_dispatch_attempt(
    arguments: Mapping[str, object], current: SliceState
) -> DispatchAttempt:
    return DispatchAttempt(
        intent_id=cast(str, arguments["dispatch_intent_id"]),
        started_at=float(arguments["dispatch_started_at"]),
        harness="",
        requested_harness=current.requested_harness,
        route_reconciliation_source="proven_preexecution_retry",
        attempt=int(arguments["dispatch_attempt"]),
        controller_epoch=cast(str | None, arguments.get("controller_epoch")),
        dispatch_generation=int(arguments["dispatch_generation"]),
        ledger_floor=int(arguments["dispatch_ledger_floor"]),
    )


def _validated_blocked_resume_result(
    proof: _BlockedLeafResumeProof,
    result: ToolResult,
) -> tuple[str, str, str | None, str | None] | None:
    payload = result.result
    if not isinstance(payload, Mapping):
        return None
    agent = payload.get("agent")
    invocation = payload.get("invocation")
    if not isinstance(agent, Mapping) or not isinstance(invocation, Mapping):
        return None
    invocation_id = invocation.get("invocation_id")
    runtime = invocation.get("runtime")
    if (
        payload.get("chainlink_issue_id") != proof.owner.issue_id
        or agent.get("id") != proof.owner.agent_name
        or agent.get("issue") != proof.leaf.name
        or agent.get("intent_id") != proof.intent_id
        or agent.get("branch_name") != proof.owner.branch
        or Path(str(agent.get("worktree_path", ""))).resolve() != proof.owner.worktree
        or invocation.get("trigger") != "resume_blocked"
        or invocation.get("branch_name") != proof.owner.branch
        or invocation.get("ready") is not True
        or invocation.get("outcome") not in {"started", "adopted_after_response_loss"}
        or invocation.get("fresh") is not (invocation.get("outcome") == "started")
        or not isinstance(invocation_id, str)
        or not invocation_id
        or not isinstance(runtime, str)
        or not runtime
    ):
        return None
    try:
        identity, _persisted = validate_resumed_owner(
            proof.owner,
            invocation_id=invocation_id,
            dispatch_intent_id=proof.intent_id,
            runtime=runtime,
        )
    except BlockedLeafOwnerError:
        return None
    return (
        invocation_id,
        runtime,
        _optional_nonempty_text(identity.get("model")),
        _optional_nonempty_text(identity.get("effort")),
    )


def _optional_nonempty_text(value: object) -> str | None:
    return value.strip() if isinstance(value, str) and value.strip() else None


def _checkpoint_blocked_leaf_successor(
    proof: _BlockedLeafResumeProof,
    state: RunState,
    store: RunStore,
    attempt: DispatchAttempt,
    invocation_id: str,
    runtime: str,
    model: str | None,
    effort: str | None,
) -> RunState:
    current = proof.current
    updated = replace(
        slice_transition(current, SliceStatusChanged(SliceStatus.DISPATCH_UNCONFIRMED)),
        base_ref=proof.owner.parent_branch,
        branch=proof.owner.branch,
        worktree=str(proof.owner.worktree),
        agent_type=runtime,
        model=model,
        resolved_harness=f"{runtime}/{model}" if model else runtime,
        attempts=attempt.attempt,
        dispatch_uses_current_role_configuration=True,
        dispatch_intent_id=proof.intent_id,
        dispatch_started_at=attempt.started_at,
        dispatch_last_boundary="spawn_request_accepted",
        dispatch_error=None,
        dispatch_error_code=None,
        dispatch_ledger_floor=attempt.ledger_floor,
        dispatch_generation=attempt.dispatch_generation,
        dispatch_next_attempt_at=None,
        dispatch_retry_for_attempt=0,
        dispatch_agent_id=proof.owner.agent_name,
        dispatch_invocation_id=invocation_id,
        dispatch_authoritative_event_seq=None,
        park_cause=ParkCause.DISPATCH_UNCONFIRMED,
        recovery=None,
    )
    clear_gates = {proof.gate_name}
    proof_gate = f"tl-blocked-leaf-resume-proof-{proof.leaf.name}"
    if any(gate.name == proof_gate for gate in state.gates):
        clear_gates.add(proof_gate)
    return store.checkpoint(
        _phase_from_state(state),
        {**state.slices, proof.leaf.name: updated},
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=state.integration,
        clear_gates=tuple(sorted(clear_gates)),
    )


def _hold_blocked_leaf_resume(
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    reason: str,
) -> RunState:
    blocked = next(
        (
            item
            for item in state.slices.values()
            if item.status is SliceStatus.BLOCKED and item.recovery is not None
        ),
        None,
    )
    if blocked is None:
        return state
    gate_name = f"tl-blocked-leaf-resume-proof-{blocked.id}"
    if not any(gate.name == gate_name for gate in state.gates):
        state = store.set_gate(gate_name, GateStatus.PENDING)
        _record_controller_event(
            blocked.id,
            "tl.gate_opened",
            {"gate_name": gate_name, "run_id": state.run_id},
            config,
            effects,
            effects_log,
        )
    LOGGER.warning("blocked-leaf resume held slice=%s reason=%s", blocked.id, reason)
    return store.load()


def _apply_deferred_startup_recovery(
    plan: WorkPlan,
    state: RunState,
    review_events: Sequence[EventEnvelope],
    ci_events: Sequence[EventEnvelope],
    convergence: ConvergenceTracker,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Apply only final replayed failure actions after catch-up is complete."""
    reviewed: set[tuple[str, str]] = set()
    for event in review_events:
        slice_id = _review_slice_id(event, state)
        head_sha = _event_review_head(event)
        if slice_id is None or head_sha is None or (slice_id, head_sha) in reviewed:
            continue
        reviewed.add((slice_id, head_sha))
        current = state.slices.get(slice_id)
        if (
            current is None
            or current.status is SliceStatus.REPAIRING
            or current.reviewed_head != head_sha
            or current.verdict is not Verdict.NO_GO
            or _review_rounds_exhausted(state, current, config)
        ):
            continue
        reasons = [
            {
                "severity": finding.get("severity", "blocking"),
                "file": finding.get("path", "review"),
                "line": 0,
                "claim": finding.get("rationale", "review requested changes"),
            }
            for finding in current.review_findings.get(head_sha, ())
        ]
        state = _route_repair(
            store,
            state,
            _phase_from_state(state),
            max(state.events.last_consumed_offset, event.run_seq or 0),
            slice_id,
            config,
            effects,
            effects_log,
            _forward_findings_repair(
                {"verdict": Verdict.NO_GO.value, "reasons": reasons}, store, current
            ),
        )
    failed_ci: dict[tuple[str, str], EventEnvelope] = {}
    for event in ci_events:
        slice_id = _review_slice_id(event, state)
        if slice_id is None or event.head_sha is None:
            continue
        key = (slice_id, event.head_sha)
        if _ci_status(event) == "failure":
            failed_ci[key] = event
        else:
            failed_ci.pop(key, None)
    for (slice_id, head_sha), event in failed_ci.items():
        current = state.slices.get(slice_id)
        if (
            current is None
            or current.status is SliceStatus.REPAIRING
            or current.ci_state.get(head_sha) != "failure"
        ):
            continue
        state = _route_ci_event(
            store,
            state,
            _phase_from_state(state),
            event,
            max(state.events.last_consumed_offset, event.run_seq or 0),
            config,
            effects,
            effects_log,
            allow_lifecycle_effects=True,
            reconcile_deferred=True,
        )
    return state


def _recovery_inconsistency(plan: WorkPlan, state: RunState) -> str | None:
    """Validate the recovered projection before any live scheduling or timer.

    Returns a specific diagnostic when the checkpoint, ordered stages, or
    integration candidates disagree, so the run holds behind an actionable gate
    instead of scheduling work on an inconsistent projection.
    """
    if state.plan_manifest is None:
        return "checkpoint has no immutable plan manifest"
    if state.events.last_consumed_offset < 0:
        return "checkpoint cursor is negative"
    planned_sub_tls = {task.name for task in plan.sub_tls}
    if plan.sub_tls and not state.ordered_stages:
        return "ordered plan has no persisted stages"
    if plan.sub_tls:
        orders = [stage.order for stage in state.ordered_stages]
        if any(order < 1 for order in orders):
            return "ordered plan has a non-positive stage order"
        if len(set(orders)) != len(orders):
            return "ordered plan has duplicate stage orders"
        if sorted(orders) != list(range(1, len(orders) + 1)):
            return "ordered stage orders are not contiguous from one"
        if state.current_order < 1:
            return "ordered plan has an invalid current order"
        if state.current_order > max(orders) + 1:
            return "current order is beyond the final ordered stage"
        if len(orders) != len(plan.ordered_stages):
            return "persisted ordered stages do not match the accepted plan"
    for candidate_id in state.integration.candidates:
        if candidate_id not in state.slices:
            return f"integration candidate {candidate_id!r} has no slice"
        if candidate_id not in planned_sub_tls:
            return f"integration candidate {candidate_id!r} is not a declared sub-TL"
    for stage in state.ordered_stages:
        for member in stage.sub_tls:
            if member not in state.slices:
                return f"ordered stage member {member!r} has no slice"
            if member not in planned_sub_tls:
                return f"ordered stage member {member!r} is not a declared sub-TL"
    return None


def _run_loop(
    run_id: str,
    plan: WorkPlan,
    source: EventQueue,
    effects: EffectClient | ReadOnlyEffectClient,
    config: TLLoopConfig,
    store: RunStore,
    state: RunState,
    effects_log: list[EffectIntent],
    decoder: TLEventDecoder,
    startup_recovery: bool = False,
    continued_failed_root_reason: str | None = None,
) -> TLRunResult:
    """Shared loop body; active mode changes only effect execution."""
    phase = _phase_from_state(state)
    expected = (
        {task.name for task in plan.workers}
        | {task.name for task in plan.leaves}
        | {task.name for task in plan.sub_tls}
    )
    transitions: list[LoopTransition] = []
    consumed: list[int] = []
    policy = _review_policy_for_state(state, config.review_policy_path, store)
    state = store.load()
    freshness_window_secs = (
        load_freshness_window(config.review_policy_path)
        if config.review_policy_path is not None
        else None
    )
    convergence = ConvergenceTracker(
        reviewer_max_rounds=policy.reviewer_max_rounds,
        review_freshness_window_secs=freshness_window_secs,
        review_now=config.review_clock() if config.review_clock is not None else None,
    )
    heartbeat_events: list[SyntheticHeartbeatEvent] = []
    # One invocation-scoped work clock: fresh start table, monotonic source.
    # Nothing marks a slice active during catch-up/replay, so no work-time
    # clock is read until live operation observes proven active work.
    active_work_clock = ActiveWorkClock(config.work_clock)
    diagnostics = EventDiagnostics(
        task_started_at={
            slice_id: slice_state.dispatch_started_at
            for slice_id, slice_state in state.slices.items()
            if slice_state.dispatch_started_at is not None
        }
    )
    # Move legacy audit rows first, then capture one finite source prefix. New
    # ledger writes after this snapshot remain ordinary live input.
    _migrate_audit_marked_quarantine(store)
    history = (
        _capture_startup_history(source, state, store)
        if startup_recovery
        else _StartupHistory((), state.events.last_consumed_offset)
    )
    if history.error is not None:
        return _recovery_hold_result(
            state,
            store,
            config,
            effects,
            effects_log,
            history.error,
            history.boundary_run_seq,
        )
    startup_events = list(history.events)
    startup_event_index = 0
    startup_drain_empty_polls = 0
    startup_drain_duplicate_polls = 0
    quarantined = [entry.event for entry in startup_events if entry.quarantined]
    deferred_reviews: list[EventEnvelope] = []
    deferred_ci: list[EventEnvelope] = []
    if state.goals.controller_started_at is None:
        state = store.set_goals(
            replace(state.goals, controller_started_at=diagnostics.controller_started_at)
        )
    # Catch-up is a captured finite prefix, not a poll-until-empty rule.
    recovery_pending = bool(startup_events)
    if recovery_pending:
        _record_recovery_boundary(
            state,
            config,
            effects,
            effects_log,
            reason="historical_catch_up_pending",
            cursor=state.events.last_consumed_offset,
            pending_quarantine=sum(event.quarantined for event in startup_events),
            boundary_run_seq=history.boundary_run_seq,
        )
    elif startup_recovery:
        blocker = _blocking_quarantine_reason(
            state, store, expected, config.ledger_run_id or run_id
        )
        if blocker is not None:
            return _recovery_hold_result(
                state,
                store,
                config,
                effects,
                effects_log,
                blocker,
                history.boundary_run_seq,
            )
        state, inconsistency, terminal_after_replay = _complete_startup_recovery(
            plan,
            state,
            source,
            config,
            effects,
            store,
            effects_log,
            history.boundary_run_seq,
            continued_failed_root_reason,
        )
        if inconsistency is not None:
            return _recovery_hold_result(
                state,
                store,
                config,
                effects,
                effects_log,
                inconsistency,
                history.boundary_run_seq,
            )
        if terminal_after_replay:
            return TLRunResult(
                state,
                tuple(effects_log),
                tuple(transitions),
                tuple(consumed),
                diagnostics=_terminal_recovery_diagnostics(state, diagnostics.snapshot()),
                journal_entries=_journal_entries(effects_log),
            )
        config = _continued_ordered_recovery_config(state, config)
    if not recovery_pending:
        if (
            not plan.sub_tls
            and not _source_has_pending(source)
            and _scope_has_pending_post_merge(state)
        ):
            state = _drain_direct_scope_convergence(
                state, convergence, store, config, effects, effects_log
            )
        before_finalization_phase = _phase_from_state(state)
        state = _maybe_finalize_scope(state, store, config, effects, effects_log)
        after_finalization_phase = _phase_from_state(state)
        if after_finalization_phase != before_finalization_phase:
            _emit_phase_change(
                run_id,
                before_finalization_phase,
                after_finalization_phase,
                config,
                effects,
                effects_log,
            )
        phase = _phase_from_state(state)
        if (
            isinstance(state.recursive_fsm, RecursiveTLAllMerged)
            and not _source_has_pending(source)
            and _child_handoff_ready(state, state.parent_run_id or "")
        ):
            return TLRunResult(
                state,
                tuple(effects_log),
                tuple(transitions),
                tuple(consumed),
                diagnostics=diagnostics.snapshot(),
                journal_entries=_journal_entries(effects_log),
            )
        if not expected and not plan.sub_tls and not _is_terminal_phase(phase):
            if not isinstance(phase, RecursiveTLAllMerged):
                raise TLLoopError("empty scope did not reach a canonical completion boundary")
            return TLRunResult(
                state,
                tuple(effects_log),
                tuple(transitions),
                tuple(consumed),
                diagnostics=diagnostics.snapshot(),
                journal_entries=_journal_entries(effects_log),
            )

    if not recovery_pending and not isinstance(
        derive_next_action(
            state,
            reviewer_max_rounds=convergence.reviewer_max_rounds,
            review_freshness_window_secs=convergence.review_freshness_window_secs,
            now=convergence.review_now,
        ),
        Quiescent,
    ):
        state = _apply_convergence(state, convergence, store, config, effects, effects_log)
        phase = _phase_from_state(state)

    while not config.test_harness or len(consumed) < config.max_events:
        if not recovery_pending and not (
            isinstance(_phase_from_state(state), RecursiveTLAllMerged)
            and _source_has_pending(source)
        ):
            before_finalization_phase = _phase_from_state(state)
            state = _maybe_finalize_scope(state, store, config, effects, effects_log)
            after_finalization_phase = _phase_from_state(state)
            if after_finalization_phase != before_finalization_phase:
                _emit_phase_change(
                    run_id,
                    before_finalization_phase,
                    after_finalization_phase,
                    config,
                    effects,
                    effects_log,
                )
        phase = _phase_from_state(state)
        if (
            not recovery_pending
            and not _source_has_pending(source)
            and _child_handoff_ready(state, state.parent_run_id or "")
        ):
            return TLRunResult(
                state,
                tuple(effects_log),
                tuple(transitions),
                tuple(consumed),
                tuple(heartbeat_events),
                diagnostics.snapshot(),
                _journal_entries(effects_log),
            )
        if _is_terminal_phase(phase) and not recovery_pending:
            break
        if (
            not recovery_pending
            and isinstance(convergence.last_decision, Quiescent)
            and not config.keep_alive_on_waiting
            and not _source_has_pending(source)
        ):
            return TLRunResult(
                state,
                tuple(effects_log),
                tuple(transitions),
                tuple(consumed),
                tuple(heartbeat_events),
                diagnostics.snapshot(),
                _journal_entries(effects_log),
            )
        if config.cancel_event is not None and config.cancel_event.is_set():
            raise LoopCancelled(f"TL controller {run_id!r} was cancelled")
        _record_reader_findings(source, diagnostics)
        replaying = False
        catching_up = False
        event: EventEnvelope | None = None
        if recovery_pending:
            next_startup_event = (
                startup_events[startup_event_index]
                if startup_event_index < len(startup_events)
                else None
            )
            next_startup_seq = (
                next_startup_event.event.run_seq if next_startup_event is not None else None
            )
            replay_index = _replayable_event_index(quarantined, state, expected)
            replay_seq = quarantined[replay_index].run_seq if replay_index is not None else None
            replay_before_next = replay_index is not None and (
                next_startup_seq is None
                or replay_seq is not None
                and replay_seq <= next_startup_seq
            )
            if replay_before_next:
                event = quarantined.pop(cast(int, replay_index))
                replaying = True
                catching_up = True
                if replay_seq == next_startup_seq:
                    startup_event_index += 1
            elif next_startup_event is not None:
                if next_startup_event.quarantined and not next_startup_event.source_backed:
                    startup_event_index += 1
                    event = None
                    continue
                try:
                    queued_event = _next_event(source, config)
                except LoopCancelled:
                    raise
                except (OSError, ValueError) as error:
                    return _recovery_hold_result(
                        state,
                        store,
                        config,
                        effects,
                        effects_log,
                        f"ledger_snapshot_drain_unavailable:{type(error).__name__}",
                        history.boundary_run_seq,
                    )
                catching_up = True
                if (
                    queued_event is not None
                    and queued_event.run_seq is not None
                    and queued_event.run_seq <= state.events.last_consumed_offset
                ):
                    source.acknowledge(queued_event)
                    diagnostics.filtered += 1
                    diagnostics.acknowledged += 1
                    startup_drain_duplicate_polls += 1
                    if startup_drain_duplicate_polls >= STARTUP_DRAIN_EMPTY_POLL_LIMIT:
                        return _recovery_hold_result(
                            state,
                            store,
                            config,
                            effects,
                            effects_log,
                            "ledger_snapshot_duplicate_delivery_limit",
                            history.boundary_run_seq,
                        )
                    queued_event = None
                if queued_event is None:
                    startup_drain_empty_polls += 1
                    if startup_drain_empty_polls >= STARTUP_DRAIN_EMPTY_POLL_LIMIT:
                        return _recovery_hold_result(
                            state,
                            store,
                            config,
                            effects,
                            effects_log,
                            "ledger_snapshot_drain_timeout",
                            history.boundary_run_seq,
                        )
                elif queued_event != next_startup_event.event:
                    return _recovery_hold_result(
                        state,
                        store,
                        config,
                        effects,
                        effects_log,
                        "ledger_snapshot_queue_mismatch",
                        history.boundary_run_seq,
                    )
                else:
                    startup_drain_empty_polls = 0
                    startup_drain_duplicate_polls = 0
                    startup_event_index += 1
                    event = queued_event
                    replaying = False
            else:
                blocker = _blocking_quarantine_reason(
                    state, store, expected, config.ledger_run_id or run_id
                )
                if blocker is not None:
                    return _recovery_hold_result(
                        state,
                        store,
                        config,
                        effects,
                        effects_log,
                        blocker,
                        history.boundary_run_seq,
                    )
                state, inconsistency = _prepare_startup_recovery(
                    plan,
                    state,
                    source,
                    config,
                    effects,
                    store,
                    effects_log,
                    history.boundary_run_seq,
                )
                if inconsistency is not None:
                    return _recovery_hold_result(
                        state,
                        store,
                        config,
                        effects,
                        effects_log,
                        inconsistency,
                        history.boundary_run_seq,
                    )
                state = _apply_deferred_startup_recovery(
                    plan,
                    state,
                    deferred_reviews,
                    deferred_ci,
                    convergence,
                    config,
                    effects,
                    store,
                    effects_log,
                )
                state = _reconcile_continued_root_failure(
                    plan,
                    state,
                    config,
                    effects,
                    store,
                    effects_log,
                    continued_failed_root_reason,
                )
                if continued_failed_root_reason is not None and _is_terminal_phase(
                    _phase_from_state(state)
                ):
                    return TLRunResult(
                        state,
                        tuple(effects_log),
                        tuple(transitions),
                        tuple(consumed),
                        diagnostics=_terminal_recovery_diagnostics(state, diagnostics.snapshot()),
                        journal_entries=_journal_entries(effects_log),
                    )
                config = _continued_ordered_recovery_config(state, config)
                state = _activate_startup_work(
                    plan,
                    state,
                    source,
                    config,
                    effects,
                    store,
                    effects_log,
                    history.boundary_run_seq,
                )
                before_finalization_phase = _phase_from_state(state)
                state = _maybe_finalize_scope(state, store, config, effects, effects_log)
                phase = _phase_from_state(state)
                if phase != before_finalization_phase:
                    _emit_phase_change(
                        run_id,
                        before_finalization_phase,
                        phase,
                        config,
                        effects,
                        effects_log,
                    )
                decision = derive_next_action(
                    state,
                    reviewer_max_rounds=convergence.reviewer_max_rounds,
                    review_freshness_window_secs=convergence.review_freshness_window_secs,
                    now=convergence.review_now,
                )
                if not _is_terminal_phase(phase) and not isinstance(decision, Quiescent):
                    state = _apply_convergence(
                        state, convergence, store, config, effects, effects_log
                    )
                phase = _phase_from_state(state)
                recovery_pending = False
        if event is None:
            if not recovery_pending and _is_terminal_phase(_phase_from_state(state)):
                break
            replay_index = _replayable_event_index(quarantined, state, expected)
            if replay_index is not None:
                event = quarantined.pop(replay_index)
                replaying = True
            else:
                event = _next_event(source, config)
        _record_reader_findings(source, diagnostics)
        if event is None:
            if recovery_pending:
                continue
            if config.heartbeat is not None and not recovery_pending:
                heartbeat = heartbeat_once(
                    state,
                    store,
                    effects,
                    config.heartbeat,
                    project_root=config.project_root,
                    active_work=active_work_clock,
                    review_replay=lambda replay_state, replay_slice, replay_watcher, replay_config=config: (
                        _replay_watcher_review_if_needed(
                            plan,
                            replay_state,
                            replay_slice,
                            replay_watcher,
                            replay_config,
                            effects,
                            store,
                            effects_log,
                        )
                    ),
                )
                if heartbeat.fired:
                    before_phase = phase
                    state = heartbeat.state
                    heartbeat_events.extend(heartbeat.events)
                    diagnostics.last_observed_progress_at = state.goals.last_progress_at
                    phase = _phase_from_state(state)
                    LOGGER.info(
                        "[TL loop] waiting observation run_id=%s elapsed=%.3fs "
                        "last_authoritative_event_seq=%s last_progress_at=%s",
                        run_id,
                        time.time() - diagnostics.controller_started_at,
                        state.goals.last_authoritative_event_seq,
                        state.goals.last_progress_at,
                    )
                    _emit_phase_change(run_id, before_phase, phase, config, effects, effects_log)
                    state = _apply_convergence(
                        state, convergence, store, config, effects, effects_log
                    )
                    phase = _phase_from_state(state)
                    if heartbeat.parked_slice_ids and _all_expected_terminal(state, expected):
                        before_phase = phase
                        state = store.checkpoint(
                            _failure_phase(
                                state,
                                "heartbeat parked the remaining active slices",
                            ),
                            state.slices,
                            state.budgets,
                            state.events.last_consumed_offset,
                        )
                        phase = _phase_from_state(state)
                        _emit_phase_change(
                            run_id, before_phase, phase, config, effects, effects_log
                        )
            if (
                not recovery_pending
                and _sub_tls_waiting_for_integration(plan, state)
                and not config.keep_alive_on_waiting
            ):
                return TLRunResult(
                    state,
                    tuple(effects_log),
                    tuple(transitions),
                    tuple(consumed),
                    tuple(heartbeat_events),
                    diagnostics.snapshot(),
                    _journal_entries(effects_log),
                )
            # A direct-leaf/worker scope (no sub_tls) has no recursive
            # sub-child dispatch to await, so an empty poll carries no new
            # information: any remaining work (post-merge boundary steps,
            # scope finalization) is entirely internal to already-persisted
            # state. Drain it here instead of relying on the next ledger
            # event, which will never come.
            if (
                not recovery_pending
                and not plan.sub_tls
                and not _is_terminal_phase(_phase_from_state(state))
            ):
                state = _drain_direct_scope_convergence(
                    state, convergence, store, config, effects, effects_log
                )
            continue
        event_seq = event.run_seq
        if event_seq is None:
            raise TLLoopError(f"{event.event_type!r} has no run_seq")
        if not replaying and event_seq <= state.events.last_consumed_offset:
            diagnostics.filtered += 1
            _ack_event(source, event, replaying, diagnostics)
            state = store.load()
            continue
        if not replaying:
            consumed.append(event_seq)
            diagnostics.received += 1
        diagnostics.last_event_seq = event_seq
        checkpoint_seq = max(event_seq, state.events.last_consumed_offset)
        ledger_run_id = config.ledger_run_id or run_id
        if event.run_id not in {None, ledger_run_id}:
            diagnostics.filtered += 1
            _checkpoint_and_ack(store, source, event, state, phase, acknowledge=not replaying)
            if not replaying:
                diagnostics.acknowledged += 1
            _release_replayed_event(store, event, replaying)
            state = store.load()
            LOGGER.warning(
                "Ignoring event from stale swarm run_id=%s expected=%s local_checkpoint=%s event_seq=%s",
                event.run_id,
                ledger_run_id,
                run_id,
                event_seq,
            )
            continue
        spawn_slice_hint, spawn_alias_conflict = _uncheckpointed_spawn_slice_hint(
            event, state, plan
        )
        gate_name = event.data.get("gate_name")
        if (
            event.event_type == "tl.gate_answered"
            and isinstance(gate_name, str)
            and gate_name.startswith(AGGREGATE_PUBLICATION_GATE_PREFIX)
        ):
            _checkpoint_and_ack(store, source, event, state, phase, acknowledge=not replaying)
            if not replaying:
                diagnostics.acknowledged += 1
            diagnostics.correlated += 1
            state = store.load()
            if (
                not catching_up
                and event.data.get("decision") == GateStatus.APPROVED.value
                and plan.sub_tls
            ):
                state = _run_sub_tls(plan, state, config, source, effects, store, effects_log)
                phase = _phase_from_state(state)
                state = _apply_convergence(state, convergence, store, config, effects, effects_log)
                phase = _phase_from_state(state)
            _release_replayed_event(store, event, replaying)
            if _is_terminal_phase(phase) and not catching_up:
                break
            continue
        if event.kind is EventKind.AGENT_TASK_BLOCKED:
            state, routed = _route_task_blocked_event(
                event,
                plan,
                state,
                event_seq,
                replaying,
                diagnostics,
                convergence,
                config,
                effects,
                store,
                source,
                effects_log,
                allow_lifecycle_effects=not catching_up,
            )
            if not routed:
                return TLRunResult(
                    state,
                    tuple(effects_log),
                    tuple(transitions),
                    tuple(consumed),
                    tuple(heartbeat_events),
                    diagnostics.snapshot(),
                    _journal_entries(effects_log),
                )
            phase = _phase_from_state(state)
            continue
        resolution = resolve_event_slice(event, state, allowed_ids=expected)
        if not _event_belongs_to_plan(event, expected, state) and spawn_slice_hint is None:
            if _is_reconcilable_identity_event(event):
                if not replaying:
                    quarantined.append(event)
                    store.quarantine_event(envelope_document(event))
                diagnostics.record_unresolved_event(event, resolution)
            diagnostics.filtered += 1
            _checkpoint_and_ack(
                store,
                source,
                event,
                state,
                phase,
                acknowledge=not replaying,
            )
            if not replaying:
                diagnostics.acknowledged += 1
            state = store.load()
            continue
        if catching_up and spawn_slice_hint is not None:
            if spawn_alias_conflict:
                return _recovery_hold_result(
                    state,
                    store,
                    config,
                    effects,
                    effects_log,
                    "spawn_confirmation_conflicting_slice_aliases",
                    history.boundary_run_seq,
                )
            state, disposition, reason = _restore_dispatch_from_confirmation(
                event,
                spawn_slice_hint,
                state,
                config,
                store,
                effects_log,
            )
            if disposition == "hold":
                return _recovery_hold_result(
                    state,
                    store,
                    config,
                    effects,
                    effects_log,
                    reason or "spawn_confirmation_unresolved",
                    history.boundary_run_seq,
                )
            if disposition == "historical":
                _record_historical_spawn(store, event, DISPATCH_EPOCH_MISMATCH)
                diagnostics.filtered += 1
                _checkpoint_and_ack(store, source, event, state, phase, acknowledge=not replaying)
                if not replaying:
                    diagnostics.acknowledged += 1
                _release_replayed_event(store, event, replaying)
                state = store.load()
                continue
        state = _note_authoritative_event(
            store, state, checkpoint_seq, update_progress=not catching_up
        )
        diagnostics.last_authoritative_event_seq = event_seq
        diagnostics.last_observed_progress_at = state.goals.last_progress_at
        if config.heartbeat is not None and not catching_up:
            state = _note_heartbeat_progress(store, state)
        direct_reviewer_verdict = event.event_type == "pr.review" and "verdict" in event.data
        if event.kind in {EventKind.PR_REVIEW, EventKind.COPILOT_REVIEW}:
            diagnostics.correlated += 1
            if _review_workflow_enabled(config) or direct_reviewer_verdict:
                state = _route_review_event(
                    plan,
                    store,
                    state,
                    phase,
                    event,
                    checkpoint_seq,
                    config,
                    effects,
                    effects_log,
                    allow_lifecycle_effects=not catching_up,
                )
            else:
                state = _record_review_event(store, state, phase, event, checkpoint_seq)
            if plan.sub_tls and not catching_up:
                state = _run_sub_tls(plan, state, config, source, effects, store, effects_log)
                phase = _phase_from_state(state)
            if catching_up:
                deferred_reviews.append(event)
            else:
                state = _apply_convergence(state, convergence, store, config, effects, effects_log)
            _ack_event(source, event, replaying, diagnostics)
            _release_replayed_event(store, event, replaying)
            if _is_terminal_phase(phase) and not catching_up:
                break
            continue
        if event.kind is EventKind.CI_STATUS_CHANGED:
            diagnostics.correlated += 1
            state = _route_ci_event(
                store,
                state,
                phase,
                event,
                checkpoint_seq,
                config,
                effects,
                effects_log,
                allow_lifecycle_effects=not catching_up,
            )
            if plan.sub_tls and not catching_up:
                state = _run_sub_tls(plan, state, config, source, effects, store, effects_log)
                phase = _phase_from_state(state)
            if catching_up:
                deferred_ci.append(event)
            else:
                state = _apply_convergence(state, convergence, store, config, effects, effects_log)
            _ack_event(source, event, replaying, diagnostics)
            _release_replayed_event(store, event, replaying)
            if _is_terminal_phase(phase) and not catching_up:
                break
            continue
        if event.kind is EventKind.AGENT_SPAWN_FAILED:
            # Telemetry-only: the refused spawn is already persisted as a
            # dispatch boundary by the dispatch path, and this row is the
            # durable evidence its machine code is read from. There is no
            # transition to apply and no second decision to make here.
            diagnostics.correlated += 1
            _checkpoint_and_ack(store, source, event, state, phase, acknowledge=not replaying)
            if not replaying:
                diagnostics.acknowledged += 1
            _release_replayed_event(store, event, replaying)
            state = store.load()
            continue
        # Rust's direct agent.spawned records carry the canonical branch and
        # child identity; shadowed replay records use the normal decoder path.
        if event.kind is EventKind.AGENT_SPAWNED:
            correlation = correlate_dispatch_event(state, event)
            if correlation.classification == DISPATCH_ALREADY_CONFIRMED:
                state = _absorb_duplicate_spawn_confirmation(
                    store,
                    state,
                    event,
                    correlation,
                    phase,
                    source,
                    replaying,
                    diagnostics,
                )
                continue
            if correlation.classification != DISPATCH_CORRELATED:
                diagnostics.filtered += 1
                diagnostics.rejected += 1
                LOGGER.warning(
                    "Ignoring %s agent.spawned event run_id=%s event_seq=%s reason=%s",
                    correlation.classification,
                    run_id,
                    event_seq,
                    correlation.reason,
                )
                _record_dispatch_correlation_failure(
                    store,
                    state,
                    event,
                    correlation,
                    config,
                    effects,
                    effects_log,
                )
                _checkpoint_and_ack(store, source, event, state, phase, acknowledge=not replaying)
                if not replaying:
                    diagnostics.acknowledged += 1
                state = store.load()
                continue
            event_slice_id = _event_slice_id(event, state)
            if event_slice_id is None:
                raise TLLoopError("agent.spawned matched an intent but no dispatch slice was found")
            current = state.slices[event_slice_id]
            branch = event.data.get("branch")
            branch = branch if isinstance(branch, str) and branch else current.branch or ""
            agent_type = event.data.get("agent_type")
            agent_type = (
                agent_type
                if isinstance(agent_type, str) and agent_type
                else current.agent_type or "unknown"
            )
            fsm_event = ChildSpawned(ChildHandle(event_slice_id, branch, agent_type))
            try:
                next_phase = phase_transition(phase, fsm_event)
            except IllegalTransition as error:
                raise TLLoopError(str(error)) from error
            next_slices = _confirm_dispatch_event(
                state.slices,
                state.slices,
                event,
                event_slice_id,
                event_seq,
                state.controller_epoch,
            )
            next_slices[event_slice_id] = replace(
                next_slices[event_slice_id],
                branch=branch or next_slices[event_slice_id].branch,
            )
            previous_state = state
            state = store.checkpoint(next_phase, next_slices, state.budgets, checkpoint_seq)
            if not catching_up:
                _emit_slice_status_changes(
                    previous_state.slices,
                    next_slices,
                    config,
                    effects,
                    effects_log,
                )
                _emit_dispatch_confirmation(
                    previous_state.slices,
                    next_slices,
                    event,
                    event_slice_id,
                    config,
                    effects,
                    effects_log,
                    state.controller_epoch,
                )
            if not catching_up:
                state = _apply_convergence(state, convergence, store, config, effects, effects_log)
            _ack_event(source, event, replaying, diagnostics)
            _release_replayed_event(store, event, replaying)
            diagnostics.correlated += 1
            transitions.append(
                LoopTransition(
                    event_seq,
                    event.event_type,
                    _phase_tag(phase),
                    _phase_tag(next_phase),
                )
            )
            if not catching_up:
                _emit_phase_change(run_id, phase, next_phase, config, effects, effects_log)
            phase = next_phase
            if _is_terminal_phase(phase) and not catching_up:
                break
            continue
        try:
            fsm_event = decoder.decode(event)
        except Exception as error:
            raise TLLoopError(str(error)) from error
        if isinstance(
            fsm_event,
            (PublicationObserved, InboxNotificationObserved, RecoveryObserved),
        ):
            # Telemetry-only rows are acknowledged without an FSM transition or
            # slice mutation; the immutable ledger retains their audit payload.
            diagnostics.correlated += 1
            _checkpoint_and_ack(store, source, event, state, phase, acknowledge=not replaying)
            if not replaying:
                diagnostics.acknowledged += 1
            _release_replayed_event(store, event, replaying)
            state = store.load()
            continue
        event_slice_id = _event_slice_id(event, state)
        if (
            isinstance(fsm_event, (PRFiled, PRUpdated))
            and fsm_event.slice_id is None
            and event_slice_id is not None
        ):
            fsm_event = replace(fsm_event, slice_id=event_slice_id)
        # The decoder reads the row's ``agent_id`` to name the child, so a
        # worker row decodes to its runtime agent id. The FSM barrier is keyed
        # by slice, and the resolver above has already proven which slice this
        # row belongs to, so the child is renamed before the transition rather
        # than raising an illegal transition against an unknown child.
        fsm_event = _retarget_child_event(fsm_event, event_slice_id)
        if isinstance(fsm_event, PRMerged):
            aggregate_slice = state.slices.get(event_slice_id or "")
            if (
                aggregate_slice is not None
                and _is_aggregate_slice(aggregate_slice)
                and (
                    aggregate_slice.pr_number is None
                    or fsm_event.pr_number != aggregate_slice.pr_number
                )
            ):
                _record_historical_child_merge(store, event)
                diagnostics.filtered += 1
                _checkpoint_and_ack(store, source, event, state, phase, acknowledge=not replaying)
                if not replaying:
                    diagnostics.acknowledged += 1
                _release_replayed_event(store, event, replaying)
                state = store.load()
                continue
        if _duplicate_event(phase, fsm_event, state):
            diagnostics.filtered += 1
            _checkpoint_and_ack(store, source, event, state, phase, acknowledge=not replaying)
            if not replaying:
                diagnostics.acknowledged += 1
            state = store.load()
            continue
        if isinstance(phase, RecursiveTLRunning) and isinstance(fsm_event, AllChildrenDone):
            next_phase = _complete_legacy_direct_children(phase)
            if next_phase == phase and not phase.parallel_pending:
                next_phase = TLDone()
            if next_phase != phase:
                state = store.checkpoint(
                    next_phase,
                    state.slices,
                    state.budgets,
                    checkpoint_seq,
                )
                _ack_event(source, event, replaying, diagnostics)
                _release_replayed_event(store, event, replaying)
                diagnostics.correlated += 1
                transitions.append(
                    LoopTransition(
                        event_seq,
                        event.event_type,
                        _phase_tag(phase),
                        _phase_tag(next_phase),
                    )
                )
                _emit_phase_change(run_id, phase, next_phase, config, effects, effects_log)
                phase = next_phase
                continue
        if isinstance(fsm_event, (PRFiled, PRUpdated)):
            # Validate ownership and generation against pre-reduction state.
            # The reducer clears publication, handoff, and recovery state, so
            # every refused publication must be stopped here -- not only the
            # historical ones. A same-invocation conflicting PR/head, a wrong
            # owner, or a wrong branch would otherwise mutate the slice before
            # the binder refuses it.
            refusal, historical = _publication_event_rejection(
                state.slices, fsm_event, event, event_slice_id, state.controller_epoch
            )
            if refusal is not None:
                diagnostics.filtered += 1
                if historical:
                    # Generation/historical evidence is retained permanently for
                    # audit; it must never re-enter replay.
                    _quarantine_historical_publication(store, event, refusal)
                    LOGGER.warning(
                        "[TL loop] rejecting historical publication before reduction pr=%s: %s",
                        fsm_event.pr_number,
                        refusal,
                    )
                else:
                    LOGGER.warning(
                        "[TL loop] refusing publication before reduction pr=%s: %s",
                        fsm_event.pr_number,
                        refusal,
                    )
                _checkpoint_and_ack(store, source, event, state, phase, acknowledge=not replaying)
                if not replaying:
                    diagnostics.acknowledged += 1
                # The refusal is durable; only now drop a replayed pending row
                # so a refused event cannot survive in the replay queue.
                _release_replayed_event(store, event, replaying)
                state = store.load()
                continue
        try:
            next_phase = phase_transition(phase, fsm_event)
        except IllegalTransition as error:
            raise TLLoopError(str(error)) from error
        spawn_refusal = _spawn_confirmation_refusal(
            state.slices, event, controller_epoch=state.controller_epoch
        )
        if spawn_refusal == DISPATCH_EPOCH_MISMATCH:
            # A row from a predecessor epoch proves what that generation did,
            # never what this one owns. Retain it as permanent audit evidence on
            # the same terms as a refused publication -- never as pending work,
            # so it cannot re-enter replay -- and let the reducer run without a
            # spawn confirmation so the slice stays untouched.
            _record_historical_spawn(store, event, spawn_refusal)
            LOGGER.warning(
                "[TL loop] retaining spawn row from a prior controller epoch "
                "run_id=%s event_seq=%s run_seq=%s",
                run_id,
                event_seq,
                event.run_seq,
            )
        next_slices = _update_slices(
            state.slices,
            fsm_event,
            slice_id=event_slice_id,
            allow_spawn_confirmation=spawn_refusal is None,
        )
        if isinstance(fsm_event, ChildCompleted):
            completed_slice = next_slices.get(event_slice_id or "")
            next_slices = _apply_child_completion(
                next_slices,
                event_slice_id,
                event,
                persist_publication=(
                    config.parent_run_id is not None
                    or (
                        completed_slice is not None
                        and "/sub_tl/" in (completed_slice.manifest_node_id or "")
                    )
                ),
            )
        if _is_spawn_confirmation_event(event):
            next_slices = _confirm_dispatch_event(
                state.slices,
                next_slices,
                event,
                event_slice_id,
                event_seq,
                state.controller_epoch,
            )
        if isinstance(fsm_event, (PRFiled, PRUpdated)):
            next_slices = _bind_publication_evidence(
                next_slices,
                fsm_event,
                event,
                event_slice_id,
                controller_epoch=state.controller_epoch,
                quarantine=partial(_quarantine_historical_publication, store, event),
                validation_slices=state.slices,
            )
        previous_state = state
        state = store.checkpoint(next_phase, next_slices, state.budgets, checkpoint_seq)
        if not catching_up:
            _emit_slice_status_changes(
                previous_state.slices,
                next_slices,
                config,
                effects,
                effects_log,
            )
            _emit_dispatch_confirmation(
                previous_state.slices,
                next_slices,
                event,
                event_slice_id,
                config,
                effects,
                effects_log,
                state.controller_epoch,
            )
        if (
            isinstance(phase, RecursiveTLRunning)
            and isinstance(fsm_event, ChildSpawned)
            and not transitions
            and isinstance(event.data.get("shadow_event"), Mapping)
            and event.data["shadow_event"].get("kind") == "child_spawned"
            and not catching_up
        ):
            _emit_phase_change(
                run_id,
                TLPlanning(),
                TLWaiting({}),
                config,
                effects,
                effects_log,
            )
        _ack_event(source, event, replaying, diagnostics)
        _release_replayed_event(store, event, replaying)
        diagnostics.correlated += 1
        before_tag = _phase_tag(phase)
        after_tag = _phase_tag(next_phase)
        transitions.append(LoopTransition(event_seq, event.event_type, before_tag, after_tag))
        if not catching_up:
            _emit_phase_change(run_id, phase, next_phase, config, effects, effects_log)
        LOGGER.info(
            "[TL loop] transition run_id=%s event_seq=%d before=%s after=%s",
            run_id,
            event_seq,
            before_tag.value,
            after_tag.value,
        )
        phase = next_phase
        if not catching_up and _reopens_dispatch_pass(plan, config):
            state = _dispatch_children(plan, state, config, effects, effects_log, store)
        if not catching_up:
            state = _apply_convergence(state, convergence, store, config, effects, effects_log)
        if _is_terminal_phase(phase) and not catching_up:
            break
    else:
        if config.test_harness:
            raise LoopLimitExceeded(
                f"event limit {config.max_events} reached before TL reached a terminal phase"
            )
    if not _is_terminal_phase(phase):
        raise TLLoopError("TL controller exited without an authoritative terminal phase")
    if phase is TLFailed:
        reason = next(
            (current.dispatch_error for current in state.slices.values() if current.dispatch_error),
            "TL reached the failed terminal phase",
        )
        store.record_terminal_summary(
            {
                "reason": reason,
                "deadline_reason": None,
                "timeout_seconds": None,
                "diagnostics": diagnostics.snapshot(),
            }
        )
    return TLRunResult(
        state,
        tuple(effects_log),
        tuple(transitions),
        tuple(consumed),
        tuple(heartbeat_events),
        diagnostics.snapshot(),
        _journal_entries(effects_log),
    )


def _apply_convergence(
    state: RunState,
    tracker: ConvergenceTracker,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Run bounded post-reduction convergence until the next effect or wait."""
    if not config.enable_reviewer_spawn:
        decision = derive_next_action(
            state,
            reviewer_max_rounds=tracker.reviewer_max_rounds,
            review_freshness_window_secs=tracker.review_freshness_window_secs,
            now=tracker.review_now,
        )
        if isinstance(decision, ExternalIntent) and decision.operation == "spawn_reviewer":
            tracker.last_decision = Quiescent("reviewer_spawn_disabled")
            return state
    for _ in range(MAX_CONVERGENCE_STEPS):
        try:
            result = tracker.reduce(state)
        except ConvergenceInvariantError as error:
            for event in error.events:
                _record_convergence_event(error.key, event, config, effects, effects_log)
            return _park_repeated_action(
                state,
                error,
                tracker.last_decision,
                store,
                config,
                effects,
                effects_log,
            )
        if isinstance(result.state, RunState) and result.state.state_version > state.state_version:
            state = store.set_state_version(result.state.state_version)
        for event in result.events:
            _record_convergence_event(
                _event_target(event.payload), event, config, effects, effects_log
            )
        if isinstance(result.decision, InternalTransition):
            if result.decision.reason == "review_rounds_exhausted":
                return _park_review_rounds_exhausted(
                    state,
                    store,
                    config,
                    effects,
                    effects_log,
                    tracker.reviewer_max_rounds,
                )
            prior = state
            state = _apply_internal_transition(state, result.decision, store)
            if result.decision.transition == "terminal" or state == prior:
                return state
            continue
        if isinstance(result.decision, ExternalIntent):
            return _execute_external_intent(
                state,
                result.decision,
                tracker,
                store,
                config,
                effects,
                effects_log,
            )
        return state
    raise TLLoopError("convergence did not reach a stable action or wait state")


def _repeated_action_label(decision: MergeDecision | None) -> str:
    if isinstance(decision, ExternalIntent):
        return f"{decision.operation} effect"
    if isinstance(decision, InternalTransition):
        return f"{decision.transition} transition"
    return "controller"


def _park_repeated_action(
    state: RunState,
    error: ConvergenceInvariantError,
    decision: MergeDecision | None,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Park the slice whose identical action repeated without durable progress.

    The livelock detector still fires; this converts its exception into the same
    durable park + named gate every other bounded-failure path uses, instead of
    taking down the whole controller. A repeated action that cannot be isolated
    to a non-terminal slice opens a stable run-level gate and returns, so the
    next cycle can never crash on another repeated action either.
    """
    target_id = error.target
    action_label = _repeated_action_label(decision)
    reason = (
        f"controller detected the same {action_label} proposed twice for "
        f"{target_id or 'the run'} without durable state advancing "
        f"({error.invariant}, action key {error.key}); the underlying effect is "
        "not completing -- inspect the slice reconciliation and any open gate "
        "before resolving"
    )
    target = state.slices.get(target_id) if target_id else None
    if target is None or target.status in {
        SliceStatus.MERGED,
        SliceStatus.FAILED,
        SliceStatus.PARKED,
        SliceStatus.BLOCKED,
    }:
        gate_name = f"{REPEATED_ACTION_GATE_PREFIX}{error.key}"
        existing = next((gate for gate in state.gates if gate.name == gate_name), None)
        if existing is not None and existing.status is not GateStatus.APPROVED:
            # Pending or rejected: already parked. Preserve the operator's
            # answer and do not re-record the same incident.
            return state
        # Absent, or an approved retry repeated: open/re-arm one pending
        # occurrence. Derivation holds the action behind a pending or rejected
        # gate, so an approved retry that fails again needs a fresh decision.
        state = store.set_gate(gate_name, GateStatus.PENDING)
        _record_controller_event(
            "controller",
            "tl.repeated_action_parked",
            {
                "gate_name": gate_name,
                "invariant": error.invariant,
                "action_key": error.key,
                "action": action_label,
                "target_id": target_id,
                "reason": reason,
            },
            config,
            effects,
            effects_log,
        )
        return state
    audit = {
        "invariant": error.invariant,
        "action_key": error.key,
        "action": action_label,
        "target_id": target.id,
        "reason": reason,
        "head_sha": _persisted_slice_head(target),
    }
    if config.active:
        park(
            target,
            ParkCause.REPEATED_ACTION_NO_PROGRESS,
            store=store,
            issue_creator=cast(EffectClient, effects),
            audit=audit,
        )
    else:
        parked = slice_transition(target, SliceStatusChanged(SliceStatus.PARKED))
        parked = replace(
            parked,
            park_cause=ParkCause.REPEATED_ACTION_NO_PROGRESS,
            park_audit=audit,
        )
        store.checkpoint(
            state.fsm,
            {**state.slices, target.id: parked},
            state.budgets,
            state.events.last_consumed_offset,
            current_order=state.current_order,
            ordered_stages=state.ordered_stages,
            integration=state.integration,
        )
    parked_state = store.load()
    _record_controller_event(
        target.id,
        "tl.repeated_action_parked",
        {
            "invariant": error.invariant,
            "action_key": error.key,
            "action": action_label,
            "target_id": target.id,
            "reason": reason,
        },
        config,
        effects,
        effects_log,
    )
    return parked_state


def _drain_direct_scope_convergence(
    state: RunState,
    convergence: ConvergenceTracker,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Advance a direct-leaf/worker scope's internal-only work to a real wait.

    _apply_convergence advances at most one post-merge boundary (or other
    internal) step per call, and its ConvergenceTracker deliberately rejects
    repeating the same action against an unchanged ``state_version`` -- most
    post-merge boundary steps do not bump it. Each step below therefore uses
    its own fresh tracker (the same bounded-drain idiom already used by
    tests exercising this pipeline directly), so a direct-leaf scope with no
    remaining child dispatch to observe can reach TLDone, or a genuine wait,
    within this call instead of only advancing on the next ledger event.
    The caller's shared ``convergence`` tracker is refreshed with the final
    decision so its own wait/Quiescent bookkeeping reflects drained state.

    A fresh tracker per step means the dedup guard that would normally catch
    a non-progressing action repeated against an unchanged state_version
    cannot fire here. This drain owns that check itself instead, comparing
    persisted content (every field but the ``version``/``revision``/
    ``state_version`` write counters, which a checkpoint -- or, for
    state_version, _apply_convergence's own InternalTransition handling --
    can bump even when nothing meaningful changed) before and after each
    step: a step whose content doesn't move is a non-progressing action,
    and raises immediately rather than letting the caller's "no event" poll
    silently re-attempt it forever. A step
    that *does* move content is real progress, so exhausting
    DIRECT_SCOPE_DRAIN_STEP_LIMIT is only a per-call fairness cap -- it
    returns normally, exactly as if the event source had been empty from
    the start, and the next "no event" poll continues draining. A scope
    that legitimately needs more action boundaries than one call's budget
    must never be mistaken for a stuck one.
    """
    for _ in range(DIRECT_SCOPE_DRAIN_STEP_LIMIT):
        decision = derive_next_action(
            state,
            reviewer_max_rounds=convergence.reviewer_max_rounds,
            review_freshness_window_secs=convergence.review_freshness_window_secs,
            now=convergence.review_now,
        )
        if isinstance(decision, Quiescent):
            convergence.last_decision = decision
            return state
        before = replace(state, version=0, revision=0, state_version=0)
        state = _apply_convergence(
            state,
            ConvergenceTracker(
                reviewer_max_rounds=convergence.reviewer_max_rounds,
                review_freshness_window_secs=convergence.review_freshness_window_secs,
                review_now=convergence.review_now,
            ),
            store,
            config,
            effects,
            effects_log,
        )
        if replace(state, version=0, revision=0, state_version=0) == before:
            raise TLLoopError(
                "direct-leaf/worker scope made no progress advancing "
                f"{decision!r}; refusing to retry a non-progressing action"
            )
    convergence.last_decision = derive_next_action(
        state,
        reviewer_max_rounds=convergence.reviewer_max_rounds,
        review_freshness_window_secs=convergence.review_freshness_window_secs,
        now=convergence.review_now,
    )
    return state


def _park_review_rounds_exhausted(
    state: RunState,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    reviewer_max_rounds: int | None,
) -> RunState:
    """Hand the first exhausted direct-review slice to the roles.tl judgment.

    The deterministic worker<->reviewer loop is over for this slice. While the
    slice has roles.tl interventions left, ONE judgment chooses ``guide`` (a
    validated handoff through ``resume_pr`` with a fresh round budget) or
    ``escalate`` (the named human gate). Without interventions left, the gate
    opens. A shadow (inactive) controller only records the gate.
    """
    effective_reviewer_max_rounds = (
        state.reviewer_max_rounds
        if state.reviewer_max_rounds_source is not None
        else reviewer_max_rounds
    )
    target = next(
        (
            current
            for _, current in sorted(state.slices.items())
            if current.verdict is Verdict.NO_GO
            and effective_reviewer_max_rounds is not None
            and current.review_rounds >= effective_reviewer_max_rounds
            and not _is_aggregate_slice(current)
            and current.status
            not in {
                SliceStatus.MERGED,
                SliceStatus.FAILED,
                SliceStatus.PARKED,
                SliceStatus.BLOCKED,
            }
        ),
        None,
    )
    if target is None:
        return state
    if config.active:
        return _judge_review_stuck(
            state, target, store, config, effects, effects_log, effective_reviewer_max_rounds
        )
    return _open_review_stuck_gate(
        state, target, store, config, effects, effects_log, effective_reviewer_max_rounds
    )


def _judge_review_stuck(
    state: RunState,
    target: SliceState,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    reviewer_max_rounds: int | None,
) -> RunState:
    """Make the one bounded roles.tl judgment for a slice that cannot converge."""
    choice = config.tl_model_choice
    if choice is None or config.policy is None:
        raise TLLoopError(
            "review_rounds_exhausted requires config.tl_model_choice and config.policy; "
            "the controller must resolve roles.tl at startup"
        )
    if choice.role != "tl":
        raise TLLoopError("review_stuck judgments must use the roles.tl budget")
    ceiling = config.policy.roles["tl"].escalate_after_attempts
    if target.tl_intervention_attempts >= ceiling:
        LOGGER.info(
            "[TL loop] review stuck slice=%s interventions=%d ceiling=%d; opening the human gate",
            target.id,
            target.tl_intervention_attempts,
            ceiling,
        )
        return _open_review_stuck_gate(
            state, target, store, config, effects, effects_log, reviewer_max_rounds
        )
    # The intervention is charged before the model is called, so a crash between
    # the call and its outcome cannot grant an unbounded number of judgments.
    reserved = replace(target, tl_intervention_attempts=target.tl_intervention_attempts + 1)
    state = store.checkpoint(
        state.fsm,
        {**state.slices, target.id: reserved},
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=state.integration,
    )
    choice.store.ledger.bind(
        choice.role,
        spent=state.budgets.role_spent.get(choice.role, 0),
        budget=config.policy.roles["tl"].token_budget,
        charge_callback=store.charge_role_tokens,
    )
    spent_before = choice.store.ledger.spent.get(choice.role, 0)
    LOGGER.info(
        "[TL loop] review stuck slice=%s pr=%s rounds=%d intervention=%d/%d model=%s",
        target.id,
        target.pr_number,
        target.review_rounds,
        reserved.tl_intervention_attempts,
        ceiling,
        choice.model_id,
    )
    try:
        decision = judge_review_stuck(
            choice,
            evidence=_review_stuck_evidence(target, reviewer_max_rounds),
            owned_paths=target.paths,
        )
    except (RlmError, RepairError, BudgetExceeded, ContextBudgetError) as error:
        LOGGER.error("[TL loop] review-stuck judgment failed slice=%s: %s", target.id, error)
        state = store.load()
        reserved = state.slices.get(target.id)
        if reserved is None:
            raise TLLoopError(f"review-stuck slice {target.id!r} disappeared from run state")
        return _park_repair_failed(
            store,
            state,
            reserved,
            state.events.last_consumed_offset,
            error,
            config,
            effects,
            effects_log,
        )
    state = store.load()
    reserved = state.slices.get(target.id)
    if reserved is None:
        raise TLLoopError(f"review-stuck slice {target.id!r} disappeared from run state")
    _record_controller_event(
        target.id,
        "tl.review_stuck_judged",
        {
            "slice_id": target.id,
            "pr_number": target.pr_number,
            "head_sha": _persisted_slice_head(target),
            "action": decision.action,
            "intervention": reserved.tl_intervention_attempts,
            "ceiling": ceiling,
            "model": choice.model_id,
            "tokens": choice.store.ledger.spent.get(choice.role, 0) - spent_before,
        },
        config,
        effects,
        effects_log,
    )
    if decision.action == "escalate":
        return _open_review_stuck_gate(
            state, reserved, store, config, effects, effects_log, reviewer_max_rounds
        )
    guide = cast(RepairHandoff, decision.handoff)
    state = store.checkpoint(
        state.fsm,
        {**state.slices, target.id: slice_transition(reserved, ReviewRoundsReset())},
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=state.integration,
    )
    return _route_repair(
        store,
        state,
        state.fsm,
        state.events.last_consumed_offset,
        target.id,
        config,
        effects,
        effects_log,
        _guide_repair(guide, store, target.id),
    )


def _review_stuck_evidence(
    target: SliceState, reviewer_max_rounds: int | None
) -> dict[str, object]:
    """The bounded facts the review-stuck judgment may read."""
    return {
        "slice_id": target.id,
        "pr_number": target.pr_number,
        "head_sha": _persisted_slice_head(target),
        "review_rounds": target.review_rounds,
        "reviewer_max_rounds": reviewer_max_rounds,
        "ci_state": dict(target.ci_state),
        "findings_by_head": {
            head: [dict(finding) for finding in findings]
            for head, findings in target.review_findings.items()
        },
    }


def _open_review_stuck_gate(
    state: RunState,
    target: SliceState,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    effective_reviewer_max_rounds: int | None,
) -> RunState:
    """Durably park the slice on ``review_rounds_exhausted`` and open its human gate."""
    audit = {
        "review_rounds": target.review_rounds,
        "reviewer_max_rounds": effective_reviewer_max_rounds,
        "head_sha": _persisted_slice_head(target),
        "pr_number": target.pr_number,
    }
    if config.active:
        park(
            target,
            ParkCause.REVIEW_ROUNDS_EXHAUSTED,
            store=store,
            issue_creator=cast(EffectClient, effects),
            audit=audit,
            create_issue=False,
        )
    else:
        parked = slice_transition(target, ReviewRoundsExhausted())
        parked = replace(
            parked,
            park_cause=ParkCause.REVIEW_ROUNDS_EXHAUSTED,
            park_audit=audit,
        )
        store.checkpoint(
            state.fsm,
            {**state.slices, target.id: parked},
            state.budgets,
            state.events.last_consumed_offset,
            current_order=state.current_order,
            ordered_stages=state.ordered_stages,
            integration=state.integration,
        )
    parked_state = store.load()
    _record_controller_event(
        target.id,
        "tl.review_rounds_exhausted",
        {
            "slice_id": target.id,
            "pr_number": target.pr_number,
            "head_sha": _persisted_slice_head(target),
            "review_rounds": target.review_rounds,
            "reviewer_max_rounds": effective_reviewer_max_rounds,
        },
        config,
        effects,
        effects_log,
    )
    return parked_state


def _apply_internal_transition(
    state: RunState,
    decision: InternalTransition,
    store: RunStore,
) -> RunState:
    """Persist lifecycle changes derived from durable evidence on restart."""
    if decision.transition == "terminal":
        return state
    candidates = tuple(
        current
        for _, current in sorted(state.slices.items())
        if current.status not in {SliceStatus.MERGED, SliceStatus.FAILED}
    )
    target: SliceState | None = None
    if decision.transition == "revalidate_review":
        if decision.target_id is None:
            return state
        target = state.slices.get(decision.target_id)
        if target is None:
            return state
        updated = slice_transition(target, RevalidateReview())
        if updated == target:
            return state
        return store.checkpoint(
            state.fsm,
            {**state.slices, target.id: updated},
            state.budgets,
            state.events.last_consumed_offset,
            current_order=state.current_order,
            ordered_stages=state.ordered_stages,
            integration=state.integration,
        )
    if decision.reason == "head_reset":
        target = next(
            (
                current
                for current in candidates
                if current.reviewed_head is not None
                and _persisted_slice_head(current) is not None
                and current.reviewed_head != _persisted_slice_head(current)
            ),
            None,
        )
        if target is None:
            return state
        updated = slice_transition(target, HeadChanged(None))
        updated = slice_transition(updated, SliceStatusChanged(SliceStatus.IN_REVIEW))
        updated = replace(
            updated,
            dispatch_last_boundary="restart_head_reset",
            dispatch_error=None,
        )
    elif decision.transition == "repairing":
        target = next((current for current in candidates if _slice_has_conflict(current)), None)
        if target is None:
            return state
        updated = slice_transition(target, RepairQueued())
        updated = replace(
            updated,
            dispatch_last_boundary="restart_repair_queued",
            dispatch_error=None,
        )
    else:
        return state
    return _checkpoint_slice_action(store, state, target.id, None, slice_state=updated)


def _persisted_slice_head(current: SliceState) -> str | None:
    """Read the publication/handoff head without importing policy internals."""
    if current.publication is not None:
        return current.publication.head_sha
    if current.handoff is not None:
        return current.handoff.head_sha
    return current.reviewed_head


def _slice_has_conflict(current: SliceState) -> bool:
    """Match the reducer's conflict predicate for transition targeting."""
    if current.dispatch_error is not None and "conflict" in current.dispatch_error.lower():
        return True
    reconciliation = current.reconciliation
    return isinstance(reconciliation, Mapping) and bool(reconciliation.get("conflicts"))


def _execute_external_intent(
    state: RunState,
    intent: ExternalIntent,
    tracker: ConvergenceTracker,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Execute one direct-leaf intent after its durable convergence event."""
    if intent.operation in {"validate_integration", "merge_aggregate", "revalidate_base"}:
        candidate_id = next(
            (
                candidate_id
                for candidate_id, candidate in state.integration.candidates.items()
                if candidate_id == intent.target_id
                or candidate.integration_owner_id == intent.target_id
            ),
            None,
        )
        if candidate_id is None:
            return state
        return _integrate_one_candidate(
            SubTLTask(candidate_id, WorkPlan()),
            state,
            config,
            effects,
            store,
            effects_log,
        )
    if intent.target_id not in state.slices:
        return state
    if intent.operation == "merge":
        return _execute_direct_merge_intent(
            state, intent, tracker, store, config, effects, effects_log
        )
    if intent.operation == "post_merge_recovery":
        return _execute_post_merge_recovery_intent(
            state, intent, store, config, effects, effects_log
        )
    if intent.operation == "repair":
        return _execute_direct_repair_intent(
            state, intent, tracker, store, config, effects, effects_log
        )
    if intent.operation == "spawn_reviewer":
        return _execute_direct_reviewer_intent(
            state, intent, tracker, store, config, effects, effects_log
        )
    return state


def _execute_direct_reviewer_intent(
    state: RunState,
    intent: ExternalIntent,
    tracker: ConvergenceTracker,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Persist and execute a reviewer spawn derived from a direct leaf."""
    if not config.enable_reviewer_spawn:
        return state
    current = state.slices[intent.target_id]
    head_sha = intent.arguments.get("head_sha")
    pr_number = intent.arguments.get("pr_number")
    if not isinstance(head_sha, str) or not isinstance(pr_number, int):
        return state
    contract = _review_contract_for_slice(current)
    requested_digest = intent.arguments.get("review_contract_digest")
    if isinstance(requested_digest, str) and requested_digest != contract.digest:
        raise TLLoopError(
            f"review contract changed for {current.id!r} head {head_sha!r}; "
            "reduction must produce a fresh reviewer action"
        )
    repository_identity = _review_repository_identity(current, state, config, store)
    review_arguments: dict[str, object] = {
        "repository_identity": repository_identity,
        "pr_number": pr_number,
        "head_sha": head_sha,
        "review_contract_digest": contract.digest,
    }
    claimed = replace(
        current,
        reviewer_attempt={**current.reviewer_attempt, head_sha: 1},
        review_contract=contract.as_mapping(),
    )
    action_intent_id = stable_action_key(
        state.run_id, "spawn_reviewer", current.id, review_arguments
    )
    claimed = slice_transition(
        claimed,
        ReviewerDispatched(
            intent_id=action_intent_id,
            head_sha=head_sha,
            attempt=max(1, current.attempts),
            contract_digest=contract.digest,
        ),
    )
    action = claimed.action
    if action is None:
        raise TLLoopError(f"reviewer dispatch did not create an action for {current.id!r}")
    state = _checkpoint_slice_action(
        store,
        state,
        current.id,
        action,
        slice_state=claimed,
    )
    current = state.slices[current.id]
    _record_convergence_event(
        current.id,
        tracker.action_started(state, intent),
        config,
        effects,
        effects_log,
    )
    journal_intent = EffectIntent("spawn_reviewer", current.id, review_arguments, config.active)
    try:
        result = _invoke(
            "spawn_reviewer",
            current.id,
            review_arguments,
            config.active,
            cast(EffectClient, effects) if config.active else None,
            lambda client: client.spawn_reviewer(
                pr_number=pr_number,
                head_sha=head_sha,
                acceptance_criteria=contract.acceptance_criteria,
                force=False,
            ),
            effects_log,
        )
    except EffectFailed as error:
        refreshed = store.load()
        rejected = _checkpoint_slice_action(
            store,
            refreshed,
            current.id,
            replace(action, phase=ActionPhase.REJECTED),
        )
        if not _rejected_because_pr_closed(error):
            raise
        # The pull request was closed while its reviewer was being dispatched.
        # That is an authoritative observation with its own park cause
        # (`PR_CLOSED_UNMERGED`), not a controller failure, so the run stays
        # alive and the PR-state heartbeat classifies it and parks the slice
        # exactly once. Re-raising here failed the whole run instead, and for a
        # nested child that took the parent's sub-TL slice down with it, so the
        # leaf was never parked and never escalated. The action stays journaled
        # as rejected, so the attempt remains auditable.
        return _apply_convergence(rejected, tracker, store, config, effects, effects_log)
    except BaseException as error:
        refreshed = store.load()
        unknown = _checkpoint_slice_action(
            store,
            refreshed,
            current.id,
            replace(action, phase=ActionPhase.UNKNOWN),
        )
        _record_convergence_event(
            current.id,
            tracker.action_outcome(unknown, intent, outcome="unknown", error=str(error)),
            config,
            effects,
            effects_log,
        )
        if isinstance(effects_log, EffectJournal):
            key = effects_log.key_for(journal_intent)
            gate_name = _action_journal_gate_name(key)
            if not any(gate.name == gate_name for gate in unknown.gates):
                store.set_gate(gate_name, GateStatus.PENDING)
        raise
    reviewer_name = (
        result.result.get("reviewer_name")
        if result is not None and isinstance(result.result, Mapping)
        else None
    )
    refreshed = store.load()
    latest = refreshed.slices[current.id]
    updated = slice_transition(
        latest,
        ReviewerIdentityObserved(
            reviewer_name if isinstance(reviewer_name, str) else latest.reviewer_agent_id
        ),
    )
    updated = slice_transition(
        updated,
        ActionChanged(replace(action, phase=ActionPhase.CONFIRMED)),
    )
    return _checkpoint_slice_action(
        store, refreshed, current.id, updated.action, slice_state=updated
    )


def _rejected_because_pr_closed(error: BaseException) -> bool:
    """Whether a refused effect is the forge reporting a closed, unmerged PR.

    The server refuses a reviewer spawn on a PR that is no longer open and
    unmerged, and names the reason in the error. This is the same marker-based
    recognition the ordered-exit classifier already uses, and it is deliberately
    narrow: only the closed-unmerged refusal is an observation the run should
    wait for, and every other refusal still fails the run exactly as before.
    """
    message = str(error).lower()
    return "not open and unmerged" in message and "pr #" in message


def _review_contract_for_slice(current: SliceState) -> ReviewContract:
    if current.review_contract is not None:
        try:
            return ReviewContract.from_mapping(current.review_contract)
        except ValueError as error:
            raise TLLoopError(f"invalid persisted review contract for {current.id!r}") from error
    return compose_review_contract(
        current,
        {"verify": current.test_plan, "boundary": current.paths},
    )


def _review_repository_identity(
    current: SliceState,
    state: RunState,
    config: TLLoopConfig,
    store: RunStore,
) -> dict[str, object]:
    if state.repository_identity is not None:
        owner, repo = repository_api_coordinates(state.repository_identity.remote_url)
        return {
            "owner": owner,
            "repo": repo,
            "base_branch": (
                current.publication.base_branch
                if current.publication is not None
                else current.base_ref or config.branch
            ),
        }
    root = Path(config.project_root or store.root_dir.parent).resolve()
    base_branch = (
        current.publication.base_branch
        if current.publication is not None
        else current.base_ref or config.branch
    )
    return {"owner": "local", "repo": root.name or "project", "base_branch": base_branch}


def _execute_direct_repair_intent(
    state: RunState,
    intent: ExternalIntent,
    tracker: ConvergenceTracker,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Forward the reviewer's findings to the same owner; no model call is made."""
    current = state.slices[intent.target_id]
    reasons = _repair_reasons(current)
    review = {"verdict": Verdict.NO_GO.value, "reasons": reasons}
    _record_convergence_event(
        current.id,
        tracker.action_started(state, intent),
        config,
        effects,
        effects_log,
    )
    return _route_repair(
        store,
        state,
        state.fsm,
        state.events.last_consumed_offset,
        current.id,
        config,
        effects,
        effects_log,
        _forward_findings_repair(review, store, current),
    )


def _execute_post_merge_recovery_intent(
    state: RunState,
    intent: ExternalIntent,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Finish bookkeeping for a merge already adopted by the parent."""
    current = state.slices[intent.target_id]
    if current.status is not SliceStatus.MERGED or current.pr_number is None:
        return state
    journal_id = current.action.intent_id if current.action is not None else None
    if not journal_id and isinstance(current.reconciliation, Mapping):
        persisted_journal_id = current.reconciliation.get("merge_journal_id")
        if isinstance(persisted_journal_id, str) and persisted_journal_id:
            journal_id = persisted_journal_id
    if not journal_id:
        return _block_post_merge_recovery(
            store,
            state,
            current.id,
            "post-merge recovery has no durable merge journal identity",
        )
    merge_evidence = _refresh_post_merge_evidence(current, config, effects)
    result = _reconcile_merged_slice(
        state,
        current.id,
        current.pr_number,
        journal_id,
        config,
        effects,
        store,
        effects_log,
        boundary="post_merge_recovery",
        merge_evidence=merge_evidence,
    )
    return result


def _refresh_post_merge_evidence(
    current: SliceState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
) -> Mapping[str, object] | None:
    """Re-read merged Forgejo identity before recovering an older checkpoint."""
    if current.pr_number is None:
        return None
    if not config.active:
        return None
    try:
        watcher = cast(EffectClient, effects).watcher_pr_state(pr_number=current.pr_number or 0)
    except (ConnectionError, IndexError, OSError, RuntimeError, TimeoutError):
        return None
    observation = _watcher_result_observation(watcher)
    if observation is None:
        return None
    if _watcher_publication_refused(current, watcher) or (
        _watcher_publication_ownership_unresolved(watcher)
    ):
        return None
    return _watcher_merge_evidence(observation)


def _record_confirmed_merge_reconciliation(
    current: SliceState,
    pr_number: int,
    journal_key: str,
    effects_log: list[EffectIntent],
    *,
    boundary: str,
    merge_evidence: Mapping[str, object] | None,
) -> None:
    """Additive journal record for a merge already confirmed by the exact effect.

    The original action result remains intact so merge success and any
    post-merge sync diagnostic stay separately visible.
    """
    if not journal_key or not isinstance(effects_log, EffectJournal):
        return
    entry = next(
        (
            candidate
            for candidate in effects_log.confirmed_entries("merge_pr", current.id)
            if candidate.get("key") == journal_key
        ),
        None,
    )
    if (
        entry is None
        or not _merge_journal_reports_success(entry)
        or not _merge_journal_is_exact(current, entry)
    ):
        return
    arguments = entry.get("arguments")
    if not isinstance(arguments, Mapping):
        return
    expected_pr = arguments.get("pr_number")
    expected_head = arguments.get("expected_head_sha")
    if expected_pr != pr_number or not isinstance(expected_head, str):
        return

    observed = merge_evidence or {}
    watcher_observation = WatcherObservation.from_response(observed)
    watcher_snapshot = any(
        name in observed
        for name in ("head_branch", "publication_ownership_verified", "publication_ownership_error")
    )
    observed_head = observed.get("head_sha")
    if isinstance(observed_head, str) and observed_head and observed_head != expected_head:
        raise TLLoopError("confirmed merge reconciliation head does not match its action journal")
    publication = current.publication
    handoff = current.handoff
    evidence: dict[str, object] = {
        "pr_number": pr_number,
        "head_sha": expected_head,
        "head_branch": (
            observed.get("head_branch")
            or (publication.head_branch if publication is not None else None)
            or current.branch
        ),
        "base_branch": (
            observed.get("base_branch")
            or (publication.base_branch if publication is not None else None)
            or current.base_ref
        ),
        "invocation_id": (
            (publication.invocation_id if publication is not None else None)
            or (handoff.invocation_id if handoff is not None else None)
        ),
    }
    if watcher_snapshot and isinstance(observed.get("merged"), bool):
        evidence["watcher_merged"] = observed["merged"]
    for source, target in (
        ("expected_base_sha", "expected_base_sha"),
        ("expected_patch_digest", "patch_digest"),
        ("expected_merge_tree_sha", "merge_tree_sha"),
    ):
        value = arguments.get(source)
        if isinstance(value, str) and value:
            evidence[target] = value
    if watcher_snapshot:
        observed_base = observed.get("base_sha")
        if isinstance(observed_base, str) and observed_base:
            evidence["observed_base_sha"] = observed_base
    observed_head = observed.get("head_sha")
    if isinstance(observed_head, str) and observed_head:
        evidence["observed_head_sha"] = observed_head
    ownership_verified = watcher_observation.publication_ownership_verified
    if isinstance(ownership_verified, bool):
        evidence.update(publication_ownership_verified=ownership_verified)
    ownership_error = watcher_observation.publication_ownership_error
    if isinstance(ownership_error, str) and ownership_error:
        evidence.update(publication_ownership_error=ownership_error)

    old_record = entry.get("merge_reconciliation")
    old_record = old_record if isinstance(old_record, Mapping) else {}
    old_evidence = old_record.get("evidence")
    old_evidence = old_evidence if isinstance(old_evidence, Mapping) else {}
    for name in (
        "pr_number",
        "head_sha",
        "head_branch",
        "base_branch",
        "invocation_id",
        "expected_base_sha",
        "patch_digest",
        "merge_tree_sha",
    ):
        previous = old_evidence.get(name)
        current_value = evidence.get(name)
        if previous is not None and current_value is not None and previous != current_value:
            raise TLLoopError(f"merge journal reconciliation changed {name}")
    merged_evidence = {**old_evidence, **evidence}

    old_boundaries = old_record.get("boundaries")
    boundaries = (
        [value for value in old_boundaries if isinstance(value, str)]
        if isinstance(old_boundaries, list)
        else []
    )
    if boundary not in boundaries:
        boundaries.append(boundary)
    raw_result = entry.get("result")
    raw_payload = raw_result.get("result") if isinstance(raw_result, Mapping) else None
    effect_result = {
        name: raw_payload[name]
        for name in ("success", "merged", "git_fetched", "message", "next")
        if isinstance(raw_payload, Mapping) and name in raw_payload
    }
    now = _now_timestamp()
    effects_log.resolve_by_key(
        journal_key,
        merge_reconciliation={
            "status": "reconciled_merged",
            "first_recorded_at": old_record.get("first_recorded_at", now),
            "last_recorded_at": now,
            "boundaries": boundaries,
            "evidence": merged_evidence,
            "effect_result": effect_result,
        },
    )


def _reconcile_merged_slice(
    state: RunState,
    slice_id: str,
    pr_number: int,
    merge_journal_id: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    *,
    boundary: str,
    merge_evidence: Mapping[str, object] | None = None,
) -> RunState:
    """Adopt a confirmed merge and execute at most one recovery boundary."""
    current = state.slices[slice_id]
    _record_confirmed_merge_reconciliation(
        current,
        pr_number,
        merge_journal_id,
        effects_log,
        boundary=boundary,
        merge_evidence=merge_evidence,
    )
    checkpoint_needed = False
    if current.post_merge is None or current.post_merge.phase is PostMergePhase.NOT_STARTED:
        try:
            current = _adopt_post_merge_slice(
                current,
                state,
                pr_number,
                merge_journal_id,
                boundary,
                merge_evidence,
            )
        except ValueError as error:
            if state.repository_identity is None and "repository identity is unavailable" in str(
                error
            ):
                # Lazily heal exactly the #1062 gap: identity is resolved the
                # first time a merge adoption actually needs it and finds it
                # missing, not proactively on every continuation (which would
                # fire even for runs that never touch a merged PR). Retried
                # once, immediately, so the adoption below still completes
                # within this same call when the effect succeeds.
                state = _heal_missing_repository_identity(
                    state, config, effects, effects_log, store
                )
                if state.repository_identity is None:
                    return state
                try:
                    current = _adopt_post_merge_slice(
                        current,
                        state,
                        pr_number,
                        merge_journal_id,
                        boundary,
                        merge_evidence,
                    )
                except ValueError as retry_error:
                    return _block_post_merge_recovery(
                        store,
                        state,
                        slice_id,
                        f"cannot adopt merged PR #{pr_number}: {retry_error}",
                    )
            else:
                return _block_post_merge_recovery(
                    store,
                    state,
                    slice_id,
                    f"cannot adopt merged PR #{pr_number}: {error}",
                )
        checkpoint_needed = True
    try:
        integration = _resolve_recovered_lane_integration(state, current, merge_evidence)
    except ValueError as error:
        return _block_post_merge_recovery(
            store,
            state,
            slice_id,
            f"cannot resolve recovered lane for merged PR #{pr_number}: {error}",
        )
    if merge_evidence and current.post_merge is not None:
        try:
            current = _attach_forgejo_merge_evidence(
                current,
                _forgejo_merge_evidence(merge_evidence),
            )
        except ValueError as error:
            return _block_post_merge_recovery(
                store,
                state,
                slice_id,
                f"cannot refresh merged PR #{pr_number} evidence: {error}",
            )
        checkpoint_needed = True
    if integration != state.integration:
        checkpoint_needed = True
    if checkpoint_needed:
        state = _checkpoint_slice_action(
            store,
            state,
            slice_id,
            None,
            slice_state=current,
            integration=integration,
        )
    return _advance_post_merge_boundary(
        store.load(),
        slice_id,
        pr_number,
        config,
        effects,
        effects_log,
        store,
    )


def _heal_missing_repository_identity(
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    """Resolve repository identity the first time a merge adoption needs it.

    Repository identity is static run configuration -- identical for every
    slice, never changing during a run -- so it is resolved once and cached
    on the checkpoint. Persists it on success. On failure, opens the named
    REPOSITORY_IDENTITY_GATE_NAME gate rather than raising or guessing an
    owner/repo (#1062); the caller re-checks state.repository_identity to
    decide whether to retry the adoption that triggered this healing. A
    successful resolution also removes the now-resolved recovery gate.
    """
    resolved, _failure_code = _resolve_repository_identity_detail(config, effects, effects_log)
    if resolved is None:
        return store.set_gate(REPOSITORY_IDENTITY_GATE_NAME)
    try:
        state = store.migrate_repository_identity(
            resolved,
            corroborating_sub_tls=_repository_identity_sub_tl_names(state, store),
        )
    except RepositoryIdentityMigrationError:
        return store.set_gate(REPOSITORY_IDENTITY_GATE_NAME)
    if any(gate.name == REPOSITORY_IDENTITY_GATE_NAME for gate in state.gates):
        state = store.clear_gate(REPOSITORY_IDENTITY_GATE_NAME)
    return state


def _adopt_post_merge_slice(
    current: SliceState,
    state: RunState,
    pr_number: int,
    merge_journal_id: str,
    boundary: str,
    merge_evidence: Mapping[str, object] | None,
) -> SliceState:
    """Turn authoritative merge evidence into the first post-merge state."""
    if type(pr_number) is not int or pr_number <= 0:
        raise ValueError("merged PR number is unavailable in authoritative evidence")
    if not merge_journal_id:
        raise ValueError("merged PR journal identity is unavailable")
    if (
        current.post_merge is not None
        and current.post_merge.phase is not PostMergePhase.NOT_STARTED
    ):
        return replace(
            slice_transition(current, MergeCompleted(pr_number)),
            dispatch_last_boundary=boundary,
        )
    evidence = dict(merge_evidence or {})
    if not evidence and isinstance(current.reconciliation, Mapping):
        evidence = {
            key: current.reconciliation[key]
            for key in (
                "forgejo_pr_number",
                "forgejo_merged",
                "forgejo_head_sha",
                "forgejo_merge_commit_sha",
                "forgejo_merge_commit_tree_sha",
                "prospective_merge_tree_sha",
                "reviewed_pr_head_tree_sha",
            )
            if key in current.reconciliation
        }
    head_sha = _required_merge_identity(
        evidence,
        ("head_sha", "expected_head_sha"),
        "merged PR head SHA",
    )
    expected_base_sha = _required_merge_identity(
        evidence,
        ("base_sha", "expected_base_sha"),
        "merged PR base SHA",
    )
    lane_epoch = _merge_adoption_lane_epoch(state, current, evidence)
    persisted_repository = _repository_identity(state)
    repository = (
        _required_merge_identity(evidence, ("repository",), "merged PR repository")
        if "repository" in evidence
        else persisted_repository
    )
    if repository != persisted_repository:
        raise ValueError("merged PR repository does not match persisted repository identity")
    persisted_parent_branch = _publication_parent_branch_from_slice(current)
    parent_branch = (
        _required_merge_identity(evidence, ("base_branch", "parent_branch"), "parent branch")
        if "base_branch" in evidence or "parent_branch" in evidence
        else persisted_parent_branch
    )
    if parent_branch != persisted_parent_branch:
        raise ValueError("merged PR parent branch does not match persisted publication identity")
    adopted = replace(
        slice_transition(current, MergeCompleted(pr_number)),
        post_merge=None,
    )
    adopted = slice_transition(
        adopted,
        PostMergeEventObserved(
            MergeAdopted(
                child_id=current.id,
                pr_number=pr_number,
                head_sha=head_sha,
                journal_id=merge_journal_id,
                repository=repository,
                parent_branch=parent_branch,
                lane_epoch=lane_epoch,
            )
        ),
    )
    assert adopted.post_merge is not None
    reconciliation = dict(current.reconciliation or {})
    defaults: dict[str, object] = {
        "confirmed_stage": boundary,
        "authoritative_evidence": [],
        "missing_evidence": [],
        "conflicts": [],
        "next_action": "post_merge_recovery",
    }
    for key, default in defaults.items():
        value = reconciliation.get(key)
        if (key in {"confirmed_stage", "next_action"} and not isinstance(value, str)) or (
            key not in {"confirmed_stage", "next_action"} and not isinstance(value, list)
        ):
            reconciliation[key] = default
    authoritative = _forgejo_merge_evidence(evidence)
    reconciliation.update(
        {
            "merge_base_sha": expected_base_sha,
            "merge_head_sha": head_sha,
            "merge_journal_id": merge_journal_id,
        }
    )
    adopted = _attach_forgejo_merge_evidence(adopted, authoritative)
    return replace(
        adopted,
        dispatch_last_boundary=boundary,
        reconciliation=reconciliation,
    )


def _forgejo_merge_evidence(evidence: Mapping[str, object]) -> dict[str, str]:
    """Persist only typed Forgejo fields needed by squash proof validation."""
    result: dict[str, str] = {}
    pr_number = evidence.get("pr_number", evidence.get("forgejo_pr_number"))
    if isinstance(pr_number, str) and pr_number.isdigit():
        pr_number = int(pr_number)
    if type(pr_number) is int and pr_number > 0:
        result["forgejo_pr_number"] = str(pr_number)
    merged = evidence.get("merged", evidence.get("forgejo_merged"))
    if isinstance(merged, str) and merged in {"true", "false"}:
        merged = merged == "true"
    if type(merged) is bool:
        result["forgejo_merged"] = "true" if merged else "false"
    for source, target in (
        ("head_sha", "forgejo_head_sha"),
        ("pr_head_tree_sha", "reviewed_pr_head_tree_sha"),
        ("merge_commit_sha", "forgejo_merge_commit_sha"),
        ("merge_commit_tree_sha", "forgejo_merge_commit_tree_sha"),
        ("merge_tree_sha", "prospective_merge_tree_sha"),
    ):
        value = evidence.get(source, evidence.get(target))
        if isinstance(value, str) and value:
            result[target] = value
    return result


def _attach_forgejo_merge_evidence(current: SliceState, evidence: Mapping[str, str]) -> SliceState:
    """Attach merge-time Forgejo proof and reject identity conflicts."""
    if current.post_merge is None or not evidence:
        return current
    immutable_keys = {
        "forgejo_pr_number",
        "forgejo_merged",
        "forgejo_head_sha",
        "forgejo_merge_commit_sha",
        "forgejo_merge_commit_tree_sha",
        "reviewed_pr_head_tree_sha",
    }
    merged = dict(current.post_merge.evidence)
    for key, value in evidence.items():
        if key == "prospective_merge_tree_sha":
            continue
        if key in immutable_keys:
            previous = merged.get(key)
            if previous is not None and previous != value:
                raise ValueError(f"conflicting refreshed Forgejo evidence for {key}")
        merged[key] = value
    if "prospective_merge_tree_sha" not in merged:
        historical_tree = merged.get(
            "forgejo_merge_commit_tree_sha",
            evidence.get("prospective_merge_tree_sha"),
        )
        if isinstance(historical_tree, str) and historical_tree:
            merged["prospective_merge_tree_sha"] = historical_tree
    post_merge = replace(current.post_merge, evidence=merged)
    return replace(current, post_merge=post_merge)


def _required_merge_identity(
    evidence: Mapping[str, object], keys: tuple[str, ...], name: str
) -> str:
    for key in keys:
        value = evidence.get(key)
        if isinstance(value, str) and value:
            return value
    raise ValueError(f"{name} is unavailable in authoritative merge evidence")


def _merge_adoption_lane_epoch(
    state: RunState,
    current: SliceState,
    evidence: Mapping[str, object],
) -> int:
    value = evidence.get("lane_epoch")
    if value is None:
        try:
            repository, parent_branch = _candidate_lane_key(state, current)
            lane = state.integration.lanes.get(f"{repository}:{parent_branch}")
            value = lane.lane_epoch if lane is not None else 1
        except ValueError:
            value = 1
    if isinstance(value, str) and value.isdigit():
        value = int(value)
    if type(value) is not int or value <= 0:
        raise ValueError("merged PR lane epoch is unavailable")
    return value


def _repository_identity(state: RunState) -> str:
    identity = state.repository_identity
    if identity is None:
        raise ValueError("repository identity is unavailable")
    return identity.remote_url


def _publication_parent_branch_from_slice(current: SliceState) -> str:
    """Use persisted publication identity, then the immutable target branch."""
    if current.publication is not None and current.publication.base_branch:
        return current.publication.base_branch
    if current.base_ref:
        return current.base_ref
    raise ValueError("parent branch is unavailable in persisted slice identity")


def _merge_result_payload(result: ToolResult | None) -> Mapping[str, object] | None:
    if result is None or result.success is not True or not isinstance(result.result, Mapping):
        return None
    return result.result


def _merge_effect_failed(result: ToolResult | None) -> bool:
    """Interpret both the tool envelope and MergePrResponse outcome."""
    if result is None:
        return False
    if result.success is False:
        return True
    return isinstance(result.result, Mapping) and result.result.get("success") is False


def _merge_result_matches_action(
    result: ToolResult | None,
    current: SliceState,
    action: ActionState,
) -> bool:
    """Accept the typed success response, checking optional returned identity."""
    if (
        action.kind is not ActionKind.MERGE
        or action.phase is not ActionPhase.IN_FLIGHT
        or not action.intent_id
        or not action.head_sha
    ):
        return False
    payload = _merge_result_payload(result)
    if payload is None or payload.get("success") is not True:
        return False
    result_head = payload.get("head_sha")
    if result_head is not None and (
        not isinstance(result_head, str) or (result_head and result_head != action.head_sha)
    ):
        return False
    result_branch = payload.get("branch_name")
    return result_branch is None or (
        isinstance(result_branch, str)
        and (not result_branch or current.branch is None or result_branch == current.branch)
    )


def _post_merge_effect(
    operation: str,
    target: str,
    arguments: Mapping[str, object],
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    method: str,
    *,
    active: bool = True,
    call_arguments: Mapping[str, object] | None = None,
    retryable_failure: bool = True,
) -> ToolResult | None:
    callback = getattr(effects, method, None)
    if not callable(callback):
        raise TLLoopError(f"{operation} requires effect {method!r}; no safe fallback exists")
    dispatch_arguments = call_arguments or arguments
    return _invoke(
        operation,
        target,
        arguments,
        active,
        cast(EffectClient, effects),
        lambda client: cast(ToolResult, getattr(client, method)(**dispatch_arguments)),
        effects_log,
        raise_on_failure=False,
        retryable_failure=retryable_failure,
    )


def _checkpoint_post_merge_event(
    store: RunStore,
    state: RunState,
    slice_id: str,
    event: object,
    reconciliation_additions: Mapping[str, object] | None = None,
    lane_event: object | tuple[object, ...] | None = None,
    *,
    expected_revision: int | None = None,
    clear_gates: tuple[str, ...] = (),
    clear_dispatch_error: bool = False,
) -> RunState:
    current = state.slices[slice_id]
    updated = slice_transition(current, PostMergeEventObserved(event))
    if reconciliation_additions:
        reconciliation = dict(updated.reconciliation or {})
        reconciliation.update(reconciliation_additions)
        updated = replace(updated, reconciliation=reconciliation)
    if (
        clear_dispatch_error
        and current.dispatch_error == IDLE_LANE_BOOKKEEPING_ERROR
        and current.dispatch_error_code is None
    ):
        updated = replace(updated, dispatch_error=None, dispatch_error_code=None)
    integration = state.integration
    if lane_event is not None:
        repository, parent_branch = _candidate_lane_key(state, current)
        key = f"{repository}:{parent_branch}"
        lane = integration.lanes.get(key)
        if lane is None:
            raise ValueError(f"lane {key!r} is not reserved for post-merge progress")
        lanes = dict(integration.lanes)
        lane_events = lane_event if isinstance(lane_event, tuple) else (lane_event,)
        for lane_transition_event in lane_events:
            lane = transition_lane(lane, lane_transition_event)
        lanes[key] = lane
        integration = replace(integration, lanes=lanes)
    result = _checkpoint_slice_action(
        store,
        state,
        slice_id,
        None,
        slice_state=updated,
        integration=integration,
        expected_revision=expected_revision,
        clear_gates=clear_gates,
    )
    return result


def _advance_post_merge_boundary(
    state: RunState,
    slice_id: str,
    pr_number: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    """Run one authoritative effect or persist the next pending boundary."""
    current = state.slices[slice_id]
    post_merge = current.post_merge
    if post_merge is None or post_merge.phase is PostMergePhase.COMPLETE:
        return state
    evidence = dict(post_merge.evidence)
    try:
        if post_merge.phase is PostMergePhase.REMOTE_MERGE_ADOPTED:
            return _run_parent_sync(
                state, current, pr_number, evidence, config, effects, effects_log, store
            )
        if post_merge.phase is PostMergePhase.PARENT_BRANCH_SYNCED:
            if current.chainlink_issue_id is None:
                return _resolve_unlinked_changelog(
                    state, current, pr_number, evidence, config, effects, effects_log, store
                )
            issue_id = _required_issue_id(current.chainlink_issue_id)
            intent_id = _post_merge_key(state, "issue_close", current.id, pr_number)
            return _checkpoint_post_merge_event(
                store,
                state,
                slice_id,
                IssueClosePending(current.id, issue_id, intent_id),
            )
        if post_merge.phase is PostMergePhase.ISSUE_CLOSE_PENDING:
            return _run_issue_close(state, current, evidence, config, effects, effects_log, store)
        if post_merge.phase is PostMergePhase.ISSUE_CLOSE_CONFIRMED:
            intent_id = _post_merge_key(state, "changelog", current.id, pr_number)
            return _checkpoint_post_merge_event(
                store,
                state,
                slice_id,
                ChangelogPending(current.id, intent_id, 0),
            )
        if post_merge.phase is PostMergePhase.CHANGELOG_PENDING:
            if post_merge.evidence.get("rebuild_reason") and not post_merge.evidence.get(
                "rebuild_applied"
            ):
                generation = _required_int(
                    post_merge.evidence,
                    "changelog_generation",
                    "changelog generation",
                    allow_zero=True,
                )
                return _checkpoint_post_merge_event(
                    store,
                    state,
                    slice_id,
                    ChangelogPending(
                        current.id,
                        _post_merge_key(
                            state,
                            "changelog_rebuild",
                            current.id,
                            pr_number,
                            generation=generation,
                        ),
                        generation,
                    ),
                )
            return _run_changelog(state, current, evidence, config, effects, effects_log, store)
        if post_merge.phase is PostMergePhase.CHANGELOG_COMMITTED:
            generation = (
                _required_int(
                    post_merge.evidence,
                    "changelog_generation",
                    "changelog generation",
                    allow_zero=True,
                )
                if post_merge.evidence.get("rebuild_reason")
                else None
            )
            operation = "parent_push_rebuild" if generation is not None else "parent_push"
            journal_operation = (
                "parent_push_rebuild_journal" if generation is not None else "parent_push_journal"
            )
            intent_id = _post_merge_key(
                state, operation, current.id, pr_number, generation=generation
            )
            journal_id = _post_merge_key(
                state, journal_operation, current.id, pr_number, generation=generation
            )
            try:
                state, lane_ready = _ensure_bookkeeping_lane(
                    state,
                    current,
                    evidence,
                    store,
                    push_intent_id=intent_id,
                    push_journal_id=journal_id,
                )
            except (TypeError, ValueError) as error:
                return _block_post_merge_recovery(store, state, slice_id, str(error))
            if not lane_ready:
                return state
            current = state.slices[slice_id]
            evidence = dict(current.post_merge.evidence) if current.post_merge else evidence
            lane_epoch = _required_bookkeeping_lane_epoch(state, current)
            return _checkpoint_post_merge_event(
                store,
                state,
                slice_id,
                ParentPushPending(
                    current.id,
                    intent_id,
                    _required_current_base(current),
                    journal_id,
                    lane_epoch,
                ),
                lane_event=LaneBookkeepingStarted(
                    current.id,
                    _required_merge_identity(evidence, ("merge_journal_id",), "merge journal"),
                    intent_id,
                    journal_id,
                    _required_merge_identity(
                        evidence, ("changelog_commit_sha",), "changelog commit"
                    ),
                    _required_current_base(current),
                ),
            )
        if post_merge.phase is PostMergePhase.PARENT_PUSH_PENDING:
            return _run_parent_push(state, current, evidence, config, effects, effects_log, store)
    except IssueCloseRecoveryError as error:
        return _record_issue_close_failure(
            store, state, slice_id, error, config, effects, effects_log
        )
    except CheckpointConflict:
        return store.load()
    except (EffectFailed, TLLoopError, ToolUnavailableError, TypeError, ValueError) as error:
        return _block_post_merge_recovery(store, state, slice_id, str(error))
    return state


def _resolve_unlinked_changelog(
    state: RunState,
    current: SliceState,
    pr_number: int,
    evidence: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    """Judge an unlinked slice's CHANGELOG coverage, write any entry, and complete it.

    The decision is checkpointed before anything is written, so a restart writes
    the judged entry instead of judging again. Every judgment or write failure
    becomes a typed changelog outcome; the slice still completes. A shadow
    controller makes no model call and writes nothing.
    """
    if not config.active:
        return state
    decision = evidence.get("changelog_decision")
    if decision is None:
        return _judge_unlinked_changelog(
            state, current, pr_number, evidence, config, effects, effects_log, store
        )
    if decision != "add_entry":
        detail = (
            str(evidence.get("changelog_decision_reason", "")) if decision != "captured" else ""
        )
        return _complete_unlinked_changelog(
            store,
            state,
            current,
            pr_number,
            evidence,
            str(decision),
            detail,
            config,
            effects,
            effects_log,
        )
    arguments = {
        "child_id": current.id,
        "repository": _required_merge_identity(evidence, ("repository",), "repository"),
        "parent_branch": _required_merge_identity(evidence, ("parent_branch",), "parent branch"),
        "expected_base_sha": _required_merge_identity(
            evidence, ("parent_commit_sha",), "synchronized parent head"
        ),
        "intent_id": _required_merge_identity(
            evidence, ("changelog_judgment_intent_id",), "changelog judgment intent"
        ),
        "section": _required_merge_identity(
            evidence, ("changelog_entry_section",), "changelog entry section"
        ),
        "entry": _required_merge_identity(evidence, ("changelog_entry",), "changelog entry"),
        "working_dir": _relative_process_working_dir(config),
    }
    result = _post_merge_effect(
        "post_merge_changelog_entry",
        current.id,
        arguments,
        effects,
        effects_log,
        "post_merge_changelog_entry",
        active=config.active,
    )
    payload = _merge_result_payload(result)
    if payload is None:
        # The tool reports every Git outcome as a result; only its argument
        # validation fails, which happens before any write.
        error = result.error if result is not None else None
        return _complete_unlinked_changelog(
            store,
            state,
            current,
            pr_number,
            evidence,
            "entry_write_failed",
            error or "changelog entry tool returned no result",
            config,
            effects,
            effects_log,
        )
    outcome = payload.get("outcome")
    if outcome not in {"entry_added", "entry_write_failed", "entry_push_failed"}:
        raise ValueError(f"changelog entry tool returned an unknown outcome {outcome!r}")
    _require_matching_text(payload, arguments, "child_id", "parent_branch", "intent_id")
    commit_sha = payload.get("commit_sha") if outcome == "entry_added" else None
    remote_head = payload.get("observed_remote_head") if outcome == "entry_added" else None
    return _complete_unlinked_changelog(
        store,
        state,
        current,
        pr_number,
        evidence,
        str(outcome),
        str(payload.get("detail") or ""),
        config,
        effects,
        effects_log,
        commit_sha=commit_sha if isinstance(commit_sha, str) else "",
        remote_head=remote_head if isinstance(remote_head, str) else "",
    )


def _judge_unlinked_changelog(
    state: RunState,
    current: SliceState,
    pr_number: int,
    evidence: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    """Read the evidence, make the one roles.tl judgment, and checkpoint the decision."""
    choice = config.tl_model_choice
    if choice is None or config.policy is None:
        raise TLLoopError(
            "changelog_coverage requires config.tl_model_choice and config.policy; "
            "the controller must resolve roles.tl at startup"
        )
    if choice.role != "tl":
        raise TLLoopError("changelog_coverage judgments must use the roles.tl budget")
    intent_id = _post_merge_key(state, "unlinked_changelog", current.id, pr_number)
    merge_commit = evidence.get("forgejo_merge_commit_sha")
    arguments: dict[str, object] = {
        "child_id": current.id,
        "parent_branch": _required_merge_identity(evidence, ("parent_branch",), "parent branch"),
        "expected_base_sha": _required_merge_identity(
            evidence, ("parent_commit_sha",), "synchronized parent head"
        ),
        "pr_number": pr_number,
        "working_dir": _relative_process_working_dir(config),
    }
    if isinstance(merge_commit, str) and merge_commit:
        arguments["merge_commit_sha"] = merge_commit
    try:
        result = _post_merge_effect(
            "post_merge_changelog_context",
            current.id,
            arguments,
            effects,
            effects_log,
            "post_merge_changelog_context",
            active=config.active,
        )
    except (EffectFailed, ToolUnavailableError) as error:
        return _record_unlinked_decision(
            store, state, current, intent_id, "judgment_failed", f"context read failed: {error}"
        )
    context = _merge_result_payload(result)
    if context is None:
        context_error = result.error if result is not None else None
        return _record_unlinked_decision(
            store,
            state,
            current,
            intent_id,
            "judgment_failed",
            f"context read failed: {context_error or 'no result'}",
        )
    if context.get("changelog_present") is not True:
        return _record_unlinked_decision(
            store,
            state,
            current,
            intent_id,
            "no_changelog",
            "the parent branch has no CHANGELOG.md",
        )
    if context.get("unreleased_present") is not True:
        return _record_unlinked_decision(
            store,
            state,
            current,
            intent_id,
            "no_changelog",
            "CHANGELOG.md has no [Unreleased] section",
        )
    role_policy = config.policy.roles["tl"]
    choice.store.ledger.bind(
        choice.role,
        spent=state.budgets.role_spent.get(choice.role, 0),
        budget=role_policy.token_budget,
        charge_callback=store.charge_role_tokens,
    )
    spent_before = choice.store.ledger.spent.get(choice.role, 0)
    judgment_evidence = {
        "pr_number": pr_number,
        "pr_title": context.get("pr_title"),
        "pr_body": context.get("pr_body"),
        "pr_lookup_error": context.get("pr_lookup_error"),
        "changed_paths": context.get("changed_paths"),
        "changed_paths_error": context.get("changed_paths_error"),
        "pr_edited_changelog": context.get("pr_edited_changelog"),
        "unreleased_section": context.get("unreleased_section"),
    }
    try:
        decision = judge_changelog_coverage(choice, evidence=judgment_evidence)
    except (
        RlmError,
        ChangelogCoverageJudgmentError,
        BudgetExceeded,
        ContextBudgetError,
    ) as error:
        state = store.load()
        return _record_unlinked_decision(
            store,
            state,
            current,
            intent_id,
            "judgment_failed",
            f"{type(error).__name__}: {error}",
            model=choice.model_id,
            tokens=choice.store.ledger.spent.get(choice.role, 0) - spent_before,
        )
    state = store.load()
    return _record_unlinked_decision(
        store,
        state,
        current,
        intent_id,
        decision.action,
        decision.reason,
        section=decision.section or "",
        entry=decision.entry or "",
        model=choice.model_id,
        tokens=choice.store.ledger.spent.get(choice.role, 0) - spent_before,
    )


def _record_unlinked_decision(
    store: RunStore,
    state: RunState,
    current: SliceState,
    intent_id: str,
    decision: str,
    reason: str,
    *,
    section: str = "",
    entry: str = "",
    model: str | None = None,
    tokens: int = 0,
) -> RunState:
    LOGGER.info(
        "[TL loop] unlinked changelog slice=%s decision=%s model=%s tokens=%d",
        current.id,
        decision,
        model,
        tokens,
    )
    return _checkpoint_post_merge_event(
        store,
        state,
        current.id,
        UnlinkedChangelogJudged(
            current.id,
            intent_id,
            decision,
            reason or decision,
            section,
            entry,
            model or "",
            tokens,
        ),
    )


def _complete_unlinked_changelog(
    store: RunStore,
    state: RunState,
    current: SliceState,
    pr_number: int,
    evidence: Mapping[str, object],
    outcome: str,
    detail: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    *,
    commit_sha: str = "",
    remote_head: str = "",
) -> RunState:
    """Checkpoint typed completion without releasing a lane the child no longer owns."""
    for _ in range(3):
        state = store.load()
        current = state.slices[current.id]
        if _same_unlinked_completion_is_already_saved(current, outcome, commit_sha, remote_head):
            return state
        proof_error = _unlinked_completion_proof_error(
            state, current, pr_number, effects_log, outcome, commit_sha, remote_head
        )
        if proof_error:
            try:
                return _hold_unlinked_completion(store, state, current.id, proof_error)
            except CheckpointConflict:
                continue
        lane_event, _lane_action, lane_error = _unlinked_completion_lane_decision(state, current)
        if lane_error:
            try:
                return _hold_unlinked_completion(store, state, current.id, lane_error)
            except CheckpointConflict:
                continue
        evidence = current.post_merge.evidence if current.post_merge is not None else evidence
        try:
            completed = _checkpoint_post_merge_event(
                store,
                state,
                current.id,
                PostMergeNotApplicable(current.id, outcome, detail, commit_sha, remote_head),
                lane_event=lane_event,
                expected_revision=state.revision,
                clear_gates=(f"tl-post-merge-{current.id}",),
                clear_dispatch_error=True,
            )
        except CheckpointConflict:
            continue
        except ValueError as error:
            try:
                return _hold_unlinked_completion(
                    store, state, current.id, f"post-merge completion evidence refused: {error}"
                )
            except CheckpointConflict:
                continue
        _record_unlinked_completion_event(
            current,
            pr_number,
            evidence,
            outcome,
            config,
            effects,
            effects_log,
        )
        return completed
    return store.load()


def _same_unlinked_completion_is_already_saved(
    current: SliceState,
    outcome: str,
    commit_sha: str,
    remote_head: str,
) -> bool:
    """Recognize the exact durable terminal result without replaying its effects."""
    post_merge = current.post_merge
    return (
        post_merge is not None
        and post_merge.phase is PostMergePhase.COMPLETE
        and post_merge.evidence.get("issue_close_outcome") == "not_applicable"
        and post_merge.evidence.get("changelog_outcome") == outcome
        and post_merge.evidence.get("changelog_commit_sha", "") == commit_sha
        and post_merge.evidence.get("observed_remote_head", "") == remote_head
    )


def _hold_unlinked_completion(
    store: RunStore,
    state: RunState,
    slice_id: str,
    reason: str,
) -> RunState:
    """Retain lane ownership and the post-merge gate when completion proof fails."""
    return _block_post_merge_recovery(
        store,
        state,
        slice_id,
        f"unlinked post-merge completion held: {reason}",
        preserve_lane=True,
        expected_revision=state.revision,
    )


def _unlinked_completion_lane_decision(
    state: RunState,
    current: SliceState,
) -> tuple[object | None, str, str | None]:
    """Release only the exact active owner; preserve absent and idle lane records."""
    try:
        repository, parent_branch = _candidate_lane_key(state, current)
    except ValueError as error:
        return None, "held", str(error)
    lane = state.integration.lanes.get(f"{repository}:{parent_branch}")
    if lane is None:
        return None, "lane_absent", None
    if lane.phase is LanePhase.IDLE:
        return None, "lane_idle_preserved", _idle_lane_conflict(lane)
    return _active_unlinked_lane_decision(state, current, lane)


def _idle_lane_conflict(lane: LaneState) -> str | None:
    """Reject an idle phase that still claims active ownership coordinates."""
    active_fields = (
        lane.child_id,
        lane.lane_epoch,
        lane.expected_base_sha,
        lane.head_sha,
        lane.merge_journal_id,
        lane.push_intent_id,
        lane.push_journal_id,
        lane.changelog_commit,
    )
    return "idle lane retains active owner coordinates" if any(active_fields) else None


def _active_unlinked_lane_decision(
    state: RunState,
    current: SliceState,
    lane: LaneState,
) -> tuple[object | None, str, str | None]:
    """Require exact child, epoch and merge coordinates before a guarded release."""
    if lane.phase not in {LanePhase.INTEGRATING, LanePhase.BOOKKEEPING}:
        return None, "held", f"lane is unresolved in phase {lane.phase.value}"
    if lane.child_id != current.id:
        return None, "held", f"lane is owned by another child ({lane.child_id or 'unknown'})"
    mismatch = _owned_unlinked_lane_mismatch(state, current, lane)
    if mismatch:
        return None, "held", mismatch
    return LaneBookkeepingNotRequired(current.id), "owned_lane_released", None


def _owned_unlinked_lane_mismatch(
    state: RunState,
    current: SliceState,
    lane: LaneState,
) -> str | None:
    """Validate active lane identity and ensure no pending push remains."""
    evidence = current.post_merge.evidence if current.post_merge is not None else {}
    expected_epoch = _evidence_int(evidence, "lane_epoch", "post-merge lane epoch")
    if lane.lane_epoch != expected_epoch:
        return "active lane epoch conflicts with the retained merge evidence"
    if lane.head_sha != evidence.get("head_sha"):
        return "active lane head conflicts with the retained merge evidence"
    expected_base = current.reconciliation.get("merge_base_sha") if current.reconciliation else None
    if lane.expected_base_sha not in {None, expected_base}:
        return "active lane base conflicts with the retained merge evidence"
    if lane.repository != _repository_identity(state) or lane.parent_branch != evidence.get(
        "parent_branch"
    ):
        return "active lane repository or parent branch conflicts with the merge evidence"
    merge_id = evidence.get("merge_journal_id")
    if lane.merge_journal_id not in {None, merge_id}:
        return "active lane merge journal conflicts with the retained merge evidence"
    if lane.phase is LanePhase.BOOKKEEPING and any(
        (lane.push_intent_id, lane.push_journal_id, lane.changelog_commit)
    ):
        return "active bookkeeping lane retains an unresolved push obligation"
    return None


def _unlinked_completion_proof_error(
    state: RunState,
    current: SliceState,
    pr_number: int,
    effects_log: list[EffectIntent],
    outcome: str,
    commit_sha: str,
    remote_head: str,
) -> str | None:
    """Check the saved parent sync and candidate identity before terminal completion."""
    post_merge = current.post_merge
    if post_merge is None or post_merge.phase is not PostMergePhase.PARENT_BRANCH_SYNCED:
        return "a parent-branch-synced checkpoint is required"
    error = _unlinked_completion_coordinates(state, current, pr_number, post_merge.evidence)
    if error:
        return error
    error = _unlinked_changelog_outcome_error(outcome, commit_sha, remote_head)
    if error:
        return error
    candidate = state.integration.candidates.get(current.id)
    if candidate is None:
        return None
    return _aggregate_completion_sync_error(state, current, pr_number, candidate, effects_log)


def _unlinked_completion_coordinates(
    state: RunState,
    current: SliceState,
    pr_number: int,
    evidence: Mapping[str, object],
) -> str | None:
    """Bind the terminal receipt to this slice's accepted repository and PR."""
    if (
        state.repository_identity is None
        or evidence.get("repository") != state.repository_identity.remote_url
    ):
        return "repository identity is missing or conflicts with the saved merge receipt"
    if evidence.get("child_id") != current.id:
        return "merge receipt child does not match the completing slice"
    if evidence.get("parent_branch") != _publication_parent_branch_from_slice(current):
        return "merge receipt parent branch conflicts with the accepted slice"
    if current.pr_number != pr_number or str(evidence.get("pr_number")) != str(pr_number):
        return "merge receipt PR number conflicts with the completing slice"
    if not evidence.get("head_sha") or not evidence.get("merge_journal_id"):
        return "merge receipt is missing its exact head or journal identity"
    try:
        _required_int(evidence, "lane_epoch", "post-merge lane epoch")
    except ValueError:
        return "merge receipt is missing its lane epoch"
    publication = current.publication
    if publication is not None:
        if publication.pr_number != pr_number:
            return "publication PR number conflicts with the saved merge receipt"
        if publication.head_sha != evidence.get("head_sha"):
            return "publication head conflicts with the saved merge receipt"
        if publication.base_branch != evidence.get("parent_branch"):
            return "publication parent branch conflicts with the saved merge receipt"
    return None


def _unlinked_changelog_outcome_error(
    outcome: str,
    commit_sha: str,
    remote_head: str,
) -> str | None:
    """Reject unsupported or contradictory typed changelog completion evidence."""
    valid = {
        "captured",
        "no_changelog",
        "judgment_failed",
        "entry_added",
        "entry_write_failed",
        "entry_push_failed",
    }
    if outcome not in valid:
        return f"unknown changelog outcome {outcome!r}"
    if outcome == "entry_added" and (
        not commit_sha or not remote_head or commit_sha != remote_head
    ):
        return "entry_added requires matching changelog commit and observed remote head"
    if outcome != "entry_added" and (commit_sha or remote_head):
        return f"{outcome} must not carry changelog commit evidence"
    return None


def _aggregate_completion_sync_error(
    state: RunState,
    current: SliceState,
    pr_number: int,
    candidate: IntegrationCandidateState,
    effects_log: list[EffectIntent],
) -> str | None:
    """Validate aggregate merge and parent-sync receipts for the no-write path."""
    post_merge = current.post_merge
    assert post_merge is not None
    base_sha = candidate.aggregate_original_base_sha
    evidence = post_merge.evidence
    merge_id = evidence.get("merge_journal_id", "")
    if candidate.lifecycle is not IntegrationLifecycle.MERGED:
        return "aggregate candidate is not authoritatively merged"
    if candidate.aggregate_pr_number != pr_number or candidate.aggregate_head_sha != evidence.get(
        "head_sha"
    ):
        return "aggregate candidate PR or head conflicts with the merge receipt"
    if not base_sha or not merge_id:
        return "aggregate merge base or journal identity is missing"
    reconciliation = current.reconciliation
    if not isinstance(reconciliation, Mapping) or reconciliation.get("merge_base_sha") != base_sha:
        return "aggregate accepted base conflicts with its retained merge evidence"
    merge_proof = _verified_aggregate_merge_journal(
        state,
        current,
        candidate,
        pr_number,
        str(evidence.get("head_sha", "")),
        base_sha,
        merge_id,
        effects_log,
    )
    if merge_proof != "verified":
        return f"aggregate merge journal is {merge_proof}"
    return _verified_aggregate_parent_sync(state, current, pr_number, candidate, effects_log)


def _verified_aggregate_parent_sync(
    state: RunState,
    current: SliceState,
    pr_number: int,
    candidate: IntegrationCandidateState,
    effects_log: list[EffectIntent],
) -> str | None:
    """Match the retained sync result to current checkpoint and candidate coordinates."""
    post_merge = current.post_merge
    assert post_merge is not None
    evidence = post_merge.evidence
    reconciliation = current.reconciliation
    if not isinstance(reconciliation, Mapping):
        return "parent synchronization reconciliation evidence is missing"
    expected_base = candidate.aggregate_original_base_sha
    if not expected_base:
        return "aggregate original base is missing from the accepted candidate"
    arguments = _parent_sync_arguments(current, pr_number, evidence, expected_base, None)
    identity = _parent_sync_identity_fields(arguments)
    sync_id = stable_action_key(
        state.run_id, "post_merge_parent_sync_operation", current.id, identity
    )
    history, history_error = _parent_sync_history(effects_log, current.id, sync_id, identity)
    if history_error or not history:
        return history_error or "confirmed parent synchronization journal is missing"
    attempt, operation, entry = max(history, key=lambda record: record[0])
    return _aggregate_parent_sync_entry_error(
        state, current, arguments, sync_id, attempt, operation, entry, reconciliation
    )


def _aggregate_parent_sync_entry_error(
    state: RunState,
    current: SliceState,
    arguments: Mapping[str, object],
    sync_id: str,
    attempt: int,
    operation: str,
    entry: Mapping[str, object],
    reconciliation: Mapping[str, object],
) -> str | None:
    """Validate journal ownership, exact sync receipt and checkpoint projection."""
    entry_arguments = entry.get("arguments")
    if (
        entry.get("run_id") != state.run_id
        or entry.get("target") != current.id
        or operation not in {"post_merge_parent_sync", "post_merge_parent_sync_reconcile"}
        or not isinstance(entry_arguments, Mapping)
    ):
        return "parent synchronization journal has conflicting ownership"
    result = entry.get("result")
    raw = result.get("result") if isinstance(result, Mapping) else None
    if not isinstance(raw, Mapping):
        return "parent synchronization journal has no receipt"
    stable = entry_arguments.get("sync_operation_id") == sync_id
    payload = _validated_sync_payload(raw, arguments, sync_id, attempt, require_correlation=stable)
    if payload.get("sync_outcome") != "confirmed":
        return "parent synchronization journal is not confirmed: " + str(
            payload.get("diagnostic", "unresolved")
        )
    post_merge = current.post_merge
    assert post_merge is not None
    evidence = post_merge.evidence
    recorded_sync_id = evidence.get("sync_operation_id")
    if recorded_sync_id is not None and recorded_sync_id != sync_id:
        return "parent synchronization identity conflicts with the saved receipt"
    recorded_attempt = evidence.get("sync_attempt")
    if recorded_attempt is not None and str(recorded_attempt) != str(attempt):
        return "parent synchronization attempt conflicts with the saved receipt"
    for name, observed in (
        ("parent_commit_sha", evidence.get("parent_commit_sha")),
        ("remote_head_sha", reconciliation.get("remote_head_sha")),
        ("ancestry_proof", reconciliation.get("ancestry_proof")),
    ):
        if payload.get(name) != observed:
            return f"parent synchronization {name} conflicts with its checkpoint projection"
    return None


def _record_unlinked_completion_event(
    current: SliceState,
    pr_number: int,
    evidence: Mapping[str, object],
    outcome: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    """Record the committed terminal disposition after its atomic checkpoint."""
    _record_controller_event(
        current.id,
        "tl.unlinked_changelog_resolved",
        {
            "slice_id": current.id,
            "pr_number": pr_number,
            "decision": str(evidence.get("changelog_decision", "")),
            "outcome": outcome,
            "model": str(evidence.get("changelog_judgment_model", "")),
            "tokens": int(str(evidence.get("changelog_judgment_tokens", "0"))),
        },
        config,
        effects,
        effects_log,
    )


def _drain_post_merge_recovery(
    state: RunState,
    slice_id: str,
    pr_number: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    """Advance checkpointed post-merge edges until an effect blocks or completes."""
    for _ in range(12):
        current = state.slices[slice_id]
        if current.post_merge is None or current.post_merge.phase is PostMergePhase.COMPLETE:
            return state
        before = (current.post_merge.phase, tuple(current.post_merge.evidence.items()))
        state = _advance_post_merge_boundary(
            state, slice_id, pr_number, config, effects, effects_log, store
        )
        current = state.slices[slice_id]
        if current.post_merge is None:
            return state
        after = (current.post_merge.phase, tuple(current.post_merge.evidence.items()))
        if before == after:
            return state
    return state


def _required_issue_id(issue_id: int | None) -> str:
    if type(issue_id) is not int or issue_id <= 0:
        raise ValueError("Chainlink issue ID is unavailable")
    return str(issue_id)


def _post_merge_key(
    state: RunState,
    operation: str,
    child_id: str,
    pr_number: int,
    *,
    generation: int | None = None,
) -> str:
    arguments: dict[str, object] = {"pr_number": pr_number}
    if generation is not None:
        arguments["generation"] = generation
    return stable_action_key(state.run_id, f"post_merge_{operation}", child_id, arguments)


def _run_parent_sync(
    state: RunState,
    current: SliceState,
    pr_number: int,
    evidence: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    arguments, payload = _parent_sync_effect(
        state,
        current,
        pr_number,
        evidence,
        config,
        effects,
        effects_log,
        operation="post_merge_parent_sync",
        expected_base_sha=_required_current_base(current),
    )
    outcome = payload.get("sync_outcome")
    if outcome != "confirmed":
        diagnostic = payload.get("diagnostic")
        phase = payload.get("sync_phase")
        detail = (
            diagnostic if isinstance(diagnostic, str) and diagnostic else "no diagnostic supplied"
        )
        context = f"{outcome or 'unresolved'} during {phase or 'unknown phase'}: {detail}"
        if outcome in {"pre_mutation_refusal", "known_partial_progress"}:
            LOGGER.info("[TL loop] parent synchronization attempt held for retry: %s", context)
            return state
        return _block_post_merge_recovery(
            store,
            state,
            current.id,
            f"parent synchronization requires current Git reconciliation: {context}",
        )
    return _checkpoint_post_merge_event(
        store,
        state,
        current.id,
        ParentBranchSynced(
            current.id,
            cast(str, arguments["parent_branch"]),
            cast(str, payload["parent_commit_sha"]),
        ),
        {
            "remote_head_sha": cast(str, payload["remote_head_sha"]),
            "ancestry_proof": cast(str, payload["ancestry_proof"]),
            **(
                {"remote_name": cast(str, payload["remote_name"])}
                if "remote_name" in payload
                else {}
            ),
        },
    )


def _parent_sync_effect(
    state: RunState,
    current: SliceState,
    pr_number: int,
    evidence: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    *,
    operation: str,
    expected_base_sha: str,
) -> tuple[dict[str, object], Mapping[str, object]]:
    """Run one stable synchronization attempt or reconcile its prior outcome."""
    call_arguments = _parent_sync_arguments(
        current, pr_number, evidence, expected_base_sha, _relative_process_working_dir(config)
    )
    identity = _parent_sync_identity_fields(call_arguments)
    sync_id = stable_action_key(
        state.run_id, "post_merge_parent_sync_operation", current.id, identity
    )
    history, history_error = _parent_sync_history(effects_log, current.id, sync_id, identity)
    if history_error:
        return call_arguments, _unresolved_sync_decision(sync_id, 0, history_error)

    latest = max(history, key=lambda entry: entry[0], default=None)
    latest_mutation = max(
        (entry for entry in history if entry[1] == "post_merge_parent_sync"),
        key=lambda entry: entry[0],
        default=None,
    )
    next_attempt = max((entry[0] for entry in history), default=0) + 1
    if latest is not None:
        attempt, _, entry = latest
        outcome, old_payload = _journal_sync_outcome(entry)
        ready_reconciliation: Mapping[str, object] | None = None
        refusal_payload: Mapping[str, object] | None = None
        refusal_lacks_preconditions = False
        if latest_mutation is not None:
            mutation_entry = latest_mutation[2]
            mutation_outcome, mutation_payload = _journal_sync_outcome(mutation_entry)
            if (
                mutation_outcome == "known_partial_progress"
                and mutation_payload is not None
                and mutation_payload.get("sync_phase") == "fast_forward"
            ):
                refusal_payload = mutation_payload
                refusal_lacks_preconditions = (
                    _parent_sync_refusal_preconditions(
                        mutation_payload, call_arguments.get("parent_branch")
                    )
                    is None
                )
        entry_arguments = entry.get("arguments")
        stable_attempt = (
            isinstance(entry_arguments, Mapping)
            and entry_arguments.get("sync_operation_id") == sync_id
        )
        if outcome == "confirmed" and old_payload is not None and "sync_outcome" not in old_payload:
            old_payload = {**old_payload, "sync_outcome": "confirmed"}
        if stable_attempt and old_payload is not None:
            old_payload = _validated_sync_payload(
                old_payload, call_arguments, sync_id, attempt, require_correlation=True
            )
            observed_outcome = old_payload.get("sync_outcome")
            outcome = observed_outcome if isinstance(observed_outcome, str) else "unresolved"
        if outcome == "confirmed":
            if old_payload is None:
                return call_arguments, _unresolved_sync_decision(
                    sync_id, attempt, "confirmed parent-sync entry has no recoverable result"
                )
            if not stable_attempt:
                old_payload = _validated_sync_payload(
                    old_payload, call_arguments, sync_id, attempt, require_correlation=False
                )
            if old_payload.get("sync_outcome") == "unresolved":
                return call_arguments, old_payload
            identity_error = _confirmed_sync_repository_error(
                call_arguments, config, effects, effects_log
            )
            if identity_error is not None:
                return call_arguments, _unresolved_sync_decision(sync_id, attempt, identity_error)
            reconciled = _run_parent_sync_observation(
                current.id,
                call_arguments,
                sync_id,
                next_attempt,
                effects,
                effects_log,
                config,
            )
            if reconciled.get("sync_outcome") == "confirmed":
                return call_arguments, reconciled
            if reconciled.get("sync_outcome") != "safe_to_retry":
                return call_arguments, reconciled
            ready_reconciliation = reconciled
            outcome = "safe_to_retry"
            next_attempt += 1
        if outcome == "pre_mutation_refusal":
            pass
        elif outcome in {
            "known_partial_progress",
            "safe_to_retry",
            "unknown_interruption",
            "unresolved",
        }:
            reconciliation_was_freshly_started = ready_reconciliation is None
            if ready_reconciliation is None:
                reconciled = _run_parent_sync_observation(
                    current.id,
                    call_arguments,
                    sync_id,
                    next_attempt,
                    effects,
                    effects_log,
                    config,
                )
            else:
                reconciled = ready_reconciliation
            if reconciled.get("sync_outcome") == "confirmed":
                return call_arguments, _validated_sync_payload(
                    reconciled, call_arguments, sync_id, next_attempt, require_correlation=True
                )
            if reconciled.get("sync_outcome") != "safe_to_retry":
                return call_arguments, reconciled
            if refusal_payload is not None:
                if refusal_lacks_preconditions:
                    return call_arguments, _unresolved_sync_decision(
                        sync_id,
                        next_attempt,
                        "prior fast-forward refusal lacks exact preconditions; synchronization remains held",
                    )
                previous_preconditions = _parent_sync_refusal_preconditions(
                    refusal_payload, call_arguments.get("parent_branch")
                )
                current_preconditions = _parent_sync_refusal_preconditions(
                    reconciled, call_arguments.get("parent_branch")
                )
                if current_preconditions is None:
                    return call_arguments, _unresolved_sync_decision(
                        sync_id,
                        next_attempt,
                        "Git reconciliation omitted exact fast-forward refusal preconditions",
                    )
                if current_preconditions == previous_preconditions:
                    return call_arguments, _unresolved_sync_decision(
                        sync_id,
                        next_attempt,
                        "known fast-forward refusal preconditions are unchanged; no mutation was retried",
                    )
            if reconciliation_was_freshly_started:
                next_attempt += 1
        else:
            return call_arguments, _unresolved_sync_decision(
                sync_id, attempt, "prior parent-sync result lacks a recognized outcome"
            )

    return _dispatch_parent_sync_attempt(
        operation,
        current.id,
        call_arguments,
        sync_id,
        next_attempt,
        effects,
        effects_log,
        config,
    )


def _confirmed_sync_repository_error(
    arguments: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> str | None:
    identity, failure = _resolve_repository_identity_detail(config, effects, effects_log)
    if identity is None:
        return f"current repository identity is {failure or 'unavailable'}"
    if identity.remote_url != arguments.get("repository"):
        return "current repository identity differs from the confirmed parent-sync operation"
    return None


def _parent_sync_identity_fields(arguments: Mapping[str, object]) -> dict[str, object]:
    """Keep observations out of the immutable parent-sync identity."""
    return {
        key: arguments[key]
        for key in (
            "child_id",
            "pr_number",
            "repository",
            "parent_branch",
            "merged_head_sha",
            "merge_journal_id",
            "lane_epoch",
        )
    }


def _parent_sync_history(
    effects_log: list[EffectIntent],
    child_id: str,
    sync_id: str,
    identity: Mapping[str, object],
) -> tuple[list[tuple[int, str, Mapping[str, object]]], str | None]:
    """Find this operation's attempts while safely recognizing old journal rows."""
    if not isinstance(effects_log, EffectJournal):
        return [], None
    rows = [
        ("post_merge_parent_sync", entry)
        for entry in effects_log.entries_for("post_merge_parent_sync", child_id)
    ] + [
        ("post_merge_parent_sync_reconcile", entry)
        for entry in effects_log.entries_for("post_merge_parent_sync_reconcile", child_id)
    ]
    matches: list[tuple[int, str, Mapping[str, object]]] = []
    legacy_attempt = 0
    for operation, entry in rows:
        arguments = entry.get("arguments")
        if not isinstance(arguments, Mapping):
            if entry.get("status") in {"intended", "unknown"}:
                return [], "pending synchronization entry has malformed identity arguments"
            continue
        observed_id = arguments.get("sync_operation_id")
        if isinstance(observed_id, str):
            if observed_id != sync_id:
                if entry.get("status") in {"intended", "unknown"}:
                    return (
                        [],
                        "pending synchronization entry conflicts with the current logical operation",
                    )
                continue
        elif operation == "post_merge_parent_sync":
            legacy_attempt += 1
            required = set(identity).difference({"merge_journal_id"})
            if not required.issubset(arguments):
                if entry.get("status") in {"intended", "unknown"}:
                    return (
                        [],
                        "legacy synchronization entry lacks coordinates needed to prove its owner",
                    )
                continue
            if any(str(arguments[key]) != str(identity[key]) for key in required):
                if entry.get("status") in {"intended", "unknown"}:
                    return (
                        [],
                        "legacy synchronization entry conflicts with the current PR or branch identity",
                    )
                continue
        else:
            if entry.get("status") in {"intended", "unknown"}:
                return [], "pending reconciliation entry lacks its stable synchronization identity"
            continue
        raw_attempt = arguments.get("sync_attempt")
        attempt = raw_attempt if type(raw_attempt) is int and raw_attempt > 0 else legacy_attempt
        if attempt <= 0:
            return [], "synchronization attempt number is malformed"
        matches.append((attempt, operation, entry))
    return matches, None


def _parent_sync_refusal_preconditions(
    payload: Mapping[str, object],
    expected_branch: object = None,
) -> dict[str, object] | None:
    """Return the exact safe Git-state coordinates recorded for a refusal."""
    value = payload.get("refusal_preconditions")
    if not isinstance(value, Mapping):
        return None
    required = {
        "parent_branch",
        "remote_name",
        "local_head_sha",
        "remote_head_sha",
        "working_tree_status",
        "local_is_ancestor_remote",
    }
    if set(value) != required:
        return None
    if any(not isinstance(value[key], str) for key in required - {"local_is_ancestor_remote"}):
        return None
    if any(
        not value[key]
        for key in ("parent_branch", "remote_name", "local_head_sha", "remote_head_sha")
    ):
        return None
    if expected_branch is not None and value["parent_branch"] != expected_branch:
        return None
    if type(value["local_is_ancestor_remote"]) is not bool:
        return None
    return {key: value[key] for key in sorted(required)}


def _journal_sync_outcome(
    entry: Mapping[str, object],
) -> tuple[str, Mapping[str, object] | None]:
    """Classify a stored attempt without treating a missing result as rejection."""
    status = entry.get("status")
    if status in {"intended", "unknown"}:
        return "unknown_interruption", None
    raw_result = entry.get("result")
    if not isinstance(raw_result, Mapping):
        return "unresolved", None
    result = raw_result.get("result")
    if not isinstance(result, Mapping):
        return "unresolved", None
    outcome = result.get("sync_outcome")
    if isinstance(outcome, str):
        return outcome, result
    if all(key in result for key in ("parent_commit_sha", "remote_head_sha", "ancestry_proof")):
        return "confirmed", result
    return "unresolved", result


def _run_parent_sync_observation(
    child_id: str,
    arguments: dict[str, object],
    sync_id: str,
    attempt: int,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    config: TLLoopConfig,
) -> Mapping[str, object]:
    """Re-read current Git state before deciding whether an unknown is retryable."""
    stable_arguments = {"sync_operation_id": sync_id, "sync_attempt": attempt}
    result = _post_merge_effect(
        "post_merge_parent_sync_reconcile",
        child_id,
        stable_arguments,
        effects,
        effects_log,
        "post_merge_parent_sync",
        active=config.active,
        call_arguments={
            **_parent_sync_tool_arguments(arguments),
            "sync_operation_id": sync_id,
            "sync_attempt": attempt,
            "reconcile_only": True,
        },
        retryable_failure=False,
    )
    payload = _sync_decision_payload(result, sync_id, attempt)
    if payload is None:
        return _unresolved_sync_decision(
            sync_id, attempt, "Git reconciliation returned malformed evidence"
        )
    return _validated_sync_payload(payload, arguments, sync_id, attempt, require_correlation=True)


def _dispatch_parent_sync_attempt(
    operation: str,
    child_id: str,
    arguments: dict[str, object],
    sync_id: str,
    attempt: int,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    config: TLLoopConfig,
) -> tuple[dict[str, object], Mapping[str, object]]:
    stable_arguments = {"sync_operation_id": sync_id, "sync_attempt": attempt}
    result = _post_merge_effect(
        operation,
        child_id,
        stable_arguments,
        effects,
        effects_log,
        "post_merge_parent_sync",
        active=config.active,
        call_arguments={
            **_parent_sync_tool_arguments(arguments),
            "sync_operation_id": sync_id,
            "sync_attempt": attempt,
            "reconcile_only": False,
        },
        retryable_failure=False,
    )
    payload = _sync_decision_payload(result, sync_id, attempt)
    if payload is None:
        return arguments, _unresolved_sync_decision(
            sync_id, attempt, "parent synchronization returned malformed evidence"
        )
    return arguments, _validated_sync_payload(
        payload, arguments, sync_id, attempt, require_correlation=True
    )


def _sync_decision_payload(
    result: ToolResult | None,
    sync_id: str,
    attempt: int,
) -> Mapping[str, object] | None:
    if result is None or result.success is not True:
        return _unresolved_sync_decision(
            sync_id,
            attempt,
            result.error if result is not None else "synchronization was not dispatched",
        )
    payload = _merge_result_payload(result)
    if payload is None or payload.get("sync_outcome") not in {
        "pre_mutation_refusal",
        "known_partial_progress",
        "unknown_interruption",
        "unresolved",
        "safe_to_retry",
        "confirmed",
    }:
        return None
    return payload


def _parent_sync_tool_arguments(arguments: Mapping[str, object]) -> dict[str, object]:
    """Drop controller-only lineage while retaining the stable opaque identity."""
    return {key: value for key, value in arguments.items() if key != "merge_journal_id"}


def _validate_sync_correlation(payload: Mapping[str, object], sync_id: str, attempt: int) -> None:
    if payload.get("sync_operation_id") != sync_id:
        raise ValueError(
            "parent synchronization response has a different logical operation identity"
        )
    if payload.get("sync_attempt") != attempt:
        raise ValueError("parent synchronization response has a different attempt number")


def _validate_sync_receipt(
    payload: Mapping[str, object],
    arguments: Mapping[str, object],
    sync_id: str,
    attempt: int | None,
) -> Mapping[str, object]:
    for field_name in (
        "child_id",
        "repository",
        "parent_branch",
        "merged_head_sha",
        "expected_base_sha",
        "parent_commit_sha",
        "remote_head_sha",
        "ancestry_proof",
    ):
        value = payload.get(field_name)
        if not isinstance(value, str) or not value:
            raise ValueError(f"parent synchronization receipt is missing {field_name}")
    for field_name in ("pr_number", "lane_epoch"):
        value = payload.get(field_name)
        if type(value) is not int and not (isinstance(value, str) and value.isdigit()):
            raise ValueError(f"parent synchronization receipt is missing {field_name}")
    _require_matching_text(
        payload,
        arguments,
        "child_id",
        "repository",
        "parent_branch",
        "merged_head_sha",
        "expected_base_sha",
    )
    if str(payload["pr_number"]) != str(arguments["pr_number"]):
        raise ValueError("parent synchronization receipt mismatch for pr_number")
    if str(payload["lane_epoch"]) != str(arguments["lane_epoch"]):
        raise ValueError("parent synchronization receipt mismatch for lane_epoch")
    if payload["parent_commit_sha"] != payload["remote_head_sha"]:
        raise ValueError("parent synchronization returned divergent local and remote heads")
    if attempt is not None:
        _validate_sync_correlation(payload, sync_id, attempt)
    if (
        payload["ancestry_proof"]
        != (f"ancestor:{arguments['merged_head_sha']}->{payload['parent_commit_sha']}")
        and "merge_integration_proof" not in payload
    ):
        raise ValueError("parent synchronization returned unverifiable ancestry evidence")
    _validate_parent_sync_proof(payload, arguments, cast(Mapping[str, str], payload))
    return payload


def _validated_sync_payload(
    payload: Mapping[str, object],
    arguments: Mapping[str, object],
    sync_id: str,
    attempt: int,
    *,
    require_correlation: bool,
) -> Mapping[str, object]:
    try:
        if require_correlation:
            _validate_sync_correlation(payload, sync_id, attempt)
        if payload.get("sync_outcome") == "confirmed":
            return _validate_sync_receipt(
                payload,
                arguments,
                sync_id,
                attempt if require_correlation else None,
            )
    except (KeyError, TypeError, ValueError) as error:
        return _unresolved_sync_decision(sync_id, attempt, str(error))
    return payload


def _unresolved_sync_decision(sync_id: str, attempt: int, diagnostic: str) -> Mapping[str, object]:
    return {
        "sync_outcome": "unresolved",
        "sync_phase": "controller_reconciliation",
        "sync_operation_id": sync_id,
        "sync_attempt": attempt,
        "diagnostic": _redact_sync_diagnostic(diagnostic),
    }


def _redact_sync_diagnostic(value: str) -> str:
    """Bound returned process diagnostics and remove common credential forms."""
    safe = re.sub(
        r"(?i)(https?://)[^/@\s]+@",
        r"\1[REDACTED]@",
        re.sub(r"[\x00-\x1f\x7f]+", " ", value),
    )
    safe = re.sub(
        r"(?i)(token|password|authorization)=\S+",
        r"\1=[REDACTED]",
        safe,
    )
    return " ".join(safe.split())[:500]


def _validate_parent_sync_proof(
    payload: Mapping[str, object],
    arguments: Mapping[str, object],
    receipt: Mapping[str, str],
) -> None:
    proof = payload.get("merge_integration_proof")
    if proof is None:
        return
    _validate_structured_merge_proof(
        proof,
        arguments,
        expected_merge_commit=receipt["parent_commit_sha"],
        ancestry=f"ancestor:{arguments['merged_head_sha']}->{receipt['parent_commit_sha']}",
        operation="parent synchronization",
    )


def _validate_remote_reconcile_proof(
    payload: Mapping[str, object],
    arguments: Mapping[str, object],
    receipt: Mapping[str, str],
) -> None:
    proof = payload.get("merge_integration_proof")
    if proof is None:
        if receipt["ancestry_proof"] != (
            f"ancestor:{arguments['merged_head_sha']}->{receipt['rebuilt_commit_sha']}"
        ):
            raise ValueError("remote rebuild receipt has unverifiable merge ancestry")
        return
    _validate_structured_merge_proof(
        proof,
        arguments,
        expected_merge_commit=(
            receipt["rebuilt_commit_sha"]
            if isinstance(proof, Mapping) and proof.get("kind") == "ancestry"
            else arguments["expected_base_sha"]
        ),
        ancestry=f"ancestor:{arguments['merged_head_sha']}->{receipt['rebuilt_commit_sha']}",
        operation="remote rebuild",
    )


def _validate_structured_merge_proof(
    proof: object,
    arguments: Mapping[str, object],
    *,
    expected_merge_commit: object,
    ancestry: str,
    operation: str,
) -> None:
    if not isinstance(proof, Mapping):
        raise TypeError(f"{operation} integration proof is not structured")
    if str(proof.get("pr_number")) != str(arguments["pr_number"]):
        raise ValueError(f"{operation} proof PR binding mismatch")
    if proof.get("pr_head_sha") != arguments["merged_head_sha"]:
        raise ValueError(f"{operation} proof head binding mismatch")
    if proof.get("kind") == "ancestry":
        if proof.get("merge_commit_sha") != expected_merge_commit:
            raise ValueError(f"{operation} ancestry proof merge commit mismatch")
        if proof.get("ancestry") != ancestry:
            raise ValueError(f"{operation} ancestry proof mismatch")
        return
    if proof.get("kind") != "squash":
        raise ValueError(f"{operation} proof kind is unsupported")
    if proof.get("forgejo_merged") is not True:
        raise ValueError(f"{operation} squash proof is not Forgejo-merged")
    required_fields = (
        "forgejo_pr_number",
        "forgejo_head_sha",
        "forgejo_merge_commit_sha",
        "forgejo_merge_commit_tree_sha",
        "prospective_merge_tree_sha",
        "reviewed_pr_head_tree_sha",
    )
    if any(field not in arguments for field in required_fields):
        raise ValueError(f"{operation} squash proof lacks authoritative Forgejo evidence")
    if proof.get("forgejo_pr_number") != arguments["forgejo_pr_number"]:
        raise ValueError(f"{operation} squash proof PR binding mismatch")
    if proof.get("forgejo_head_sha") != arguments["forgejo_head_sha"]:
        raise ValueError(f"{operation} squash proof head binding mismatch")
    if proof.get("forgejo_merge_commit_sha") != arguments["forgejo_merge_commit_sha"]:
        raise ValueError(f"{operation} squash proof merge commit binding mismatch")
    if proof.get("merge_commit_sha") != expected_merge_commit:
        raise ValueError(f"{operation} squash proof merge commit mismatch")
    if arguments["forgejo_merge_commit_sha"] != expected_merge_commit:
        raise ValueError(f"{operation} squash proof expected base is not the Forgejo merge commit")
    reviewed_tree = arguments["reviewed_pr_head_tree_sha"]
    authoritative_tree = arguments["forgejo_merge_commit_tree_sha"]
    prospective_tree = arguments["prospective_merge_tree_sha"]
    if proof.get("reviewed_pr_head_tree_sha") != reviewed_tree:
        raise ValueError(f"{operation} squash proof reviewed tree mismatch")
    if proof.get("pr_head_tree_sha") != reviewed_tree:
        raise ValueError(f"{operation} squash proof PR-head tree mismatch")
    if proof.get("forgejo_merge_commit_tree_sha") != authoritative_tree:
        raise ValueError(f"{operation} squash proof authoritative tree binding mismatch")
    if proof.get("merge_commit_tree_sha") != authoritative_tree:
        raise ValueError(f"{operation} squash proof merge tree mismatch")
    if proof.get("prospective_merge_tree_sha") != prospective_tree:
        raise ValueError(f"{operation} squash proof prospective tree mismatch")
    if authoritative_tree != prospective_tree:
        raise ValueError(
            f"{operation} squash proof found divergent prospective and authoritative merge trees"
        )


def _relative_process_working_dir(config: TLLoopConfig) -> str:
    """Use the calling controller's own worktree as the process working directory.

    ProcessHandler resolves relative paths under the caller's EffectContext worktree.
    ``config.working_dir`` already names that checkout, so converting it relative to
    the project root would append the worktree path a second time. Validate the
    configured checkout boundary, then pass ``.`` to use the existing context root.
    """
    value = config.working_dir
    if value is not None:
        path = Path(value).expanduser()
        if path.is_absolute():
            if config.project_root is None:
                raise TLLoopError(
                    "absolute process working directory requires a project root for validation"
                )
            project_root = Path(config.project_root).expanduser().resolve()
            try:
                path.resolve().relative_to(project_root)
            except ValueError as error:
                raise TLLoopError(
                    "process working directory is outside the configured project root"
                ) from error
        elif ".." in path.parts:
            raise TLLoopError("process working directory must not traverse above the project root")
    return "."


def _parent_sync_arguments(
    current: SliceState,
    pr_number: int,
    evidence: Mapping[str, object],
    expected_base_sha: str,
    working_dir: str | None,
) -> dict[str, object]:
    arguments: dict[str, object] = {
        "child_id": current.id,
        "pr_number": pr_number,
        "repository": _required_merge_identity(evidence, ("repository",), "repository"),
        "parent_branch": _required_merge_identity(evidence, ("parent_branch",), "parent branch"),
        "merged_head_sha": _required_merge_identity(evidence, ("head_sha",), "merged head SHA"),
        "expected_base_sha": expected_base_sha,
        "lane_epoch": _required_int(evidence, "lane_epoch", "lane epoch"),
        "merge_journal_id": _required_merge_identity(
            evidence, ("merge_journal_id",), "merge journal"
        ),
        "working_dir": working_dir,
    }
    forgejo_pr_number = evidence.get("forgejo_pr_number")
    forgejo_merged = evidence.get("forgejo_merged")
    forgejo_head_sha = evidence.get("forgejo_head_sha")
    forgejo_merge_commit_sha = evidence.get("forgejo_merge_commit_sha")
    forgejo_merge_commit_tree_sha = evidence.get("forgejo_merge_commit_tree_sha")
    prospective_tree = evidence.get("prospective_merge_tree_sha")
    reviewed_tree = evidence.get("reviewed_pr_head_tree_sha")
    complete_forgejo_binding = (
        isinstance(forgejo_pr_number, str)
        and forgejo_pr_number.isdigit()
        and isinstance(forgejo_merged, str)
        and forgejo_merged == "true"
        and isinstance(forgejo_head_sha, str)
        and bool(forgejo_head_sha)
        and isinstance(forgejo_merge_commit_sha, str)
        and bool(forgejo_merge_commit_sha)
        and isinstance(forgejo_merge_commit_tree_sha, str)
        and bool(forgejo_merge_commit_tree_sha)
        and isinstance(prospective_tree, str)
        and bool(prospective_tree)
        and isinstance(reviewed_tree, str)
        and bool(reviewed_tree)
    )
    if complete_forgejo_binding:
        arguments.update(
            {
                "forgejo_pr_number": int(forgejo_pr_number),
                "forgejo_merged": True,
                "forgejo_head_sha": forgejo_head_sha,
                "forgejo_merge_commit_sha": forgejo_merge_commit_sha,
                "forgejo_merge_commit_tree_sha": forgejo_merge_commit_tree_sha,
                "prospective_merge_tree_sha": prospective_tree,
                "reviewed_pr_head_tree_sha": reviewed_tree,
            }
        )
    return arguments


def _remote_reconcile_effect(
    current: SliceState,
    pr_number: int,
    evidence: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    *,
    expected_base_sha: str,
) -> tuple[dict[str, object], Mapping[str, str]]:
    """Rebase local bookkeeping onto a new parent base and validate its receipt."""
    arguments = _parent_sync_arguments(
        current, pr_number, evidence, expected_base_sha, _relative_process_working_dir(config)
    )
    result = _post_merge_effect(
        "post_merge_remote_reconcile",
        current.id,
        arguments,
        effects,
        effects_log,
        "post_merge_remote_reconcile",
        active=config.active,
    )
    payload = _required_effect_result(
        result,
        (
            "child_id",
            "pr_number",
            "repository",
            "parent_branch",
            "merged_head_sha",
            "expected_base_sha",
            "lane_epoch",
            "parent_commit_sha",
            "rebuilt_commit_sha",
            "remote_head_sha",
            "new_base_sha",
            "remote_ancestry_proof",
            "ancestry_proof",
        ),
    )
    _require_matching_text(
        payload,
        arguments,
        "child_id",
        "repository",
        "parent_branch",
        "merged_head_sha",
        "expected_base_sha",
    )
    if str(payload["pr_number"]) != str(arguments["pr_number"]):
        raise ValueError("remote rebuild receipt mismatch for pr_number")
    if str(payload["lane_epoch"]) != str(arguments["lane_epoch"]):
        raise ValueError("remote rebuild receipt mismatch for lane_epoch")
    if payload["new_base_sha"] != payload["remote_head_sha"]:
        raise ValueError("remote rebuild receipt has divergent new base and remote head")
    if payload["parent_commit_sha"] != payload["rebuilt_commit_sha"]:
        raise ValueError("remote rebuild receipt has divergent rebuilt commit identities")
    if payload["remote_ancestry_proof"] != (
        f"ancestor:{payload['remote_head_sha']}->{payload['rebuilt_commit_sha']}"
    ):
        raise ValueError("remote rebuild receipt has unverifiable parent ancestry")
    raw_payload = _merge_result_payload(result)
    if raw_payload is None:
        raise ValueError("remote rebuild returned no authoritative receipt")
    payload = _include_selected_remote(payload, raw_payload)
    _validate_remote_reconcile_proof(raw_payload, arguments, payload)
    return arguments, payload


def _run_issue_close(
    state: RunState,
    current: SliceState,
    evidence: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    issue_id = _required_issue_id(current.chainlink_issue_id)
    intent_id = _required_merge_identity(evidence, ("issue_close_intent_id",), "issue-close intent")
    attempt = _evidence_int(evidence, "issue_close_attempt", "issue-close attempt", default=1)
    observed_status = evidence.get("issue_close_retry_observed_status", "open")
    if not isinstance(observed_status, str):
        observed_status = "open"
    arguments: dict[str, object] = {
        "issue_id": int(issue_id),
        "force": True,
        "commit_changelog": False,
    }
    if attempt > 1:
        arguments["retry_attempt"] = attempt
    effect_arguments = {**arguments, "intent_id": intent_id}
    intent = EffectIntent("post_merge_issue_close", current.id, effect_arguments, config.active)
    journal_entry = effects_log.existing(intent) if isinstance(effects_log, EffectJournal) else None
    journal_status = journal_entry.get("status") if journal_entry else None
    if journal_status == "reconciled":
        resolution = journal_entry.get("resolution")
        if (
            isinstance(resolution, Mapping)
            and resolution.get("issue_id") == int(issue_id)
            and resolution.get("status") == "closed"
        ):
            return _accept_already_closed_issue(
                state, current, issue_id, intent_id, store, config, effects, effects_log
            )

    replayable_receipt = _issue_close_entry_has_receipt(journal_entry, issue_id)
    if replayable_receipt:
        result = _post_merge_issue_close_effect(
            current,
            issue_id,
            intent_id,
            attempt,
            observed_status,
            evidence,
            config,
            effects,
            effects_log,
        )
    else:
        observed_status = _chainlink_issue_status(
            current, issue_id, attempt, config, effects, effects_log
        )
        if observed_status is None:
            return state
        if observed_status == "closed":
            _resolve_issue_close_entry(effects_log, intent, issue_id, observed_status)
            updated = _accept_already_closed_issue(
                state, current, issue_id, intent_id, store, config, effects, effects_log
            )
            return _clear_issue_close_gates(store, updated, current.id, intent, effects_log)

        if journal_entry and journal_status in {"intended", "unknown", "reconciled"}:
            _resolve_issue_close_entry(effects_log, intent, issue_id, observed_status)
            current_failure = _evidence_int(
                evidence,
                "issue_close_failure_attempt",
                "issue-close failure attempt",
                default=0,
            )
            if current_failure != attempt:
                failure_generation = (
                    _evidence_int(
                        evidence,
                        "issue_close_failure_generation",
                        "issue-close failure generation",
                        default=0,
                    )
                    + 1
                )
                return _record_issue_close_failure(
                    store,
                    state,
                    current.id,
                    IssueCloseRecoveryError(
                        issue_id,
                        intent_id,
                        attempt,
                        IssueCloseFailureKind.UNKNOWN,
                        "Restart observed the linked issue still open after an unresolved close attempt.",
                        observed_status,
                    ),
                    config,
                    effects,
                    effects_log,
                    failure_generation=failure_generation,
                )

        failure_attempt = _evidence_int(
            evidence,
            "issue_close_failure_attempt",
            "issue-close failure attempt",
            default=0,
        )
        if failure_attempt == attempt:
            failure_generation = _evidence_int(
                evidence,
                "issue_close_failure_generation",
                "issue-close failure generation",
                default=0,
            )
            gate_name = _issue_close_gate_name(current.id, failure_generation)
            gate = next((item for item in state.gates if item.name == gate_name), None)
            if gate is None or gate.status is not GateStatus.APPROVED:
                return state
            state = _checkpoint_post_merge_event(
                store,
                state,
                current.id,
                IssueCloseRetryAuthorized(
                    current.id,
                    issue_id,
                    intent_id,
                    failure_generation,
                    attempt + 1,
                    observed_status,
                ),
            )
            state = store.clear_gate(gate_name)
            current = state.slices[current.id]
            evidence = dict(current.post_merge.evidence) if current.post_merge else evidence
            attempt = _evidence_int(evidence, "issue_close_attempt", "issue-close attempt")
            intent_arguments: dict[str, object] = dict(arguments)
            intent_arguments["retry_attempt"] = attempt
            intent = EffectIntent(
                "post_merge_issue_close",
                current.id,
                {**intent_arguments, "intent_id": intent_id},
                config.active,
            )

        result = _post_merge_issue_close_effect(
            current,
            issue_id,
            intent_id,
            attempt,
            observed_status,
            evidence,
            config,
            effects,
            effects_log,
        )

    if result is None:
        return state
    if result.success is not True:
        failure_kind = (
            IssueCloseFailureKind.UNAVAILABLE
            if result.error_kind == "tool_unavailable"
            else IssueCloseFailureKind.REJECTED
        )
        raise IssueCloseRecoveryError(
            issue_id,
            intent_id,
            attempt,
            failure_kind,
            result.error or "Chainlink rejected the issue-close request.",
            observed_status,
        )
    payload = _required_effect_result(result, ("issue_id", "receipt_id"))
    if str(payload["issue_id"]) != issue_id:
        raise IssueCloseRecoveryError(
            issue_id,
            intent_id,
            attempt,
            IssueCloseFailureKind.UNKNOWN,
            "Issue-close receipt has a different issue ID.",
            observed_status,
        )
    updated = _checkpoint_post_merge_event(
        store,
        state,
        current.id,
        IssueCloseConfirmed(current.id, issue_id, intent_id, payload["receipt_id"]),
    )
    _record_issue_close_outcome(current.id, issue_id, "closed", config, effects, effects_log)
    return _clear_issue_close_gates(store, updated, current.id, intent, effects_log)


def _post_merge_issue_close_effect(
    current: SliceState,
    issue_id: str,
    intent_id: str,
    attempt: int,
    observed_status: str,
    evidence: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> ToolResult | None:
    arguments: dict[str, object] = {
        "issue_id": int(issue_id),
        "force": True,
        "commit_changelog": False,
    }
    if attempt > 1:
        arguments["retry_attempt"] = attempt
    try:
        return _post_merge_effect(
            "post_merge_issue_close",
            current.id,
            {**arguments, "intent_id": intent_id},
            effects,
            effects_log,
            "chainlink_issue_close",
            active=config.active,
            call_arguments={
                "issue_id": int(issue_id),
                "force": True,
                "commit_changelog": False,
                "summary": f"Closed after successful merge of PR #{evidence['pr_number']}",
            },
            retryable_failure=True,
        )
    except ToolUnavailableError as error:
        raise IssueCloseRecoveryError(
            issue_id,
            intent_id,
            attempt,
            IssueCloseFailureKind.UNAVAILABLE,
            str(error),
            observed_status,
        ) from error
    except (ServerTimeout, TimeoutError) as error:
        raise IssueCloseRecoveryError(
            issue_id,
            intent_id,
            attempt,
            IssueCloseFailureKind.TIMEOUT,
            str(error),
            observed_status,
        ) from error
    except ServerUnreachable as error:
        raise IssueCloseRecoveryError(
            issue_id,
            intent_id,
            attempt,
            IssueCloseFailureKind.UNAVAILABLE,
            str(error),
            observed_status,
        ) from error
    except TransportError as error:
        raise IssueCloseRecoveryError(
            issue_id,
            intent_id,
            attempt,
            IssueCloseFailureKind.UNKNOWN,
            str(error),
            observed_status,
        ) from error


def _chainlink_issue_status(
    current: SliceState,
    issue_id: str,
    attempt: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> str | None:
    try:
        result = _invoke(
            "post_merge_issue_status",
            current.id,
            {"issue_id": int(issue_id)},
            config.active,
            cast(EffectClient, effects),
            lambda client: client.chainlink_issue_show(issue_id=int(issue_id)),
            effects_log,
            raise_on_failure=False,
        )
    except ToolUnavailableError as error:
        raise IssueCloseRecoveryError(
            issue_id,
            _post_merge_key_from_slice(current),
            attempt,
            IssueCloseFailureKind.UNAVAILABLE,
            str(error),
        ) from error
    except (ServerTimeout, TimeoutError) as error:
        raise IssueCloseRecoveryError(
            issue_id,
            _post_merge_key_from_slice(current),
            attempt,
            IssueCloseFailureKind.TIMEOUT,
            str(error),
        ) from error
    except ServerUnreachable as error:
        raise IssueCloseRecoveryError(
            issue_id,
            _post_merge_key_from_slice(current),
            attempt,
            IssueCloseFailureKind.UNAVAILABLE,
            str(error),
        ) from error
    except TransportError as error:
        raise IssueCloseRecoveryError(
            issue_id,
            _post_merge_key_from_slice(current),
            attempt,
            IssueCloseFailureKind.UNKNOWN,
            str(error),
        ) from error
    if result is None:
        return None
    if result.success is not True or not isinstance(result.result, Mapping):
        raise IssueCloseRecoveryError(
            issue_id,
            _post_merge_key_from_slice(current),
            attempt,
            IssueCloseFailureKind.UNAVAILABLE,
            result.error or "Chainlink issue status could not be read.",
        )
    observed_id = result.result.get("id")
    if type(observed_id) is not int or str(observed_id) != issue_id:
        raise IssueCloseRecoveryError(
            issue_id,
            _post_merge_key_from_slice(current),
            attempt,
            IssueCloseFailureKind.UNKNOWN,
            "Chainlink issue status returned a different or invalid issue ID.",
        )
    status = result.result.get("status")
    if not isinstance(status, str) or status.lower() not in {"open", "in_progress", "closed"}:
        raise IssueCloseRecoveryError(
            issue_id,
            _post_merge_key_from_slice(current),
            attempt,
            IssueCloseFailureKind.UNKNOWN,
            "Chainlink issue status returned an unsupported status.",
        )
    return status.lower()


def _post_merge_key_from_slice(current: SliceState) -> str:
    if current.post_merge is None:
        raise ValueError("issue-close recovery has no post-merge state")
    return _required_merge_identity(
        current.post_merge.evidence,
        ("issue_close_intent_id",),
        "issue-close intent",
    )


def _issue_close_entry_has_receipt(
    entry: Mapping[str, object] | None,
    issue_id: str,
) -> bool:
    if entry is None or entry.get("status") != "confirmed":
        return False
    raw_result = entry.get("result")
    if not isinstance(raw_result, dict):
        return False
    result = ToolResult.from_raw(cast(JsonObject, raw_result))
    payload = _merge_result_payload(result)
    return bool(
        payload
        and str(payload.get("issue_id")) == issue_id
        and isinstance(payload.get("receipt_id"), str)
        and payload.get("receipt_id")
    )


def _resolve_issue_close_entry(
    effects_log: list[EffectIntent],
    intent: EffectIntent,
    issue_id: str,
    observed_status: str,
) -> None:
    if not isinstance(effects_log, EffectJournal):
        return
    entry = effects_log.existing(intent)
    if entry is None:
        return
    key = entry.get("key")
    if not isinstance(key, str):
        raise TLLoopError("issue-close action journal entry has no stable key")
    effects_log.resolve_by_key(
        key,
        status="reconciled",
        resolution={
            "kind": "chainlink_issue_show",
            "issue_id": int(issue_id),
            "status": observed_status,
        },
    )


def _accept_already_closed_issue(
    state: RunState,
    current: SliceState,
    issue_id: str,
    intent_id: str,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    updated = _checkpoint_post_merge_event(
        store,
        state,
        current.id,
        IssueCloseAlreadyClosed(current.id, issue_id, intent_id, "closed"),
    )
    _record_issue_close_outcome(
        current.id, issue_id, "already_closed", config, effects, effects_log
    )
    return updated


def _record_issue_close_failure(
    store: RunStore,
    state: RunState,
    slice_id: str,
    error: IssueCloseRecoveryError,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    *,
    failure_generation: int | None = None,
) -> RunState:
    current = state.slices[slice_id]
    if current.post_merge is None:
        raise TLLoopError("issue-close failure has no post-merge checkpoint")
    evidence = current.post_merge.evidence
    generation = failure_generation or (
        _evidence_int(
            evidence,
            "issue_close_failure_generation",
            "issue-close failure generation",
            default=0,
        )
        + 1
    )
    updated = _checkpoint_post_merge_event(
        store,
        state,
        slice_id,
        IssueCloseFailed(
            slice_id,
            error.issue_id,
            error.intent_id,
            generation,
            error.failure_kind,
            error.detail[:500],
            error.observed_status,
        ),
    )
    changed = replace(
        slice_transition(updated.slices[slice_id], ActionChanged(None)),
        dispatch_error=error.detail[:500],
    )
    updated = _checkpoint_slice_action(
        store,
        updated,
        slice_id,
        None,
        slice_state=changed,
        integration=_abandon_owned_lane_integration(
            updated, changed, updated.integration, "post_merge_issue_close", error.detail[:500]
        ),
    )
    gate_name = _issue_close_gate_name(slice_id, generation)
    if not any(gate.name == gate_name for gate in updated.gates):
        updated = store.set_gate(gate_name, GateStatus.PENDING)
    _record_issue_close_outcome(
        slice_id, error.issue_id, error.failure_kind.value, config, effects, effects_log
    )
    return updated


def _issue_close_gate_name(slice_id: str, generation: int) -> str:
    return f"tl-post-merge-issue-close-{slice_id}-{generation}"


def _clear_issue_close_gates(
    store: RunStore,
    state: RunState,
    slice_id: str,
    intent: EffectIntent,
    effects_log: list[EffectIntent],
) -> RunState:
    names = {f"tl-post-merge-{slice_id}"}
    if isinstance(effects_log, EffectJournal):
        entry = effects_log.existing(intent)
        if entry is not None:
            key = entry.get("key")
            if isinstance(key, str):
                names.add(
                    _action_journal_gate_name(key, _action_journal_compensation_attempt(entry))
                )
    for gate in state.gates:
        if (
            gate.name.startswith(f"tl-post-merge-issue-close-{slice_id}-")
            and gate.status is GateStatus.PENDING
        ):
            names.add(gate.name)
    for name in sorted(names):
        state = store.clear_gate(name)
    return state


def _record_issue_close_outcome(
    slice_id: str,
    issue_id: str,
    outcome: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    _record_controller_event(
        slice_id,
        "tl.issue_close_outcome",
        {"slice_id": slice_id, "issue_id": int(issue_id), "outcome": outcome},
        config,
        effects,
        effects_log,
    )


def _run_changelog(
    state: RunState,
    current: SliceState,
    evidence: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    issue_id = _required_issue_id(current.chainlink_issue_id)
    intent_id = _required_merge_identity(evidence, ("changelog_intent_id",), "changelog intent")
    generation = _required_int(
        evidence, "changelog_generation", "changelog generation", allow_zero=True
    )
    arguments = {
        "child_id": current.id,
        "issue_id": int(issue_id),
        "repository": _required_merge_identity(evidence, ("repository",), "repository"),
        "parent_branch": _required_merge_identity(evidence, ("parent_branch",), "parent branch"),
        "expected_base_sha": _required_current_base(current),
        "generation": generation,
        "intent_id": intent_id,
        "working_dir": _relative_process_working_dir(config),
    }
    result = _post_merge_effect(
        "post_merge_changelog",
        current.id,
        arguments,
        effects,
        effects_log,
        "post_merge_changelog",
        active=config.active,
    )
    payload = _required_effect_result(
        result,
        (
            "child_id",
            "issue_id",
            "repository",
            "parent_branch",
            "expected_base_sha",
            "generation",
            "intent_id",
            "commit_sha",
        ),
    )
    _require_matching_text(
        payload,
        arguments,
        "child_id",
        "repository",
        "parent_branch",
        "expected_base_sha",
        "intent_id",
    )
    if str(payload["issue_id"]) != str(arguments["issue_id"]):
        raise ValueError("changelog receipt mismatch for issue_id")
    if str(payload["generation"]) != str(arguments["generation"]):
        raise ValueError("changelog receipt mismatch for generation")
    updated = _checkpoint_post_merge_event(
        store,
        state,
        current.id,
        ChangelogCommitted(current.id, intent_id, payload["commit_sha"]),
    )
    return updated


def _run_parent_push(
    state: RunState,
    current: SliceState,
    evidence: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    try:
        state, lane_ready = _ensure_bookkeeping_lane(state, current, evidence, store)
    except (TypeError, ValueError):
        return state
    if not lane_ready:
        return state
    current = state.slices[current.id]
    arguments = {
        "child_id": current.id,
        "repository": _required_merge_identity(evidence, ("repository",), "repository"),
        "parent_branch": _required_merge_identity(evidence, ("parent_branch",), "parent branch"),
        "lane_epoch": _required_int(evidence, "lane_epoch", "lane epoch"),
        "push_intent_id": _required_merge_identity(
            evidence, ("parent_push_intent_id",), "push intent"
        ),
        "push_journal_id": _required_merge_identity(evidence, ("push_journal_id",), "push journal"),
        "expected_base_sha": _required_merge_identity(
            evidence, ("expected_base_sha",), "push base SHA"
        ),
        "pushed_commit": _required_merge_identity(
            evidence, ("changelog_commit_sha",), "changelog commit"
        ),
        "working_dir": _relative_process_working_dir(config),
    }
    result = _post_merge_effect(
        "post_merge_push",
        current.id,
        arguments,
        effects,
        effects_log,
        "post_merge_push",
        active=config.active,
        retryable_failure=False,
    )
    if result is None or result.success is not True:
        return _recover_remote_advance(
            state,
            current,
            pr_number=int(evidence["pr_number"]),
            evidence=evidence,
            push_arguments=arguments,
            failed_result=result,
            config=config,
            effects=effects,
            effects_log=effects_log,
            store=store,
        )
    payload = _required_effect_result(
        result,
        (
            "repository",
            "parent_branch",
            "child_id",
            "lane_epoch",
            "push_intent_id",
            "push_journal_id",
            "push_receipt_id",
            "expected_base_sha",
            "pushed_commit",
            "observed_remote_head",
            "ancestry_proof",
        ),
    )
    _require_matching_text(payload, arguments, "repository", "parent_branch", "child_id")
    for key in (
        "lane_epoch",
        "push_intent_id",
        "push_journal_id",
        "expected_base_sha",
        "pushed_commit",
    ):
        if str(payload[key]) != str(arguments[key]):
            raise ValueError(f"parent-push receipt mismatch for {key}")
    if payload["observed_remote_head"] != payload["pushed_commit"]:
        raise ValueError("parent-push receipt observed a different remote head")
    if payload["ancestry_proof"] != (
        f"ancestor:{payload['pushed_commit']}->{payload['observed_remote_head']}"
    ):
        raise ValueError("parent-push receipt has unverifiable ancestry evidence")
    lane_epoch = payload["lane_epoch"]
    if isinstance(lane_epoch, str) and lane_epoch.isdigit():
        lane_epoch = int(lane_epoch)
    receipt = PushReceipt(
        repository=payload["repository"],
        parent_branch=payload["parent_branch"],
        child_id=payload["child_id"],
        lane_epoch=_positive_int(lane_epoch, "lane epoch"),
        push_intent_id=payload["push_intent_id"],
        push_journal_id=payload["push_journal_id"],
        push_receipt_id=payload["push_receipt_id"],
        expected_base_sha=payload["expected_base_sha"],
        pushed_commit=payload["pushed_commit"],
        observed_remote_head=payload["observed_remote_head"],
        ancestry_proof=payload["ancestry_proof"],
    )
    return _checkpoint_post_merge_event(
        store,
        state,
        current.id,
        PostMergeComplete(
            current.id,
            evidence["merge_journal_id"],
            arguments["push_intent_id"],
            arguments["pushed_commit"],
            receipt,
        ),
        lane_event=LaneReleased(current.id, receipt),
    )


def _recover_remote_advance(
    state: RunState,
    current: SliceState,
    pr_number: int,
    evidence: Mapping[str, object],
    push_arguments: Mapping[str, object],
    failed_result: ToolResult | None,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    """Reconcile a stale parent push into a fresh bookkeeping generation."""
    failure = failed_result.error if failed_result is not None else None
    if not _is_remote_advance_failure(failure):
        raise ValueError(failure or "parent push returned no authoritative result")
    expected_base_sha = push_arguments.get("expected_base_sha")
    if not isinstance(expected_base_sha, str) or not expected_base_sha:
        raise ValueError("failed parent push has no expected base SHA")
    _, payload = _remote_reconcile_effect(
        current,
        pr_number,
        evidence,
        config,
        effects,
        effects_log,
        expected_base_sha=expected_base_sha,
    )
    observed_remote_head = payload["remote_head_sha"]
    if observed_remote_head == expected_base_sha:
        raise ValueError("parent push failed without authoritative remote advancement")
    generation = (
        _required_int(evidence, "changelog_generation", "changelog generation", allow_zero=True) + 1
    )
    failed_push_result = failure or "parent push failed"
    reason = f"parent push compare-and-swap rejected after remote advancement: {failed_push_result}"
    rebuilt = PostMergeRebuildRequested(
        current.id,
        generation,
        str(push_arguments["push_intent_id"]),
        str(push_arguments["push_journal_id"]),
        failed_push_result,
        observed_remote_head,
        observed_remote_head,
        payload["ancestry_proof"],
        reason,
    )
    rebuilt_slice = slice_transition(current, PostMergeEventObserved(rebuilt))
    rebuilt_intent = _post_merge_key(
        state,
        "changelog_rebuild",
        current.id,
        pr_number,
        generation=generation,
    )
    committed_slice = slice_transition(
        rebuilt_slice,
        PostMergeEventObserved(
            ChangelogCommitted(
                current.id,
                rebuilt_intent,
                payload["rebuilt_commit_sha"],
            )
        ),
    )
    repository, parent_branch = _candidate_lane_key(state, current)
    lane_key = f"{repository}:{parent_branch}"
    lane = state.integration.lanes.get(lane_key)
    prior_epoch = (
        lane.lane_epoch if lane is not None else _required_int(evidence, "lane_epoch", "lane epoch")
    )
    next_epoch = prior_epoch + 1
    if committed_slice.post_merge is None:
        raise ValueError("remote rebuild did not preserve post-merge state")
    rebuilt_evidence = dict(committed_slice.post_merge.evidence)
    rebuilt_evidence["lane_epoch"] = str(next_epoch)
    rebuilt_evidence["expected_base_sha"] = observed_remote_head
    if "remote_name" in payload:
        rebuilt_evidence["remote_name"] = payload["remote_name"]
    committed_slice = replace(
        committed_slice,
        post_merge=replace(
            committed_slice.post_merge,
            evidence=rebuilt_evidence,
        ),
    )
    reconciliation = dict(committed_slice.reconciliation or {})
    reconciliation.update(
        {
            "remote_head_sha": observed_remote_head,
            "merge_base_sha": observed_remote_head,
        }
    )
    lane_for_rebuild = lane or LaneState(repository, parent_branch)
    lane_events: tuple[object, ...] = (
        (LaneRecoveryRequested(reason),) if lane is not None else ()
    ) + (
        LaneReserved(current.id, next_epoch, observed_remote_head),
        LaneIntegrationStarted(current.id, payload["rebuilt_commit_sha"]),
    )
    rebuilt_lane = lane_for_rebuild
    for lane_event in lane_events:
        rebuilt_lane = transition_lane(rebuilt_lane, lane_event)
    return _checkpoint_slice_action(
        store,
        state,
        current.id,
        None,
        slice_state=replace(committed_slice, reconciliation=reconciliation),
        integration=replace(
            state.integration,
            lanes={
                **state.integration.lanes,
                lane_key: rebuilt_lane,
            },
        ),
    )


def _is_remote_advance_failure(error: str | None) -> bool:
    """Recognize only server errors that identify a stale compare-and-swap base."""
    if not error:
        return False
    normalized = error.lower()
    return any(marker in normalized for marker in REMOTE_ADVANCE_FAILURE_MARKERS)


def _required_effect_result(
    result: ToolResult | None, fields: tuple[str, ...]
) -> Mapping[str, str]:
    payload = _merge_result_payload(result)
    if payload is None:
        raise ValueError("post-merge effect returned no authoritative success receipt")
    values: dict[str, str] = {}
    for field_name in fields:
        value = payload.get(field_name)
        if isinstance(value, str) and value:
            values[field_name] = value
        elif (
            field_name in {"lane_epoch", "pr_number", "issue_id", "generation"}
            and type(value) is int
        ):
            values[field_name] = str(value)
        else:
            raise ValueError(f"post-merge effect receipt is missing {field_name}")
    return values


def _include_selected_remote(
    receipt: Mapping[str, str], raw_payload: Mapping[str, object]
) -> Mapping[str, str]:
    """Retain current selected-remote evidence while accepting legacy receipts."""
    if "remote_name" not in raw_payload:
        return receipt
    remote_name = raw_payload["remote_name"]
    if (
        not isinstance(remote_name, str)
        or not remote_name
        or remote_name.startswith("-")
        or any(char.isspace() or char == "\x00" for char in remote_name)
    ):
        raise ValueError("post-merge receipt has an invalid selected remote name")
    return {**receipt, "remote_name": remote_name}


def _require_matching_text(
    payload: Mapping[str, object], arguments: Mapping[str, object], *fields: str
) -> None:
    for field_name in fields:
        if payload.get(field_name) != arguments.get(field_name):
            raise ValueError(f"post-merge receipt mismatch for {field_name}")


def _required_current_base(current: SliceState) -> str:
    reconciliation = current.reconciliation
    value = None
    if isinstance(reconciliation, Mapping):
        for key in ("remote_head_sha", "merge_base_sha"):
            candidate = reconciliation.get(key)
            if isinstance(candidate, str) and candidate:
                value = candidate
                break
    if value is None:
        raise ValueError("merged PR base SHA is unavailable")
    return value


def _required_int(
    evidence: Mapping[str, object], key: str, name: str, *, allow_zero: bool = False
) -> int:
    value = evidence.get(key)
    if isinstance(value, str) and value.isdigit():
        value = int(value)
    minimum = 0 if allow_zero else 1
    if type(value) is not int or value < minimum:
        raise ValueError(f"{name} is unavailable")
    return value


def _evidence_int(
    evidence: Mapping[str, object],
    key: str,
    name: str,
    *,
    default: int | None = None,
) -> int:
    value = evidence.get(key)
    if value is None and default is not None:
        return default
    if isinstance(value, str) and value.isdigit():
        value = int(value)
    if type(value) is not int or value < 0:
        raise ValueError(f"{name} is unavailable")
    return value


def _positive_int(value: object, name: str) -> int:
    if type(value) is not int or value <= 0:
        raise ValueError(f"{name} must be a positive integer")
    return value


def _block_post_merge_recovery(
    store: RunStore,
    state: RunState,
    slice_id: str,
    reason: str,
    *,
    preserve_lane: bool = False,
    expected_revision: int | None = None,
) -> RunState:
    bounded = reason[:500]
    blocked = replace(
        slice_transition(state.slices[slice_id], ActionChanged(None)),
        dispatch_error=bounded,
    )
    blocked_state = _checkpoint_slice_action(
        store,
        state,
        slice_id,
        None,
        slice_state=blocked,
        integration=(
            state.integration
            if preserve_lane
            else _abandon_owned_lane_integration(
                state, blocked, state.integration, "post_merge_gate", bounded
            )
        ),
        expected_revision=expected_revision,
    )
    gate_name = f"tl-post-merge-{slice_id}"
    gate = next(
        (candidate for candidate in blocked_state.gates if candidate.name == gate_name), None
    )
    if gate is None:
        return store.set_gate(gate_name, GateStatus.PENDING)
    return blocked_state


def _execute_direct_merge_intent(
    state: RunState,
    intent: ExternalIntent,
    tracker: ConvergenceTracker,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Compare, journal, merge, and re-read one direct PR before adoption."""
    current = state.slices[intent.target_id]
    if current.pr_number is None or not config.active:
        return state
    live = cast(EffectClient, effects)
    watcher = _invoke(
        "watcher_pr_state",
        current.id,
        {"pr_number": current.pr_number},
        True,
        live,
        lambda client: client.watcher_pr_state(pr_number=current.pr_number or 0),
        effects_log,
        raise_on_failure=False,
    )
    if _watcher_publication_refused(current, watcher):
        LOGGER.warning(
            "[TL loop] refusing direct merge for %s: publication provenance mismatch",
            current.id,
        )
        return state
    if _watcher_publication_ownership_unresolved(watcher):
        # The reconciliation path parks unresolved ownership; a destructive
        # direct merge must apply the same gate rather than proceed on
        # unverified watcher evidence.
        LOGGER.warning(
            "[TL loop] refusing direct merge for %s: publication ownership unresolved",
            current.id,
        )
        return state
    if (
        watcher is not None
        and watcher.success is True
        and (_watcher_result_observation(watcher) is not None)
        and _watcher_result_observation(watcher).merged is True
    ):
        observation = _watcher_result_observation(watcher)
        return _reconcile_merged_slice(
            store.load(),
            current.id,
            current.pr_number,
            current.action.intent_id if current.action is not None else "",
            config,
            effects,
            store,
            effects_log,
            boundary="direct_merge_adopted",
            merge_evidence=_watcher_merge_evidence(observation),
        )
    if (
        watcher is not None
        and watcher.success is True
        and isinstance(watcher.result, Mapping)
        and not _direct_compare_evidence_complete(watcher)
    ):
        reason = (
            "direct merge requires complete watcher evidence: "
            "base_sha, head_sha, patch_digest, merge_tree_sha, and ci_status"
        )
        previous_gate = next(
            (gate for gate in state.gates if gate.name == INTEGRITY_RECONCILIATION_GATE_NAME),
            None,
        )
        state = _clear_action_for_reduction(store, state, current.id)
        state = store.set_gate(INTEGRITY_RECONCILIATION_GATE_NAME, GateStatus.PENDING)
        if previous_gate is None or previous_gate.status is not GateStatus.PENDING:
            _record_controller_event(
                "controller",
                "tl.gate_opened",
                {
                    "gate_name": INTEGRITY_RECONCILIATION_GATE_NAME,
                    "run_id": state.run_id,
                    "reason": reason,
                },
                config,
                effects,
                effects_log,
            )
        return state
    freshness_window_secs = (
        load_freshness_window(config.review_policy_path)
        if config.review_policy_path is not None
        else None
    )
    if current.verdict is not None and verdict_is_stale(
        current,
        now=config.review_clock() if config.review_clock is not None else None,
        freshness_window_secs=freshness_window_secs,
    ):
        return _request_review_revalidation(
            state,
            current,
            store,
            reason="pre_merge_review_validation_expired",
        )
    evidence = _direct_merge_evidence(current, watcher, config)
    if evidence is None:
        return _clear_action_for_reduction(store, state, current.id)
    if state.repository_identity is None:
        state = _heal_missing_repository_identity(state, config, effects, effects_log, store)
        if state.repository_identity is None:
            return state
        current = state.slices[current.id]
    state, lane_ready = _ensure_candidate_lane(state, current, evidence["base_sha"], store)
    if not lane_ready:
        return state
    state, lane_ready = _start_candidate_lane(
        state, state.slices[current.id], evidence["head_sha"], store
    )
    if not lane_ready:
        return state
    current = state.slices[current.id]
    arguments = {
        "pr_number": current.pr_number,
        "expected_base_sha": evidence["base_sha"],
        "expected_head_sha": evidence["head_sha"],
        "expected_patch_digest": evidence["patch_digest"],
        "expected_merge_tree_sha": evidence["merge_tree_sha"],
    }
    action = ActionState(
        ActionKind.MERGE,
        ActionPhase.IN_FLIGHT,
        intent_id=stable_action_key(state.run_id, "merge_pr", current.id, arguments),
        head_sha=cast(str, evidence["head_sha"]),
        attempt=max(1, current.attempts),
    )
    state = _checkpoint_slice_action(store, state, current.id, action)
    _record_convergence_event(
        current.id,
        tracker.action_started(state, intent),
        config,
        effects,
        effects_log,
    )
    try:
        merge_result = _invoke(
            "merge_pr",
            current.id,
            arguments,
            True,
            live,
            lambda client: client.merge_pr(
                pr_number=current.pr_number or 0,
                strategy=config.merge_strategy,
                working_dir=_relative_process_working_dir(config),
                expected_base_sha=cast(str, evidence["base_sha"]),
                expected_head_sha=cast(str, evidence["head_sha"]),
                expected_patch_digest=cast(str, evidence["patch_digest"]),
                expected_merge_tree_sha=cast(str, evidence["merge_tree_sha"]),
            ),
            effects_log,
            raise_on_failure=False,
        )
    except ToolUnavailableError:
        raise
    except (ConnectionError, OSError, RuntimeError, TimeoutError) as error:
        return _reconcile_unknown_merge(
            state,
            intent,
            action,
            arguments,
            error,
            tracker,
            store,
            config,
            effects,
            effects_log,
        )
    return _adopt_direct_merge_result(
        state,
        current.id,
        action,
        merge_result,
        store,
        config,
        effects,
        effects_log,
    )


def _derive_eligible_integration_after_nonmerge(
    integration: IntegrationRuntimeState,
    slice_id: str,
) -> IntegrationRuntimeState:
    """Return one candidate to an integration-eligible lifecycle after a
    disproved merge attempt.

    A rejected or non-confirmed merge leaves the candidate at ``MERGING`` while
    its action is cleared. Without this edge the candidate waits forever for a
    merge event that no longer exists. ``MERGE_NOT_CONFIRMED`` is the typed
    retirement edge back to ``READY_FOR_INTEGRATION`` so the normal aggregate
    approval/integration path can derive a fresh, evidence-bound attempt. Only
    the exact ``MERGING`` lifecycle is moved; every other lifecycle is left for
    its own owner to reconcile.

    Retiring an attempt also advances the candidate's merge-attempt counter, so
    the next approved attempt gets a distinct action identity instead of
    colliding with the journal entry just retired. This is applied uniformly on
    the startup retirement pass and every live non-merge resolution.

    An impossible transition is a bug, not a recoverable state: it is raised
    rather than swallowed, so the caller never clears the action and bumps the
    counter while leaving the candidate stuck at ``MERGING``.
    """
    if _candidate_runtime(integration, slice_id).lifecycle is not IntegrationLifecycle.MERGING:
        return integration
    transitioned = _transition_candidate_runtime(
        integration, slice_id, IntegrationTransition.MERGE_NOT_CONFIRMED
    )
    runtime = _candidate_runtime(transitioned, slice_id)
    return _persist_candidate_runtime(
        transitioned, slice_id, replace(runtime, merge_attempts=runtime.merge_attempts + 1)
    )


def _resolve_nonmerged_merge(
    state: RunState,
    slice_id: str,
    store: RunStore,
    effects_log: list[EffectIntent],
    *,
    journal_key: str | None,
    diagnostic: str,
    terminal: bool = False,
) -> RunState:
    """Clear a disproved merge and release its durable integration lane."""
    refreshed = store.load()
    current = refreshed.slices[slice_id]
    cleared = slice_transition(current, ActionChanged(None))
    if terminal:
        cleared = slice_transition(cleared, SliceStatusChanged(SliceStatus.PARKED))
        cleared = replace(
            cleared,
            park_cause=ParkCause.HUMAN_DECISION_REQUIRED,
            dispatch_error=diagnostic[:500],
        )
    integration = _abandon_owned_lane_integration(
        refreshed,
        cleared,
        refreshed.integration,
        "merge_not_confirmed",
        diagnostic,
    )
    if not terminal:
        integration = _derive_eligible_integration_after_nonmerge(integration, slice_id)
    updated = _checkpoint_slice_action(
        store,
        refreshed,
        slice_id,
        None,
        slice_state=cleared,
        integration=integration,
    )
    if journal_key and isinstance(effects_log, EffectJournal):
        try:
            status = "rejected" if terminal else "compensated"
            effects_log.resolve_by_key(
                journal_key,
                status=status,
                result={
                    "success": False,
                    "result": {"merged": False, "reconciled": True},
                    "error": diagnostic,
                },
                error=diagnostic,
            )
        except ActionJournalError:
            LOGGER.info(
                "[TL loop] merge journal key=%s was already absent during non-merge recovery",
                journal_key,
            )
    return store.load() if updated != refreshed else updated


def _merge_recovery_gate_name(state: RunState, current: SliceState) -> str:
    """Return an occurrence-scoped gate for a journal-less merge attempt."""
    intent_id = (
        current.action.intent_id
        if current.action is not None and current.action.intent_id
        else "missing-intent"
    )
    attempt = (
        current.action.attempt
        if current.action is not None and current.action.attempt is not None
        else current.attempts
    )
    lane_epoch: int | None = None
    try:
        repository, parent_branch = _candidate_lane_key(state, current)
        lane = state.integration.lanes.get(f"{repository}:{parent_branch}")
        if lane is not None and lane.lane_epoch is not None:
            lane_epoch = lane.lane_epoch
    except ValueError:
        pass
    occurrence = {
        "attempt": attempt,
        "intent_id": intent_id,
        "lane_epoch": lane_epoch,
        "slice_id": current.id,
    }
    encoded = json.dumps(occurrence, sort_keys=True, separators=(",", ":"))
    digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
    return f"{MERGE_RECOVERY_GATE_PREFIX}{digest}"


def _reconcile_merge_recovery_gate(
    state: RunState,
    current: SliceState,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> tuple[RunState, bool]:
    """Resolve a journal-less unknown merge through an explicit operator gate."""
    gate_name = _merge_recovery_gate_name(state, current)
    gate = next((item for item in state.gates if item.name == gate_name), None)
    if gate is None:
        return store.set_gate(gate_name, GateStatus.PENDING), True
    if gate.status is GateStatus.PENDING:
        return state, True
    return (
        _resolve_nonmerged_merge(
            state,
            current.id,
            store,
            effects_log,
            journal_key=None,
            diagnostic=(
                "operator approved a fresh merge attempt"
                if gate.status is GateStatus.APPROVED
                else "operator abandoned journal-less unknown merge"
            ),
            terminal=gate.status is GateStatus.REJECTED,
        ),
        True,
    )


def _reconcile_unknown_merge(
    state: RunState,
    intent: ExternalIntent,
    action: ActionState,
    arguments: Mapping[str, object],
    error: BaseException,
    tracker: ConvergenceTracker,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Probe Forgejo after a lost merge response before leaving an unknown intent."""
    current = state.slices[intent.target_id]
    watcher = _invoke(
        "watcher_pr_state",
        current.id,
        {"pr_number": current.pr_number or 0},
        config.active,
        cast(EffectClient, effects) if config.active else None,
        lambda client: client.watcher_pr_state(pr_number=current.pr_number or 0),
        effects_log,
        raise_on_failure=False,
    )
    observation = _watcher_result_observation(watcher)
    # A present-but-refused or ownership-unresolved publication record may not
    # resolve the unknown merge in either direction; fall through to the
    # unknown-outcome path that retains the action.
    refused = observation is not None and publication_refused(
        current, observation, observation.head_sha, None
    )
    unresolved = _watcher_publication_ownership_unresolved(watcher)
    if (
        watcher is not None
        and watcher.success is True
        and observation is not None
        and observation.merged
        and not refused
        and not unresolved
    ):
        if isinstance(effects_log, EffectJournal):
            key = stable_action_key(state.run_id, "merge_pr", current.id, arguments)
            effects_log.resolve_by_key(
                key,
                status="confirmed",
                result={"success": True, "result": {"merged": True, "reconciled": True}},
            )
        refreshed = store.load()
        return _reconcile_merged_slice(
            refreshed,
            current.id,
            current.pr_number or 0,
            action.intent_id,
            config,
            effects,
            store,
            effects_log,
            boundary="direct_merge_reconciled",
            merge_evidence={
                **arguments,
                **_watcher_merge_evidence(observation),
            },
        )
    if (
        watcher is not None
        and watcher.success is True
        and observation is not None
        and observation.merged is False
        and observation.pr_number in {None, current.pr_number}
        and not refused
        and not unresolved
    ):
        diagnostic = "authoritative watcher state says the merge did not happen"
        key = stable_action_key(state.run_id, "merge_pr", current.id, arguments)
        updated = _resolve_nonmerged_merge(
            state,
            current.id,
            store,
            effects_log,
            journal_key=key,
            diagnostic=diagnostic,
        )
        _record_convergence_event(
            current.id,
            tracker.action_outcome(updated, intent, outcome="rejected", error=diagnostic),
            config,
            effects,
            effects_log,
        )
        return updated
    refreshed = store.load()
    unknown = replace(action, phase=ActionPhase.UNKNOWN)
    lane_integration = _recover_owned_lane_integration(
        refreshed,
        refreshed.slices[current.id],
        refreshed.integration,
        "direct merge outcome is unknown",
    )
    updated = _checkpoint_slice_action(
        store,
        refreshed,
        current.id,
        unknown,
        integration=lane_integration,
    )
    _record_convergence_event(
        current.id,
        tracker.action_outcome(updated, intent, outcome="unknown", error=str(error)),
        config,
        effects,
        effects_log,
    )
    return updated


def _direct_compare_evidence_complete(watcher: ToolResult) -> bool:
    observation = _watcher_result_observation(watcher)
    if observation is None:
        return False
    return all(
        isinstance(getattr(observation, key), str) and bool(getattr(observation, key))
        for key in ("base_sha", "head_sha", "patch_digest", "merge_tree_sha", "ci_status")
    )


def _watcher_merge_evidence(observation: object) -> dict[str, object]:
    """Copy only authoritative Forgejo merge evidence from a watcher snapshot."""
    if observation is None:
        return {}
    values: dict[str, object] = {}
    for name in (
        "pr_number",
        "head_sha",
        "base_sha",
        "base_branch",
        "head_branch",
        "merged",
        "publication_ownership_verified",
        "publication_ownership_error",
        "pr_head_tree_sha",
        "merge_tree_sha",
        "merge_commit_sha",
        "merge_commit_tree_sha",
    ):
        value = getattr(observation, name, None)
        if value is not None:
            values[name] = value
    return values


def _direct_merge_evidence(
    current: SliceState,
    watcher: ToolResult | None,
    config: TLLoopConfig,
) -> dict[str, str] | None:
    """Validate the watcher snapshot used as the direct merge compare."""
    if watcher is None:
        return None
    observation = _watcher_result_observation(watcher)
    if observation is None:
        return None
    head_sha = observation.head_sha or ""
    evidence = {
        "base_sha": observation.base_sha,
        "head_sha": head_sha,
        "patch_digest": observation.patch_digest,
        "merge_tree_sha": observation.merge_tree_sha,
    }
    if any(not isinstance(value, str) or not value for value in evidence.values()):
        return None
    if observation.ci_status not in {"success", "neutral"}:
        return None
    try:
        freshness_window_secs = (
            load_freshness_window(config.review_policy_path)
            if config.review_policy_path is not None
            else None
        )
        verify_review(
            current,
            head_sha,
            now=config.review_clock() if config.review_clock is not None else None,
            freshness_window_secs=freshness_window_secs,
            current_patch_digest=evidence["patch_digest"],
        )
    except ReviewGateError:
        return None
    return cast(dict[str, str], evidence)


def _adopt_direct_merge_result(
    state: RunState,
    slice_id: str,
    action: ActionState,
    result: ToolResult | None,
    store: RunStore,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Adopt a compare-bound merge from its exact journaled effect result."""
    current = state.slices[slice_id]
    if _merge_effect_failed(result):
        cleared = slice_transition(current, ActionChanged(None))
        return _checkpoint_slice_action(
            store,
            state,
            slice_id,
            None,
            slice_state=cleared,
            integration=_abandon_owned_lane_integration(
                state, cleared, state.integration, "merge_failed", "direct merge failed"
            ),
        )
    merge_entry = _confirmed_merge_entry(effects_log, current, current.pr_number)
    if (
        merge_entry is not None
        and merge_entry.get("key") == action.intent_id
        and _merge_journal_is_exact(current, merge_entry)
        and _merge_journal_reports_success(merge_entry)
        and _merge_result_matches_action(result, current, action)
    ):
        arguments = merge_entry.get("arguments")
        assert isinstance(arguments, Mapping)
        expected_base = arguments.get("expected_base_sha")
        expected_head = arguments.get("expected_head_sha")
        expected_tree = arguments.get("expected_merge_tree_sha")
        if all(isinstance(value, str) and value for value in (expected_base, expected_head)):
            merge_evidence: dict[str, object] = {
                "pr_number": current.pr_number,
                "merged": True,
                "head_sha": expected_head,
                "base_sha": expected_base,
                "base_branch": _publication_parent_branch_from_slice(current),
            }
            if isinstance(expected_tree, str) and expected_tree:
                merge_evidence["merge_tree_sha"] = expected_tree
            return _reconcile_merged_slice(
                store.load(),
                slice_id,
                current.pr_number or 0,
                action.intent_id,
                config,
                effects,
                store,
                effects_log,
                boundary="direct_merge_effect_confirmed",
                merge_evidence=merge_evidence,
            )
    watcher = _invoke(
        "watcher_pr_state",
        slice_id,
        {"pr_number": current.pr_number or 0},
        config.active,
        cast(EffectClient, effects) if config.active else None,
        lambda client: client.watcher_pr_state(pr_number=current.pr_number or 0),
        effects_log,
        raise_on_failure=False,
    )
    if _watcher_publication_refused(current, watcher):
        LOGGER.warning(
            "[TL loop] refusing to confirm direct merge for %s: publication provenance mismatch",
            slice_id,
        )
        return store.load()
    if _watcher_publication_ownership_unresolved(watcher):
        LOGGER.warning(
            "[TL loop] refusing to confirm direct merge for %s: publication ownership unresolved",
            slice_id,
        )
        return store.load()
    if (
        watcher is not None
        and watcher.success is True
        and (_watcher_result_observation(watcher) is not None)
        and _watcher_result_observation(watcher).merged is True
    ):
        observation = _watcher_result_observation(watcher)
        return _reconcile_merged_slice(
            store.load(),
            slice_id,
            current.pr_number,
            action.intent_id,
            config,
            effects,
            store,
            effects_log,
            boundary="direct_merge_confirmed",
            merge_evidence=_watcher_merge_evidence(observation),
        )
    return _checkpoint_slice_action(
        store,
        store.load(),
        slice_id,
        replace(action, phase=ActionPhase.CONFIRMED),
    )


def _checkpoint_slice_action(
    store: RunStore,
    state: RunState,
    slice_id: str,
    action: ActionState | None,
    *,
    slice_state: SliceState | None = None,
    integration: IntegrationRuntimeState | None = None,
    clear_gates: tuple[str, ...] = (),
    expected_revision: int | None = None,
) -> RunState:
    """Persist one direct action phase without changing unrelated run state."""
    current = slice_state or state.slices[slice_id]
    if slice_state is None:
        current = slice_transition(current, ActionChanged(action))
    checkpoint_phase = _recursive_phase_after_slice_update(state, slice_id, current)
    if checkpoint_phase is None:
        checkpoint_phase = state.fsm
        if (
            current.status is SliceStatus.MERGED
            and current.post_merge is not None
            and current.post_merge.phase is PostMergePhase.COMPLETE
        ):
            checkpoint_phase = _phase_after_slice_merge(state, slice_id, current)
    return store.checkpoint(
        checkpoint_phase,
        {**state.slices, slice_id: current},
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=integration or state.integration,
        clear_gates=clear_gates,
        expected_revision=expected_revision,
    )


def _recursive_phase_after_slice_update(
    state: RunState,
    slice_id: str,
    current: SliceState,
) -> PhaseValue | None:
    """Project slice recovery into the canonical recursive scope FSM."""
    phase = state.recursive_fsm
    if not isinstance(phase, RecursiveTLRunning) or current.post_merge is None:
        return None
    if slice_id not in phase.post_merge:
        return None
    if current.post_merge.phase is not PostMergePhase.COMPLETE:
        post_merge = dict(phase.post_merge)
        post_merge[slice_id] = current.post_merge
        return replace(phase, post_merge=post_merge)
    # The terminal boundary is dispatched as a PostMergeComplete scope event
    # against the pre-update phase (not a pre-projected copy already showing
    # COMPLETE) so post_merge_transition's own not-yet-complete branch runs
    # and removes this child from parallel_pending/pending_by_order. Handing
    # it an already-COMPLETE phase makes it treat the call as a no-op repeat,
    # leaving the child parked in the FSM's pending set forever even once its
    # post-merge recovery has truly finished.
    evidence = current.post_merge.evidence
    try:
        receipt = PushReceipt(
            repository=evidence["repository"],
            parent_branch=evidence["parent_branch"],
            child_id=evidence["child_id"],
            lane_epoch=int(evidence["lane_epoch"]),
            push_intent_id=evidence["parent_push_intent_id"],
            push_journal_id=evidence["push_journal_id"],
            push_receipt_id=evidence["push_receipt_id"],
            expected_base_sha=evidence["expected_base_sha"],
            pushed_commit=evidence["pushed_commit"],
            observed_remote_head=evidence["observed_remote_head"],
            ancestry_proof=evidence["ancestry_proof"],
        )
        return scope_transition(
            phase,
            PostMergeComplete(
                child_id=slice_id,
                journal_id=evidence["merge_journal_id"],
                push_intent_id=evidence["parent_push_intent_id"],
                bookkeeping_commit=evidence["bookkeeping_commit"],
                receipt=receipt,
            ),
        )
    except (KeyError, TypeError, ValueError, IllegalTransition):
        post_merge = dict(phase.post_merge)
        post_merge[slice_id] = current.post_merge
        return replace(phase, post_merge=post_merge)


def _phase_after_slice_merge(
    state: RunState,
    slice_id: str,
    merged_slice: SliceState,
) -> PhaseValue:
    """Remove a merged slice from the waiting FSM in the same checkpoint."""
    phase = _phase_from_state(state)
    if isinstance(phase, (TLWaiting, TLMerging)):
        return phase_transition(
            phase,
            PRMerged(merged_slice.pr_number or 0, slice_id),
        )
    active = {
        current_id: ChildHandle(
            current_id,
            current.branch or "",
            current.agent_type or "unknown",
        )
        for current_id, current in state.slices.items()
        if current_id != slice_id
        and current.status in {SliceStatus.SPAWNED, SliceStatus.IN_REVIEW, SliceStatus.REPAIRING}
    }
    if active:
        return TLWaiting(active)
    if all(
        current.status is SliceStatus.MERGED
        and current.post_merge is not None
        and current.post_merge.phase is PostMergePhase.COMPLETE
        for current in state.slices.values()
    ):
        return TLAllMerged()
    return phase


def _clear_action_for_reduction(store: RunStore, state: RunState, slice_id: str) -> RunState:
    """Clear a stale direct intent so the next authoritative reduction can act."""
    return _checkpoint_slice_action(store, state, slice_id, None)


def _repair_reasons(current: SliceState) -> list[dict[str, object]]:
    """Convert persisted reviewer findings into the repair contract."""
    findings = current.review_findings.get(current.reviewed_head or "", ())
    return [
        {
            "severity": finding.get("severity", "blocking"),
            "file": finding.get("path", "review"),
            "line": 0,
            "claim": finding.get("rationale", "Reviewer requested changes"),
        }
        for finding in findings
    ] or [
        {
            "severity": "blocking",
            "file": "review",
            "line": 0,
            "claim": "Reviewer requested changes",
        }
    ]


def _record_convergence_event(
    target: str,
    event: object,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    """Emit a statically declared convergence event for contract checking."""
    event_type = getattr(event, "event_type", None)
    payload = getattr(event, "payload", None)
    if not isinstance(payload, Mapping):
        raise TLLoopError("convergence event payload must be an object")
    if event_type == "tl.action_queued":
        _record_controller_event(
            target,
            "tl.action_queued",
            {
                "run_id": payload.get("run_id"),
                "target_id": payload.get("target_id"),
                "state_version": payload.get("state_version"),
                "action": payload.get("action"),
                "action_key": payload.get("action_key"),
                "arguments": payload.get("arguments"),
            },
            config,
            effects,
            effects_log,
        )
    elif event_type == "tl.action_started":
        _record_controller_event(
            target,
            "tl.action_started",
            {
                "run_id": payload.get("run_id"),
                "target_id": payload.get("target_id"),
                "state_version": payload.get("state_version"),
                "action": payload.get("action"),
                "action_key": payload.get("action_key"),
            },
            config,
            effects,
            effects_log,
        )
    elif event_type == "tl.action_unknown":
        _record_controller_event(
            target,
            "tl.action_unknown",
            {
                "run_id": payload.get("run_id"),
                "target_id": payload.get("target_id"),
                "state_version": payload.get("state_version"),
                "action": payload.get("action"),
                "action_key": payload.get("action_key"),
                "outcome": payload.get("outcome"),
                "error": payload.get("error"),
            },
            config,
            effects,
            effects_log,
        )
    elif event_type == "tl.action_reconciled":
        _record_controller_event(
            target,
            "tl.action_reconciled",
            {
                "run_id": payload.get("run_id"),
                "target_id": payload.get("target_id"),
                "state_version": payload.get("state_version"),
                "action": payload.get("action"),
                "action_key": payload.get("action_key"),
                "outcome": payload.get("outcome"),
            },
            config,
            effects,
            effects_log,
        )
    elif event_type == "tl.wait_reason_changed":
        _record_controller_event(
            target,
            "tl.wait_reason_changed",
            {
                "run_id": payload.get("run_id"),
                "target_id": payload.get("target_id"),
                "state_version": payload.get("state_version"),
                "reason": payload.get("reason"),
                "previous_reason": payload.get("previous_reason"),
            },
            config,
            effects,
            effects_log,
        )
    elif event_type == "tl.transition_applied":
        _record_controller_event(
            target,
            "tl.transition_applied",
            {
                "run_id": payload.get("run_id"),
                "target_id": payload.get("target_id"),
                "state_version": payload.get("state_version"),
                "transition": payload.get("transition"),
                "reason": payload.get("reason"),
            },
            config,
            effects,
            effects_log,
        )
    elif event_type == "tl.transition_invariant_failed":
        _record_controller_event(
            target,
            "tl.transition_invariant_failed",
            {
                "run_id": payload.get("run_id"),
                "target_id": payload.get("target_id"),
                "state_version": payload.get("state_version"),
                "invariant": payload.get("invariant"),
                "action_key": payload.get("action_key"),
            },
            config,
            effects,
            effects_log,
        )
    else:
        raise TLLoopError(f"unknown convergence event {event_type!r}")


def _event_target(payload: Mapping[str, object]) -> str:
    target = payload.get("target_id", payload.get("run_id", "controller"))
    return target if isinstance(target, str) and target else "controller"


def _source_has_pending(source: EventQueue) -> bool:
    """Inspect only explicit in-memory source queues before honoring WAIT."""
    events = getattr(source, "events", None)
    if isinstance(events, (list, tuple, set, frozenset)):
        return bool(events)
    if events is not None and hasattr(events, "empty"):
        try:
            return not events.empty()
        except (AttributeError, TypeError):
            return True
    queued = getattr(source, "_events", None)
    if queued is not None:
        try:
            return not queued.empty()
        except (AttributeError, TypeError):
            return True
    nested = getattr(source, "queue", None)
    if nested is not None and nested is not source:
        return _source_has_pending(nested)
    return True


def _record_reader_findings(source: EventQueue, diagnostics: EventDiagnostics) -> None:
    """Promote reader-side filtering into durable controller diagnostics."""
    findings = getattr(source, "findings", ())
    if findings:
        diagnostics.record_reader_findings(tuple(findings))


def _record_dispatch_intent(
    slice_id: str,
    attempt: DispatchAttempt,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    _record_controller_event(
        slice_id,
        "tl.dispatch_intended",
        _dispatch_payload(slice_id, attempt, "dispatch_intended"),
        config,
        effects,
        effects_log,
    )


def _record_spawn_request(
    slice_id: str,
    attempt: DispatchAttempt,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    _record_controller_event(
        slice_id,
        "tl.spawn_requested",
        _dispatch_payload(slice_id, attempt, "spawn_requested"),
        config,
        effects,
        effects_log,
    )


def _record_dispatch_result(
    store: RunStore,
    state: RunState,
    slice_id: str,
    attempt: DispatchAttempt,
    result: ToolResult | None,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    if result is not None and result.success is False:
        return _record_dispatch_failure(
            store,
            state,
            slice_id,
            attempt,
            result.error or "spawn request rejected",
            config,
            effects,
            effects_log,
            code=_dispatch_failure_code(store, config, attempt),
        )
    boundary = "spawn_request_accepted" if result is not None else "spawn_not_executed"
    current = state.slices[slice_id]
    updated = slice_transition(current, SliceStatusChanged(SliceStatus.DISPATCH_UNCONFIRMED))
    updated = replace(
        updated,
        park_cause=ParkCause.DISPATCH_UNCONFIRMED,
        dispatch_last_boundary=boundary,
        dispatch_agent_id=_spawn_agent_id(result),
        dispatch_invocation_id=_spawn_invocation_id(result),
        dispatch_error=None,
        dispatch_error_code=None,
        dispatch_next_attempt_at=None,
        dispatch_retry_for_attempt=0,
    )
    state = store.checkpoint(
        state.fsm,
        {**state.slices, slice_id: updated},
        state.budgets,
        state.events.last_consumed_offset,
    )
    if result is not None:
        _record_controller_event(
            slice_id,
            "tl.spawn_request_accepted",
            _dispatch_payload(slice_id, attempt, boundary),
            config,
            effects,
            effects_log,
        )
    return state


def _record_dispatch_failure(
    store: RunStore,
    state: RunState,
    slice_id: str,
    attempt: DispatchAttempt,
    reason: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    *,
    code: str | None = None,
) -> RunState:
    """Persist one rejected spawn request, retrying, holding, or parking it.

    A retryable machine code schedules a durable re-drive boundary instead of
    an unqualified intent: no leaf, branch, worktree, or PR exists yet, so the
    intent, agent, and invocation identities are cleared. An ambiguous code
    proves nothing either way, so the persisted intent is kept and the slice
    holds at ``dispatch_unconfirmed`` for evidence and owner reconciliation --
    never a second spawn, and never a gate of its own. Every other code,
    including an absent one, is terminal and opens the named gate.
    """
    bounded_reason = reason[:500]
    failure_class = classify_dispatch_failure(code)
    if failure_class is DispatchFailureClass.RETRYABLE:
        return _record_dispatch_retry_scheduled(
            store,
            state,
            slice_id,
            attempt,
            bounded_reason,
            code,
            config,
            effects,
            effects_log,
        )
    if failure_class is DispatchFailureClass.AMBIGUOUS:
        return _record_ambiguous_dispatch_outcome(
            store,
            state,
            slice_id,
            attempt,
            bounded_reason,
            code,
            config,
            effects,
            effects_log,
        )
    return _record_terminal_dispatch_failure(
        store, state, slice_id, attempt, bounded_reason, code, config, effects, effects_log
    )


def _record_ambiguous_dispatch_outcome(
    store: RunStore,
    state: RunState,
    slice_id: str,
    attempt: DispatchAttempt,
    reason: str,
    code: str | None,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Hold an unproven dispatch for evidence instead of re-driving it.

    The intent is deliberately **kept**: it is the only correlation the
    reconciler has against the correlated ``agent.spawned`` event and the
    runtime's owner listing, so clearing it would make an already-launched leaf
    unreachable. The slice stays ``dispatch_unconfirmed``, which is the
    documented home for an accepted request with delayed evidence, and no gate
    opens: this is a wait state, not a decision.
    """
    current = state.slices[slice_id]
    if (
        current.status is SliceStatus.DISPATCH_UNCONFIRMED
        and current.dispatch_error_code == code
        and current.dispatch_intent_id == attempt.intent_id
    ):
        return state
    updated = slice_transition(current, SliceStatusChanged(SliceStatus.DISPATCH_UNCONFIRMED))
    updated = replace(
        updated,
        park_cause=ParkCause.DISPATCH_UNCONFIRMED,
        dispatch_last_boundary="spawn_outcome_ambiguous",
        dispatch_error=reason,
        dispatch_error_code=code,
        dispatch_next_attempt_at=None,
        dispatch_retry_for_attempt=0,
    )
    state = store.checkpoint(
        state.fsm,
        {**state.slices, slice_id: updated},
        state.budgets,
        state.events.last_consumed_offset,
    )
    _record_controller_event(
        slice_id,
        "tl.spawn_request_failed",
        _dispatch_payload(slice_id, attempt, "spawn_outcome_ambiguous", error=reason),
        config,
        effects,
        effects_log,
    )
    return state


def _record_terminal_dispatch_failure(
    store: RunStore,
    state: RunState,
    slice_id: str,
    attempt: DispatchAttempt,
    reason: str,
    code: str | None,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Park one terminal dispatch failure and open its single named gate."""
    current = state.slices[slice_id]
    updated = slice_transition(current, SliceStatusChanged(SliceStatus.DISPATCH_FAILED))
    updated = replace(
        updated,
        park_cause=ParkCause.DISPATCH_FAILED,
        dispatch_last_boundary="spawn_request_failed",
        dispatch_error=reason,
        dispatch_error_code=code,
        dispatch_next_attempt_at=None,
        dispatch_retry_for_attempt=0,
    )
    before_phase = _phase_from_state(state)
    state = store.checkpoint(
        _failure_phase(state, f"dispatch failed for {slice_id!r}: {reason}"),
        {**state.slices, slice_id: updated},
        state.budgets,
        state.events.last_consumed_offset,
    )
    gate_name = _dispatch_failure_gate_name(slice_id, code)
    previous_gate = next((gate for gate in state.gates if gate.name == gate_name), None)
    state = store.set_gate(gate_name)
    if previous_gate is None or previous_gate.status is not GateStatus.PENDING:
        _record_controller_event(
            "controller",
            "tl.gate_opened",
            {"gate_name": gate_name, "run_id": state.run_id},
            config,
            effects,
            effects_log,
        )
    _record_controller_event(
        slice_id,
        "tl.spawn_request_failed",
        _dispatch_payload(slice_id, attempt, "spawn_request_failed", error=reason),
        config,
        effects,
        effects_log,
    )
    _emit_phase_change(
        state.run_id,
        before_phase,
        _phase_from_state(state),
        config,
        effects,
        effects_log,
    )
    return state


def _dispatch_failure_gate_name(slice_id: str, code: str | None) -> str:
    """Name the one gate an operator must answer for one slice's dispatch failure.

    The name is scoped to the slice, the way ``tl-ordered-child-recovery-<child>``
    is scoped to its child, so two slices that both exhaust their retries are two
    operator decisions instead of one shared gate whose second opening would emit
    no ``tl.gate_opened``. The slice id is the whole scope: gates live in the
    slice-owning run's checkpoint and slice ids are unique inside it.

    The code picks the prefix, because the operator action differs: an ownership
    conflict asks them to resolve who owns the branch, not merely to acknowledge
    that a spawn was refused.
    """
    prefix = (
        DISPATCH_OWNERSHIP_CONFLICT_GATE_PREFIX
        if code == OWNERSHIP_CONFLICT_CODE
        else DISPATCH_FAILURE_GATE_PREFIX
    )
    return f"{prefix}{slice_id}"


def _migrate_legacy_dispatch_gates(store: RunStore, state: RunState) -> RunState:
    """Re-scope a pending pre-#1119 run-global dispatch gate onto its slice.

    A run-global gate says *that* a dispatch needs a decision but not *which
    slice's*, so it is migrated from durable state instead of renamed by
    assumption: the slice parked on ``DISPATCH_FAILED`` names the exhaustion the
    operator was asked about. Exactly one such slice is required. Zero or several
    candidates is an ambiguous checkpoint, so the controller fails closed and
    names them rather than attaching an operator's pending question to a slice
    they were never asked about.

    The migration preserves the gate's pending status and emits no
    ``tl.gate_opened``: that exhaustion already emitted one, under the old name.

    A legacy gate that is already answered is left exactly as it is. It is the
    durable record of a decision an operator made, and every future exhaustion
    opens its own per-slice gate, so there is nothing left to migrate.
    """
    for legacy_name, expected_prefix in LEGACY_DISPATCH_GATES.items():
        gate = next((item for item in state.gates if item.name == legacy_name), None)
        if gate is None or gate.status is not GateStatus.PENDING:
            continue
        parked = sorted(
            slice_id
            for slice_id, slice_state in state.slices.items()
            if slice_state.status is SliceStatus.DISPATCH_FAILED
            and slice_state.park_cause is ParkCause.DISPATCH_FAILED
        )
        if len(parked) != 1:
            candidates = ", ".join(parked) if parked else "none"
            raise TLLoopError(
                f"pending gate {legacy_name!r} cannot be attributed to exactly one parked "
                f"dispatch slice; candidates: {candidates}. Answer it with "
                f"`python3 -m tl_loop gate --run-id {state.run_id} --name {legacy_name} "
                f"--approve` to retire it; the next dispatch exhaustion then opens its own "
                f"per-slice gate."
            )
        slice_id = parked[0]
        code = state.slices[slice_id].dispatch_error_code
        replacement = _dispatch_failure_gate_name(slice_id, code)
        if not replacement.startswith(expected_prefix):
            raise TLLoopError(
                f"pending gate {legacy_name!r} contradicts the machine code {code!r} recorded "
                f"for parked slice {slice_id!r}, which names {replacement!r}. Answer it with "
                f"`python3 -m tl_loop gate --run-id {state.run_id} --name {legacy_name} "
                f"--approve` to retire it."
            )
        if any(item.name == replacement for item in state.gates):
            raise TLLoopError(
                f"cannot migrate pending gate {legacy_name!r}: {replacement!r} is already "
                f"pending for the parked slice {slice_id!r}. Answer the run-global duplicate "
                f"with `python3 -m tl_loop gate --run-id {state.run_id} --name {legacy_name} "
                f"--approve`; the slice's own gate stays pending."
            )
        state = store.rename_gate(legacy_name, replacement)
    return state


def _record_dispatch_retry_scheduled(
    store: RunStore,
    state: RunState,
    slice_id: str,
    attempt: DispatchAttempt,
    reason: str,
    code: str | None,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Record the durable uncreated boundary a retryable rejection schedules.

    The boundary is idempotent per dispatch attempt: a repeated reconciliation
    that observes the same rejected attempt leaves the counter and the
    scheduled instant untouched instead of consuming the retry budget twice.
    Exhausting the configured attempt limit is terminal and keeps the machine
    code that proved the last attempt retryable.
    """
    current = state.slices[slice_id]
    if current.dispatch_retry_for_attempt == attempt.attempt:
        return state
    if current.dispatch_retry_attempt >= config.dispatch_retry_limit:
        return _record_terminal_dispatch_failure(
            store, state, slice_id, attempt, reason, code, config, effects, effects_log
        )
    retry_attempt = current.dispatch_retry_attempt + 1
    delay = dispatch_retry_delay(
        retry_attempt,
        config.dispatch_retry_base_delay_seconds,
        config.dispatch_retry_max_delay_seconds,
    )
    next_attempt_at = _wall_clock(config) + delay
    updated = slice_transition(current, SliceStatusChanged(SliceStatus.DISPATCH_RETRY_SCHEDULED))
    updated = replace(
        updated,
        park_cause=None,
        dispatch_last_boundary="dispatch_retry_scheduled",
        dispatch_error=reason,
        dispatch_error_code=code,
        dispatch_retry_attempt=retry_attempt,
        dispatch_next_attempt_at=next_attempt_at,
        dispatch_retry_for_attempt=attempt.attempt,
        dispatch_intent_id=None,
        dispatch_started_at=None,
        # The rejected attempt created nothing, so its generation dies with its
        # intent; the re-drive mints the next one with the same boundary.
        dispatch_generation=0,
        dispatch_agent_id=None,
        dispatch_invocation_id=None,
        dispatch_authoritative_event_seq=None,
    )
    state = store.checkpoint(
        state.fsm,
        {**state.slices, slice_id: updated},
        state.budgets,
        state.events.last_consumed_offset,
    )
    _record_controller_event(
        slice_id,
        "tl.spawn_request_failed",
        _dispatch_payload(slice_id, attempt, "spawn_request_failed", error=reason),
        config,
        effects,
        effects_log,
    )
    _record_controller_event(
        slice_id,
        "tl.dispatch_retry_scheduled",
        _dispatch_retry_payload(slice_id, attempt, reason, code, retry_attempt, next_attempt_at),
        config,
        effects,
        effects_log,
    )
    return state


def _wall_clock(config: TLLoopConfig) -> float:
    """Read the injected dispatch clock, defaulting to the wall clock."""
    if config.wall_clock is not None:
        return float(config.wall_clock())
    return time.time()


def _dispatch_failure_code(
    store: RunStore,
    config: TLLoopConfig,
    attempt: DispatchAttempt,
) -> str | None:
    """Resolve one rejected dispatch's stable machine code, or None.

    The runtime writes one ``agent.spawn_failed`` ledger event per refused
    spawn, carrying the typed ``EffectError`` code it already returned. That
    event is the only channel this classification reads: the rejected tool
    result's ``error`` prose is operator-facing and is never inspected.

    The read starts at the attempt's recorded ledger floor rather than at the
    consumption cursor or at zero, so it is bounded by the intent that is being
    classified. A refusal for this attempt can only be at or after that
    position, and a row recorded before it belongs to an earlier attempt even
    if it happens to carry the same intent. The floor is persisted with the
    slice, so a restart resolves against the same position the intent was
    issued at. An unreadable ledger, a missing event, and an event with no code
    all resolve to None, which classifies as terminal.
    """
    if config.project_root is None or config.ledger_run_id is None:
        return None
    try:
        reader = LedgerReader(
            Path(config.project_root) / ".exo" / "ledger" / "segments",
            run_dir=store.run_dir,
            ledger_run_id=config.ledger_run_id,
        )
        result = reader.read_from(cursor=attempt.ledger_floor)
    except (LedgerReadError, OSError, ValueError):
        return None
    code: str | None = None
    for event in result.events:
        if event.event_type != "agent.spawn_failed":
            continue
        if event.run_seq is None or event.run_seq <= attempt.ledger_floor:
            continue
        if event.data.get("intent_id") != attempt.intent_id:
            continue
        raw = event.data.get("code")
        if isinstance(raw, str) and raw:
            code = raw
    return code


ACTION_JOURNAL_GATE_PREFIX = "tl-action-journal-"


def _action_journal_gate_name(key: str, attempt: int = 0) -> str:
    suffix = f"-{attempt}" if attempt else ""
    return f"{ACTION_JOURNAL_GATE_PREFIX}{key[:16]}{suffix}"


def _action_journal_compensation_attempt(entry: Mapping[str, object]) -> int:
    attempt = entry.get("compensation_attempt")
    return attempt if isinstance(attempt, int) and attempt >= 0 else 0


def _reconcile_action_journal(
    state: RunState,
    store: RunStore,
    effects_log: list[EffectIntent],
    *,
    effects: EffectClient | ReadOnlyEffectClient | None = None,
    project_root: str | Path | None = None,
    ledger_run_id: str | None = None,
) -> RunState:
    """Resolve action-journal entries stuck at intended/unknown so a restart
    does not crash permanently on the same blocked lifecycle effect.

    Whether the underlying side effect (spawn, PR file, merge, cleanup, ...)
    actually happened cannot be inferred generically here, so this never
    guesses. Each stuck entry instead opens (or reuses) a durable named gate:
    approving it records the entry as compensated, clearing the block so the
    next matching dispatch proceeds as a genuinely fresh attempt; rejecting
    it records a durable rejected outcome so callers observe a normal
    failure instead of a crash on the next retry.

    An approval only ever authorizes the one ambiguous occurrence the
    operator looked at. The gate name is scoped by a persisted per-key
    compensation_attempt counter that increments every time this key is
    resolved, so a *later* unknown/intended outcome for the same
    operation+target+arguments (e.g. the retried dispatch itself lands in
    another ambiguous state) opens a brand-new PENDING gate rather than
    silently matching the earlier APPROVED one. Without this, one approval
    would authorize the effect (spawn, merge, PR, or cleanup) to be retried
    indefinitely with no further human check, risking it running twice.

    This provides at-most-once dispatch until an operator reconciles an
    ambiguous outcome; it cannot autonomously prove exactly-once execution
    after a process crash between the external effect and its response.
    """
    if not isinstance(effects_log, EffectJournal):
        return state
    for entry in effects_log.pending_entries():
        if entry.get("operation") == "resume_blocked_leaf":
            # This exact same-owner operation has an authoritative idempotency
            # key and its owner-specific reconciler validates the persisted
            # successor before replay. A generic gate cannot establish that
            # lineage and would prevent safe response-loss adoption.
            continue
        if entry.get("operation") == "prepare_scope_handoff":
            if isinstance(effects, EffectClient):
                _reconcile_pending_scope_handoff(entry, effects_log, effects)
            # The operation is bound to a stable Git snapshot and its host
            # handler adopts a matching commit by trailer before retrying.
            # A generic approval gate would prevent that safe reconciliation.
            continue
        if entry.get("operation") in {
            "post_merge_parent_sync",
            "post_merge_parent_sync_reconcile",
        }:
            # Parent synchronization owns its Git probe and retry policy. A
            # generic approval gate cannot distinguish a preflight refusal
            # from a completed fast-forward or an unknown interruption.
            continue
        if entry.get("operation") == "post_merge_issue_close":
            continue
        if _is_aggregate_file_pr_entry(entry, state):
            # Aggregate file_pr is an idempotent upsert by its durable head
            # branch. Its owner reconciles the exact PR identity before retry;
            # a generic approval gate would prevent that recovery from running.
            continue
        key = entry.get("key")
        if not isinstance(key, str) or not key:
            continue
        if effects is not None and _reconcile_pending_merge_entry(
            entry,
            state,
            store,
            effects_log,
            effects,
        ):
            state = store.load()
            continue
        if _controller_event_was_committed(
            entry,
            store,
            project_root=project_root,
            ledger_run_id=ledger_run_id,
        ):
            effects_log.resolve_by_key(
                key,
                status="confirmed",
                result={"success": True, "result": {"reconciled": True}},
            )
            continue
        attempt = _action_journal_compensation_attempt(entry)
        gate_name = _action_journal_gate_name(key, attempt)
        gate = next((candidate for candidate in state.gates if candidate.name == gate_name), None)
        if gate is None:
            state = store.set_gate(gate_name, GateStatus.PENDING)
            LOGGER.warning(
                "[TL loop] action journal entry key=%s operation=%s target=%s has "
                "unknown outcome; opened gate=%s for operator resolution",
                key,
                entry.get("operation"),
                entry.get("target"),
                gate_name,
            )
        elif gate.status is GateStatus.APPROVED:
            effects_log.resolve_by_key(key, status="compensated", compensation_attempt=attempt + 1)
        elif gate.status is GateStatus.REJECTED:
            effects_log.resolve_by_key(
                key,
                status="rejected",
                compensation_attempt=attempt + 1,
                result={
                    "success": False,
                    "error": f"operator rejected retry via gate {gate_name!r}",
                },
            )
    return state


def _reconcile_pending_scope_handoff(
    entry: Mapping[str, object],
    effects_log: EffectJournal,
    effects: EffectClient,
) -> bool:
    """Replay one ambiguous handoff with the exact durable snapshot arguments."""
    key = entry.get("key")
    arguments = entry.get("arguments")
    if (
        not isinstance(key, str)
        or not isinstance(arguments, Mapping)
        or arguments.get("apply") is not True
        or not isinstance(arguments.get("expected_head_sha"), str)
        or not isinstance(arguments.get("expected_source_fingerprint"), str)
    ):
        return False
    try:
        result = _scope_handoff_call(effects, arguments)
    except Exception:  # noqa: BLE001 - retain unknown until a later safe replay
        return False
    expected = {
        key: arguments.get(key)
        for key in (
            "handoff_id",
            "controller_id",
            "parent_run_id",
            "parent_scope_id",
            "child_scope_id",
            "expected_branch",
        )
    }
    if (
        _scope_handoff_response_error(
            result,
            expected,
            expected_head=cast(str, arguments.get("expected_head_sha")),
            expected_fingerprint=cast(str, arguments.get("expected_source_fingerprint")),
        )
        is not None
    ):
        return False
    effects_log.resolve_by_key(key, status="confirmed", result=result.raw, error=None)
    return True


def _scope_handoff_call(
    effects: EffectClient,
    arguments: Mapping[str, object],
) -> ToolResult:
    """Decode journaled arguments before replaying the idempotent host operation."""
    required = (
        "apply",
        "handoff_id",
        "controller_id",
        "parent_run_id",
        "parent_scope_id",
        "child_scope_id",
        "expected_branch",
    )
    if any(key not in arguments for key in required) or type(arguments.get("apply")) is not bool:
        raise ActionJournalError("scope handoff journal arguments are incomplete")
    text = {key: arguments.get(key) for key in required if key != "apply"}
    if any(not isinstance(value, str) or not value for value in text.values()):
        raise ActionJournalError("scope handoff journal identity is malformed")
    head = arguments.get("expected_head_sha")
    fingerprint = arguments.get("expected_source_fingerprint")
    if head is not None and not isinstance(head, str):
        raise ActionJournalError("scope handoff expected HEAD is malformed")
    if fingerprint is not None and not isinstance(fingerprint, str):
        raise ActionJournalError("scope handoff source fingerprint is malformed")
    return effects.prepare_scope_handoff(
        apply=cast(bool, arguments["apply"]),
        handoff_id=cast(str, text["handoff_id"]),
        controller_id=cast(str, text["controller_id"]),
        parent_run_id=cast(str, text["parent_run_id"]),
        parent_scope_id=cast(str, text["parent_scope_id"]),
        child_scope_id=cast(str, text["child_scope_id"]),
        expected_branch=cast(str, text["expected_branch"]),
        expected_head_sha=head,
        expected_source_fingerprint=fingerprint,
    )


def _is_aggregate_file_pr_entry(entry: Mapping[str, object], state: RunState) -> bool:
    """Recognize aggregate publication journal entries for owner recovery."""
    if entry.get("operation") != "file_pr":
        return False
    target = entry.get("target")
    arguments = entry.get("arguments")
    if not isinstance(target, str) or target not in state.slices:
        return False
    if not isinstance(arguments, Mapping):
        return False
    title = arguments.get("title")
    return isinstance(title, str) and title.startswith("Aggregate ")


def _reconcile_confirmed_repair_actions(
    state: RunState,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Adopt a confirmed repair effect before retry derivation can run."""
    if not isinstance(effects_log, EffectJournal):
        return state
    for slice_id, current in state.slices.items():
        action = current.action
        if (
            action is None
            or action.kind is not ActionKind.REPAIR
            or action.phase not in {ActionPhase.INTENDED, ActionPhase.IN_FLIGHT}
        ):
            continue
        confirmed = _confirmed_repair_entry(effects_log, current)
        if confirmed is None:
            continue
        attempts = current.attempts
        repair_attempts = current.repair_attempts
        if attempts <= action.attempt:
            attempts = action.attempt + 1
            repair_attempts += 1
        updated = slice_transition(
            current,
            ActionChanged(replace(action, phase=ActionPhase.CONFIRMED)),
        )
        updated = replace(
            updated,
            attempts=attempts,
            repair_attempts=repair_attempts,
        )
        state = _checkpoint_slice_action(
            store,
            state,
            slice_id,
            updated.action,
            slice_state=updated,
        )
    return state


def _confirmed_repair_entry(
    effects_log: EffectJournal,
    current: SliceState,
) -> Mapping[str, object] | None:
    """Find successful resume evidence for the current PR, newest first."""
    if current.pr_number is None:
        return None
    entries = effects_log.confirmed_entries("resume_pr", current.id)
    if len(entries) < max(1, current.action.attempt if current.action else 1):
        return None
    for entry in reversed(entries):
        arguments = entry.get("arguments")
        if not isinstance(arguments, Mapping) or arguments.get("pr_number") != current.pr_number:
            continue
        try:
            result = effects_log.replay(entry)
        except ActionJournalError:
            continue
        if result.success is True:
            return entry
    return None


def _reconcile_pending_merge_entry(
    entry: Mapping[str, object],
    state: RunState,
    store: RunStore,
    effects_log: EffectJournal,
    effects: EffectClient | ReadOnlyEffectClient,
) -> bool:
    """Adopt a merge that completed before restart but lost its response."""
    if entry.get("operation") != "merge_pr":
        return False
    arguments = entry.get("arguments")
    if not isinstance(arguments, Mapping):
        return False
    pr_number = arguments.get("pr_number")
    target = entry.get("target")
    if type(pr_number) is not int or not isinstance(target, str) or target not in state.slices:
        return False
    key = entry.get("key")
    if not isinstance(key, str) or not key:
        return False
    try:
        watcher = effects.watcher_pr_state(pr_number=pr_number)
    except (ConnectionError, OSError, RuntimeError, TimeoutError):
        return False
    observation = _watcher_result_observation(watcher)
    if _watcher_publication_refused(state.slices[target], watcher) or (
        _watcher_publication_ownership_unresolved(watcher)
    ):
        # A refused or ownership-unresolved publication record may not resolve
        # the pending merge.
        return False
    if watcher.success is True and observation is not None and observation.merged is False:
        _resolve_nonmerged_merge(
            state,
            target,
            store,
            effects_log,
            journal_key=key,
            diagnostic="authoritative watcher state says the merge did not happen",
        )
        return True
    if watcher.success is not True or observation is None or observation.merged is not True:
        return False
    effects_log.resolve_by_key(
        key,
        status="confirmed",
        result={"success": True, "result": {"merged": True, "reconciled": True}},
    )
    _reconcile_merged_slice(
        state,
        target,
        pr_number,
        key,
        TLLoopConfig(active=True),
        effects,
        store,
        effects_log,
        boundary="restart_merge_reconciled",
        merge_evidence={
            **arguments,
            **_watcher_merge_evidence(_watcher_result_observation(watcher)),
        },
    )
    return True


def _controller_event_was_committed(
    entry: Mapping[str, object],
    store: RunStore,
    *,
    project_root: str | Path | None,
    ledger_run_id: str | None,
) -> bool:
    """Use the authoritative ledger to resolve an interrupted event emission."""
    if project_root is None or ledger_run_id is None:
        return False
    if entry.get("operation") != "emit_controller_event":
        return False
    arguments = entry.get("arguments")
    if not isinstance(arguments, Mapping):
        return False
    event_type = arguments.get("event_type")
    payload = arguments.get("payload")
    if not isinstance(event_type, str) or not isinstance(payload, Mapping):
        return False
    try:
        reader = LedgerReader(
            Path(project_root) / ".exo" / "ledger" / "segments",
            run_dir=store.run_dir,
            ledger_run_id=ledger_run_id,
        )
        return reader.has_record(event_type, payload)
    except (LedgerReadError, OSError, ValueError):
        return False


def _reconcile_dispatches(
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Adopt persisted dispatches before any restart can issue a duplicate.

    A slice parked on a retry boundary has no intent to reconcile: resource
    creation never completed, so there is nothing to adopt and nothing to
    wait for. It is left on its persisted boundary, and the dispatch path
    re-drives it only once that boundary's instant has arrived.
    """
    pending = [
        slice_state
        for slice_state in state.slices.values()
        if slice_state.status in DISPATCHING_STATUSES
    ]
    if not pending:
        return state
    agent_listing: ToolResult | None = None
    if config.active:
        live = cast(EffectClient, effects)
        agent_listing = _invoke(
            "list_agents",
            "controller",
            {},
            True,
            live,
            lambda client: client.list_agents(),
            effects_log,
            raise_on_failure=False,
        )
    for pending_slice in pending:
        current = state.slices.get(pending_slice.id, pending_slice)
        if current.dispatch_intent_id is None or current.dispatch_started_at is None:
            continue
        attempt = DispatchAttempt.recorded_for(current, state.controller_epoch)
        _record_controller_event(
            current.id,
            "tl.dispatch_reconciliation_started",
            _dispatch_payload(current.id, attempt, "reconciliation_started"),
            config,
            effects,
            effects_log,
        )
        owner_id = _agent_for_dispatch_intent(agent_listing, attempt.intent_id)
        if owner_id is not None:
            _record_controller_event(
                current.id,
                "tl.dispatch_reconciliation_completed",
                _dispatch_payload(current.id, attempt, "owner_found"),
                config,
                effects,
                effects_log,
            )
            confirmation = _record_controller_event(
                current.id,
                "tl.dispatch_confirmed",
                _dispatch_payload(current.id, attempt, "owner_adopted"),
                config,
                effects,
                effects_log,
            )
            authoritative_seq = _controller_event_run_seq(confirmation)
            if authoritative_seq is not None:
                adopted_slices = {
                    **state.slices,
                    current.id: replace(
                        slice_transition(current, SliceStatusChanged(SliceStatus.SPAWNED)),
                        park_cause=None,
                        dispatch_last_boundary="owner_adopted",
                        dispatch_error=None,
                        dispatch_agent_id=owner_id,
                        dispatch_authoritative_event_seq=authoritative_seq,
                    ),
                }
                state = store.checkpoint(
                    _dispatch_waiting_phase(adopted_slices),
                    adopted_slices,
                    state.budgets,
                    state.events.last_consumed_offset,
                )
                continue
        if current.status is SliceStatus.DISPATCHING:
            state = store.checkpoint(
                state.fsm,
                {
                    **state.slices,
                    current.id: replace(
                        slice_transition(
                            current, SliceStatusChanged(SliceStatus.DISPATCH_UNCONFIRMED)
                        ),
                        park_cause=ParkCause.DISPATCH_UNCONFIRMED,
                        dispatch_last_boundary="reconciliation_started",
                    ),
                },
                state.budgets,
                state.events.last_consumed_offset,
            )
        _record_controller_event(
            current.id,
            "tl.dispatch_reconciliation_completed",
            _dispatch_payload(current.id, attempt, "awaiting_authoritative_event"),
            config,
            effects,
            effects_log,
        )
    return state


def _reviewer_effect_pending(
    slice_id: str,
    effects_log: list[EffectIntent],
) -> bool:
    """Whether a reviewer spawn for this slice has an unresolved journal entry."""
    if not isinstance(effects_log, EffectJournal):
        return False
    return any(
        entry.get("operation") == "spawn_reviewer" and entry.get("target") == slice_id
        for entry in effects_log.pending_entries()
    )


def _heal_stale_reviewer_action(
    current: SliceState,
    effects_log: list[EffectIntent],
) -> SliceState | None:
    """Clear a provably-stale matching-head reviewer action after a verdict.

    A verdict recorded by older code (or any prior bug) can leave a
    REVIEWER_SPAWN action for the same head, which holds ``_derive_slice_action``
    at ``await_reviewer_spawn_reconciliation`` forever. Repair only the narrow,
    provable case: an exact-head verdict, a matching terminal reviewer action, an
    existing reviewer attempt, and no pending/unknown reviewer journal entry.
    Ambiguous actions (including every REPAIR action) stay gated, and the general
    verdict-is-set fast path is untouched.
    """
    action = current.action
    head_sha = current.reviewed_head
    if (
        current.verdict is None
        or head_sha is None
        or action is None
        or action.kind is not ActionKind.REVIEWER_SPAWN
        or action.head_sha != head_sha
        or action.phase not in {ActionPhase.CONFIRMED, ActionPhase.RECONCILED}
        or current.reviewer_attempt.get(head_sha, 0) <= 0
        or _reviewer_effect_pending(current.id, effects_log)
    ):
        return None
    try:
        healed = slice_transition(current, StaleReviewerActionHealed(head_sha))
    except IllegalSliceTransition:
        return None
    return healed if healed != current else None


def _reconfirm_park(
    current: SliceState,
    watcher: WatcherObservation | Mapping[str, object] | None,
    state: RunState,
    store: RunStore,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> SliceState | None:
    """Re-emit one park whose authoritative observation still proves it.

    A restart has to show that the controller reached the same conclusion it
    recorded before it stopped, so the boundary is emitted again -- and only
    that. `park` resolves the escalation intent by (slice, cause, attempt) under
    a lock and reuses the issue it names, so a re-confirmation can never add a
    second intent or a second issue. A park whose observation no longer proves
    it is left exactly as it is: reconciliation never resurrects a parked slice.
    """
    if current.park_cause is None or watcher is None:
        return None
    cause = pr_terminal_cause(watcher)
    if cause is None or cause.value != current.park_cause.value:
        return None
    if isinstance(effects, ReadOnlyEffectClient):
        return None
    park(
        current,
        current.park_cause,
        store=store,
        issue_creator=effects,
        ledger=state.budgets,
        audit=pr_payload(watcher),
    )
    refreshed = store.load().slices.get(current.id)
    return refreshed if refreshed is not None else None


def _merge_retirement_gate_name(state: RunState, slice_id: str, key: str) -> str:
    """Name a per-slice, per-occurrence gate for a rejected merge hold.

    The slice id is part of the name so an operator can tell which slice the
    decision is about; the digest over the run, slice, and rejected action key
    makes a later contradictory occurrence a new decision instead of a silent
    reuse of an already-answered gate.
    """
    occurrence = {"run_id": state.run_id, "slice_id": slice_id, "key": key}
    encoded = json.dumps(occurrence, sort_keys=True, separators=(",", ":"))
    digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()[:16]
    token = re.sub(r"[^A-Za-z0-9._-]", "-", slice_id) or "slice"
    return f"{MERGE_RETIREMENT_GATE_PREFIX}{token}-{digest}"


def _hold_rejected_merge(
    state: RunState,
    store: RunStore,
    slice_id: str,
    entry: Mapping[str, object],
    diagnostic: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Open a bounded actionable hold for a rejected merge we cannot converge.

    The gate is a real operator decision: approving it authorizes treating the
    rejected attempt as a proven non-merge (retire + fresh attempt), while
    rejecting it keeps the entry held with no retry.
    """
    key = str(entry.get("key") or "")
    gate_name = _merge_retirement_gate_name(state, slice_id, key)
    previous = next((gate for gate in state.gates if gate.name == gate_name), None)
    if previous is None or previous.status is not GateStatus.PENDING:
        state = store.set_gate(gate_name, GateStatus.PENDING)
        _record_controller_event(
            "controller",
            "tl.gate_opened",
            {"gate_name": gate_name, "run_id": state.run_id},
            config,
            effects,
            effects_log,
        )
        LOGGER.warning(
            "[TL loop] rejected merge for %s needs operator reconciliation: %s (gate=%s)",
            slice_id,
            diagnostic,
            gate_name,
        )
    return state


def _clear_merge_retirement_gate(
    state: RunState,
    store: RunStore,
    slice_id: str,
    key: str,
) -> RunState:
    """Close the retirement hold once its exact occurrence is resolved."""
    gate_name = _merge_retirement_gate_name(state, slice_id, key)
    if any(gate.name == gate_name for gate in state.gates):
        return store.clear_gate(gate_name)
    return state


def _retire_rejected_merge_attempt(
    state: RunState,
    store: RunStore,
    slice_id: str,
    entry: Mapping[str, object],
    diagnostic: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    *,
    observation: WatcherObservation | None = None,
) -> RunState:
    """Retire one proven-rejected merge attempt and derive eligible integration.

    The original rejected journal entry is preserved byte-for-byte: it is
    historical evidence. The corrective disposition is a durable controller
    event plus a checkpoint projection that clears the stale in-flight action
    and returns the candidate to ``READY_FOR_INTEGRATION``. Retiring advances
    the candidate's merge-attempt counter so a genuinely new approved attempt
    gets a distinct action identity instead of replaying the old rejection.
    """
    refreshed = store.load()
    current = refreshed.slices.get(slice_id)
    if current is None:
        return refreshed
    key = str(entry.get("key") or "")
    action = current.action
    if action is None or action.intent_id != key:
        # Already retired, or a newer attempt replaced it.
        return refreshed
    rejected_attempt = action.attempt
    integration_candidate = (
        refreshed.integration.candidates.get(slice_id)
        if refreshed.integration is not None
        else None
    )
    park_release_reason = _stale_aggregate_timeout_park_release_reason(
        current, integration_candidate, observation
    )
    integration = _abandon_owned_lane_integration(
        refreshed, current, refreshed.integration, "merge_not_confirmed", diagnostic
    )
    integration = _derive_eligible_integration_after_nonmerge(integration, slice_id)
    cleared = slice_transition(current, ActionChanged(None))
    if park_release_reason is not None:
        cleared = slice_transition(cleared, SliceStatusChanged(SliceStatus.IN_REVIEW))
        cleared = replace(cleared, park_cause=None, dispatch_error=None)
    elif current.status is SliceStatus.PARKED:
        # A terminal merge result resolves the merge action, not the separate
        # reason this slice was parked. Keep manual/current timeout parks intact.
        cleared = replace(cleared, dispatch_error=None)
    else:
        cleared = replace(cleared, park_cause=None, dispatch_error=None)
    # Record the immutable disposition before clearing its checkpoint action.
    # If the controller stops after the event, the action journal replays this
    # same idempotency key and the next pass can finish the checkpoint. The
    # reverse ordering could permanently lose the disposition on a crash.
    _record_controller_event(
        slice_id,
        "tl.merge_attempt_retired",
        {
            "run_id": state.run_id,
            "slice_id": slice_id,
            "transition_version": 1,
            "rejected_action_key": key,
            "rejected_attempt": rejected_attempt,
            "rejected_error": diagnostic[:500],
            "retired_by": "rejected_journal_terminal_result",
            "released_park_cause": (
                ParkCause.TASK_BUDGET_EXCEEDED.value if park_release_reason is not None else None
            ),
            "park_release_reason": park_release_reason,
            "park_release_pr_number": (
                observation.pr_number
                if park_release_reason is not None and observation is not None
                else None
            ),
            "park_release_head_sha": (
                observation.head_sha
                if park_release_reason is not None and observation is not None
                else None
            ),
        },
        config,
        effects,
        effects_log,
    )
    gate_name = _merge_retirement_gate_name(refreshed, slice_id, key)
    clear_gates = (gate_name,) if any(gate.name == gate_name for gate in refreshed.gates) else ()
    state = _checkpoint_slice_action(
        store,
        refreshed,
        slice_id,
        None,
        slice_state=cleared,
        integration=integration,
        clear_gates=clear_gates,
    )
    LOGGER.info(
        "[TL loop] retired rejected merge attempt slice=%s key=%s",
        slice_id,
        key,
    )
    return store.load()


def _stale_aggregate_timeout_park_release_reason(
    current: SliceState,
    candidate: IntegrationCandidateState | None,
    observation: WatcherObservation | None,
) -> str | None:
    """Prove the legacy worker timeout no longer owns an open aggregate stage.

    A timeout park can be released only when the same persisted aggregate
    publication is still open at the exact action head. The merge rejection
    alone is insufficient: it resolves only the merge action, not the park.
    """
    if (
        current.status is not SliceStatus.PARKED
        or current.park_cause is not ParkCause.TASK_BUDGET_EXCEEDED
    ):
        return None
    if current.dispatch_last_boundary != "aggregate_pr_open":
        return None
    publication = current.publication
    if not _parked_timeout_matches_aggregate_candidate(current, candidate):
        return None
    if not _watcher_confirms_open_publication(publication, observation):
        return None
    return "stale_task_timeout_superseded_by_open_aggregate_publication"


def _parked_timeout_matches_aggregate_candidate(
    current: SliceState,
    candidate: IntegrationCandidateState | None,
) -> bool:
    """Match the persisted merge action and publication to its aggregate."""
    publication = current.publication
    action = current.action
    return bool(
        publication is not None
        and action is not None
        and action.kind is ActionKind.MERGE
        and publication.pr_number == current.pr_number
        and publication.head_sha == action.head_sha
        and candidate is not None
        and candidate.lifecycle is IntegrationLifecycle.MERGING
        and candidate.aggregate_pr_number == publication.pr_number
        and candidate.aggregate_head_sha == publication.head_sha
    )


def _watcher_confirms_open_publication(
    publication: PublicationBinding | None,
    observation: WatcherObservation | None,
) -> bool:
    """Require authoritative open state for the same published coordinates."""
    if publication is None or observation is None:
        return False
    ownership_ok, _ = observation.ownership_status()
    return bool(
        ownership_ok
        and observation.found is True
        and observation.pr_number == publication.pr_number
        and observation.pr_state == "open"
        and observation.merged is False
        and observation.head_sha == publication.head_sha
        and observation.head_branch == publication.head_branch
        and observation.base_branch == publication.base_branch
    )


def _retire_rejected_merge_results(
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Converge terminal rejected merge results into the integration projection.

    A rejected ``merge_pr`` journal entry is authoritative history: the merge
    did not happen. Startup reconciliation only scanned intended/unknown
    entries, so a rejected result left the slice's MERGE action stuck
    ``IN_FLIGHT`` and its candidate at ``MERGING`` forever, waiting for a merge
    event that never arrives.

    This pass acts only on exact evidence: the persisted action's intent id
    resolves to a rejected merge entry for the same slice, a fresh authoritative
    observation resolves the same PR/head, and that observation says the merge
    did not happen. Every other outcome -- an unavailable observation, a
    present-but-refused publication record, a handled/in-flight action, or a
    contradictory merged observation -- is held, adopted, or left to its own
    authoritative owner.
    """
    if not isinstance(effects_log, EffectJournal):
        return state
    state = store.load()
    for slice_id, current in list(state.slices.items()):
        action = current.action
        if (
            action is None
            or action.kind is not ActionKind.MERGE
            or not action.intent_id
            or action.phase not in {ActionPhase.IN_FLIGHT, ActionPhase.UNKNOWN}
        ):
            continue
        entry = effects_log.entry_by_key(action.intent_id)
        if (
            entry is None
            or entry.get("operation") != "merge_pr"
            or entry.get("target") != slice_id
            or entry.get("status") != "rejected"
        ):
            continue
        if current.pr_number is None:
            continue
        key = str(entry.get("key") or "")
        gate = next(
            (
                candidate_gate
                for candidate_gate in state.gates
                if candidate_gate.name == _merge_retirement_gate_name(state, slice_id, key)
            ),
            None,
        )
        operator_approved = gate is not None and gate.status is GateStatus.APPROVED
        # A read-only observation, never journaled: unavailable remote facts
        # leave the rejected entry and checkpoint untouched while the hold gate
        # records the decision that is still needed.
        watcher: ToolResult | None = None
        observation: WatcherObservation | None = None
        try:
            watcher = effects.watcher_pr_state(pr_number=current.pr_number)
            observation = _watcher_result_observation(watcher)
        except (ConnectionError, OSError, RuntimeError, TimeoutError) as error:
            LOGGER.warning(
                "[TL loop] rejected merge for %s: watcher unavailable: %s",
                slice_id,
                error,
            )
        refused = watcher is not None and (
            _watcher_publication_refused(current, watcher, current.dispatch_agent_id or current.id)
            or _watcher_publication_ownership_unresolved(watcher)
        )
        diagnostic = str(entry.get("error") or "merge_pr was rejected")
        if observation is not None and not refused:
            # Require an exact, present head on both sides. A missing head is
            # not a match: unknown evidence must hold rather than authorize a
            # retry or an adoption.
            same_head = bool(
                isinstance(observation.head_sha, str)
                and observation.head_sha
                and isinstance(action.head_sha, str)
                and action.head_sha
                and observation.head_sha == action.head_sha
            )
            if observation.merged is True and same_head:
                state = _reconcile_merged_slice(
                    state,
                    slice_id,
                    observation.pr_number or current.pr_number,
                    action.intent_id,
                    config,
                    effects,
                    store,
                    effects_log,
                    boundary="rejected_journal_remote_merge_reconciled",
                    merge_evidence={
                        **dict(entry.get("arguments") or {}),
                        **_watcher_merge_evidence(observation),
                    },
                )
                state = _clear_merge_retirement_gate(state, store, slice_id, key)
                continue
            if observation.merged is False and same_head:
                if (
                    current.status is SliceStatus.PARKED
                    and current.park_cause is ParkCause.TASK_BUDGET_EXCEEDED
                    and _stale_aggregate_timeout_park_release_reason(
                        current,
                        state.integration.candidates.get(slice_id)
                        if state.integration is not None
                        else None,
                        observation,
                    )
                    is None
                ):
                    state = _hold_rejected_merge(
                        state,
                        store,
                        slice_id,
                        entry,
                        "the rejected merge is resolved, but the task-timeout park is not "
                        "proven stale by the exact open aggregate publication",
                        config,
                        effects,
                        effects_log,
                    )
                    continue
                state = _retire_rejected_merge_attempt(
                    state,
                    store,
                    slice_id,
                    entry,
                    diagnostic,
                    config,
                    effects,
                    effects_log,
                    observation=observation,
                )
                continue
            if operator_approved:
                state = _retire_rejected_merge_attempt(
                    state,
                    store,
                    slice_id,
                    entry,
                    "operator approved retirement of the held rejected merge attempt "
                    f"via gate {_merge_retirement_gate_name(state, slice_id, key)}",
                    config,
                    effects,
                    effects_log,
                )
                continue
            reason = (
                f"rejected merge head {action.head_sha!r} does not exactly match observed "
                f"head {observation.head_sha!r}"
                if observation.merged is False
                else "rejected merge conflicts with a merged PR whose head does not match "
                "the rejected attempt"
                if observation.merged is True
                else "authoritative observation did not prove the rejected merge outcome"
            )
            state = _hold_rejected_merge(
                state, store, slice_id, entry, reason, config, effects, effects_log
            )
            continue
        if operator_approved:
            state = _retire_rejected_merge_attempt(
                state,
                store,
                slice_id,
                entry,
                "operator approved retirement of the held rejected merge attempt "
                f"via gate {_merge_retirement_gate_name(state, slice_id, key)} "
                "without an authoritative observation",
                config,
                effects,
                effects_log,
            )
            continue
        reason = (
            "publication provenance refused the authoritative observation"
            if refused
            else "authoritative observation is unavailable"
        )
        state = _hold_rejected_merge(
            state, store, slice_id, entry, reason, config, effects, effects_log
        )
    return state


def _reconcile_nonterminal_slices(
    plan: WorkPlan,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Rebuild safe derived fields before the cursor advances."""
    state = _retire_rejected_merge_results(state, config, effects, store, effects_log)
    candidates = [
        slice_state
        for slice_state in state.slices.values()
        if slice_state.status
        in {
            SliceStatus.SPAWNED,
            SliceStatus.IN_REVIEW,
            SliceStatus.REPAIRING,
            SliceStatus.PARKED,
        }
    ]
    if not candidates:
        return state

    agent_listing: ToolResult | None = None
    if config.active:
        agent_listing = _invoke(
            "list_agents",
            "controller-reconciliation",
            {},
            True,
            cast(EffectClient, effects),
            lambda client: client.list_agents(),
            effects_log,
            raise_on_failure=False,
        )
    snapshots: dict[int, WatcherObservation | None] = {}
    updated = dict(state.slices)
    conflicts_found = False
    changed = False
    reconciled_aggregate_identity = False
    gate_evidence_complete = True
    for current in candidates:
        healed = _heal_stale_reviewer_action(current, effects_log)
        if healed is not None:
            current = healed
            updated[current.id] = healed
            changed = True
            LOGGER.info(
                "[TL loop] healed stale reviewer action target=%s head=%s",
                current.id,
                current.reviewed_head,
            )
        watcher = None
        if current.pr_number is not None and config.ledger_run_id is not None:
            if current.pr_number not in snapshots:
                snapshots[current.pr_number] = _watcher_snapshot(
                    current.pr_number,
                    config,
                    effects,
                    effects_log,
                )
            watcher = snapshots[current.pr_number]
        elif config.ledger_run_id is not None:
            # pr_number was never persisted (e.g. a crash between pr.filed
            # being acknowledged and identity association). Recover it from
            # the durable publication registry keyed by slice_id.
            watcher = _watcher_snapshot_for_slice(
                current.id,
                config,
                effects,
                effects_log,
            )
            recovered_pr_number = watcher.get("pr_number") if watcher else None
            if isinstance(recovered_pr_number, int) and recovered_pr_number > 0:
                snapshots[recovered_pr_number] = watcher
        if current.status is SliceStatus.PARKED:
            # A parked slice is reconciled only to confirm the park it already
            # holds; every other derived field is left alone, and a slice whose
            # observation no longer proves its cause stays parked untouched.
            reconfirmed = _reconfirm_park(current, watcher, state, store, effects, effects_log)
            if reconfirmed is not None:
                updated[current.id] = reconfirmed
                changed = True
                current = reconfirmed
            state = store.load()
            continue
        if _aggregate_resume_requires_owner_reconciliation(plan, current, watcher, config):
            LOGGER.info(
                "[TL loop] deferring resumed aggregate publication to its owner reconciler: slice=%s",
                current.id,
            )
            continue
        aggregate_task = next(
            (task for task in plan.sub_tls if task.name == current.id),
            None,
        )
        owner_id = (
            aggregate_task.agent_id or aggregate_task.name
            if aggregate_task is not None
            else _agent_for_dispatch_intent(
                agent_listing,
                current.dispatch_intent_id or "",
            )
        )
        if aggregate_task is not None:
            restored = _restore_legacy_aggregate_dispatch_owner(
                aggregate_task,
                current,
                watcher,
                owner_id,
                state,
                config,
                effects,
                effects_log,
            )
            if restored is not None:
                current = restored
                updated[current.id] = restored
                changed = True
                reconciled_aggregate_identity = True
        # A watcher-only merge may be adopted when publication provenance
        # validates against the dispatch or active recovery succession. A
        # confirmed, exact merge journal is a separate authority for adopting
        # an operation already checked before dispatch; it never authorizes a
        # new merge. A refused snapshot still cannot change state.
        accepted_publication = (
            _publication_from_watcher(current, watcher, watcher.head_sha, owner_id)
            if watcher is not None
            else None
        )
        # A journal-confirmed merge is accepted only for the same persisted
        # PR/head and matching watcher observation. Without that completed
        # action, watcher provenance must validate before it can authorize
        # adoption.
        watcher_presents_publication = _watcher_presents_publication(watcher)
        watcher_merged = watcher is not None and watcher.merged is True
        merge_evidence = _watcher_merge_evidence(watcher) if watcher_merged else None
        merge_entry = (
            _confirmed_merge_entry(effects_log, current, watcher.pr_number)
            if watcher_merged and watcher is not None
            else None
        )
        journaled_merge_authorized = (
            merge_entry is not None
            and _merge_journal_is_exact(current, merge_entry)
            and _merge_journal_reports_success(merge_entry)
            and _merge_watcher_identity_matches(current, watcher, merge_entry)
            and (
                current.action is None
                or current.action.kind is not ActionKind.MERGE
                or not current.action.intent_id
                or current.action.intent_id == merge_entry.get("key")
            )
        )
        # A successful merge effect has already checked publication ownership
        # and compare-and-swap before it reaches Forgejo. Cleanup can then
        # remove the worker identity, so a post-merge watcher read may report
        # unresolved ownership. The exact confirmed journal entry remains
        # sufficient to adopt that merge; it cannot authorize a new merge.
        durable_merge_authorized = journaled_merge_authorized or (
            not watcher_presents_publication
            and merge_evidence is not None
            and _merge_action_is_exact(current, merge_evidence)
        )
        merge_authorized = accepted_publication is not None or durable_merge_authorized
        if _watcher_publication_refused(current, watcher, owner_id) or (
            publication_ownership_malformed(watcher)
        ):
            # A present-but-refused or malformed-ownership record may not change
            # any durable slice or run state: no reconciliation result, merge
            # readiness, unknown-merge resolution, review replay, park, or
            # state-changing effect. An explicit unverified verdict is excluded
            # here so it still reaches the ownership park path below.
            LOGGER.warning(
                "[TL loop] refusing watcher snapshot for %s: publication provenance mismatch",
                current.id,
            )
            continue
        if (
            current.action is not None
            and current.action.kind is ActionKind.MERGE
            and current.action.phase is ActionPhase.UNKNOWN
        ):
            if (
                watcher is not None
                and watcher.merged is True
                and merge_evidence is not None
                and merge_authorized
                and current.action.intent_id
                and isinstance(merge_evidence.get("head_sha"), str)
                and isinstance(merge_evidence.get("base_sha"), str)
                and watcher.pr_number in {None, current.pr_number}
            ):
                state = _reconcile_merged_slice(
                    store.load(),
                    current.id,
                    watcher.pr_number or current.pr_number or 0,
                    current.action.intent_id,
                    config,
                    effects,
                    store,
                    effects_log,
                    boundary="legacy_unknown_merge_reconciled",
                    merge_evidence=merge_evidence,
                )
                updated = dict(state.slices)
                changed = False
                continue
            if (
                watcher is not None
                and watcher.merged is False
                and watcher.pr_number in {None, current.pr_number}
            ):
                state = _resolve_nonmerged_merge(
                    state,
                    current.id,
                    store,
                    effects_log,
                    journal_key=None,
                    diagnostic="authoritative watcher state says the merge did not happen",
                )
                updated = dict(state.slices)
                changed = False
                continue
            state, handled = _reconcile_merge_recovery_gate(
                state,
                current,
                store,
                effects_log,
            )
            if handled:
                updated = dict(state.slices)
                changed = False
                continue
        if (
            watcher is not None
            and watcher.merged is True
            and merge_entry is not None
            and merge_authorized
        ):
            state = _adopt_authoritative_merged_snapshot(
                state,
                current.id,
                watcher.pr_number or current.pr_number or 0,
                merge_entry,
                config,
                effects,
                store,
                effects_log,
                merge_evidence=merge_evidence,
            )
            updated = dict(state.slices)
            changed = False
            continue
        result = reconcile_slice(
            current,
            authoritative_owner_id=owner_id,
            watcher=watcher,
        )
        unresolved_for_gate = bool(result.conflicts) or bool(result.missing_evidence)
        if aggregate_task is not None and set(result.missing_evidence) <= {"review_state"}:
            unresolved_for_gate = bool(result.conflicts)
        gate_evidence_complete &= not unresolved_for_gate
        reconciled = _apply_reconciliation_observations(
            current,
            result,
            watcher,
            owner_id,
            accepted_publication=accepted_publication,
        )
        if watcher is not None:
            replay_state = replace(
                state,
                slices={**state.slices, **updated, current.id: reconciled},
            )
            replayed = _replay_watcher_review_if_needed(
                plan,
                replay_state,
                reconciled,
                watcher,
                config,
                effects,
                store,
                effects_log,
            )
            if replayed != state:
                state = replayed
                reconciled = state.slices[current.id]
        if watcher is not None and (not watcher_merged or merge_authorized):
            # A refused snapshot may not adopt merge readiness either; only an
            # authorized merge (or a non-merged observation) folds here.
            reconciled = reconcile_merge_observation(reconciled, watcher)
        if current.handoff is None and watcher is not None:
            handoff_payload = _handoff_reconciliation_event_payload(
                current,
                reconciled,
                watcher,
                owner_id,
            )
            if handoff_payload is not None:
                _record_controller_event(
                    current.id,
                    "tl.handoff_reconciled",
                    handoff_payload,
                    config,
                    effects,
                    effects_log,
                )
        if result.next_action in {
            "park_closed_unmerged_pr",
            "park_unreachable_pr_head",
            "park_publication_ownership_unresolved",
        }:
            if isinstance(effects, ReadOnlyEffectClient):
                raise TLLoopError(
                    f"reconciliation for {current.id!r} requires an active effect client to park"
                )
            cause = {
                "park_closed_unmerged_pr": ParkCause.PR_CLOSED_UNMERGED,
                "park_unreachable_pr_head": ParkCause.PR_HEAD_UNREACHABLE,
                "park_publication_ownership_unresolved": (
                    ParkCause.PUBLICATION_OWNERSHIP_UNRESOLVED
                ),
            }[result.next_action]
            park_audit = {
                "reconciliation": result.as_state(),
                "pr_number": current.pr_number or (watcher.pr_number if watcher else None),
                "head_sha": _snapshot_text(watcher, "head_sha") if watcher else None,
                "branch": _snapshot_text(watcher, "head_branch") if watcher else current.branch,
                "observed_at": _now_timestamp(),
                "observation_error": _snapshot_text(watcher, "evidence_error") if watcher else None,
                "publication_ownership_error": (
                    (
                        watcher.publication_ownership_error
                        or _publication_ownership_status(watcher)[1]
                    )
                    if watcher
                    else None
                ),
            }
            if reconciled != current:
                state = store.checkpoint(
                    state.fsm,
                    {**state.slices, current.id: reconciled},
                    state.budgets,
                    state.events.last_consumed_offset,
                    current_order=state.current_order,
                    ordered_stages=state.ordered_stages,
                    integration=state.integration,
                )
            park(
                state.slices[current.id],
                cause,
                store=store,
                issue_creator=effects,
                ledger=state.budgets,
                audit=park_audit,
            )
            state = store.load()
            parked_slice = replace(state.slices[current.id], reconciliation=result.as_state())
            state = store.checkpoint(
                state.fsm,
                {**state.slices, current.id: parked_slice},
                state.budgets,
                state.events.last_consumed_offset,
                current_order=state.current_order,
                ordered_stages=state.ordered_stages,
                integration=state.integration,
            )
            updated = dict(state.slices)
            changed = False
            continue
        if reconciled != current:
            updated[current.id] = reconciled
            changed = True
        conflicts_found |= bool(result.conflicts)

    if changed:
        checkpoint_phase = _reconciliation_phase(state, updated)
        clear_integrity_gate = (
            reconciled_aggregate_identity
            and gate_evidence_complete
            and not conflicts_found
            and any(
                gate.name == INTEGRITY_RECONCILIATION_GATE_NAME
                and gate.status is GateStatus.PENDING
                for gate in state.gates
            )
        )
        if clear_integrity_gate:
            _record_controller_event(
                "controller",
                "tl.integrity_reconciliation_cleared",
                {
                    "run_id": state.run_id,
                    "gate_name": INTEGRITY_RECONCILIATION_GATE_NAME,
                    "resolved_slice_ids": sorted(
                        current.id
                        for current in candidates
                        if updated[current.id].dispatch_last_boundary
                        in _AGGREGATE_DISPATCH_BOUNDARIES
                    ),
                    "evidence": "all active publication bindings revalidated without conflicts",
                    "transition_version": 1,
                },
                config,
                effects,
                effects_log,
            )
        state = store.checkpoint(
            checkpoint_phase,
            updated,
            state.budgets,
            state.events.last_consumed_offset,
            current_order=state.current_order,
            ordered_stages=state.ordered_stages,
            integration=state.integration,
            expected_revision=state.revision,
            clear_gates=((INTEGRITY_RECONCILIATION_GATE_NAME,) if clear_integrity_gate else ()),
        )
    elif reconciled_aggregate_identity and gate_evidence_complete and not conflicts_found:
        if any(
            gate.name == INTEGRITY_RECONCILIATION_GATE_NAME and gate.status is GateStatus.PENDING
            for gate in state.gates
        ):
            _record_controller_event(
                "controller",
                "tl.integrity_reconciliation_cleared",
                {
                    "run_id": state.run_id,
                    "gate_name": INTEGRITY_RECONCILIATION_GATE_NAME,
                    "resolved_slice_ids": sorted(
                        current.id
                        for current in candidates
                        if updated[current.id].dispatch_last_boundary
                        in _AGGREGATE_DISPATCH_BOUNDARIES
                    ),
                    "evidence": "all active publication bindings revalidated without conflicts",
                    "transition_version": 1,
                },
                config,
                effects,
                effects_log,
            )
            state = store.checkpoint(
                state.fsm,
                state.slices,
                state.budgets,
                state.events.last_consumed_offset,
                current_order=state.current_order,
                ordered_stages=state.ordered_stages,
                integration=state.integration,
                expected_revision=state.revision,
                clear_gates=(INTEGRITY_RECONCILIATION_GATE_NAME,),
            )
    if conflicts_found:
        state = store.set_gate(INTEGRITY_RECONCILIATION_GATE_NAME, GateStatus.PENDING)
    return state


def _restore_legacy_aggregate_dispatch_owner(
    task: SubTLTask,
    current: SliceState,
    watcher: WatcherObservation | Mapping[str, object] | None,
    owner_id: str | None,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> SliceState | None:
    """Restore a coordinator-overwritten dispatch owner from exact publication proof."""
    coordinator_id = f"{state.run_id}:{task.name}:integration"
    candidate = state.integration.candidates.get(task.name)
    observation = _as_watcher_observation(watcher)
    manifest = state.plan_manifest
    node = (
        next(
            (item for item in manifest.nodes if item.name == task.name and item.kind == "sub_tl"),
            None,
        )
        if manifest is not None
        else None
    )
    child_manifest = (
        manifest.child_manifests.get(node.node_id)
        if manifest is not None and node is not None
        else None
    )
    if (
        owner_id is None
        or current.dispatch_agent_id != coordinator_id
        or current.dispatch_last_boundary not in _AGGREGATE_DISPATCH_BOUNDARIES
        or not current.dispatch_intent_id
        or not current.dispatch_invocation_id
        or current.dispatch_generation <= 0
        or child_manifest is None
        or child_manifest.scope_id != node.node_id
        or child_manifest.owned_branch != current.branch
        or child_manifest.parent_integration_target != current.base_ref
        or candidate is None
        or candidate.integration_owner_id != coordinator_id
        or candidate.integration_owner_run_id != task.name
        or candidate.integration_owner_branch != child_manifest.owned_branch
        or candidate.aggregate_pr_number != current.pr_number
        or candidate.aggregate_head_sha is None
        or observation is None
        or observation.head_sha != candidate.aggregate_head_sha
        or observation.patch_digest != candidate.aggregate_patch_digest
        or candidate.integration_owner_worktree != current.worktree
    ):
        return None
    declared_dispatch = replace(current, dispatch_agent_id=owner_id)
    publication = _publication_from_watcher(
        declared_dispatch, observation, observation.head_sha, owner_id
    )
    if publication is None or publication.pr_number != candidate.aggregate_pr_number:
        return None
    _record_controller_event(
        task.name,
        "tl.aggregate_dispatch_identity_reconciled",
        {
            "run_id": state.run_id,
            "slice_id": task.name,
            "transition_version": 1,
            "old_dispatch_agent_id": coordinator_id,
            "restored_dispatch_agent_id": owner_id,
            "dispatch_intent_id": current.dispatch_intent_id,
            "dispatch_invocation_id": current.dispatch_invocation_id,
            "dispatch_generation": current.dispatch_generation,
            "aggregate_pr_number": publication.pr_number,
            "aggregate_head_sha": publication.head_sha,
            "aggregate_branch": publication.head_branch,
            "aggregate_base_branch": publication.base_branch,
            "candidate_owner_run_id": candidate.integration_owner_run_id,
            "candidate_owner_branch": candidate.integration_owner_branch,
            "candidate_owner_worktree": candidate.integration_owner_worktree,
            "declared_scope_id": child_manifest.scope_id,
            "child_manifest_digest": child_manifest.digest,
        },
        config,
        effects,
        effects_log,
    )
    return replace(current, dispatch_agent_id=owner_id)


def _aggregate_resume_requires_owner_reconciliation(
    plan: WorkPlan,
    current: SliceState,
    watcher: WatcherObservation | Mapping[str, object] | None,
    config: TLLoopConfig,
) -> bool:
    """Keep resumed aggregate adoption on the path that durably checkpoints lineage."""
    task = _aggregate_resume_task(plan, current.id)
    observation = _as_watcher_observation(watcher)
    if (
        task is None
        or observation is None
        or observation.publication is None
        or config.project_root is None
        or current.dispatch_invocation_id is None
    ):
        return False
    record = _read_durable_sub_tl_invocation(config.project_root, task.agent_id or task.name)
    return _aggregate_resume_observation_matches(task, current, observation, record)


def _aggregate_resume_task(plan: WorkPlan, slice_id: str) -> SubTLTask | None:
    """Find the planned aggregate owner for one persisted slice."""
    return next(
        (
            task
            for task in plan.sub_tls
            if task.name == slice_id and task.integration.aggregate_pr_required
        ),
        None,
    )


def _aggregate_resume_observation_matches(
    task: SubTLTask,
    current: SliceState,
    observation: WatcherObservation,
    record: Mapping[str, object] | None,
) -> bool:
    """Check whether this watcher record needs lineage checkpointing first."""
    if record is None or observation.publication is None:
        return False
    if not _authorized_aggregate_resume(
        record,
        task.name,
        current.branch or "",
        current.worktree or "",
        current.dispatch_invocation_id,
    ):
        return False
    resumed_id = record.get("invocation_id")
    succession_matches = (
        record.get("prior_invocation_id") == current.dispatch_invocation_id
        or current.dispatch_invocation_id in observation.publication.succession_invocation_ids
    )
    return bool(
        observation.publication.invocation_id == resumed_id
        and succession_matches
        and observation.pr_number == record.get("pr_number")
        and observation.head_branch == current.branch
        and observation.base_branch == current.base_ref
    )


def _watcher_presents_publication(watcher: WatcherObservation | None) -> bool:
    """Whether the watcher snapshot carries any publication provenance at all.

    Delegates to the shared validator so the driver and heartbeat agree.
    """
    return watcher_presents_publication(watcher)


def _watcher_publication_refused(
    current: SliceState,
    watcher: ToolResult | WatcherObservation | Mapping[str, object] | None,
    owner_id: str | None = None,
) -> bool:
    """Whether a watcher presents a publication record that fails validation.

    A present-but-refused record may not change any durable slice or run state
    through any watcher-driven path.
    """
    if isinstance(watcher, ToolResult):
        observation = _watcher_result_observation(watcher)
    else:
        observation = _as_watcher_observation(watcher)
    if observation is None:
        return False
    return publication_refused(current, observation, observation.head_sha, owner_id)


def _watcher_publication_ownership_unresolved(
    watcher: ToolResult | WatcherObservation | Mapping[str, object] | None,
) -> bool:
    """Whether a watcher presents publication evidence with unresolved ownership.

    An explicit unverified verdict, or a publication record whose ownership was
    never verified, must not authorize a destructive merge.
    """
    if isinstance(watcher, ToolResult):
        observation = _watcher_result_observation(watcher)
    else:
        observation = _as_watcher_observation(watcher)
    if observation is None:
        return False
    return publication_ownership_unresolved(observation)


def _persisted_merge_head(current: SliceState) -> str | None:
    if current.reviewed_head:
        return current.reviewed_head
    if current.action is not None and current.action.head_sha:
        return current.action.head_sha
    return None


def _merge_journal_reports_success(merge_entry: Mapping[str, object]) -> bool:
    """Require the confirmed effect envelope and MergePrResponse to both succeed."""
    result = merge_entry.get("result")
    if not isinstance(result, Mapping) or result.get("success") is not True:
        return False
    payload = result.get("result")
    return isinstance(payload, Mapping) and (
        payload.get("success") is True or payload.get("merged") is True
    )


def _merge_watcher_identity_matches(
    current: SliceState,
    watcher: WatcherObservation | None,
    merge_entry: Mapping[str, object],
) -> bool:
    """Match a post-merge observation to the PR/head authorized by the journal."""
    arguments = merge_entry.get("arguments")
    if not isinstance(arguments, Mapping) or watcher is None or watcher.merged is not True:
        return False
    expected_pr = arguments.get("pr_number")
    expected_head = arguments.get("expected_head_sha")
    if (
        type(expected_pr) is not int
        or expected_pr <= 0
        or not isinstance(expected_head, str)
        or not expected_head
        or watcher.pr_number != expected_pr
        or current.pr_number != expected_pr
        or watcher.head_sha != expected_head
    ):
        return False
    if current.branch and watcher.head_branch != current.branch:
        return False
    expected_base_branch = current.publication.base_branch if current.publication else None
    expected_base_branch = expected_base_branch or current.base_ref
    return not (
        expected_base_branch
        and watcher.base_branch is not None
        and watcher.base_branch != expected_base_branch
    )


def _merge_journal_is_exact(current: SliceState, merge_entry: Mapping[str, object]) -> bool:
    """Whether a confirmed merge journal entry is exact to the persisted PR/head."""
    arguments = merge_entry.get("arguments")
    if not isinstance(arguments, Mapping):
        return False
    journal_pr_number = arguments.get("pr_number")
    if type(journal_pr_number) is not int or journal_pr_number <= 0:
        return False
    if current.pr_number is not None and journal_pr_number != current.pr_number:
        return False
    expected_head = arguments.get("expected_head_sha")
    if not isinstance(expected_head, str) or not expected_head:
        return False
    persisted_head = _persisted_merge_head(current)
    return persisted_head is not None and expected_head == persisted_head


def _merge_action_is_exact(current: SliceState, merge_evidence: Mapping[str, object]) -> bool:
    """Whether the durable unknown-merge action head matches the observed head."""
    action = current.action
    if action is None or not action.intent_id or not action.head_sha:
        return False
    return merge_evidence.get("head_sha") == action.head_sha


def _confirmed_merge_entry(
    effects_log: list[EffectIntent],
    current: SliceState,
    observed_pr_number: int | None,
) -> Mapping[str, object] | None:
    """Find durable merge evidence without reconstructing its arguments."""
    if not isinstance(effects_log, EffectJournal):
        return None
    for entry in effects_log.confirmed_entries("merge_pr", current.id):
        arguments = entry.get("arguments")
        if not isinstance(arguments, Mapping):
            continue
        journal_pr_number = arguments.get("pr_number")
        if type(journal_pr_number) is not int:
            continue
        if observed_pr_number is not None and journal_pr_number != observed_pr_number:
            continue
        if current.pr_number is not None and journal_pr_number != current.pr_number:
            continue
        if not _merge_journal_reports_success(entry):
            continue
        return entry
    return None


def _adopt_authoritative_merged_snapshot(
    state: RunState,
    slice_id: str,
    pr_number: int,
    merge_entry: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    merge_evidence: Mapping[str, object] | None = None,
) -> RunState:
    """Adopt a journal-confirmed merge before review/ownership recovery."""
    arguments = merge_entry.get("arguments")
    merge_key = merge_entry.get("key")
    merge_journal_id = merge_key if isinstance(merge_key, str) else ""
    authoritative_evidence = dict(arguments) if isinstance(arguments, Mapping) else {}
    if merge_evidence is not None:
        authoritative_evidence.update(merge_evidence)
    return _reconcile_merged_slice(
        state,
        slice_id,
        pr_number,
        merge_journal_id,
        config,
        effects,
        store,
        effects_log,
        boundary="authoritative_merge_adopted",
        merge_evidence=authoritative_evidence,
    )


def _reconciliation_phase(
    state: RunState,
    slices: Mapping[str, SliceState],
) -> PhaseValue:
    phase = _phase_from_state(state)
    if not isinstance(phase, TLWaiting):
        return phase
    handles = {
        slice_id: ChildHandle(
            slice_id,
            slice_state.branch or "",
            slice_state.agent_type or "unknown",
        )
        for slice_id, slice_state in slices.items()
        if slice_state.status
        in {
            SliceStatus.SPAWNED,
            SliceStatus.IN_REVIEW,
            SliceStatus.REPAIRING,
            SliceStatus.MERGED,
        }
        and (
            slice_state.status is not SliceStatus.MERGED
            or slice_state.post_merge is None
            or slice_state.post_merge.phase is not PostMergePhase.COMPLETE
        )
    }
    if handles:
        return TLWaiting(handles)
    return (
        TLAllMerged()
        if all(item.status is SliceStatus.MERGED for item in slices.values())
        else TLPlanning()
    )


def _replay_watcher_review_if_needed(
    plan: WorkPlan,
    state: RunState,
    current: SliceState,
    watcher: WatcherObservation | Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Revalidate one exact-head review snapshot without creating a new round."""
    observed_watcher = _as_watcher_observation(watcher)
    if observed_watcher is None:
        return state
    watcher = observed_watcher
    head_sha = watcher.head_sha
    review_head_sha = watcher.review_head_sha
    reviewer_agent_id = watcher.reviewer_agent_id
    ownership_verified, _ = watcher.ownership_status()
    freshness_window_secs = (
        load_freshness_window(config.review_policy_path)
        if config.review_policy_path is not None
        else None
    )
    stale_verdict = current.verdict is not None and verdict_is_stale(
        current,
        now=config.review_clock() if config.review_clock is not None else None,
        freshness_window_secs=freshness_window_secs,
    )
    if (
        current.status not in {SliceStatus.SPAWNED, SliceStatus.IN_REVIEW, SliceStatus.REPAIRING}
        or watcher.found is not True
        or not head_sha
        or not review_head_sha
        or review_head_sha != head_sha
        or current.reviewed_head not in {None, head_sha}
        or watcher.review_id is None
        or not reviewer_agent_id
        or watcher.reviewer_identity_error
        or not ownership_verified
        or current.handoff is None
        or current.handoff.head_sha != head_sha
        or current.dispatch_agent_id == reviewer_agent_id
        or (current.pr_number is not None and watcher.pr_number != current.pr_number)
        or watcher.review_verdict not in {"approved", "changes_requested"}
    ):
        if stale_verdict and not current.review_validation_required:
            return _persist_review_validation_failure(
                state,
                current,
                store,
                disposition=ReviewValidationDisposition.INVALIDATED,
                reason="authoritative_review_observation_incomplete",
            )
        return state
    publication = watcher.publication
    if publication is not None:
        if publication.slice_id not in {None, current.id}:
            return state
        if current.dispatch_agent_id is not None and publication.author_agent not in {
            None,
            current.dispatch_agent_id,
        }:
            return state
    kind = "approved" if watcher.review_verdict == "approved" else "review_received"
    review_rationale = (watcher.review_body or "").strip()
    if not review_rationale:
        review_rationale = (
            f"Forgejo review {watcher.review_id} requested changes on exact head {head_sha}"
        )
    findings = (
        []
        if kind == "approved"
        else [
            {
                "severity": "blocking",
                "path": "review",
                "rationale": review_rationale,
            }
        ]
    )
    observed_at = _now_timestamp()
    pr_number = watcher.pr_number or current.pr_number
    if pr_number is None:
        return _request_review_revalidation(
            state,
            current,
            store,
            reason="authoritative_review_pr_missing",
        )
    observation = ReviewValidationObservation(
        review_id=watcher.review_id,
        pr_number=pr_number,
        head_sha=head_sha,
        reviewer_agent_id=reviewer_agent_id,
        verdict=Verdict.GO if kind == "approved" else Verdict.NO_GO,
        observed_at=observed_at,
        # A proto string answers as empty when it has no value, and the
        # observation contract takes a non-empty timestamp or none. Normalizing
        # here keeps a snapshot with no submission time from raising inside the
        # reducer, where it would take the controller down.
        submitted_at=(
            (
                current.review_evidence.submitted_at
                if current.review_evidence is not None
                and current.review_evidence.review_id == watcher.review_id
                else watcher.review_submitted_at
            )
            or None
        ),
    )
    disposition = review_validation_disposition(
        current.review_evidence,
        observation,
        now=config.review_clock() if config.review_clock is not None else None,
        freshness_window_secs=freshness_window_secs,
    )
    if disposition is ReviewValidationDisposition.OUT_OF_ORDER:
        LOGGER.info(
            "[TL loop] stale watcher review ignored target=%s review_id=%s current_review_id=%s",
            current.id,
            observation.review_id,
            current.review_evidence.review_id if current.review_evidence is not None else None,
        )
        return state
    if current.verdict is not None and disposition is ReviewValidationDisposition.ALREADY_FRESH:
        if current.review_validation_required:
            return _persist_review_validation(
                state,
                current,
                observation,
                store,
                submitted_at=observation.submitted_at,
            )
        LOGGER.info(
            "[TL loop] review validation ignored target=%s disposition=%s state_version=%s",
            current.id,
            disposition.value,
            state.state_version,
        )
        return state
    if (
        current.verdict is not None
        and disposition is ReviewValidationDisposition.REFRESHED
        and current.reviewed_head == head_sha
        and current.verdict == observation.verdict
    ):
        return _persist_review_validation(
            state,
            current,
            observation,
            store,
            submitted_at=observation.submitted_at,
        )
    if current.verdict is not None and disposition in {
        ReviewValidationDisposition.INVALIDATED,
        ReviewValidationDisposition.UNAUTHORIZED,
    }:
        return _persist_review_validation_failure(
            state,
            current,
            store,
            disposition=disposition,
            reason=f"review_validation_{disposition.value}",
        )
    event = project(
        {
            "event_type": "pr.review",
            "run_id": state.run_id,
            "agent_id": reviewer_agent_id,
            "slice_id": current.id,
            "pr_number": pr_number,
            "head_sha": head_sha,
            "role": "reviewer",
            "lifecycle_state": "running",
            "observed_at": observed_at,
            "data": {
                "kind": kind,
                "slice_id": current.id,
                "pr_number": pr_number,
                "head_sha": head_sha,
                "review_head_sha": review_head_sha,
                "review_id": watcher.review_id,
                "review_submitted_at": observation.submitted_at or observed_at,
                "submitted_at": observation.submitted_at or observed_at,
                "validated_at": observed_at,
                "reviewer_agent_id": reviewer_agent_id,
                "reviewer_account_authenticated": True,
                "reviewer_identity_unresolved": False,
                "verdict": "GO" if kind == "approved" else "NO-GO",
                "findings": findings,
                "review_state": watcher.review_verdict,
                "ci_status": watcher.ci_status,
                "source": "watcher_snapshot",
            },
        }
    )
    replayed = _route_review_event(
        plan,
        store,
        state,
        _phase_from_state(state),
        event,
        state.events.last_consumed_offset,
        config,
        effects,
        effects_log,
    )
    updated = replayed.slices[current.id]
    if updated.verdict is None:
        LOGGER.warning(
            "[TL loop] rejected exact-head watcher review replay target=%s review_id=%s reviewer=%s",
            current.id,
            watcher.review_id,
            reviewer_agent_id,
        )
        return state
    _record_controller_event(
        current.id,
        "tl.review_reconciled",
        {
            "slice_id": current.id,
            "pr_number": watcher.pr_number or current.pr_number,
            "head_sha": head_sha,
            "review_id": watcher.review_id,
            "verdict": watcher.review_verdict,
            "reviewer_agent_id": reviewer_agent_id,
            "source": "authoritative_watcher_snapshot",
        },
        config,
        effects,
        effects_log,
    )
    return replayed


def _persist_review_validation(
    state: RunState,
    current: SliceState,
    observation: ReviewValidationObservation,
    store: RunStore,
    *,
    submitted_at: str | None,
) -> RunState:
    """Persist one successful revalidation and its single version advance."""
    requested = slice_transition(current, RevalidateReview())
    validated = slice_transition(
        requested,
        ReviewValidated(observation, submitted_at=submitted_at),
    )
    if validated == current:
        return state
    refreshed = store.checkpoint(
        state.fsm,
        {**state.slices, current.id: validated},
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=state.integration,
        state_version=(
            state.state_version
            if (
                current.review_validation_required
                and current.review_evidence is not None
                and current.review_validation_disposition is None
            )
            else state.state_version + 1
        ),
    )
    LOGGER.info(
        "[TL loop] review validation refreshed target=%s disposition=refreshed state_version=%s->%s",
        current.id,
        state.state_version,
        refreshed.state_version,
    )
    return refreshed


def _persist_review_validation_failure(
    state: RunState,
    current: SliceState,
    store: RunStore,
    *,
    disposition: ReviewValidationDisposition,
    reason: str,
) -> RunState:
    """Persist a named validation failure and keep the verdict quiescent."""
    if not reason:
        raise ValueError("review validation failure reason must be non-empty")
    failed = slice_transition(
        current,
        ReviewValidationFailed(disposition=disposition, reason=reason),
    )
    if failed == current:
        return state
    failed_state = store.checkpoint(
        state.fsm,
        {**state.slices, current.id: failed},
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=state.integration,
        state_version=state.state_version + 1,
    )
    LOGGER.warning(
        "[TL loop] review validation failed target=%s disposition=%s reason=%s state_version=%s->%s",
        current.id,
        disposition.value,
        reason,
        state.state_version,
        failed_state.state_version,
    )
    return failed_state


def _request_review_revalidation(
    state: RunState,
    current: SliceState,
    store: RunStore,
    *,
    reason: str,
) -> RunState:
    """Durably quiesce a stale verdict until a fresh authoritative observation arrives."""
    if not reason:
        raise ValueError("review revalidation reason must be non-empty")
    requested = slice_transition(current, RevalidateReview())
    if requested == current:
        return state
    requested_state = store.checkpoint(
        state.fsm,
        {**state.slices, current.id: requested},
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=state.integration,
        state_version=state.state_version + 1,
    )
    LOGGER.info(
        "[TL loop] review validation requested target=%s reason=%s state_version=%s->%s",
        current.id,
        reason,
        state.state_version,
        requested_state.state_version,
    )
    return requested_state


_ACCEPTED_PUBLICATION_UNSET = object()


def _apply_reconciliation_observations(
    current: SliceState,
    result: ReconciliationResult,
    watcher: WatcherObservation | Mapping[str, object] | None,
    owner_id: str | None,
    *,
    accepted_publication: PublicationBinding | None | object = _ACCEPTED_PUBLICATION_UNSET,
) -> SliceState:
    watcher = _as_watcher_observation(watcher)
    updates: dict[str, object] = {"reconciliation": result.as_state()}
    transitioned = current
    if result.conflicts:
        return replace(current, **updates)

    if watcher is not None and watcher.found is True:
        head_sha = watcher.head_sha
        ci_status = watcher.ci_status
        # Reuse the caller's validated binding when supplied so the merge and
        # handoff decisions cannot diverge between reconciliation paths.
        if accepted_publication is _ACCEPTED_PUBLICATION_UNSET:
            publication = _publication_from_watcher(current, watcher, head_sha, owner_id)
        else:
            publication = cast(PublicationBinding | None, accepted_publication)
        if publication is not None:
            # PR number, head/CI evidence, handoff, and merge adoption all
            # require the accepted binding, so a refused provenance mismatch can
            # never mutate the slice.
            updates["publication"] = publication
            updates["pr_number"] = publication.pr_number
            if head_sha and ci_status in CI_STATUS_VALUES:
                transitioned = slice_transition(
                    transitioned,
                    HeadEvidenceObserved(
                        head_sha=head_sha,
                        ci_status=ci_status,
                        bind_reviewed_head=(
                            not _is_aggregate_slice(current)
                            and transitioned.reviewed_head in {None, head_sha}
                        ),
                    ),
                )
            effective_agent_id = current.dispatch_agent_id or owner_id
            invocation_id = current.dispatch_invocation_id
            if invocation_id is None:
                invocation_id = publication.invocation_id
            if (
                head_sha
                and effective_agent_id
                and invocation_id
                and (
                    current.publication is None
                    or (
                        current.publication.pr_number == publication.pr_number
                        and current.publication.head_sha == head_sha
                    )
                )
            ):
                attempt = publication.attempt
                updates["handoff"] = HandoffEvidence(
                    pr_number=publication.pr_number,
                    head_sha=head_sha,
                    attempt=attempt,
                    invocation_id=invocation_id,
                    agent_id=effective_agent_id,
                    observed_at=_now_timestamp(),
                )
                if current.status is SliceStatus.SPAWNED:
                    transitioned = slice_transition(
                        transitioned, SliceStatusChanged(SliceStatus.IN_REVIEW)
                    )
            else:
                missing = [
                    name
                    for name, value in (
                        ("head_sha", head_sha),
                        ("pr_number", publication.pr_number),
                        ("owner_agent_id", effective_agent_id),
                        ("invocation_id_provenance", invocation_id),
                    )
                    if not value
                ]
                LOGGER.warning(
                    "[TL loop] skipping handoff backfill for %s: missing %s",
                    current.id,
                    ", ".join(missing) or "matching publication identity",
                )
            if watcher.merged is True:
                transitioned = slice_transition(
                    transitioned, MergeCompleted(watcher.pr_number or 0)
                )
        elif watcher.publication_ownership_verified is True:
            LOGGER.warning(
                "[TL loop] skipping watcher reconciliation for %s: publication provenance was refused",
                current.id,
            )
        elif watcher.found is True:
            _, ownership_reason = _publication_ownership_status(watcher)
            LOGGER.warning(
                "[TL loop] skipping handoff backfill for %s: publication ownership is not verified (%s)",
                current.id,
                watcher.publication_ownership_error
                or ownership_reason
                or "host publication identity unavailable",
            )
    if owner_id is not None and current.dispatch_agent_id is None:
        updates["dispatch_agent_id"] = owner_id
    return replace(transitioned, **updates)


def _publication_from_watcher(
    current: SliceState,
    watcher: WatcherObservation | Mapping[str, object],
    head_sha: str | None,
    owner_id: str | None,
) -> PublicationBinding | None:
    """Recover a publication only from an ownership-verified watcher snapshot.

    Delegates to the authoritative shared validator so the active driver and
    the heartbeat cannot diverge.
    """
    validation = validate_publication_from_watcher(current, watcher, head_sha, owner_id)
    if validation.rejection is not None and watcher_presents_publication(watcher):
        rejection = validation.rejection
        LOGGER.warning(
            "[TL loop] refusing watcher publication evidence for %s: reason_code=%s expected=%s observed=%s",
            current.id,
            rejection.reason_code,
            dict(rejection.expected),
            dict(rejection.observed),
        )
    return validation.binding


def _dispatch_waiting_phase(slices: Mapping[str, SliceState]) -> TLWaiting:
    handles = {
        slice_id: ChildHandle(
            slice_id,
            slice_state.branch or "",
            slice_state.agent_type or "unknown",
        )
        for slice_id, slice_state in slices.items()
        if slice_state.status is SliceStatus.SPAWNED
    }
    return TLWaiting(handles)


def _agent_for_dispatch_intent(result: ToolResult | None, intent_id: str) -> str | None:
    """Resolve the owning agent id for a dispatch intent.

    Deliberately does not require the agent to still be alive: intent_id is
    a per-dispatch UUID persisted at spawn time (agent_dir/dispatch_intent)
    and never reused, so a matching record safely identifies the owner
    regardless of current liveness. Coding agents are one-shot by design
    (see CLAUDE.md "One-shot coding invocations") -- a dev normally exits
    right after filing its PR, well before the controller reconciles
    ownership on restart. Requiring is_alive here would make runtime_owner
    permanently unrecoverable for the common case of a dev that already
    finished its one assignment.
    """
    if result is None or result.success is False or not isinstance(result.result, Mapping):
        return None
    agents = result.result.get("agents")
    if not isinstance(agents, list):
        return None
    for raw_agent in agents:
        if not isinstance(raw_agent, Mapping):
            continue
        if raw_agent.get("intent_id") != intent_id:
            continue
        for key in ("agent_id", "id"):
            agent_id = raw_agent.get(key)
            if isinstance(agent_id, str) and agent_id:
                return agent_id
    return None


def _controller_event_run_seq(result: ToolResult | None) -> int | None:
    if result is None or result.success is False or not isinstance(result.result, Mapping):
        return None
    value = result.result.get("run_seq")
    return value if type(value) is int and value > 0 else None


def _dispatch_payload(
    slice_id: str,
    attempt: DispatchAttempt,
    boundary: str,
    *,
    error: str | None = None,
) -> dict[str, object]:
    payload: dict[str, object] = {
        "slice_id": slice_id,
        "intent_id": attempt.intent_id,
        "boundary": boundary,
        "started_at": attempt.started_at,
        "attempt": attempt.attempt,
    }
    if attempt.controller_epoch is not None:
        payload["controller_epoch"] = attempt.controller_epoch
        payload["dispatch_generation"] = attempt.dispatch_generation
    if error is not None:
        payload["error"] = error
    if attempt.harness:
        payload["harness"] = attempt.harness
    if attempt.agent_type:
        payload["agent_type"] = attempt.agent_type
    if attempt.requested_harness:
        payload["requested_harness"] = attempt.requested_harness
    if attempt.route_reconciliation_source is not None:
        payload["route_reconciliation_source"] = attempt.route_reconciliation_source
    if attempt.model:
        payload["model"] = attempt.model
    return payload


def _dispatch_retry_payload(
    slice_id: str,
    attempt: DispatchAttempt,
    reason: str,
    code: str | None,
    retry_attempt: int,
    next_attempt_at: float,
) -> dict[str, object]:
    """Build the scheduled-retry payload, keeping the code beside the prose.

    The machine code is its own dimension so a reader can classify a retry
    without parsing the operator-facing error text.
    """
    payload = _dispatch_payload(slice_id, attempt, "dispatch_retry_scheduled", error=reason)
    payload["machine_code"] = code
    payload["retry_attempt"] = retry_attempt
    payload["next_attempt_at"] = next_attempt_at
    return payload


def _spawn_route(attempt: DispatchAttempt) -> tuple[str | None, str | None]:
    """Return the protocol fields this attempt was actually dispatched with.

    Only a resolved attempt carries a route. A policy run resolves the harness
    in :func:`_prepare_spawn`; the direct no-policy run resolves the plan's
    own request once, in :func:`_resolve_direct_request`, so the plan value is
    still parsed and validated rather than forwarded unexamined.
    """
    return (attempt.agent_type or None), attempt.model


def _resolve_direct_request(request: str | None) -> DispatchAttempt | None:
    """Validate a plan request for a run with no harness policy bound.

    Without a policy there is no allowlist, capability map, or budget to bind a
    request to, so this is the *only* place such a request is accepted. It is
    parsed by the same ``parse_harness_identifier`` preflight uses, which is
    what keeps an unsupported agent type out of the spawn arguments.
    """
    if request is None:
        return None
    route = parse_harness_identifier(request)
    return DispatchAttempt.requested(route)


def _confirm_dispatch_event(
    previous_slices: Mapping[str, SliceState],
    updated_slices: Mapping[str, SliceState],
    event: EventEnvelope,
    slice_id: str | None,
    event_seq: int,
    controller_epoch: str | None = None,
) -> dict[str, SliceState]:
    if (
        not _is_spawn_confirmation_event(event)
        or slice_id is None
        or not _dispatch_confirmation_matches(
            previous_slices, event, controller_epoch=controller_epoch
        )
    ):
        return dict(updated_slices)
    current = updated_slices.get(slice_id)
    if current is None or current.dispatch_intent_id is None:
        return dict(updated_slices)
    data_agent = event.data.get("child_agent") or event.data.get("slug")
    agent_id = data_agent if isinstance(data_agent, str) and data_agent else None
    if not agent_id and isinstance(event.agent_id, str):
        agent_id = event.agent_id
    return {
        **updated_slices,
        slice_id: replace(
            slice_transition(current, SliceStatusChanged(SliceStatus.SPAWNED)),
            park_cause=None,
            dispatch_last_boundary=DISPATCH_CONFIRMED_BOUNDARY,
            dispatch_error=None,
            dispatch_agent_id=agent_id,
            dispatch_invocation_id=_event_dispatch_invocation_id(event),
            dispatch_authoritative_event_seq=event_seq,
        ),
    }


def _absorb_duplicate_spawn_confirmation(
    store: RunStore,
    state: RunState,
    event: EventEnvelope,
    correlation: DispatchCorrelation,
    phase: PhaseValue,
    source: EventQueue,
    replaying: bool,
    diagnostics: EventDiagnostics,
) -> RunState:
    """Acknowledge a second spawn row for an already-recorded dispatch.

    A refused duplicate stays in the quarantine file and re-enters replay on
    every poll, which is how a live confirmation turned into a permanent
    conflict in #1148. Recognising it here advances the cursor and drops the
    pending row, so no slice status is written and no FSM transition runs.
    """
    diagnostics.filtered += 1
    diagnostics.duplicate_confirmations += 1
    LOGGER.info(
        "Acknowledging duplicate agent.spawned for an already-confirmed dispatch "
        "slice_id=%s event_seq=%s intent_id=%s",
        correlation.slice_id,
        event.run_seq,
        _event_dispatch_intent_id(event),
    )
    _checkpoint_and_ack(store, source, event, state, phase, acknowledge=not replaying)
    if not replaying:
        diagnostics.acknowledged += 1
    _release_replayed_event(store, event, replaying)
    return store.load()


def _event_dispatch_intent_id(event: EventEnvelope) -> str | None:
    value = event.data.get("intent_id")
    if isinstance(value, str) and value:
        return value
    shadow_event = event.data.get("shadow_event")
    if isinstance(shadow_event, Mapping):
        value = shadow_event.get("intent_id")
        if isinstance(value, str) and value:
            return value
    return None


def _event_dispatch_epoch(event: EventEnvelope) -> str | None:
    value = event.data.get("controller_epoch")
    return value if isinstance(value, str) and value else None


def _event_dispatch_invocation_id(event: EventEnvelope) -> str | None:
    """Read the spawned child's invocation from either supported envelope shape."""
    values = {
        value
        for value in (event.invocation_id, event.data.get("invocation_id"))
        if isinstance(value, str) and value
    }
    return next(iter(values)) if len(values) == 1 else None


def _event_dispatch_generation(event: EventEnvelope) -> int | None:
    value = event.data.get("dispatch_generation")
    return value if type(value) is int and value >= 0 else None


def _event_slice_hint(event: EventEnvelope) -> str | None:
    value = event.data.get("slice_id") or event.slice_id
    return value if isinstance(value, str) and value else None


def _dispatch_intent_id_for(state: RunState, slice_id: str, attempt: int) -> str:
    """Derive the stable intent for one declared run generation and attempt."""
    identity = f"{state.run_id}:{slice_id}:{attempt}:{state.generation_id or ''}"
    return hashlib.sha256(identity.encode("utf-8")).hexdigest()[:32]


def _uncheckpointed_spawn_slice_hint(
    event: EventEnvelope,
    state: RunState,
    plan: WorkPlan,
) -> tuple[str | None, bool]:
    """Find one pending declared slice whose spawn row can restore its checkpoint."""
    if not _is_spawn_confirmation_event(event):
        return None, False
    declared = {task.name for task in (*plan.workers, *plan.leaves)}
    pending = {
        name: current
        for name, current in state.slices.items()
        if name in declared
        and current.status in {SliceStatus.PENDING, SliceStatus.READY}
        and current.dispatch_intent_id is None
    }
    shadow = event.data.get("shadow_event")
    shadow_slug = shadow.get("slug") if isinstance(shadow, Mapping) else None
    raw_aliases = (
        event.slice_id,
        event.data.get("slice_id"),
        event.data.get("slug"),
        shadow_slug,
    )
    aliases = {value for value in raw_aliases if isinstance(value, str) and value}
    named = aliases & pending.keys()
    if len(named) > 1:
        return None, True
    if named:
        slice_id = next(iter(named))
        return slice_id, aliases != {slice_id}
    intent_id = _event_dispatch_intent_id(event)
    if intent_id is None:
        return None, False
    matches = [
        name
        for name, current in pending.items()
        if intent_id == _dispatch_intent_id_for(state, name, current.attempts + 1)
    ]
    return (matches[0], False) if len(matches) == 1 else (None, len(matches) > 1)


def _restore_dispatch_from_confirmation(
    event: EventEnvelope,
    slice_id: str,
    state: RunState,
    config: TLLoopConfig,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> tuple[RunState, str | None, str | None]:
    """Restore a lost dispatch checkpoint only from its exact durable spawn row."""
    current = state.slices.get(slice_id)
    if (
        current is None
        or current.status not in {SliceStatus.PENDING, SliceStatus.READY}
        or current.dispatch_intent_id is not None
    ):
        return state, None, None
    event_epoch = _event_dispatch_epoch(event)
    if (
        state.controller_epoch is not None
        and event_epoch is not None
        and event_epoch != state.controller_epoch
    ):
        return state, "historical", DISPATCH_EPOCH_MISMATCH
    if not dependencies_satisfied(state.slices, slice_id):
        return state, "hold", "spawn_confirmation_precedes_declared_dependencies"
    attempt = current.attempts + 1
    expected_intent = _dispatch_intent_id_for(state, slice_id, attempt)
    intent_ids = _spawn_event_intent_ids(event)
    if intent_ids != {expected_intent}:
        return state, "hold", "spawn_confirmation_intent_mismatch"
    if not _spawn_event_generation_matches(event, attempt, state.controller_epoch):
        return state, "hold", "spawn_confirmation_generation_mismatch"
    identity, error = _spawn_event_identity(event, current, slice_id, config)
    if error is not None or identity is None:
        return state, "hold", error or "spawn_confirmation_identity_incomplete"
    start_time = _spawn_event_timestamp(event)
    if start_time is None:
        return state, "hold", "spawn_confirmation_timestamp_malformed"
    owner_id, invocation_id, branch, agent_type, model, resolved_harness = identity
    choice, choice_error = _recovered_spawn_choice(
        current,
        state,
        config,
        agent_type,
        model,
        resolved_harness,
    )
    if choice_error is not None:
        return state, "hold", choice_error
    journal_error = _reconcile_spawn_journal_from_confirmation(
        effects_log,
        slice_id,
        expected_intent,
        owner_id,
        invocation_id,
        branch,
    )
    if journal_error is not None:
        return state, "hold", journal_error
    audit_error = _audit_dispatch_checkpoint_restoration(event, store)
    if audit_error is not None:
        return state, "hold", audit_error
    try:
        restored_state = _persist_restored_dispatch(
            state,
            current,
            slice_id,
            attempt,
            expected_intent,
            start_time,
            branch,
            agent_type,
            model,
            resolved_harness,
            choice,
            store,
        )
    except (OSError, ValueError, TimeoutError) as error:
        return state, "hold", f"spawn_checkpoint_restore_failed:{type(error).__name__}"
    return restored_state, "restored", None


def _recovered_spawn_choice(
    current: SliceState,
    state: RunState,
    config: TLLoopConfig,
    agent_type: str,
    model: str | None,
    resolved_harness: str,
) -> tuple[HarnessChoice | None, str | None]:
    """Recompute the charge from the active policy and compare its route evidence."""
    if config.policy is None:
        return None, None
    try:
        capabilities = config.capabilities or load_capability()
        choice = select_agent_type(
            current,
            config.role,
            state.budgets,
            config.policy,
            capabilities,
            config.learned_policy,
            requested_harness=(
                None
                if current.dispatch_uses_current_role_configuration
                else current.requested_harness
            ),
        )
    except (OSError, ValueError):
        return None, "spawn_confirmation_policy_or_capability_unavailable"
    if choice is None:
        return None, "spawn_confirmation_policy_no_longer_selects_a_harness"
    route = parse_harness_identifier(choice.harness)
    try:
        expected_model = _selected_spawn_model(choice, route, config)
    except (OSError, ValueError):
        return None, "spawn_confirmation_model_catalog_unavailable"
    if (
        choice.harness != resolved_harness
        or route.agent_type != agent_type
        or expected_model != model
    ):
        return None, "spawn_confirmation_route_differs_from_current_policy"
    return choice, None


def _selected_spawn_model(
    choice: HarnessChoice,
    route: HarnessRoute,
    config: TLLoopConfig,
) -> str | None:
    if config.catalog is None:
        return route.model
    if config.requested_model:
        return select_model(choice.harness, config.catalog, config.requested_model).model_id
    return select_model_for_difficulty(
        choice.harness,
        config.catalog,
        choice.difficulty,
        escalated=choice.reason == "escalated_after_no_go",
    ).model_id


def _audit_dispatch_checkpoint_restoration(event: EventEnvelope, store: RunStore) -> str | None:
    try:
        store.append_audit_event(
            {
                **envelope_document(event),
                "correlation": "dispatch_checkpoint_restored",
                "correlation_reason": "exact current-plan spawn intent restored a missing checkpoint",
            }
        )
    except QuarantineStorageError:
        return "spawn_confirmation_audit_conflict"
    return None


def _persist_restored_dispatch(
    state: RunState,
    current: SliceState,
    slice_id: str,
    attempt: int,
    intent_id: str,
    started_at: float,
    branch: str,
    agent_type: str,
    model: str | None,
    resolved_harness: str,
    choice: HarnessChoice | None,
    store: RunStore,
) -> RunState:
    def update(document: dict[str, object]) -> dict[str, object]:
        return _record_restored_dispatch_document(
            document,
            slice_id,
            attempt,
            intent_id,
            started_at,
            branch,
            agent_type,
            model,
            resolved_harness,
            RECOVERED_DISPATCH_LEDGER_FLOOR,
            state.controller_epoch,
        )

    if choice is not None and not _spawn_charge_already_recorded(state, current, choice):
        apply_spawn_and_charge(store.run_dir, choice, current, update)
        return store.load()
    dispatching = slice_transition(current, SliceStatusChanged(SliceStatus.DISPATCHING))
    restored = replace(
        dispatching,
        attempts=attempt,
        agent_type=agent_type,
        model=model,
        resolved_harness=resolved_harness,
        branch=branch,
        dispatch_intent_id=intent_id,
        dispatch_started_at=started_at,
        dispatch_last_boundary="dispatch_intended",
        dispatch_error=None,
        dispatch_error_code=None,
        dispatch_ledger_floor=RECOVERED_DISPATCH_LEDGER_FLOOR,
        dispatch_generation=attempt if state.controller_epoch is not None else 0,
        dispatch_next_attempt_at=None,
        dispatch_retry_for_attempt=0,
        dispatch_agent_id=None,
        dispatch_invocation_id=None,
        dispatch_authoritative_event_seq=None,
        park_cause=None,
    )
    return store.checkpoint(
        state.fsm,
        {**state.slices, slice_id: restored},
        state.budgets,
        state.events.last_consumed_offset,
    )


def _record_restored_dispatch_document(
    document: dict[str, object],
    slice_id: str,
    attempt: int,
    intent_id: str,
    started_at: float,
    branch: str,
    agent_type: str,
    model: str | None,
    resolved_harness: str,
    ledger_floor: int,
    controller_epoch: str | None,
) -> dict[str, object]:
    slices = document.get("slices")
    if not isinstance(slices, dict) or not isinstance(slices.get(slice_id), dict):
        raise TypeError("restored dispatch slice is missing from checkpoint")
    slices[slice_id].update(
        {
            "status": SliceStatus.DISPATCHING.value,
            "attempts": attempt,
            "agent_type": agent_type,
            "model": model,
            "resolved_harness": resolved_harness,
            "branch": branch,
            "dispatch_intent_id": intent_id,
            "dispatch_started_at": started_at,
            "dispatch_last_boundary": "dispatch_intended",
            "dispatch_error": None,
            "dispatch_error_code": None,
            "dispatch_ledger_floor": ledger_floor,
            "dispatch_generation": attempt if controller_epoch is not None else 0,
            "dispatch_next_attempt_at": None,
            "dispatch_retry_for_attempt": 0,
            "dispatch_agent_id": None,
            "dispatch_invocation_id": None,
            "dispatch_authoritative_event_seq": None,
            "park_cause": None,
        }
    )
    return document


def _spawn_charge_already_recorded(
    state: RunState,
    current: SliceState,
    choice: HarnessChoice,
) -> bool:
    charges = [
        charge
        for charge in state.budgets.charges
        if charge.slice_id == current.id and charge.attempt == current.attempts + 1
    ]
    if not charges:
        return False
    if len(charges) != 1:
        raise ValueError("multiple budget charges match restored dispatch")
    charge = charges[0]
    if charge.harness != choice.harness or charge.estimated_tokens != choice.estimated_cost:
        raise ValueError("budget charge disagrees with restored dispatch route")
    return True


def _spawn_event_intent_ids(event: EventEnvelope) -> set[str]:
    values: set[str] = set()
    direct = event.data.get("intent_id")
    if isinstance(direct, str) and direct:
        values.add(direct)
    shadow = event.data.get("shadow_event")
    nested = shadow.get("intent_id") if isinstance(shadow, Mapping) else None
    if isinstance(nested, str) and nested:
        values.add(nested)
    return values


def _spawn_event_generation_matches(
    event: EventEnvelope,
    attempt: int,
    controller_epoch: str | None,
) -> bool:
    reported_attempt = event.data.get("attempt")
    if reported_attempt is not None and (
        type(reported_attempt) is not int or reported_attempt != attempt
    ):
        return False
    reported_generation = _event_dispatch_generation(event)
    expected_generation = attempt if controller_epoch is not None else 0
    return reported_generation is None or reported_generation == expected_generation


def _spawn_event_identity(
    event: EventEnvelope,
    current: SliceState,
    slice_id: str,
    config: TLLoopConfig,
) -> tuple[tuple[str, str, str, str, str | None, str] | None, str | None]:
    """Validate owner, invocation, route and branch against one declared slice."""
    shadow = event.data.get("shadow_event")
    shadow_data = shadow if isinstance(shadow, Mapping) else {}
    owner = event.data.get("child_agent")
    if not isinstance(owner, str) or not owner:
        owner = event.agent_id if event.kind is EventKind.AGENT_NOTIFY_PARENT else None
    if event.kind is EventKind.AGENT_NOTIFY_PARENT and event.agent_id != owner:
        return None, "spawn_confirmation_owner_alias_mismatch"
    invocation_id = _event_dispatch_invocation_id(event)
    if invocation_id is None:
        return None, "spawn_confirmation_invocation_missing_or_conflicting"
    branch = event.data.get("branch") or shadow_data.get("branch")
    expected_branch = current.branch or derive_child_branch(config.branch, slice_id)
    if not isinstance(branch, str) or branch != expected_branch:
        return None, "spawn_confirmation_branch_mismatch"
    raw_agent_type = event.data.get("agent_type") or shadow_data.get("agent_type")
    if not isinstance(raw_agent_type, str) or not raw_agent_type:
        return None, "spawn_confirmation_agent_type_missing"
    model_value = event.data.get("model")
    model = model_value if isinstance(model_value, str) and model_value else None
    if "/" in raw_agent_type:
        try:
            route = parse_harness_identifier(raw_agent_type)
        except ValueError:
            return None, "spawn_confirmation_agent_type_malformed"
        agent_type = route.agent_type
        model = route.model
        resolved_harness = raw_agent_type
    else:
        agent_type = raw_agent_type
        resolved_harness = f"{agent_type}/{model}" if model else agent_type
    if not owner:
        return None, "spawn_confirmation_owner_missing"
    return (owner, invocation_id, branch, agent_type, model, resolved_harness), None


def _spawn_event_timestamp(event: EventEnvelope) -> float | None:
    try:
        observed = datetime.fromisoformat(event.observed_at)
    except ValueError:
        return None
    if observed.tzinfo is None or observed.utcoffset() is None:
        return None
    return observed.timestamp()


def _reconcile_spawn_journal_from_confirmation(
    effects_log: list[EffectIntent],
    slice_id: str,
    intent_id: str,
    owner_id: str,
    invocation_id: str,
    branch: str,
) -> str | None:
    if not isinstance(effects_log, EffectJournal):
        return None
    expected_operation = (
        "spawn_worker"
        if any(
            entry.get("operation") == "spawn_worker" and entry.get("target") == slice_id
            for entry in effects_log.snapshot()
        )
        else "spawn_leaf"
    )
    for entry in effects_log.snapshot():
        if entry.get("operation") != expected_operation or entry.get("target") != slice_id:
            continue
        arguments = entry.get("arguments")
        if not isinstance(arguments, Mapping) or arguments.get("intent_id") != intent_id:
            continue
        if entry.get("status") == "rejected":
            return "spawn_confirmation_conflicts_with_rejected_action_result"
        if entry.get("status") == "confirmed" and not _spawn_journal_result_matches(
            entry, owner_id, invocation_id, branch
        ):
            return "spawn_confirmation_conflicts_with_confirmed_action_result"
        key = entry.get("key")
        if entry.get("status") in {"intended", "unknown"} and isinstance(key, str):
            effects_log.resolve_by_key(
                key,
                status="confirmed",
                result={
                    "success": True,
                    "result": {
                        "agent_id": owner_id,
                        "invocation_id": invocation_id,
                        "branch": branch,
                        "reconciled_from_spawn_event": True,
                    },
                },
            )
    return None


def _spawn_journal_result_matches(
    entry: Mapping[str, object],
    owner_id: str,
    invocation_id: str,
    branch: str,
) -> bool:
    result = entry.get("result")
    if not isinstance(result, Mapping):
        return False
    if result.get("success") is not True:
        return False
    payload = result.get("result")
    if not isinstance(payload, Mapping):
        return True
    expected = {
        "agent_id": owner_id,
        "invocation_id": invocation_id,
        "branch": branch,
    }
    return all(payload.get(key, value) == value for key, value in expected.items())


def _record_dispatch_correlation_failure(
    store: RunStore,
    state: RunState,
    event: EventEnvelope,
    correlation: DispatchCorrelation,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    """Retain rejected observations and emit one deduplicated integrity fact."""
    run_seq = event.run_seq
    prior = store.quarantined_events()
    if run_seq is not None and any(item.get("run_seq") == run_seq for item in prior):
        return
    document = dict(envelope_document(event))
    document["correlation"] = correlation.classification
    document["correlation_reason"] = correlation.reason
    store.quarantine_event(document)
    payload = {
        "slice_id": correlation.slice_id,
        "intent_id": _event_dispatch_intent_id(event),
        "attempt": event.data.get("attempt"),
        "controller_epoch": _event_dispatch_epoch(event),
        "dispatch_generation": _event_dispatch_generation(event),
        "classification": correlation.classification,
        "reason": correlation.reason,
        "event_run_seq": event.run_seq,
    }
    _record_controller_event(
        correlation.slice_id or state.run_id,
        "tl.dispatch_event_rejected",
        payload,
        config,
        effects,
        effects_log,
    )


def correlate_dispatch_event(state: RunState, event: EventEnvelope) -> DispatchCorrelation:
    """Correlate a spawn observation using the current controller epoch.

    Events from an earlier controller epoch remain queryable for audit but
    can never confirm a current dispatch or charge a new owner. A matching
    epoch with a stale generation is an integrity conflict, not evidence of
    a new worker.

    One dispatch emits more than one spawn row for the same intent: the
    controller records its own confirmation from the accepted spawn, and the
    server separately writes the child registration (``child_agent``) and the
    dispatch record (``slug``/``task_summary``) under the *parent's*
    ``agent_id``. So the second row for a live intent arrives after the slice
    has left the dispatching statuses and is a duplicate, not a conflict. It
    is classified as ``already_confirmed`` so the loop can acknowledge it
    without an FSM transition. Every other mismatch -- an intent no slice
    records, an ambiguous intent, a stale epoch, or a stale dispatch
    generation -- still refuses exactly as before.
    """
    if not _is_spawn_confirmation_event(event):
        return DispatchCorrelation(DISPATCH_CORRELATED)
    intent_id = _event_dispatch_intent_id(event)
    matches = [
        slice_state
        for slice_state in state.slices.values()
        if intent_id is not None
        and slice_state.dispatch_intent_id == intent_id
        and slice_state.status in DISPATCHING_STATUSES
    ]
    candidate = matches[0] if len(matches) == 1 else None
    event_epoch = _event_dispatch_epoch(event)
    if candidate is not None:
        if event_epoch is not None and event_epoch != state.controller_epoch:
            return DispatchCorrelation(
                DISPATCH_HISTORICAL_AUDIT,
                candidate.id,
                DISPATCH_EPOCH_MISMATCH,
            )
        event_generation = _event_dispatch_generation(event)
        if event_generation is not None and event_generation != candidate.dispatch_generation:
            return DispatchCorrelation(
                DISPATCH_INTEGRITY_CONFLICT,
                candidate.id,
                "dispatch_generation_mismatch",
            )
        return DispatchCorrelation(DISPATCH_CORRELATED, candidate.id)
    duplicate = _correlate_duplicate_confirmation(state, event, intent_id, event_epoch)
    if duplicate is not None:
        return duplicate
    hint = _event_slice_hint(event)
    current = state.slices.get(hint) if hint is not None else None
    if current is not None and event_epoch is not None and event_epoch != state.controller_epoch:
        return DispatchCorrelation(
            DISPATCH_HISTORICAL_AUDIT,
            current.id,
            DISPATCH_EPOCH_MISMATCH,
        )
    return DispatchCorrelation(DISPATCH_INTEGRITY_CONFLICT, hint, "intent_mismatch")


def _correlate_duplicate_confirmation(
    state: RunState,
    event: EventEnvelope,
    intent_id: str | None,
    event_epoch: str | None,
) -> DispatchCorrelation | None:
    """Classify a second spawn row for an intent this run already confirmed.

    A duplicate is proven, not inferred: the intent must name exactly one slice,
    that slice must have left the dispatching statuses, it must already carry
    the authoritative sequence of a recorded confirmation, and every child
    identity the row names must be one the owner already recorded. An intent
    that no slice records, that several slices claim, or that arrives naming
    somebody else's child proves nothing and is left to the caller's refusal
    path.

    The epoch and dispatch generation are still checked against the owner, so a
    duplicate row that names an earlier attempt or an earlier controller is
    refused with the same reason a first confirmation would be.
    """
    if intent_id is None:
        return None
    owners = [
        slice_state
        for slice_state in state.slices.values()
        if slice_state.dispatch_intent_id == intent_id
    ]
    if len(owners) != 1:
        return None
    owner = owners[0]
    if owner.status in DISPATCHING_STATUSES:
        return None
    if owner.dispatch_authoritative_event_seq is None:
        return None
    if not _named_child_matches_owner(event, owner):
        return DispatchCorrelation(
            DISPATCH_INTEGRITY_CONFLICT,
            owner.id,
            "dispatch_agent_mismatch",
        )
    if event_epoch is not None and event_epoch != state.controller_epoch:
        return DispatchCorrelation(
            DISPATCH_HISTORICAL_AUDIT,
            owner.id,
            DISPATCH_EPOCH_MISMATCH,
        )
    event_generation = _event_dispatch_generation(event)
    if event_generation is not None and event_generation != owner.dispatch_generation:
        return DispatchCorrelation(
            DISPATCH_INTEGRITY_CONFLICT,
            owner.id,
            "dispatch_generation_mismatch",
        )
    return DispatchCorrelation(
        DISPATCH_ALREADY_CONFIRMED,
        owner.id,
        "dispatch_already_confirmed",
    )


def _named_child_matches_owner(event: EventEnvelope, owner: SliceState) -> bool:
    """Require every child identity the row names to be the owner's.

    The two spawn rows for one dispatch differ in shape: the child
    registration carries ``child_agent`` (the runtime agent id the server
    minted) and the dispatch record carries ``slug`` (the slice id). Both name
    the same owner, so each is accepted only when it equals the slice id or the
    ``dispatch_agent_id`` that owner already persisted. A row that names some
    other child is not a duplicate of this dispatch, however well its intent
    matches, so an intent alone can never authorise a foreign confirmation.
    """
    permitted = {owner.id, owner.dispatch_agent_id}
    for key in ("child_agent", "slug", "agent_id", "dispatch_agent_id"):
        value = event.data.get(key)
        if isinstance(value, str) and value and value not in permitted:
            return False
    return True


def _dispatch_confirmation_matches(
    slices: Mapping[str, SliceState],
    event: EventEnvelope,
    *,
    controller_epoch: str | None = None,
) -> bool:
    """Whether a spawn row may confirm this controller's dispatch."""
    return _spawn_confirmation_refusal(slices, event, controller_epoch=controller_epoch) is None


def _spawn_confirmation_refusal(
    slices: Mapping[str, SliceState],
    event: EventEnvelope,
    *,
    controller_epoch: str | None = None,
) -> str | None:
    """Why a spawn row cannot confirm this controller's dispatch, or None.

    The reason matters, not just the verdict: a row confirmed under a
    predecessor controller epoch is historical evidence about an earlier
    generation, while a row naming no owned intent is an integrity conflict
    about this one. The caller keeps the two apart, and only the historical
    refusal is retained.
    """
    if not _is_spawn_confirmation_event(event):
        return None
    intent_id = _event_dispatch_intent_id(event)
    if intent_id is None:
        return "dispatch intent is missing"
    matches = [
        slice_state
        for slice_state in slices.values()
        if slice_state.dispatch_intent_id == intent_id
        and slice_state.status in DISPATCHING_STATUSES
    ]
    if len(matches) != 1:
        return "dispatch intent names no single dispatching slice"
    event_epoch = _event_dispatch_epoch(event)
    if controller_epoch is not None and event_epoch is not None and event_epoch != controller_epoch:
        return DISPATCH_EPOCH_MISMATCH
    generation = _event_dispatch_generation(event)
    if generation is not None and generation != matches[0].dispatch_generation:
        return "dispatch_generation_mismatch"
    return None


def _emit_dispatch_confirmation(
    before: Mapping[str, SliceState],
    after: Mapping[str, SliceState],
    event: EventEnvelope,
    slice_id: str | None,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    controller_epoch: str | None = None,
) -> None:
    if not _is_spawn_confirmation_event(event) or slice_id is None:
        return
    previous = before.get(slice_id)
    current = after.get(slice_id)
    if (
        previous is None
        or current is None
        or previous.dispatch_intent_id is None
        or previous.dispatch_started_at is None
        or current.dispatch_authoritative_event_seq is None
        or previous.dispatch_authoritative_event_seq == current.dispatch_authoritative_event_seq
    ):
        return
    attempt = DispatchAttempt.recorded_for(previous, controller_epoch)
    _record_controller_event(
        slice_id,
        "tl.dispatch_confirmed",
        _dispatch_payload(slice_id, attempt, "agent.spawned"),
        config,
        effects,
        effects_log,
    )


def _is_spawn_confirmation_event(event: EventEnvelope) -> bool:
    if event.kind is EventKind.AGENT_SPAWNED:
        return True
    shadow_event = event.data.get("shadow_event")
    return isinstance(shadow_event, Mapping) and shadow_event.get("kind") == "child_spawned"


def _spawn_agent_id(result: ToolResult | None) -> str | None:
    if result is None or not isinstance(result.result, Mapping):
        return None
    for key in ("agent_id", "id", "child_agent"):
        value = result.result.get(key)
        if isinstance(value, str) and value:
            return value
    return None


def _spawn_invocation_id(result: ToolResult | None) -> str | None:
    if result is None or not isinstance(result.result, Mapping):
        return None
    value = result.result.get("invocation_id")
    if isinstance(value, str) and value:
        return value
    nested = result.result.get("invocation")
    if isinstance(nested, Mapping):
        value = nested.get("invocation_id")
        if isinstance(value, str) and value:
            return value
    return None


def _dispatch_candidate(name: str, state: RunState, config: TLLoopConfig) -> bool:
    """Whether this slice's next dispatch effect may be issued now.

    A due retry boundary is a fresh dispatch of a slice that already holds a
    scheduling slot, so it is not re-gated by the pending-slice width ceiling.
    A boundary whose scheduled instant has not arrived is not a candidate at
    all: the backoff is a durable boundary, never an in-memory sleep.
    """
    current = state.slices.get(name)
    if current is not None and _retry_boundary_due(current, config):
        return True
    if _already_dispatched(name, state):
        return False
    return _can_dispatch(name, state, config)


def _retry_boundary_due(current: SliceState, config: TLLoopConfig) -> bool:
    """Whether one persisted retry boundary has reached its scheduled instant.

    A boundary without a scheduled instant is never due: the controller fails
    closed rather than re-driving a dispatch it cannot date.
    """
    if current.status not in REDRIVEN_DISPATCH_STATUSES:
        return False
    scheduled = current.dispatch_next_attempt_at
    if scheduled is None:
        return False
    return scheduled <= _wall_clock(config)


def _held_by_dispatch_park(state: RunState) -> bool:
    """Whether the run's failure is an unanswered per-slice dispatch gate.

    The hold is read from the durable parks and gates rather than from the
    phase alone, because a failed phase cannot say *which* slice the operator
    still owes an answer. A slice parked on its own dispatch failure whose own
    named gate is still pending is exactly the state a held run waits on, and
    it is what makes "one refusal, one question" true for a whole run.
    """
    return any(
        slice_state.status is SliceStatus.DISPATCH_FAILED
        and slice_state.park_cause is ParkCause.DISPATCH_FAILED
        and any(
            gate.name
            == _dispatch_failure_gate_name(slice_state.id, slice_state.dispatch_error_code)
            and gate.status is GateStatus.PENDING
            for gate in state.gates
        )
        for slice_state in state.slices.values()
    )


def _dispatch_pass_stops(state: RunState) -> bool:
    """Whether a failed phase ends the whole dispatch pass instead of one slice.

    One slice exhausting its dispatch retries is scoped to that slice: it
    parks, it opens its own gate, and the run *holds* behind the operator's
    answer rather than stopping. Holding must not starve the siblings the
    refusal says nothing about, so the pass keeps dispatching them and each
    exhausted sibling opens its own gate. A failed phase that no open dispatch
    park explains is an unrelated failure and still stops the pass at once.
    """
    if state.fsm.phase is not TLPhase.TLFailed:
        return False
    return not _held_by_dispatch_park(state)


def _dispatch_children(
    plan: WorkPlan,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    live = cast(EffectClient, effects) if config.active else None
    state = _block_unsatisfiable_dependents(state, config, effects, effects_log, store)
    before_slices = state.slices
    for worker in plan.workers:
        if not _dispatch_candidate(worker.name, state, config):
            continue
        attempt = _prepare_spawn(worker.name, state, config, effects, store, effects_log)
        state = store.load()
        _record_spawn_request(worker.name, attempt, config, effects, effects_log)
        runtime_name = config.dispatch_names.get(worker.name, worker.name)
        worker_args: dict[str, object] = {"name": runtime_name, "task": worker.task}
        # The resolved route is authoritative. A plan request reaches the wire
        # only because the selector honored it, so a slice can never be
        # dispatched with an unvalidated plan value when policy resolved a
        # different harness.
        agent_type, model = _spawn_route(attempt)
        _optional_argument(worker_args, "agent_type", agent_type)
        _optional_argument(worker_args, "model", model)
        try:
            result = _invoke(
                "spawn_worker",
                worker.name,
                worker_args,
                config.active,
                live,
                _worker_call(worker, agent_type, model, attempt.intent_id, runtime_name),
                effects_log,
                raise_on_failure=False,
            )
        except Exception as error:  # noqa: BLE001 - persist the boundary failure
            return _record_dispatch_failure(
                store,
                state,
                worker.name,
                attempt,
                str(error),
                config,
                effects,
                effects_log,
                code=_dispatch_failure_code(store, config, attempt),
            )
        state = _record_dispatch_result(
            store, state, worker.name, attempt, result, config, effects, effects_log
        )
        if _dispatch_pass_stops(state):
            return state
    for leaf in plan.leaves:
        if not _dispatch_candidate(leaf.name, state, config):
            continue
        attempt = _prepare_spawn(leaf.name, state, config, effects, store, effects_log)
        state = store.load()
        _record_spawn_request(leaf.name, attempt, config, effects, effects_log)
        runtime_name = config.dispatch_names.get(leaf.name, leaf.name)
        leaf_args: dict[str, object] = {"name": runtime_name, "task": leaf.task}
        _optional_argument(leaf_args, "intent_id", attempt.intent_id)
        agent_type, model = _spawn_route(attempt)
        _optional_argument(leaf_args, "agent_type", agent_type)
        _optional_argument(leaf_args, "model", model)
        for name, value in (
            ("boundary", leaf.boundary),
            ("read_first", leaf.read_first),
            ("steps", leaf.steps),
            ("verify", leaf.verify),
        ):
            if value:
                leaf_args[name] = list(value)
        _optional_argument(leaf_args, "context", leaf.context)
        try:
            result = _invoke(
                "spawn_leaf",
                leaf.name,
                leaf_args,
                config.active,
                live,
                _leaf_call(leaf, agent_type, model, attempt.intent_id, runtime_name),
                effects_log,
                raise_on_failure=False,
            )
        except Exception as error:  # noqa: BLE001 - persist the boundary failure
            return _record_dispatch_failure(
                store,
                state,
                leaf.name,
                attempt,
                str(error),
                config,
                effects,
                effects_log,
                code=_dispatch_failure_code(store, config, attempt),
            )
        state = _record_dispatch_result(
            store, state, leaf.name, attempt, result, config, effects, effects_log
        )
        if _dispatch_pass_stops(state):
            return state
    updated = store.load() if config.policy is not None else state
    _emit_slice_status_changes(
        before_slices,
        updated.slices,
        config,
        effects,
        effects_log,
    )
    return updated


def _block_unsatisfiable_dependents(
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    """Record a durable block for every leaf whose prerequisite can never merge.

    Without this the dependent would sit pending behind a prerequisite that no
    longer exists as an outcome, and the run would wait on an operator question
    that has no answer. Blocking before the dispatch pass means the pass never
    considers the slice, and the status change is durable across a restart
    because it lands in the same checkpoint as every other slice transition.
    """
    blocked = withhold_unsatisfiable_dependents(state.slices)
    changed = {
        slice_id: current
        for slice_id, current in blocked.items()
        if current != state.slices.get(slice_id)
    }
    if not changed:
        return state
    updated = store.checkpoint(
        _phase_from_state(state),
        blocked,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=state.integration,
    )
    for slice_id in sorted(changed):
        _record_controller_event(
            slice_id,
            "tl.dependency_blocked",
            {
                "slice_id": slice_id,
                "depends_on": list(changed[slice_id].depends_on),
                "blocked_by": changed[slice_id].blocked_by,
                "reason": "a declared dependency can no longer merge",
            },
            config,
            effects,
            effects_log,
        )
    _emit_slice_status_changes(state.slices, changed, config, effects, effects_log)
    return updated


def _child_recovery_projection(
    child_state: RunState | None,
    parent_run_id: str,
) -> tuple[SubTLLifecycle, ChildRecoverySummary] | None:
    """Project one child's authoritative recovery to its nearest parent."""
    if child_state is None:
        return None
    slices = getattr(child_state, "slices", {})
    if not isinstance(slices, Mapping):
        return None
    for slice_id, slice_state in slices.items():
        recovery = slice_state.recovery
        if recovery is None:
            continue
        cause = BlockCause(recovery.cause)
        lifecycle = (
            SubTLLifecycle.HUMAN_GATE
            if recovery.phase is RecoveryPhase.HUMAN_GATE
            else SubTLLifecycle.RECOVERING
        )
        owner_run_id = getattr(child_state, "run_id", parent_run_id)
        child_path = tuple(
            item
            for item in (parent_run_id, owner_run_id, slice_id)
            if isinstance(item, str) and item
        )
        return lifecycle, ChildRecoverySummary(
            owner_run_id=owner_run_id,
            child_path=child_path,
            slice_id=slice_id,
            cause=cause,
            recovery_round=recovery.recovery_round,
            next_probe_at=recovery.next_probe_at,
        )
    integration = getattr(child_state, "integration", None)
    nested_recoveries = getattr(integration, "sub_tl_recovery", {})
    if isinstance(nested_recoveries, Mapping):
        nested_states = getattr(integration, "sub_tl_states", {})
        for child_name, summary in nested_recoveries.items():
            if not isinstance(summary, ChildRecoverySummary):
                continue
            lifecycle = (
                nested_states.get(child_name, SubTLLifecycle.RECOVERING)
                if isinstance(nested_states, Mapping)
                else SubTLLifecycle.RECOVERING
            )
            if not isinstance(lifecycle, SubTLLifecycle):
                lifecycle = SubTLLifecycle.RECOVERING
            path = summary.child_path
            if not path or path[0] != parent_run_id:
                path = (parent_run_id, *path)
            return lifecycle, replace(summary, child_path=path)
    return None


def _scope_handoff_identity(
    task: SubTLTask,
    state: RunState,
    config: TLLoopConfig,
    store: RunStore,
    effects: EffectClient,
) -> tuple[dict[str, object], str] | str:
    """Resolve one parent and child only through the accepted manifest."""
    manifest = state.plan_manifest
    if manifest is None or not manifest.scope_id:
        return "accepted parent manifest is unavailable for the child handoff"
    declarations = [
        node for node in manifest.nodes if node.kind == "sub_tl" and node.name == task.name
    ]
    if len(declarations) != 1:
        return f"accepted parent manifest does not uniquely declare subTL {task.name!r}"
    if state.owner_branch is not None and state.owner_branch != config.branch:
        return "controller branch differs from its persisted owner branch"
    node = declarations[0]
    coordinates = {
        "controller_id": effects.name,
        "parent_run_id": store.run_id,
        "parent_scope_id": manifest.scope_id,
        "child_scope_id": node.node_id,
        "expected_branch": config.branch,
    }
    stable = json.dumps(
        {**coordinates, "manifest_digest": manifest.digest or ""},
        sort_keys=True,
        separators=(",", ":"),
    )
    handoff_id = hashlib.sha256(stable.encode("utf-8")).hexdigest()
    return coordinates, handoff_id


def _scope_handoff_response_error(
    result: ToolResult | None,
    expected: Mapping[str, object],
    *,
    expected_head: str | None = None,
    expected_fingerprint: str | None = None,
) -> str | None:
    """Reject incomplete or inconsistent inspect/apply receipts before dispatch."""
    if result is None or result.success is not True or not isinstance(result.result, Mapping):
        return "scope handoff tool returned no structured result"
    payload = result.result
    if payload.get("success") is not True or payload.get("ready") is not True:
        return _safe_scope_handoff_error(payload.get("error"), payload.get("outcome"))
    for key, value in expected.items():
        response_key = "branch" if key == "expected_branch" else key
        if payload.get(response_key) != value:
            return f"scope handoff receipt has conflicting {key}"
    if not _is_git_object_id(payload.get("head_before")):
        return "scope handoff receipt is missing a valid source HEAD"
    if not _is_sha256_text(payload.get("source_fingerprint")):
        return "scope handoff receipt is missing its source fingerprint"
    committed_paths = _scope_handoff_paths(payload.get("committed_paths"))
    remaining_paths = _scope_handoff_paths(payload.get("remaining_dirty_paths"))
    if committed_paths is None or remaining_paths is None:
        return "scope handoff receipt has missing or malformed path evidence"
    if payload.get("changed_paths") != remaining_paths:
        return "scope handoff changed_paths alias conflicts with remaining_dirty_paths"
    outcome = payload.get("outcome")
    if outcome == "no_changes":
        if payload.get("head_after") != payload.get("head_before"):
            return "no-op scope handoff receipt changed source HEAD"
        if payload.get("commit_sha") != "":
            return "no-op scope handoff receipt reports a commit"
        if committed_paths or remaining_paths:
            return "no-op scope handoff receipt contains path changes"
    if expected_head is not None and payload.get("head_before") != expected_head:
        return "scope handoff source HEAD changed between inspection and apply"
    if (
        expected_fingerprint is not None
        and payload.get("source_fingerprint") != expected_fingerprint
    ):
        return "scope handoff source fingerprint changed between inspection and apply"
    if expected_head is None and payload.get("head_after") != payload.get("head_before"):
        return "read-only scope handoff inspection reported a changed HEAD"
    if expected_head is not None and not _is_git_object_id(payload.get("head_after")):
        return "scope handoff apply receipt is missing its resulting HEAD"
    if expected_head is None:
        if committed_paths:
            return "read-only scope handoff inspection reported committed paths"
        if outcome not in {"ready", "no_changes"}:
            return "scope handoff inspection has an unsupported outcome"
    elif outcome in {"committed", "recovered_commit"}:
        if not committed_paths or remaining_paths:
            return "successful scope handoff receipt has incomplete committed or remaining paths"
        if payload.get("commit_sha") != payload.get("head_after"):
            return "successful scope handoff receipt has conflicting commit and resulting HEAD"
    elif outcome != "no_changes":
        return "scope handoff apply receipt has an unsupported success outcome"
    if not isinstance(payload.get("source_worktree"), str) or not payload["source_worktree"]:
        return "scope handoff receipt is missing its authenticated source worktree"
    return None


def _scope_handoff_paths(value: object) -> list[str] | None:
    """Validate the canonical sorted hexadecimal path-list wire format."""
    if not isinstance(value, list) or any(not isinstance(path, str) for path in value):
        return None
    paths = cast(list[str], value)
    if any(
        not path
        or len(path) % 2 != 0
        or any(character not in "0123456789abcdef" for character in path)
        for path in paths
    ):
        return None
    if paths != sorted(set(paths)):
        return None
    return paths


def _safe_scope_handoff_error(error: object, outcome: object) -> str:
    """Return a bounded operator diagnostic without raw tool output."""
    code = outcome if isinstance(outcome, str) and outcome else "unknown"
    detail = error if isinstance(error, str) and error else "operation did not become ready"
    safe = "".join(max(character, " ") for character in detail)[:320]
    return f"scope handoff outcome {code}: {safe}"


def _is_git_object_id(value: object) -> bool:
    return (
        isinstance(value, str)
        and len(value) in {40, 64}
        and all(character in "0123456789abcdefABCDEF" for character in value)
    )


def _is_sha256_text(value: object) -> bool:
    return (
        isinstance(value, str)
        and len(value) == 64
        and all(character in "0123456789abcdefABCDEF" for character in value)
    )


def _scope_handoff_action_target(
    effects_log: list[EffectIntent],
    handoff_id: str,
    head: str,
    fingerprint: str,
) -> str:
    """Reuse readiness evidence and retain each known failed apply attempt."""
    matching = []
    if isinstance(effects_log, EffectJournal):
        for entry in effects_log.snapshot():
            arguments = entry.get("arguments")
            if (
                entry.get("operation") == "prepare_scope_handoff"
                and isinstance(arguments, Mapping)
                and arguments.get("handoff_id") == handoff_id
                and arguments.get("expected_head_sha") == head
                and arguments.get("expected_source_fingerprint") == fingerprint
            ):
                matching.append(entry)
    snapshot_key = hashlib.sha256(f"{head}\0{fingerprint}".encode("ascii")).hexdigest()[:16]
    prefix = f"{handoff_id}:{snapshot_key}"
    if matching and _scope_handoff_entry_ready(matching[-1]):
        target = matching[-1].get("target")
        if isinstance(target, str) and target:
            return target
    return f"{prefix}:attempt:{len(matching)}"


def _scope_handoff_entry_ready(entry: Mapping[str, object]) -> bool:
    """Reuse only a confirmed apply receipt with valid path and identity evidence."""
    arguments = entry.get("arguments")
    result = entry.get("result")
    payload = result.get("result") if isinstance(result, Mapping) else None
    if (
        not isinstance(arguments, Mapping)
        or arguments.get("apply") is not True
        or entry.get("status") != "confirmed"
        or not isinstance(result, dict)
        or not isinstance(payload, Mapping)
    ):
        return False
    try:
        decoded = ToolResult.from_raw(cast(JsonObject, result))
    except (DecodeError, TypeError, ValueError):
        return False
    expected = {
        key: arguments.get(key)
        for key in (
            "handoff_id",
            "controller_id",
            "parent_run_id",
            "parent_scope_id",
            "child_scope_id",
            "expected_branch",
        )
    }
    return (
        _scope_handoff_response_error(
            decoded,
            expected,
            expected_head=cast(str, arguments.get("expected_head_sha")),
            expected_fingerprint=cast(str, arguments.get("expected_source_fingerprint")),
        )
        is None
    )


def _invoke_scope_handoff_apply(
    effects: EffectClient,
    effects_log: list[EffectIntent],
    target: str,
    arguments: Mapping[str, object],
) -> ToolResult:
    """Record and safely replay one idempotent source-snapshot commit attempt."""
    intent = EffectIntent("prepare_scope_handoff", target, arguments, True)
    journal = effects_log if isinstance(effects_log, EffectJournal) else None
    probe = journal.probe(intent) if journal is not None else None
    if probe is not None and probe.status in {"confirmed", "rejected"}:
        if probe.result is None:
            raise ActionJournalError("scope handoff journal response is missing")
        if probe.status == "confirmed" and _scope_handoff_entry_ready(
            cast(Mapping[str, object], probe.entry)
        ):
            return probe.result
    elif probe is None or probe.entry is None:
        effects_log.append(intent)
    try:
        result = _scope_handoff_call(effects, arguments)
    except BaseException as error:
        if journal is not None:
            journal.mark_unknown(intent, error)
        raise
    if journal is not None:
        journal.mark_result(intent, result)
    return result


def _prepare_scope_handoff(
    task: SubTLTask,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> str | None:
    """Commit the accepted parent worktree snapshot before a new subTL starts."""
    if not config.active:
        return None
    if not isinstance(effects, EffectClient):
        return "scope handoff is blocked because the active effect client is unavailable"
    identity = _scope_handoff_identity(task, state, config, store, effects)
    if isinstance(identity, str):
        return identity
    coordinates, handoff_id = identity
    if _scope_handoff_is_unresolved(effects_log, handoff_id):
        return "a prior scope handoff outcome is unresolved; continuation must reconcile it first"
    inspection_args = {"apply": False, "handoff_id": handoff_id, **coordinates}
    inspection = _invoke(
        "inspect_scope_handoff",
        handoff_id,
        inspection_args,
        True,
        effects,
        lambda client: _scope_handoff_call(client, inspection_args),
        effects_log,
        raise_on_failure=False,
    )
    error = _scope_handoff_response_error(inspection, coordinates)
    if error is not None:
        return error
    assert inspection is not None and isinstance(inspection.result, Mapping)
    inspected = inspection.result
    head = cast(str, inspected["head_after"])
    fingerprint = cast(str, inspected["source_fingerprint"])
    apply_args = {
        "apply": True,
        "handoff_id": handoff_id,
        **coordinates,
        "expected_head_sha": head,
        "expected_source_fingerprint": fingerprint,
    }
    target = _scope_handoff_action_target(effects_log, handoff_id, head, fingerprint)
    try:
        applied = _invoke_scope_handoff_apply(effects, effects_log, target, apply_args)
    except Exception as error:  # noqa: BLE001 - retain state and do not transfer control
        return f"scope handoff result is unresolved ({type(error).__name__}); retry continuation to reconcile"
    return _scope_handoff_response_error(
        applied,
        coordinates,
        expected_head=head,
        expected_fingerprint=fingerprint,
    )


def _scope_handoff_is_unresolved(effects_log: list[EffectIntent], handoff_id: str) -> bool:
    """Prevent a changed snapshot from bypassing a prior ambiguous commit."""
    if not isinstance(effects_log, EffectJournal):
        return False
    return any(
        entry.get("operation") == "prepare_scope_handoff"
        and entry.get("status") in {"intended", "unknown"}
        and isinstance(entry.get("arguments"), Mapping)
        and entry["arguments"].get("handoff_id") == handoff_id
        for entry in effects_log.snapshot()
    )


def _run_sub_tls(
    plan: WorkPlan,
    state: RunState,
    config: TLLoopConfig,
    source: EventQueue,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Run recursive children in deterministic, bounded order batches."""
    if not plan.sub_tls:
        return state
    post_merge_verified: dict[str, bool] = {}
    state = _reconcile_aggregate_publication_gates(
        plan.sub_tls, state, config, effects, store, effects_log, post_merge_verified
    )
    for task in plan.sub_tls:
        current = state.slices.get(task.name)
        if (
            task.integration.aggregate_pr_required
            and current is not None
            and _post_merge_recovery_started(current)
            and not post_merge_verified.get(task.name, False)
        ):
            return state
        gate = next(
            (
                item
                for item in state.gates
                if item.name == _aggregate_publication_gate_name(task.name)
            ),
            None,
        )
        if (
            task.integration.aggregate_pr_required
            and current is not None
            and _post_merge_recovery_started(current)
            and gate is not None
            and gate.status is not GateStatus.APPROVED
        ):
            return state
    tasks_by_name = {task.name: task for task in plan.sub_tls}
    current_order = state.current_order or 1
    for stage in plan.ordered_stages:
        if stage.order < current_order:
            continue
        if stage.order > current_order:
            break
        stage_tasks = tuple(tasks_by_name[name] for name in stage.sub_tls)
        state = store.load()
        stage_states = [state.slices.get(task.name) for task in stage_tasks]
        if any(current is None for current in stage_states):
            missing = next(
                task.name for task, current in zip(stage_tasks, stage_states) if current is None
            )
            raise TLLoopError(f"recursive slice {missing!r} is missing")
        for task, current in zip(stage_tasks, stage_states):
            if (
                current is not None
                and current.status is SliceStatus.MERGED
                and current.pr_number is not None
                and current.post_merge is not None
                and current.post_merge.phase is not PostMergePhase.COMPLETE
            ):
                state = _drain_post_merge_recovery(
                    state,
                    task.name,
                    current.pr_number,
                    config,
                    effects,
                    effects_log,
                    store,
                )
        state = store.load()
        stage_states = [state.slices.get(task.name) for task in stage_tasks]
        if any(
            task.integration.aggregate_pr_required
            and current is not None
            and current.status is SliceStatus.MERGED
            and _post_merge_recovery_pending(current)
            for task, current in zip(stage_tasks, stage_states)
        ):
            return state
        if any(
            current.status is SliceStatus.FAILED
            or (
                current.status is SliceStatus.PARKED
                and current.park_cause is not ParkCause.PUBLICATION_BLOCKED
            )
            for current in stage_states
            if current is not None
        ):
            return _fail_recursive_parent(
                state, config, effects, store, effects_log, "recursive child is not recoverable"
            )
        was_stage_complete = _ordered_stage_complete(stage_tasks, state.slices)
        pending = tuple(
            task
            for task, current in zip(stage_tasks, stage_states)
            if current is not None
            and current.status not in {SliceStatus.IN_REVIEW, SliceStatus.REPAIRING}
            and not (
                current.status is SliceStatus.PARKED
                and current.park_cause is ParkCause.PUBLICATION_BLOCKED
            )
            and not _ordered_child_complete(task, current)
        )
        for task in pending:
            current = state.slices.get(task.name)
            if current is None or current.status not in {SliceStatus.PENDING, SliceStatus.READY}:
                continue
            handoff_error = _prepare_scope_handoff(task, state, config, effects, store, effects_log)
            if handoff_error is not None:
                return _fail_recursive_parent(
                    state,
                    config,
                    effects,
                    store,
                    effects_log,
                    f"scope handoff for {task.name!r} is blocked: {handoff_error}",
                )
        if not pending:
            state = _integrate_stage_candidates(
                stage_tasks, state, config, effects, store, effects_log
            )
            _emit_stage_completion(
                stage,
                state,
                was_stage_complete,
                config,
                effects,
                effects_log,
            )
            if any(
                state.slices[task.name].status in {SliceStatus.IN_REVIEW, SliceStatus.REPAIRING}
                for task in stage_tasks
            ):
                break
            if not _ordered_stage_complete(stage_tasks, state.slices):
                break
            state, current_order = _advance_ordered_stage(
                stage.order, state, current_order, plan, store
            )
            continue
        if not any(
            current is not None and current.status is not SliceStatus.PENDING
            for current in stage_states
        ):
            _record_controller_event(
                "controller",
                "tl.stage_started",
                {
                    "order": stage.order,
                    "sub_tl_ids": list(stage.sub_tls),
                    "run_id": store.run_id,
                },
                config,
                effects,
                effects_log,
            )
        _validate_stage_event_routes(pending)
        if config.max_parallel_slices == 0:
            raise LoopLimitExceeded("max_parallel_slices must permit one recursive child")
        state, spawned = _prepare_sub_tl_stage(
            pending, state, config, source, effects, store, effects_log, stage.order
        )
        width = config.max_parallel_slices or len(spawned)
        stage_recovery = False
        for batch_start in range(0, len(spawned), width):
            batch = spawned[batch_start : batch_start + width]
            outcomes = _run_sub_tl_batch(batch, config, source, effects, store, state.budgets)
            # A live child process may have durably bound the server-confirmed
            # controller invocation into this parent while it was running.
            # Rebase the batch completion on that checkpoint so its status
            # update cannot overwrite the invocation lineage with stale state.
            state = store.load()
            state = _complete_sub_tl_batch(
                batch, outcomes, state, config, effects, store, effects_log
            )
            if any(phase is TLPhase.TLFailed for _, phase, _ in outcomes):
                return _fail_recursive_parent(
                    state, config, effects, store, effects_log, "recursive child failed"
                )
            if any(task.name in state.integration.sub_tl_recovery for task in stage_tasks):
                stage_recovery = True
        state = _integrate_stage_candidates(stage_tasks, state, config, effects, store, effects_log)
        _emit_stage_completion(
            stage,
            state,
            was_stage_complete,
            config,
            effects,
            effects_log,
        )
        if any(
            state.slices[task.name].status in {SliceStatus.IN_REVIEW, SliceStatus.REPAIRING}
            for task in stage_tasks
        ):
            break
        if not _ordered_stage_complete(stage_tasks, state.slices):
            break
        if stage_recovery:
            break
        state, current_order = _advance_ordered_stage(
            stage.order, state, current_order, plan, store
        )
    if plan.sub_tls and not plan.workers and not plan.leaves:
        current_stage_ids = next(
            (stage.sub_tls for stage in plan.ordered_stages if stage.order == state.current_order),
            (),
        )
        awaiting_integration = tuple(
            task.name
            for task in plan.sub_tls
            if task.name in current_stage_ids
            and not _ordered_child_complete(task, state.slices[task.name])
        )
        if awaiting_integration:
            before_phase = _phase_from_state(state)
            handles = {
                task_id: ChildHandle(task_id, state.slices[task_id].branch or "", "sub-tl")
                for task_id in awaiting_integration
            }
            state = store.checkpoint(
                TLWaiting(handles),
                state.slices,
                state.budgets,
                state.events.last_consumed_offset,
                current_order=state.current_order,
                ordered_stages=state.ordered_stages,
                integration=state.integration,
            )
            _emit_phase_change(
                store.run_id,
                before_phase,
                _phase_from_state(state),
                config,
                effects,
                effects_log,
            )
            return state
        before_phase = _phase_from_state(state)
        if isinstance(state.recursive_fsm, RecursiveTLAllMerged):
            return state
        state = store.checkpoint(
            TLDone(), state.slices, state.budgets, state.events.last_consumed_offset
        )
        _emit_phase_change(
            store.run_id,
            before_phase,
            _phase_from_state(state),
            config,
            effects,
            effects_log,
        )
    return state


def _emit_stage_completion(
    stage: OrderedStage,
    state: RunState,
    was_complete: bool,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    """Publish one durable completion observation for an ordered stage."""
    if was_complete or any(
        not _ordered_slice_complete(state.slices[slice_id])
        for slice_id in stage.sub_tls
        if slice_id in state.slices
    ):
        return
    _record_controller_event(
        "controller",
        "tl.stage_completed",
        {
            "order": stage.order,
            "sub_tl_ids": list(stage.sub_tls),
        },
        config,
        effects,
        effects_log,
    )


def _advance_ordered_stage(
    order: int,
    state: RunState,
    current_order: int,
    plan: WorkPlan,
    store: RunStore,
) -> tuple[RunState, int]:
    """Persist the next manifest stage only after this stage is complete."""
    next_orders = [stage.order for stage in plan.ordered_stages if stage.order > order]
    if not next_orders:
        return state, current_order
    next_order = min(next_orders)
    if current_order == next_order:
        return state, current_order
    return (
        store.set_ordered_state(
            next_order,
            state.ordered_stages,
            state.integration,
        ),
        next_order,
    )


def _prepare_sub_tl_stage(
    tasks: Sequence[SubTLTask],
    state: RunState,
    config: TLLoopConfig,
    source: EventQueue,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    order: int,
) -> tuple[RunState, tuple[SubTLTask, ...]]:
    """Persist every owner before launching a same-order batch."""
    del source
    updated_slices = dict(state.slices)
    prepared: list[SubTLTask] = []
    for task in tasks:
        current = state.slices[task.name]
        child_name = _child_controller_name(task)
        branch = derive_child_branch(config.branch, child_name)
        worktree = str(_sub_tl_worktree(config, store.root_dir, store.run_id, task))
        if config.depth >= config.max_depth:
            before_phase = _phase_from_state(state)
            parked = replace(
                slice_transition(current, SliceStatusChanged(SliceStatus.PARKED)),
                park_cause=ParkCause.SCHEDULE_DEADLOCK,
            )
            failed_slices = {**state.slices, task.name: parked}
            state = store.checkpoint(
                TLFailed(f"depth ceiling reached for {task.name}"),
                failed_slices,
                state.budgets,
                state.events.last_consumed_offset,
                current_order=order,
                ordered_stages=state.ordered_stages,
                integration=state.integration,
            )
            _emit_slice_status_changes(
                {task.name: current},
                {task.name: parked},
                config,
                effects,
                effects_log,
            )
            _record_controller_event(
                task.name,
                "tl.slice_parked",
                {
                    "slice_id": task.name,
                    "park_cause": ParkCause.SCHEDULE_DEADLOCK.value,
                    "attempts": parked.attempts,
                },
                config,
                effects,
                effects_log,
            )
            _emit_phase_change(
                store.run_id,
                before_phase,
                _phase_from_state(state),
                config,
                effects,
                effects_log,
            )
            raise DepthLimitExceeded(f"depth ceiling {config.max_depth} reached for {task.name!r}")
        if current.status is SliceStatus.PENDING:
            internal_intent_id = hashlib.sha256(
                f"{store.run_id}:{task.name}:{current.attempts + 1}".encode()
            ).hexdigest()[:32]
            # This mints a fresh identity for a child controller, it does not
            # rebuild a leaf dispatch, so it carries neither this run's
            # controller epoch nor a dispatch generation. The child mints its
            # own epoch, and the generation persisted below is the one the
            # parent's publication binder compares the child's own PR event
            # against, so it is not this run's attempt number.
            internal_attempt = DispatchAttempt(
                internal_intent_id,
                time.time() if config.active else 0.0,
                current.agent_type or "sub-tl",
                attempt=current.attempts + 1,
            )
            confirmation = _record_controller_event(
                task.name,
                "tl.dispatch_confirmed",
                _dispatch_payload(task.name, internal_attempt, "sub_tl_started"),
                config,
                effects,
                effects_log,
            )
            authoritative_seq = _controller_event_run_seq(confirmation)
            if authoritative_seq is None:
                authoritative_seq = state.events.last_consumed_offset
            updated_slices[task.name] = replace(
                slice_transition(current, SliceStatusChanged(SliceStatus.SPAWNED)),
                attempts=internal_attempt.attempt,
                base_ref=config.branch,
                branch=branch,
                worktree=worktree,
                dispatch_intent_id=internal_intent_id,
                dispatch_started_at=internal_attempt.started_at,
                dispatch_last_boundary=SUB_TL_DISPATCH_STARTED_BOUNDARY,
                dispatch_agent_id=child_name,
                dispatch_authoritative_event_seq=authoritative_seq,
                dispatch_generation=internal_attempt.dispatch_generation,
            )
        prepared.append(task)
    states = dict(state.integration.sub_tl_states)
    for task in prepared:
        if not isinstance(states.get(task.name), SubTLLifecycle):
            states[task.name] = IntegrationLifecycle.RUNNING
    integration = replace(state.integration, sub_tl_states=states)
    previous_slices = state.slices
    state = store.checkpoint(
        _phase_from_state(state),
        updated_slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=order,
        ordered_stages=state.ordered_stages,
        integration=integration,
    )
    _emit_slice_status_changes(previous_slices, state.slices, config, effects, effects_log)
    return state, tuple(prepared)


def _run_sub_tl_batch(
    tasks: Sequence[SubTLTask],
    config: TLLoopConfig,
    source: EventQueue,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    budgets: BudgetLedger,
) -> tuple[tuple[SubTLTask, TLPhase | None, RunState | None], ...]:
    """Run one bounded batch and collect outcomes in plan order."""
    if (
        config.active
        and isinstance(effects, EffectClient)
        and isinstance(effects.transport, TransportClient)
    ):
        return _run_live_sub_tl_batch(tasks, config, source, effects, store, budgets)

    def run_one(task: SubTLTask) -> tuple[SubTLTask, TLPhase | None, RunState | None]:
        branch = derive_child_branch(config.branch, _child_controller_name(task))
        worktree = str(_sub_tl_worktree(config, store.root_dir, store.run_id, task))
        child_store = RunStore(task.name, store.run_dir)
        if child_store.path.exists():
            child_state = child_store.load()
            child_phase = _child_completion_phase(child_state)
            retrying_failed_child = (
                config.ordered_recovery_child == task.name and child_phase is TLPhase.TLFailed
            )
            retrying_approved_blocked_leaf = retrying_failed_child and (
                _approved_blocked_leaf_child_retry(task, child_state, config, store)
            )
            if _child_handoff_ready(child_state, store.run_id) and not retrying_failed_child:
                return task, child_phase, child_state
            if child_phase is TLPhase.TLFailed and not retrying_failed_child:
                return task, child_phase, child_state
            if (
                _child_recovery_projection(child_state, store.run_id) is not None
                and not retrying_approved_blocked_leaf
            ):
                return task, child_phase, child_state
        child_config = _child_config(
            config,
            task,
            source,
            effects,
            store,
            branch,
            worktree,
            ordered_recovery=config.ordered_recovery_child == task.name,
        )
        try:
            child_result = tl_run({"run_id": task.name, "plan": task.plan}, child_config, budgets)
        except Exception as error:  # noqa: BLE001 - batch completion persists a durable failure
            child_store.record_exit_reason(str(error))
            return task, TLPhase.TLFailed, None
        return task, _child_completion_phase(child_result.final_state), child_result.final_state

    with ThreadPoolExecutor(max_workers=len(tasks)) as executor:
        futures = [executor.submit(run_one, task) for task in tasks]
        return tuple(future.result() for future in futures)


def _child_completion_phase(state: RunState) -> TLPhase:
    """Project an empty canonical child for the legacy parent adapter."""
    recursive_fsm = getattr(state, "recursive_fsm", None)
    manifest = getattr(state, "plan_manifest", None)
    if (
        isinstance(recursive_fsm, RecursiveTLAllMerged)
        and manifest is not None
        and not manifest.nodes
    ):
        return TLPhase.TLDone
    if recursive_fsm is None:
        return state.fsm.phase
    return _phase_tag(_phase_from_state(state))


def _run_live_sub_tl_batch(
    tasks: Sequence[SubTLTask],
    config: TLLoopConfig,
    source: EventQueue,
    effects: EffectClient,
    store: RunStore,
    budgets: BudgetLedger,
) -> tuple[tuple[SubTLTask, TLPhase | None, RunState | None], ...]:
    """Run live children as independently owned controller processes."""
    if "fork" not in multiprocessing.get_all_start_methods():
        raise TLLoopError("live ordered sub-TLs require fork-capable controller isolation")
    context = multiprocessing.get_context("fork")
    child_source_spec = _child_source_spec(source)
    existing: dict[str, tuple[SubTLTask, TLPhase | None, RunState | None]] = {}
    runnable: list[SubTLTask] = []
    for task in tasks:
        child_store = RunStore(task.name, store.run_dir)
        if child_store.path.exists():
            child_state = child_store.load()
            child_phase = _child_completion_phase(child_state)
            retrying_failed_child = (
                config.ordered_recovery_child == task.name and child_phase is TLPhase.TLFailed
            )
            retrying_approved_blocked_leaf = retrying_failed_child and (
                _approved_blocked_leaf_child_retry(task, child_state, config, store)
            )
            if (_child_handoff_ready(child_state, store.run_id) and not retrying_failed_child) or (
                _child_recovery_projection(child_state, store.run_id) is not None
                and not retrying_approved_blocked_leaf
            ):
                existing[task.name] = (task, child_phase, child_state)
                continue
            if child_phase is TLPhase.TLFailed and not retrying_failed_child:
                existing[task.name] = (task, child_phase, child_state)
                continue
        runnable.append(task)
    processes = [
        (
            task,
            context.Process(
                target=_run_live_sub_tl,
                args=(task, config, child_source_spec, effects, store, budgets),
                name=f"tl-sub-{task.name}",
            ),
        )
        for task in runnable
    ]
    for _, process in processes:
        process.start()
    outcomes_by_name: dict[str, tuple[SubTLTask, TLPhase | None, RunState | None]] = {
        task.name: existing[task.name] for task in tasks if task.name in existing
    }
    for task, process in processes:
        child_store = RunStore(task.name, store.run_dir)
        child_state = _supervise_live_sub_tl(process, child_store, config)
        phase = (
            _child_completion_phase(child_state) if child_state is not None else TLPhase.TLFailed
        )
        outcomes_by_name[task.name] = (task, phase, child_state)
    return tuple(outcomes_by_name[task.name] for task in tasks)


def _approved_blocked_leaf_child_retry(
    task: SubTLTask,
    child_state: RunState,
    parent_config: TLLoopConfig,
    parent_store: RunStore,
) -> bool:
    """Bypass a retained child gate only for the exact approved resume proof."""
    branch = derive_child_branch(parent_config.branch, _child_controller_name(task))
    worktree = str(
        _sub_tl_worktree(parent_config, parent_store.root_dir, parent_store.run_id, task)
    )
    child_config = _ordered_child_config(
        parent_config, task, branch, worktree, parent_config.branch
    )
    child_store = RunStore(task.name, parent_store.run_dir)
    proof, _reason = _blocked_leaf_resume_proof(task.plan, child_state, child_config, child_store)
    return proof is not None


def _persist_child_startup_failure(child_store: RunStore, reason: str) -> None:
    """Durably record a live child controller failure before its diagnostic.

    A child that dies before authoritative resolution otherwise leaves a
    non-terminal checkpoint, which makes the recovery proof impossible because
    recovery requires an authoritative recursive failure. The failure
    checkpoint is also the revision the controller-exit diagnostic binds to.
    """
    load = getattr(child_store, "load", None)
    checkpoint = getattr(child_store, "checkpoint", None)
    if load is None or checkpoint is None:
        return
    try:
        state = load()
    except (OSError, ValueError):
        return
    if _is_terminal_phase(_phase_from_state(state)):
        return
    try:
        checkpoint(
            _failure_phase(state, reason),
            state.slices,
            state.budgets,
            state.events.last_consumed_offset,
            current_order=state.current_order,
            ordered_stages=state.ordered_stages,
            integration=state.integration,
        )
    except (OSError, ValueError, TLLoopError):
        return


def _supervise_live_sub_tl(
    process: multiprocessing.Process,
    child_store: RunStore,
    config: TLLoopConfig,
) -> RunState | None:
    """Supervise a child until it resolves or explicit cancellation is requested."""
    poll_interval = max(config.poll_interval, 0.05)
    cancelled = False
    while process.is_alive():
        if config.cancel_event is not None and config.cancel_event.is_set():
            cancelled = True
            process.terminate()
            process.join()
            reason = "sub-TL controller cancelled explicitly"
            _persist_child_startup_failure(child_store, reason)
            _record_child_exit_reason(child_store, reason, outcome="cancelled")
            break
        try:
            child_state = child_store.load()
        except (OSError, ValueError):
            child_state = None
        if _child_recovery_projection(child_state, getattr(child_store, "run_id", "")) is not None:
            return child_state
        process.join(timeout=poll_interval)
    exitcode = getattr(process, "exitcode", None)
    if not cancelled and exitcode is not None:
        try:
            child_state = child_store.load()
        except (OSError, ValueError):
            child_state = None
        if (
            child_state is not None
            and _child_recovery_projection(child_state, getattr(child_store, "run_id", ""))
            is not None
        ):
            return child_state
        empty_scope = (
            child_state is not None
            and isinstance(getattr(child_state, "recursive_fsm", None), RecursiveTLAllMerged)
            and getattr(child_state, "plan_manifest", None) is not None
            and not child_state.plan_manifest.nodes
        )
        if child_state is None or (
            child_state.fsm.phase
            not in {
                TLPhase.TLAllMerged,
                TLPhase.TLDone,
                TLPhase.TLPRFiled,
                TLPhase.TLFailed,
            }
            and not empty_scope
        ):
            reason = (
                f"sub-TL controller exited before authoritative resolution with code {exitcode}"
            )
            _persist_child_startup_failure(child_store, reason)
            _record_child_exit_reason(child_store, reason, outcome="process_exit")
            return None
    try:
        child_state = child_store.load()
    except (OSError, ValueError):
        return None
    if isinstance(getattr(child_state, "recursive_fsm", None), RecursiveTLFailed):
        _record_child_exit_reason(
            child_store,
            child_state.recursive_fsm.reason,
            outcome="supervisor_observed_failure",
            expected_revision=child_state.revision,
        )
        return child_store.load()
    return child_state


def _run_live_sub_tl(
    task: SubTLTask,
    config: TLLoopConfig,
    source: EventQueue | str | Path | None,
    effects: EffectClient,
    store: RunStore,
    budgets: BudgetLedger,
) -> None:
    """Own one live child controller process and leave its checkpoint durable."""
    branch = derive_child_branch(config.branch, _child_controller_name(task))
    worktree = str(_sub_tl_worktree(config, store.root_dir, store.run_id, task))
    child_store = RunStore(task.name, store.run_dir)
    owned_source: LedgerQueue | None = None
    try:
        child_source = task.source
        if child_source is None:
            child_source, owned_source = _child_source(
                source,
                task,
                config,
                store,
                child_store,
            )
        if config.project_root is not None:
            published_pr_number: int | None = None
            published_head_sha: str | None = None
            if child_store.path.exists():
                persisted_child = child_store.load()
                published_pr_number = persisted_child.integration.aggregate_pr_number
                published_head_sha = persisted_child.integration.aggregate_head_sha
            invocation_id = effects.transport.provision_ordered_sub_tl(
                effects.name,
                agent_name=_child_controller_name(task),
                birth_branch=branch,
                parent_branch=config.branch,
                working_dir=worktree,
                slice_id=task.name,
                pr_number=published_pr_number,
                head_sha=published_head_sha,
            )
            _checkpoint_ordered_sub_tl_invocation(store, task.name, invocation_id)
        child_config = _child_config(
            config,
            task,
            child_source,
            effects,
            store,
            branch,
            worktree,
            keep_alive_on_waiting=True,
            ordered_recovery=config.ordered_recovery_child == task.name,
        )
        result = tl_run({"run_id": task.name, "plan": task.plan}, child_config, budgets)
        final_state = getattr(result, "final_state", None)
        if final_state is not None and not (
            _child_handoff_ready(final_state, store.run_id)
            or _child_recovery_projection(final_state, store.run_id) is not None
        ):
            raise TLLoopError("sub-TL controller returned before authoritative resolution")
        if final_state is not None and isinstance(final_state.recursive_fsm, RecursiveTLFailed):
            _record_child_exit_reason(
                child_store,
                final_state.recursive_fsm.reason,
                outcome="normal_return",
                expected_revision=final_state.revision,
            )
    except Exception as error:
        _persist_child_startup_failure(child_store, str(error))
        _record_child_exit_reason(child_store, str(error), error=error, outcome="exception")
        raise
    finally:
        if owned_source is not None:
            owned_source.close(timeout=max(1.0, config.poll_interval * 4))


def _checkpoint_ordered_sub_tl_invocation(
    store: RunStore,
    child_id: str,
    invocation_id: str,
) -> None:
    """Persist the server-confirmed invocation across the parent FSM and slice."""
    if not isinstance(invocation_id, str) or not invocation_id.strip():
        raise TLLoopError("ordered sub-TL provisioning returned an empty invocation ID")
    if not store.path.exists():
        return
    for _attempt in range(MAX_ORDERED_INVOCATION_CHECKPOINT_ATTEMPTS):
        state = store.load()
        target = state.slices.get(child_id)
        if target is None:
            return
        recursive_fsm = state.recursive_fsm
        if not isinstance(recursive_fsm, RecursiveTLRunning):
            raise TLLoopError("ordered sub-TL invocation has no running parent scope")
        pending_by_order = dict(recursive_fsm.pending_by_order)
        match_count = 0
        for order, records in pending_by_order.items():
            updated_records = []
            for record in records:
                if record.child_id == child_id:
                    match_count += 1
                    updated_records.append(
                        replace(
                            record,
                            dispatch_intent_id=target.dispatch_intent_id,
                            invocation_id=invocation_id,
                        )
                    )
                else:
                    updated_records.append(record)
            pending_by_order[order] = tuple(updated_records)
        if match_count != 1:
            raise TLLoopError(f"ordered sub-TL {child_id!r} has {match_count} pending FSM records")
        dispatch_intents = dict(recursive_fsm.dispatch_intents)
        if target.dispatch_intent_id is None:
            dispatch_intents.pop(child_id, None)
        else:
            dispatch_intents[child_id] = target.dispatch_intent_id
        recovery = target.recovery
        if recovery is not None:
            evidence = dict(recovery.evidence)
            evidence["invocation_id"] = invocation_id
            recovery = replace(recovery, evidence=evidence)
        slices = dict(state.slices)
        slices[child_id] = replace(
            target,
            dispatch_invocation_id=invocation_id,
            recovery=recovery,
        )
        updated_fsm = replace(
            recursive_fsm,
            pending_by_order=pending_by_order,
            dispatch_intents=dispatch_intents,
        )
        if slices[child_id] == target and updated_fsm == recursive_fsm:
            return
        try:
            store.checkpoint(
                updated_fsm,
                slices,
                state.budgets,
                state.events.last_consumed_offset,
                expected_revision=state.revision,
            )
            return
        except CheckpointConflict:
            continue
    raise TLLoopError("parent checkpoint kept changing while recording ordered invocation")


def _child_source_spec(source: EventQueue) -> EventQueue | Path:
    """Pass ledger metadata across fork while retaining synthetic sources."""
    candidate: object = source
    seen: set[int] = set()
    while id(candidate) not in seen:
        seen.add(id(candidate))
        if isinstance(candidate, LedgerQueue):
            return candidate.reader.segments_dir
        nested = getattr(candidate, "queue", None)
        if nested is None or nested is candidate:
            break
        candidate = nested
    return source


def _child_source(
    source: EventQueue | str | Path | None,
    task: SubTLTask,
    config: TLLoopConfig,
    store: RunStore,
    child_store: RunStore,
) -> tuple[EventQueue, LedgerQueue | None]:
    """Build a child-owned source, retaining explicit synthetic sources."""
    if isinstance(source, (str, Path)):
        segments_dir = Path(source)
    elif isinstance(source, LedgerQueue):
        # Compatibility for direct callers of _run_live_sub_tl. The normal
        # batch path passes only the immutable path before forking.
        segments_dir = source.reader.segments_dir
    elif source is not None:
        return source, None
    else:
        raise TLLoopError(f"live sub-TL {task.name!r} has no event source")
    ledger_run_id = config.ledger_run_id
    if ledger_run_id is None:
        try:
            ledger_run_id = store.load().ledger_run_id
        except (OSError, ValueError):
            ledger_run_id = None
    child_source = start_child_ledger_queue(
        segments_dir,
        child_store.run_dir,
        ledger_run_id=ledger_run_id,
        scope_agent_id=_child_controller_name(task),
        poll_interval=config.poll_interval,
    )
    return child_source, child_source


def _child_handoff_ready(state: RunState | None, parent_run_id: str) -> bool:
    """Accept only child scopes whose direct merge work is complete."""
    if state is None:
        return False
    del parent_run_id
    slices = getattr(state, "slices", {})
    if isinstance(slices, Mapping) and any(
        getattr(slice_state, "recovery", None) is not None for slice_state in slices.values()
    ):
        return False
    integration = getattr(state, "integration", None)
    if getattr(integration, "sub_tl_recovery", {}):
        return False
    recursive_fsm = getattr(state, "recursive_fsm", None)
    if isinstance(recursive_fsm, (RecursiveTLFailed, RecursiveTLParked)):
        return True
    if isinstance(
        recursive_fsm,
        (RecursiveTLAllMerged, RecursiveTLFinalizing, RecursiveTLPRFiled, RecursiveTLDone),
    ):
        return _scope_post_merge_complete(state) and _scope_declared_completion_matches(state)
    if recursive_fsm is not None:
        return False
    if state.fsm.phase is TLPhase.TLAllMerged:
        return _scope_post_merge_complete(state) and _scope_declared_completion_matches(state)
    return state.fsm.phase in {TLPhase.TLDone, TLPhase.TLPRFiled, TLPhase.TLFailed}


def _aggregate_scope_phase_complete(state: RunState) -> bool:
    """Require a terminal child phase before repairing its aggregate label."""
    recursive_fsm = getattr(state, "recursive_fsm", None)
    if recursive_fsm is None:
        return state.fsm.phase in {TLPhase.TLDone, TLPhase.TLPRFiled, TLPhase.TLAllMerged}
    return isinstance(
        recursive_fsm,
        (RecursiveTLAllMerged, RecursiveTLFinalizing, RecursiveTLPRFiled, RecursiveTLDone),
    )


def _aggregate_declared_node_complete(
    scope_state: RunState,
    scope_store: RunStore,
    declared_manifest: PlanManifest,
    node: ManifestNode,
) -> bool:
    """Prove one direct leaf or nested sub-TL declaration completed."""
    current = scope_state.slices.get(node.name)
    if current is None:
        return False
    if node.kind in {"leaf", "worker"}:
        return _ordered_slice_complete(current)
    if node.kind != "sub_tl" or not _ordered_slice_complete(current):
        return False
    child_manifest = declared_manifest.child_manifests.get(node.node_id)
    if child_manifest is None:
        return False
    child_store = RunStore(node.name, scope_store.run_dir)
    try:
        child_state = child_store.load()
    except (OSError, ValueError):
        return False
    return _aggregate_scope_completion_proven(
        scope_state,
        node.name,
        child_state,
        child_store,
        child_manifest,
    )


def _aggregate_scope_completion_proven(
    parent_state: RunState,
    expected_scope_run_id: str,
    scope_state: RunState,
    scope_store: RunStore,
    declared_manifest: PlanManifest,
) -> bool:
    """Prove one declared scope and every direct descendant completed."""
    if (
        _aggregate_scope_branch_binding_error(
            parent_state, expected_scope_run_id, scope_state, declared_manifest
        )
        is not None
    ):
        return False
    if not _child_owner_checkpoint_matches(
        parent_state,
        expected_scope_run_id,
        scope_state,
        declared_manifest,
    ) or not _aggregate_scope_phase_complete(scope_state):
        return False
    return all(
        _aggregate_declared_node_complete(scope_state, scope_store, declared_manifest, node)
        for node in declared_manifest.nodes
    ) and _scope_post_merge_complete(scope_state)


def _aggregate_child_completion_proven(
    parent_state: RunState,
    child_state: RunState | None,
    child_store: RunStore,
    child_name: str,
) -> tuple[bool, str]:
    """Bind aggregate repair to the accepted parent declaration and leaves."""
    if child_state is None or parent_state.plan_manifest is None:
        return False, "aggregate_child_declaration_unavailable"
    declaration = next(
        (
            node
            for node in parent_state.plan_manifest.nodes
            if node.kind == "sub_tl" and node.name == child_name
        ),
        None,
    )
    if declaration is None:
        return False, "aggregate_child_declaration_missing"
    child_manifest = parent_state.plan_manifest.child_manifests.get(declaration.node_id)
    if child_manifest is None:
        return False, "aggregate_child_manifest_missing"
    if child_state.run_id != declaration.name:
        return False, "aggregate_child_run_id_mismatch"
    if child_state.parent_run_id != parent_state.run_id:
        return False, "aggregate_child_parent_mismatch"
    if (
        child_state.plan_manifest is None
        or child_state.plan_manifest.digest != child_manifest.digest
    ):
        return False, "aggregate_child_manifest_mismatch"
    branch_error = _aggregate_scope_branch_binding_error(
        parent_state, declaration.name, child_state, child_manifest
    )
    if branch_error is not None:
        return False, branch_error
    if not _aggregate_scope_completion_proven(
        parent_state, declaration.name, child_state, child_store, child_manifest
    ):
        return False, "aggregate_child_completion_incomplete"
    return True, "accepted_child_declaration_and_completion"


def _aggregate_scope_branch_binding_error(
    parent_state: RunState,
    expected_scope_run_id: str,
    scope_state: RunState,
    declared_manifest: PlanManifest,
) -> str | None:
    """Bind checkpoint branches to the accepted parent declaration."""
    parent_manifest = parent_state.plan_manifest
    if parent_manifest is None:
        return "aggregate_child_declaration_unavailable"
    declaration = next(
        (
            node
            for node in parent_manifest.nodes
            if node.kind == "sub_tl" and node.name == expected_scope_run_id
        ),
        None,
    )
    if declaration is None:
        return "aggregate_child_declaration_missing"
    accepted_child = parent_manifest.child_manifests.get(declaration.node_id)
    if accepted_child is None or accepted_child.digest != declared_manifest.digest:
        return "aggregate_child_manifest_mismatch"
    return _aggregate_declared_scope_branch_error(
        parent_state, scope_state, parent_manifest, declaration, declared_manifest
    )


def _aggregate_declared_scope_branch_error(
    parent_state: RunState,
    scope_state: RunState,
    parent_manifest: PlanManifest,
    declaration: ManifestNode,
    declared_manifest: PlanManifest,
) -> str | None:
    """Check the checkpoint against the declaration's immutable branch pair."""
    if (
        declaration.owned_branch != declared_manifest.owned_branch
        or declaration.parent_integration_target != declared_manifest.parent_integration_target
    ):
        return "aggregate_child_branch_declaration_mismatch"
    expected_parent_branch = parent_manifest.owned_branch
    if (
        declaration.parent_integration_target != expected_parent_branch
        or declared_manifest.parent_integration_target != expected_parent_branch
    ):
        return "aggregate_child_parent_branch_declaration_mismatch"
    if parent_state.owner_branch and parent_state.owner_branch != expected_parent_branch:
        return "aggregate_parent_branch_mismatch"
    if scope_state.parent_branch != expected_parent_branch:
        return "aggregate_child_parent_branch_mismatch"
    if scope_state.owner_branch != declaration.owned_branch:
        return "aggregate_child_owner_branch_mismatch"
    return None


def _exit_marker_matches_checkpoint(
    diagnostic: Mapping[str, object] | None,
    child_store: RunStore,
) -> bool:
    """Return whether a diagnostic marker is already bound to the live checkpoint."""
    if not isinstance(diagnostic, Mapping):
        return False
    bound_revision = diagnostic.get("checkpoint_revision")
    if type(bound_revision) is not int:
        return False
    load = getattr(child_store, "load", None)
    if load is None:
        return False
    try:
        state = load()
    except (OSError, ValueError):
        return False
    return bound_revision == state.revision


def _record_child_exit_reason(
    child_store: RunStore,
    reason: str,
    *,
    error: BaseException | None = None,
    outcome: str = "controller_exit",
    expected_revision: int | None = None,
) -> None:
    """Record a checkpoint-bound diagnostic without overwriting newer evidence.

    A same-revision conflicting diagnostic is retained for recovery to reject.
    A marker bound to an older checkpoint is replaced only after the current
    failure checkpoint has been loaded and its revision rechecked under the
    shared run-state lock.
    """
    try:
        state = child_store.load()
    except (OSError, ValueError):
        return
    if expected_revision is not None and state.revision != expected_revision:
        return
    recursive_phase = getattr(state, "recursive_fsm", None)
    ordinary_phase = getattr(getattr(state, "fsm", None), "phase", None)
    if not (isinstance(recursive_phase, RecursiveTLFailed) or ordinary_phase is TLPhase.TLFailed):
        return
    existing = child_store.exit_diagnostics()
    existing_revision = (
        existing.get("checkpoint_revision") if isinstance(existing, Mapping) else None
    )
    if existing_revision == state.revision:
        if _ordered_exit_diagnostic_binding_error(existing, state) is None:
            return
        return
    if type(existing_revision) is int and existing_revision > state.revision:
        return
    child_store.record_exit_reason(
        reason,
        error=error,
        outcome=outcome,
        expected_revision=state.revision,
    )


def _complete_sub_tl_batch(
    tasks: Sequence[SubTLTask],
    outcomes: Sequence[tuple[SubTLTask, TLPhase | None, RunState | None]],
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    *,
    prepublished_candidates: Mapping[str, AggregateCandidate] | None = None,
) -> RunState:
    """Apply a batch atomically after all same-order children finish."""
    del tasks
    updated_slices = dict(state.slices)
    sub_tl_states = dict(state.integration.sub_tl_states)
    sub_tl_recovery = dict(state.integration.sub_tl_recovery)
    candidate_records = dict(state.integration.candidates)
    canonical_phase = state.recursive_fsm
    publication_failures: list[AggregatePublicationRejected] = []
    for task, phase, child_state in outcomes:
        child_handoff_ready = phase is TLPhase.TLFailed or _child_handoff_ready(
            child_state, state.run_id
        )
        if not child_handoff_ready:
            current = updated_slices[task.name]
            updated_slices[task.name] = slice_transition(
                current, SliceStatusChanged(SliceStatus.SPAWNED)
            )
            projection = _child_recovery_projection(child_state, state.run_id)
            if projection is not None:
                lifecycle, summary = projection
                sub_tl_states[task.name] = lifecycle
                sub_tl_recovery[task.name] = summary
            continue
        status = SliceStatus.FAILED if phase is TLPhase.TLFailed else SliceStatus.MERGED
        previous_lifecycle = sub_tl_states.get(task.name, IntegrationLifecycle.RUNNING)
        if isinstance(previous_lifecycle, SubTLLifecycle):
            previous_lifecycle = IntegrationLifecycle.RUNNING
        sub_tl_recovery.pop(task.name, None)
        lifecycle = (
            previous_lifecycle
            if status is SliceStatus.MERGED
            and previous_lifecycle is IntegrationLifecycle.CHILDREN_MERGED
            else _transition_sub_tl_lifecycle(
                previous_lifecycle,
                (
                    IntegrationTransition.CHILDREN_MERGED
                    if status is SliceStatus.MERGED
                    else IntegrationTransition.FAILED
                ),
            )
        )
        current = updated_slices[task.name]
        candidate_runtime = _candidate_runtime(state.integration, task.name)
        if status is SliceStatus.MERGED:
            candidate = (prepublished_candidates or {}).get(task.name)
            if candidate is None:
                try:
                    candidate = _ensure_aggregate_candidate(
                        task, child_state, config, effects, store, effects_log
                    )
                except AggregatePublicationRejected as error:
                    if error.task_name != task.name:
                        raise
                    current = _park_aggregate_publication(current, error)
                    status = SliceStatus.PARKED
                    lifecycle = IntegrationLifecycle.CHILDREN_MERGED
                    candidate_runtime = replace(candidate_runtime, lifecycle=lifecycle)
                    publication_failures.append(error)
                    candidate = None
            if candidate is not None:
                current = store.load().slices.get(task.name, current)
                owner_id = f"{store.run_id}:{task.name}:integration"
                owner_branch = (
                    child_state.owner_branch
                    if child_state is not None and child_state.owner_branch
                    else derive_child_branch(config.branch, _child_controller_name(task))
                )
                owner_worktree = (
                    child_state.owner_worktree
                    if child_state is not None and child_state.owner_worktree
                    else str(_sub_tl_worktree(config, store.root_dir, store.run_id, task))
                )
                if current.park_cause is ParkCause.PUBLICATION_BLOCKED:
                    current = replace(
                        current,
                        park_cause=None,
                        park_issue_id=None,
                        park_audit=None,
                        blocked_by=None,
                    )
                current = slice_transition(current, SliceStatusChanged(SliceStatus.IN_REVIEW))
                current = replace(
                    current,
                    pr_number=candidate.pr_number,
                    dispatch_last_boundary="aggregate_pr_open",
                )
                status = SliceStatus.IN_REVIEW
                lifecycle = _transition_sub_tl_lifecycle(
                    lifecycle, IntegrationTransition.AGGREGATE_PR_OPENED
                )
                candidate_runtime = replace(
                    candidate_runtime,
                    lifecycle=lifecycle,
                    aggregate_pr_number=candidate.pr_number,
                    aggregate_head_sha=candidate.head_sha,
                    aggregate_patch_digest=candidate.patch_digest,
                    aggregate_original_base_sha=candidate.original_base_sha,
                    integration_owner_id=owner_id,
                    integration_owner_run_id=task.name,
                    integration_owner_branch=owner_branch,
                    integration_owner_worktree=owner_worktree,
                    head_sha=candidate.head_sha,
                    patch_digest=candidate.patch_digest,
                )
        updated_slices[task.name] = (
            current
            if status is SliceStatus.PARKED
            else slice_transition(current, SliceStatusChanged(status))
        )
        sub_tl_states[task.name] = lifecycle
        candidate_records[task.name] = IntegrationCandidateState(
            lifecycle=candidate_runtime.lifecycle,
            aggregate_pr_number=candidate_runtime.aggregate_pr_number,
            aggregate_head_sha=candidate_runtime.aggregate_head_sha,
            aggregate_patch_digest=candidate_runtime.aggregate_patch_digest,
            aggregate_original_base_sha=candidate_runtime.aggregate_original_base_sha,
            integration_owner_id=candidate_runtime.integration_owner_id,
            integration_owner_run_id=candidate_runtime.integration_owner_run_id,
            integration_owner_branch=candidate_runtime.integration_owner_branch,
            integration_owner_worktree=candidate_runtime.integration_owner_worktree,
            head_sha=candidate_runtime.head_sha,
            patch_digest=candidate_runtime.patch_digest,
            validated_base_sha=candidate_runtime.validated_base_sha,
            merge_tree_sha=candidate_runtime.merge_tree_sha,
            integration_evidence_at=candidate_runtime.integration_evidence_at,
            ci_status=candidate_runtime.ci_status,
            merge_attempts=candidate_runtime.merge_attempts,
            base_revalidation_count=candidate_runtime.base_revalidation_count,
            tl_intervention_attempts=candidate_runtime.tl_intervention_attempts,
            stage_verification=candidate_runtime.stage_verification,
        )
    integration = replace(
        state.integration,
        sub_tl_states=sub_tl_states,
        sub_tl_recovery=sub_tl_recovery,
        candidates=candidate_records,
    )
    previous_slices = state.slices
    checkpoint_phase = (
        canonical_phase
        if isinstance(
            canonical_phase,
            (RecursiveTLRunning, RecursiveTLAllMerged, RecursiveTLFinalizing),
        )
        else _phase_from_state(state)
    )
    state = store.checkpoint(
        checkpoint_phase,
        updated_slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=integration,
    )
    _emit_slice_status_changes(previous_slices, state.slices, config, effects, effects_log)
    for failure in publication_failures:
        state = _open_aggregate_publication_gate(
            state,
            failure.task_name,
            failure.detail,
            config,
            effects,
            store,
            effects_log,
            rearm=True,
        )
        _emit_aggregate_publication_failure(state, failure, config, effects, effects_log)
    for task, _, _ in outcomes:
        current = state.slices[task.name]
        if current.park_cause is not ParkCause.PUBLICATION_BLOCKED:
            gate_name = _aggregate_publication_gate_name(task.name)
            if any(gate.name == gate_name for gate in state.gates):
                state = store.clear_gate(gate_name)
    return state


def _aggregate_publication_gate_name(slice_id: str) -> str:
    """Return the stable operator gate for one aggregate publication."""
    return f"{AGGREGATE_PUBLICATION_GATE_PREFIX}{slice_id}"


def _park_aggregate_publication(
    current: SliceState,
    failure: AggregatePublicationRejected,
) -> SliceState:
    """Persist the rejection details on its owning sub-TL slice."""
    parked = (
        current
        if current.status is SliceStatus.PARKED
        else slice_transition(current, SliceStatusChanged(SliceStatus.PARKED))
    )
    return replace(
        parked,
        park_cause=ParkCause.PUBLICATION_BLOCKED,
        park_issue_id=None,
        park_audit=_aggregate_publication_audit(current, failure),
        blocked_by=None,
    )


def _aggregate_publication_audit(
    current: SliceState,
    failure: AggregatePublicationRejected,
) -> dict[str, object]:
    """Build the closed-key audit payload for one rejected publication."""
    audit = dict(current.park_audit or {})
    audit.update(
        {
            "gate_name": _aggregate_publication_gate_name(failure.task_name),
            "reason": failure.detail,
            "error": failure.detail,
            "error_kind": failure.error_kind or "unknown",
            "needs_human": failure.needs_human,
            "retryable": failure.retryable,
            "missing_evidence": list(failure.missing_evidence),
            "publication_attempt": failure.attempt,
            "publication_approval_consumed": False,
        }
    )
    return audit


def _open_aggregate_publication_gate(
    state: RunState,
    slice_id: str,
    reason: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    *,
    rearm: bool = False,
) -> RunState:
    """Create or re-arm a pending gate without overwriting an operator rejection."""
    gate_name = _aggregate_publication_gate_name(slice_id)
    existing = next((gate for gate in state.gates if gate.name == gate_name), None)
    if existing is not None and not (rearm and existing.status is GateStatus.APPROVED):
        return state
    state = store.set_gate(gate_name, GateStatus.PENDING)
    _emit_aggregate_gate_opened(state, gate_name, reason, config, effects, effects_log)
    return state


def _emit_aggregate_gate_opened(
    state: RunState,
    gate_name: str,
    reason: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    """Publish the open boundary for one aggregate publication gate."""
    _record_controller_event(
        "controller",
        "tl.gate_opened",
        {"gate_name": gate_name, "run_id": state.run_id, "reason": reason},
        config,
        effects,
        effects_log,
    )


def _emit_aggregate_publication_failure(
    state: RunState,
    failure: AggregatePublicationRejected,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    """Record a slice-scoped startup reconciliation failure for operators."""
    kind = (failure.error_kind or "unknown").strip().lower().replace("-", "_")
    _record_controller_event(
        "controller",
        "tl.transition_invariant_failed",
        {
            "run_id": state.run_id,
            "target_id": "controller",
            "state_version": state.state_version,
            "invariant": f"aggregate_publication:{failure.task_name}:{kind}",
            "action_key": (
                f"{state.run_id}:{failure.task_name}:aggregate-publication:{failure.attempt}"
            ),
        },
        config,
        effects,
        effects_log,
    )


def _reconcile_aggregate_publication_gates(
    tasks: Sequence[SubTLTask],
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    post_merge_verified: dict[str, bool],
) -> RunState:
    """Repair missing gates and resume only operator-approved publications."""
    state = store.load()
    for task in tasks:
        state, verified = _reconcile_aggregate_publication_gate(
            task, state, config, effects, store, effects_log
        )
        if _post_merge_recovery_started(state.slices.get(task.name)):
            post_merge_verified[task.name] = verified
    return state


def _post_merge_recovery_started(current: SliceState | None) -> bool:
    """Whether this slice already crossed the durable remote-merge boundary."""
    return (
        current is not None
        and current.post_merge is not None
        and current.post_merge.phase
        not in {PostMergePhase.NOT_STARTED, PostMergePhase.NOT_REQUIRED}
    )


def _post_merge_recovery_pending(current: SliceState) -> bool:
    """Whether a merged slice still has required local post-merge work."""
    return (
        _post_merge_recovery_started(current)
        and current.post_merge is not None
        and (current.post_merge.phase is not PostMergePhase.COMPLETE)
    )


def _verified_aggregate_post_merge(
    task: SubTLTask,
    state: RunState,
    current: SliceState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> tuple[bool, str]:
    """Verify the saved aggregate merge against its exact durable or live identity."""
    receipt = current.post_merge
    if receipt is None or not _post_merge_recovery_started(current):
        return False, "post_merge_receipt_missing"
    candidate = state.integration.candidates.get(task.name)
    publication = current.publication
    reconciliation = current.reconciliation
    if (
        current.status not in {SliceStatus.MERGED, SliceStatus.PARKED}
        or (
            current.status is SliceStatus.PARKED
            and current.park_cause is not ParkCause.PUBLICATION_BLOCKED
        )
        or candidate is None
        or candidate.lifecycle
        not in {IntegrationLifecycle.CHILDREN_MERGED, IntegrationLifecycle.MERGED}
        or publication is None
        or state.repository_identity is None
        or not isinstance(reconciliation, Mapping)
    ):
        return False, "aggregate_merge_checkpoint_incomplete"
    if candidate.lifecycle is IntegrationLifecycle.CHILDREN_MERGED:
        child_store = RunStore(task.name, store.run_dir)
        try:
            child_state = child_store.load()
        except (OSError, ValueError):
            return False, "aggregate_child_completion_unavailable"
        child_complete, child_reason = _aggregate_child_completion_proven(
            state, child_state, child_store, task.name
        )
        if not child_complete:
            return False, child_reason
    evidence = receipt.evidence
    pr_number = current.pr_number
    head_sha = candidate.aggregate_head_sha
    base_sha = reconciliation.get("merge_base_sha")
    merge_journal_id = evidence.get("merge_journal_id")
    parent_branch = publication.base_branch or current.base_ref
    if (
        evidence.get("child_id") != task.name
        or type(pr_number) is not int
        or pr_number <= 0
        or evidence.get("pr_number") != str(pr_number)
        or candidate.aggregate_pr_number != pr_number
        or not isinstance(head_sha, str)
        or not head_sha
        or evidence.get("head_sha") != head_sha
        or publication.pr_number != pr_number
        or publication.head_sha != head_sha
        or not current.branch
        or publication.head_branch != current.branch
        or not isinstance(parent_branch, str)
        or not parent_branch
        or evidence.get("parent_branch") != parent_branch
        or current.base_ref != parent_branch
        or evidence.get("repository") != state.repository_identity.remote_url
        or not isinstance(base_sha, str)
        or not base_sha
        or not isinstance(merge_journal_id, str)
        or not merge_journal_id
        or reconciliation.get("merge_head_sha") != head_sha
        or reconciliation.get("merge_journal_id") != merge_journal_id
    ):
        return False, "aggregate_merge_coordinates_conflict"
    journal_result = _verified_aggregate_merge_journal(
        state,
        current,
        candidate,
        pr_number,
        head_sha,
        base_sha,
        merge_journal_id,
        effects_log,
    )
    if journal_result == "verified":
        return True, "confirmed_merge_journal"
    if journal_result == "conflict":
        return False, "aggregate_merge_journal_conflict"
    if not config.active:
        return False, "aggregate_merge_journal_unavailable_for_shadow_resume"
    try:
        watcher = _watcher_snapshot(pr_number, config, effects, effects_log)
    except (ConnectionError, OSError, RuntimeError, TimeoutError, ToolUnavailableError):
        return False, "bound_pr_merge_observation_unavailable"
    if watcher is None:
        return False, "bound_pr_merge_observation_missing"
    if _aggregate_watcher_confirms_merged_pr(task, current, candidate, watcher):
        return True, "closed_merged_pr_observation"
    return False, "bound_pr_merge_observation_mismatched"


def _promote_candidate_after_verified_merge(
    integration: IntegrationRuntimeState,
    candidate_id: str,
) -> IntegrationRuntimeState:
    """Record a proof-backed merge repair without widening normal FSM edges.

    A publication failure can leave the candidate at CHILDREN_MERGED after the
    remote merge receipt was durably recorded.  This repair is only callable
    after `_verified_aggregate_post_merge` has authenticated that receipt (or
    equivalent authoritative watcher evidence); ordinary integration still
    uses the centralized transition table.
    """
    candidate = _candidate_runtime(integration, candidate_id)
    if candidate.lifecycle is IntegrationLifecycle.MERGED:
        return integration
    if candidate.lifecycle is not IntegrationLifecycle.CHILDREN_MERGED:
        raise IntegrationTransitionError(
            "verified aggregate merge repair requires a CHILDREN_MERGED candidate"
        )
    sub_tl_states = dict(integration.sub_tl_states)
    sub_tl_states[candidate_id] = IntegrationLifecycle.MERGED
    return _persist_candidate_runtime(
        replace(integration, sub_tl_states=sub_tl_states),
        candidate_id,
        replace(candidate, lifecycle=IntegrationLifecycle.MERGED),
    )


def _verified_aggregate_merge_journal(
    state: RunState,
    current: SliceState,
    candidate: IntegrationCandidateState,
    pr_number: int,
    head_sha: str,
    base_sha: str,
    merge_journal_id: str,
    effects_log: list[EffectIntent],
) -> str:
    """Classify the retained merge action without rewriting its outcome."""
    if not isinstance(effects_log, EffectJournal):
        return "unavailable"
    entry = effects_log.entry_by_key(merge_journal_id)
    if entry is None:
        return "unavailable"
    if entry.get("status") != "confirmed":
        return "unavailable" if entry.get("status") in {"intended", "unknown"} else "conflict"
    arguments = entry.get("arguments")
    result = entry.get("result")
    payload = result.get("result") if isinstance(result, Mapping) else None
    if (
        entry.get("key") != merge_journal_id
        or entry.get("run_id") != state.run_id
        or entry.get("operation") != "merge_pr"
        or entry.get("target") != current.id
        or not isinstance(arguments, Mapping)
        or not isinstance(payload, Mapping)
        or not _merge_journal_reports_success(entry)
    ):
        return "conflict"
    journal_pr = arguments.get("pr_number")
    journal_base = arguments.get("base_sha", arguments.get("expected_base_sha"))
    if journal_pr != pr_number or journal_base != base_sha:
        return "conflict"
    for field_name, expected in (
        ("expected_head_sha", head_sha),
        ("expected_patch_digest", candidate.aggregate_patch_digest),
        ("expected_merge_tree_sha", candidate.merge_tree_sha),
    ):
        observed = arguments.get(field_name)
        if observed is not None and observed != expected:
            return "conflict"
    for field_name, expected in (
        ("pr_number", pr_number),
        ("head_sha", head_sha),
        ("base_sha", base_sha),
        ("repository", state.repository_identity.remote_url if state.repository_identity else None),
        ("parent_branch", current.publication.base_branch if current.publication else None),
    ):
        observed = payload.get(field_name)
        if observed is not None and observed != expected:
            return "conflict"
    return "verified"


def _aggregate_watcher_confirms_merged_pr(
    task: SubTLTask,
    current: SliceState,
    candidate: IntegrationCandidateState,
    watcher: WatcherObservation | None,
) -> bool:
    """Require the bound PR-by-number read to prove closed merge and provenance."""
    publication = current.publication
    record = watcher.publication if watcher is not None else None
    expected_author = task.agent_id or task.name
    return (
        watcher is not None
        and publication is not None
        and record is not None
        and watcher.found is True
        and watcher.pr_number == current.pr_number
        and watcher.merged is True
        and isinstance(watcher.pr_state, str)
        and watcher.pr_state.lower() == "closed"
        and watcher.head_sha == candidate.aggregate_head_sha
        and watcher.head_branch == current.branch
        and watcher.base_branch == publication.base_branch
        and watcher.publication_ownership_verified is True
        and watcher.evidence_error is None
        and watcher.head_reachable is True
        and record.slice_id == task.name
        and record.author_agent == expected_author
        and publication.invocation_id is not None
        and record.invocation_id == publication.invocation_id
        and (
            watcher.patch_digest is None or watcher.patch_digest == candidate.aggregate_patch_digest
        )
        and (watcher.merge_tree_sha is None or watcher.merge_tree_sha == candidate.merge_tree_sha)
    )


def _record_aggregate_post_merge_hold(
    state: RunState,
    slice_id: str,
    reason: str,
    store: RunStore,
) -> RunState:
    """Persist a bounded diagnosis while retaining the original publication park."""
    current = state.slices[slice_id]
    reconciliation = dict(current.reconciliation or {})
    hold = {"reason_code": reason, "pr_number": current.pr_number}
    if reconciliation.get("aggregate_post_merge_hold") == hold:
        return state
    reconciliation["aggregate_post_merge_hold"] = hold
    return _checkpoint_slice_action(
        store,
        state,
        slice_id,
        current.action,
        slice_state=replace(current, reconciliation=reconciliation),
    )


def _adopt_aggregate_post_merge_recovery(
    task: SubTLTask,
    state: RunState,
    current: SliceState,
    gate: GateState | None,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
) -> RunState:
    """Retire the matching publication park while retaining its audit evidence."""
    assert current.post_merge is not None
    reconciliation = dict(current.reconciliation or {})
    reconciliation.pop("aggregate_post_merge_hold", None)
    reconciliation["aggregate_publication_resolution"] = {
        "resolution": "superseded_by_verified_merge",
        "pr_number": current.pr_number,
        "head_sha": current.post_merge.evidence["head_sha"],
        "merge_journal_id": current.post_merge.evidence["merge_journal_id"],
    }
    updated = current
    if current.status is SliceStatus.PARKED:
        updated = slice_transition(current, MergeCompleted(current.pr_number or 0))
    if current.park_cause is ParkCause.PUBLICATION_BLOCKED:
        updated = replace(
            updated,
            park_cause=None,
            dispatch_error=None,
            reconciliation=reconciliation,
        )
    elif updated.reconciliation != reconciliation:
        updated = replace(updated, reconciliation=reconciliation)
    promoted_integration = _promote_candidate_after_verified_merge(state.integration, task.name)
    if updated != current or promoted_integration != state.integration:
        state = _checkpoint_slice_action(
            store,
            state,
            task.name,
            updated.action,
            slice_state=updated,
            integration=promoted_integration,
        )
    if gate is not None and gate.status is GateStatus.PENDING:
        _record_controller_event(
            task.name,
            "tl.aggregate_publication_gate_superseded",
            {
                "slice_id": task.name,
                "gate_name": gate.name,
                "pr_number": current.pr_number,
                "head_sha": current.post_merge.evidence["head_sha"],
                "merge_journal_id": current.post_merge.evidence["merge_journal_id"],
                "reason": "the exact aggregate PR is already durably merged",
            },
            config,
            effects,
            effects_log,
        )
        state = store.clear_gate(gate.name)
    return state


def _reconcile_aggregate_publication_gate(
    task: SubTLTask,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> tuple[RunState, bool]:
    """Reconcile one sub-TL's publication park and approval gate."""
    current = state.slices.get(task.name)
    if current is None:
        return state, False
    gate_name = _aggregate_publication_gate_name(task.name)
    gate = next((item for item in state.gates if item.name == gate_name), None)
    if task.integration.aggregate_pr_required and _post_merge_recovery_started(current):
        verified, reason = _verified_aggregate_post_merge(
            task, state, current, config, effects, effects_log, store
        )
        if not verified:
            LOGGER.warning(
                "[TL loop] holding aggregate post-merge recovery for %s: %s",
                task.name,
                reason,
            )
            return _record_aggregate_post_merge_hold(state, task.name, reason, store), False
        state = _adopt_aggregate_post_merge_recovery(
            task, state, current, gate, config, effects, effects_log, store
        )
        return state, True
    if current.park_cause is not ParkCause.PUBLICATION_BLOCKED:
        return (store.clear_gate(gate_name) if gate is not None else state), False
    if config.active:
        recovered_state = _recover_parked_aggregate_candidate(
            task, state, config, effects, store, effects_log
        )
        if recovered_state is not None:
            state = recovered_state
            current = state.slices.get(task.name)
            if current is not None and current.park_cause is not ParkCause.PUBLICATION_BLOCKED:
                return store.clear_gate(gate_name), False
    if gate is None:
        state = _restore_aggregate_publication_gate(
            task.name, current, state, config, effects, store, effects_log
        )
        gate = next((item for item in state.gates if item.name == gate_name), None)
    if config.active and gate is not None and gate.status is GateStatus.APPROVED:
        return _retry_aggregate_publication(task, state, config, effects, store, effects_log), False
    return state, False


def _recover_parked_aggregate_candidate(
    task: SubTLTask,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState | None:
    """Adopt a watcher publication and resume a previously parked slice."""
    child_state = RunStore(task.name, store.run_dir).load()
    if not _child_handoff_ready(child_state, state.run_id):
        return None
    try:
        candidate = _ensure_aggregate_candidate(
            task, child_state, config, effects, store, effects_log, publish=False
        )
    except AggregatePublicationRejected as error:
        return _record_parked_aggregate_rejection(task, error, config, effects, store, effects_log)
    if candidate is None:
        return None
    child_state = RunStore(task.name, store.run_dir).load()
    return _complete_sub_tl_batch(
        (task,),
        ((task, _child_completion_phase(child_state), child_state),),
        state,
        config,
        effects,
        store,
        effects_log,
        prepublished_candidates={task.name: candidate},
    )


def _record_parked_aggregate_rejection(
    task: SubTLTask,
    error: AggregatePublicationRejected,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Refresh the parked reason and re-arm its approval gate after reconciliation."""
    state = store.load()
    current = state.slices.get(task.name)
    if current is None:
        return state
    parked = _park_aggregate_publication(current, error)
    state = _checkpoint_slice_action(store, state, task.name, None, slice_state=parked)
    state = _open_aggregate_publication_gate(
        state, task.name, error.detail, config, effects, store, effects_log, rearm=True
    )
    _emit_aggregate_publication_failure(state, error, config, effects, effects_log)
    return state


def _restore_aggregate_publication_gate(
    slice_id: str,
    current: SliceState,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Recreate a lost pending gate from its durable slice park."""
    return _open_aggregate_publication_gate(
        state,
        slice_id,
        _aggregate_publication_reason(current),
        config,
        effects,
        store,
        effects_log,
    )


def _aggregate_publication_reason(current: SliceState) -> str:
    """Return the persisted operator-facing reason for a parked publication."""
    reason = current.park_audit.get("reason") if current.park_audit is not None else None
    return reason if isinstance(reason, str) and reason else "aggregate publication is blocked"


def _retry_aggregate_publication(
    task: SubTLTask,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Consume one approved gate and retry its journaled publication once."""
    current = state.slices.get(task.name)
    if current is None or not _aggregate_publication_is_approved(task.name, current, state):
        return state
    if not config.active:
        return state
    claimed = _claim_aggregate_publication_approval(task.name, current, state, store)
    if claimed is None:
        return state
    state, attempt = claimed
    return _execute_aggregate_publication_retry(
        task, state, attempt, config, effects, store, effects_log
    )


def _aggregate_publication_is_approved(
    slice_id: str,
    current: SliceState,
    state: RunState,
) -> bool:
    """Check both the typed park cause and its exact durable gate answer."""
    gate = next(
        (item for item in state.gates if item.name == _aggregate_publication_gate_name(slice_id)),
        None,
    )
    return current.park_cause is ParkCause.PUBLICATION_BLOCKED and (
        gate is not None and gate.status is GateStatus.APPROVED
    )


def _claim_aggregate_publication_approval(
    slice_id: str,
    current: SliceState,
    state: RunState,
    store: RunStore,
) -> tuple[RunState, int] | None:
    """Checkpoint one approval and return its stable attempt ordinal."""
    audit = dict(current.park_audit or {})
    previous_attempt = audit.get("publication_attempt", 1)
    consumed = audit.get("publication_approval_consumed", False)
    if type(previous_attempt) is not int or previous_attempt < 1 or type(consumed) is not bool:
        return None
    if consumed:
        return state, previous_attempt
    attempt = previous_attempt + 1
    audit.update(publication_attempt=attempt, publication_approval_consumed=True)
    state = _checkpoint_slice_action(
        store, state, slice_id, None, slice_state=replace(current, park_audit=audit)
    )
    return state, attempt


def _execute_aggregate_publication_retry(
    task: SubTLTask,
    state: RunState,
    attempt: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Run the journaled retry and checkpoint its parent candidate."""
    try:
        return _publish_aggregate_retry_candidate(
            task, state, attempt, config, effects, store, effects_log
        )
    except AggregatePublicationRejected as failure:
        return _record_aggregate_publication_retry_failure(
            task.name, failure, config, effects, store, effects_log
        )


def _publish_aggregate_retry_candidate(
    task: SubTLTask,
    state: RunState,
    attempt: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Request one candidate and finish its parent checkpoint."""
    candidate = _request_aggregate_retry_candidate(
        task, attempt, config, effects, store, effects_log
    )
    if candidate is None:
        raise AggregatePublicationRejected(
            task.name,
            "aggregate publication candidate is still unavailable",
            "missing_candidate",
            attempt,
            needs_human=True,
            retryable=False,
        )
    refreshed_child = RunStore(task.name, store.run_dir).load()
    return _complete_sub_tl_batch(
        (task,),
        ((task, None, refreshed_child),),
        state,
        config,
        effects,
        store,
        effects_log,
        prepublished_candidates={task.name: candidate},
    )


def _request_aggregate_retry_candidate(
    task: SubTLTask,
    attempt: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> AggregateCandidate | None:
    """Request or replay the candidate for one approved publication attempt."""
    child_state = RunStore(task.name, store.run_dir).load()
    return _ensure_aggregate_candidate(
        task,
        child_state,
        config,
        effects,
        store,
        effects_log,
        publication_attempt=attempt,
    )


def _record_aggregate_publication_retry_failure(
    slice_id: str,
    failure: AggregatePublicationRejected,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Re-park a rejected retry and require a fresh gate approval."""
    state = store.load()
    parked = _park_aggregate_publication(state.slices[slice_id], failure)
    state = _checkpoint_slice_action(store, state, slice_id, None, slice_state=parked)
    state = _open_aggregate_publication_gate(
        state, slice_id, failure.detail, config, effects, store, effects_log, rearm=True
    )
    _emit_aggregate_publication_failure(state, failure, config, effects, effects_log)
    return state


def _ensure_aggregate_candidate(
    task: SubTLTask,
    child_state: RunState | None,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    *,
    publication_attempt: int = 1,
    publish: bool = True,
) -> AggregateCandidate | None:
    """Publish one resumable aggregate PR, reusing the child checkpoint on restart."""
    if (
        child_state is None
        or not isinstance(child_state, RunState)
        or not task.integration.aggregate_pr_required
    ):
        return None
    if not _child_has_aggregate_output(child_state):
        return None
    child_state = _migrate_aggregate_child_identity(
        task, child_state, config, store, publication_attempt
    )
    child_integration = child_state.integration
    own_candidate = child_integration.candidates.get(task.name)
    identity = _aggregate_publication_identity(
        task,
        child_state,
        own_candidate,
        config,
        store,
        publication_attempt,
    )
    candidate = _find_aggregate_candidate(
        task,
        child_state,
        own_candidate,
        identity,
        publication_attempt,
        publish,
        config,
        effects,
        store,
        effects_log,
    )
    if candidate is None:
        return None
    _validate_aggregate_candidate(task.name, candidate, publication_attempt)
    _persist_aggregate_candidate(
        task,
        child_state,
        child_integration,
        identity,
        candidate,
        config,
        effects,
        store,
        effects_log,
    )
    return candidate


def _migrate_aggregate_child_identity(
    task: SubTLTask,
    child_state: RunState,
    config: TLLoopConfig,
    store: RunStore,
    publication_attempt: int,
) -> RunState:
    """Upgrade a legacy child checkpoint before parent-owned writes touch it."""
    if child_state.version != LEGACY_IDENTITY_CHECKPOINT_VERSION:
        return child_state
    identity = config.repository_identity
    if identity is None:
        raise _aggregate_reconciliation_rejected(
            task.name,
            "repository_identity_missing",
            publication_attempt,
            ("selected_repository_url",),
            retryable=True,
        )
    child_store = RunStore(task.name, store.run_dir)
    evidence_children = (
        _repository_identity_sub_tl_names(child_state, child_store)
        if child_state.repository_identity is None
        else ()
    )
    try:
        return child_store.migrate_repository_identity(
            identity,
            corroborating_sub_tls=evidence_children,
        )
    except RepositoryIdentityMigrationError as error:
        reason = (
            "repository_identity_mismatch"
            if error.code == "conflicting"
            else f"repository_identity_{error.code}"
        )
        raise _aggregate_reconciliation_rejected(
            task.name,
            reason,
            publication_attempt,
            ("child_repository_identity",),
            retryable=error.code in {"missing", "unavailable", "stale"},
        ) from error


def _aggregate_publication_identity(
    task: SubTLTask,
    child_state: RunState,
    own_candidate: IntegrationCandidateState | None,
    config: TLLoopConfig,
    store: RunStore,
    publication_attempt: int,
) -> _AggregatePublicationIdentity:
    """Resolve the branch, agent, and invocation that own the publication."""
    branch = child_state.owner_branch or derive_child_branch(
        config.branch, _child_controller_name(task)
    )
    owner_agent = task.agent_id or task.name
    owner_worktree = child_state.owner_worktree or str(
        _sub_tl_worktree(config, store.root_dir, store.run_id, task)
    )
    parent_slice = store.load().slices.get(task.name)
    parent_slice, invocation_id, resume_invocation = _registered_aggregate_invocation(
        task,
        parent_slice,
        branch,
        owner_agent,
        owner_worktree,
        config,
        store,
        publication_attempt,
    )
    return _AggregatePublicationIdentity(
        owner_id=(own_candidate.integration_owner_id if own_candidate else None)
        or f"{store.run_id}:{task.name}:integration",
        branch=branch,
        owner_worktree=owner_worktree,
        owner_agent=owner_agent,
        parent_slice=parent_slice,
        invocation_id=invocation_id,
        resume_invocation=resume_invocation,
    )


def _registered_aggregate_invocation(
    task: SubTLTask,
    parent_slice: SliceState | None,
    branch: str,
    owner_agent: str,
    owner_worktree: str,
    config: TLLoopConfig,
    store: RunStore,
    publication_attempt: int,
) -> tuple[SliceState | None, str | None, Mapping[str, object] | None]:
    """Rehydrate an invocation when possible and reject unsafe publication."""
    invocation_id = parent_slice.dispatch_invocation_id if parent_slice is not None else None
    if config.project_root is not None and not invocation_id:
        invocation_id = _rehydrate_aggregate_invocation(
            task, owner_agent, branch, owner_worktree, config.project_root, store
        )
        parent_slice = store.load().slices.get(task.name)
        invocation_id = parent_slice.dispatch_invocation_id if parent_slice else None
    if config.project_root is None:
        return parent_slice, invocation_id, None
    durable = _durable_sub_tl_invocation_matches(
        config.project_root, owner_agent, task.name, branch, invocation_id, owner_worktree
    )
    if not durable:
        record = _read_durable_sub_tl_invocation(config.project_root, owner_agent)
        if _authorized_aggregate_resume(record, task.name, branch, owner_worktree, invocation_id):
            return parent_slice, invocation_id, record
        raise AggregatePublicationRejected(
            task.name,
            "aggregate publication stopped before file_pr: the sub-TL invocation record is "
            "missing or does not match its persisted slice and branch identity",
            "missing_invocation_registration",
            publication_attempt,
            needs_human=True,
            retryable=False,
            missing_evidence=("invocation_id", "slice_id", "head_branch"),
        )
    return parent_slice, invocation_id, None


def _rehydrate_aggregate_invocation(
    task: SubTLTask,
    owner_agent: str,
    branch: str,
    owner_worktree: str,
    project_root: str | Path,
    store: RunStore,
) -> str | None:
    """Checkpoint a matching host invocation record into the parent slice."""
    record = _read_durable_sub_tl_invocation(project_root, owner_agent)
    invocation_id = record.get("invocation_id") if record else None
    if not (
        isinstance(invocation_id, str)
        and record.get("slice_id") == task.name
        and record.get("branch") == branch
        and record.get("worktree") == owner_worktree
        and record.get("prior_invocation_id") is None
        and record.get("trigger") != "resume_pr"
    ):
        return None
    try:
        _checkpoint_ordered_sub_tl_invocation(store, task.name, invocation_id)
    except TLLoopError:
        return None
    return invocation_id


def _find_aggregate_candidate(
    task: SubTLTask,
    child_state: RunState,
    own_candidate: IntegrationCandidateState | None,
    identity: _AggregatePublicationIdentity,
    publication_attempt: int,
    publish: bool,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> AggregateCandidate | None:
    """Reuse durable evidence, observe the watcher, then publish if needed."""
    candidate = _aggregate_candidate_from_watcher(
        task,
        identity.parent_slice,
        identity.branch,
        identity.owner_agent,
        identity.invocation_id,
        config,
        effects,
        effects_log,
        store,
        publication_attempt,
        identity.owner_worktree,
        identity.resume_invocation,
    )
    if own_candidate is not None and own_candidate.aggregate_pr_number is not None:
        return _reuse_verified_aggregate_candidate(
            task, own_candidate, candidate, publication_attempt
        )
    if candidate is not None or not publish:
        return candidate
    _require_safe_aggregate_creation(task, identity, config, effects_log, publication_attempt)
    return _request_aggregate_candidate(
        task, child_state, identity, publication_attempt, config, effects, store, effects_log
    )


def _reuse_verified_aggregate_candidate(
    task: SubTLTask,
    persisted: IntegrationCandidateState,
    observed: AggregateCandidate | None,
    publication_attempt: int,
) -> AggregateCandidate:
    """Require fresh watcher ownership to agree with a saved aggregate PR number."""
    if observed is None:
        reason = "persisted_candidate_not_found"
        missing = ("authoritative_publication",)
    elif observed.pr_number != persisted.aggregate_pr_number:
        reason = "persisted_candidate_mismatch"
        missing = ("persisted_pr_number", "observed_pr_number")
    else:
        return observed
    raise _aggregate_publication_failure(
        task.name,
        f"aggregate publication recovery refused: reason_code={reason}",
        reason,
        publication_attempt,
        missing,
    )


def _require_safe_aggregate_creation(
    task: SubTLTask,
    identity: _AggregatePublicationIdentity,
    config: TLLoopConfig,
    effects_log: list[EffectIntent],
    publication_attempt: int,
) -> None:
    """Allow file_pr only when authority proves no PR and no prior attempt is ambiguous."""
    if identity.resume_invocation is not None or (
        identity.parent_slice is not None and identity.parent_slice.pr_number is not None
    ):
        raise _aggregate_reconciliation_rejected(
            task.name,
            "existing_publication_not_found",
            publication_attempt,
            ("authoritative_publication",),
            retryable=False,
        )
    if _aggregate_file_pr_effect_is_unresolved(task, config, effects_log):
        raise _aggregate_reconciliation_rejected(
            task.name,
            "prior_file_pr_outcome_unresolved",
            publication_attempt,
            ("prior_file_pr_outcome", "authoritative_publication"),
            retryable=False,
        )


def _aggregate_file_pr_effect_is_unresolved(
    task: SubTLTask,
    config: TLLoopConfig,
    effects_log: list[EffectIntent],
) -> bool:
    """Prevent a second external PR creation after an ambiguous prior attempt."""
    title = _aggregate_pr_title(task.name, config.branch)
    if isinstance(effects_log, EffectJournal):
        records = effects_log.snapshot()
        return any(
            record.get("operation") == "file_pr"
            and record.get("target") == task.name
            and isinstance(record.get("arguments"), Mapping)
            and record["arguments"].get("title") == title
            and record["arguments"].get("base_branch") == config.branch
            and record.get("status") in {"intended", "unknown", "confirmed", "reconciled"}
            for record in records
        )
    return any(
        intent.operation == "file_pr"
        and intent.target == task.name
        and intent.arguments.get("title") == title
        and intent.arguments.get("base_branch") == config.branch
        for intent in effects_log
    )


def _request_aggregate_candidate(
    task: SubTLTask,
    child_state: RunState,
    identity: _AggregatePublicationIdentity,
    publication_attempt: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> AggregateCandidate:
    """Build and publish one sub-TL aggregate candidate."""
    title = _aggregate_pr_title(task.name, config.branch)
    body = _aggregate_publication_body(task, child_state, identity, config, store)
    arguments = {
        "title": title,
        "base_branch": config.branch,
        "publication_attempt": publication_attempt,
        "publication_identity": {
            "slice_id": task.name,
            "invocation_id": identity.invocation_id,
            "author_agent": identity.owner_agent,
            "head_branch": identity.branch,
            "base_branch": config.branch,
        },
    }
    return _publish_aggregate_candidate(
        task,
        title,
        body,
        identity,
        arguments,
        publication_attempt,
        config,
        effects,
        store,
        effects_log,
    )


def _aggregate_publication_body(
    task: SubTLTask,
    child_state: RunState,
    identity: _AggregatePublicationIdentity,
    config: TLLoopConfig,
    store: RunStore,
) -> str:
    """Format the credential-free aggregate PR description."""
    child_store = RunStore(task.name, store.run_dir)
    return _aggregate_pr_body(
        task.name,
        config.branch,
        identity.owner_id,
        _child_head_sha(child_state, identity.branch),
        _child_patch_digest(child_state),
        _aggregate_leaf_provenance(child_state, child_store),
    )


def _aggregate_leaf_provenance(
    state: RunState,
    store: RunStore,
) -> tuple[_LeafIssueProvenance, ...]:
    """Collect issue and PR references from leaf changes represented in this branch."""
    references: list[_LeafIssueProvenance] = []
    _collect_aggregate_leaf_provenance(state, store, references)
    return tuple(
        sorted(
            set(references),
            key=lambda ref: (
                ref.issue_id is None,
                ref.issue_id or 0,
                ref.pr_number is None,
                ref.pr_number or 0,
            ),
        )
    )


def _collect_aggregate_leaf_provenance(
    state: RunState,
    store: RunStore,
    references: list[_LeafIssueProvenance],
) -> None:
    """Walk nested sub-TLs and collect leaves that published or merged their changes."""
    if state.plan_manifest is None:
        return
    for node in state.plan_manifest.nodes:
        if node.kind == "leaf":
            _collect_leaf_slice_provenance(state, node, references)
        elif node.kind == "sub_tl":
            _collect_nested_leaf_provenance(state, store, node, references)


def _collect_leaf_slice_provenance(
    state: RunState,
    node: ManifestNode,
    references: list[_LeafIssueProvenance],
) -> None:
    """Add references from one leaf that published or merged its change."""
    current = state.slices.get(node.name)
    if current is None or current.status not in {SliceStatus.IN_REVIEW, SliceStatus.MERGED}:
        return
    issue_id = node.chainlink_issue_id or current.chainlink_issue_id
    pr_number = current.pr_number
    if issue_id is not None or pr_number is not None:
        references.append(_LeafIssueProvenance(issue_id, pr_number))


def _collect_nested_leaf_provenance(
    state: RunState,
    store: RunStore,
    node: ManifestNode,
    references: list[_LeafIssueProvenance],
) -> None:
    """Recurse into a completed nested sub-TL branch."""
    current = state.slices.get(node.name)
    if current is None or current.status is not SliceStatus.MERGED:
        return
    child_manifest = state.plan_manifest.child_manifests.get(node.node_id)
    if child_manifest is None:
        return
    child_store = RunStore(node.name, store.run_dir)
    if not child_store.path.exists():
        _collect_manifest_leaf_issue_ids(child_manifest, references)
        return
    _collect_aggregate_leaf_provenance(child_store.load(), child_store, references)


def _collect_manifest_leaf_issue_ids(
    manifest: PlanManifest,
    references: list[_LeafIssueProvenance],
) -> None:
    """Retain declared leaf issue IDs when a completed nested state is absent."""
    for node in manifest.nodes:
        if node.kind == "leaf" and node.chainlink_issue_id is not None:
            references.append(_LeafIssueProvenance(node.chainlink_issue_id, None))
        if node.kind == "sub_tl":
            child = manifest.child_manifests.get(node.node_id)
            if child is not None:
                _collect_manifest_leaf_issue_ids(child, references)


def _aggregate_pr_title(task_name: str, base_branch: str) -> str:
    """Create a single-line title from the supplied aggregate identifiers."""
    return _single_line_public_text(f"Aggregate {task_name} into {base_branch}")


def _aggregate_pr_body(
    task_name: str,
    base_branch: str,
    owner_id: str,
    head_sha: str,
    patch_digest: str,
    references: Sequence[_LeafIssueProvenance],
) -> str:
    """Render escaped aggregate metadata and non-closing leaf references."""
    lines = [
        (
            f"Aggregate sub-TL {_markdown_code_span(task_name)} into "
            f"{_markdown_code_span(base_branch)}."
        ),
        f"Owner: {_markdown_code_span(owner_id)}",
        f"Head: {_markdown_code_span(head_sha)}",
        f"Patch: {_markdown_code_span(patch_digest)}",
    ]
    reference_lines = _aggregate_reference_lines(references)
    if reference_lines:
        lines.extend(("", "Leaf issue references:", *reference_lines))
    return "\n".join(lines)


def _aggregate_reference_lines(
    references: Sequence[_LeafIssueProvenance],
) -> tuple[str, ...]:
    """Render stable, non-closing issue and PR references for included leaves."""
    lines: list[str] = []
    ordered = sorted(
        set(references),
        key=lambda ref: (
            ref.issue_id is None,
            ref.issue_id or 0,
            ref.pr_number is None,
            ref.pr_number or 0,
        ),
    )
    for reference in ordered:
        parts: list[str] = []
        if reference.issue_id is not None:
            parts.append(f"Refs #{reference.issue_id}")
        if reference.pr_number is not None:
            parts.append(f"Related PR: #{reference.pr_number}")
        if parts:
            lines.append(f"- {' · '.join(parts)}")
    return tuple(lines)


def _markdown_code_span(value: str) -> str:
    """Wrap supplied text in a code span that cannot be closed by embedded ticks."""
    normalized = _single_line_public_text(value)
    fence = "`" * (_longest_backtick_run(normalized) + 1)
    padding = " " if normalized.startswith("`") or normalized.endswith("`") else ""
    return f"{fence}{padding}{normalized}{padding}{fence}"


def _longest_backtick_run(value: str) -> int:
    """Return the longest consecutive backtick run in one supplied value."""
    longest = current = 0
    for character in value:
        if character == "`":
            current += 1
            longest = max(longest, current)
        else:
            current = 0
    return longest


def _single_line_public_text(value: str) -> str:
    """Remove control characters and collapse whitespace before PR rendering."""
    printable = "".join(character if character.isprintable() else " " for character in value)
    return " ".join(printable.split())


def _validate_aggregate_candidate(
    task_name: str,
    candidate: AggregateCandidate,
    publication_attempt: int,
) -> None:
    """Reject aggregate evidence before it can enter the parent checkpoint."""
    if all(
        (
            candidate.pr_number > 0,
            candidate.head_sha,
            candidate.patch_digest,
            candidate.original_base_sha,
        )
    ):
        return
    raise AggregatePublicationRejected(
        task_name,
        "aggregate publication candidate is missing authoritative PR evidence",
        "incomplete_evidence",
        publication_attempt,
        needs_human=False,
        retryable=True,
        missing_evidence=("pr_number", "head_sha", "base_sha", "patch_digest"),
    )


def _persist_aggregate_candidate(
    task: SubTLTask,
    child_state: RunState,
    child_integration: IntegrationRuntimeState,
    identity: _AggregatePublicationIdentity,
    candidate: AggregateCandidate,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> None:
    """Persist verified publication evidence in the child handoff checkpoint."""
    updated_integration = replace(
        child_integration,
        lifecycle=IntegrationLifecycle.AGGREGATE_PR_OPEN,
        aggregate_pr_number=candidate.pr_number,
        aggregate_head_sha=candidate.head_sha,
        aggregate_patch_digest=candidate.patch_digest,
        aggregate_original_base_sha=candidate.original_base_sha,
        integration_owner_id=identity.owner_id,
        integration_owner_run_id=task.name,
        integration_owner_branch=identity.branch,
        integration_owner_worktree=identity.owner_worktree,
        head_sha=candidate.head_sha,
        patch_digest=candidate.patch_digest,
    )
    child_store = RunStore(task.name, store.run_dir)
    updated_child_state = child_store.set_ordered_state(
        child_state.current_order, child_state.ordered_stages, updated_integration
    )
    _persist_non_root_handoff(
        updated_child_state,
        child_store,
        updated_integration,
        candidate,
        parent_branch=config.branch,
    )
    if child_integration.aggregate_pr_number is None:
        _record_aggregate_open_event(task, candidate, identity, config, effects, effects_log)


def _record_aggregate_open_event(
    task: SubTLTask,
    candidate: AggregateCandidate,
    identity: _AggregatePublicationIdentity,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    """Record the verified aggregate publication without sensitive fields."""
    _record_controller_event(
        task.name,
        "tl.aggregate_pr_opened",
        {
            "sub_tl_id": task.name,
            "pr_number": candidate.pr_number,
            "head_sha": candidate.head_sha,
            "patch_digest": candidate.patch_digest,
            "original_base_sha": candidate.original_base_sha,
            "integration_owner_id": identity.owner_id,
        },
        config,
        effects,
        effects_log,
    )


def _durable_sub_tl_invocation_matches(
    project_root: str | Path,
    owner_agent: str,
    slice_id: str,
    branch: str,
    invocation_id: str | None,
    worktree: str,
) -> bool:
    """Require the exact server-owned invocation record before publication."""
    record = _read_durable_sub_tl_invocation(project_root, owner_agent)
    return bool(
        invocation_id
        and record is not None
        and record.get("invocation_id") == invocation_id
        and record.get("slice_id") == slice_id
        and record.get("branch") == branch
        and record.get("worktree") == worktree
    )


def _authorized_aggregate_resume(
    record: Mapping[str, object] | None,
    slice_id: str,
    branch: str,
    worktree: str,
    prior_invocation_id: str | None,
) -> bool:
    """Recognize a durable same-owner resume without checkpointing it yet."""
    if record is None or not prior_invocation_id:
        return False
    return _aggregate_resume_record_matches(record, slice_id, branch, worktree, prior_invocation_id)


def _aggregate_resume_record_matches(
    record: Mapping[str, object],
    slice_id: str,
    branch: str,
    worktree: str,
    prior_invocation_id: str,
) -> bool:
    """Validate durable resume coordinates before watcher correlation."""
    invocation_id = record.get("invocation_id")
    prior = record.get("prior_invocation_id")
    return bool(
        isinstance(invocation_id, str)
        and invocation_id
        and invocation_id != prior_invocation_id
        and record.get("trigger") == "resume_pr"
        and isinstance(prior, str)
        and prior
        and record.get("slice_id") == slice_id
        and record.get("branch") == branch
        and record.get("worktree") == worktree
        and _aggregate_resume_pr_coordinates_present(record)
    )


def _aggregate_resume_pr_coordinates_present(record: Mapping[str, object]) -> bool:
    """Require a resume record anchored to a concrete existing PR head."""
    return bool(
        type(record.get("pr_number")) is int
        and record.get("pr_number", 0) > 0
        and isinstance(record.get("head_sha"), str)
        and record.get("head_sha")
    )


def _read_durable_sub_tl_invocation(
    project_root: str | Path,
    owner_agent: str,
) -> Mapping[str, object] | None:
    """Read the exact invocation file consumed by the host file_pr handler."""
    path = Path(project_root) / ".exo" / "agents" / owner_agent / "invocation.json"
    try:
        record = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return None
    return record if isinstance(record, Mapping) else None


def _aggregate_candidate_from_watcher(
    task: SubTLTask,
    parent_slice: SliceState | None,
    branch: str,
    owner_agent: str,
    invocation_id: str | None,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
    publication_attempt: int,
    owner_worktree: str,
    resume_invocation: Mapping[str, object] | None,
) -> AggregateCandidate | None:
    """Adopt an aggregate PR only when watcher identity and evidence are complete."""
    if parent_slice is None:
        raise _aggregate_reconciliation_rejected(
            task.name,
            "parent_slice_missing",
            publication_attempt,
            ("parent_slice",),
            retryable=False,
        )
    _validate_aggregate_repository_identity(
        task.name, config, effects, effects_log, store, publication_attempt
    )
    observation = _resolve_aggregate_watcher_observation(
        task.name, config, effects, effects_log, publication_attempt
    )
    if observation is None:
        return None
    binding = _validate_aggregate_watcher_identity(
        task,
        parent_slice,
        observation,
        branch,
        owner_agent,
        invocation_id,
        config.branch,
        publication_attempt,
        owner_worktree,
        resume_invocation,
    )
    _checkpoint_aggregate_resume(
        task, resume_invocation, invocation_id, observation, store, publication_attempt
    )
    return _aggregate_candidate_from_observation(
        task.name, observation, binding, publication_attempt
    )


def _checkpoint_aggregate_resume(
    task: SubTLTask,
    resume_invocation: Mapping[str, object] | None,
    prior_invocation_id: str | None,
    observation: WatcherObservation,
    store: RunStore,
    publication_attempt: int,
) -> None:
    """Persist a verified resume before storing its PR binding."""
    if resume_invocation is None:
        return
    resumed_id = cast(str, resume_invocation.get("invocation_id"))
    LOGGER.info(
        "[TL loop] adopting authorized aggregate resume: slice=%s prior_invocation_id=%s resumed_invocation_id=%s pr_number=%s",
        task.name,
        prior_invocation_id,
        resumed_id,
        observation.pr_number,
    )
    try:
        _checkpoint_ordered_sub_tl_invocation(store, task.name, resumed_id)
        _assert_aggregate_resume_checkpoint(store, task.name, resumed_id)
    except (TLLoopError, DurableWriteError, CheckpointConflict) as error:
        _raise_resume_checkpoint_rejection(task.name, publication_attempt, error)


def _assert_aggregate_resume_checkpoint(
    store: RunStore,
    slice_id: str,
    invocation_id: str,
) -> None:
    """Fail closed if the lineage checkpoint did not take effect."""
    current = store.load().slices.get(slice_id)
    if current is None or current.dispatch_invocation_id != invocation_id:
        raise TLLoopError("aggregate resume invocation checkpoint did not persist")


def _raise_resume_checkpoint_rejection(
    slice_id: str,
    publication_attempt: int,
    error: Exception,
) -> None:
    """Convert durable resume checkpoint errors into a safe retryable park."""
    LOGGER.warning(
        "[TL loop] aggregate resume lineage checkpoint deferred: slice=%s error_type=%s",
        slice_id,
        type(error).__name__,
    )
    raise _aggregate_reconciliation_rejected(
        slice_id,
        "resume_lineage_checkpoint_failed",
        publication_attempt,
        ("durable_invocation_lineage",),
        retryable=True,
    ) from error


def _aggregate_candidate_from_observation(
    slice_id: str,
    observation: WatcherObservation,
    binding: PublicationBinding,
    publication_attempt: int,
) -> AggregateCandidate:
    """Project the verified current PR evidence into a candidate."""
    if binding.pr_number != observation.pr_number or binding.head_sha != observation.head_sha:
        raise _aggregate_reconciliation_rejected(
            slice_id,
            "publication_binding_observation_mismatch",
            publication_attempt,
            ("pr_number", "head_sha"),
            retryable=False,
        )
    return AggregateCandidate(
        slice_id,
        binding.pr_number,
        binding.head_sha,
        cast(str, observation.patch_digest),
        cast(str, observation.base_sha),
    )


def _resolve_aggregate_watcher_observation(
    slice_id: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    publication_attempt: int,
) -> WatcherObservation | None:
    """Return an observation, only using ``None`` for authoritative absence."""
    result = _call_aggregate_publication_lookup(
        slice_id, config, effects, effects_log, publication_attempt
    )
    lookup = _decode_aggregate_publication_lookup(slice_id, result, publication_attempt)
    if lookup is None:
        return None
    return _read_aggregate_pr_observation(
        slice_id, lookup, config, effects, effects_log, publication_attempt
    )


def _call_aggregate_publication_lookup(
    slice_id: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    publication_attempt: int,
) -> ToolResult | None:
    """Query host publication identity and convert transport failures safely."""
    try:
        return _invoke(
            "resolve_live_pr_for_slice",
            f"slice:{slice_id}",
            {"slice_id": slice_id},
            config.active,
            cast(EffectClient, effects),
            lambda client: client.resolve_live_pr_for_slice(slice_id=slice_id),
            effects_log,
            raise_on_failure=False,
        )
    except TLLoopError:
        raise
    except (ConnectionError, OSError, RuntimeError, TimeoutError, ToolUnavailableError) as error:
        LOGGER.warning(
            "[TL loop] aggregate publication lookup unavailable: slice=%s error_type=%s",
            slice_id,
            type(error).__name__,
        )
        _raise_aggregate_lookup_unavailable(slice_id, publication_attempt, error)


def _raise_aggregate_lookup_unavailable(
    slice_id: str,
    publication_attempt: int,
    error: Exception | None = None,
) -> None:
    """Record an actionable unavailable lookup without copying tool error text."""
    failure = _aggregate_reconciliation_rejected(
        slice_id,
        "publication_lookup_unavailable",
        publication_attempt,
        ("authoritative_publication_lookup",),
        retryable=True,
    )
    if error is not None:
        raise failure from error
    raise failure


def _decode_aggregate_publication_lookup(
    slice_id: str,
    result: ToolResult | None,
    publication_attempt: int,
) -> _AggregatePublicationLookup | None:
    """Distinguish a never-published slice from unresolved host responses."""
    if result is None or result.success is not True or not isinstance(result.result, Mapping):
        _raise_aggregate_lookup_unavailable(slice_id, publication_attempt)
    resolution = result.result.get("resolution")
    if result.result.get("slice_id") != slice_id:
        raise _aggregate_reconciliation_rejected(
            slice_id,
            "publication_lookup_slice_mismatch",
            publication_attempt,
            ("slice_id",),
            retryable=False,
        )
    if resolution == "never_published":
        return None
    if resolution != "live":
        raise _aggregate_reconciliation_rejected(
            slice_id,
            "publication_lookup_unresolved",
            publication_attempt,
            ("unique_live_publication",),
            retryable=False,
        )
    return _aggregate_lookup_coordinates(slice_id, result.result, publication_attempt)


def _aggregate_lookup_coordinates(
    slice_id: str,
    result: Mapping[str, object],
    publication_attempt: int,
) -> _AggregatePublicationLookup:
    """Require a unique PR number and its durable publication record."""
    pr_number = result.get("pr_number")
    publication = result.get("publication")
    if type(pr_number) is not int or pr_number <= 0 or not isinstance(publication, Mapping):
        raise _aggregate_reconciliation_rejected(
            slice_id,
            "publication_lookup_malformed",
            publication_attempt,
            ("pr_number", "publication_record"),
            retryable=False,
        )
    return _AggregatePublicationLookup(pr_number, publication)


def _read_aggregate_pr_observation(
    slice_id: str,
    lookup: _AggregatePublicationLookup,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    publication_attempt: int,
) -> WatcherObservation:
    """Read fresh Forgejo facts for the one host-resolved PR."""
    snapshot = _call_aggregate_watcher(
        slice_id, lookup.pr_number, config, effects, effects_log, publication_attempt
    )
    observation = WatcherObservation.from_response(snapshot).with_publication(lookup.publication)
    if observation.pr_number != lookup.pr_number or observation.found is not True:
        raise _aggregate_reconciliation_rejected(
            slice_id,
            "watcher_pr_mismatch",
            publication_attempt,
            ("pr_number", "found"),
            retryable=False,
        )
    return observation


def _call_aggregate_watcher(
    slice_id: str,
    pr_number: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    publication_attempt: int,
) -> Mapping[str, object]:
    """Fetch fresh PR state, parking on unavailable or malformed responses."""
    try:
        snapshot = _invoke(
            "watcher_pr_state",
            str(pr_number),
            {"pr_number": pr_number},
            config.active,
            cast(EffectClient, effects),
            lambda client: client.watcher_pr_state(pr_number=pr_number),
            effects_log,
            raise_on_failure=False,
        )
    except TLLoopError:
        raise
    except (ConnectionError, OSError, RuntimeError, TimeoutError, ToolUnavailableError) as error:
        LOGGER.warning(
            "[TL loop] aggregate watcher unavailable: slice=%s pr_number=%s error_type=%s",
            slice_id,
            pr_number,
            type(error).__name__,
        )
        _raise_aggregate_watcher_unavailable(slice_id, pr_number, publication_attempt, error)
    if snapshot is None or snapshot.success is not True or not isinstance(snapshot.result, Mapping):
        _raise_aggregate_watcher_unavailable(slice_id, pr_number, publication_attempt)
    return snapshot.result


def _raise_aggregate_watcher_unavailable(
    slice_id: str,
    pr_number: int,
    publication_attempt: int,
    error: Exception | None = None,
) -> None:
    """Record an actionable watcher failure without copying raw error text."""
    failure = _aggregate_reconciliation_rejected(
        slice_id,
        "watcher_observation_unavailable",
        publication_attempt,
        ("current_pr_head", "base_sha", "patch_digest"),
        retryable=True,
    )
    if error is not None:
        raise failure from error
    raise failure


def _validate_aggregate_repository_identity(
    slice_id: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    store: RunStore,
    publication_attempt: int,
) -> None:
    """Refuse watcher adoption when the host repository differs from the run."""
    state = store.load()
    observed, failure_code = _resolve_repository_identity_detail(config, effects, effects_log)
    if observed is None:
        raise _aggregate_reconciliation_rejected(
            slice_id,
            f"repository_identity_{failure_code or 'unavailable'}",
            publication_attempt,
            ("authoritative_repository_identity",),
            retryable=failure_code in {"missing", "unavailable", "timeout"},
        )
    if config.repository_identity is not None and config.repository_identity != observed:
        raise _aggregate_reconciliation_rejected(
            slice_id,
            "repository_identity_mismatch",
            publication_attempt,
            ("repository_identity",),
            retryable=False,
        )
    evidence_children = (
        _repository_identity_sub_tl_names(state, store) if state.repository_identity is None else ()
    )
    try:
        state = store.migrate_repository_identity(
            observed,
            corroborating_sub_tls=evidence_children,
        )
    except RepositoryIdentityMigrationError as error:
        reason = (
            "repository_identity_mismatch"
            if error.code == "conflicting"
            else f"repository_identity_{error.code}"
        )
        raise _aggregate_reconciliation_rejected(
            slice_id,
            reason,
            publication_attempt,
            ("repository_identity_migration",),
            retryable=error.code in {"missing", "unavailable", "stale"},
        ) from error
    if not _aggregate_repository_matches(state.repository_identity, config, observed):
        raise _aggregate_reconciliation_rejected(
            slice_id,
            "repository_identity_mismatch",
            publication_attempt,
            ("repository_identity",),
            retryable=False,
        )


def _aggregate_repository_matches(
    persisted: RepositoryIdentity | None,
    config: TLLoopConfig,
    observed: RepositoryIdentity,
) -> bool:
    """Compare only the canonical repository URL across runtime and state."""
    return bool(
        persisted is not None
        and observed == persisted
        and (config.repository_identity is None or config.repository_identity == persisted)
    )


def _validate_aggregate_watcher_identity(
    task: SubTLTask,
    parent_slice: SliceState,
    observation: WatcherObservation,
    branch: str,
    owner_agent: str,
    invocation_id: str | None,
    base_branch: str,
    publication_attempt: int,
    owner_worktree: str,
    resume_invocation: Mapping[str, object] | None,
) -> PublicationBinding:
    """Validate exact coordinates and lineage before allowing invocation adoption."""
    _require_aggregate_watcher_evidence(task.name, observation, publication_attempt)
    publication = observation.publication
    _require_aggregate_publication_coordinates(
        task, observation, publication, branch, owner_agent, base_branch, publication_attempt
    )
    if resume_invocation is None:
        return _validate_existing_aggregate_lineage(
            task, parent_slice, observation, owner_agent, invocation_id, publication_attempt
        )
    return _validate_resumed_aggregate_lineage(
        task,
        parent_slice,
        observation,
        publication,
        branch,
        owner_agent,
        invocation_id,
        owner_worktree,
        resume_invocation,
        publication_attempt,
    )


def _require_aggregate_watcher_evidence(
    slice_id: str,
    observation: WatcherObservation,
    publication_attempt: int,
) -> None:
    """Require verified ownership and complete current-head evidence."""
    if observation.ownership_status()[0] is not True:
        raise _aggregate_reconciliation_rejected(
            slice_id,
            "publication_ownership_unverified",
            publication_attempt,
            ("publication_ownership",),
            retryable=False,
        )
    missing = _aggregate_missing_publication_evidence(observation)
    if missing:
        raise _aggregate_reconciliation_rejected(
            slice_id,
            "publication_evidence_incomplete",
            publication_attempt,
            missing,
            retryable=True,
        )


def _require_aggregate_publication_coordinates(
    task: SubTLTask,
    observation: WatcherObservation,
    publication: PublicationRecord | None,
    branch: str,
    owner_agent: str,
    base_branch: str,
    publication_attempt: int,
) -> None:
    """Refuse a live PR whose immutable coordinates differ from its plan."""
    if publication is not None and _aggregate_publication_coordinates_match(
        task, observation, publication, branch, owner_agent, base_branch
    ):
        return
    raise _aggregate_reconciliation_rejected(
        task.name,
        "publication_coordinates_mismatch",
        publication_attempt,
        ("pr_number", "head_branch", "base_branch", "slice_id", "author_agent"),
        retryable=False,
    )


def _validate_resumed_aggregate_lineage(
    task: SubTLTask,
    parent_slice: SliceState,
    observation: WatcherObservation,
    publication: PublicationRecord | None,
    branch: str,
    owner_agent: str,
    prior_invocation_id: str | None,
    owner_worktree: str,
    resume_invocation: Mapping[str, object],
    publication_attempt: int,
) -> PublicationBinding:
    """Accept a fresh resume only when host lineage ties it to this existing PR."""
    if not _aggregate_resume_publication_matches(
        task.name,
        observation,
        publication,
        branch,
        owner_worktree,
        prior_invocation_id,
        resume_invocation,
    ):
        raise _aggregate_reconciliation_rejected(
            task.name,
            "publication_resume_identity_mismatch",
            publication_attempt,
            ("invocation_id", "pr_number"),
            retryable=False,
        )
    resumed_id = cast(str, resume_invocation.get("invocation_id"))
    resumed_slice = replace(parent_slice, dispatch_invocation_id=resumed_id)
    return _validated_aggregate_binding(
        task.name,
        resumed_slice,
        observation,
        owner_agent,
        publication_attempt,
        "publication_resume_rejected",
    )


def _aggregate_resume_publication_matches(
    slice_id: str,
    observation: WatcherObservation,
    publication: PublicationRecord | None,
    branch: str,
    owner_worktree: str,
    prior_invocation_id: str | None,
    resume_invocation: Mapping[str, object],
) -> bool:
    """Match the resumed invocation to the same PR and prior owner lineage."""
    return bool(
        publication is not None
        and _authorized_aggregate_resume(
            resume_invocation, slice_id, branch, owner_worktree, prior_invocation_id
        )
        and publication.invocation_id == resume_invocation.get("invocation_id")
        and resume_invocation.get("pr_number") == observation.pr_number
        and (
            resume_invocation.get("prior_invocation_id") == prior_invocation_id
            or prior_invocation_id in publication.succession_invocation_ids
        )
    )


def _validate_existing_aggregate_lineage(
    task: SubTLTask,
    parent_slice: SliceState,
    observation: WatcherObservation,
    owner_agent: str,
    invocation_id: str | None,
    publication_attempt: int,
) -> PublicationBinding:
    """Validate an existing invocation or its host-recorded succession."""
    binding = _validated_aggregate_binding(
        task.name,
        parent_slice,
        observation,
        owner_agent,
        publication_attempt,
        "publication_lineage_rejected",
    )
    if not _aggregate_invocation_matches(
        cast(PublicationRecord, observation.publication), invocation_id
    ):
        raise _aggregate_reconciliation_rejected(
            task.name,
            "publication_lineage_rejected:invocation_lineage_mismatch",
            publication_attempt,
            ("invocation_lineage",),
            retryable=False,
        )
    return binding


def _validated_aggregate_binding(
    slice_id: str,
    current: SliceState,
    observation: WatcherObservation,
    owner_agent: str,
    publication_attempt: int,
    rejection_prefix: str,
) -> PublicationBinding:
    """Use the shared validator and turn refusals into stable aggregate park reasons."""
    validation = validate_publication_from_watcher(
        current, observation, observation.head_sha, owner_agent
    )
    if validation.binding is not None:
        return validation.binding
    rejection_code = validation.rejection.reason_code if validation.rejection else "unknown"
    raise _aggregate_reconciliation_rejected(
        slice_id,
        f"{rejection_prefix}:{rejection_code}",
        publication_attempt,
        ("invocation_lineage",),
        retryable=False,
    )


def _aggregate_watcher_identity_matches(
    task: SubTLTask,
    parent_slice: SliceState,
    observation: WatcherObservation,
    branch: str,
    owner_agent: str,
    invocation_id: str | None,
    base_branch: str,
) -> bool:
    """Compatibility predicate for tests of the non-resume identity contract."""
    publication = observation.publication
    if publication is None or observation.ownership_status()[0] is not True:
        return False
    if not _aggregate_invocation_matches(publication, invocation_id):
        return False
    if _aggregate_missing_publication_evidence(observation):
        return False
    validation = validate_publication_from_watcher(
        parent_slice, observation, observation.head_sha, owner_agent
    )
    return bool(
        validation.binding is not None
        and _aggregate_publication_coordinates_match(
            task, observation, publication, branch, owner_agent, base_branch
        )
    )


def _aggregate_missing_publication_evidence(
    observation: WatcherObservation,
) -> tuple[str, ...]:
    """Name absent current-head publication evidence without exposing tool errors."""
    fields = {
        "pr_number": observation.pr_number,
        "head_sha": observation.head_sha,
        "base_sha": observation.base_sha,
        "patch_digest": observation.patch_digest,
        "head_branch": observation.head_branch,
        "base_branch": observation.base_branch,
        "publication": observation.publication,
    }
    missing = [name for name, value in fields.items() if value is None or value == ""]
    if observation.head_reachable is not True:
        missing.append("head_reachable")
    return tuple(missing)


def _aggregate_reconciliation_rejected(
    slice_id: str,
    reason_code: str,
    publication_attempt: int,
    missing_evidence: Sequence[str],
    *,
    retryable: bool,
) -> AggregatePublicationRejected:
    """Build a safe, stable parked reason for unresolved aggregate ownership."""
    return AggregatePublicationRejected(
        slice_id,
        f"aggregate publication recovery parked: reason_code={reason_code}; "
        f"missing evidence: {', '.join(missing_evidence) if missing_evidence else 'none'}",
        reason_code,
        publication_attempt,
        needs_human=not retryable,
        retryable=retryable,
        missing_evidence=missing_evidence,
    )


def _aggregate_invocation_matches(
    publication: PublicationRecord,
    invocation_id: str | None,
) -> bool:
    if invocation_id is not None and (
        publication.invocation_id == invocation_id
        or invocation_id in publication.succession_invocation_ids
    ):
        return True
    LOGGER.warning(
        "[TL loop] refusing aggregate watcher publication: reason_code=%s expected_invocation_id=%s observed_invocation_id=%s succession_invocation_ids=%s",
        "aggregate_invocation_lineage_mismatch",
        invocation_id,
        publication.invocation_id,
        publication.succession_invocation_ids,
    )
    return False


def _aggregate_publication_coordinates_match(
    task: SubTLTask,
    observation: WatcherObservation,
    publication: PublicationRecord,
    branch: str,
    owner_agent: str,
    base_branch: str,
) -> bool:
    if type(observation.pr_number) is not int or observation.pr_number <= 0:
        return False
    return bool(
        observation.head_branch == branch
        and observation.base_branch == base_branch
        and publication.slice_id == task.name
        and publication.author_agent == owner_agent
    )


def _publish_aggregate_candidate(
    task: SubTLTask,
    title: str,
    body: str,
    identity: _AggregatePublicationIdentity,
    arguments: Mapping[str, object],
    publication_attempt: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> AggregateCandidate:
    """Run or replay one idempotent aggregate publication and checkpoint its evidence."""
    if not config.active:
        raise _aggregate_publication_failure(
            task.name,
            "aggregate publication was not dispatched because the loop is inactive",
            "not_dispatched",
            publication_attempt,
            ("pr_number", "head_sha", "base_sha", "patch_digest"),
        )
    intent = EffectIntent("file_pr", task.name, arguments, config.active)
    journal = effects_log if isinstance(effects_log, EffectJournal) else None
    _prepare_aggregate_file_pr_replay(intent, journal, task.name, identity, config.branch)
    owner_effects = _owner_effect_client(effects, identity.owner_agent)
    response = _invoke_aggregate_file_pr(
        task,
        title,
        body,
        arguments,
        identity,
        publication_attempt,
        config,
        cast(EffectClient | None, owner_effects),
        effects,
        store,
        effects_log,
        journal,
    )
    if isinstance(response, AggregateCandidate):
        return response
    result_data = response.result if response and isinstance(response.result, Mapping) else {}
    candidate, missing = _aggregate_candidate_from_result(
        task.name,
        result_data,
        identity.branch,
        config.branch,
        identity.owner_agent,
        identity.invocation_id,
    )
    if candidate is not None:
        result = _candidate_result(
            candidate,
            task.name,
            identity.branch,
            config.branch,
            identity.owner_agent,
            identity.invocation_id,
        )
        _resolve_aggregate_file_pr_entries(journal, task.name, title, config.branch, result)
        return candidate
    recovered = _adopt_aggregate_watcher_candidate(
        task,
        title,
        identity,
        publication_attempt,
        config,
        effects,
        store,
        effects_log,
        journal,
    )
    if recovered is not None:
        return recovered
    raise _aggregate_publication_failure(
        task.name,
        "aggregate file_pr returned incomplete or mismatched authoritative evidence; "
        f"missing evidence: {', '.join(missing) if missing else 'publication identity'}",
        "incomplete_evidence",
        publication_attempt,
        missing or ("publication_identity",),
    )


def _prepare_aggregate_file_pr_replay(
    intent: EffectIntent,
    journal: EffectJournal | None,
    task_name: str,
    identity: _AggregatePublicationIdentity,
    base_branch: str,
) -> None:
    """Mark ambiguous file_pr calls replayable after watcher reconciliation."""
    if journal is None:
        return
    probe = journal.probe(intent)
    incomplete_confirmation = probe.status == "confirmed" and not _aggregate_result_is_complete(
        probe.result,
        task_name,
        identity.branch,
        base_branch,
        identity.owner_agent,
        identity.invocation_id,
    )
    if probe.status in {"intended", "unknown"} or incomplete_confirmation:
        journal.resolve_by_key(journal.key_for(intent), status="compensated")


def _invoke_aggregate_file_pr(
    task: SubTLTask,
    title: str,
    body: str,
    arguments: Mapping[str, object],
    identity: _AggregatePublicationIdentity,
    publication_attempt: int,
    config: TLLoopConfig,
    owner_effects: EffectClient | None,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    journal: EffectJournal | None,
) -> ToolResult | AggregateCandidate | None:
    """Invoke file_pr and recover publication results at ambiguous boundaries."""

    def call_file_pr(client: EffectClient) -> ToolResult:
        return client.file_pr(title=title, body=body, base_branch=config.branch)

    try:
        result = _invoke(
            "file_pr",
            task.name,
            arguments,
            config.active,
            owner_effects,
            call_file_pr,
            effects_log,
            raise_on_failure=False,
        )
    except Exception as error:
        recovered = _adopt_aggregate_watcher_candidate(
            task,
            title,
            identity,
            publication_attempt,
            config,
            effects,
            store,
            effects_log,
            journal,
        )
        if recovered is not None:
            return recovered
        LOGGER.warning(
            "[TL loop] aggregate file_pr outcome unresolved: slice=%s error_type=%s",
            task.name,
            type(error).__name__,
        )
        raise _aggregate_reconciliation_rejected(
            task.name,
            "publication_outcome_unknown",
            publication_attempt,
            ("pr_number", "head_sha", "base_sha", "patch_digest", "invocation_id"),
            retryable=True,
        ) from error
    if result is not None and result.success is False:
        return _recover_rejected_aggregate_file_pr(
            task,
            title,
            identity,
            result,
            publication_attempt,
            config,
            effects,
            store,
            effects_log,
            journal,
        )
    return result


def _recover_rejected_aggregate_file_pr(
    task: SubTLTask,
    title: str,
    identity: _AggregatePublicationIdentity,
    result: ToolResult,
    publication_attempt: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    journal: EffectJournal | None,
) -> AggregateCandidate:
    """Adopt a completed PR or park the explicit file_pr rejection."""
    recovered = _adopt_aggregate_watcher_candidate(
        task,
        title,
        identity,
        publication_attempt,
        config,
        effects,
        store,
        effects_log,
        journal,
    )
    if recovered is not None:
        return recovered
    error_kind = result.error_kind
    normalized_kind = error_kind.strip().lower().replace("-", "_") if error_kind else ""
    missing_invocation = (
        normalized_kind in {"invalid_input", "invalidinput"}
        and "durable invocation record" in (result.error or "").lower()
    )
    needs_human = normalized_kind in {"invalid_input", "invalidinput"}
    reason = "missing_invocation_registration" if missing_invocation else "file_pr_rejected"
    safe_error_kind = (
        error_kind
        if normalized_kind in {"invalid_input", "invalidinput", "internal", "tool_unavailable"}
        else reason
    )
    raise AggregatePublicationRejected(
        task.name,
        f"aggregate publication recovery parked: reason_code={reason}",
        safe_error_kind,
        publication_attempt,
        needs_human=needs_human,
        retryable=not needs_human,
        missing_evidence=(
            ("durable_invocation_record",)
            if missing_invocation
            else ("pr_number", "head_sha", "base_sha", "patch_digest", "publication_identity")
        ),
    )


def _adopt_aggregate_watcher_candidate(
    task: SubTLTask,
    title: str,
    identity: _AggregatePublicationIdentity,
    publication_attempt: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    journal: EffectJournal | None,
) -> AggregateCandidate | None:
    """Adopt watcher evidence and resolve its matching ambiguous journal rows."""
    candidate = _aggregate_candidate_from_watcher(
        task,
        identity.parent_slice,
        identity.branch,
        identity.owner_agent,
        identity.invocation_id,
        config,
        effects,
        effects_log,
        store,
        publication_attempt,
        identity.owner_worktree,
        identity.resume_invocation,
    )
    if candidate is not None:
        result = _candidate_result(
            candidate,
            task.name,
            identity.branch,
            config.branch,
            identity.owner_agent,
            (
                cast(str, identity.resume_invocation["invocation_id"])
                if identity.resume_invocation is not None
                else identity.invocation_id
            ),
        )
        _resolve_aggregate_file_pr_entries(journal, task.name, title, config.branch, result)
    return candidate


def _aggregate_result_is_complete(
    result: ToolResult | None,
    task_name: str,
    branch: str,
    base_branch: str,
    owner_agent: str,
    invocation_id: str | None,
) -> bool:
    """Check a journal replay has all evidence and exact publication correlation."""
    if result is None or not isinstance(result.result, Mapping):
        return False
    candidate, missing = _aggregate_candidate_from_result(
        task_name, result.result, branch, base_branch, owner_agent, invocation_id
    )
    return candidate is not None and not missing


def _aggregate_candidate_from_result(
    task_name: str,
    data: Mapping[str, object],
    branch: str,
    base_branch: str,
    owner_agent: str,
    invocation_id: str | None,
) -> tuple[AggregateCandidate | None, tuple[str, ...]]:
    """Decode the authoritative FilePr evidence and its invocation correlation."""
    fields = {
        "pr_number": _positive_result_int(data, "pr_number"),
        "head_sha": _result_text(data, "head_sha"),
        "base_sha": _result_text(data, "base_sha"),
        "patch_digest": _result_text(data, "patch_digest"),
        "head_branch": _result_text(data, "head_branch"),
        "base_branch": _result_text(data, "base_branch"),
        "slice_id": _result_text(data, "slice_id"),
        "invocation_id": _result_text(data, "invocation_id"),
        "author_agent": _result_text(data, "author_agent"),
    }
    missing = tuple(key for key, value in fields.items() if value is None)
    if missing:
        return None, missing
    expected = {
        "head_branch": branch,
        "base_branch": base_branch,
        "slice_id": task_name,
        "author_agent": owner_agent,
    }
    if any(fields[key] != value for key, value in expected.items()):
        return None, ("publication_identity_mismatch",)
    if invocation_id is not None and fields["invocation_id"] != invocation_id:
        return None, ("invocation_id_mismatch",)
    return (
        AggregateCandidate(
            task_name,
            cast(int, fields["pr_number"]),
            cast(str, fields["head_sha"]),
            cast(str, fields["patch_digest"]),
            cast(str, fields["base_sha"]),
        ),
        (),
    )


def _candidate_result(
    candidate: AggregateCandidate,
    task_name: str,
    branch: str,
    base_branch: str,
    owner_agent: str,
    invocation_id: str | None,
) -> dict[str, object]:
    """Build a credential-free authoritative result from a verified candidate."""
    return {
        "pr_number": candidate.pr_number,
        "head_sha": candidate.head_sha,
        "base_sha": candidate.original_base_sha,
        "patch_digest": candidate.patch_digest,
        "head_branch": branch,
        "base_branch": base_branch,
        "slice_id": task_name,
        "author_agent": owner_agent,
        "invocation_id": invocation_id,
    }


def _resolve_aggregate_file_pr_entries(
    journal: EffectJournal | None,
    task_name: str,
    title: str,
    base_branch: str,
    result: Mapping[str, object],
) -> None:
    """Close stale ambiguous aggregate entries after publication is authoritative."""
    if journal is None:
        return
    raw = {"success": True, "result": dict(result)}
    for entry in journal.snapshot():
        arguments = entry.get("arguments")
        if (
            entry.get("operation") == "file_pr"
            and entry.get("target") == task_name
            and isinstance(arguments, Mapping)
            and arguments.get("title") == title
            and arguments.get("base_branch") == base_branch
            and entry.get("status") in {"intended", "unknown", "compensated"}
        ):
            key = entry.get("key")
            if isinstance(key, str):
                journal.resolve_by_key(key, status="confirmed", result=raw)


def _aggregate_publication_failure(
    task_name: str,
    detail: str,
    error_kind: str,
    attempt: int,
    missing_evidence: Sequence[str],
) -> AggregatePublicationRejected:
    """Build the retryable parked result for publication evidence failures."""
    return AggregatePublicationRejected(
        task_name,
        detail,
        error_kind,
        attempt,
        needs_human=False,
        retryable=True,
        missing_evidence=missing_evidence,
    )


def _integrate_stage_candidates(
    tasks: Sequence[SubTLTask],
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Serialize ready aggregate merges through the parent controller only."""
    if not config.active or _integration_gate_pending(state):
        return state
    for task in sorted(tasks, key=lambda item: item.name):
        state = _promote_aggregate_if_child_complete(
            task, state, config, effects, store, effects_log
        )
        current = state.slices[task.name]
        if _ordered_child_complete(task, current):
            continue
        if (
            current.status is SliceStatus.PARKED
            and current.park_cause is ParkCause.PUBLICATION_BLOCKED
        ):
            continue
        candidate = state.integration.candidates.get(task.name)
        if (
            current.status is not SliceStatus.IN_REVIEW
            or current.pr_number is None
            or candidate is None
            # A restart can land after validation and parent approval were
            # checkpointed but before MERGING. Re-enter the full integration
            # validator for that durable intermediate state.
            or candidate.lifecycle
            not in {
                IntegrationLifecycle.READY_FOR_INTEGRATION,
                IntegrationLifecycle.INTEGRATION_VALIDATED,
            }
        ):
            return state
        state = _integrate_one_candidate(task, state, config, effects, store, effects_log)
        if state.slices[task.name].status is not SliceStatus.MERGED:
            if _candidate_lane_blocked_by_other(state, state.slices[task.name]):
                continue
            break
    return state


def _promote_aggregate_if_child_complete(
    task: SubTLTask,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Move an adopted aggregate to integration only with exact child receipts."""
    current = state.slices.get(task.name)
    candidate_state = state.integration.candidates.get(task.name)
    candidate = _aggregate_candidate_from_state(task.name, candidate_state)
    child_store = RunStore(task.name, store.run_dir)
    if (
        current is None
        or current.pr_number is None
        or candidate_state is None
        or candidate is None
        or not child_store.path.exists()
    ):
        return state
    if candidate_state.lifecycle not in {
        IntegrationLifecycle.AGGREGATE_PR_OPEN,
        IntegrationLifecycle.CODE_REVIEWED,
        IntegrationLifecycle.NEEDS_BASE_REVALIDATION,
    }:
        return state
    child_state = child_store.load()
    watcher = _watcher_snapshot(current.pr_number, config, effects, effects_log)
    if watcher is None:
        LOGGER.warning(
            "[TL loop] aggregate readiness blocked for %s: watcher_unavailable",
            task.name,
        )
        return state
    refusal = _aggregate_publication_refusal(task, current, candidate, watcher)
    if refusal is not None:
        LOGGER.warning(
            "[TL loop] aggregate readiness blocked for %s: %s",
            task.name,
            refusal,
        )
        return state
    repository = (
        candidate_state.integration_owner_worktree or current.worktree or config.working_dir
    )
    evidence = _verified_child_completion_evidence(
        task,
        child_state,
        candidate,
        watcher=watcher,
        repository=repository,
    )
    if evidence is None:
        return state
    _record_controller_event(
        task.name,
        "tl.aggregate_completion_verified",
        {
            "slice_id": task.name,
            "child_run_id": evidence.child_run_id,
            "child_manifest_digest": evidence.child_manifest_digest,
            "aggregate_pr_number": evidence.aggregate_pr_number,
            "aggregate_head_sha": evidence.aggregate_head_sha,
            "aggregate_head_tree_sha": evidence.aggregate_head_tree_sha,
            "aggregate_base_sha": evidence.aggregate_base_sha,
            "aggregate_patch_digest": evidence.aggregate_patch_digest,
            "reviewed_leaf_ids": list(evidence.reviewed_leaf_ids),
            "lineage_commit_shas": list(evidence.lineage_commit_shas),
            "lineage_proof_digest": evidence.lineage_proof_digest,
            "receipt_digest": evidence.receipt_digest,
        },
        config,
        effects,
        effects_log,
    )
    updated_integration = _transition_candidate_runtime(
        state.integration,
        task.name,
        IntegrationTransition.CHILD_COMPLETION_VERIFIED,
        readiness_evidence=evidence,
    )
    updated_slices = dict(state.slices)
    updated_slices[task.name] = _supersede_ordered_recovery_after_proof(
        current, state.run_id, task.name, evidence, config, effects, effects_log
    )
    return store.checkpoint(
        _phase_from_state(state),
        updated_slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=updated_integration,
        expected_revision=state.revision,
    )


def _aggregate_candidate_from_state(
    slice_id: str, candidate: IntegrationCandidateState | None
) -> AggregateCandidate | None:
    if candidate is None:
        return None
    required = (
        candidate.aggregate_pr_number,
        candidate.aggregate_head_sha,
        candidate.aggregate_patch_digest,
        candidate.aggregate_original_base_sha,
    )
    if not all(required):
        return None
    return AggregateCandidate(
        slice_id,
        cast(int, candidate.aggregate_pr_number),
        cast(str, candidate.aggregate_head_sha),
        cast(str, candidate.aggregate_patch_digest),
        cast(str, candidate.aggregate_original_base_sha),
    )


def _load_child_readiness_for_watcher(
    task: SubTLTask,
    state: RunState,
    current: SliceState,
    aggregate: AggregateCandidate,
    watcher: WatcherObservation | Mapping[str, object],
    config: TLLoopConfig,
    store: RunStore,
) -> IntegrationReadinessEvidence | None:
    """Load durable child receipts and prove them against one live watcher head."""
    child_store = RunStore(task.name, store.run_dir)
    if not child_store.path.exists():
        _log_readiness_refusal(
            task.name, "child_checkpoint_missing", "child RunStore is unavailable"
        )
        return None
    try:
        child_state = child_store.load()
    except (OSError, ValueError) as error:
        _log_readiness_refusal(task.name, "child_checkpoint_unavailable", type(error).__name__)
        return None
    candidate_state = state.integration.candidates.get(task.name)
    repository = (
        (candidate_state.integration_owner_worktree if candidate_state is not None else None)
        or current.worktree
        or config.working_dir
    )
    refusal = _aggregate_publication_refusal(
        task, current, aggregate, _as_watcher_observation(watcher)
    )
    if refusal is not None:
        _log_readiness_refusal(task.name, refusal, "live watcher does not confirm the candidate")
        return None
    return _verified_child_completion_evidence(
        task,
        child_state,
        aggregate,
        watcher=watcher,
        repository=repository,
    )


def _verified_child_completion_evidence(
    task: SubTLTask,
    child_state: RunState,
    aggregate: AggregateCandidate,
    *,
    watcher: WatcherObservation | Mapping[str, object],
    repository: str | Path | None,
) -> IntegrationReadinessEvidence | None:
    """Prove completed child receipts are in the authoritative aggregate head."""
    if (
        child_state.run_id != task.name
        or child_state.plan_manifest is None
        or not _child_handoff_ready(child_state, child_state.parent_run_id or "")
        or isinstance(child_state.recursive_fsm, (RecursiveTLFailed, RecursiveTLParked))
    ):
        _log_readiness_refusal(task.name, "child_run_not_complete", "child run is not complete")
        return None
    observation = _as_watcher_observation(watcher)
    if observation is None:
        _log_readiness_refusal(task.name, "watcher_malformed", "watcher snapshot is malformed")
        return None
    if (
        observation.found is not True
        or observation.pr_number != aggregate.pr_number
        or observation.head_sha != aggregate.head_sha
        or observation.patch_digest != aggregate.patch_digest
        or observation.head_reachable is not True
        or not observation.pr_head_tree_sha
    ):
        _log_readiness_refusal(
            task.name,
            "aggregate_publication_incomplete",
            "watcher does not confirm the candidate PR, exact head, patch, reachability, and head tree",
        )
        return None
    receipts: list[Mapping[str, object]] = []
    reviewed_leaf_ids: list[str] = []
    lineage_commits: list[str] = []
    for node in child_state.plan_manifest.nodes:
        current = child_state.slices.get(node.name)
        if current is None or current.status is not SliceStatus.MERGED:
            _log_readiness_refusal(
                task.name,
                "child_slice_incomplete",
                f"planned child {node.name!r} is not durably merged",
            )
            return None
        if node.kind == "leaf" and current.pr_number is not None:
            receipt = _verified_leaf_merge_receipt(current)
            if receipt is None:
                _log_readiness_refusal(
                    task.name,
                    "child_receipt_invalid",
                    f"completed leaf {node.name!r} has invalid review, publication, or push evidence",
                )
                return None
            reviewed_leaf_ids.append(node.node_id)
            receipts.append(receipt)
            lineage_commits.extend(
                (cast(str, receipt["parent_commit_sha"]), cast(str, receipt["pushed_commit"]))
            )
        elif node.kind == "sub_tl" and node.integration_contract.get("aggregate_pr_required", True):
            nested_receipt = _verified_nested_aggregate_receipt(child_state, node.name, current)
            if nested_receipt is None:
                _log_readiness_refusal(
                    task.name,
                    "nested_aggregate_receipt_invalid",
                    f"nested aggregate {node.name!r} lacks a valid completed push receipt",
                )
                return None
            receipts.append(nested_receipt)
            lineage_commits.extend(
                (
                    cast(str, nested_receipt["parent_commit_sha"]),
                    cast(str, nested_receipt["pushed_commit"]),
                )
            )
    if not receipts:
        _log_readiness_refusal(
            task.name, "child_receipts_missing", "no completed child receipts found"
        )
        return None
    if repository is None:
        _log_readiness_refusal(
            task.name,
            "aggregate_repository_unavailable",
            "aggregate owner worktree is not recorded",
        )
        return None
    try:
        lineage = verify_aggregate_lineage(
            repository,
            aggregate.head_sha,
            observation.pr_head_tree_sha,
            tuple(lineage_commits),
        )
    except GitLineageError as error:
        _log_readiness_refusal(task.name, error.code, error.detail)
        return None
    payload = {
        "child_run_id": child_state.run_id,
        "child_manifest_digest": child_state.plan_manifest.digest,
        "receipts": receipts,
        "aggregate": {
            "pr_number": aggregate.pr_number,
            "head_sha": aggregate.head_sha,
            "base_sha": aggregate.original_base_sha,
            "patch_digest": aggregate.patch_digest,
        },
        "aggregate_head_tree_sha": lineage.aggregate_tree_sha,
        "lineage_commit_shas": sorted(set(lineage_commits)),
        "lineage_proof_digest": lineage.digest,
    }
    digest = hashlib.sha256(
        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    return IntegrationReadinessEvidence(
        child_run_id=child_state.run_id,
        child_manifest_digest=child_state.plan_manifest.digest,
        aggregate_pr_number=aggregate.pr_number,
        aggregate_head_sha=aggregate.head_sha,
        aggregate_base_sha=aggregate.original_base_sha,
        aggregate_patch_digest=aggregate.patch_digest,
        aggregate_head_tree_sha=lineage.aggregate_tree_sha,
        reviewed_leaf_ids=tuple(sorted(reviewed_leaf_ids)),
        lineage_commit_shas=tuple(sorted(set(lineage_commits))),
        lineage_proof_digest=lineage.digest,
        receipt_digest=digest,
    )


def _log_readiness_refusal(slice_id: str, code: str, detail: str) -> None:
    LOGGER.warning(
        "[TL loop] aggregate readiness blocked for %s: %s: %s",
        slice_id,
        code,
        detail,
    )


def _aggregate_publication_refusal(
    task: SubTLTask,
    current: SliceState,
    aggregate: AggregateCandidate,
    watcher: WatcherObservation | Mapping[str, object] | None,
) -> str | None:
    """Require one exact, reachable watcher publication before readiness."""
    watcher = _as_watcher_observation(watcher)
    if watcher is None:
        return "watcher_malformed"
    owner_id = task.agent_id or task.name
    if _watcher_publication_refused(current, watcher, owner_id):
        validation = validate_publication_from_watcher(
            current,
            watcher,
            watcher.head_sha,
            owner_id,
        )
        rejection = validation.rejection
        reason = rejection.reason_code if rejection is not None else "unknown"
        expected = dict(rejection.expected) if rejection is not None else {}
        observed = dict(rejection.observed) if rejection is not None else {}
        return f"publication_provenance_mismatch:{reason} expected={expected} observed={observed}"
    if _watcher_publication_ownership_unresolved(watcher):
        return "publication_ownership_unresolved"
    if watcher.found is not True:
        return "aggregate_publication_not_found"
    if watcher.pr_number != aggregate.pr_number:
        return "aggregate_pr_number_mismatch"
    if watcher.head_sha != aggregate.head_sha:
        return "aggregate_head_sha_mismatch"
    if watcher.patch_digest != aggregate.patch_digest:
        return "aggregate_patch_digest_mismatch"
    if watcher.head_branch != current.branch:
        return "aggregate_head_branch_mismatch"
    if watcher.base_branch != current.base_ref:
        return "aggregate_base_branch_mismatch"
    if watcher.head_reachable is not True:
        return "aggregate_head_unreachable"
    if not watcher.pr_head_tree_sha:
        return "aggregate_head_tree_missing"
    if watcher.evidence_error:
        return "aggregate_publication_evidence_error"
    return None


def _verified_leaf_merge_receipt(current: SliceState) -> Mapping[str, object] | None:
    publication = current.publication
    handoff = current.handoff
    post_merge = current.post_merge
    if (
        publication is None
        or handoff is None
        or post_merge is None
        or post_merge.phase is not PostMergePhase.COMPLETE
        or current.pr_number != publication.pr_number
        or current.reviewed_head != publication.head_sha
        or current.dispatch_agent_id is None
        or handoff.agent_id != current.dispatch_agent_id
        or handoff.pr_number != publication.pr_number
        or handoff.head_sha != publication.head_sha
        or handoff.invocation_id != publication.invocation_id
    ):
        return None
    receipt = post_merge.evidence
    if (
        receipt.get("pr_number") not in {str(publication.pr_number), publication.pr_number}
        or receipt.get("head_sha") != publication.head_sha
        or receipt.get("parent_branch") != publication.base_branch
        or not receipt.get("merge_journal_id")
    ):
        return None
    push_errors: list[str] = []
    _validate_completed_push_receipt(current, receipt, push_errors)
    if push_errors:
        return None
    patch_digest = current.review_patch_digests.get(publication.head_sha)
    try:
        verify_review(current, publication.head_sha, current_patch_digest=patch_digest)
    except ReviewGateError:
        return None
    return {
        "slice_id": current.manifest_node_id or current.id,
        "pr_number": publication.pr_number,
        "head_sha": publication.head_sha,
        "patch_digest": patch_digest,
        "publication_invocation_id": publication.invocation_id,
        "handoff_invocation_id": handoff.invocation_id,
        "merge_journal_id": receipt.get("merge_journal_id"),
        "parent_commit_sha": receipt.get("parent_commit_sha"),
        "pushed_commit": receipt.get("pushed_commit"),
        "bookkeeping_commit": receipt.get("bookkeeping_commit") or receipt.get("pushed_commit"),
        "observed_remote_head": receipt.get("observed_remote_head"),
        "post_merge_receipt": hashlib.sha256(
            json.dumps(dict(receipt), sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest(),
    }


def _verified_nested_aggregate_receipt(
    state: RunState,
    slice_id: str,
    current: SliceState,
) -> Mapping[str, object] | None:
    candidate = state.integration.candidates.get(slice_id)
    receipt = current.post_merge.evidence if current.post_merge is not None else None
    if (
        candidate is None
        or candidate.lifecycle is not IntegrationLifecycle.MERGED
        or candidate.aggregate_pr_number != current.pr_number
        or current.status is not SliceStatus.MERGED
        or current.post_merge is None
        or current.post_merge.phase is not PostMergePhase.COMPLETE
        or not receipt
        or not receipt.get("head_sha")
        or receipt.get("pr_number") not in {str(current.pr_number), current.pr_number}
        or not receipt.get("parent_commit_sha")
    ):
        return None
    push_errors: list[str] = []
    _validate_completed_push_receipt(current, receipt, push_errors)
    if push_errors:
        return None
    return {
        "slice_id": current.manifest_node_id or current.id,
        "pr_number": current.pr_number,
        "head_sha": receipt.get("head_sha"),
        "parent_commit_sha": receipt.get("parent_commit_sha"),
        "pushed_commit": receipt.get("pushed_commit"),
        "bookkeeping_commit": receipt.get("bookkeeping_commit") or receipt.get("pushed_commit"),
        "observed_remote_head": receipt.get("observed_remote_head"),
        "nested_integration_lifecycle": candidate.lifecycle.value,
    }


def _ordered_recovery_is_superseded(current: SliceState, owner_run_id: str, slice_id: str) -> bool:
    recovery = current.recovery
    return (
        recovery is not None
        and recovery.cause == BlockCause.ORDERED_CHILD_PANE_EXITED.value
        and recovery.owner_run_id == owner_run_id
        and recovery.owner_agent_id == current.dispatch_agent_id
        and recovery.evidence.get("slice_id") == slice_id
        and recovery.evidence.get("authorization_source") == "human"
        and recovery.evidence.get("invocation_id") == current.dispatch_invocation_id
        and recovery.invocation_generation == current.dispatch_generation
    )


def _supersede_ordered_recovery_after_proof(
    current: SliceState,
    owner_run_id: str,
    slice_id: str,
    evidence: IntegrationReadinessEvidence,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> SliceState:
    """Clear an ordered pane recovery only after aggregate readiness is proven."""
    if not _ordered_recovery_is_superseded(current, owner_run_id, slice_id):
        return current
    recovery = current.recovery
    assert recovery is not None
    _record_controller_event(
        slice_id,
        "tl.ordered_recovery_superseded",
        {
            "slice_id": slice_id,
            "cause": recovery.cause,
            "invocation_id": recovery.evidence.get("invocation_id"),
            "generation": recovery.invocation_generation,
            "aggregate_pr_number": evidence.aggregate_pr_number,
            "aggregate_head_sha": evidence.aggregate_head_sha,
            "receipt_digest": evidence.receipt_digest,
        },
        config,
        effects,
        effects_log,
    )
    return replace(current, recovery=None)


def _candidate_lane_key(state: RunState, current: SliceState) -> tuple[str, str]:
    """Resolve the durable lane identity for one aggregate candidate."""
    return _repository_identity(state), _publication_parent_branch_from_slice(current)


def _candidate_lane_blocked_by_other(state: RunState, current: SliceState) -> bool:
    """Report whether another child currently owns this integration lane."""
    try:
        repository, parent_branch = _candidate_lane_key(state, current)
    except ValueError:
        return False
    lane = state.integration.lanes.get(f"{repository}:{parent_branch}")
    return lane is not None and lane.phase is not LanePhase.IDLE and lane.child_id != current.id


def _abandon_owned_lane_integration(
    state: RunState,
    current: SliceState,
    integration: IntegrationRuntimeState,
    cause: str,
    diagnostic: str,
) -> IntegrationRuntimeState:
    """Abandon an owned lane when a deterministic failure opens a durable gate."""
    try:
        repository, parent_branch = _candidate_lane_key(state, current)
    except ValueError:
        return integration
    key = f"{repository}:{parent_branch}"
    lane = integration.lanes.get(key)
    if lane is None or lane.child_id != current.id:
        return integration
    if lane.phase is LanePhase.IDLE:
        return integration
    abandoned = transition_lane(lane, LaneAbandoned(cause, diagnostic[:500]))
    return replace(integration, lanes={**integration.lanes, key: abandoned})


def _recover_owned_lane_integration(
    state: RunState,
    current: SliceState,
    integration: IntegrationRuntimeState,
    diagnostic: str,
) -> IntegrationRuntimeState:
    """Keep an uncertain effect lane owned until an operator resolves it."""
    try:
        repository, parent_branch = _candidate_lane_key(state, current)
    except ValueError:
        return integration
    key = f"{repository}:{parent_branch}"
    lane = integration.lanes.get(key)
    if lane is None or lane.child_id != current.id:
        return integration
    if lane.phase in {LanePhase.IDLE, LanePhase.RECOVERY, LanePhase.PARKED}:
        return integration
    recovered = transition_lane(lane, LaneRecoveryRequested(diagnostic[:500]))
    return replace(integration, lanes={**integration.lanes, key: recovered})


def _resolve_recovered_lane_integration(
    state: RunState,
    current: SliceState,
    merge_evidence: Mapping[str, object] | None = None,
) -> IntegrationRuntimeState:
    """Resolve a lost merge response once the watcher proves the merge."""
    try:
        repository, parent_branch = _candidate_lane_key(state, current)
    except ValueError:
        return state.integration
    key = f"{repository}:{parent_branch}"
    lane = state.integration.lanes.get(key)
    if lane is None or lane.child_id != current.id or lane.phase is not LanePhase.RECOVERY:
        return state.integration
    if current.post_merge is None:
        raise ValueError("merged slice has no post-merge evidence")
    evidence = merge_evidence or current.post_merge.evidence
    head_sha = _required_merge_identity(evidence, ("head_sha",), "recovered merge head SHA")
    resolved = transition_lane(lane, LaneRecoveryResolved(current.id, head_sha))
    return replace(state.integration, lanes={**state.integration.lanes, key: resolved})


def _reconcile_legacy_parked_lanes(
    state: RunState,
    store: RunStore,
    effects_log: list[EffectIntent] | None = None,
) -> RunState:
    """Move legacy parked resources into explicit, recoverable ownership."""
    for lane in tuple(state.integration.lanes.values()):
        if lane.phase is not LanePhase.PARKED:
            continue
        current = state.slices.get(lane.child_id or "")
        if not _legacy_parked_lane_needs_recovery(current, effects_log):
            state = store.transition_lane(
                lane.repository,
                lane.parent_branch,
                LaneAbandoned(
                    "legacy_parked_failure",
                    "legacy parked lane has no ambiguous merge effect to recover",
                ),
            )
            continue
        state = store.transition_lane(
            lane.repository,
            lane.parent_branch,
            LaneRecoveryRequested("legacy parked lane requires authoritative reconciliation"),
        )
    return state


def _legacy_parked_lane_needs_recovery(
    current: SliceState | None,
    effects_log: list[EffectIntent] | None,
) -> bool:
    """Keep only ambiguous legacy merge attempts behind recovery."""
    if (
        current is not None
        and current.action is not None
        and current.action.kind is ActionKind.MERGE
        and current.action.phase
        in {
            ActionPhase.INTENDED,
            ActionPhase.IN_FLIGHT,
            ActionPhase.UNKNOWN,
        }
    ):
        return True
    if not isinstance(effects_log, EffectJournal) or current is None:
        return False
    return any(
        entry.get("operation") == "merge_pr" and entry.get("target") == current.id
        for entry in effects_log.pending_entries()
    )


def _ensure_candidate_lane(
    state: RunState,
    current: SliceState,
    expected_base_sha: str,
    store: RunStore,
) -> tuple[RunState, bool]:
    """Atomically reserve a parent lane, preserving cross-controller races."""
    try:
        repository, parent_branch = _candidate_lane_key(state, current)
    except ValueError:
        return state, False
    key = f"{repository}:{parent_branch}"
    lane = state.integration.lanes.get(key)
    if lane is not None:
        if lane.phase is LanePhase.PARKED:
            if lane.child_id is None:
                try:
                    return (
                        store.transition_lane(
                            repository,
                            parent_branch,
                            LaneAbandoned(
                                "legacy_parked_without_owner",
                                "parked lane had no durable owner",
                            ),
                        ),
                        False,
                    )
                except ValueError:
                    return store.load(), False
            try:
                return (
                    store.transition_lane(
                        repository,
                        parent_branch,
                        LaneRecoveryRequested(
                            "legacy parked lane requires authoritative reconciliation"
                        ),
                    ),
                    False,
                )
            except ValueError:
                return store.load(), False
        if lane.phase in {
            LanePhase.RESERVED,
            LanePhase.INTEGRATING,
            LanePhase.BOOKKEEPING,
            LanePhase.RECOVERY,
        }:
            return (state, lane.child_id == current.id)
        next_epoch = lane.last_lane_epoch + 1
    else:
        next_epoch = 1
    try:
        return (
            store.transition_lane(
                repository,
                parent_branch,
                LaneReserved(current.id, next_epoch, expected_base_sha),
            ),
            True,
        )
    except ValueError:
        return store.load(), False


def _start_candidate_lane(
    state: RunState,
    current: SliceState,
    head_sha: str,
    store: RunStore,
) -> tuple[RunState, bool]:
    """Durably move a reservation into compare-bound integration."""
    try:
        repository, parent_branch = _candidate_lane_key(state, current)
    except ValueError:
        return state, False
    lane = state.integration.lanes.get(f"{repository}:{parent_branch}")
    if lane is None or lane.child_id != current.id:
        return state, False
    if lane.phase is LanePhase.INTEGRATING:
        return state, lane.head_sha == head_sha
    if lane.phase is not LanePhase.RESERVED:
        return state, False
    try:
        return (
            store.transition_lane(
                repository,
                parent_branch,
                LaneIntegrationStarted(current.id, head_sha),
            ),
            True,
        )
    except ValueError:
        return store.load(), False


def _ensure_bookkeeping_lane(
    state: RunState,
    current: SliceState,
    evidence: Mapping[str, object],
    store: RunStore,
    *,
    push_intent_id: str | None = None,
    push_journal_id: str | None = None,
) -> tuple[RunState, bool]:
    """Backfill a lane for a pre-lane checkpoint before pushing bookkeeping."""
    try:
        expected_base_sha = _required_current_base(current)
    except ValueError:
        expected_base_sha = _required_merge_identity(
            evidence, ("expected_base_sha",), "push base SHA"
        )
    state, ready = _ensure_candidate_lane(state, current, expected_base_sha, store)
    if not ready:
        return state, False
    repository, parent_branch = _candidate_lane_key(state, current)
    lane = state.integration.lanes[f"{repository}:{parent_branch}"]
    if lane.phase is LanePhase.RECOVERY:
        head_sha = _required_merge_identity(evidence, ("head_sha",), "merged head SHA")
        state = store.transition_lane(
            repository,
            parent_branch,
            LaneRecoveryResolved(current.id, head_sha),
        )
        lane = state.integration.lanes[f"{repository}:{parent_branch}"]
    lane_epoch = _required_int(evidence, "lane_epoch", "lane epoch")
    if lane.lane_epoch is None or lane.lane_epoch < lane_epoch:
        return state, False
    if lane.phase is LanePhase.RESERVED:
        state, ready = _start_candidate_lane(
            state,
            current,
            _required_merge_identity(evidence, ("head_sha",), "merged head SHA"),
            store,
        )
        if not ready:
            return state, False
        lane = state.integration.lanes[f"{repository}:{parent_branch}"]
    if lane.phase is LanePhase.INTEGRATING:
        event = LaneBookkeepingStarted(
            current.id,
            _required_merge_identity(evidence, ("merge_journal_id",), "merge journal"),
            push_intent_id
            or _required_merge_identity(evidence, ("parent_push_intent_id",), "push intent"),
            push_journal_id
            or _required_merge_identity(evidence, ("push_journal_id",), "push journal"),
            _required_merge_identity(evidence, ("changelog_commit_sha",), "changelog commit"),
            expected_base_sha,
        )
        state = store.transition_lane(repository, parent_branch, event)
    return state, state.integration.lanes[
        f"{repository}:{parent_branch}"
    ].phase is LanePhase.BOOKKEEPING


def _required_bookkeeping_lane_epoch(state: RunState, current: SliceState) -> int:
    """Return the epoch of the lane that owns this child's bookkeeping push."""
    repository, parent_branch = _candidate_lane_key(state, current)
    lane = state.integration.lanes.get(f"{repository}:{parent_branch}")
    if (
        lane is None
        or lane.child_id != current.id
        or lane.phase is not LanePhase.BOOKKEEPING
        or type(lane.lane_epoch) is not int
        or lane.lane_epoch <= 0
    ):
        raise ValueError("bookkeeping lane epoch is unavailable")
    return lane.lane_epoch


def _merge_result_is_authoritative(result: ToolResult | None) -> bool:
    """Accept the typed merge response's successful operation outcome."""
    payload = _merge_result_payload(result)
    return payload is not None and (payload.get("merged") is True or payload.get("success") is True)


def _merge_failure_classification(result: ToolResult | None) -> str | None:
    if result is None or not _merge_effect_failed(result):
        return None
    values = [result.error or ""]
    if isinstance(result.result, Mapping):
        for key in ("classification", "reason", "message", "error"):
            value = result.result.get(key)
            if isinstance(value, str):
                values.append(value)
        nested = result.result.get("result")
        if isinstance(nested, Mapping):
            for key in ("classification", "reason", "message", "error"):
                value = nested.get(key)
                if isinstance(value, str):
                    values.append(value)
    text = " ".join(values).lower()
    if "conflict" in text:
        return "conflict"
    if any(
        marker in text
        for marker in (
            "stale",
            "compare-and-swap",
            "compare_and_swap",
            "cas",
            "base changed",
            "head changed",
        )
    ):
        return "base_changed"
    return "failure"


def _merge_failure_reason(result: ToolResult | None) -> str:
    if result is None:
        return "merge result was not returned"
    if result.error:
        return result.error[:500]
    if isinstance(result.result, Mapping):
        for key in ("reason", "message", "error"):
            value = result.result.get(key)
            if isinstance(value, str) and value:
                return value[:500]
        nested = result.result.get("result")
        if isinstance(nested, Mapping):
            for key in ("reason", "message", "error"):
                value = nested.get(key)
                if isinstance(value, str) and value:
                    return value[:500]
    return "merge_pr returned failure"


def _watcher_evidence_text(result: ToolResult, key: str) -> str | None:
    """Read one non-empty compare field from a watcher response."""
    observation = _watcher_result_observation(result)
    if observation is None:
        return None
    value = getattr(observation, key, None)
    return value if isinstance(value, str) and value else None


def _watcher_result_observation(result: ToolResult | None) -> WatcherObservation | None:
    if result is None or result.success is not True or not isinstance(result.result, Mapping):
        return None
    return WatcherObservation.from_response(result.result)


def _integration_gate_pending(state: RunState) -> bool:
    return any(
        gate.name
        in {
            INTEGRATION_REVALIDATION_GATE_NAME,
            INTEGRATION_CONFLICT_GATE_NAME,
            INTEGRATION_FAILURE_GATE_NAME,
        }
        and gate.status is GateStatus.PENDING
        for gate in state.gates
    )


def _open_integration_gate(
    task: SubTLTask | str,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    *,
    gate_name: str,
    lifecycle: IntegrationLifecycle,
    reason: str,
) -> RunState:
    slice_id = task if isinstance(task, str) else task.name
    current = state.slices[slice_id]
    candidate_runtime = _candidate_runtime(state.integration, slice_id)
    transitioned = state.integration
    if candidate_runtime.lifecycle is not lifecycle:
        transition = {
            IntegrationLifecycle.NEEDS_BASE_REVALIDATION: IntegrationTransition.BASE_INVALIDATED,
            IntegrationLifecycle.INTEGRATION_CONFLICT: IntegrationTransition.INTEGRATION_CONFLICT,
        }.get(lifecycle)
        if transition is None:
            raise TLLoopError(f"unsupported integration gate lifecycle {lifecycle.value!r}")
        transitioned = _transition_candidate_runtime(state.integration, slice_id, transition)
        candidate_runtime = _candidate_runtime(transitioned, slice_id)
    updated = slice_transition(current, SliceStatusChanged(SliceStatus.IN_REVIEW))
    updated = slice_transition(updated, ActionChanged(None))
    updated = replace(
        updated,
        dispatch_last_boundary="integration_gate",
        dispatch_error=reason[:500],
    )
    previous = next((gate for gate in state.gates if gate.name == gate_name), None)
    candidate_runtime = replace(
        candidate_runtime,
        lifecycle=lifecycle,
        validated_base_sha=None,
        merge_tree_sha=None,
        integration_evidence_at=None,
        ci_status="unknown",
        stage_verification="failed",
        head_sha=(
            None
            if lifecycle is IntegrationLifecycle.INTEGRATION_CONFLICT
            else candidate_runtime.head_sha
        ),
        patch_digest=(
            None
            if lifecycle is IntegrationLifecycle.INTEGRATION_CONFLICT
            else candidate_runtime.patch_digest
        ),
    )
    sub_states = {**transitioned.sub_tl_states, slice_id: lifecycle}
    integration = _persist_candidate_runtime(
        replace(transitioned, sub_tl_states=sub_states), slice_id, candidate_runtime
    )
    integration = _abandon_owned_lane_integration(
        state, updated, integration, "integration_gate", reason
    )
    state = store.checkpoint(
        _phase_from_state(state),
        {**state.slices, slice_id: updated},
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=integration,
    )
    state = store.set_gate(gate_name, GateStatus.PENDING)
    if previous is None or previous.status is not GateStatus.PENDING:
        _record_controller_event(
            "controller",
            "tl.gate_opened",
            {"gate_name": gate_name, "run_id": store.run_id, "reason": reason[:500]},
            config,
            effects,
            effects_log,
        )
    return state


def _handle_external_base_change(
    task: SubTLTask,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    *,
    base_sha: str,
    head_sha: str,
    patch_digest: str,
    reason: str,
) -> RunState:
    _record_controller_event(
        task.name,
        "tl.integration_base_invalidated",
        {
            "slice_id": task.name,
            "base_sha": base_sha,
            "head_sha": head_sha,
            "reason": reason[:500],
        },
        config,
        effects,
        effects_log,
    )
    candidate_runtime = _candidate_runtime(state.integration, task.name)
    if candidate_runtime.base_revalidation_count >= config.max_base_revalidations:
        return _open_integration_gate(
            task,
            state,
            config,
            effects,
            store,
            effects_log,
            gate_name=INTEGRATION_REVALIDATION_GATE_NAME,
            lifecycle=IntegrationLifecycle.NEEDS_BASE_REVALIDATION,
            reason=reason,
        )
    invalidated = invalidate_integration_evidence(
        candidate_runtime,
        base_sha="",
        head_sha=head_sha,
        patch_digest=patch_digest,
    )
    invalidated = replace(
        invalidated,
        lifecycle=_transition_sub_tl_lifecycle(
            candidate_runtime.lifecycle, IntegrationTransition.BASE_INVALIDATED
        ),
    )
    current = state.slices[task.name]
    return _checkpoint_integration_retry(
        state,
        task.name,
        invalidated,
        config,
        store,
        slice_update=replace(
            slice_transition(current, ActionChanged(None)),
            dispatch_last_boundary="base_revalidation",
            dispatch_error=reason[:500],
        ),
    )


def _handle_integration_revalidation(
    task: SubTLTask,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    *,
    base_sha: str,
    head_sha: str,
    patch_digest: str,
    reason: str,
) -> RunState:
    """Clear non-review integration evidence without misclassifying a base change."""
    _record_controller_event(
        task.name,
        "tl.integration_evidence_invalidated",
        {
            "slice_id": task.name,
            "base_sha": base_sha,
            "head_sha": head_sha,
            "reason": reason[:500],
        },
        config,
        effects,
        effects_log,
    )
    candidate_runtime = _candidate_runtime(state.integration, task.name)
    lifecycle = _transition_sub_tl_lifecycle(
        candidate_runtime.lifecycle, IntegrationTransition.BASE_INVALIDATED
    )
    invalidated = replace(
        candidate_runtime,
        lifecycle=lifecycle,
        validated_base_sha=None,
        merge_tree_sha=None,
        ci_status="unknown",
        stage_verification="pending",
        integration_evidence_at=None,
    )
    current = state.slices[task.name]
    return _checkpoint_integration_retry(
        state,
        task.name,
        invalidated,
        config,
        store,
        slice_update=replace(
            slice_transition(current, ActionChanged(None)),
            dispatch_last_boundary="integration_revalidation",
            dispatch_error=reason[:500],
        ),
    )


def _handle_integration_conflict(
    task: SubTLTask,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    *,
    base_sha: str,
    head_sha: str,
    reason: str,
) -> RunState:
    return _judge_integration_failure(
        task.name,
        state,
        config,
        effects,
        store,
        effects_log,
        failure_kind="parent_merge_conflict",
        reason=reason,
        gate_name=INTEGRATION_CONFLICT_GATE_NAME,
        base_sha=base_sha,
        head_sha=head_sha,
        increment_merge_attempt=True,
    )


def _judge_integration_failure(
    slice_id: str,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    *,
    failure_kind: str,
    reason: str,
    gate_name: str,
    head_sha: str,
    base_sha: str | None = None,
    parent_branch: str | None = None,
    increment_merge_attempt: bool = False,
) -> RunState:
    """Reserve, judge, and route one bounded parent integration failure."""
    choice = config.tl_model_choice
    if choice is None or config.policy is None:
        raise TLLoopError(
            "integration_failure requires config.tl_model_choice and config.policy; "
            "the controller must resolve roles.tl at startup"
        )
    if choice.role != "tl":
        raise TLLoopError("integration_failure judgments must use the roles.tl budget")
    role_policy = config.policy.roles["tl"]
    ceiling = role_policy.escalate_after_attempts
    current = state.slices[slice_id]
    candidate = _candidate_runtime(state.integration, slice_id)
    if candidate.tl_intervention_attempts >= ceiling:
        return _open_integration_failure_ceiling(
            slice_id,
            state,
            config,
            effects,
            store,
            effects_log,
            failure_kind,
            reason,
            gate_name,
            candidate.tl_intervention_attempts,
            ceiling,
        )
    attempt = candidate.tl_intervention_attempts + 1
    transitioned = _transition_candidate_runtime(
        state.integration, slice_id, IntegrationTransition.INTEGRATION_CONFLICT
    )
    reserved = replace(
        _candidate_runtime(transitioned, slice_id),
        head_sha=head_sha,
        patch_digest=current.review_patch_digests.get(head_sha),
        validated_base_sha=base_sha,
        merge_tree_sha=None,
        ci_status="failure",
        integration_evidence_at=None,
        stage_verification="failed",
        merge_attempts=candidate.merge_attempts + int(increment_merge_attempt),
        tl_intervention_attempts=attempt,
    )
    state = store.checkpoint(
        _phase_from_state(state),
        state.slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=_persist_candidate_runtime(transitioned, slice_id, reserved),
    )
    return _call_integration_judgment(
        slice_id,
        state,
        config,
        effects,
        store,
        effects_log,
        failure_kind,
        reason,
        gate_name,
        head_sha,
        base_sha,
        parent_branch,
        choice,
        role_policy,
        attempt,
        ceiling,
    )


def _call_integration_judgment(
    slice_id: str,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    failure_kind: str,
    reason: str,
    gate_name: str,
    head_sha: str,
    base_sha: str | None,
    parent_branch: str | None,
    choice: RlmModelChoice,
    role_policy: RolePolicy,
    attempt: int,
    ceiling: int,
) -> RunState:
    """Run one already-reserved roles.tl integration judgment."""
    choice.store.ledger.bind(
        choice.role,
        spent=state.budgets.role_spent.get(choice.role, 0),
        budget=role_policy.token_budget,
        charge_callback=store.charge_role_tokens,
    )
    spent_before = choice.store.ledger.spent.get(choice.role, 0)
    current = state.slices[slice_id]
    try:
        decision = judge_integration_failure(
            choice,
            evidence={
                "failure_kind": failure_kind,
                "reason": reason[:500],
                "pr_number": current.pr_number,
                "base_sha": base_sha,
                "parent_branch": parent_branch,
                "head_sha": head_sha,
                "attempt": attempt,
                "ceiling": ceiling,
            },
            owned_paths=current.paths,
        )
    except (RlmError, RepairError, BudgetExceeded, ContextBudgetError) as error:
        state = store.load()
        return _integration_judgment_failed(
            slice_id,
            state,
            config,
            effects,
            store,
            effects_log,
            failure_kind,
            reason,
            gate_name,
            error,
            choice.model_id,
            attempt,
            ceiling,
        )
    state = store.load()
    _record_controller_event(
        slice_id,
        "tl.integration_failure_judged",
        {
            "slice_id": slice_id,
            "pr_number": current.pr_number,
            "head_sha": head_sha,
            "failure_kind": failure_kind,
            "action": decision.action,
            "reason": decision.reason[:500],
            "intervention": attempt,
            "ceiling": ceiling,
            "model": choice.model_id,
            "tokens": choice.store.ledger.spent.get(choice.role, 0) - spent_before,
        },
        config,
        effects,
        effects_log,
    )
    if decision.action == "escalate":
        return _open_integration_gate(
            slice_id,
            state,
            config,
            effects,
            store,
            effects_log,
            gate_name=gate_name,
            lifecycle=IntegrationLifecycle.INTEGRATION_CONFLICT,
            reason=f"{reason}; roles.tl escalated: {decision.reason[:300]}",
        )
    return _dispatch_integration_repair(
        slice_id,
        state,
        config,
        effects,
        store,
        effects_log,
        failure_kind,
        reason,
        decision.handoff,
    )


def _open_integration_failure_ceiling(
    slice_id: str,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    failure_kind: str,
    reason: str,
    gate_name: str,
    attempts: int,
    ceiling: int,
) -> RunState:
    """Open a human gate without making a judgment past the configured ceiling."""
    _record_controller_event(
        slice_id,
        "tl.integration_failure_ceiling_reached",
        {
            "slice_id": slice_id,
            "failure_kind": failure_kind,
            "interventions": attempts,
            "ceiling": ceiling,
            "reason": reason[:500],
        },
        config,
        effects,
        effects_log,
    )
    return _open_integration_gate(
        slice_id,
        state,
        config,
        effects,
        store,
        effects_log,
        gate_name=gate_name,
        lifecycle=IntegrationLifecycle.INTEGRATION_CONFLICT,
        reason=f"{reason}; roles.tl integration judgment ceiling {ceiling} reached",
    )


def _integration_judgment_failed(
    slice_id: str,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    failure_kind: str,
    reason: str,
    gate_name: str,
    error: Exception,
    model_id: str,
    attempt: int,
    ceiling: int,
) -> RunState:
    """Fail closed to a human gate when the bounded judgment cannot be used."""
    failure_reason = f"{reason}; roles.tl judgment failed: {error}"
    _record_controller_event(
        slice_id,
        "tl.integration_failure_judgment_failed",
        {
            "slice_id": slice_id,
            "failure_kind": failure_kind,
            "intervention": attempt,
            "ceiling": ceiling,
            "model": model_id,
            "error": str(error)[:500],
        },
        config,
        effects,
        effects_log,
    )
    return _open_integration_gate(
        slice_id,
        state,
        config,
        effects,
        store,
        effects_log,
        gate_name=gate_name,
        lifecycle=IntegrationLifecycle.INTEGRATION_CONFLICT,
        reason=failure_reason,
    )


def _dispatch_integration_repair(
    slice_id: str,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    failure_kind: str,
    reason: str,
    handoff: RepairHandoff | None,
) -> RunState:
    """Resume the existing aggregate owner with the validated TL handoff."""
    if handoff is None:
        raise TLLoopError("delegate integration judgment has no validated handoff")
    current = state.slices[slice_id]
    transitioning = _transition_candidate_runtime(
        state.integration, slice_id, IntegrationTransition.REPAIR_STARTED
    )
    candidate = replace(
        _candidate_runtime(transitioning, slice_id),
        head_sha=None,
        patch_digest=None,
        validated_base_sha=None,
        merge_tree_sha=None,
        integration_evidence_at=None,
        ci_status="unknown",
        stage_verification="pending",
    )
    updated = replace(
        current,
        dispatch_last_boundary="integration_failure",
        dispatch_error=reason[:500],
    )
    state = store.checkpoint(
        _phase_from_state(state),
        {**state.slices, slice_id: updated},
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=_persist_candidate_runtime(transitioning, slice_id, candidate),
    )
    _record_controller_event(
        slice_id,
        "tl.integration_repair_requested",
        {
            "slice_id": slice_id,
            "pr_number": current.pr_number,
            "owner_id": current.dispatch_agent_id,
            "failure_kind": failure_kind,
            "reason": reason[:500],
            "repair_attempt": current.repair_attempts + 1,
        },
        config,
        effects,
        effects_log,
    )
    return _route_repair(
        store,
        state,
        _phase_from_state(state),
        state.events.last_consumed_offset,
        slice_id,
        config,
        effects,
        effects_log,
        _guide_repair(handoff, store, slice_id),
        aggregate_repair=True,
        gate_name_on_failure=(
            INTEGRATION_CONFLICT_GATE_NAME
            if failure_kind == "parent_merge_conflict"
            else INTEGRATION_FAILURE_GATE_NAME
        ),
    )


def _integrate_one_candidate(
    task: SubTLTask,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> RunState:
    """Validate one aggregate candidate, recheck its base, then merge it."""
    current = state.slices[task.name]
    candidate_runtime = _candidate_runtime(state.integration, task.name)
    aggregate_identity = _aggregate_candidate_from_state(
        task.name, state.integration.candidates.get(task.name)
    )
    publication_owner = task.agent_id or task.name
    if current.pr_number is None or aggregate_identity is None:
        _log_readiness_refusal(
            task.name, "aggregate_candidate_missing", "aggregate PR binding is absent"
        )
        return state
    first: Mapping[str, object] | None = None
    if candidate_runtime.lifecycle is IntegrationLifecycle.MERGING:
        first = _watcher_snapshot(current.pr_number, config, effects, effects_log)
        if first is None:
            return state
        if _watcher_publication_refused(current, first, publication_owner) or (
            _watcher_publication_ownership_unresolved(first)
        ):
            LOGGER.warning(
                "[TL loop] refusing aggregate merge for %s: publication provenance mismatch",
                task.name,
            )
            return state
        if _snapshot_bool(first, "merged"):
            readiness = _load_child_readiness_for_watcher(
                task,
                state,
                current,
                aggregate_identity,
                first,
                config,
                store,
            )
            if readiness is None:
                return state
            _record_controller_event(
                task.name,
                "tl.merge_reconciled",
                {
                    "slice_id": task.name,
                    "pr_number": current.pr_number,
                    "head_sha": candidate_runtime.head_sha,
                    "reconciliation": "authoritative_merge_reconciled",
                },
                config,
                effects,
                effects_log,
            )
            return _checkpoint_aggregate_merged(
                task, state, store, candidate_runtime, config, effects, effects_log
            )
        # A successful merge response is not terminal. Keep the action in
        # flight and wait for an authoritative merged observation instead of
        # issuing a second request while the remote operation settles.
        return state
    first = first or _watcher_snapshot(current.pr_number, config, effects, effects_log)
    if first is None:
        return state
    if _watcher_publication_refused(current, first, publication_owner) or (
        _watcher_publication_ownership_unresolved(first)
    ):
        LOGGER.warning(
            "[TL loop] refusing aggregate merge for %s: publication provenance mismatch",
            task.name,
        )
        return state
    refusal = _aggregate_publication_refusal(task, current, aggregate_identity, first)
    if refusal is not None:
        _log_readiness_refusal(
            task.name, refusal, "live aggregate publication does not match its candidate"
        )
        return state
    if _snapshot_bool(first, "merged"):
        readiness = _load_child_readiness_for_watcher(
            task,
            state,
            current,
            aggregate_identity,
            first,
            config,
            store,
        )
        if readiness is None:
            return state
        merged_head = _snapshot_text(first, "head_sha") or candidate_runtime.head_sha
        merged_patch = (
            _snapshot_text(first, "patch_digest")
            or candidate_runtime.patch_digest
            or current.review_patch_digests.get(merged_head or "")
        )
        merged_base = _snapshot_text(first, "base_sha") or candidate_runtime.validated_base_sha
        reconciled = replace(
            candidate_runtime,
            head_sha=merged_head,
            patch_digest=merged_patch,
            validated_base_sha=merged_base,
            merge_tree_sha=(
                _snapshot_text(first, "merge_tree_sha") or candidate_runtime.merge_tree_sha
            ),
            ci_status=_snapshot_text(first, "ci_status") or candidate_runtime.ci_status,
            stage_verification=candidate_runtime.stage_verification or "passed",
        )
        _record_controller_event(
            task.name,
            "tl.merge_reconciled",
            {
                "slice_id": task.name,
                "pr_number": current.pr_number,
                "head_sha": merged_head,
                "reconciliation": "unexpected_external_merge",
            },
            config,
            effects,
            effects_log,
        )
        return _checkpoint_aggregate_merged(
            task, state, store, reconciled, config, effects, effects_log
        )
    head_sha = _snapshot_text(first, "head_sha")
    base_sha = _snapshot_text(first, "base_sha")
    patch_digest = _snapshot_text(first, "patch_digest") or current.review_patch_digests.get(
        current.reviewed_head or ""
    )
    merge_tree_sha = _snapshot_text(first, "merge_tree_sha")
    ci_status = _snapshot_text(first, "ci_status")
    if not all((head_sha, base_sha, patch_digest, merge_tree_sha, ci_status)):
        return state
    if head_sha != aggregate_identity.head_sha or patch_digest != aggregate_identity.patch_digest:
        return state
    readiness = _load_child_readiness_for_watcher(
        task,
        state,
        current,
        aggregate_identity,
        first,
        config,
        store,
    )
    if readiness is None:
        return state
    reconciled_current = _supersede_ordered_recovery_after_proof(
        current, state.run_id, task.name, readiness, config, effects, effects_log
    )
    if reconciled_current is not current:
        state = store.checkpoint(
            _phase_from_state(state),
            {**state.slices, task.name: reconciled_current},
            state.budgets,
            state.events.last_consumed_offset,
            current_order=state.current_order,
            ordered_stages=state.ordered_stages,
            expected_revision=state.revision,
        )
        current = state.slices[task.name]
    transitioned_integration = (
        state.integration
        if candidate_runtime.lifecycle is IntegrationLifecycle.INTEGRATION_VALIDATED
        else _transition_candidate_runtime(
            state.integration, task.name, IntegrationTransition.INTEGRATION_VALIDATED
        )
    )
    integration = replace(
        _candidate_runtime(transitioned_integration, task.name),
        head_sha=head_sha,
        patch_digest=patch_digest,
        validated_base_sha=base_sha,
        merge_tree_sha=merge_tree_sha,
        ci_status=ci_status,
        stage_verification="passed",
        integration_evidence_at=_now_timestamp(),
    )
    state = store.checkpoint(
        _phase_from_state(state),
        state.slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=_persist_candidate_runtime(transitioned_integration, task.name, integration),
    )
    _record_controller_event(
        task.name,
        "tl.integration_validated",
        {
            "slice_id": task.name,
            "pr_number": current.pr_number,
            "base_sha": base_sha,
            "head_sha": head_sha,
            "merge_tree_sha": merge_tree_sha,
            "ci_status": ci_status,
        },
        config,
        effects,
        effects_log,
    )
    second = _watcher_snapshot(current.pr_number, config, effects, effects_log)
    if second is None:
        return state
    if _watcher_publication_refused(current, second, publication_owner) or (
        _watcher_publication_ownership_unresolved(second)
    ):
        LOGGER.warning(
            "[TL loop] refusing aggregate merge for %s: publication provenance mismatch",
            task.name,
        )
        return state
    if second.pr_number != aggregate_identity.pr_number or second.found is not True:
        _log_readiness_refusal(
            task.name,
            "aggregate_publication_changed",
            "watcher no longer resolves the same aggregate PR",
        )
        return state
    if (
        _snapshot_text(second, "head_sha") == readiness.aggregate_head_sha
        and _snapshot_text(second, "pr_head_tree_sha") != readiness.aggregate_head_tree_sha
    ):
        _log_readiness_refusal(
            task.name,
            "aggregate_head_tree_changed",
            "authoritative aggregate head tree changed after readiness verification",
        )
        return state
    if _snapshot_text(second, "base_sha") != base_sha:
        return _handle_external_base_change(
            task,
            state,
            config,
            effects,
            store,
            effects_log,
            base_sha=base_sha,
            head_sha=head_sha,
            patch_digest=patch_digest,
            reason=(
                f"aggregate base changed from {base_sha!r} to "
                f"{_snapshot_text(second, 'base_sha')!r} before merge"
            ),
        )
    live_head_sha = _snapshot_text(second, "head_sha")
    live_patch_digest = _snapshot_text(second, "patch_digest")
    live_merge_tree_sha = _snapshot_text(second, "merge_tree_sha")
    live_ci_status = _snapshot_text(second, "ci_status")
    if not all((live_head_sha, live_patch_digest, live_merge_tree_sha, live_ci_status)):
        return state
    try:
        verify_integration(
            integration,
            base_sha=base_sha,
            head_sha=live_head_sha,
            patch_digest=live_patch_digest,
            merge_tree_sha=live_merge_tree_sha,
            ci_status=live_ci_status,
        )
    except IntegrationEvidenceMismatch as error:
        if error.field in {"head_sha", "patch_digest"}:
            return _open_integration_gate(
                task,
                state,
                config,
                effects,
                store,
                effects_log,
                gate_name=INTEGRATION_CONFLICT_GATE_NAME,
                lifecycle=IntegrationLifecycle.INTEGRATION_CONFLICT,
                reason=str(error),
            )
        return _handle_integration_revalidation(
            task,
            state,
            config,
            effects,
            store,
            effects_log,
            base_sha=base_sha,
            head_sha=live_head_sha,
            patch_digest=live_patch_digest,
            reason=str(error),
        )
    _record_controller_event(
        task.name,
        "tl.integration_revalidated",
        {
            "slice_id": task.name,
            "pr_number": current.pr_number,
            "base_sha": base_sha,
            "head_sha": head_sha,
            "merge_tree_sha": merge_tree_sha,
            "ci_status": ci_status,
        },
        config,
        effects,
        effects_log,
    )
    lane_base_sha = base_sha
    state, lane_ready = _ensure_candidate_lane(state, current, lane_base_sha, store)
    if not lane_ready:
        return state
    state, lane_ready = _start_candidate_lane(state, current, live_head_sha, store)
    if not lane_ready:
        return state
    try:
        approval_history, approval_receipt = _parent_aggregate_approval(
            task,
            state,
            readiness,
            store,
            config,
            pr_number=current.pr_number,
            head_sha=live_head_sha,
            head_tree_sha=readiness.aggregate_head_tree_sha,
            base_sha=base_sha,
            patch_digest=live_patch_digest,
            merge_tree_sha=live_merge_tree_sha,
            ci_status=live_ci_status,
        )
        approval_ref = approval_reference(approval_receipt, state.controller_epoch or "")
    except (AggregateApprovalError, ValueError) as error:
        _log_readiness_refusal(task.name, "parent_approval_unavailable", str(error))
        return state
    approval_runtime = replace(
        _candidate_runtime(state.integration, task.name),
        aggregate_approval_receipts=approval_history,
        active_aggregate_approval_id=approval_receipt.receipt_id,
    )
    state = store.checkpoint(
        _phase_from_state(state),
        state.slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=_persist_candidate_runtime(state.integration, task.name, approval_runtime),
    )
    merge_arguments = {
        "pr_number": current.pr_number,
        "strategy": config.merge_strategy or task.integration.merge_strategy,
        "working_dir": _relative_process_working_dir(config),
        "base_sha": base_sha,
        "aggregate_approval_receipt_id": approval_receipt.receipt_id,
        # A retirement of a proven-rejected attempt advances this counter, so a
        # genuinely new approved attempt has a distinct action identity and can
        # never silently replay the old rejection from the durable journal.
        "attempt": _candidate_runtime(state.integration, task.name).merge_attempts + 1,
    }
    merge_intent_id = stable_action_key(state.run_id, "merge_pr", task.name, merge_arguments)
    merge_action = ActionState(
        ActionKind.MERGE,
        ActionPhase.IN_FLIGHT,
        intent_id=merge_intent_id,
        head_sha=head_sha,
        attempt=max(1, current.attempts),
    )
    merge_slice = slice_transition(current, ActionChanged(merge_action))
    merging_integration = _transition_candidate_runtime(
        state.integration, task.name, IntegrationTransition.MERGE_STARTED
    )
    state = store.checkpoint(
        _phase_from_state(state),
        {**state.slices, task.name: merge_slice},
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=merging_integration,
    )
    _emit_merge_decision(
        task.name,
        current.pr_number,
        "merge",
        head_sha,
        config,
        effects,
        effects_log,
    )
    merge_result = _invoke(
        "merge_pr",
        task.name,
        merge_arguments,
        config.active,
        cast(EffectClient, effects),
        lambda client: client.merge_pr(
            pr_number=current.pr_number or 0,
            strategy=config.merge_strategy or task.integration.merge_strategy,
            working_dir=_relative_process_working_dir(config),
            expected_base_sha=base_sha,
            expected_head_sha=head_sha,
            expected_patch_digest=patch_digest,
            expected_merge_tree_sha=merge_tree_sha,
            aggregate_approval=approval_ref,
        ),
        effects_log,
        raise_on_failure=False,
    )
    failure = _merge_failure_classification(merge_result)
    if _merge_result_is_authoritative(merge_result):
        return _checkpoint_aggregate_merged(
            task,
            state,
            store,
            _candidate_runtime(state.integration, task.name),
            config,
            effects,
            effects_log,
        )
    if failure == "conflict":
        return _handle_integration_conflict(
            task,
            state,
            config,
            effects,
            store,
            effects_log,
            base_sha=base_sha,
            head_sha=head_sha,
            reason=_merge_failure_reason(merge_result),
        )
    if failure == "base_changed":
        return _handle_external_base_change(
            task,
            state,
            config,
            effects,
            store,
            effects_log,
            base_sha=base_sha,
            head_sha=head_sha,
            patch_digest=patch_digest,
            reason=_merge_failure_reason(merge_result),
        )
    if failure is not None:
        raise EffectFailed(f"merge_pr for {task.name!r}: {_merge_failure_reason(merge_result)}")
    return state


def _parent_aggregate_approval(
    task: SubTLTask,
    state: RunState,
    readiness: IntegrationReadinessEvidence,
    store: RunStore,
    config: TLLoopConfig,
    *,
    pr_number: int,
    head_sha: str,
    head_tree_sha: str,
    base_sha: str,
    patch_digest: str,
    merge_tree_sha: str,
    ci_status: str,
) -> tuple[tuple[AggregateApprovalReceipt, ...], AggregateApprovalReceipt]:
    """Bind parent authorization to the accepted plan and verified aggregate evidence."""
    coordinates = _parent_aggregate_approval_coordinates(
        task,
        state,
        readiness,
        store,
        config,
        pr_number,
        head_sha,
        head_tree_sha,
        base_sha,
        patch_digest,
        merge_tree_sha,
        ci_status,
    )
    existing = _candidate_runtime(state.integration, task.name).aggregate_approval_receipts
    return ensure_parent_aggregate_approval(existing, coordinates, created_at=_now_timestamp())


def _parent_aggregate_approval_coordinates(
    task: SubTLTask,
    state: RunState,
    readiness: IntegrationReadinessEvidence,
    store: RunStore,
    config: TLLoopConfig,
    pr_number: int,
    head_sha: str,
    head_tree_sha: str,
    base_sha: str,
    patch_digest: str,
    merge_tree_sha: str,
    ci_status: str,
) -> dict[str, object]:
    """Collect authoritative plan, scope and compare coordinates."""
    manifest, node = _accepted_aggregate_node(task, state, readiness, config)
    parent_path = _controller_scope_path(store, config.depth)
    policy_digest = _approval_policy_digest(manifest, node, readiness)
    coordinates = _aggregate_scope_coordinates(
        task, state, config, manifest, node, readiness, parent_path, policy_digest
    )
    compare_coordinates = _aggregate_compare_coordinates(
        readiness,
        pr_number,
        head_sha,
        head_tree_sha,
        base_sha,
        patch_digest,
        merge_tree_sha,
        ci_status,
    )
    return {**coordinates, **compare_coordinates}


def _accepted_aggregate_node(
    task: SubTLTask,
    state: RunState,
    readiness: IntegrationReadinessEvidence,
    config: TLLoopConfig,
) -> tuple[PlanManifest, ManifestNode]:
    """Resolve an aggregate only through its accepted parent declaration."""
    if parse_aggregate_approval_mode(task.integration.aggregate_approval_mode) != "parent":
        raise AggregateApprovalError("aggregate approval policy is not parent mode")
    manifest = state.plan_manifest
    if manifest is None or state.repository_identity is None:
        raise AggregateApprovalError("accepted plan and repository identity are required")
    _validate_parent_controller_identity(state, config)
    node = next((item for item in manifest.nodes if item.name == task.name), None)
    if node is None or node.kind != "sub_tl":
        raise AggregateApprovalError("aggregate is not a declared sub-TL in the accepted plan")
    if node.child_manifest_digest != readiness.child_manifest_digest:
        raise AggregateApprovalError("child manifest differs from the accepted parent binding")
    if node.integration_contract.get("aggregate_pr_required", True) is not True:
        raise AggregateApprovalError("accepted plan does not require an aggregate PR")
    if node.integration_contract.get("aggregate_review_owner", "none") != "none":
        raise AggregateApprovalError("accepted plan requires an unsupported aggregate reviewer")
    return manifest, node


def _validate_parent_controller_identity(state: RunState, config: TLLoopConfig) -> None:
    """Require a live identified controller on its recorded owner branch."""
    if not config.agent_id or not state.controller_epoch:
        raise AggregateApprovalError("current parent controller identity is unavailable")
    if state.owner_branch and state.owner_branch != config.branch:
        raise AggregateApprovalError("current branch differs from the declared parent branch")


def _approval_policy_digest(
    manifest: PlanManifest,
    node: ManifestNode,
    readiness: IntegrationReadinessEvidence,
) -> str:
    """Digest the supported policy together with its accepted plan bindings."""
    return canonical_digest(
        {
            "approval_mode": "parent",
            "parent_manifest_digest": manifest.digest,
            "parent_manifest_revision": manifest.manifest_revision,
            "child_manifest_digest": readiness.child_manifest_digest,
            "integration_contract": dict(node.integration_contract),
        }
    )


def _aggregate_scope_coordinates(
    task: SubTLTask,
    state: RunState,
    config: TLLoopConfig,
    manifest: PlanManifest,
    node: ManifestNode,
    readiness: IntegrationReadinessEvidence,
    parent_path: tuple[str, ...],
    policy_digest: str,
) -> dict[str, object]:
    """Bind actor, repository and accepted scope coordinates."""
    if state.repository_identity is None:
        raise AggregateApprovalError("accepted repository identity is required")
    child_manifest = manifest.child_manifests.get(node.node_id)
    if child_manifest is None:
        raise AggregateApprovalError("accepted parent manifest has no declared child manifest")
    return {
        "parent_run_id": state.run_id,
        "parent_scope_path": list(parent_path),
        "parent_manifest_scope_id": manifest.scope_id,
        "candidate_key": task.name,
        "child_run_id": node.name,
        "child_manifest_node_id": node.node_id,
        "child_manifest_scope_id": child_manifest.scope_id,
        "parent_agent_id": config.agent_id,
        "parent_branch": config.branch,
        "repository_url": state.repository_identity.remote_url,
        "plan_manifest_digest": manifest.digest,
        "plan_manifest_revision": manifest.manifest_revision,
        "approval_policy_digest": policy_digest,
        "child_manifest_digest": readiness.child_manifest_digest,
    }


def _aggregate_compare_coordinates(
    readiness: IntegrationReadinessEvidence,
    pr_number: int,
    head_sha: str,
    head_tree_sha: str,
    base_sha: str,
    patch_digest: str,
    merge_tree_sha: str,
    ci_status: str,
) -> dict[str, object]:
    """Bind the current PR compare and child-lineage proof."""
    return {
        "pr_number": pr_number,
        "head_sha": head_sha,
        "head_tree_sha": head_tree_sha,
        "base_sha": base_sha,
        "patch_digest": patch_digest,
        "merge_tree_sha": merge_tree_sha,
        "ci_status": ci_status,
        "readiness_receipt_digest": readiness.receipt_digest,
        "lineage_proof_digest": readiness.lineage_proof_digest,
        "lineage_commit_shas": list(readiness.lineage_commit_shas),
        "reviewed_leaf_ids": list(readiness.reviewed_leaf_ids),
    }


def _controller_scope_path(store: RunStore, depth: int) -> tuple[str, ...]:
    """Return the canonical .exo/tl-loop path to this controller scope."""
    if type(depth) is not int or depth < 0 or depth >= len(store.run_dir.parents):
        raise AggregateApprovalError("controller nesting depth is invalid")
    root = store.run_dir.parents[depth]
    try:
        parts = store.run_dir.relative_to(root).parts
    except ValueError as error:
        raise AggregateApprovalError("controller scope is outside the run hierarchy") from error
    if not parts or parts[-1] != store.run_id:
        raise AggregateApprovalError("controller scope path does not match its run ID")
    return tuple(parts)


def _checkpoint_aggregate_merged(
    task: SubTLTask,
    state: RunState,
    store: RunStore,
    integration: IntegrationRuntimeState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Persist one merge result, including a restart reconciliation result."""
    current = state.slices[task.name]
    previous_slices = state.slices
    updated_slices = dict(state.slices)
    aggregate_pr_number = current.pr_number
    if type(aggregate_pr_number) is not int or aggregate_pr_number <= 0:
        return _block_post_merge_recovery(
            store,
            state,
            task.name,
            f"aggregate merge for {task.name!r} has no authoritative PR number",
        )
    if current.action is None or not current.action.intent_id:
        return _block_post_merge_recovery(
            store,
            state,
            task.name,
            f"aggregate merge for {task.name!r} has no durable merge intent",
        )
    aggregate_merge_key = current.action.intent_id
    aggregate_head = integration.aggregate_head_sha or integration.head_sha
    aggregate_base = integration.validated_base_sha or integration.aggregate_original_base_sha
    if not aggregate_head or not aggregate_base:
        return _block_post_merge_recovery(
            store,
            state,
            task.name,
            f"aggregate merge for {task.name!r} has incomplete merge evidence",
        )
    state, lane_ready = _ensure_candidate_lane(state, current, aggregate_base, store)
    if not lane_ready:
        return state
    state, lane_ready = _start_candidate_lane(state, current, aggregate_head, store)
    if not lane_ready:
        return state
    current = state.slices[task.name]
    try:
        merge_evidence = {
            "head_sha": aggregate_head,
            "base_sha": aggregate_base,
            "repository": _repository_identity(state),
            "parent_branch": _publication_parent_branch_from_slice(current),
            "lane_epoch": state.integration.lanes[
                f"{_repository_identity(state)}:{_publication_parent_branch_from_slice(current)}"
            ].lane_epoch,
        }
    except ValueError as error:
        return _block_post_merge_recovery(
            store,
            state,
            task.name,
            f"cannot adopt aggregate merge for {task.name!r}: {error}",
        )
    updated_slices[task.name] = _adopt_post_merge_slice(
        current,
        state,
        aggregate_pr_number,
        aggregate_merge_key,
        "aggregate_merged",
        merge_evidence,
    )
    try:
        merged_candidates = _transition_candidate_runtime(
            state.integration, task.name, IntegrationTransition.MERGED
        )
    except IntegrationTransitionError as error:
        return _block_post_merge_recovery(
            store,
            state,
            task.name,
            f"aggregate merge lifecycle is not recoverable: {error}",
        )
    sub_states = dict(merged_candidates.sub_tl_states)
    candidate_records = dict(state.integration.candidates)
    for sibling in state.ordered_stages:
        if task.name not in sibling.sub_tls:
            continue
        for sibling_id in sibling.sub_tls:
            if (
                sibling_id != task.name
                and updated_slices[sibling_id].status is SliceStatus.IN_REVIEW
            ):
                sibling_runtime = _candidate_runtime(state.integration, sibling_id)
                sibling_lifecycle = _transition_sub_tl_lifecycle(
                    sibling_runtime.lifecycle, IntegrationTransition.BASE_INVALIDATED
                )
                sub_states[sibling_id] = sibling_lifecycle
                candidate_records[sibling_id] = IntegrationCandidateState(
                    lifecycle=sibling_lifecycle,
                    aggregate_pr_number=sibling_runtime.aggregate_pr_number,
                    aggregate_head_sha=sibling_runtime.aggregate_head_sha,
                    aggregate_patch_digest=sibling_runtime.aggregate_patch_digest,
                    aggregate_original_base_sha=sibling_runtime.aggregate_original_base_sha,
                    integration_owner_id=sibling_runtime.integration_owner_id,
                    integration_owner_run_id=sibling_runtime.integration_owner_run_id,
                    integration_owner_branch=sibling_runtime.integration_owner_branch,
                    integration_owner_worktree=sibling_runtime.integration_owner_worktree,
                    head_sha=sibling_runtime.head_sha,
                    patch_digest=sibling_runtime.patch_digest,
                    validated_base_sha=None,
                    merge_tree_sha=None,
                    integration_evidence_at=None,
                    ci_status="unknown",
                    merge_attempts=sibling_runtime.merge_attempts,
                    base_revalidation_count=sibling_runtime.base_revalidation_count,
                    tl_intervention_attempts=sibling_runtime.tl_intervention_attempts,
                    stage_verification="pending",
                )
    merged_integration = replace(
        _candidate_runtime(merged_candidates, task.name),
        aggregate_pr_number=integration.aggregate_pr_number or current.pr_number,
        aggregate_head_sha=integration.aggregate_head_sha
        or integration.head_sha
        or current.reviewed_head,
        aggregate_patch_digest=(
            integration.aggregate_patch_digest
            or integration.patch_digest
            or current.review_patch_digests.get(current.reviewed_head or "")
        ),
        integration_owner_id=(
            integration.integration_owner_id
            or current.dispatch_agent_id
            or f"{store.run_id}:{task.name}:integration"
        ),
        integration_owner_run_id=integration.integration_owner_run_id or task.name,
        integration_owner_branch=(
            integration.integration_owner_branch
            or current.branch
            or derive_child_branch(current.base_ref or "main", _child_controller_name(task))
        ),
        integration_owner_worktree=(
            integration.integration_owner_worktree
            or current.worktree
            or str(store.root_dir / task.name)
        ),
        merge_attempts=integration.merge_attempts + 1,
        integration_evidence_at=integration.integration_evidence_at or _now_timestamp(),
        stage_verification="passed",
    )
    persisted_merged = _persist_candidate_runtime(merged_candidates, task.name, merged_integration)
    candidate_records[task.name] = persisted_merged.candidates[task.name]
    remaining = {
        sibling_id: ChildHandle(
            sibling_id,
            sibling_slice.branch or "",
            "sub-tl",
        )
        for sibling_id, sibling_slice in updated_slices.items()
        if sibling_slice.status
        in {
            SliceStatus.SPAWNED,
            SliceStatus.IN_REVIEW,
            SliceStatus.REPAIRING,
        }
        or (
            sibling_slice.status is SliceStatus.MERGED
            and (
                sibling_slice.post_merge is None
                or sibling_slice.post_merge.phase is not PostMergePhase.COMPLETE
            )
        )
    }
    checkpoint_phase: PhaseValue = TLWaiting(remaining) if remaining else TLPlanning()
    checkpointed = store.checkpoint(
        checkpoint_phase,
        updated_slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=replace(
            persisted_merged,
            sub_tl_states=sub_states,
            candidates=candidate_records,
        ),
    )
    _emit_slice_status_changes(previous_slices, checkpointed.slices, config, effects, effects_log)
    return _drain_post_merge_recovery(
        checkpointed,
        task.name,
        aggregate_pr_number,
        config,
        effects,
        effects_log,
        store,
    )


def _checkpoint_integration_retry(
    state: RunState,
    slice_id: str,
    integration: IntegrationRuntimeState,
    config: TLLoopConfig,
    store: RunStore,
    *,
    slice_update: SliceState | None = None,
) -> RunState:
    """Persist a base retry without changing the candidate head or sibling slices."""
    del config
    sub_states = dict(state.integration.sub_tl_states)
    sub_states[slice_id] = IntegrationLifecycle.NEEDS_BASE_REVALIDATION
    persisted = _persist_candidate_runtime(state.integration, slice_id, integration)
    slices = dict(state.slices)
    if slice_update is not None:
        slices[slice_id] = slice_update
    return store.checkpoint(
        _phase_from_state(state),
        slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=replace(persisted, sub_tl_states=sub_states),
    )


def _resolve_repository_identity(
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RepositoryIdentity | None:
    """Resolve a canonical repository URL without exposing transport details."""
    identity, _failure_code = _resolve_repository_identity_detail(config, effects, effects_log)
    return identity


def _repository_identity_required(
    state: RunState | None,
    config: TLLoopConfig,
) -> bool:
    """Require identity before any new or resumable controller can act."""
    if state is None or not _is_terminal_phase(_phase_from_state(state)):
        return True
    return isinstance(state.recursive_fsm, RecursiveTLFailed) and (
        config.session_mode == "continue" or config.ordered_recovery
    )


def _verify_supplied_plan_before_identity_recovery(
    run_id: str,
    plan: WorkPlan | Mapping[str, object] | None,
    state: RunState,
    config: TLLoopConfig,
    runstore_root: Path,
) -> None:
    """Reject stale declarations before identity migration can write a checkpoint."""
    manifest = state.plan_manifest
    if plan is None or manifest is None or _manifest_is_legacy(manifest):
        return
    supplied_plan = plan if isinstance(plan, WorkPlan) else WorkPlan.from_mapping(plan)
    candidate = retain_scope_revisions(_candidate_manifest(supplied_plan, run_id, config), manifest)
    if candidate.digest == manifest.digest:
        return
    if _is_terminal_phase(_phase_from_state(state)):
        raise TLLoopError(
            "terminal checkpoint plan digest "
            f"{manifest.digest} differs from supplied plan digest {candidate.digest}; "
            "archive the completed run before starting a new plan"
        )
    project_root = (
        Path(config.project_root).expanduser().absolute()
        if config.project_root is not None
        else runstore_root.expanduser().absolute().parent.parent
    )
    migration_message = _plan_compatibility_migration_message(project_root, run_id)
    if migration_message is not None:
        raise TLLoopError(migration_message)
    raise TLLoopError(
        "external plan differs from the persisted manifest; use "
        "`exomonad plan revise --dry-run` and apply the audited revision. "
        "If revision analysis reports unversioned drift, inspect "
        "`exomonad plan reconcile --dry-run` and apply only with its "
        "current evidence fingerprint."
    )


def _plan_compatibility_migration_message(project_root: Path, run_id: str) -> str | None:
    """Use the advertised migration assessment before the generic drift message."""
    from tl_loop.state.plan_reconciliation import analyze_plan_reconciliation

    try:
        analysis = analyze_plan_reconciliation(project_root, run_id=run_id)
    except ValueError as error:
        code = getattr(error, "code", None)
        if code == "unsupported_aggregate_review_policy":
            return f"unsupported plan policy: {error}"
        return None
    transition = analysis.compatibility_transition
    if transition is None:
        return None
    apply = (
        'exomonad plan reconcile --apply --reason "Migrate legacy aggregate review defaults" '
        f"--expected-fingerprint {analysis.evidence_fingerprint}"
    )
    if analysis.can_apply:
        status = "the audited compatibility migration is ready"
    else:
        blockers = ", ".join(sorted({item.code for item in analysis.blockers}))
        status = f"the migration is blocked by {blockers or 'unresolved evidence'}"
    return (
        "persisted plan compatibility migration is required before dispatch; "
        f"{status}. Run `exomonad plan reconcile --dry-run`; apply only when can_apply "
        f"is true using `{apply}`"
    )


def _repository_identity_sub_tl_names(
    state: RunState,
    store: RunStore,
) -> tuple[str, ...]:
    """Return existing direct child scopes declared by this run's manifest."""
    manifest = state.plan_manifest
    if manifest is None:
        return ()
    return tuple(
        node.name
        for node in manifest.nodes
        if node.kind == "sub_tl"
        and node.parent_id == manifest.scope_id
        and RunStore(node.name, store.run_dir).path.is_file()
    )


def _park_repository_identity_failure(
    store: RunStore,
    failure_code: str,
    effects: Sequence[EffectIntent],
    legacy_state: RunState | None = None,
) -> TLRunResult:
    """Keep identity failures visible without mutating unbound legacy state."""
    if legacy_state is not None and legacy_state.version == LEGACY_IDENTITY_CHECKPOINT_VERSION:
        parked = legacy_state
    else:
        parked = store.set_gate(REPOSITORY_IDENTITY_GATE_NAME)
    return TLRunResult(
        parked,
        tuple(effects),
        (),
        (),
        diagnostics={"repository_identity_blocker": failure_code},
    )


def _resolve_repository_identity_detail(
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> tuple[RepositoryIdentity | None, str | None]:
    """Classify authority failures without logging the supplied remote URL."""
    del config
    try:
        result = _invoke(
            "repository_identity",
            "repository_identity",
            {},
            True,
            cast(EffectClient, effects),
            lambda client: client.repository_identity(),
            effects_log,
            raise_on_failure=False,
        )
    except ToolUnavailableError:
        return None, "unavailable"
    except (ServerTimeout, TimeoutError):
        return None, "timeout"
    except DecodeError:
        return None, "malformed"
    except (ServerUnreachable, TransportError, OSError, ConnectionError):
        return None, "unavailable"
    if result is None:
        return None, "unavailable"
    if result.success is not True:
        failure_code = "malformed" if result.success is None else "unavailable"
        if result.error_kind == "timeout":
            failure_code = "timeout"
        return None, failure_code
    if not isinstance(result.result, Mapping):
        return None, "malformed"
    if "remote_url" not in result.result:
        return None, "missing"
    remote_url = result.result.get("remote_url")
    if remote_url is None or remote_url == "":
        return None, "missing"
    if not isinstance(remote_url, str):
        return None, "malformed"
    try:
        identity = RepositoryIdentity(canonical_repository_url(remote_url))
    except ValueError as error:
        detail = str(error)
        failure_code = (
            "ambiguous" if "ambiguous" in detail or "credential marker" in detail else "malformed"
        )
        return None, failure_code
    LOGGER.info("[TL loop] Resolved canonical repository identity")
    return identity, None


def _watcher_snapshot(
    pr_number: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> WatcherObservation | None:
    """Read one live PR/base snapshot through the parent-owned watcher."""
    result = _invoke(
        "watcher_pr_state",
        str(pr_number),
        {"pr_number": pr_number},
        config.active,
        cast(EffectClient, effects),
        lambda client: client.watcher_pr_state(pr_number=pr_number),
        effects_log,
    )
    if result is None or result.success is not True or not isinstance(result.result, Mapping):
        return None
    return WatcherObservation.from_response(result.result)


def _watcher_snapshot_for_slice(
    slice_id: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> WatcherObservation | None:
    """Resolve a live PR identity, then read its Forgejo facts."""
    result = _invoke(
        "resolve_live_pr_for_slice",
        f"slice:{slice_id}",
        {"slice_id": slice_id},
        config.active,
        cast(EffectClient, effects),
        lambda client: client.resolve_live_pr_for_slice(slice_id=slice_id),
        effects_log,
        raise_on_failure=False,
    )
    if result is None or result.success is not True or not isinstance(result.result, Mapping):
        return None
    resolution = result.result.get("resolution")
    if resolution == "never_published":
        return None
    if resolution != "live":
        return WatcherObservation.from_response(
            {
                "found": False,
                "publication_ownership_verified": False,
                "publication_ownership_error": result.result.get("error")
                or f"slice publication resolution is {resolution!r}",
            }
        )
    pr_number = result.result.get("pr_number")
    if not isinstance(pr_number, int) or isinstance(pr_number, bool) or pr_number <= 0:
        return None
    snapshot = _watcher_snapshot(pr_number, config, effects, effects_log)
    publication = result.result.get("publication")
    if snapshot is not None and isinstance(publication, Mapping):
        return snapshot.with_publication(publication)
    return snapshot


def _as_watcher_observation(
    snapshot: WatcherObservation | Mapping[str, object] | None,
) -> WatcherObservation | None:
    if snapshot is None or isinstance(snapshot, WatcherObservation):
        return snapshot
    return WatcherObservation.from_response(snapshot)


def _snapshot_text(snapshot: WatcherObservation | Mapping[str, object], key: str) -> str | None:
    observation = _as_watcher_observation(snapshot)
    assert observation is not None
    value = getattr(observation, key, None)
    return value if isinstance(value, str) and value else None


def _publication_evidence(
    watcher: WatcherObservation | Mapping[str, object],
) -> object | None:
    observation = _as_watcher_observation(watcher)
    return observation.publication if observation is not None else None


def _publication_record_text(
    watcher: WatcherObservation | Mapping[str, object] | object | None,
    key: str,
) -> str | None:
    if watcher is None:
        return None
    record = watcher if hasattr(watcher, key) else _publication_evidence(watcher)
    if record is None:
        return None
    value = getattr(record, key, None)
    return value if isinstance(value, str) and value else None


def _publication_record_succession(record: object | None) -> tuple[str, ...]:
    """The invocation ids explicitly recorded as a publication succession."""
    if record is None:
        return ()
    if isinstance(record, Mapping):
        value = record.get("succession_invocation_ids")
    else:
        value = getattr(record, "succession_invocation_ids", None)
    if isinstance(value, (list, tuple)):
        return tuple(item for item in value if isinstance(item, str) and item)
    return ()


def _handoff_reconciliation_event_payload(
    current: SliceState,
    reconciled: SliceState,
    watcher: WatcherObservation | Mapping[str, object],
    owner_id: str | None,
) -> dict[str, object] | None:
    watcher = _as_watcher_observation(watcher)
    assert watcher is not None
    if watcher.found is not True:
        return None
    if watcher.publication_ownership_verified is not True:
        _, ownership_reason = _publication_ownership_status(watcher)
        return {
            "slice_id": current.id,
            "pr_number": watcher.pr_number or 0,
            "head_sha": _snapshot_text(watcher, "head_sha") or "",
            "invocation_id": "",
            "outcome": "skipped",
            "reason": watcher.publication_ownership_error
            or ownership_reason
            or "publication_ownership_unverified",
            "source": "host_publication",
        }
    publication = reconciled.publication or current.publication
    head_sha = _snapshot_text(watcher, "head_sha") or (
        publication.head_sha if publication is not None else ""
    )
    pr_number = (
        reconciled.pr_number
        or (publication.pr_number if publication is not None else None)
        or watcher.pr_number
    )
    handoff = reconciled.handoff
    if handoff is not None:
        return {
            "slice_id": current.id,
            "pr_number": handoff.pr_number,
            "head_sha": handoff.head_sha,
            "invocation_id": handoff.invocation_id,
            "outcome": "backfilled",
            "reason": "",
            "source": "host_publication",
        }
    record = _publication_evidence(watcher)
    expected_owner = current.dispatch_agent_id or owner_id
    record_slice = _publication_record_text(record, "slice_id")
    record_owner = _publication_record_text(record, "author_agent")
    if record_slice is not None and record_slice != current.id:
        reason = f"slice_id_mismatch:{record_slice}"
    elif record_owner is not None and expected_owner is not None and record_owner != expected_owner:
        reason = f"owner_agent_mismatch:{record_owner}"
    else:
        missing = [
            name
            for name, value in (
                ("head_sha", head_sha),
                ("pr_number", pr_number),
                ("owner_agent_id", expected_owner),
                ("invocation_id_provenance", _publication_record_text(record, "invocation_id")),
            )
            if not value
        ]
        reason = "missing " + ", ".join(missing) if missing else "publication_identity"
    return {
        "slice_id": current.id,
        "pr_number": pr_number or 0,
        "head_sha": head_sha,
        "invocation_id": "",
        "outcome": "skipped",
        "reason": reason,
        "source": "host_publication",
    }


def _snapshot_bool(snapshot: Mapping[str, object], key: str) -> bool:
    value = snapshot.get(key)
    return value is True or value == "true"


def _now_timestamp() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def _review_event_submitted_at(event: EventEnvelope) -> str:
    """Prefer the immutable Forgejo submission timestamp over observation time."""
    for key in ("review_submitted_at", "submitted_at"):
        value = event.data.get(key)
        if isinstance(value, str) and value:
            return value
    return event.observed_at


def _child_has_aggregate_output(state: RunState) -> bool:
    """Require a child result with a reviewable head before opening an aggregate PR."""
    if state.integration.aggregate_pr_number is not None:
        return True
    return any(
        slice_state.pr_number is not None or slice_state.reviewed_head is not None
        for slice_state in state.slices.values()
    )


def _child_head_sha(state: RunState, branch: str) -> str:
    for slice_state in state.slices.values():
        if slice_state.reviewed_head:
            return slice_state.reviewed_head
    return hashlib.sha256(f"{branch}:{state.revision}".encode()).hexdigest()


def _child_patch_digest(state: RunState) -> str:
    values = sorted(
        f"{slice_state.id}:{slice_state.pr_number or ''}:{slice_state.reviewed_head or ''}"
        for slice_state in state.slices.values()
    )
    return hashlib.sha256("|".join(values).encode()).hexdigest()


def _persist_non_root_handoff(
    state: RunState,
    store: RunStore,
    integration: IntegrationRuntimeState,
    candidate: AggregateCandidate,
    *,
    parent_branch: str,
) -> None:
    """Durably finish a non-root scope after its parent publishes its candidate."""
    phase = state.recursive_fsm
    manifest = state.plan_manifest
    if manifest is None or manifest.role != "non_root":
        return
    if isinstance(phase, RecursiveTLPRFiled):
        return
    if not isinstance(phase, (RecursiveTLAllMerged, RecursiveTLFinalizing)):
        return
    owner_id = integration.integration_owner_id
    if not owner_id:
        raise TLLoopError("non-root aggregate handoff is missing its durable owner identity")
    evidence = {
        "aggregate_pr": str(candidate.pr_number),
        "head_sha": candidate.head_sha,
        "base_sha": candidate.original_base_sha or parent_branch,
        "parent_branch": parent_branch,
        "handoff": owner_id,
    }
    if isinstance(phase, RecursiveTLAllMerged):
        finalizing = scope_transition(phase, ScopeFinalizationRequested(ScopeRole.NON_ROOT))
        finalizing = replace(finalizing, evidence=evidence)
        state = _checkpoint_scope_phase(finalizing, state, store)
    else:
        finalizing = phase
        if not finalizing.evidence:
            finalizing = replace(finalizing, evidence=evidence)
            state = _checkpoint_scope_phase(finalizing, state, store)
    filed = scope_transition(
        finalizing,
        ScopeFinalizationComplete(ScopeRole.NON_ROOT, finalizing.evidence),
    )
    _checkpoint_scope_phase(filed, state, store)


def _positive_result_int(value: Mapping[str, object], key: str) -> int | None:
    candidate = value.get(key)
    return candidate if type(candidate) is int and candidate > 0 else None


def _result_text(value: Mapping[str, object], key: str) -> str | None:
    candidate = value.get(key)
    return candidate if isinstance(candidate, str) and candidate else None


def _fail_recursive_parent(
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
    reason: str,
) -> RunState:
    """Stop stage advancement while retaining completed sibling results."""
    before_phase = _phase_from_state(state)
    state = store.checkpoint(
        _failure_phase(state, reason),
        state.slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=state.integration,
    )
    _emit_phase_change(
        store.run_id,
        before_phase,
        _phase_from_state(state),
        config,
        effects,
        effects_log,
    )
    return state


def _validate_stage_event_routes(tasks: Sequence[SubTLTask]) -> None:
    """Require independent cursors for concurrent children that consume events."""
    consuming = [task for task in tasks if _plan_consumes_events(task.plan)]
    if len(consuming) < 2:
        return
    if any(task.source is None for task in consuming):
        raise TLLoopError("same-order sub-TLs that consume events require isolated sources")
    if len({id(task.source) for task in consuming}) != len(consuming):
        raise TLLoopError("same-order sub-TLs cannot share an event source")


def _plan_consumes_events(plan: WorkPlan | Mapping[str, object]) -> bool:
    """Return whether a child can consume a projected event stream."""
    if isinstance(plan, WorkPlan):
        return bool(plan.workers or plan.leaves or plan.sub_tls)
    return bool(plan.get("workers") or plan.get("leaves") or plan.get("sub_tls"))


def _parent_generation_id(store: RunStore) -> str | None:
    """The generation a child inherits, or None when the parent has no state yet.

    A child run's generation must differ from its predecessor's when the parent
    is recreated, and the parent's own ``generation_id`` is what changes. A
    parent with no checkpoint yet carries no generation, so the child mints from
    its own scope name exactly as it always did; that keeps provisioning a
    child before the parent state exists working unchanged.
    """
    if not store.path.exists():
        return None
    return store.load().generation_id


def _child_config(
    config: TLLoopConfig,
    task: SubTLTask,
    source: EventQueue,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    branch: str,
    worktree: str,
    *,
    keep_alive_on_waiting: bool = False,
    ordered_recovery: bool = False,
) -> TLLoopConfig:
    child_effects = _owner_effect_client(effects, task.agent_id or task.name)
    return replace(
        config,
        source=task.source or source,
        effects=task.effects or child_effects,
        root_dir=store.run_dir,
        run_id=task.name,
        branch=branch,
        worktree=worktree,
        parent_branch=config.branch,
        parent_run_id=store.run_id,
        parent_agent_id=config.agent_id or store.run_id,
        parent_generation_id=_parent_generation_id(store),
        agent_id=task.agent_id or task.name,
        working_dir=worktree,
        depth=config.depth + 1,
        dispatch_names={},
        ordered_recovery_child=None,
        ordered_recovery=ordered_recovery,
        keep_alive_on_waiting=keep_alive_on_waiting,
        declared_manifest=_declared_child_manifest(store, task),
    )


def _owner_effect_client(
    effects: EffectClient | ReadOnlyEffectClient, owner_name: str
) -> EffectClient | ReadOnlyEffectClient:
    """Bind live effect calls to the persistent child controller identity."""
    if not isinstance(effects, EffectClient):
        return effects
    return EffectClient(effects.transport, role=effects.role, name=owner_name)


def _park_schedule_deadlock(
    error: ScheduleDeadlock,
    state: RunState,
    config: TLLoopConfig,
    live: EffectClient | None,
    store: RunStore,
) -> None:
    if not config.active:
        return
    if live is None:
        raise TLLoopError("active loop has no effect client for escalation")
    blocked_id = error.blocked_slices[0]
    slice_state = state.slices.get(blocked_id)
    if slice_state is None:
        raise TLLoopError(f"deadlock references missing slice {blocked_id!r}")
    park(
        slice_state,
        ParkCause.SCHEDULE_DEADLOCK,
        store=store,
        issue_creator=live,
        ledger=state.budgets,
    )


def _reopens_dispatch_pass(plan: WorkPlan, config: TLLoopConfig) -> bool:
    """Whether one consumed event may open a fresh dispatch pass.

    A policy-owned width ceiling already makes dispatch a per-event decision,
    because a completion frees a slot another pending slice may take. A plan
    with declared dependency edges needs the same per-event re-evaluation for a
    different reason: a dependent becomes dispatchable only once its
    prerequisite merges, which is exactly the event that was just consumed. A
    plan with neither shape keeps its single up-front dispatch pass.
    """
    if config.policy is not None and config.max_parallel_slices is not None:
        return True
    return any(leaf.depends_on for leaf in plan.leaves)


def _can_dispatch(name: str, state: RunState, config: TLLoopConfig) -> bool:
    if not dependencies_satisfied(state.slices, name):
        return False
    if config.policy is None or config.max_parallel_slices is None:
        return True
    return name in {
        slice_state.id for slice_state in ready(state.slices, config.max_parallel_slices)
    }


#: Statuses that prove no dispatch has acted on a slice's declared dependency
#: edges yet. A slice outside this set has left the queue, so a manifest
#: revision may not rewire it.
_UNDISPATCHED_STATUSES = frozenset({SliceStatus.PENDING, SliceStatus.READY})


def _recorded_dependencies(value: Mapping[str, object]) -> list[str]:
    """Read the edges one durable slice record currently carries.

    This only compares a record against the manifest; the record's own shape is
    proven by the state schema, so an absent or unusable value simply reads as
    "no recorded edge" rather than raising here.
    """
    raw = value.get("depends_on", ())
    if not isinstance(raw, Sequence) or isinstance(raw, (str, bytes)):
        return []
    return [item for item in raw if isinstance(item, str)]


def _already_dispatched(name: str, state: RunState) -> bool:
    current = state.slices.get(name)
    return current is not None and current.status is not SliceStatus.PENDING


#: Every ``SelectionFailure`` that can park a slice, and the typed cause it parks
#: with. A refused request and an exhausted budget are different operator actions,
#: so they are different causes rather than one generic "no harness" park.
_SELECTION_PARK_CAUSES: MappingProxyType = MappingProxyType(
    {
        SelectionFailure.OVER_BUDGET: ParkCause.BUDGET_EXHAUSTED,
        SelectionFailure.NO_CAPABLE_HARNESS: ParkCause.NO_CAPABLE_HARNESS,
        SelectionFailure.REQUEST_NOT_ALLOWED: ParkCause.HARNESS_REQUEST_NOT_ALLOWED,
        SelectionFailure.REQUEST_NOT_CAPABLE: ParkCause.NO_CAPABLE_HARNESS,
        SelectionFailure.REQUEST_SUPERSEDED_BY_ESCALATION: (ParkCause.HARNESS_REQUEST_SUPERSEDED),
    }
)


def _selection_refusal(
    failure: SelectionFailure,
    requested: str | None,
    role: str,
    policy: HarnessPolicy,
) -> str:
    """Explain one refusal in the operator's terms, naming the request."""
    if requested is None:
        return f"{failure.value}: no {role} harness is both capable and within budget"
    allowed = ", ".join(policy.roles[role].allow) if role in policy.roles else "<no role policy>"
    return (
        f"{failure.value}: requested harness {requested!r} is not selectable for role "
        f"{role!r}; policy allows {allowed}"
    )


def _prepare_spawn(
    name: str,
    state: RunState,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    effects_log: list[EffectIntent],
) -> DispatchAttempt:
    intent = _new_dispatch_attempt(state, name, config)
    if config.policy is None:
        current = state.slices.get(name)
        if current is None:
            raise TLLoopError(f"dispatch slice {name!r} is missing from run state")
        if (
            current.dispatch_uses_current_role_configuration
            and current.requested_harness is not None
        ):
            raise TLLoopError(
                "pre-execution retry requires the current validated role policy; refusing to reuse the historical harness request"
            )
        direct = _resolve_direct_request(current.requested_harness)
        if direct is not None:
            intent = intent.routed(
                harness=direct.harness,
                agent_type=direct.agent_type,
                model=direct.model,
                requested_harness=current.requested_harness,
            )
        updated = slice_transition(current, SliceStatusChanged(SliceStatus.DISPATCHING))
        updated = replace(
            updated,
            agent_type=intent.agent_type or None,
            resolved_harness=intent.harness or None,
            attempts=current.attempts + 1,
            dispatch_intent_id=intent.intent_id,
            dispatch_started_at=intent.started_at,
            dispatch_last_boundary="dispatch_intended",
            dispatch_error=None,
            dispatch_error_code=None,
            dispatch_ledger_floor=intent.ledger_floor,
            dispatch_generation=intent.dispatch_generation,
            dispatch_next_attempt_at=None,
            dispatch_retry_for_attempt=0,
            dispatch_agent_id=None,
            dispatch_invocation_id=None,
            dispatch_authoritative_event_seq=None,
            park_cause=None,
        )
        state = store.checkpoint(
            state.fsm,
            {**state.slices, name: updated},
            state.budgets,
            state.events.last_consumed_offset,
        )
        _record_dispatch_intent(name, intent, config, effects, effects_log)
        return intent
    slice_state = state.slices.get(name)
    if slice_state is None:
        raise TLLoopError(f"selector slice {name!r} is missing from run state")
    capabilities = config.capabilities or load_capability()
    requested = (
        None
        if slice_state.dispatch_uses_current_role_configuration
        else slice_state.requested_harness
    )
    choice = select_agent_type(
        slice_state,
        config.role,
        state.budgets,
        config.policy,
        capabilities,
        config.learned_policy,
        requested_harness=requested,
    )
    if choice is None:
        failure = selection_failure(
            slice_state,
            config.role,
            state.budgets,
            config.policy,
            capabilities,
            requested_harness=requested,
        )
        cause = _SELECTION_PARK_CAUSES.get(failure)
        if cause is None:
            raise TLLoopError(f"cannot select harness for {name!r}: {failure.value}")
        if config.active:
            live = cast(EffectClient, effects)
            park(
                slice_state,
                cause,
                store=store,
                issue_creator=live,
                ledger=state.budgets,
                audit={
                    "reason": _selection_refusal(failure, requested, config.role, config.policy)
                },
            )
        raise TLLoopError(f"cannot select harness for {name!r}: {failure.value}; slice parked")
    route = parse_harness_identifier(choice.harness)
    if config.catalog is not None:
        if config.requested_model:
            model_id = select_model(choice.harness, config.catalog, config.requested_model).model_id
        else:
            model_id = select_model_for_difficulty(
                choice.harness,
                config.catalog,
                choice.difficulty,
                escalated=choice.reason == "escalated_after_no_go",
            ).model_id
    else:
        model_id = route.model

    # Only the selected route is attached here. The intent identity, its
    # ledger floor, and the controller epoch and dispatch generation this
    # attempt was minted with are carried through by construction, so a
    # policy-path dispatch records the same provenance as a direct one.
    intent = intent.routed(
        harness=choice.harness,
        agent_type=route.agent_type,
        model=model_id,
        requested_harness=slice_state.requested_harness,
        route_reconciliation_source=(
            "proven_preexecution_retry"
            if slice_state.dispatch_uses_current_role_configuration
            else None
        ),
    )

    def record_spawn(document: dict[str, object]) -> dict[str, object]:
        slices = document.get("slices")
        if not isinstance(slices, dict):
            raise TLLoopError("run state slices are not an object")
        raw_slice = slices.get(name)
        if not isinstance(raw_slice, dict):
            raise TLLoopError(f"selector slice {name!r} is not an object")
        dispatched = slice_transition(slice_state, SliceStatusChanged(SliceStatus.DISPATCHING))
        raw_slice.update(
            {
                "status": dispatched.status.value,
                "agent_type": route.agent_type,
                # The resolved route and the plan request are persisted as two
                # independent facts. A reader can tell a request that policy
                # narrowed from one it honored verbatim, and a restart replays
                # the request rather than mistaking it for the executed route.
                "resolved_harness": choice.harness,
                "model": model_id,
                "attempts": slice_state.attempts + 1,
                "dispatch_intent_id": intent.intent_id,
                "dispatch_started_at": intent.started_at,
                "dispatch_last_boundary": "dispatch_intended",
                "dispatch_error": None,
                "dispatch_error_code": None,
                "dispatch_ledger_floor": intent.ledger_floor,
                "dispatch_generation": intent.dispatch_generation,
                "dispatch_next_attempt_at": None,
                "dispatch_retry_for_attempt": 0,
                "dispatch_agent_id": None,
                "dispatch_invocation_id": None,
                "dispatch_authoritative_event_seq": None,
                "park_cause": None,
            }
        )
        return document

    apply_spawn_and_charge(store.run_dir, choice, slice_state, record_spawn)
    LOGGER.info(
        "[TL loop] selection target=%s harness=%s model=%s estimate=%d",
        name,
        choice.harness,
        model_id or "unresolved",
        choice.estimated_cost,
    )
    _record_dispatch_intent(name, intent, config, effects, effects_log)
    return intent


def _new_dispatch_attempt(state: RunState, name: str, config: TLLoopConfig) -> DispatchAttempt:
    current = state.slices.get(name)
    attempt = (current.attempts if current is not None else 0) + 1
    # Keep the public intent stable for legacy event readers. The controller
    # epoch and generation are part of the persisted dispatch payload and
    # journal key, so a recreated controller cannot adopt the old observation.
    # The identity also names the run *generation* this state was created in:
    # `agent.spawned` is the only row that can confirm a dispatch, it carries
    # the intent and nothing else that tells two generations apart, and a new
    # run re-reads the shared ledger from its start. Without a generation in
    # the identity the same run id, slice and attempt mint one intent in both
    # generations, and the predecessor's spawn row confirms the recreated
    # dispatch with the predecessor's owner.
    #
    # The generation is written once, when the run state is created, and never
    # rewritten -- unlike `controller_epoch`, which `exomonad init` re-mints on
    # every launch (`--continue` included) and the driver adopts, so naming the
    # live epoch would re-mint a different intent for an attempt that is still
    # in flight. A state that predates the field falls back to the empty
    # generation: stable for that state, and distinct from any state that has
    # one.
    intent_id = _dispatch_intent_id_for(state, name, attempt)
    started_at = time.time() if config.active else 0.0
    return DispatchAttempt(
        intent_id,
        started_at,
        "",
        attempt=attempt,
        controller_epoch=state.controller_epoch,
        dispatch_generation=attempt if state.controller_epoch is not None else 0,
        ledger_floor=state.events.last_consumed_offset,
    )


def _controller_epoch(root_dir: Path, run_id: str, parent_generation_id: str | None = None) -> str:
    """Read the init-owned epoch marker, with a deterministic first-run value.

    A nested run is never ``init``-launched, so its first epoch is minted here
    rather than by the operator. Seeding that from ``run_id`` alone made the
    value a function of the *name* rather than of the run: a nested run's marker
    lives inside its parent run directory, which a confirmed recreate replaces
    wholesale, so the recreated child re-minted the identical epoch. Identical
    epochs mean an identical ``generation_id``, which means an identical
    dispatch intent identity -- and the predecessor generation's ``agent.spawned``
    row then confirmed the recreated dispatch with the *dead* invocation. That
    bound the pre-recreate publication instead of the current one, so a leaf
    dispatched under a child sub-TL never progressed past ``spawned``.

    Seeding from the parent generation distinguishes the two: the parent's
    generation changes on a recreate, so its child inherits a new one.
    """
    marker = Path(root_dir) / f"{run_id}.controller-epoch"
    try:
        value = marker.read_text(encoding="utf-8").strip()
    except (OSError, UnicodeError):
        value = ""
    if value:
        return value
    seed = f"controller:{run_id}"
    if parent_generation_id:
        seed = f"{seed}:{parent_generation_id}"
    value = hashlib.sha256(seed.encode()).hexdigest()[:32]
    try:
        marker.parent.mkdir(parents=True, exist_ok=True)
        marker.write_text(value + "\n", encoding="utf-8")
    except OSError:
        LOGGER.warning("unable to persist controller epoch marker path=%s", marker)
    return value


def _worker_call(
    task: WorkerTask,
    selected_agent_type: str | None,
    selected_model: str | None,
    intent_id: str | None,
    runtime_name: str | None = None,
) -> Callable[[EffectClient], ToolResult]:
    def invoke(client: EffectClient) -> ToolResult:
        return client.spawn_worker(
            name=runtime_name or task.name,
            task=task.task,
            intent_id=intent_id,
            agent_type=selected_agent_type or task.agent_type,
            model=selected_model,
        )

    return invoke


def _leaf_call(
    task: LeafTask,
    selected_agent_type: str | None,
    selected_model: str | None,
    intent_id: str | None,
    runtime_name: str | None = None,
) -> Callable[[EffectClient], ToolResult]:
    def invoke(client: EffectClient) -> ToolResult:
        return client.spawn_leaf(
            name=runtime_name or task.name,
            task=task.task,
            intent_id=intent_id,
            agent_type=selected_agent_type or task.agent_type,
            model=selected_model,
            boundary=task.boundary,
            context=task.context,
            read_first=task.read_first,
            steps=task.steps,
            verify=task.verify,
        )

    return invoke


def _emit_merge_decision(
    slice_id: str,
    pr_number: int,
    decision: str,
    head_sha: str | None,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    _record_controller_event(
        "controller",
        "tl.merge_decided",
        {
            "slice_id": slice_id,
            "pr_number": pr_number,
            "decision": decision,
            "head_sha_hash": _hash_head_sha(head_sha),
        },
        config,
        effects,
        effects_log,
    )


def _hash_head_sha(head_sha: str | None) -> str:
    if head_sha is None:
        return "missing"
    return hashlib.sha256(head_sha.encode("utf-8")).hexdigest()


def _discard_review(slices: Mapping[str, SliceState], slice_id: str) -> dict[str, SliceState]:
    current = slices.get(slice_id)
    if current is None:
        return dict(slices)
    discarded = slice_transition(current, ReviewDiscarded())
    return {
        **slices,
        slice_id: discarded,
    }


def _record_review_event(
    store: RunStore,
    state: RunState,
    phase: PhaseValue,
    event: EventEnvelope,
    event_seq: int,
) -> RunState:
    slice_id = _review_slice_id(event, state)
    if slice_id is None:
        raise TLLoopError(f"{event.event_type!r} has no slice identity")
    current = state.slices.get(slice_id)
    if current is None:
        raise TLLoopError(f"review event references unknown slice {slice_id!r}")
    findings = _event_findings(event)
    if event.head_sha is None:
        if findings is not None:
            raise TLLoopError(f"{event.event_type!r} findings have no head SHA")
        return store.checkpoint(phase, state.slices, state.budgets, event_seq)
    review_findings = _review_findings(current, event.head_sha, findings)
    patch_digest = _event_patch_digest(event)
    patch_digests = dict(current.review_patch_digests)
    if patch_digest is not None:
        patch_digests[event.head_sha] = patch_digest
    stall_classification = _event_stall_classification(event)
    if current.reviewed_head is not None and current.reviewed_head != event.head_sha:
        updated = dict(state.slices)
        updated[slice_id] = replace(
            current,
            review_findings=review_findings,
            review_patch_digests=patch_digests,
        )
        return store.checkpoint(phase, updated, state.budgets, event_seq)
    verdict = _review_verdict(event)
    if verdict in {Verdict.GO, Verdict.GO_WITH_NITS} and not _reviewer_identity_authorized(
        event,
        current,
        strict=event.event_type == "pr.review" and "verdict" in event.data,
    ):
        LOGGER.warning(
            "[TL loop] ignoring unauthorized approval evidence target=%s agent=%s",
            slice_id,
            event.agent_id,
        )
        verdict = None
    if verdict is None:
        updated = dict(state.slices)
        updated[slice_id] = replace(
            slice_transition(
                current,
                StallClassificationObserved(stall_classification or current.stall_classification),
            ),
            pr_number=event.pr_number or current.pr_number,
            review_findings=review_findings,
            review_patch_digests=patch_digests,
        )
        return store.checkpoint(phase, updated, state.budgets, event_seq)
    updated = dict(state.slices)
    transitioned = slice_transition(
        current,
        ReviewVerdictObserved(
            head_sha=event.head_sha,
            verdict=verdict,
            reviewer_agent_id=current.reviewer_agent_id,
            review_id=event.data.get("review_id")
            if type(event.data.get("review_id")) is int
            else None,
            findings=tuple(findings or ()),
            source="ledger",
            pr_number=event.pr_number,
            reviewer_account_authenticated=event.data.get("reviewer_account_authenticated") is True,
            reviewer_identity_unresolved=event.data.get("reviewer_identity_unresolved")
            is not False,
            self_approval=(
                event.agent_id is not None and event.agent_id == current.dispatch_agent_id
            ),
            stall_classification=stall_classification or current.stall_classification,
            requires_authenticated_evidence=False,
            increment_round=not (
                current.reviewed_head == event.head_sha and current.verdict is not None
            ),
            next_status=(
                SliceStatus.IN_REVIEW
                if current.status is SliceStatus.REPAIRING and _is_aggregate_slice(current)
                else None
            ),
            submitted_at=_review_event_submitted_at(event),
            validated_at=(
                event.data.get("validated_at")
                if isinstance(event.data.get("validated_at"), str)
                else event.observed_at
            ),
            observed_at=event.observed_at,
            dismissed=event.data.get("dismissed") is True,
            forgejo_stale=event.data.get("forgejo_stale") is True,
        ),
    )
    updated[slice_id] = replace(
        transitioned,
        pr_number=event.pr_number or current.pr_number,
        verdict_at=event.observed_at,
        review_findings=review_findings,
        review_patch_digests=patch_digests,
    )
    return store.checkpoint(phase, updated, state.budgets, event_seq)


def _review_workflow_enabled(config: TLLoopConfig) -> bool:
    return config.active and config.review_model_choice is not None


def _reviewer_max_rounds(path: str | Path | None) -> int | None:
    """Load the configured review ceiling for controller convergence."""
    if path is None:
        return None
    return load_reviewer_max_rounds(path)


def _review_policy_for_state(
    state: RunState,
    path: str | Path | None,
    store: RunStore,
) -> ReviewPolicySnapshot:
    """Resolve review policy once, then reuse the persisted snapshot on restart."""
    if state.reviewer_max_rounds_source is not None:
        return ReviewPolicySnapshot(
            state.reviewer_max_rounds,
            state.reviewer_max_rounds_source,
        )
    resolved = load_reviewer_policy_snapshot(path)
    store.set_review_policy(resolved.reviewer_max_rounds, resolved.source)
    return resolved


def _reviewer_identity_authorized(
    event: EventEnvelope,
    current: SliceState,
    *,
    strict: bool = False,
) -> bool:
    """Accept authorized reviewer/human evidence, never a worker self-approval."""
    if strict:
        if current.pr_number is not None and event.pr_number != current.pr_number:
            return False
        if event.head_sha is None:
            return False
        if current.reviewed_head is not None and current.reviewed_head != event.head_sha:
            return False
        if current.handoff is not None and current.handoff.head_sha != event.head_sha:
            return False
        if (
            current.handoff is not None
            and current.pr_number is not None
            and current.handoff.pr_number != current.pr_number
        ):
            return False
        if not _review_evidence_matches_exact_head(event, event.head_sha):
            return False
        reviewer_agent_id = event.data.get("reviewer_agent_id")
        if current.reviewer_agent_id is not None:
            return reviewer_agent_id == current.reviewer_agent_id
        if current.reviewer_attempt.get(event.head_sha, 0) <= 0:
            return False
        return reviewer_agent_id != current.dispatch_agent_id
    actor_role = event.role or event.data.get("actor_role") or event.data.get("actor_type")
    if isinstance(actor_role, str):
        normalized = actor_role.strip().lower()
        if normalized in {"worker", "dev", "developer", "agent"}:
            return False
        if normalized in {"reviewer", "human", "operator"}:
            return True
    actor_id = event.agent_id
    owner_id = current.dispatch_agent_id
    if owner_id is not None and actor_id == owner_id:
        return False
    return actor_id is not None


def _review_evidence_matches_exact_head(event: EventEnvelope, head_sha: str) -> bool:
    """Validate watcher proof for one exact-head reviewer decision.

    ``reviewer_agent_id`` is the durable invocation assigned to the slice; it
    is not a Forgejo login.  The Rust watcher only emits
    ``reviewer_account_authenticated`` after the review author matched the
    configured shared reviewer token and the exact-head invocation lookup
    succeeded.  Keep that proof separate from the assignment binding.
    """
    if event.data.get("review_head_sha") != head_sha:
        return False
    review_id = event.data.get("review_id")
    if type(review_id) is not int or review_id <= 0:
        return False
    if "reviewer_agent_id" in event.data:
        reviewer_agent_id = event.data.get("reviewer_agent_id")
        if not isinstance(reviewer_agent_id, str) or not reviewer_agent_id:
            return False
    else:
        return False
    if event.data.get("reviewer_account_authenticated") is not True:
        return False
    if "reviewer_identity_error" in event.data and event.data.get("reviewer_identity_error"):
        return False
    return event.data.get("reviewer_identity_unresolved") is False


def _review_slice_id(event: EventEnvelope, state: RunState) -> str | None:
    return resolve_event_slice(event, state).slice_id


#: Every dispatch boundary a persisted sub-TL aggregate owner can carry. The
#: integration paths overwrite the label the publication wrote, so recognising
#: only ``aggregate_pr_open`` loses the owner's identity the moment its base or
#: head evidence is invalidated -- and an aggregate whose review is no longer
#: bound is one whose approval is re-derived as a first review instead.
_AGGREGATE_DISPATCH_BOUNDARIES: frozenset[str] = frozenset(
    {
        "aggregate_pr_open",
        "base_revalidation",
        "integration_revalidation",
        "integration_conflict",
        "integration_gate",
    }
)


def _is_aggregate_slice(slice_state: SliceState) -> bool:
    """Identify a persisted sub-TL aggregate owner without trusting event text."""
    return slice_state.dispatch_agent_id is not None and (
        slice_state.dispatch_last_boundary in _AGGREGATE_DISPATCH_BOUNDARIES
        or slice_state.dispatch_agent_id.endswith(":integration")
    )


def _event_review_head(event: EventEnvelope) -> str | None:
    """Return the head a review is about, wherever the row carries it.

    The watcher's ``pr.review`` row names the reviewed head twice: as the
    envelope's own ``head_sha`` and, authoritatively, inside the event data
    alongside ``review_head_sha``. Reading only the envelope field made the
    repeated-verdict guard compare against a value the row never set, so a
    review the slice already held was re-derived from scratch -- and a
    re-derived approval demands findings a clean approval has none of.
    """
    for key in ("head_sha", "review_head_sha"):
        value = event.data.get(key)
        if isinstance(value, str) and value:
            return value
    return event.head_sha


def _event_findings(event: EventEnvelope) -> list[dict[str, str]] | None:
    if "findings" not in event.data:
        return None
    raw_findings = event.data["findings"]
    if not isinstance(raw_findings, list):
        raise TLLoopError(f"{event.event_type!r} findings must be an array")
    findings: list[dict[str, str]] = []
    for index, raw_finding in enumerate(raw_findings):
        if not isinstance(raw_finding, Mapping):
            raise TLLoopError(f"{event.event_type!r} findings[{index}] must be an object")
        finding: dict[str, str] = {}
        for key in ("severity", "path", "rationale"):
            value = raw_finding.get(key)
            if not isinstance(value, str) or not value.strip():
                raise TLLoopError(f"{event.event_type!r} findings[{index}].{key} must be non-empty")
            finding[key] = value
        findings.append(finding)
    return findings


def _event_patch_digest(event: EventEnvelope) -> str | None:
    """Persist only a patch hash when the event carries patch material."""
    explicit = event.data.get("patch_digest")
    if isinstance(explicit, str) and explicit:
        return explicit
    patch = event.data.get("diff", event.data.get("patch"))
    if patch is None:
        return None
    return hashlib.sha256(repr(patch).encode("utf-8")).hexdigest()


def _review_findings(
    current: SliceState,
    head_sha: str,
    findings: list[dict[str, str]] | None,
) -> Mapping[str, tuple[Mapping[str, str], ...]]:
    updated = dict(current.review_findings)
    if findings is not None:
        updated[head_sha] = tuple(findings)
    return updated


def _event_stall_classification(event: EventEnvelope) -> str | None:
    classification = event.stall_classification
    return classification.value if classification is not None else None


def _route_review_event(
    plan: WorkPlan,
    store: RunStore,
    state: RunState,
    phase: PhaseValue,
    event: EventEnvelope,
    event_seq: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    *,
    allow_lifecycle_effects: bool = True,
    reconcile_deferred: bool = False,
) -> RunState:
    slice_id = _review_slice_id(event, state)
    if slice_id is None:
        raise TLLoopError(f"{event.event_type!r} has no slice identity")
    current = state.slices.get(slice_id)
    if current is None:
        raise TLLoopError(f"review event references unknown slice {slice_id!r}")
    if _is_aggregate_slice(current):
        LOGGER.info(
            "[TL loop] ignoring unsupported parent aggregate review event slice=%s pr=%s",
            slice_id,
            event.pr_number,
        )
        return state
    head_sha = _event_review_head(event)
    findings = _event_findings(event)
    if head_sha is None:
        raise TLLoopError(f"{event.event_type!r} findings have no head SHA")
    incoming_verdict = _review_verdict(event)
    if (
        incoming_verdict is not None
        and current.reviewed_head == head_sha
        and current.verdict is not None
        and not reconcile_deferred
    ):
        incoming_review_id = event.data.get("review_id")
        existing_review_id = (
            current.review_evidence.review_id if current.review_evidence is not None else None
        )
        if existing_review_id is not None and not (
            type(incoming_review_id) is int and incoming_review_id > existing_review_id
        ):
            LOGGER.info(
                "[TL loop] ignoring repeated reviewer verdict target=%s head=%s existing=%s incoming=%s",
                slice_id,
                head_sha,
                current.verdict.value,
                incoming_verdict.value,
            )
            return state
    review_findings = _review_findings(current, head_sha, findings)
    patch_digest = _event_patch_digest(event)
    patch_digests = dict(current.review_patch_digests)
    if patch_digest is not None:
        patch_digests[head_sha] = patch_digest
    stall_classification = _event_stall_classification(event)
    if findings is None:
        LOGGER.warning(
            "[TL loop] ignoring review without binding findings target=%s head=%s",
            slice_id,
            head_sha,
        )
        updated = dict(state.slices)
        updated[slice_id] = replace(
            slice_transition(
                current,
                StallClassificationObserved(stall_classification or current.stall_classification),
            ),
            review_findings=review_findings,
            review_patch_digests=patch_digests,
        )
        return store.checkpoint(phase, updated, state.budgets, event_seq)
    if (
        current.reviewed_head is not None
        and current.reviewed_head != head_sha
        and not _is_aggregate_slice(current)
    ):
        LOGGER.warning(
            "[TL loop] ignoring stale review target=%s reviewed=%s event=%s",
            slice_id,
            current.reviewed_head,
            head_sha,
        )
        updated = dict(state.slices)
        updated[slice_id] = replace(
            current,
            review_findings=review_findings,
            review_patch_digests=patch_digests,
        )
        return store.checkpoint(phase, updated, state.budgets, event_seq)
    leaf = next((candidate for candidate in plan.leaves if candidate.name == slice_id), None)
    if leaf is None and not _is_aggregate_slice(current):
        raise TLLoopError(f"review event references non-leaf slice {slice_id!r}")
    criteria = compose_acceptance_criteria(current, leaf or {})
    direct_reviewer_event = event.event_type == "pr.review" and "verdict" in event.data
    reviewer_agent_id = current.reviewer_agent_id
    if direct_reviewer_event:
        if not _review_evidence_matches_exact_head(event, head_sha):
            LOGGER.warning(
                "[TL loop] ignoring incomplete exact-head reviewer evidence target=%s head=%s",
                slice_id,
                head_sha,
            )
            return state
        if incoming_verdict is None or not _reviewer_identity_authorized(
            event, current, strict=True
        ):
            LOGGER.warning(
                "[TL loop] ignoring unauthorized reviewer verdict target=%s agent=%s head=%s",
                slice_id,
                event.agent_id,
                head_sha,
            )
            return state
        decision_verdict = incoming_verdict
        decision_head = head_sha
        decision_reasons = tuple(
            {
                "severity": finding["severity"],
                "file": finding["path"],
                "line": 0,
                "claim": finding["rationale"],
            }
            for finding in findings
        )
        if reviewer_agent_id is None:
            reviewer_agent_id = event.data.get("reviewer_agent_id")
    else:
        result = adjudicate_review(
            _review_diff(event),
            findings,
            list(criteria),
            head_sha,
            model_choice=config.review_model_choice,
            policy_path=config.review_policy_path or Path(".exo/review-policy.toml"),
        )
        decision_verdict = result.verdict
        decision_head = result.reviewed_head
        decision_reasons = result.reasons
        if decision_verdict in {
            Verdict.GO,
            Verdict.GO_WITH_NITS,
        } and not _reviewer_identity_authorized(event, current):
            LOGGER.warning(
                "[TL loop] ignoring unauthorized approval evidence target=%s agent=%s",
                slice_id,
                event.agent_id,
            )
            updated = dict(state.slices)
            updated[slice_id] = replace(
                slice_transition(
                    current,
                    StallClassificationObserved(
                        stall_classification or current.stall_classification
                    ),
                ),
                pr_number=event.pr_number or current.pr_number,
                review_findings=review_findings,
                review_patch_digests=patch_digests,
            )
            return store.checkpoint(phase, updated, state.budgets, event_seq)
    review_findings = _persist_adjudication_nits(review_findings, head_sha, decision_reasons)
    updated = dict(state.slices)
    authorized_exact_verdict = (
        decision_verdict in {Verdict.GO, Verdict.GO_WITH_NITS}
        and _reviewer_identity_authorized(
            event,
            current,
            strict=direct_reviewer_event,
        )
        and decision_head == head_sha
    )
    next_stall_classification = (
        None
        if authorized_exact_verdict and current.stall_classification == "reviewer_not_responding"
        else stall_classification or current.stall_classification
    )
    transitioned = slice_transition(
        current,
        ReviewVerdictObserved(
            head_sha=decision_head,
            verdict=decision_verdict,
            reviewer_agent_id=reviewer_agent_id,
            review_id=event.data.get("review_id")
            if type(event.data.get("review_id")) is int
            else None,
            findings=tuple(findings),
            source=(
                "watcher_snapshot" if event.data.get("source") == "watcher_snapshot" else "ledger"
            ),
            pr_number=event.pr_number,
            reviewer_account_authenticated=event.data.get("reviewer_account_authenticated") is True,
            reviewer_identity_unresolved=event.data.get("reviewer_identity_unresolved")
            is not False,
            self_approval=(
                reviewer_agent_id is not None and reviewer_agent_id == current.dispatch_agent_id
            ),
            stall_classification=next_stall_classification,
            requires_authenticated_evidence=direct_reviewer_event,
            submitted_at=_review_event_submitted_at(event),
            validated_at=(
                event.data.get("validated_at")
                if isinstance(event.data.get("validated_at"), str)
                else event.observed_at
            ),
            observed_at=event.observed_at,
            dismissed=event.data.get("dismissed") is True,
            forgejo_stale=event.data.get("forgejo_stale") is True,
        ),
    )
    updated[slice_id] = replace(
        transitioned,
        pr_number=event.pr_number or current.pr_number,
        verdict_at=event.observed_at,
        review_findings=review_findings,
        review_patch_digests=patch_digests,
    )
    state = store.checkpoint(phase, updated, state.budgets, event_seq)
    if decision_verdict is Verdict.NO_GO:
        if not allow_lifecycle_effects or _review_rounds_exhausted(
            state, state.slices[slice_id], config
        ):
            return state
        return _route_repair(
            store,
            state,
            phase,
            event_seq,
            slice_id,
            config,
            effects,
            effects_log,
            _forward_findings_repair(
                {"verdict": decision_verdict.value, "reasons": list(decision_reasons)},
                store,
                state.slices[slice_id],
            ),
        )
    return state


def _persist_adjudication_nits(
    review_findings: Mapping[str, tuple[Mapping[str, str], ...]],
    head_sha: str,
    reasons: Sequence[Mapping[str, object]],
) -> Mapping[str, tuple[Mapping[str, str], ...]]:
    """Store model-identified nits in the durable per-head review evidence."""
    nits = tuple(
        {
            "severity": "nit",
            "path": f"{reason['file']}:{reason['line']}",
            "rationale": str(reason["claim"]),
        }
        for reason in reasons
        if reason.get("severity") == "nit"
    )
    if not nits:
        return review_findings
    existing = list(review_findings.get(head_sha, ()))
    existing.extend(nit for nit in nits if nit not in existing)
    return {**review_findings, head_sha: tuple(existing)}


def _review_diff(event: EventEnvelope) -> Mapping[str, object] | str:
    candidate = event.data.get("diff", event.data.get("patch"))
    if isinstance(candidate, (Mapping, str)):
        return candidate
    if candidate is not None:
        raise TLLoopError(f"{event.event_type!r} diff must be an object or string")
    return event.data


def _route_ci_event(
    store: RunStore,
    state: RunState,
    phase: PhaseValue,
    event: EventEnvelope,
    event_seq: int,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    *,
    allow_lifecycle_effects: bool = True,
    reconcile_deferred: bool = False,
) -> RunState:
    slice_id = _review_slice_id(event, state)
    if slice_id is None:
        raise TLLoopError(f"{event.event_type!r} has no slice identity")
    current = state.slices.get(slice_id)
    if current is None:
        raise TLLoopError(f"CI event references unknown slice {slice_id!r}")
    head_sha = event.head_sha
    if head_sha is None:
        raise TLLoopError(f"{event.event_type!r} has no head SHA")
    status = _ci_status(event)
    candidate = state.integration.candidates.get(slice_id)
    aggregate_head_matches = (
        _is_aggregate_slice(current)
        and candidate is not None
        and candidate.aggregate_head_sha == head_sha
    )
    bound_review_head_matches = current.reviewed_head == head_sha or aggregate_head_matches
    updated = dict(state.slices)
    transitioned = slice_transition(
        current,
        CIStatusObserved(
            head_sha=head_sha,
            status=status,
            observed_at=event.observed_at,
        ),
    )
    updated[slice_id] = replace(
        transitioned,
        pr_number=event.pr_number or current.pr_number,
    )
    state = store.checkpoint(phase, updated, state.budgets, event_seq)
    should_repair = (
        allow_lifecycle_effects
        and config.active
        and status == "failure"
        and bound_review_head_matches
        and current.status is not SliceStatus.REPAIRING
        and (reconcile_deferred or current.ci_state.get(head_sha) != "failure")
    )
    if (
        not should_repair
        and status in {"success", "neutral"}
        and current.status is not SliceStatus.REPAIRING
        and bound_review_head_matches
        and _is_aggregate_slice(current)
    ):
        return _reset_integration_failure_attempts(store, state, slice_id)
    if not should_repair:
        return state
    if _is_aggregate_slice(current):
        parent_branch = event.data.get("branch")
        return _judge_integration_failure(
            slice_id,
            state,
            config,
            effects,
            store,
            effects_log,
            failure_kind="parent_branch_ci_failure",
            reason=_ci_reason(event),
            gate_name=INTEGRATION_FAILURE_GATE_NAME,
            head_sha=head_sha,
            parent_branch=parent_branch if isinstance(parent_branch, str) else None,
        )
    if _review_rounds_exhausted(state, state.slices[slice_id], config):
        return state
    reason = {
        "severity": "blocking",
        "file": _ci_reason_file(event),
        "line": 0,
        "claim": _ci_reason(event),
    }
    return _route_repair(
        store,
        state,
        phase,
        event_seq,
        slice_id,
        config,
        effects,
        effects_log,
        _forward_findings_repair(
            {"verdict": Verdict.NO_GO.value, "reasons": [reason]},
            store,
            state.slices[slice_id],
        ),
    )


def _reset_integration_failure_attempts(
    store: RunStore, state: RunState, slice_id: str
) -> RunState:
    """Start a fresh intervention allowance after aggregate CI recovers."""
    candidate = _candidate_runtime(state.integration, slice_id)
    if candidate.tl_intervention_attempts == 0:
        return state
    reset = replace(candidate, tl_intervention_attempts=0)
    return store.checkpoint(
        _phase_from_state(state),
        state.slices,
        state.budgets,
        state.events.last_consumed_offset,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=_persist_candidate_runtime(state.integration, slice_id, reset),
    )


def _ci_status(event: EventEnvelope) -> str:
    value = event.ci_status
    aliases = {"passed": "success", "error": "failure", "cancelled": "failure"}
    status = aliases.get(value, value)
    if status not in CI_STATUS_VALUES:
        raise TLLoopError(f"{event.event_type!r} has unsupported CI status {value!r}")
    return status


def _ci_reason(event: EventEnvelope) -> str:
    value = event.data.get("message", event.notification)
    if isinstance(value, str) and value.strip():
        return value.strip()
    return "CI reported a failure for the reviewed PR head"


def _ci_reason_file(event: EventEnvelope) -> str:
    value = event.data.get("path")
    return value.strip() if isinstance(value, str) and value.strip() else "CI"


def _route_repair(
    store: RunStore,
    state: RunState,
    phase: PhaseValue,
    event_seq: int,
    slice_id: str,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
    repair_with: RepairWith,
    *,
    aggregate_repair: bool = False,
    gate_name_on_failure: str | None = None,
) -> RunState:
    """Resume the slice's existing PR owner through ``repair_with``.

    ``repair_with`` decides what the handoff says; the same-owner ``resume_pr``
    dispatch and the REPAIRING checkpoint are shared by every repair path.
    Integration judgments can route a failed dispatch to their own gate.
    """
    current = state.slices.get(slice_id)
    if current is None or current.pr_number is None:
        raise TLLoopError(f"repair event references slice without PR {slice_id!r}")
    expected_head_sha = (
        _candidate_runtime(state.integration, slice_id).head_sha
        if aggregate_repair
        else current.reviewed_head
    )
    repair_arguments = {
        "pr_number": current.pr_number,
        "expected_head_sha": expected_head_sha,
    }
    repair_action = ActionState(
        ActionKind.REPAIR,
        ActionPhase.IN_FLIGHT,
        intent_id=stable_action_key(state.run_id, "resume_pr", slice_id, repair_arguments),
        head_sha=expected_head_sha,
        attempt=max(1, current.attempts),
    )
    repairing = (
        slice_transition(current, SliceStatusChanged(SliceStatus.REPAIRING))
        if aggregate_repair
        else slice_transition(current, RepairQueued())
    )
    repairing = slice_transition(repairing, ActionChanged(repair_action))
    state = store.checkpoint(
        phase,
        {**state.slices, slice_id: repairing},
        state.budgets,
        event_seq,
        current_order=state.current_order,
        ordered_stages=state.ordered_stages,
        integration=state.integration,
    )
    current = state.slices[slice_id]
    live = cast(EffectClient, effects)
    pr = {
        "pr_number": current.pr_number,
        "paths": list(current.paths),
        "slice_id": slice_id,
        "attempts": current.attempts,
    }
    effects_log.append(
        EffectIntent(
            "watcher_pr_state",
            slice_id,
            {"pr_number": current.pr_number},
            True,
        )
    )
    try:

        def dispatch_resume(arguments: JsonObject) -> object:
            resume_arguments = dict(arguments)
            reset_key = current.task_budget_reset_key
            task = resume_arguments.get("task")
            if isinstance(task, str):
                generation_seed = "\0".join(
                    (
                        state.run_id,
                        slice_id,
                        str(event_seq),
                        str(current.attempts),
                        str(current.repair_attempts),
                        reset_key or "",
                    )
                )
                recovery_generation = hashlib.sha256(generation_seed.encode("utf-8")).hexdigest()[
                    :16
                ]
                recovery_kind = (
                    "Operator-authorized execution-budget recovery"
                    if reset_key is not None
                    else "Repair dispatch generation"
                )
                resume_arguments["task"] = (
                    f"{task}\n\n{recovery_kind} {recovery_generation}: "
                    f"continue the existing PR #{current.pr_number} "
                    "in the same owner worktree and branch; do not create another PR."
                )
            return _invoke(
                "resume_pr",
                slice_id,
                resume_arguments,
                True,
                live,
                lambda client: client.resume_pr(**resume_arguments),
                effects_log,
                raise_on_failure=False,
            )

        repair_with(pr, live, dispatch_resume)
    except (RepairError, ValueError) as error:
        if gate_name_on_failure is not None:
            return _open_integration_gate(
                slice_id,
                state,
                config,
                effects,
                store,
                effects_log,
                gate_name=gate_name_on_failure,
                lifecycle=IntegrationLifecycle.INTEGRATION_CONFLICT,
                reason=f"integration repair dispatch failed: {error}",
            )
        return _park_repair_failed(
            store, state, current, event_seq, error, config, effects, effects_log
        )
    refreshed = store.load()
    resumed = slice_transition(
        refreshed.slices[slice_id],
        ActionChanged(replace(repair_action, phase=ActionPhase.CONFIRMED)),
    )
    # A successful same-owner resume starts a fresh execution budget. Reusing
    # the original dispatch timestamp can make the heartbeat immediately time
    # out the newly resumed worker after a long parked/review interval.
    resumed = replace(resumed, dispatch_started_at=time.time())
    return store.checkpoint(
        phase,
        {**refreshed.slices, slice_id: resumed},
        refreshed.budgets,
        event_seq,
        current_order=refreshed.current_order,
        ordered_stages=refreshed.ordered_stages,
        integration=refreshed.integration,
    )


def _park_repair_failed(
    store: RunStore,
    state: RunState,
    current: SliceState,
    event_seq: int,
    error: Exception,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> RunState:
    """Park a slice whose repair or review-stuck judgment failed, with the cause recorded."""
    slice_id = current.id
    parked = slice_transition(
        slice_transition(current, SliceStatusChanged(SliceStatus.PARKED)),
        ActionChanged(None),
    )
    parked = slice_transition(parked, StallClassificationObserved("review_stuck"))
    parked = replace(
        parked,
        park_cause=ParkCause.REVIEW_STUCK,
        dispatch_last_boundary="repair_exhausted",
        dispatch_error=str(error)[:500],
    )
    remaining = {
        waiting_id: ChildHandle(
            waiting_id,
            state.slices[waiting_id].branch or "",
            state.slices[waiting_id].agent_type or "unknown",
        )
        for waiting_id in state.fsm.waiting
        if waiting_id != slice_id
        and state.slices[waiting_id].status
        in {SliceStatus.SPAWNED, SliceStatus.IN_REVIEW, SliceStatus.REPAIRING}
    }
    repair_phase: PhaseValue = TLWaiting(remaining) if remaining else TLPlanning()
    state = store.checkpoint(
        repair_phase,
        {**state.slices, slice_id: parked},
        state.budgets,
        event_seq,
    )
    _record_controller_event(
        slice_id,
        "tl.slice_parked",
        {
            "slice_id": slice_id,
            "park_cause": ParkCause.REVIEW_STUCK.value,
            "reason": str(error)[:500],
        },
        config,
        effects,
        effects_log,
    )
    return state


def _forward_findings_repair(
    review: object,
    store: RunStore,
    current: SliceState,
) -> RepairWith:
    """Forward the reviewer's or CI's findings verbatim; the inner loop makes no model call."""

    def repair(
        pr: Mapping[str, object],
        live: EffectClient,
        dispatch: Callable[[JsonObject], object],
    ) -> object:
        return forward_review_findings(
            pr,
            Verdict.NO_GO,
            review,
            client=live,
            test_plan=current.test_plan,
            store=store,
            slice_id=current.id,
            dispatch=dispatch,
        )

    return repair


def _guide_repair(
    handoff: RepairHandoff,
    store: RunStore,
    slice_id: str,
) -> RepairWith:
    """Dispatch the roles.tl guide handoff after its owned-path validation."""

    def repair(
        pr: Mapping[str, object],
        live: EffectClient,
        dispatch: Callable[[JsonObject], object],
    ) -> object:
        return dispatch_guide_handoff(
            pr,
            handoff,
            client=live,
            store=store,
            slice_id=slice_id,
            dispatch=dispatch,
        )

    return repair


def _effective_reviewer_max_rounds(state: RunState, config: TLLoopConfig) -> int | None:
    return (
        state.reviewer_max_rounds
        if state.reviewer_max_rounds_source is not None
        else _reviewer_max_rounds(config.review_policy_path)
    )


def _review_rounds_exhausted(state: RunState, current: SliceState, config: TLLoopConfig) -> bool:
    """Whether the inner loop is over and the slice belongs to the review-stuck judgment."""
    max_rounds = _effective_reviewer_max_rounds(state, config)
    return (
        max_rounds is not None
        and current.review_rounds >= max_rounds
        and not _is_aggregate_slice(current)
    )


def _review_verdict(event: EventEnvelope) -> Verdict | None:
    explicit = event.data.get("verdict")
    if isinstance(explicit, str):
        normalized = explicit.strip().upper().replace("_", "-")
        if normalized in {"GO", "APPROVED"}:
            return Verdict.GO
        if normalized in {"GO-WITH-NITS", "APPROVED-WITH-NITS"}:
            return Verdict.GO_WITH_NITS
        if normalized in {"NO-GO", "CHANGES-REQUESTED", "REQUESTED-CHANGES"}:
            return Verdict.NO_GO
    if event.review_kind in {"merge_ready", "approved"}:
        return Verdict.GO
    if event.review_state in {"approved", "approve"}:
        return Verdict.GO
    if event.review_state in {"changes_requested", "request_changes"}:
        return Verdict.NO_GO
    return None


def _emit_phase_change(
    run_id: str,
    before: PhaseValue,
    after: PhaseValue,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    before_tag = _phase_tag(before)
    after_tag = _phase_tag(after)
    if before_tag is after_tag:
        return
    _record_controller_event(
        "controller",
        "tl.phase_changed",
        {
            "from_phase": before_tag.value,
            "to_phase": after_tag.value,
            "run_id": run_id,
        },
        config,
        effects,
        effects_log,
    )


def _emit_slice_status_changes(
    before: Mapping[str, SliceState],
    after: Mapping[str, SliceState],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> None:
    for slice_id in sorted(after):
        current = after[slice_id]
        previous = before.get(slice_id)
        from_status = previous.status if previous is not None else SliceStatus.PENDING
        if from_status is current.status:
            continue
        _record_controller_event(
            slice_id,
            "tl.slice_status_changed",
            {
                "slice_id": slice_id,
                "from_status": from_status.value,
                "to_status": current.status.value,
            },
            config,
            effects,
            effects_log,
        )


def _record_controller_event(
    target: str,
    event_type: str,
    payload: Mapping[str, object],
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    effects_log: list[EffectIntent],
) -> ToolResult | None:
    LOGGER.info(
        "[TL loop] effect=emit_controller_event target=%s event_type=%s active=%s",
        target,
        event_type,
        config.active,
    )
    if isinstance(effects_log, EffectJournal):
        arguments = {"event_type": event_type, "payload": dict(payload)}
        try:
            result = _invoke(
                "emit_controller_event",
                target,
                arguments,
                config.active,
                cast(EffectClient, effects),
                lambda client: client.emit_controller_event(
                    event_type=event_type,
                    payload=cast(JsonObject, dict(payload)),
                ),
                effects_log,
                raise_on_failure=False,
            )
        except DurableWriteError:
            raise
        except Exception as error:  # noqa: BLE001 - observability is fail-open
            LOGGER.warning("controller event %s failed: %s", event_type, error)
            return None
        if result is not None and result.success is False:
            LOGGER.warning(
                "controller event %s failed: %s",
                event_type,
                result.error or "effect returned failure",
            )
        return result
    intent = EffectIntent("emit_controller_event", target, payload, config.active)
    effects_log.append(intent)
    if not config.active:
        return None
    live = cast(EffectClient, effects)
    try:
        result = live.emit_controller_event(
            event_type=event_type,
            payload=cast(JsonObject, dict(payload)),
        )
    except Exception as error:  # noqa: BLE001 - observability is fail-open
        LOGGER.warning("controller event %s failed: %s", event_type, error)
        return None
    if result.success is False:
        LOGGER.warning(
            "controller event %s failed: %s",
            event_type,
            result.error or "effect returned failure",
        )
    return result


def _journal_entries(
    effects_log: list[EffectIntent],
) -> tuple[Mapping[str, object], ...]:
    """Expose journal evidence without allowing callers to mutate it."""
    if not isinstance(effects_log, EffectJournal):
        return ()
    return effects_log.snapshot()


def _invoke(
    operation: str,
    target: str,
    arguments: Mapping[str, object],
    active: bool,
    client: EffectClient | None,
    call: Callable[[EffectClient], ToolResult],
    effects_log: list[EffectIntent],
    *,
    raise_on_failure: bool = True,
    retryable_failure: bool = False,
) -> ToolResult | None:
    intent = EffectIntent(operation, target, arguments, active)
    journal = effects_log if isinstance(effects_log, EffectJournal) else None
    try:
        probe = journal.probe(intent) if journal and operation in MUTATING_OPERATIONS else None
        prior = probe.entry if probe is not None else None
    except DurableWriteError as error:
        raise error.with_context(operation=operation, target=target) from error
    if prior is not None:
        status = prior.get("status")
        if status in {"confirmed", "rejected"}:
            if probe is None or probe.result is None:
                raise TLLoopError(f"journal probe has no result for {operation} {target!r}")
            result = probe.result
            if result.error_kind == "tool_unavailable":
                raise ToolUnavailableError(operation, result, target=target)
            if result.success is False and raise_on_failure:
                detail = result.error or f"{operation} returned failure"
                raise EffectFailed(f"{operation} for {target!r}: {detail}")
            return result
        if status == "reconciled":
            raise TLLoopError(
                f"lifecycle effect {operation} for {target!r} was reconciled from external "
                "evidence and must be adopted by its owning state transition"
            )
        if status in {"intended", "unknown"}:
            key = prior.get("key", journal.key_for(intent))
            gate_name = _action_journal_gate_name(key, _action_journal_compensation_attempt(prior))
            raise TLLoopError(
                f"lifecycle effect {operation} for {target!r} has unknown outcome "
                f"and requires reconciliation before retry (key={key}); restart to "
                f"open gate={gate_name}, then answer it with `tl_loop gate --name "
                f"{gate_name} --approve|--reject`"
            )
        if status != "compensated":
            key = prior.get("key", journal.key_for(intent))
            raise TLLoopError(
                f"lifecycle effect {operation} for {target!r} has unrecognized "
                f"action journal status {status!r} (key={key})"
            )
        # An operator-approved _reconcile_action_journal() pass cleared this
        # entry for a fresh attempt; fall through and dispatch as new.
    try:
        effects_log.append(intent)
    except DurableWriteError as error:
        raise error.with_context(operation=operation, target=target) from error
    LOGGER.info("[TL loop] effect=%s target=%s active=%s", operation, target, active)
    if not active:
        if journal is not None:
            try:
                journal.mark_not_dispatched(intent)
            except DurableWriteError as error:
                raise error.with_context(operation=operation, target=target) from error
        return None
    if client is None:
        raise TLLoopError("active loop has no effect client")
    try:
        result = call(client)
    except BaseException as error:
        if journal is not None:
            try:
                journal.mark_unknown(intent, error)
            except DurableWriteError as journal_error:
                raise journal_error.with_context(operation=operation, target=target) from error
        raise
    if journal is not None:
        try:
            if retryable_failure and result.success is not True:
                journal.mark_unknown(
                    intent,
                    RuntimeError(result.error or f"{operation} returned a retryable failure"),
                )
            else:
                journal.mark_result(intent, result)
        except DurableWriteError as error:
            raise error.with_context(operation=operation, target=target) from error
    if result.error_kind == "tool_unavailable":
        raise ToolUnavailableError(operation, result, target=target)
    if result.success is False and raise_on_failure:
        detail = result.error or f"{operation} returned failure"
        raise EffectFailed(f"{operation} for {target!r}: {detail}")
    return result


def _next_event(
    source: EventQueue,
    config: TLLoopConfig,
) -> EventEnvelope | None:
    if config.cancel_event is not None and config.cancel_event.is_set():
        raise LoopCancelled("TL controller cancellation requested")
    timeout = config.poll_interval or 0.01
    try:
        return source.get(timeout=timeout)
    except queue_module.Empty:
        if config.poll_interval == 0:
            time.sleep(0.01)
        return None


@dataclass(frozen=True)
class _TaskBlockedOwner:
    """One persisted scope that owns the blocked slice."""

    store: RunStore
    slice_id: str
    path: tuple[str, ...]
    resolution: IdentityResolution


@dataclass(frozen=True)
class _TaskBlockedScopeIssue:
    """One scope whose aliases did not resolve consistently."""

    reason_code: str
    path: tuple[str, ...]
    state: RunState
    resolution: IdentityResolution


@dataclass(frozen=True)
class _TaskBlockedOwnerLookup:
    """An unambiguous owner or a stable reason that recovery cannot be routed."""

    owner: _TaskBlockedOwner | None = None
    reason_code: str = "owner_not_found"
    candidate_paths: tuple[tuple[str, ...], ...] = ()
    unavailable_paths: tuple[tuple[str, ...], ...] = ()
    candidate_slice_ids: tuple[str, ...] = ()
    reporter_id: str | None = None
    subject_slice_id: str | None = None
    reporter_scope_path: tuple[str, ...] = ()
    reporter_invocation_id: str | None = None
    reporter_generation: int | None = None
    conflicting_aliases: tuple[str, ...] = ()
    missing_proof: tuple[str, ...] = ()


@dataclass(frozen=True)
class _TaskBlockedDisposition:
    """Evidence-based decision made before recovery mutates a child scope."""

    decision: str
    reason_code: str
    proof: tuple[str, ...] = ()
    missing_proof: tuple[str, ...] = ()
    evidence_digest: str | None = None


def _route_task_blocked_event(
    event: EventEnvelope,
    plan: WorkPlan,
    state: RunState,
    event_seq: int,
    replaying: bool,
    diagnostics: EventDiagnostics,
    convergence: ConvergenceTracker,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    source: EventQueue,
    effects_log: list[EffectIntent],
    *,
    allow_lifecycle_effects: bool = True,
) -> tuple[RunState, bool]:
    """Record blocked recovery at its owner before acknowledging the root event."""
    lookup = _resolve_task_blocked_owner(event, state, store)
    owner = lookup.owner
    if owner is None:
        return _park_task_blocked_owner_issue(event, state, store, lookup, diagnostics), False
    try:
        owner_state = owner.store.load()
        identity = resolve_event_slice(event, owner_state)
        if not identity.resolved or identity.slice_id != owner.slice_id:
            raise TLLoopError("task-blocked owner changed during recovery routing")
        disposition = _classify_task_blocked_disposition(
            event,
            owner,
            owner_state,
            lookup,
        )
        if disposition.decision == "unresolved":
            failed = replace(
                lookup,
                reason_code=disposition.reason_code,
                missing_proof=disposition.missing_proof,
            )
            return _park_task_blocked_owner_issue(event, state, store, failed, diagnostics), False
        if disposition.decision == "superseded_by_durable_completion":
            store.record_task_blocked_disposition(
                {
                    "disposition_id": _task_blocked_disposition_id(event),
                    "decision": disposition.decision,
                    "run_seq": event.run_seq,
                    "event_id": event.event_id,
                    "event_type": event.event_type,
                    "reporter_id": event.agent_id,
                    "reporter_scope_path": list(lookup.reporter_scope_path),
                    "subject_slice_id": owner.slice_id,
                    "owner_path": list(owner.path),
                    "attempt": event.task_blocked.attempt if event.task_blocked else None,
                    "proof": list(disposition.proof),
                    "evidence_digest": disposition.evidence_digest,
                }
            )
            return _finish_superseded_nested_task_blocked_event(
                event,
                plan,
                event_seq,
                state,
                convergence,
                config,
                effects,
                store,
                source,
                replaying,
                diagnostics,
                effects_log,
                lookup,
                allow_lifecycle_effects,
            )
        owner_state = _record_task_blocked_recovery(
            event,
            owner_state,
            owner.store,
            _phase_from_state(owner_state),
            max(event_seq, owner_state.events.last_consumed_offset),
            _owner_effect_client(effects, owner.store.run_id),
        )
    except (OSError, ValueError, RuntimeError):
        failed = replace(lookup, reason_code="recovery_record_failed")
        return _park_task_blocked_owner_issue(event, state, store, failed, diagnostics), False
    if owner.store.path == store.path:
        return _finish_local_task_blocked_event(
            event,
            owner_state,
            convergence,
            config,
            effects,
            store,
            source,
            replaying,
            diagnostics,
            effects_log,
            lookup,
            allow_lifecycle_effects,
        )
    return _finish_nested_task_blocked_event(
        event,
        plan,
        event_seq,
        state,
        convergence,
        config,
        effects,
        store,
        source,
        replaying,
        diagnostics,
        effects_log,
        lookup,
        allow_lifecycle_effects,
    )


def _finish_local_task_blocked_event(
    event: EventEnvelope,
    state: RunState,
    convergence: ConvergenceTracker,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    source: EventQueue,
    replaying: bool,
    diagnostics: EventDiagnostics,
    effects_log: list[EffectIntent],
    lookup: _TaskBlockedOwnerLookup,
    allow_lifecycle_effects: bool,
) -> tuple[RunState, bool]:
    """Finish a block owned by this scope, parking convergence write failures."""
    try:
        if allow_lifecycle_effects:
            state = _apply_convergence(state, convergence, store, config, effects, effects_log)
        state = _clear_task_blocked_owner_gate(event, state, store)
    except (OSError, ValueError, RuntimeError):
        failed = replace(lookup, reason_code="owner_convergence_failed")
        return _park_task_blocked_owner_issue(event, state, store, failed, diagnostics), False
    _ack_task_blocked_event(event, source, replaying, diagnostics, store)
    return state, True


def _finish_nested_task_blocked_event(
    event: EventEnvelope,
    plan: WorkPlan,
    event_seq: int,
    state: RunState,
    convergence: ConvergenceTracker,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    source: EventQueue,
    replaying: bool,
    diagnostics: EventDiagnostics,
    effects_log: list[EffectIntent],
    lookup: _TaskBlockedOwnerLookup,
    allow_lifecycle_effects: bool,
) -> tuple[RunState, bool]:
    """Checkpoint parent progress, project recovery, then acknowledge the event."""
    try:
        state = store.checkpoint(
            _phase_from_state(state),
            state.slices,
            state.budgets,
            max(event_seq, state.events.last_consumed_offset),
        )
    except (OSError, ValueError, RuntimeError):
        failed = replace(lookup, reason_code="parent_checkpoint_failed")
        return _park_task_blocked_owner_issue(event, state, store, failed, diagnostics), False
    try:
        if allow_lifecycle_effects and plan.sub_tls:
            state = _run_sub_tls(plan, state, config, source, effects, store, effects_log)
        if allow_lifecycle_effects:
            state = _apply_convergence(state, convergence, store, config, effects, effects_log)
        state = _clear_task_blocked_owner_gate(event, state, store)
    except (OSError, ValueError, RuntimeError):
        failed = replace(lookup, reason_code="parent_projection_failed")
        return _park_task_blocked_owner_issue(event, state, store, failed, diagnostics), False
    _ack_task_blocked_event(event, source, replaying, diagnostics, store)
    return state, True


def _finish_superseded_nested_task_blocked_event(
    event: EventEnvelope,
    plan: WorkPlan,
    event_seq: int,
    state: RunState,
    convergence: ConvergenceTracker,
    config: TLLoopConfig,
    effects: EffectClient | ReadOnlyEffectClient,
    store: RunStore,
    source: EventQueue,
    replaying: bool,
    diagnostics: EventDiagnostics,
    effects_log: list[EffectIntent],
    lookup: _TaskBlockedOwnerLookup,
    allow_lifecycle_effects: bool,
) -> tuple[RunState, bool]:
    """Project a durable supersession before atomically advancing and acking."""
    try:
        if allow_lifecycle_effects and plan.sub_tls:
            state = _run_sub_tls(plan, state, config, source, effects, store, effects_log)
        if allow_lifecycle_effects:
            state = _apply_convergence(state, convergence, store, config, effects, effects_log)
        latest = store.load()
        gate_name = _task_blocked_owner_gate_name(event)
        state = store.checkpoint(
            _phase_from_state(latest),
            latest.slices,
            latest.budgets,
            max(event_seq, latest.events.last_consumed_offset),
            current_order=latest.current_order,
            ordered_stages=latest.ordered_stages,
            integration=latest.integration,
            clear_gates=(gate_name,),
        )
    except (OSError, ValueError, RuntimeError):
        failed = replace(lookup, reason_code="superseded_projection_failed")
        return _park_task_blocked_owner_issue(event, state, store, failed, diagnostics), False
    _ack_task_blocked_event(event, source, replaying, diagnostics, store)
    return state, True


def _task_blocked_disposition_id(event: EventEnvelope) -> str:
    """Build a stable key from immutable event identity, never its age or cursor."""
    return f"{event.event_type}:{event.run_seq}:{event.event_id or 'missing-event-id'}"


def _clear_task_blocked_owner_gate(
    event: EventEnvelope,
    state: RunState,
    store: RunStore,
) -> RunState:
    """Clear a prior owner-resolution park after recovery is durable."""
    gate_name = _task_blocked_owner_gate_name(event)
    if any(gate.name == gate_name for gate in state.gates):
        return store.clear_gate(gate_name)
    return state


def _ack_task_blocked_event(
    event: EventEnvelope,
    source: EventQueue,
    replaying: bool,
    diagnostics: EventDiagnostics,
    store: RunStore,
) -> None:
    """Acknowledge only after owner and parent checkpoints are durable."""
    _ack_event(source, event, replaying, diagnostics)
    _release_replayed_event(store, event, replaying)
    diagnostics.correlated += 1


def _resolve_task_blocked_owner(
    event: EventEnvelope,
    state: RunState,
    store: RunStore,
) -> _TaskBlockedOwnerLookup:
    """Resolve the subject while proving a controller reporter's scope path."""
    matches: list[_TaskBlockedOwner] = []
    issues: list[_TaskBlockedScopeIssue] = []
    scopes: dict[tuple[str, ...], tuple[RunState, RunStore]] = {}
    _collect_task_blocked_owners(
        event,
        state,
        store,
        (state.run_id,),
        matches,
        issues,
        scopes,
    )
    if len(matches) > 1:
        scoped_owner = _scope_qualified_blocked_owner(event, matches, scopes)
        if scoped_owner is not None:
            matches = [scoped_owner]
    paths = tuple(sorted({owner.path for owner in matches}))
    slice_ids = tuple(sorted({owner.slice_id for owner in matches}))
    if len(matches) > 1:
        return _TaskBlockedOwnerLookup(
            reason_code="ambiguous_owner",
            candidate_paths=paths,
            candidate_slice_ids=slice_ids,
            reporter_id=event.agent_id,
            subject_slice_id=_blocked_subject_id(event),
            conflicting_aliases=_all_conflicting_aliases(issues),
            missing_proof=("unique_manifest_owned_subject",),
        )
    if len(matches) == 1:
        owner = matches[0]
        reporter = _resolve_task_blocked_reporter(event, owner, scopes)
        invalid_issues = [
            issue
            for issue in issues
            if not (
                _is_proven_reporting_ancestor_issue(
                    event,
                    owner,
                    reporter[0],
                    issue,
                    scopes,
                )
                or _is_proven_descendant_subject_alias(
                    event,
                    owner,
                    reporter[0],
                    issue,
                    scopes,
                )
                or _is_proven_unrelated_sibling_issue(
                    event,
                    owner,
                    reporter[0],
                    issue,
                    scopes,
                )
            )
        ]
        if reporter[0] is None:
            return _TaskBlockedOwnerLookup(
                reason_code=reporter[1],
                candidate_paths=paths,
                candidate_slice_ids=slice_ids,
                reporter_id=event.agent_id,
                subject_slice_id=owner.slice_id,
                conflicting_aliases=_all_conflicting_aliases(invalid_issues),
                missing_proof=(reporter[1],),
            )
        if not invalid_issues:
            reporter_path, reporter_invocation, reporter_generation = reporter[0]
            return _TaskBlockedOwnerLookup(
                owner=owner,
                candidate_paths=paths,
                reporter_id=event.agent_id,
                subject_slice_id=owner.slice_id,
                reporter_scope_path=reporter_path,
                reporter_invocation_id=reporter_invocation,
                reporter_generation=reporter_generation,
            )
        issues = invalid_issues
    if issues:
        issue = min(issues, key=lambda item: (item.reason_code, item.path))
        reason = issue.reason_code
        candidate = _blocked_subject_id(event)
        return _TaskBlockedOwnerLookup(
            reason_code=reason,
            candidate_paths=tuple(sorted(set(paths) | {entry.path for entry in issues})),
            unavailable_paths=tuple(
                sorted(
                    {
                        entry.path
                        for entry in issues
                        if entry.reason_code
                        not in {"owner_identity_conflict", "repository_identity_conflict"}
                    }
                )
            ),
            candidate_slice_ids=(candidate,) if candidate is not None else (),
            reporter_id=event.agent_id,
            subject_slice_id=candidate,
            reporter_scope_path=(reporter[0][0] if len(matches) == 1 and reporter[0] else ()),
            conflicting_aliases=_all_conflicting_aliases(issues),
            missing_proof=tuple(
                sorted(
                    {
                        entry.reason_code
                        for entry in issues
                        if entry.reason_code
                        not in {"owner_identity_conflict", "repository_identity_conflict"}
                    }
                    | (
                        {"consistent_event_aliases"}
                        if any(
                            entry.reason_code
                            in {"owner_identity_conflict", "repository_identity_conflict"}
                            for entry in issues
                        )
                        else set()
                    )
                )
            ),
        )
    return _TaskBlockedOwnerLookup(
        reporter_id=event.agent_id,
        subject_slice_id=_blocked_subject_id(event),
        reason_code="owner_not_found",
        missing_proof=("unique_manifest_owned_subject",),
    )


def _collect_task_blocked_owners(
    event: EventEnvelope,
    state: RunState,
    store: RunStore,
    path: tuple[str, ...],
    matches: list[_TaskBlockedOwner],
    issues: list[_TaskBlockedScopeIssue],
    scopes: dict[tuple[str, ...], tuple[RunState, RunStore]],
) -> None:
    """Walk declared child scopes and collect matching durable owners."""
    scopes[path] = (state, store)
    resolution = resolve_event_slice(event, state)
    if resolution.resolved and resolution.slice_id is not None:
        matches.append(_TaskBlockedOwner(store, resolution.slice_id, path, resolution))
    elif (resolution.candidates or resolution.rejected_aliases) and not (
        _task_blocked_scope_is_unrelated_no_match(event, state, resolution)
    ):
        reason = (
            "repository_identity_conflict"
            if resolution.reason == "repository_identity_conflict"
            else "owner_identity_conflict"
        )
        issues.append(_TaskBlockedScopeIssue(reason, path, state, resolution))
    manifest = state.plan_manifest
    if manifest is None:
        return
    for node in manifest.nodes:
        if node.kind != "sub_tl":
            continue
        child_manifest = manifest.child_manifests.get(node.node_id)
        if child_manifest is None:
            continue
        child_store = RunStore(node.name, store.run_dir)
        child_path = (*path, node.name)
        if not child_store.path.exists():
            if _manifest_contains_blocked_slice(event, child_manifest):
                issues.append(
                    _TaskBlockedScopeIssue("child_state_missing", child_path, state, resolution)
                )
            continue
        try:
            child_state = child_store.load()
        except (OSError, ValueError):
            if _manifest_contains_blocked_slice(event, child_manifest):
                issues.append(
                    _TaskBlockedScopeIssue("child_state_unavailable", child_path, state, resolution)
                )
            continue
        if not _child_owner_checkpoint_matches(state, node.name, child_state, child_manifest):
            if (
                _manifest_contains_blocked_slice(event, child_manifest)
                or resolve_event_slice(event, child_state).candidates
            ):
                issues.append(
                    _TaskBlockedScopeIssue("owner_identity_mismatch", child_path, state, resolution)
                )
            continue
        _collect_task_blocked_owners(
            event,
            child_state,
            child_store,
            child_path,
            matches,
            issues,
            scopes,
        )


def _blocked_subject_id(event: EventEnvelope) -> str | None:
    """Return the typed blocked subject, never deriving it from reporter text."""
    return event.task_blocked.slice_id if event.task_blocked is not None else None


def _task_blocked_scope_is_unrelated_no_match(
    event: EventEnvelope,
    state: RunState,
    resolution: IdentityResolution,
) -> bool:
    """Classify an absent local subject alias as unrelated when its manifest omits it."""
    subject = _blocked_subject_id(event)
    manifest = state.plan_manifest
    if subject is None or manifest is None or resolution.candidates or resolution.evidence:
        return False
    return set(resolution.rejected_aliases) == {
        f"slice_id={subject}"
    } and not _manifest_contains_blocked_slice(event, manifest)


def _scope_qualified_blocked_owner(
    event: EventEnvelope,
    matches: Sequence[_TaskBlockedOwner],
    scopes: Mapping[tuple[str, ...], tuple[RunState, RunStore]],
) -> _TaskBlockedOwner | None:
    """Use a durable reporter path to choose among repeated sibling-local IDs."""
    qualified: list[_TaskBlockedOwner] = []
    for owner in matches:
        reporter, _ = _resolve_task_blocked_reporter(event, owner, scopes)
        if reporter is not None and owner.path[: len(reporter[0])] == reporter[0]:
            qualified.append(owner)
    if len(qualified) != 1:
        return None
    selected = qualified[0]
    for other in matches:
        if other is selected:
            continue
        if not _scope_paths_are_siblings(other.path, selected.path):
            return None
        if not _resolution_matches_only_blocked_subject(other.resolution, event):
            return None
    return selected


def _resolution_matches_only_blocked_subject(
    resolution: IdentityResolution,
    event: EventEnvelope,
) -> bool:
    """Permit sibling-local duplicate IDs only when they carry no other alias evidence."""
    subject = _blocked_subject_id(event)
    return (
        subject is not None
        and resolution.resolved
        and resolution.slice_id == subject
        and dict(resolution.evidence) == {"slice_id": (subject,)}
        and not resolution.rejected_aliases
    )


def _scope_paths_are_siblings(left: tuple[str, ...], right: tuple[str, ...]) -> bool:
    """Return whether accepted scope paths diverge below a shared parent."""
    if not left or not right or left[0] != right[0]:
        return False
    common_length = 0
    for left_part, right_part in zip(left, right):
        if left_part != right_part:
            break
        common_length += 1
    return 0 < common_length < min(len(left), len(right))


def _is_proven_unrelated_sibling_issue(
    event: EventEnvelope,
    owner: _TaskBlockedOwner,
    reporter: tuple[tuple[str, ...], str | None, int | None] | None,
    issue: _TaskBlockedScopeIssue,
    scopes: Mapping[tuple[str, ...], tuple[RunState, RunStore]],
) -> bool:
    """Ignore only a sibling scope excluded by the accepted reporter path."""
    if reporter is None or owner.path[: len(reporter[0])] != reporter[0]:
        return False
    if not _scope_paths_are_siblings(issue.path, owner.path):
        return False
    if issue.reason_code == "owner_identity_conflict":
        return _task_blocked_scope_is_unrelated_no_match(event, issue.state, issue.resolution)
    if issue.reason_code not in {"child_state_missing", "child_state_unavailable"}:
        return False
    parent_entry = scopes.get(issue.path[:-1])
    if parent_entry is None:
        return False
    parent_state, _ = parent_entry
    manifest = parent_state.plan_manifest
    if manifest is None:
        return False
    child_node = next(
        (node for node in manifest.nodes if node.kind == "sub_tl" and node.name == issue.path[-1]),
        None,
    )
    child_manifest = manifest.child_manifests.get(child_node.node_id) if child_node else None
    return child_manifest is not None and _manifest_contains_blocked_slice(event, child_manifest)


def _all_conflicting_aliases(issues: Sequence[_TaskBlockedScopeIssue]) -> tuple[str, ...]:
    return tuple(
        sorted(
            {alias for issue in issues for alias in issue.resolution.rejected_aliases}
            | {
                f"{alias}->{slice_id}"
                for issue in issues
                for alias, slice_ids in issue.resolution.evidence.items()
                for slice_id in slice_ids
            }
        )
    )


def _resolve_task_blocked_reporter(
    event: EventEnvelope,
    owner: _TaskBlockedOwner,
    scopes: Mapping[tuple[str, ...], tuple[RunState, RunStore]],
) -> tuple[tuple[tuple[str, ...], str | None, int | None] | None, str]:
    """Bind the reporter to a persisted controller scope or dispatch owner."""
    reporter_id = event.agent_id
    owner_state, _ = scopes[owner.path]
    current = owner_state.slices.get(owner.slice_id)
    candidates: list[tuple[tuple[str, ...], str | None, int | None]] = []
    if current is not None and reporter_id in {owner.slice_id, current.dispatch_agent_id}:
        candidates.append((owner.path, current.dispatch_invocation_id, current.dispatch_generation))
    if isinstance(reporter_id, str) and reporter_id:
        for index, scope_id in enumerate(owner.path):
            scope_path = owner.path[: index + 1]
            if index == 0:
                if reporter_id == scope_id:
                    candidates.append((scope_path, None, None))
                continue
            parent_path = owner.path[:index]
            parent_entry = scopes.get(parent_path)
            child_entry = scopes.get(scope_path)
            if parent_entry is None or child_entry is None:
                continue
            parent_state, _ = parent_entry
            child_state, _ = child_entry
            binding = parent_state.slices.get(scope_id)
            if (
                binding is not None
                and reporter_id in {scope_id, binding.dispatch_agent_id}
                and child_state.parent_run_id == parent_state.run_id
                and _task_blocked_reporter_binding_is_durable(
                    event,
                    parent_state,
                    scope_id,
                    child_state,
                    binding,
                )
            ):
                candidates.append(
                    (
                        scope_path,
                        binding.dispatch_invocation_id,
                        binding.dispatch_generation,
                    )
                )
    if len(candidates) == 1:
        return candidates[0], "resolved"
    if len(candidates) > 1:
        return None, "reporter_scope_ambiguous"
    if reporter_id is None and current is not None and event.invocation_id:
        known = {
            current.dispatch_invocation_id,
            current.publication.invocation_id if current.publication is not None else None,
            current.handoff.invocation_id if current.handoff is not None else None,
        }
        if event.invocation_id in known:
            return (
                owner.path,
                current.dispatch_invocation_id,
                current.dispatch_generation,
            ), "resolved"
    return None, "reporter_scope_unproven"


def _task_blocked_reporter_binding_is_durable(
    event: EventEnvelope,
    parent_state: RunState,
    child_name: str,
    child_state: RunState,
    binding: SliceState,
) -> bool:
    """Prove the reporter through the original dispatch or persisted aggregate owner."""
    if binding.dispatch_agent_id == event.agent_id and _sub_tl_dispatch_binding_is_durable(binding):
        return True
    return _aggregate_reporter_binding_is_durable(
        event,
        parent_state,
        child_name,
        child_state,
        binding,
    )


def _aggregate_reporter_binding_is_durable(
    event: EventEnvelope,
    parent_state: RunState,
    child_name: str,
    child_state: RunState,
    binding: SliceState,
) -> bool:
    """Prove the original subTL reporter while keeping integration ownership separate."""
    candidate = parent_state.integration.candidates.get(child_name)
    if candidate is None:
        return False
    aggregate_lifecycles = {
        IntegrationLifecycle.AGGREGATE_PR_OPEN,
        IntegrationLifecycle.CODE_REVIEWED,
        IntegrationLifecycle.READY_FOR_INTEGRATION,
        IntegrationLifecycle.INTEGRATION_VALIDATED,
        IntegrationLifecycle.MERGING,
        IntegrationLifecycle.MERGED,
    }
    return (
        event.agent_id == binding.dispatch_agent_id
        and child_state.run_id == child_name
        and bool(binding.dispatch_intent_id)
        and binding.status in {SliceStatus.IN_REVIEW, SliceStatus.MERGED}
        and candidate.lifecycle in aggregate_lifecycles
        and bool(candidate.aggregate_patch_digest)
        and bool(candidate.aggregate_original_base_sha)
        and candidate.integration_owner_run_id == child_state.run_id
        and candidate.integration_owner_id == f"{parent_state.run_id}:{child_name}:integration"
        and candidate.aggregate_pr_number is not None
        and candidate.aggregate_pr_number == binding.pr_number
        and candidate.integration_owner_branch == binding.branch
        and candidate.integration_owner_branch == child_state.owner_branch
        and candidate.integration_owner_worktree == binding.worktree
        and candidate.aggregate_head_sha
        == (binding.publication.head_sha if binding.publication is not None else None)
        and binding.dispatch_last_boundary in _AGGREGATE_DISPATCH_BOUNDARIES
    )


def _sub_tl_dispatch_binding_is_durable(binding: SliceState) -> bool:
    return (
        isinstance(binding.dispatch_intent_id, str)
        and bool(binding.dispatch_intent_id)
        and binding.status is not SliceStatus.PENDING
        and binding.dispatch_last_boundary in RECONCILED_SUB_TL_DISPATCH_BOUNDARIES
    )


def _is_proven_reporting_ancestor_issue(
    event: EventEnvelope,
    owner: _TaskBlockedOwner,
    reporter: tuple[tuple[str, ...], str | None, int | None] | None,
    issue: _TaskBlockedScopeIssue,
    scopes: Mapping[tuple[str, ...], tuple[RunState, RunStore]],
) -> bool:
    """Ignore only the exact subject alias explained by a bound child reporter."""
    subject = _blocked_subject_id(event)
    if issue.reason_code != "owner_identity_conflict" or subject is None or reporter is None:
        return False
    reporter_path = reporter[0]
    if len(reporter_path) <= len(issue.path) or owner.path[: len(issue.path)] != issue.path:
        return False
    if owner.path[: len(reporter_path)] != reporter_path or reporter_path[:-1] != issue.path:
        return False
    reporter_slice_id = reporter_path[-1]
    resolution = issue.resolution
    if resolution.candidates != (reporter_slice_id,):
        return False
    if dict(resolution.evidence) != {"agent_id": (reporter_slice_id,)}:
        return False
    if set(resolution.rejected_aliases) != {f"slice_id={subject}"}:
        return False
    parent_entry = scopes.get(issue.path)
    child_entry = scopes.get(reporter_path)
    if parent_entry is None or child_entry is None:
        return False
    parent_state, _ = parent_entry
    child_state, _ = child_entry
    if parent_state.plan_manifest is None:
        return False
    child_node = next(
        (
            node
            for node in parent_state.plan_manifest.nodes
            if node.kind == "sub_tl" and node.name == reporter_slice_id
        ),
        None,
    )
    if child_node is None:
        return False
    child_manifest = parent_state.plan_manifest.child_manifests.get(child_node.node_id)
    binding = parent_state.slices.get(reporter_slice_id)
    return (
        child_manifest is not None
        and binding is not None
        and _child_owner_checkpoint_matches(
            parent_state,
            reporter_slice_id,
            child_state,
            child_manifest,
        )
        and _task_blocked_reporter_binding_is_durable(
            event,
            parent_state,
            reporter_slice_id,
            child_state,
            binding,
        )
    )


def _is_proven_descendant_subject_alias(
    event: EventEnvelope,
    owner: _TaskBlockedOwner,
    reporter: tuple[tuple[str, ...], str | None, int | None] | None,
    issue: _TaskBlockedScopeIssue,
    scopes: Mapping[tuple[str, ...], tuple[RunState, RunStore]],
) -> bool:
    """Accept an absent local subject only when the exact child binding owns it."""
    subject = _blocked_subject_id(event)
    if subject is None or issue.reason_code != "owner_identity_conflict":
        return False
    if len(owner.path) <= len(issue.path) or owner.path[: len(issue.path)] != issue.path:
        return False
    if issue.resolution.candidates or issue.resolution.evidence:
        return False
    if set(issue.resolution.rejected_aliases) != {f"slice_id={subject}"}:
        return False
    if reporter is not None:
        reporter_path = reporter[0]
        if (
            owner.path[: len(reporter_path)] == reporter_path
            and reporter_path[: len(issue.path)] == issue.path
        ):
            return True
    owner_entry = scopes.get(owner.path)
    if owner_entry is None:
        return False
    owner_state, _ = owner_entry
    current = owner_state.slices.get(owner.slice_id)
    return current is not None and event.agent_id in {owner.slice_id, current.dispatch_agent_id}


def _classify_task_blocked_disposition(
    event: EventEnvelope,
    owner: _TaskBlockedOwner,
    owner_state: RunState,
    lookup: _TaskBlockedOwnerLookup,
) -> _TaskBlockedDisposition:
    """Choose recovery, supersession, or a safe park from persisted evidence."""
    blocked = event.task_blocked
    current = owner_state.slices.get(owner.slice_id)
    if blocked is None or current is None:
        return _unresolved_task_blocked("subject_checkpoint_missing", "subject_checkpoint")
    identity_failure = _task_blocked_runtime_identity_failure(event, current, lookup)
    if identity_failure is not None:
        return _unresolved_task_blocked(identity_failure, identity_failure)
    if current.status is SliceStatus.MERGED:
        proof, missing = _completed_task_blocked_proof(
            event,
            current,
            owner_state,
            owner.store,
        )
        if missing:
            return _TaskBlockedDisposition(
                "unresolved",
                "completed_child_evidence_incomplete",
                missing_proof=missing,
            )
        encoded = json.dumps(
            {
                "slice_id": current.id,
                "attempts": current.attempts,
                "last_consumed_offset": owner_state.events.last_consumed_offset,
                "status": current.status.value,
                "repository_identity": (
                    owner_state.repository_identity.remote_url
                    if owner_state.repository_identity is not None
                    else None
                ),
                "chainlink_issue_id": current.chainlink_issue_id,
                "publication": _publication_evidence_document(current.publication),
                "handoff": _handoff_evidence_document(current.handoff),
                "post_merge": dict(current.post_merge.evidence)
                if current.post_merge is not None
                else None,
            },
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        return _TaskBlockedDisposition(
            "superseded_by_durable_completion",
            "completed_child_receipts_match_blocker",
            proof=proof,
            evidence_digest=hashlib.sha256(encoded).hexdigest(),
        )
    if current.status in {
        SliceStatus.SPAWNED,
        SliceStatus.IN_REVIEW,
        SliceStatus.REPAIRING,
        SliceStatus.BLOCKED,
        SliceStatus.PARKED,
        SliceStatus.DISPATCH_UNCONFIRMED,
        SliceStatus.DISPATCH_RETRY_SCHEDULED,
    }:
        if current.attempts != blocked.attempt:
            return _unresolved_task_blocked("blocker_attempt_mismatch", "current_attempt")
        return _TaskBlockedDisposition(
            "actionable",
            "active_child_attempt_matches_blocker",
            proof=(
                f"scope={owner.path}",
                f"dispatch_intent_id={current.dispatch_intent_id or 'legacy-unavailable'}",
                f"attempt={blocked.attempt}",
            ),
        )
    return _unresolved_task_blocked("child_not_actionable_or_completed", "active_or_complete_state")


def _task_blocked_runtime_identity_failure(
    event: EventEnvelope,
    current: SliceState,
    lookup: _TaskBlockedOwnerLookup,
) -> str | None:
    """Reject observed invocation or generation conflicts without guessing."""
    if event.invocation_id is not None:
        expected = lookup.reporter_invocation_id
        if expected is None:
            return "reporter_invocation_binding_missing"
        if event.invocation_id != expected:
            return "reporter_invocation_mismatch"
    if event.generation is not None:
        if lookup.reporter_generation is None:
            return "reporter_generation_binding_missing"
        if event.generation != lookup.reporter_generation:
            return "reporter_generation_mismatch"
    if event.task_blocked is not None and event.task_blocked.attempt <= 0:
        return "invalid_blocker_attempt"
    if (
        current.status is SliceStatus.MERGED
        and current.attempts > 0
        and event.task_blocked is not None
        and event.task_blocked.attempt > current.attempts
    ):
        return "completed_attempt_mismatch"
    return None


def _completed_task_blocked_proof(
    event: EventEnvelope,
    current: SliceState,
    state: RunState,
    store: RunStore,
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    """Validate exact publication, handoff, merge, closure, and push evidence."""
    blocked = event.task_blocked
    publication = current.publication
    handoff = current.handoff
    receipt = current.post_merge
    missing: list[str] = []
    if current.verdict is not Verdict.GO:
        missing.append("accepted_review_verdict")
    if current.recovery is not None:
        missing.append("terminal_recovery_absent")
    if blocked is None:
        missing.append("blocked_attempt")
    if publication is None:
        missing.append("publication_binding")
    if handoff is None:
        missing.append("handoff_receipt")
    if receipt is None or receipt.phase is not PostMergePhase.COMPLETE:
        missing.append("post_merge_complete_receipt")
    if state.repository_identity is None:
        missing.append("repository_identity")
    if missing:
        return (), tuple(sorted(set(missing)))
    assert blocked is not None and publication is not None and handoff is not None
    assert receipt is not None and state.repository_identity is not None
    evidence = receipt.evidence
    expected_head = publication.head_sha
    expected_pr = current.pr_number
    _require_completion_match(missing, bool(current.dispatch_intent_id), "dispatch_intent")
    _require_completion_match(
        missing,
        current.dispatch_agent_id is None or handoff.agent_id == current.dispatch_agent_id,
        "dispatch_handoff_agent",
    )
    attempt_proof, attempt_missing = _completed_attempt_history_proof(
        event,
        current,
        state,
        publication,
        handoff,
    )
    missing.extend(attempt_missing)
    _require_completion_match(missing, expected_pr == publication.pr_number, "publication_pr")
    _require_completion_match(missing, handoff.pr_number == publication.pr_number, "handoff_pr")
    _require_completion_match(missing, current.reviewed_head == expected_head, "reviewed_head")
    _require_completion_match(missing, handoff.head_sha == expected_head, "handoff_head")
    _require_completion_match(missing, current.branch == publication.head_branch, "head_branch")
    _require_completion_match(
        missing, publication.base_branch == evidence.get("parent_branch"), "base_branch"
    )
    _require_completion_match(missing, evidence.get("child_id") == current.id, "merge_child_id")
    _require_completion_match(
        missing, evidence.get("pr_number") == str(expected_pr), "merge_pr_number"
    )
    _require_completion_match(missing, evidence.get("head_sha") == expected_head, "merge_head_sha")
    repository_match = _completed_repository_evidence_match_kind(
        evidence.get("repository"),
        state,
    )
    _require_completion_match(missing, repository_match is not None, "merge_repository_identity")
    _require_completion_match(
        missing,
        bool(evidence.get("merge_journal_id")),
        "merge_journal_receipt",
    )
    _validate_completed_issue_closure(current, evidence, missing, store)
    push_proof = _completed_task_blocked_push_proof(current, state, store, evidence, missing)
    if publication.invocation_id and handoff.invocation_id != publication.invocation_id:
        missing.append("publication_handoff_invocation")
    if current.dispatch_invocation_id and handoff.invocation_id != current.dispatch_invocation_id:
        missing.append("dispatch_handoff_invocation")
    if missing:
        return (), tuple(sorted(set(missing)))
    proof = (
        *attempt_proof,
        f"repository_match={repository_match}",
        f"pr={publication.pr_number}",
        f"head_sha={publication.head_sha}",
        f"merge_journal_id={evidence['merge_journal_id']}",
        f"issue_id={evidence.get('issue_id') or 'not_applicable'}",
        f"issue_close={evidence.get('issue_close_journal_id') or evidence.get('issue_close_observed_status')}",
        *push_proof,
    )
    return proof, ()


def _require_completion_match(
    missing: list[str],
    matches: bool,
    evidence_name: str,
) -> None:
    if not matches:
        missing.append(evidence_name)


def _completed_attempt_history_proof(
    event: EventEnvelope,
    current: SliceState,
    state: RunState,
    publication: PublicationBinding,
    handoff: HandoffEvidence,
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    """Prove matching or already-consumed legacy attempt history."""
    blocked = event.task_blocked
    if blocked is None:
        return (), ("blocked_attempt",)
    if publication.attempt != handoff.attempt:
        return (), ("publication_handoff_attempt", "handoff_attempt")
    completed_attempt = publication.attempt
    if current.attempts == 0:
        if blocked.attempt != completed_attempt:
            return (), ("legacy_attempt_history",)
        return (f"attempt={blocked.attempt}",), ()
    if blocked.attempt > current.attempts or completed_attempt > current.attempts:
        return (), ("attempt_exceeds_completed_history",)
    if blocked.attempt == completed_attempt == current.attempts:
        return (f"attempt={blocked.attempt}",), ()
    if event.run_seq is None or state.events.last_consumed_offset < event.run_seq:
        return (), ("subject_scope_consumed_event",)
    return (
        f"blocker_attempt={blocked.attempt}",
        f"completion_attempt={completed_attempt}",
        f"slice_attempt_high_water={current.attempts}",
        f"subject_consumed_offset={state.events.last_consumed_offset}",
    ), ()


def _completed_repository_evidence_match_kind(
    receipt_repository: object,
    state: RunState,
) -> str | None:
    """Match canonical receipts or a corroborated legacy owner/repo slug."""
    identity = state.repository_identity
    if identity is None or not isinstance(receipt_repository, str):
        return None
    try:
        if canonical_repository_url(receipt_repository) == identity.remote_url:
            return "canonical_url"
    except ValueError:
        pass
    if not _is_legacy_repository_slug(receipt_repository):
        return None
    try:
        owner, repository = repository_api_coordinates(identity.remote_url)
    except ValueError:
        return None
    return "legacy_owner_repo_slug" if receipt_repository == f"{owner}/{repository}" else None


def _is_legacy_repository_slug(value: str) -> bool:
    """Accept only the historical two-component, credential-free slug form."""
    if value.count("/") != 1 or any(character.isspace() for character in value):
        return False
    owner, repository = value.split("/")
    return all(
        part
        and part not in {".", ".."}
        and part.isascii()
        and all(character.isalnum() or character in "._-" for character in part)
        for part in (owner, repository)
    )


def _validate_completed_issue_closure(
    current: SliceState,
    evidence: Mapping[str, str],
    missing: list[str],
    store: RunStore,
) -> None:
    if current.chainlink_issue_id is None:
        _validate_legacy_issue_closure(evidence, missing, store, current.id)
        return
    _require_completion_match(
        missing,
        evidence.get("issue_id") == str(current.chainlink_issue_id),
        "issue_close_issue_id",
    )
    outcome = evidence.get("issue_close_outcome")
    if outcome == "already_closed":
        _require_completion_match(
            missing,
            evidence.get("issue_close_observed_issue_id") == str(current.chainlink_issue_id)
            and evidence.get("issue_close_observed_status") == "closed",
            "issue_already_closed_receipt",
        )
    else:
        _require_completion_match(
            missing,
            outcome == "closed" and bool(evidence.get("issue_close_journal_id")),
            "issue_close_journal_receipt",
        )


def _validate_legacy_issue_closure(
    evidence: Mapping[str, str],
    missing: list[str],
    store: RunStore,
    slice_id: str,
) -> None:
    """Corroborate a receipt-linked legacy issue when the manifest ID is absent."""
    outcome = evidence.get("issue_close_outcome")
    issue_id = evidence.get("issue_id")
    close_intent_id = evidence.get("issue_close_intent_id")
    close_receipt_id = evidence.get("issue_close_journal_id")
    closure_fields = (issue_id, close_intent_id, close_receipt_id)
    if outcome == "not_applicable" and not any(closure_fields):
        return
    if outcome not in {None, "closed"}:
        missing.append("legacy_issue_close_outcome")
        return
    if (
        not isinstance(issue_id, str)
        or not issue_id.isascii()
        or not issue_id.isdigit()
        or int(issue_id) <= 0
        or str(int(issue_id)) != issue_id
        or not isinstance(close_intent_id, str)
        or not close_intent_id
        or not isinstance(close_receipt_id, str)
        or not close_receipt_id
    ):
        missing.append("legacy_issue_close_receipt")
        return
    journal_failure = _legacy_issue_close_journal_failure(
        store,
        slice_id,
        int(issue_id),
        close_intent_id,
        close_receipt_id,
    )
    if journal_failure is not None:
        missing.append(journal_failure)


def _legacy_issue_close_journal_failure(
    store: RunStore,
    slice_id: str,
    issue_id: int,
    intent_id: str,
    receipt_id: str,
) -> str | None:
    """Require one confirmed action result matching the historical receipt."""
    journal_path = store.run_dir / "action-journal.json"
    if not journal_path.is_file():
        return "legacy_issue_close_action_journal_missing"
    try:
        entries = EffectJournal(store.run_id, journal_path).confirmed_entries(
            "post_merge_issue_close",
            slice_id,
        )
    except (ActionJournalError, OSError):
        return "legacy_issue_close_action_journal_unavailable"
    matches = [
        entry
        for entry in entries
        if _legacy_issue_close_entry_matches(entry, issue_id, intent_id, receipt_id)
    ]
    if not matches:
        return "legacy_issue_close_action_receipt_missing"
    return "legacy_issue_close_action_receipt_ambiguous" if len(matches) > 1 else None


def _legacy_issue_close_entry_matches(
    entry: Mapping[str, object],
    issue_id: int,
    intent_id: str,
    receipt_id: str,
) -> bool:
    """Compare the action intent and returned receipt to legacy checkpoint data."""
    arguments = entry.get("arguments")
    raw_result = entry.get("result")
    if not isinstance(arguments, Mapping) or not isinstance(raw_result, dict):
        return False
    if (
        type(arguments.get("issue_id")) is not int
        or arguments.get("issue_id") != issue_id
        or arguments.get("intent_id") != intent_id
    ):
        return False
    try:
        result = ToolResult.from_raw(cast(JsonObject, raw_result))
    except (DecodeError, TypeError, ValueError):
        return False
    payload = _merge_result_payload(result)
    observed_issue_id = payload.get("issue_id") if payload is not None else None
    return bool(
        payload
        and type(observed_issue_id) is int
        and observed_issue_id == issue_id
        and payload.get("receipt_id") == receipt_id
    )


def _validate_completed_push_receipt(
    current: SliceState,
    evidence: Mapping[str, str],
    missing: list[str],
) -> None:
    try:
        receipt = PushReceipt(
            repository=evidence["repository"],
            parent_branch=evidence["parent_branch"],
            child_id=evidence["child_id"],
            lane_epoch=int(evidence["lane_epoch"]),
            push_intent_id=evidence["parent_push_intent_id"],
            push_journal_id=evidence["push_journal_id"],
            push_receipt_id=evidence["push_receipt_id"],
            expected_base_sha=evidence["expected_base_sha"],
            pushed_commit=evidence["pushed_commit"],
            observed_remote_head=evidence["observed_remote_head"],
            ancestry_proof=evidence["ancestry_proof"],
        )
    except (KeyError, TypeError, ValueError):
        missing.append("typed_parent_push_receipt")
        return
    _require_completion_match(missing, receipt.child_id == current.id, "push_child_id")
    _require_completion_match(
        missing,
        receipt.pushed_commit == evidence.get("bookkeeping_commit"),
        "push_bookkeeping_commit",
    )
    _require_completion_match(
        missing,
        receipt.observed_remote_head == receipt.pushed_commit,
        "push_observed_head",
    )
    _require_completion_match(
        missing,
        receipt.ancestry_proof
        == f"ancestor:{receipt.pushed_commit}->{receipt.observed_remote_head}",
        "push_ancestry_proof",
    )


def _completed_task_blocked_push_proof(
    current: SliceState,
    state: RunState,
    store: RunStore,
    evidence: Mapping[str, str],
    missing: list[str],
) -> tuple[str, ...]:
    """Accept either typed parent push evidence or a verified no-push completion."""
    push_missing: list[str] = []
    _validate_completed_push_receipt(current, evidence, push_missing)
    if not push_missing:
        return (
            f"push_receipt_id={evidence['push_receipt_id']}",
            f"push_journal_id={evidence['push_journal_id']}",
        )
    if push_missing == ["typed_parent_push_receipt"]:
        proof = _completed_no_push_sync_proof(current, state, store, evidence)
        if proof is not None:
            return proof
    missing.extend(push_missing)
    return ()


def _completed_no_push_sync_proof(
    current: SliceState,
    state: RunState,
    store: RunStore,
    evidence: Mapping[str, str],
) -> tuple[str, ...] | None:
    """Prove a completed no-changelog leaf from its confirmed parent-sync receipt."""
    push_fields = (
        "parent_push_intent_id",
        "push_journal_id",
        "push_receipt_id",
        "expected_base_sha",
        "pushed_commit",
        "bookkeeping_commit",
        "observed_remote_head",
        "ancestry_proof",
    )
    if (
        current.chainlink_issue_id is not None
        or evidence.get("issue_close_outcome") != "not_applicable"
        or evidence.get("changelog_decision") != "captured"
        or evidence.get("changelog_outcome") != "captured"
        or evidence.get("changelog_commit_sha")
        or evidence.get("observed_remote_head")
        or any(field in evidence for field in push_fields)
        or type(current.pr_number) is not int
        or current.pr_number <= 0
    ):
        return None
    reconciliation = current.reconciliation
    if not isinstance(reconciliation, Mapping):
        return None
    expected_base = reconciliation.get("merge_base_sha")
    if not isinstance(expected_base, str) or not expected_base:
        return None
    try:
        arguments = _parent_sync_arguments(
            current,
            current.pr_number,
            evidence,
            expected_base,
            None,
        )
        identity = _parent_sync_identity_fields(arguments)
        sync_id = stable_action_key(
            state.run_id,
            "post_merge_parent_sync_operation",
            current.id,
            identity,
        )
        journal = EffectJournal(store.run_id, store.run_dir / "action-journal.json")
        history, history_error = _parent_sync_history(
            journal,
            current.id,
            sync_id,
            identity,
        )
    except (ActionJournalError, OSError, TLLoopError, TypeError, ValueError):
        return None
    if history_error or not history:
        return None
    mutations = [entry for entry in history if entry[1] == "post_merge_parent_sync"]
    if not mutations:
        return None
    attempt, operation, entry = max(mutations, key=lambda item: item[0])
    if (
        operation != "post_merge_parent_sync"
        or entry.get("run_id") != store.run_id
        or entry.get("target") != current.id
        or entry.get("status") != "confirmed"
    ):
        return None
    entry_arguments = entry.get("arguments")
    result = entry.get("result")
    payload = result.get("result") if isinstance(result, Mapping) else None
    if not isinstance(entry_arguments, Mapping) or not isinstance(payload, Mapping):
        return None
    stable_identity = entry_arguments.get("sync_operation_id") == sync_id
    validated = _validated_sync_payload(
        payload,
        arguments,
        sync_id,
        attempt,
        require_correlation=stable_identity,
    )
    if (
        validated.get("sync_outcome") != "confirmed"
        or validated.get("sync_phase") != "complete"
        or not {"fetch", "fast_forward"}.issubset(
            set(validated.get("completed_steps", ()))
            if isinstance(validated.get("completed_steps"), list)
            else set()
        )
        or validated.get("parent_commit_sha") != evidence.get("parent_commit_sha")
        or validated.get("remote_head_sha") != reconciliation.get("remote_head_sha")
        or validated.get("ancestry_proof") != reconciliation.get("ancestry_proof")
    ):
        return None
    return (
        f"parent_sync_operation_id={sync_id}",
        f"parent_sync_attempt={attempt}",
    )


def _publication_evidence_document(publication: PublicationBinding | None) -> object:
    if publication is None:
        return None
    return {
        "pr_number": publication.pr_number,
        "head_sha": publication.head_sha,
        "head_branch": publication.head_branch,
        "base_branch": publication.base_branch,
        "attempt": publication.attempt,
        "invocation_id": publication.invocation_id,
    }


def _handoff_evidence_document(handoff: HandoffEvidence | None) -> object:
    if handoff is None:
        return None
    return {
        "pr_number": handoff.pr_number,
        "head_sha": handoff.head_sha,
        "attempt": handoff.attempt,
        "invocation_id": handoff.invocation_id,
        "agent_id": handoff.agent_id,
        "observed_at": handoff.observed_at,
    }


def _unresolved_task_blocked(
    reason_code: str,
    missing_evidence: str,
) -> _TaskBlockedDisposition:
    return _TaskBlockedDisposition(
        "unresolved",
        reason_code,
        missing_proof=(missing_evidence,),
    )


def _child_owner_checkpoint_matches(
    parent: RunState,
    child_name: str,
    child: RunState,
    manifest: PlanManifest,
) -> bool:
    """Require a nested checkpoint to match its declared parent and manifest."""
    return (
        child.run_id == child_name
        and child.parent_run_id == parent.run_id
        and child.plan_manifest is not None
        and child.plan_manifest.digest == manifest.digest
    )


def _manifest_contains_blocked_slice(event: EventEnvelope, manifest: PlanManifest) -> bool:
    """Check only canonical slice aliases against declared leaf names."""
    blocked = event.task_blocked
    if blocked is None:
        return False
    observed = {blocked.slice_id, event.slice_id, event.data.get("slice_id")}
    names = {node.name for node in manifest.nodes if node.kind in {"leaf", "worker"}}
    for child in manifest.child_manifests.values():
        names.update(_manifest_leaf_names(child))
    return any(isinstance(value, str) and value in names for value in observed)


def _manifest_leaf_names(manifest: PlanManifest) -> set[str]:
    """Return declared leaf and worker names from a recursive child manifest."""
    names = {node.name for node in manifest.nodes if node.kind in {"leaf", "worker"}}
    for child in manifest.child_manifests.values():
        names.update(_manifest_leaf_names(child))
    return names


def _task_blocked_owner_gate_name(event: EventEnvelope) -> str:
    """Name one unresolved blocked-event owner decision by immutable sequence."""
    return f"task-blocked-owner:{event.run_seq}"


def _park_task_blocked_owner_issue(
    event: EventEnvelope,
    state: RunState,
    store: RunStore,
    lookup: _TaskBlockedOwnerLookup,
    diagnostics: EventDiagnostics,
) -> RunState:
    """Persist a retryable owner-routing park without advancing the event cursor."""
    blocked = event.task_blocked
    reason = lookup.reason_code
    diagnostics.record_task_blocked_owner_issue(
        event,
        reason,
        lookup.candidate_slice_ids,
        reporter_scope_path=lookup.reporter_scope_path,
        candidate_paths=lookup.candidate_paths,
        conflicting_aliases=lookup.conflicting_aliases,
        missing_proof=lookup.missing_proof,
    )
    audit = {
        "run_seq": event.run_seq,
        "event_id": event.event_id,
        "event_type": event.event_type,
        "correlation": "task_blocked_owner_unresolved",
        "reason_code": reason,
        "observed_slice_id": blocked.slice_id if blocked is not None else None,
        "observed_agent_id": event.agent_id,
        "observed_invocation_id": event.invocation_id,
        "reporter_scope_path": list(lookup.reporter_scope_path),
        "conflicting_aliases": list(lookup.conflicting_aliases),
        "missing_proof": list(lookup.missing_proof),
        "candidate_owner_paths": [list(path) for path in lookup.candidate_paths],
        "unavailable_owner_paths": [list(path) for path in lookup.unavailable_paths],
    }
    try:
        if event.run_seq is not None:
            store.append_audit_event(audit)
    except (OSError, ValueError, RuntimeError) as error:
        LOGGER.error(
            "Unable to persist task-blocked owner audit run_id=%s seq=%s reason=%s error=%s",
            state.run_id,
            event.run_seq,
            reason,
            type(error).__name__,
        )
    try:
        return store.set_gate(_task_blocked_owner_gate_name(event), GateStatus.PENDING)
    except (OSError, ValueError, RuntimeError) as error:
        LOGGER.error(
            "Unable to persist task-blocked owner gate run_id=%s seq=%s reason=%s error=%s",
            state.run_id,
            event.run_seq,
            reason,
            type(error).__name__,
        )
        return state


def _record_task_blocked_recovery(
    event: EventEnvelope,
    state: RunState,
    store: RunStore,
    phase: PhaseValue,
    event_seq: int,
    effects: EffectClient,
) -> RunState:
    """Record one externally blocked slice in nonterminal DIAGNOSING state."""
    blocked = event.task_blocked
    if blocked is None:
        raise TLLoopError("agent.task_blocked has no typed blocked payload")
    slice_id = blocked.slice_id or event.slice_id or event.agent_id
    if not isinstance(slice_id, str) or slice_id not in state.slices:
        raise TLLoopError(f"agent.task_blocked names unknown slice {slice_id!r}")
    cause_by_wire = {
        "base_ci_unstable": ParkCause.BASE_CI_UNSTABLE,
        "external_dependency": ParkCause.EXTERNAL_DEPENDENCY,
        "scope_boundary": ParkCause.SCOPE_BOUNDARY,
        "human_decision_required": ParkCause.HUMAN_DECISION_REQUIRED,
        "tooling_unavailable": ParkCause.TOOL_UNAVAILABLE,
    }
    cause = cause_by_wire.get(blocked.cause.value)
    if cause is None:
        raise TLLoopError(f"agent.task_blocked has unsupported cause {blocked.cause.value!r}")
    audit = dict(event.data)
    audit.update(
        {
            "attempt": blocked.attempt,
            "recovery_action": blocked.recovery_action,
            "needs_human": blocked.needs_human,
            "scope_attribution": blocked.scope_attribution,
            "retryable": blocked.retryable,
            "declared_difficulty": blocked.declared_difficulty.value,
            "matched_difficulty_rule": blocked.matched_difficulty_rule,
        }
    )
    current = state.slices[slice_id]
    audit.setdefault("invocation_id", event.invocation_id or current.dispatch_invocation_id)
    audit.setdefault("generation", event.generation)
    policy = policy_for_cause(blocked.cause.value)
    if current.recovery is not None:
        if current.recovery.cause != cause.value:
            raise TLLoopError(
                f"slice {slice_id!r} already recovers cause {current.recovery.cause!r}"
            )
        recovery = current.recovery
        if policy.immediate_human_gate and recovery.phase is not RecoveryPhase.HUMAN_GATE:
            recovery = transition_recovery(
                recovery,
                RecoveryPhase.HUMAN_GATE,
                next_action="open_human_gate",
                evidence=audit,
            )
        updated = {
            **state.slices,
            slice_id: replace(current, recovery=recovery),
        }
        suspended = suspend_dependents(updated, slice_id, recovery.recovery_round)
        return store.checkpoint(phase, suspended, state.budgets, event_seq)
    generation = audit.get("generation")
    recovery = begin_recovery(
        cause=cause.value,
        owner_run_id=state.run_id,
        slice_attempt=blocked.attempt or current.attempts,
        owner_agent_id=current.dispatch_agent_id,
        invocation_generation=generation if type(generation) is int and generation >= 0 else 0,
        plan_revision=state.revision,
        evidence=audit,
    )
    if policy.immediate_human_gate:
        recovery = transition_recovery(
            recovery,
            RecoveryPhase.HUMAN_GATE,
            next_action="open_human_gate",
            evidence=audit,
        )
    updated = {**state.slices, slice_id: replace(current, recovery=recovery)}
    updated = suspend_dependents(updated, slice_id, recovery.recovery_round)
    checkpointed = store.checkpoint(phase, updated, state.budgets, event_seq)
    emit_controller_event(
        effects,
        "agent.recovery.started",
        {
            "slice_id": slice_id,
            "invocation_id": recovery.evidence.get("invocation_id", current.dispatch_invocation_id),
            "generation": recovery.invocation_generation,
            "cause": recovery.cause,
            "slice_attempt": recovery.slice_attempt,
            "invocation_generation": recovery.invocation_generation,
            "recovery_round": recovery.recovery_round,
            "authorization_source": "policy",
            "recursive_depth": checkpointed.depth,
            "parallel_impact": _recovery_parallel_impact(checkpointed, slice_id),
            "policy_decision": "wait",
        },
    )
    return checkpointed


def _recovery_parallel_impact(state: RunState, slice_id: str) -> str:
    """Bound sibling scheduling impact without exporting sibling identities."""
    siblings = [sibling.status for name, sibling in state.slices.items() if name != slice_id]
    if any(status in {SliceStatus.READY, SliceStatus.PENDING} for status in siblings):
        return "sibling_progress"
    if any(
        status not in {SliceStatus.MERGED, SliceStatus.FAILED, SliceStatus.PARKED}
        for status in siblings
    ):
        return "sibling_wait"
    return "none"


def _checkpoint_and_ack(
    store: RunStore,
    source: EventQueue,
    event: EventEnvelope,
    state: RunState,
    phase: PhaseValue,
    *,
    acknowledge: bool = True,
) -> None:
    if event.run_seq is None:
        raise TLLoopError(f"{event.event_type!r} has no run_seq")
    offset = max(state.events.last_consumed_offset, event.run_seq)
    store.checkpoint(phase, state.slices, state.budgets, offset)
    if acknowledge:
        source.acknowledge(event)


def _ack_event(
    source: EventQueue,
    event: EventEnvelope,
    replaying: bool,
    diagnostics: EventDiagnostics,
) -> None:
    """Acknowledge source events once; replayed rows were already acknowledged."""
    if not replaying:
        source.acknowledge(event)
        diagnostics.acknowledged += 1


def _release_replayed_event(store: RunStore, event: EventEnvelope, replaying: bool) -> None:
    if replaying and event.run_seq is not None:
        store.release_quarantined_event(event.run_seq)


def _is_reconcilable_identity_event(event: EventEnvelope) -> bool:
    return event.kind in {
        EventKind.PR_FILED,
        EventKind.PR_UPDATED,
        EventKind.PR_REVIEW,
        EventKind.COPILOT_REVIEW,
        EventKind.CI_STATUS_CHANGED,
    }


def _replayable_event_index(
    events: Sequence[EventEnvelope],
    state: RunState,
    expected: set[str],
) -> int | None:
    for index, event in enumerate(events):
        if resolve_event_slice(event, state, allowed_ids=expected).resolved:
            return index
    return None


def _event_belongs_to_plan(
    event: EventEnvelope, expected: set[str], state: RunState | None = None
) -> bool:
    if "shadow_event" in event.data:
        value = event.data["shadow_event"]
        if isinstance(value, Mapping):
            slug = value.get("slug")
            return slug is None or slug in expected
    if event.kind in OWNERSHIP_RESOLVED_KINDS:
        if state is None:
            return False
        return resolve_event_slice(event, state, allowed_ids=expected).resolved
    if event.agent_id in expected:
        return True
    intent_id = event.data.get("intent_id")
    if (
        isinstance(intent_id, str)
        and state is not None
        and any(
            slice_state.dispatch_intent_id == intent_id for slice_state in state.slices.values()
        )
    ):
        return True
    for key in ("slug", "child_agent", "slice_id"):
        value = event.data.get(key)
        if isinstance(value, str) and value in expected:
            return True
    return False


def _retarget_child_event(fsm_event: TLEvent, slice_id: str | None) -> TLEvent:
    """Name the resolved slice instead of the row's runtime agent id.

    A dispatched worker reports under the agent id the server minted
    (``<slice>-codex``), so the decoder produces ``ChildCompleted``/``ChildFailed``
    for that id. The scope barrier and the slice map are both keyed by slice, so
    an event still naming the agent id raises ``IllegalTransition`` ("names a
    child outside the active barrier") and would otherwise abort the loop.

    Only the ownership already proven by the resolver is applied, and only when
    the row named no slice of its own: an event whose slug is already a slice
    id is left exactly as decoded.
    """
    if slice_id is None:
        return fsm_event
    if isinstance(fsm_event, (ChildCompleted, ChildFailed)):
        return replace(fsm_event, slug=slice_id)
    if isinstance(fsm_event, PRMerged):
        return replace(fsm_event, slug=slice_id)
    return fsm_event


def _event_slice_id(event: EventEnvelope, state: RunState) -> str | None:
    resolved = resolve_event_slice(event, state)
    if resolved.resolved:
        return resolved.slice_id
    shadow_event = event.data.get("shadow_event")
    if isinstance(shadow_event, Mapping):
        shadow_slug = shadow_event.get("slug")
        if isinstance(shadow_slug, str) and shadow_slug in state.slices:
            return shadow_slug
    return None


def _pr_event_target(
    slices: Mapping[str, SliceState], event: TLEvent, slice_id: str | None
) -> str | None:
    if not isinstance(event, (PRFiled, PRUpdated)):
        return None
    target_id = event.slice_id or slice_id
    if target_id is not None:
        return target_id
    matches = [
        candidate_id
        for candidate_id, candidate in slices.items()
        if candidate.pr_number == event.pr_number
    ]
    return matches[0] if len(matches) == 1 else None


def _quarantine_historical_publication(store: RunStore, event: EventEnvelope, reason: str) -> None:
    """Retain a refused historical publication event permanently for audit.

    This is deliberately the audit log, not the pending event-quarantine
    queue: a historical event must never re-enter replay or be released.
    """
    store.append_audit_event(
        {
            **envelope_document(event),
            "correlation": PUBLICATION_HISTORY_AUDIT,
            "correlation_reason": reason,
        }
    )


def _record_historical_child_merge(store: RunStore, event: EventEnvelope) -> None:
    """Retain a child PR merge that cannot prove its parent's aggregate merge."""
    store.append_audit_event(
        {
            **envelope_document(event),
            "correlation": "child_merge_does_not_bind_aggregate",
            "correlation_reason": "event PR number differs from the bound aggregate PR",
        }
    )


def _record_historical_spawn(store: RunStore, event: EventEnvelope, reason: str) -> None:
    """Retain a spawn row from a predecessor epoch permanently for audit.

    A row confirmed under another controller epoch proves what the generation
    that wrote it did, never what this one owns, so it is audit evidence on the
    same terms as a refused publication: it goes to the audit log, never to
    the pending event-quarantine queue, and is never released.
    """
    store.append_audit_event(
        {
            **envelope_document(event),
            "correlation": SPAWN_HISTORY_AUDIT,
            "correlation_reason": reason,
        }
    )


def _is_audit_document(document: Mapping[str, object]) -> bool:
    """Whether a durable row is permanent audit evidence rather than work."""
    return document.get("correlation") in AUDIT_CORRELATIONS


def _replayable_quarantine_documents(store: RunStore) -> list[Mapping[str, object]]:
    """Pending documents eligible for replay, excluding permanent audit rows.

    A conflicting audit-marked row is retained in the pending queue by the
    migration, but its top-level audit marker is not preserved by the event
    projection, so it is filtered out here and can never re-enter replay.
    """
    return [document for document in store.quarantined_events() if not _is_audit_document(document)]


def _migrate_audit_marked_quarantine(store: RunStore) -> None:
    """Move legacy audit-marked pending rows into permanent audit storage.

    Older code wrote historical-refusal records into the replayable pending
    quarantine queue. A pending row already marked as audit evidence is copied
    to permanent audit storage and then removed from the queue, so it is never
    replayed or released and never lost. The audit append happens first; a
    failed append leaves the pending row intact.
    """
    for document in store.quarantined_events():
        if not _is_audit_document(document):
            continue
        try:
            store.append_audit_event(document)
        except QuarantineStorageError as error:
            # A conflicting permanent row already exists for this run_seq.
            # Retain the pending row rather than releasing it into a conflict.
            LOGGER.warning("[TL loop] retaining conflicting audit-marked pending row: %s", error)
            continue
        run_seq = document.get("run_seq")
        if isinstance(run_seq, int):
            store.release_quarantined_event(run_seq)


def _recorded_recovery_invocation(current: SliceState) -> str | None:
    """The invocation explicitly recorded by an active recovery, if any."""
    if current.recovery is None:
        return None
    value = current.recovery.evidence.get("invocation_id")
    return value if isinstance(value, str) and value else None


def _publication_generation_rejection(
    current: SliceState,
    envelope: EventEnvelope,
    target_id: str,
    controller_epoch: str | None,
) -> str | None:
    """Return why a publication cannot bind to the current dispatch generation.

    A publication must prove the exact publishing invocation that owns the
    slice, or an invocation explicitly recorded as the current recovery
    succession. The reused agent name, branch name, swarm run_id, or PR title
    are never sufficient. Events from a prior controller epoch are historical:
    they stay queryable for audit and never bind.
    """
    event_invocation = envelope.invocation_id
    expected_invocation = current.dispatch_invocation_id
    if not event_invocation:
        return "publication event carries no invocation identity"
    if not expected_invocation:
        return "slice has no confirmed dispatch invocation to bind against"
    if event_invocation != expected_invocation and event_invocation != (
        _recorded_recovery_invocation(current)
    ):
        return (
            "publication invocation does not match the current dispatch "
            "invocation or a recorded recovery succession"
        )
    event_epoch = envelope.data.get("controller_epoch")
    if (
        controller_epoch is not None
        and isinstance(event_epoch, str)
        and event_epoch
        and event_epoch != controller_epoch
    ):
        return "publication event belongs to a prior controller epoch"
    event_generation = envelope.generation
    if event_generation is not None and event_generation != current.dispatch_generation:
        return "publication event generation does not match the current dispatch"
    if envelope.slice_id is not None and envelope.slice_id != target_id:
        return "publication event slice identity disagrees with the resolved owner"
    return None


def _publication_event_rejection(
    slices: Mapping[str, SliceState],
    event: PRFiled | PRUpdated,
    envelope: EventEnvelope,
    slice_id: str | None,
    controller_epoch: str | None,
) -> tuple[str | None, bool]:
    """Classify a publication event before it may reduce or bind.

    Returns ``(None, False)`` when the event may be reduced and bound. Otherwise
    it returns the refusal reason and whether that refusal is historical or
    generation evidence that must be retained for audit.

    The slice reducer clears publication, handoff, and recovery state, so any
    event that will be refused must be rejected before the reducer runs.
    """
    target_id = _pr_event_target(slices, event, slice_id)
    current = slices.get(target_id) if target_id is not None else None
    if target_id is None or current is None:
        return "no unambiguous owner", False
    if current.dispatch_agent_id is None or envelope.agent_id != current.dispatch_agent_id:
        return "owner agent identity disagrees with the persisted owner", False
    generation_reason = _publication_generation_rejection(
        current, envelope, target_id, controller_epoch
    )
    if generation_reason is not None:
        return generation_reason, True
    head_branch = envelope.data.get("head_branch")
    base_branch = envelope.data.get("base_branch")
    if (
        not isinstance(head_branch, str)
        or not head_branch
        or not isinstance(base_branch, str)
        or not base_branch
    ):
        return "incomplete verified head/base identity", False
    if envelope.head_sha is None or envelope.head_sha != event.head_sha:
        return "event head SHA disagrees with the verified publication", False
    if current.branch is not None and head_branch != current.branch:
        return "head branch disagrees with the persisted owner branch", False
    if current.base_ref is not None and base_branch != current.base_ref:
        return "base branch disagrees with the persisted owner base", False
    existing = current.publication
    if existing is not None and (
        existing.pr_number != event.pr_number or existing.head_sha != event.head_sha
    ):
        return "existing publication head differs", False
    return None, False


def _bind_publication_evidence(
    slices: Mapping[str, SliceState],
    event: PRFiled | PRUpdated,
    envelope: EventEnvelope,
    slice_id: str | None,
    *,
    controller_epoch: str | None = None,
    quarantine: Callable[[str], None] | None = None,
    validation_slices: Mapping[str, SliceState] | None = None,
) -> dict[str, SliceState]:
    """Bind host-verified publication metadata to its persisted owner.

    A publication only binds when the event proves the current dispatch
    invocation or a recorded recovery succession, plus the exact PR, head SHA,
    head branch, base branch, and owner. Historical events from a recreated run
    are refused and retained for audit; they are never backfilled with the
    current run's invocation.

    ``validation_slices`` lets the caller validate against pre-reduction state
    while the binding is applied to the reduced slices, so the reducer's
    mutation can never outlive a refused event.
    """
    validation = validation_slices if validation_slices is not None else slices
    target_id = _pr_event_target(validation, event, slice_id)
    reason, historical = _publication_event_rejection(
        validation, event, envelope, slice_id, controller_epoch
    )
    if reason is not None:
        LOGGER.warning(
            "[TL loop] refusing publication event pr=%s target=%s: %s",
            event.pr_number,
            target_id,
            reason,
        )
        # Only generation/historical rejections are retained for audit; ordinary
        # owner or identity mismatches keep their prior behavior.
        if quarantine is not None and historical:
            quarantine(reason)
        return dict(slices)
    assert target_id is not None
    current = validation[target_id]
    applied = slices.get(target_id, current)
    head_branch = cast(str, envelope.data.get("head_branch"))
    base_branch = cast(str, envelope.data.get("base_branch"))
    existing = current.publication
    invocation_id = envelope.invocation_id
    publication = PublicationBinding(
        pr_number=event.pr_number,
        head_sha=event.head_sha,
        head_branch=head_branch,
        base_branch=base_branch,
        attempt=existing.attempt if existing is not None else current.attempts,
        invocation_id=invocation_id,
    )
    updated = applied
    if applied.publication != publication:
        updated = replace(updated, publication=publication)
    if invocation_id is not None and current.dispatch_agent_id:
        handoff = HandoffEvidence(
            pr_number=event.pr_number,
            head_sha=event.head_sha,
            attempt=publication.attempt,
            invocation_id=invocation_id,
            agent_id=current.dispatch_agent_id,
            observed_at=envelope.observed_at,
        )
        if updated.handoff != handoff:
            updated = slice_transition(updated, SliceStatusChanged(SliceStatus.IN_REVIEW))
            updated = replace(updated, handoff=handoff)
    if updated == applied:
        return dict(slices)
    return {**slices, target_id: updated}


def _complete_legacy_direct_children(phase: RecursiveTLRunning) -> PhaseValue:
    """Translate the legacy aggregate signal into typed direct completions."""
    next_phase: PhaseValue = phase
    for record in phase.parallel_pending:
        if record.kind is ChildKind.WORKER:
            next_phase = scope_transition(
                next_phase,
                ScopeWorkerCompleted(record.child_id, "legacy-all-children-done"),
            )
        elif record.kind is ChildKind.LEAF:
            next_phase = scope_transition(
                next_phase,
                ScopeLeafCompleted(record.child_id, "legacy-all-children-done"),
            )
    return next_phase


def _apply_child_completion(
    slices: Mapping[str, SliceState],
    slice_id: str | None,
    event: EventEnvelope,
    *,
    persist_publication: bool,
) -> dict[str, SliceState]:
    """Persist the child result carried by a completion notification."""
    if slice_id is None or slice_id not in slices:
        return dict(slices)
    current = slices[slice_id]
    if not persist_publication:
        return dict(slices)
    pr_number = event.data.get("pr_number")
    head_sha = event.data.get("head_sha")
    if type(pr_number) is int and pr_number > 0 and isinstance(head_sha, str) and head_sha:
        updated = slice_transition(
            current,
            HeadEvidenceObserved(head_sha, bind_reviewed_head=True),
        )
        updated = slice_transition(updated, SliceStatusChanged(SliceStatus.IN_REVIEW))
        updated = replace(updated, pr_number=pr_number)
        return {**slices, slice_id: updated}
    return dict(slices)


def _duplicate_event(phase: PhaseValue, event: TLEvent, state: RunState) -> bool:
    if isinstance(
        phase,
        (
            RecursiveTLAllMerged,
            RecursiveTLDone,
            RecursiveTLPRFiled,
            RecursiveTLFailed,
            RecursiveTLParked,
        ),
    ):
        if isinstance(event, AllChildrenDone):
            return True
        # A worker emits both ``agent.completed`` and ``agent.notify_parent``
        # for one finished child, so the second terminal row arrives after the
        # barrier already advanced. No child is active in a phase that has left
        # running, so a child-terminal row here repeats a settled decision
        # rather than making a new one.
        return isinstance(event, (ChildCompleted, ChildFailed, PRMerged))
    if isinstance(phase, RecursiveTLRunning):
        active = set(active_child_ids(phase))
        if isinstance(event, ChildSpawned):
            current = state.slices.get(event.handle.slug)
            if current is not None and current.status in DISPATCHING_STATUSES:
                return False
            return event.handle.slug in active
        if isinstance(event, (ChildCompleted, ChildFailed, PRMerged)):
            return event.slug not in active
        if isinstance(event, AllChildrenDone):
            return isinstance(
                phase,
                (
                    RecursiveTLAllMerged,
                    RecursiveTLDone,
                    RecursiveTLPRFiled,
                    RecursiveTLFailed,
                    RecursiveTLParked,
                ),
            )
        return False
    if isinstance(event, ChildSpawned):
        active = phase.children if isinstance(phase, (TLWaiting, TLMerging)) else {}
        return event.handle.slug in active
    if isinstance(event, (ChildCompleted, ChildFailed, PRMerged)):
        active = phase.children if isinstance(phase, (TLWaiting, TLMerging)) else {}
        return event.slug not in active
    if isinstance(event, AllChildrenDone):
        return isinstance(phase, (TLDone, TLFailed))
    return False


def _record_chainlink_binding_gate(
    root_spec: WorkPlan | Mapping[str, object],
    config: TLLoopConfig,
    error: ChainlinkIssueBindingError,
) -> bool:
    raw_run_id = (
        root_spec.get("run_id", config.run_id) if isinstance(root_spec, Mapping) else config.run_id
    )
    if not isinstance(raw_run_id, str) or not raw_run_id:
        raise TLLoopError(f"invalid Chainlink binding cannot be gated: {error}") from error
    store = RunStore(raw_run_id, Path(config.root_dir))
    if store.path.exists():
        state = store.load()
        if state.version != SCHEMA_VERSION or state.repository_identity is None:
            return False
        store.set_gate(CHAINLINK_BINDING_RECONCILIATION_GATE_NAME, GateStatus.PENDING)
        return True
    if config.repository_identity is None:
        return False
    manifest = _manifest_for_plan(WorkPlan(), raw_run_id, config)
    initial: dict[str, object] = {
        "repository_identity": config.repository_identity.to_document(),
        "plan_manifest": manifest.to_document(),
        "gates": [{"name": CHAINLINK_BINDING_RECONCILIATION_GATE_NAME, "status": "pending"}],
    }
    plan_value = root_spec.get("plan", root_spec) if isinstance(root_spec, Mapping) else {}
    has_sub_tls = isinstance(plan_value, Mapping) and bool(plan_value.get("sub_tls"))
    if (
        has_sub_tls
        or config.parent_branch is not None
        or config.worktree is not None
        or config.depth > 0
    ):
        initial.update(
            {
                "owner_branch": config.branch,
                "owner_worktree": _effective_worktree(config, store.root_dir, raw_run_id),
                "parent_branch": config.parent_branch,
                "parent_run_id": config.parent_run_id,
                "parent_agent_id": config.parent_agent_id,
                "depth": config.depth,
            }
        )
    create(raw_run_id, initial, root_dir=store.root_dir)
    return True


def _root_inputs(
    root_spec: WorkPlan | Mapping[str, object], config: TLLoopConfig
) -> tuple[WorkPlan | None, str, EventQueue, EffectClient | ReadOnlyEffectClient]:
    if isinstance(root_spec, WorkPlan):
        raw: Mapping[str, object] = {}
        plan = root_spec
    elif isinstance(root_spec, Mapping):
        raw = root_spec
        plan_value = raw.get("plan")
        if plan_value is None and any(key in raw for key in ("workers", "leaves", "sub_tls")):
            plan_value = {key: raw[key] for key in ("workers", "leaves", "sub_tls") if key in raw}
        if isinstance(plan_value, WorkPlan):
            plan = plan_value
        elif isinstance(plan_value, Mapping):
            plan = WorkPlan.from_mapping(plan_value)
        else:
            plan = None
    else:
        raise TypeError("root_spec must be a WorkPlan or object")
    run_id = raw.get("run_id", config.run_id)
    if not isinstance(run_id, str) or not run_id:
        raise ValueError("root_spec.run_id must be a non-empty string")
    source = config.source or raw.get("source")
    effects = config.effects or raw.get("effects")
    if not hasattr(source, "get") or not hasattr(source, "acknowledge"):
        raise TypeError("tl_run requires an event source in cfg or root_spec")
    if not isinstance(effects, (EffectClient, ReadOnlyEffectClient)):
        raise TypeError("tl_run requires an effect client in cfg or root_spec")
    return plan, run_id, cast(EventQueue, source), effects


def derive_child_branch(parent_branch: str, name: str) -> str:
    _require_text(parent_branch, "parent branch")
    _require_text(name, "child name")
    return f"{parent_branch}.{name}"


def _child_controller_name(task: SubTLTask) -> str:
    """Return the exact route identity used by a live child controller."""
    return task.agent_id or task.name


def derive_child_worktree(parent_worktree: str | Path, name: str) -> Path:
    _require_text(str(parent_worktree), "parent worktree")
    _require_text(name, "child name")
    return Path(parent_worktree) / name


def _sub_tl_worktree(config: TLLoopConfig, root_dir: Path, run_id: str, task: SubTLTask) -> Path:
    """Use the server-owned worktree namespace for live controllers."""
    if task.worktree is not None:
        return Path(task.worktree)
    child_name = _child_controller_name(task)
    if config.project_root is not None and config.depth == 0:
        return Path(config.project_root).resolve() / ".exo" / "worktrees" / child_name
    return derive_child_worktree(_effective_worktree(config, root_dir, run_id), child_name)


def _effective_worktree(config: TLLoopConfig, root_dir: Path, run_id: str) -> str:
    value = config.worktree or (root_dir / run_id)
    return str(Path(value).expanduser().resolve())


def _manifest_plan(plan: WorkPlan) -> Mapping[str, object]:
    """Convert the typed recursive plan into its canonical declaration shape."""
    workers = [
        {
            "name": task.name,
            "task": task.task,
            "agent_type": task.agent_type,
            **(
                {"chainlink_issue_id": task.chainlink_issue_id}
                if task.chainlink_issue_id is not None
                else {}
            ),
            **(
                {"task_timeout_seconds": task.task_timeout_seconds}
                if task.task_timeout_declared
                else {}
            ),
        }
        for task in plan.workers
    ]
    leaves = [
        {
            "name": task.name,
            "task": task.task,
            "agent_type": task.agent_type,
            "boundary": list(task.boundary),
            "context": task.context,
            "read_first": list(task.read_first),
            "steps": list(task.steps),
            "verify": list(task.verify),
            "done_criteria": list(task.done_criteria),
            **(
                {"chainlink_issue_id": task.chainlink_issue_id}
                if task.chainlink_issue_id is not None
                else {}
            ),
            **(
                {"task_timeout_seconds": task.task_timeout_seconds}
                if task.task_timeout_declared
                else {}
            ),
        }
        for task in plan.leaves
    ]
    sub_tls = []
    for task in plan.sub_tls:
        child_plan = (
            task.plan if isinstance(task.plan, WorkPlan) else WorkPlan.from_mapping(task.plan)
        )
        sub_tls.append(
            {
                "name": task.name,
                "order": task.order,
                "task": f"sub-TL {task.name}",
                "worktree": str(task.worktree) if task.worktree is not None else None,
                "integration": _manifest_integration(task.integration),
                "plan": _manifest_plan(child_plan),
                "order_explicit": task.order_explicit,
                **(
                    {"chainlink_issue_id": task.chainlink_issue_id}
                    if task.chainlink_issue_id is not None
                    else {}
                ),
                **(
                    {"task_timeout_seconds": task.task_timeout_seconds}
                    if task.task_timeout_declared
                    else {}
                ),
            }
        )
    return {"workers": workers, "leaves": leaves, "sub_tls": sub_tls}


def _manifest_for_plan(
    plan: WorkPlan,
    run_id: str,
    config: TLLoopConfig,
) -> PlanManifest:
    """Build a candidate declaration only when a run explicitly supplies one."""
    return build_plan_manifest(
        _manifest_plan(plan),
        scope_id=run_id,
        parent_scope_id=config.parent_run_id,
        role="non_root" if config.parent_run_id is not None or config.depth > 0 else "root",
        owned_branch=config.branch,
        parent_integration_target=config.parent_branch,
        manifest_revision=config.plan_revision,
    )


def _candidate_manifest(
    plan: WorkPlan,
    run_id: str,
    config: TLLoopConfig,
) -> PlanManifest:
    """Prefer the parent's immutable child declaration over a rebuilt manifest.

    A live ordered child receives its scope declaration from the parent manifest
    (``TLLoopConfig.declared_manifest``). Persisting that exact declaration keeps
    the child checkpoint digest equal to the parent's ``child_manifests`` entry,
    which is what ordered recovery verifies. Rebuilding it from the child's own
    run id would change the scope id and break that proof.
    """
    if config.declared_manifest is not None:
        return config.declared_manifest
    return _manifest_for_plan(plan, run_id, config)


def _declared_child_manifest(store: RunStore, task: SubTLTask) -> PlanManifest | None:
    """Return the parent's immutable declaration for one ordered child scope."""
    try:
        state = store.load()
    except (OSError, ValueError):
        return None
    manifest = state.plan_manifest
    if manifest is None:
        return None
    node = next(
        (
            candidate
            for candidate in manifest.nodes
            if candidate.name == task.name and candidate.kind == "sub_tl"
        ),
        None,
    )
    if node is None:
        return None
    return manifest.child_manifests.get(node.node_id)


def _manifest_is_legacy(manifest: PlanManifest) -> bool:
    return manifest.role == "root" and manifest.owned_branch == "legacy"


def _work_plan_from_manifest(manifest: PlanManifest) -> WorkPlan:
    """Reconstruct executable declarations from the persisted recursive authority."""
    workers: list[WorkerTask] = []
    leaves: list[LeafTask] = []
    sub_tls: list[SubTLTask] = []
    for node in manifest.nodes:
        declaration = node.declaration
        if node.kind == "worker":
            workers.append(
                WorkerTask(
                    node.name,
                    node.task,
                    node.agent_type,
                    _manifest_timeout(declaration),
                    "task_timeout_seconds" in declaration,
                    node.chainlink_issue_id,
                )
            )
        elif node.kind == "leaf":
            leaves.append(
                LeafTask(
                    name=node.name,
                    task=node.task,
                    agent_type=node.agent_type,
                    boundary=node.boundary,
                    context=_manifest_optional_text(declaration, "context"),
                    read_first=_manifest_texts(declaration, "read_first"),
                    steps=_manifest_texts(declaration, "steps"),
                    verify=_manifest_texts(declaration, "verify"),
                    done_criteria=_manifest_texts(declaration, "done_criteria"),
                    depends_on=node.depends_on,
                    task_timeout_seconds=_manifest_timeout(declaration),
                    task_timeout_declared="task_timeout_seconds" in declaration,
                    chainlink_issue_id=node.chainlink_issue_id,
                )
            )
        elif node.kind == "sub_tl":
            child = manifest.child_manifests.get(node.node_id)
            if child is None or node.order is None:
                raise TLLoopError(
                    f"manifest node {node.node_id!r} has no reconstructable child scope"
                )
            sub_tls.append(
                SubTLTask(
                    name=node.name,
                    plan=_work_plan_from_manifest(child),
                    worktree=node.worktree,
                    order=node.order,
                    integration=_integration_contract(
                        node.integration_contract, legacy_manifest=True
                    ),
                    order_explicit=bool(declaration.get("order_explicit", True)),
                    task_timeout_seconds=_manifest_timeout(declaration),
                    task_timeout_declared="task_timeout_seconds" in declaration,
                    chainlink_issue_id=node.chainlink_issue_id,
                )
            )
        else:
            raise TLLoopError(
                f"manifest node {node.node_id!r} has legacy kind {node.kind!r} and cannot be resumed"
            )
    return normalize_work_plan(WorkPlan(tuple(workers), tuple(leaves), tuple(sub_tls)))


def _manifest_timeout(declaration: Mapping[str, object]) -> float | None:
    value = declaration.get("task_timeout_seconds")
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TLLoopError("manifest task_timeout_seconds must be numeric or null")
    return float(value)


def _manifest_optional_text(declaration: Mapping[str, object], name: str) -> str | None:
    value = declaration.get(name)
    if value is None:
        return None
    if not isinstance(value, str):
        raise TLLoopError(f"manifest declaration {name} must be a string or null")
    return value


def _manifest_texts(declaration: Mapping[str, object], name: str) -> tuple[str, ...]:
    value = declaration.get(name, ())
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes)):
        raise TLLoopError(f"manifest declaration {name} must be an array")
    if any(not isinstance(item, str) for item in value):
        raise TLLoopError(f"manifest declaration {name} must contain strings")
    return tuple(value)


def _manifest_integration(contract: IntegrationContract) -> Mapping[str, object]:
    return {
        "aggregate_pr_required": contract.aggregate_pr_required,
        "base_revalidation_required": contract.base_revalidation_required,
        "leaf_review_owner": contract.leaf_review_owner.value,
        "aggregate_review_owner": contract.aggregate_review_owner.value,
        "aggregate_repair_owner": contract.aggregate_repair_owner.value,
        "merge_strategy": contract.merge_strategy,
    }


def _rebind_dependency_edges(
    slices: Mapping[str, Mapping[str, object]],
    previous: Mapping[str, SliceState],
    manifest: PlanManifest,
) -> dict[str, Mapping[str, object]]:
    """Align never-dispatched slice edges with a revised manifest.

    A revision may add nodes and may rewire a leaf that has not dispatched,
    because nothing has acted on its old edge yet. A slice that *has* left
    ``PENDING``/``READY`` is left exactly as it was: the manifest revision check
    already refuses to change a protected node's identity, and overwriting the
    record here would silently rewrite an edge the controller has acted on.

    A record with no node in this scope is left alone as well. A legacy
    checkpoint carries slices the manifest does not declare, and those records
    already hold whatever ordering their own writer gave them.

    The two records must agree after the write, because a restart reads the
    manifest while dispatch reads the slice record.
    """
    by_name = {node.name: node.depends_on for node in manifest.nodes}
    rebound: dict[str, Mapping[str, object]] = {}
    for slice_id, value in slices.items():
        if slice_id not in by_name:
            rebound[slice_id] = value
            continue
        current = previous.get(slice_id)
        dispatched = current is not None and current.status not in _UNDISPATCHED_STATUSES
        declared = list(by_name[slice_id])
        if dispatched or _recorded_dependencies(value) == declared:
            rebound[slice_id] = value
            continue
        rebound[slice_id] = {**value, "depends_on": declared}
    return rebound


def _bind_initial_slices(
    slices: Mapping[str, Mapping[str, object]],
    manifest: PlanManifest,
) -> Mapping[str, Mapping[str, object]]:
    """Attach exact manifest identity to every direct initial slice."""
    by_name = {node.name: node for node in manifest.nodes}
    bound: dict[str, Mapping[str, object]] = {}
    for slice_id, value in slices.items():
        node = by_name.get(slice_id)
        if node is None:
            raise TLLoopError(f"slice {slice_id!r} is not declared by the plan manifest")
        record = copy.deepcopy(dict(value))
        record["manifest_node_id"] = node.node_id
        record["manifest_revision"] = manifest.manifest_revision
        bound[slice_id] = record
    return bound


def _initial_slices(
    plan: WorkPlan,
    config: TLLoopConfig | None = None,
    root_dir: str | Path | None = None,
    run_id: str | None = None,
) -> dict[str, dict[str, object]]:
    selected = config or TLLoopConfig()
    state_root = Path(root_dir or selected.root_dir)
    nested = selected.parent_branch is not None
    current_run = run_id or selected.run_id
    owner_worktree = _effective_worktree(selected, state_root, current_run)
    # A child of *this* run is dispatched off ``selected.branch`` and files its
    # pull request against that same branch: the sub-TL spawn boundary records
    # ``base_ref=config.branch`` for the slice it confirms, and a sub-TL slice is
    # declared with ``selected.branch`` below. ``selected.parent_branch`` is one
    # level further up -- it is the branch *this* run files against -- so naming
    # it here made every nested worker's and leaf's publication fail the binder's
    # base-branch identity check. A leaf dispatched by a child sub-TL then bound
    # no publication, recorded no handoff, and could never be reconciled into a
    # park when its PR was closed.
    child_base_ref = selected.branch if nested else None
    result: dict[str, dict[str, object]] = {}
    for worker in plan.workers:
        result[worker.name] = _initial_slice_record(
            worker.name,
            (f"tl-loop/{worker.name}",),
            ("controller",),
            worker.agent_type,
            derive_child_branch(selected.branch, worker.name) if nested else None,
            str(derive_child_worktree(owner_worktree, worker.name)) if nested else None,
            child_base_ref,
            config=selected,
            task_timeout_seconds=worker.task_timeout_seconds,
            task_timeout_declared=worker.task_timeout_declared,
            chainlink_issue_id=worker.chainlink_issue_id,
        )
    for leaf in plan.leaves:
        paths = leaf.boundary or (f"tl-loop/{leaf.name}",)
        test_plan = leaf.verify or leaf.steps or ("controller",)
        review_contract = _materialize_leaf_review_contract(leaf, paths, test_plan)
        result[leaf.name] = _initial_slice_record(
            leaf.name,
            paths,
            test_plan,
            leaf.agent_type,
            derive_child_branch(selected.branch, leaf.name) if nested else None,
            str(derive_child_worktree(owner_worktree, leaf.name)) if nested else None,
            child_base_ref,
            config=selected,
            task_timeout_seconds=leaf.task_timeout_seconds,
            task_timeout_declared=leaf.task_timeout_declared,
            review_contract=review_contract.as_mapping(),
            depends_on=leaf.depends_on,
            chainlink_issue_id=leaf.chainlink_issue_id,
        )
    for task in plan.sub_tls:
        # A sub-TL slice records no harness request: the child is a controller
        # process, and the harnesses it runs are chosen inside its own nested
        # plan's workers and leaves.
        result[task.name] = _initial_slice_record(
            task.name,
            (f"tl-loop/{task.name}",),
            ("controller",),
            None,
            derive_child_branch(selected.branch, _child_controller_name(task)),
            str(_sub_tl_worktree(selected, state_root, current_run, task)),
            selected.branch,
            config=selected,
            task_timeout_seconds=task.task_timeout_seconds,
            task_timeout_declared=task.task_timeout_declared,
            chainlink_issue_id=task.chainlink_issue_id,
        )
    return result


def _all_expected_terminal(state: RunState, expected: set[str]) -> bool:
    terminal = {
        SliceStatus.MERGED,
        SliceStatus.FAILED,
        SliceStatus.PARKED,
        SliceStatus.BLOCKED,
    }
    return bool(expected) and all(
        state.slices.get(slice_id) is not None and state.slices[slice_id].status in terminal
        for slice_id in expected
    )


def _note_heartbeat_progress(store: RunStore, state: RunState) -> RunState:
    return store.set_goals(replace(state.goals, last_progress_at=time.time()))


def _note_authoritative_event(
    store: RunStore,
    state: RunState,
    event_seq: int,
    *,
    update_progress: bool = True,
) -> RunState:
    return store.set_goals(
        replace(
            state.goals,
            last_authoritative_event_seq=event_seq,
            last_progress_at=time.time() if update_progress else state.goals.last_progress_at,
        )
    )


def _encode_goals(goals: GoalState) -> dict[str, object]:
    encoded = {
        "objective": goals.objective,
        "deadline": goals.deadline,
        "completion_predicate": goals.completion_predicate,
        "last_heartbeat_at": goals.last_heartbeat_at,
        "last_progress_at": goals.last_progress_at,
    }
    if goals.controller_started_at is not None:
        encoded["controller_started_at"] = goals.controller_started_at
    if goals.last_authoritative_event_seq is not None:
        encoded["last_authoritative_event_seq"] = goals.last_authoritative_event_seq
    return encoded


def _materialize_leaf_review_contract(
    leaf: LeafTask,
    paths: Sequence[str],
    test_plan: Sequence[str],
) -> ReviewContract:
    values = (
        ("Run-state test plan", test_plan),
        ("Plan verification", leaf.verify),
        ("Owned paths", paths),
        ("Plan boundary", leaf.boundary),
        ("DONE CRITERIA", leaf.done_criteria),
    )
    criteria = [f"{label}: {value}" for label, items in values for value in items]
    return ReviewContract.from_criteria(criteria)


def _initial_slice_record(
    name: str,
    paths: Sequence[str],
    test_plan: Sequence[str],
    agent_type: str | None,
    branch: str | None = None,
    worktree: str | None = None,
    base_ref: str | None = None,
    *,
    config: TLLoopConfig | None = None,
    task_timeout_seconds: float | None = None,
    task_timeout_declared: bool = False,
    review_contract: Mapping[str, object] | None = None,
    depends_on: Sequence[str] = (),
    chainlink_issue_id: int | None = None,
) -> dict[str, object]:
    """Build one pending slice record, keeping the plan request separate.

    ``agent_type`` here is the request ``plan.json`` declared, never an executed
    route. It is persisted as ``requested_harness`` so ``agent_type`` and
    ``resolved_harness`` can mean "the route this run actually dispatched" and
    stay free for the selector to fill in.
    """
    resolved_timeout, timeout_source = _resolve_task_timeout(
        config or TLLoopConfig(), task_timeout_seconds, task_timeout_declared
    )
    record: dict[str, object] = {
        "id": name,
        "status": SliceStatus.PENDING.value,
        "paths": list(paths),
        "depends_on": list(depends_on),
        "base_ref": base_ref,
        "test_plan": list(test_plan),
        "agent_type": None,
        "requested_harness": agent_type,
        "resolved_harness": None,
        "model": None,
        "branch": branch,
        "worktree": worktree,
        "pr_number": None,
        "review_findings": {},
        "ci_state": {},
        "reviewer_attempt": {},
        "repair_attempts": 0,
        "reviewed_head": None,
        "attempts": 0,
        "verdict": None,
        "task_timeout_seconds": resolved_timeout,
        "task_timeout_source": timeout_source,
    }
    if review_contract is not None:
        record["review_contract"] = copy.deepcopy(dict(review_contract))
    if chainlink_issue_id is not None:
        record["chainlink_issue_id"] = chainlink_issue_id
    return record


def _resolve_task_timeout(
    config: TLLoopConfig,
    task_timeout_seconds: float | None,
    task_timeout_declared: bool,
) -> tuple[float | None, str]:
    if task_timeout_declared:
        _validate_task_timeout(task_timeout_seconds, "task_timeout_seconds")
        return task_timeout_seconds, "slice"
    policy = config.policy
    role_policy = policy.roles.get(config.role) if policy is not None else None
    if role_policy is not None and role_policy.task_timeout_configured:
        return role_policy.task_timeout_seconds, "role"
    return config.task_timeout_seconds, config.task_timeout_source


def _validate_task_timeout(value: float | None, name: str) -> None:
    if value is None:
        return
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{name} must be null or a non-negative number")
    if value < 0 or not math.isfinite(float(value)):
        raise ValueError(f"{name} must be null or a non-negative number")


def _budget_root(
    budgets: BudgetLedger | Mapping[str, object],
) -> dict[str, object]:
    if isinstance(budgets, BudgetLedger):
        ledger: dict[str, object] = {
            "tokens": budgets.tokens,
            "wall_seconds": budgets.wall_seconds,
        }
        for key, counter in (
            ("role_spent", budgets.role_spent),
            ("harness_spent", budgets.harness_spent),
            ("role_reserved", budgets.role_reserved),
            ("harness_reserved", budgets.harness_reserved),
        ):
            if counter:
                ledger[key] = dict(counter)
        return {"ledger": ledger}
    if not isinstance(budgets, Mapping):
        raise TypeError("budgets must be a BudgetLedger or object")
    raw = copy.deepcopy(dict(budgets))
    if "ledger" in raw:
        return cast(dict[str, object], raw)
    return {"ledger": raw}


def _validate_mode(config: TLLoopConfig, effects: EffectClient | ReadOnlyEffectClient) -> None:
    if config.active and not isinstance(effects, EffectClient):
        raise TypeError("active TL loops require EffectClient")
    if not config.active and not isinstance(effects, ReadOnlyEffectClient):
        raise TypeError("shadow TL loops require ReadOnlyEffectClient")


def _workers(value: object) -> tuple[WorkerTask, ...]:
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes)):
        raise TypeError("work plan workers must be an array")
    return tuple(_worker(item) for item in value)


def _leaves(value: object, *, path: str = "plan.leaves") -> tuple[LeafTask, ...]:
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes)):
        raise TypeError("work plan leaves must be an array")
    return tuple(_leaf(item, path=f"{path}[{index}]") for index, item in enumerate(value))


def _sub_tls(value: object, *, path: str = "plan.sub_tls") -> tuple[SubTLTask, ...]:
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes)):
        raise TypeError("work plan sub_tls must be an array")
    return tuple(_sub_tl(item, path=f"{path}[{index}]") for index, item in enumerate(value))


def _sub_tl(value: object, *, path: str = "plan.sub_tls[0]") -> SubTLTask:
    if isinstance(value, SubTLTask):
        return value
    if not isinstance(value, Mapping):
        raise TypeError("sub-TL task must be an object")
    # ``agent_type`` is absent on purpose. A sub-TL runs as a nested controller
    # process rather than a model session, so a harness request on one was never
    # a truthful field; rejecting it here is what makes an older plan fail
    # closed instead of quietly running with a request that was never honored.
    allowed = {
        "name",
        "plan",
        "workers",
        "leaves",
        "sub_tls",
        "source",
        "effects",
        "worktree",
        "agent_id",
        "order",
        "integration",
        "task_timeout_seconds",
        "chainlink_issue_id",
    }
    unknown = sorted(set(value) - allowed)
    if unknown:
        raise ValueError(f"sub-TL contains unknown keys: {', '.join(unknown)}")
    plan_value = value.get("plan")
    if plan_value is None:
        plan_value = {key: value[key] for key in ("workers", "leaves", "sub_tls") if key in value}
    plan = (
        plan_value
        if isinstance(plan_value, WorkPlan)
        else WorkPlan.from_mapping(cast(Mapping[str, object], plan_value), path=f"{path}.plan")
    )
    integration = _integration_contract(value.get("integration"))
    return SubTLTask(
        _required_text(value, "name", "sub-TL"),
        plan,
        source=cast(EventQueue | None, value.get("source")),
        effects=cast(EffectClient | ReadOnlyEffectClient | None, value.get("effects")),
        worktree=cast(str | Path | None, value.get("worktree")),
        agent_id=_optional_string(value, "agent_id", "sub-TL"),
        order=_positive_order(value.get("order", 1), f"{path}.order"),
        integration=integration,
        order_explicit="order" in value,
        task_timeout_seconds=_optional_timeout(
            value.get("task_timeout_seconds"), f"{path}.task_timeout_seconds"
        ),
        task_timeout_declared="task_timeout_seconds" in value,
        chainlink_issue_id=_optional_chainlink_issue_id(
            value.get("chainlink_issue_id"), f"{path}.chainlink_issue_id"
        ),
    )


def _positive_order(value: object, name: str) -> int:
    if type(value) is not int or value <= 0:
        raise ValueError(f"{name} must be a positive integer")
    return value


def _optional_chainlink_issue_id(value: object, path: str) -> int | None:
    if value is None:
        return None
    if type(value) is not int or value <= 0:
        raise ChainlinkIssueBindingError(f"{path} must be a positive integer or null")
    return value


def _validate_chainlink_issue_id(value: object, path: str) -> None:
    _optional_chainlink_issue_id(value, path)


def _validate_chainlink_issue_bindings(plan: WorkPlan) -> None:
    bindings: dict[int, str] = {}

    def add(issue_id: int | None, path: str) -> None:
        if issue_id is None:
            return
        prior = bindings.get(issue_id)
        if prior is not None:
            raise ChainlinkIssueBindingError(
                f"chainlink_issue_id {issue_id} is bound to both {prior} and {path}; "
                "bind each issue to one slice"
            )
        bindings[issue_id] = path

    def visit(current: WorkPlan, path: str) -> None:
        for task in current.workers:
            add(task.chainlink_issue_id, f"{path}.workers[{task.name!r}]")
        for task in current.leaves:
            add(task.chainlink_issue_id, f"{path}.leaves[{task.name!r}]")
        for task in current.sub_tls:
            child_path = f"{path}.sub_tls[{task.name!r}]"
            add(task.chainlink_issue_id, child_path)
            nested = (
                task.plan
                if isinstance(task.plan, WorkPlan)
                else WorkPlan.from_mapping(task.plan, path=f"{child_path}.plan")
            )
            visit(nested, f"{child_path}.plan")

    visit(plan, "plan")


def _integration_contract(value: object, *, legacy_manifest: bool = False) -> IntegrationContract:
    if value is None:
        return IntegrationContract()
    if not isinstance(value, Mapping):
        raise TypeError("sub-TL integration must be an object")
    allowed = {
        "aggregate_pr_required",
        "aggregate_approval_mode",
        "base_revalidation_required",
        "leaf_review_owner",
        "aggregate_review_owner",
        "aggregate_repair_owner",
        "merge_strategy",
    }
    unknown = sorted(set(value) - allowed)
    if unknown:
        raise ValueError(f"sub-TL integration contains unknown keys: {', '.join(unknown)}")
    approval_mode = parse_aggregate_approval_mode(value.get("aggregate_approval_mode"))

    def owner(name: str) -> ReviewOwner:
        default = (
            ReviewOwner.LEAF.value
            if name == "leaf_review_owner"
            else ReviewOwner.NONE.value
            if name == "aggregate_review_owner"
            else ReviewOwner.AGGREGATE.value
        )
        raw = value.get(name, default)
        if name == "aggregate_review_owner" and raw == ReviewOwner.AGGREGATE.value:
            if not legacy_manifest:
                raise ValueError(
                    "aggregate_review_owner='aggregate' is unsupported; "
                    "root aggregate review phases are not available"
                )
            raw = ReviewOwner.NONE.value
        try:
            return ReviewOwner(raw)
        except (TypeError, ValueError) as error:
            raise ValueError(f"{name} must be 'leaf', 'aggregate', or 'none'") from error

    return IntegrationContract(
        aggregate_pr_required=value.get("aggregate_pr_required", True),
        base_revalidation_required=value.get("base_revalidation_required", True),
        leaf_review_owner=owner("leaf_review_owner"),
        aggregate_review_owner=owner("aggregate_review_owner"),
        aggregate_repair_owner=owner("aggregate_repair_owner"),
        aggregate_approval_mode=approval_mode,
        merge_strategy=value.get("merge_strategy", "merge"),
    )


def normalize_work_plan(plan: WorkPlan, *, path: str = "plan") -> WorkPlan:
    """Normalize explicit sibling orders and validate stage ownership.

    A plan with no explicit orders is intentionally returned in source order.
    Once ordered mode is selected, all direct sub-TLs must declare an order
    and values must be contiguous from one. Direct workers and leaves remain
    an unordered parallel block that runs before the ordered sub-TL stages.
    The nested plans have already gone through this function with their own
    path, so recursive order scopes remain independent.
    """
    tasks = plan.sub_tls
    if not tasks or not any(task.order_explicit for task in tasks):
        return plan
    if not all(task.order_explicit for task in tasks):
        missing = next(index for index, task in enumerate(tasks) if not task.order_explicit)
        raise ValueError(f"{path}.sub_tls[{missing}].order is required when ordered mode is used")
    orders = sorted({task.order for task in tasks})
    expected = list(range(1, len(orders) + 1))
    if orders != expected:
        raise ValueError(f"{path}.sub_tls order values must be contiguous from 1; got {orders}")
    for order in orders:
        peers = [task for task in tasks if task.order == order]
        _validate_concurrent_ownership(peers, path, order)
    return WorkPlan(
        workers=plan.workers,
        leaves=plan.leaves,
        sub_tls=tuple(sorted(tasks, key=lambda task: (task.order, task.name))),
    )


def _validate_concurrent_ownership(tasks: Sequence[SubTLTask], path: str, order: int) -> None:
    owned: list[tuple[str, str]] = []
    for task in tasks:
        for owned_path in _sub_tl_owned_paths(task):
            for other_name, other_path in owned:
                if _patterns_overlap(owned_path, other_path):
                    raise ValueError(
                        f"{path} order {order} ownership overlaps between "
                        f"{task.name!r} path {owned_path!r} and "
                        f"{other_name!r} path {other_path!r}"
                    )
            owned.append((task.name, owned_path))


def _sub_tl_owned_paths(task: SubTLTask) -> tuple[str, ...]:
    paths: list[str] = []
    for leaf in task.plan.leaves if isinstance(task.plan, WorkPlan) else ():
        paths.extend(leaf.boundary or (f"tl-loop/{task.name}/{leaf.name}",))
    for child in task.plan.sub_tls if isinstance(task.plan, WorkPlan) else ():
        paths.extend(_sub_tl_owned_paths(child))
    return tuple(paths or (f"tl-loop/{task.name}",))


def _patterns_overlap(left: str, right: str) -> bool:
    return left == right or fnmatchcase(left, right) or fnmatchcase(right, left)


def _worker(value: object) -> WorkerTask:
    if isinstance(value, WorkerTask):
        return value
    if not isinstance(value, Mapping):
        raise TypeError("worker task must be an object")
    _reject_unknown_task_keys(
        value,
        {"name", "task", "agent_type", "task_timeout_seconds", "chainlink_issue_id"},
        "worker",
    )
    return WorkerTask(
        name=_required_text(value, "name", "worker"),
        task=_required_text(value, "task", "worker"),
        agent_type=_optional_string(value, "agent_type", "worker"),
        task_timeout_seconds=_optional_timeout(
            value.get("task_timeout_seconds"), "worker.task_timeout_seconds"
        ),
        task_timeout_declared="task_timeout_seconds" in value,
        chainlink_issue_id=_optional_chainlink_issue_id(
            value.get("chainlink_issue_id"), "worker.chainlink_issue_id"
        ),
    )


def _leaf(value: object, *, path: str = "plan.leaves[0]") -> LeafTask:
    if isinstance(value, LeafTask):
        return value
    if not isinstance(value, Mapping):
        raise TypeError("leaf task must be an object")
    if "chainlink_issue_id" not in value:
        raise ChainlinkIssueBindingError(
            f"{path}.chainlink_issue_id is required; use null for an unlinked leaf"
        )
    _reject_unknown_task_keys(
        value,
        {
            "name",
            "task",
            "agent_type",
            "boundary",
            "context",
            "read_first",
            "steps",
            "verify",
            "done_criteria",
            "depends_on",
            "task_timeout_seconds",
            "chainlink_issue_id",
        },
        "leaf",
    )
    return LeafTask(
        name=_required_text(value, "name", "leaf"),
        task=_required_text(value, "task", "leaf"),
        agent_type=_optional_string(value, "agent_type", "leaf"),
        boundary=_string_tuple(value.get("boundary", ()), "leaf boundary"),
        context=_optional_string(value, "context", "leaf"),
        read_first=_string_tuple(value.get("read_first", ()), "leaf read_first"),
        steps=_string_tuple(value.get("steps", ()), "leaf steps"),
        verify=_string_tuple(value.get("verify", ()), "leaf verify"),
        done_criteria=_string_tuple(value.get("done_criteria", ()), "leaf done_criteria"),
        depends_on=_string_tuple(value.get("depends_on", ()), "leaf depends_on"),
        task_timeout_seconds=_optional_timeout(
            value.get("task_timeout_seconds"), "leaf.task_timeout_seconds"
        ),
        task_timeout_declared="task_timeout_seconds" in value,
        chainlink_issue_id=_optional_chainlink_issue_id(
            value.get("chainlink_issue_id"), "leaf.chainlink_issue_id"
        ),
    )


def _reject_unknown_task_keys(value: Mapping[str, object], allowed: set[str], kind: str) -> None:
    unknown = sorted(set(value) - allowed)
    if unknown:
        raise ValueError(f"{kind} contains unknown keys: {', '.join(unknown)}")


def _required_text(value: Mapping[str, object], key: str, kind: str) -> str:
    candidate = value.get(key)
    if not isinstance(candidate, str) or not candidate:
        raise ValueError(f"{kind}.{key} must be a non-empty string")
    return candidate


def _optional_string(value: Mapping[str, object], key: str, kind: str) -> str | None:
    candidate = value.get(key)
    if candidate is None:
        return None
    if not isinstance(candidate, str) or not candidate:
        raise ValueError(f"{kind}.{key} must be null or a non-empty string")
    return candidate


def _optional_timeout(value: object, label: str) -> float | None:
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{label} must be null or a non-negative number")
    parsed = float(value)
    if parsed < 0 or not math.isfinite(parsed):
        raise ValueError(f"{label} must be null or a non-negative number")
    return None if parsed == 0 else parsed


def _string_tuple(value: object, label: str) -> tuple[str, ...]:
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes)):
        raise TypeError(f"{label} must be an array")
    if any(not isinstance(item, str) or not item for item in value):
        raise TypeError(f"{label} entries must be non-empty strings")
    return tuple(value)


def _require_text(value: str, label: str) -> None:
    if not isinstance(value, str) or not value:
        raise ValueError(f"{label} must be a non-empty string")


def _optional_text(value: str | None, label: str) -> None:
    if value is not None:
        _require_text(value, label)


def _text_tuple(value: Sequence[str], label: str) -> None:
    _string_tuple(value, label)


def _optional_argument(arguments: dict[str, object], key: str, value: object) -> None:
    if value is not None:
        arguments[key] = value


__all__ = [
    "DepthLimitExceeded",
    "EffectFailed",
    "EffectIntent",
    "EventQueue",
    "LeafTask",
    "LoopCancelled",
    "LoopLimitExceeded",
    "SubTLTask",
    "TLLoopConfig",
    "TLLoopError",
    "TLRunResult",
    "WorkPlan",
    "WorkerTask",
    "derive_child_branch",
    "derive_child_worktree",
    "run_tl_loop",
    "tl_run",
]
